  ui_story_1_1_A16_dialog_content = "…",
  ui_story_1_1_B1_dialog_content = "PlayerName、これも一つの試練です。\n孤独を受け入れ、強くなりたいという意志を研ぎ澄ますのです。",
  ui_story_1_1_B2_dialog_content = "お説教はもういいよ。耳にタコができそうだ。",
  ui_story_1_1_B3_dialog_content = "では、大陸の歴史をもう一度再生しましょうか？",
  ui_story_1_1_B4_dialog_content = "もう192回も聞いたよ。",
  ui_story_1_1_B5_dialog_content = "戦場指揮術はいかがですか？",
  ui_story_1_1_B6_dialog_content = "もう246回も聞いたよ。\nそれに、ずっとここに籠りきりじゃ、実践しようもないよね。",
  ui_story_1_1_B7_dialog_content = "すみません、PlayerName。あなたの精神状態を安定させようと思ったのです。",
  ui_story_1_1_B8_dialog_content = "…",
  ui_story_1_1_B9_dialog_content = "…また、<color=#FFB400>あの夢</color>を見たのですか？",
  ui_story_1_1_B10_dialog_content = "うん。",
  ui_story_1_1_B11_dialog_content = "夢とは、未知なるものへの渇望が具象化された幻影です。",
  ui_story_1_1_B12_dialog_content = "あなたの能力はその精神的現象を大幅に強化します。それが…",
  ui_story_1_1_B13_dialog_content = "17年間ずっと一緒にいるけど、\nその話し方にはいまだに慣れないよ、ソラヴァン。",
  ui_story_1_1_B14_dialog_content = "私が言いたいことは、それは<color=#FFB400>幻影</color>で、現実ではないということです。",
  ui_story_1_1_B15_dialog_content = "そうはいうけど、幻影にしてはすごくリアルなんだ。\nまるで、<color=#FFB400>天空ノ谷</color>の襲撃に自分が居合わせたみたいに…",
  ui_story_1_1_B16_dialog_content = "殺されていく人たちの苦しみまで感じるんだ。",
  ui_story_1_1_B17_dialog_content = "記憶は感情へと変わるものです。その過程で事実も歪みます。",
  ui_story_1_1_B18_dialog_content = "実際には、あなたは今も生きている。\n私はそのために生命維持装置を作動させているのです。",
  ui_story_1_1_X3_dialog_content = "まただ…",
  ui_story_1_1_19_dialog_content = "しばらくお待ちください。新たな信号を捕捉…",
  ui_story_1_1_20_dialog_content = "新たな信号？",
  ui_story_1_1_21_dialog_content = "信号を分析中…間違いありません、確かに<color=#FFB400>光霊</color>です。",
  ui_story_1_1_22_dialog_content = "光霊…？",
  ui_story_1_1_23_dialog_content = "残念ですが、あなたの一族ではありません。",
  ui_story_1_1_B20_dialog_content = "ガッカリするのには慣れてるよ…でも、光霊がこんな所で何をしてるんだろう？",
  ui_story_1_1_B21_dialog_content = "ちょうど、この真上で<color=#FFB400>暗鬼</color>と交戦しています。\n苦戦しているようですね。",
  ui_story_1_1_A17_dialog_content = "17年間ここに近付いた光霊はいませんでした。どうして今日に限って……",
  ui_story_1_1_24_dialog_content = "とにかく、外の画面をあなたに同期します――",
  ui_story_1_1_25_dialog_content = "<color=#FFB400>バイス</color>、あなたが言ってたものって本当にここにあるの？",
  ui_story_1_1_26_dialog_content = "それなら、どうしてこんなに暗鬼がいるの？\n包囲されちゃってるじゃない…",
  ui_story_1_1_27_dialog_content = "間違いないわ。探査結果によれば、この近くに<color=#FFB400>巨像</color>があるはずよ！",
  ui_story_1_1_A18_dialog_content = "他の場所はみんな空振りだったけど、\n今回こそは絶対に何か収穫がある予感がするの！",
  ui_story_1_1_A19_dialog_content = "収穫より、生きて帰れるかどうかの方が気になるわ…\n私たちは共同探索隊であって、決死隊じゃないのよ…",
  ui_story_1_1_28_dialog_content = "暗鬼の出現ぐらい想定の範囲内じゃない。",
  ui_story_1_1_29_dialog_content = "それにしたって、多すぎるよ…",
  ui_story_1_1_30_dialog_content = "私たちはただの通りすがりですって言ったら、見逃してくれないかな…？",
  ui_story_1_1_31_dialog_content = "無理でしょうね。暗鬼と私たち光霊の<color=#FFB400>戦争</color>は千年以上も続いてるのよ。",
  ui_story_1_1_A20_dialog_content = "それに、そもそも言葉が通じると思う？",
  ui_story_1_1_32_dialog_content = "探索なんかに来るんじゃなかった…ラクできると思ってたのに…",
  ui_story_1_1_33_dialog_content = "真面目にやりなさいよ…暗鬼がどんどん増えてるわ…なんとか突破しないと。",
  ui_story_1_1_34_dialog_content = "行くわ！｢速射感知｣！！",
  ui_story_1_1_35_dialog_content = "行くわよ！バイスに合わせて…",
  ui_story_1_1_36_dialog_content = "ポッポ…あれ、地面に裂け目が？最近、寝不足だから幻覚が見えてる…？",
  ui_story_1_1_37_dialog_content = "<size=45>まずいわ、足元に気をつけて！早く何かにつかまって！</size>",
  ui_story_1_1_38_dialog_content = "ごめんなさいごめんなさい！みんな、足元に――",
  ui_story_1_1_40_dialog_content = "アイタタタタッ…",
  ui_story_1_1_41_dialog_content = "みんな大丈夫？エンジェル、ドーヴ？",
  ui_story_1_1_42_dialog_content = "ちょっと…聞こえてる――？",
  ui_story_1_1_43_dialog_content = "ここはどこなの？どうして地下に建築物が？",
  ui_story_1_1_A21_dialog_content = "この質感…それに状態の良さ。み、見間違いじゃないよね？",
  ui_story_1_1_44_dialog_content = "まさか私、本当に巨像を見つけちゃったの？",
  ui_story_1_1_45_dialog_content = "エンジェル、ドーヴ！どこ！？",
  ui_story_1_1_46_dialog_content = "<anim type=Shake>グォォ――！</anim>",
  ui_story_1_1_47_dialog_content = "う、嘘でしょ！暗鬼も追ってきたの！？",
  ui_story_1_1_48_dialog_content = "光霊が発動した攻撃で背面に亀裂が発生。ダメージ集計中…",
  ui_story_1_1_49_dialog_content = "そ…その亀裂って、外に出られる！？",
  ui_story_1_1_50_dialog_content = "計測完了。確かに、そこから地上に脱出できそうです。",
  ui_story_1_1_51_dialog_content = "出られる…の？僕は…",
  ui_story_1_1_A23_dialog_content = "ですが、お勧めはしません。外には依然として多くの暗鬼が徘徊しています。",
  ui_story_1_1_A24_dialog_content = "…災厄はまだ終結していない様子ですね。世界は相変わらずのようです…",
  ui_story_1_1_52_dialog_content = "今すぐにでも飛び出したいような…でも…そうでもないような…",
  ui_story_1_1_B22_dialog_content = "暗鬼の存在は、あなたにとって確実に危険でしょう。",
  ui_story_1_1_B23_dialog_content = "ううん。暗鬼のせいだけじゃないよ…",
  ui_story_1_1_B24_dialog_content = "なんというか、複雑で、言葉では言い表せないような気持ちっていうのかな。",
  ui_story_1_1_A25_dialog_content = "残念ながら理解不能です。\nもしかして私との別れが名残惜しいのですか？",
  ui_story_1_1_53_dialog_content = "もし最後のエネルギーまで使い果たせば、\n私も他の巨像と同じように解放されるでしょう。何も問題はありません。",
  ui_story_1_1_54_dialog_content = "ですが、私は自分の使命を全うしなければなりません。\nあなたにも、あなた自身の使命があるはずです。",
  ui_story_1_1_55_dialog_content = "しかし、ひとまずこの話はあとにしましょう。",
  ui_story_1_1_56_dialog_content = "先ほどの光霊が、危機的な状況にあるようです。ほら――",
  ui_story_1_1_58_dialog_content = "戦え…ない。力を使い果たしちゃったのに…",
  ui_story_1_1_59_dialog_content = "こんな時に暗鬼に遭遇するなんて！",
  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>グオォォォン！</size></anim>",
  ui_story_1_1_61_dialog_content = "光力…光力はどこ…？",
  ui_story_1_1_62_dialog_content = "9時の方向に2歩移動して。",
  ui_story_1_1_63_dialog_content = "<size=45>誰！？</size>",
  ui_story_1_1_64_dialog_content = "え？げ…幻聴？それとも暗鬼が喋ってる？",
  ui_story_1_1_65_dialog_content = "幻聴じゃないよ。僕が君に話しかけてるんだ。",
  ui_story_1_1_66_dialog_content = "あ！本当に人がいるの！？\nこの感覚って、何かの通信？いえ、違うわね…",
  ui_story_1_1_67_dialog_content = "これは、<color=#FFB400>精神感知</color>っていうんだ。",
  ui_story_1_1_68_dialog_content = "精神…感知？",
  ui_story_1_1_B25_dialog_content = "…本物の相手と話すのは初めてだから、やっぱり慣れないや…",
  ui_story_1_1_A26_dialog_content = "頑張れ！大丈夫、できるさ。初めてとはいえ、何年も練習してきたじゃないか…",
  ui_story_1_1_A27_dialog_content = "どうして急に私を励ますの！？あなたは一体誰？",
  ui_story_1_1_A28_dialog_content = "今のは自分に言ってたんだ！とにかく――",
  ui_story_1_1_69_option_content = "強制感知！",
  ui_story_1_1_70_dialog_content = "<size=45>わーっ！！</size>",
  ui_story_1_1_75_dialog_content = "私、ひとりで暗鬼をやっつけちゃった！",
  ui_story_1_1_76_dialog_content = "光の軌跡が見えて、大幅にパワーアップできたって…",
  ui_story_1_1_77_dialog_content = "これって光の視覚に目覚めたってこと？\n私、どんな光霊も習得できない能力をマスターしちゃったの？",
  ui_story_1_1_78_dialog_content = "…運命…これは運命よ！ううん、もしかして私には何か特殊な血脈が？",
  ui_story_1_1_79_dialog_content = "ってことは、私にはこれから家族の悲劇、運命の試練が次々と訪れるの！？\nトクベツだからってつらい目に遭ったらどうしよう？？",
  ui_story_1_1_80_dialog_content = "厳密にいうと…あれは僕の能力だよ。",
  ui_story_1_1_81_dialog_content = "わ！まだいたのね！あなたは幽霊なの！？",
  ui_story_1_1_82_dialog_content = "幽霊なんかいないよ。これは僕が持っている精神感知の力なんだ。\n君が見た光の軌跡も。",
  ui_story_1_1_83_dialog_content = "そうなの？なんだ…私が超能力とかに目覚めたわけじゃなかったのね？",
  ui_story_1_1_84_dialog_content = "ガッカリさせてごめん…",
  ui_story_1_1_B26_dialog_content = "…",
  ui_story_1_1_B27_dialog_content = "あっ…驚かせちゃったかな？",
  ui_story_1_1_B28_dialog_content = "急に君が落ちてきたものだから、こっちもビックリしちゃって。",
  ui_story_1_1_B29_dialog_content = "いったい何が起こってるの？わけがわからないわ。",
  ui_story_1_1_B30_dialog_content = "やっぱり、直に話したほうがいいかな。\n君たち光霊は、こういうコミュニケーション方法に慣れてないみたいだし。",
  ui_story_1_1_85_dialog_content = "とりあえず、通路に沿って前進して。\n僕はいちばん奥の部屋で待ってるから。",
  ui_story_1_1_86_dialog_content = "わあ…",
  ui_story_1_1_A34_dialog_content = "あれ…",
  ui_story_1_1_87_dialog_content = "どうしたの、僕の顔に何かついてる？\nさっきちゃんと洗ったんだけどなぁ…",
  ui_story_1_1_88_dialog_content = "なんでもないわ。ただ、本当に幽霊じゃなくて、\n生きてる人がいるなんて思わなくて…",
  ui_story_1_1_89_dialog_content = "<size=40>じゃあ何だと思ってたの？？</size>",
  ui_story_1_1_B31_dialog_content = "あなたこそ、さっきの「わあ」は何だったの？",
  ui_story_1_1_B32_dialog_content = "…生きてる人に会うなんて思ってなかったから。",
  ui_story_1_1_90_dialog_content = "ならお互い様じゃない…それで、あなたは一体何者なの？\nここ…巨像なの？",
  ui_story_1_1_91_dialog_content = "ここは巨像。僕はここの…主、かな。\nさっき君に精神感知の力で話しかけたのも僕だよ。",
  ui_story_1_1_92_dialog_content = "ああいう能力って、歴史の教科書でしか見たことなかったわ。だって…",
  ui_story_1_1_93_dialog_content = "だって…？",
  ui_story_1_1_94_dialog_content = "そうだわ、もしかして、あなたって――\n「<color=#FFB400>空の末裔</color>」？",
  ui_story_1_1_95_dialog_content = "そんなに驚くことかな？そうだよ、僕は「空の末裔」。",
  ui_story_1_1_96_dialog_content = "…ここには1人？",
  ui_story_1_1_97_dialog_content = "うん。ここで1人で暮らしてる。僕の故郷が暗鬼に襲われてから…",
  ui_story_1_1_A29_dialog_content = "ええ、聞いたことがあるわ…",
  ui_story_1_1_B33_dialog_content = "ねぇ、僕からも質問していいかな？",
  ui_story_1_1_B34_dialog_content = "わ、急に近寄らないで、空の末裔さん…",
  ui_story_1_1_B35_dialog_content = "あっ、ごめん。えっと、聞きたいのは――",
  ui_story_1_1_B36_option_content = "僕以外の空の末裔に会ったことはある？",
  ui_story_1_1_B37_option_content = "17年前にいったい何が起きたの？",
  ui_story_1_1_B38_option_content = "光霊や暗鬼って何？",
  ui_story_1_1_B39_dialog_content = "僕は物心ついた時からずっとここにいるんだ。\nそれに、通信システムも壊れていてどうしようも――",
  ui_story_1_1_B40_dialog_content = "落ち着いて。他の空の末裔は見たことないわ。\nでも、まだどこか、私の知らない場所にいるんじゃないかしら？",
  ui_story_1_1_B41_dialog_content = "…じゃあ、どうして探しにきてくれないんだろう？",
  ui_story_1_1_B42_dialog_content = "…",
  ui_story_1_1_B43_dialog_content = "当時…天空ノ谷で起きた事件のことは、資料で読んだだけなんだ。\nあとは時々、変な<color=#FFB400>夢</color>を見ることがあって…",
  ui_story_1_1_B44_dialog_content = "夢？",
  ui_story_1_1_B45_dialog_content = "あの時に起きた災難のこと…詳しいことを教えてくれないかな？",
  ui_story_1_1_B46_dialog_content = "あの事件が起こった時は、私もまだ生まれたばかりよ。\n詳しいことは知らないわ。",
  ui_story_1_1_B47_dialog_content = "たしか、暗鬼が突然「<color=#FFB400>組織的な襲撃</color>」を仕掛けて、\n空の末裔たちが住んでいた天空ノ谷を一夜にして滅ぼしてしまったって話よね。",
  ui_story_1_1_B48_dialog_content = "…うん、それなら僕も知ってる。",
  ui_story_1_1_B49_dialog_content = "なら、私から教えられることはなさそうね。ごめんなさい…",
  ui_story_1_1_B50_dialog_content = "で、君って「<color=#FFB400>光霊</color>」なの？",
  ui_story_1_1_B51_dialog_content = "ええ。私たちと空の末裔はかつて一緒に暗鬼と戦っていたらしいわね。",
  ui_story_1_1_B52_dialog_content = "さっきの怪物が、暗鬼？",
  ui_story_1_1_B53_dialog_content = "そうよ。ああいう「生物」が大陸のあちこちで暴れ回ってるの。\nでもあいつらがどこから出てきたのかは、誰にもわからない。",
  ui_story_1_1_B54_dialog_content = "大陸の反対側から来たって言う人もいれば、奴らが現れたのは神罰だって言う人もいるわ…",
  ui_story_1_1_B55_dialog_content = "要するに、あいつらは有史以来ずっと、私たちの共通の敵だったの。",
  ui_story_1_1_B56_dialog_content = "うん…それも全部資料で読んだことがある。",
  ui_story_1_1_B57_dialog_content = "…じゃあ、何で私に聞くのかしら…",
  ui_story_1_1_B58_option_content = "まだ聞きたいことがある",
  ui_story_1_1_B59_option_content = "（沈黙）",
  ui_story_1_1_B60_dialog_content = "他にも聞きたいことがあるんだけど――",
  ui_story_1_1_98_dialog_content = "ねえ、ずっとここにいたの？出たいと思ったことは？",
  ui_story_1_1_99_dialog_content = "それは…僕には戦う力がないんだ。\n君たちのように、<color=#FFB400>光力術</color>を使うことができないから。",
  ui_story_1_1_100_dialog_content = "光の軌跡は見えるけど、それを使って戦うことはできない。皮肉だよね。",
  ui_story_1_1_101_dialog_content = "そう…？光を使って戦えるのに光が見えない光霊の方が、皮肉じゃない…？",
  ui_story_1_1_103_dialog_content = "とにかく、僕はもう何年も地下から出たことがないんだ。\nソラヴァンの生命維持システムのおかげで、今日まで生き延びてきたんだよ。",
  ui_story_1_1_104_dialog_content = "「<color=#FFB400>ソラヴァン</color>」？それってこの巨像のこと？\nすごいわ！名前もあったなんて…",
  ui_story_1_1_105_dialog_content = "もちろんあるよ。\n巨像は魔法、科学技術、生命の結合体で…思考することもできるんだ。",
  ui_story_1_1_106_dialog_content = "生命だから、あなたは巨像とコミュニケーションができるってことね？\n感知能力を持った、空の末裔だから。",
  ui_story_1_1_107_dialog_content = "そうだよ。空の末裔なら、生まれつき持っている力だからね。",
  ui_story_1_1_109_dialog_content = "どうしたの？さっき怪我でもした？",
  ui_story_1_1_110_dialog_content = "…",
  ui_story_1_1_111_dialog_content = "…あ、なんでもないの。ちょっと昔のことを思い出しちゃっただけ。",
  ui_story_1_1_112_dialog_content = "そうだ！それって、今も起動できるってこと？もしかしたら――",
  ui_story_1_1_113_dialog_content = "ごめん。かつては世界でも数えるほどしかない天空級の巨像だったけど、\n今の僕じゃ…動かせないんだ。",
  ui_story_1_1_114_dialog_content = "ところでバイス、巨像に詳しいみたいだね？",
  ui_story_1_1_115_dialog_content = "ちょっと知ってるだけよ！巨像のことが書かれた本を読んだことがあるの。\n今回の任務も、どこかにあるかもしれない巨像を探して…",
  ui_story_1_1_A31_dialog_content = "え、今なんて言った？私、まだ名前を教えてなかったと思うんだけど…",
  ui_story_1_1_A32_dialog_content = "感知能力だよ、バイス。\nさっき、君と君の仲間たちが外で話しているのを聞いたんだ。",
  ui_story_1_1_A33_dialog_content = "あ――はは、ごめんね、さすがは空の末裔。",
  ui_story_1_1_116_dialog_content = "ソラヴァンが起動できないのは残念だけど、\nそれより貴重なお宝が見つかったみたい！",
  ui_story_1_1_117_dialog_content = "…僕のことを言ってるんじゃないよね？",
  ui_story_1_1_118_dialog_content = "あのね、手伝って欲しいことがあるの…\nそうだ、まだ名前を聞いてなかったわ。",
  ui_story_1_1_119_dialog_content = "PlayerNameだよ。",
  ui_story_1_1_120_dialog_content = "PlayerName？やっぱり名前も独特なのね！",
  ui_story_1_1_121_dialog_content = "私、上から落ちてきた時に仲間とはぐれちゃったの！\nみんなの居場所は分かる？",
  ui_story_1_1_122_dialog_content = "今のところ、何も感知できないけど…ソラヴァン、わかる？",
  ui_story_1_1_123_dialog_content = "信号発射台の付近に光霊が2名。\nですが、多くの暗鬼が接近しつつあります。",
  ui_story_1_1_124_dialog_content = "言い換えれば、我々がいるこの場所全体が、\n恐らくもう安全ではないでしょう。",
  ui_story_1_1_125_dialog_content = "君の仲間は信号発射台の近くにいるよ。\n厄介なことになってるみたいだ。",
  ui_story_1_1_126_dialog_content = "それなら助けに行かなきゃ！",
  ui_story_1_1_127_dialog_content = "あなたも来て！あなたは光の軌道を見ることができるし、私たちを指揮できる！",
  ui_story_1_1_128_dialog_content = "それだけで、さっきみたいに私の戦闘力が数倍に跳ね上がるわ！",
  ui_story_1_1_129_option_content = "でも僕、戦闘は苦手で…",
  ui_story_1_1_130_option_content = "一緒に行こう！",
  ui_story_1_1_131_dialog_content = "安心して、私があなたを守るから！",
  ui_story_1_1_132_dialog_content = "彼女の言う通りです。暗鬼は既に侵入しています。\n彼女と一緒に行動した方が安全でしょう。",
  ui_story_1_1_133_dialog_content = "わかった、僕も行くよ、バイス。でもお願いがあるんだ。",
  ui_story_1_1_134_dialog_content = "大丈夫よ！心配しないで、私が守るから！",
  ui_story_1_1_135_dialog_content = "悪くありません。勇敢な光霊ですね。バイスといいましたか？",
  ui_story_1_1_X6_dialog_content = "それにPlayerName、あなたも思い切った決断をしました！",
  ui_story_1_1_136_dialog_content = "でも、ひとつお願いがあるんだ。手伝ってくれると嬉しいんだけど。",
  ui_story_1_1_B61_dialog_content = "大丈夫よ！私にできることなら、遠慮なく話して！",
  ui_story_1_1_137_dialog_content = "僕をここから連れ出してほしいんだ。",
  ui_story_1_1_138_dialog_content = "それは…もちろん。でも、準備はできてるの？",
  ui_story_1_1_139_dialog_content = "僕も…わからない。",
  ui_story_1_1_140_dialog_content = "けど、ずっとここにいるわけにはいかないんだ！",
  ui_story_1_2_1_dialog_content = "エンジェル、もうダメ…",
  ui_story_1_2_2_dialog_content = "こいつら、まるでキリがないよ。力も、あとちょっとしかない…",
  ui_story_1_2_3_dialog_content = "ここはまったく日が当たらないから、光力がほとんどないのね。\nそれに光に抑圧されないから、暗鬼が地上よりも凶暴だわ。",
  ui_story_1_2_4_dialog_content = "どうしたら地上に戻れるかな…バイスは一体どこだろう…",
  ui_story_1_2_6_dialog_content = "ポッポ――！こんなとこで死にたくない…",
  ui_story_1_2_7_dialog_content = "ちょっと！？ドーヴ！私よ！！",
  ui_story_1_2_8_dialog_content = "危なかったわね。光力がほとんど残ってなかったからよかったけど、\nそうじゃなかったらバイスを傷つけてたわよ。",
  ui_story_1_2_9_dialog_content = "バ…バイス、大丈夫？",
  ui_story_1_2_10_dialog_content = "大丈夫！PlayerNameのおかげで無事あなたたちを見つけられたし！",
  ui_story_1_2_11_dialog_content = "PlayerName？誰それ？他には誰も見えないけど。",
  ui_story_1_2_12_dialog_content = "ここにはいないわ。\nでも、私たちを導いてくれるの！合わせてくれればいいわ！",
  ui_story_1_2_13_dialog_content = "合わせる？どうやって？私たちは…",
  ui_story_1_2_14_option_content = "強制感知！",
  ui_story_1_2_15_dialog_content = "今のは…夢？…光の中を走り回るなんて…",
  ui_story_1_2_16_dialog_content = "どういうこと、バイス…それから、そこでずっとドアの後ろに隠れてる人。",
  ui_story_1_2_17_dialog_content = "ごめん…僕は戦えないから。",
  ui_story_1_2_18_dialog_content = "光力を見る力と、精神を直接感知する能力…あなた…",
  ui_story_1_2_19_dialog_content = "バイス、あなたにそんな友達がいたなんて初耳だわ。",
  ui_story_1_2_20_option_content = "知り合ったばかりだよ…",
  ui_story_1_2_21_option_content = "「友達」…？",
  ui_story_1_2_22_dialog_content = "うん。私たちが落ちた後、PlayerNameが助けてくれたの。",
  ui_story_1_2_23_dialog_content = "しかも彼はこの巨像の主、つまり、空の末裔なのよ。",
  ui_story_1_2_24_dialog_content = "僕の…「友達」？",
  ui_story_1_2_25_dialog_content = "PlayerName…どうしたの？",
  ui_story_1_2_26_dialog_content = "ううん、何でもないよ…",
  ui_story_1_2_28_dialog_content = "落ちた後にも暗鬼に遭って、PlayerNameが助けてくれたの。",
  ui_story_1_2_29_dialog_content = "この子はエンジェル、そしてこっちはドーヴ。\n2人とも同じチームのメンバーなの。",
  ui_story_1_2_30_dialog_content = "僕はPlayerName。この巨像の主で、空の末裔だよ。",
  ui_story_1_2_31_dialog_content = "助けてくれてありがとう、PlayerName。\n聞きたいことはたくさんあるけど…",
  ui_story_1_2_32_dialog_content = "空の末裔って何？ぜんぜん知らないや…",
  ui_story_1_2_33_dialog_content = "とにかくありがとう、PlayerName。これからは友達よ！",
  ui_story_1_2_34_dialog_content = "まさか、僕にも「友達」ができる日が来るなんて…",
  ui_story_1_3_1_dialog_content = "それで、バイス。次はどうするの？暗鬼の数が多すぎるわ――応援が必要よ。",
  ui_story_1_3_2_dialog_content = "持ってきたトランシーバーは戦闘中に壊れちゃったの。\n<color=#FFB400>ナビゲーター</color>、ソラヴァンに通信手段はある？",
  ui_story_1_3_3_dialog_content = "それが、壊れてるんだ。",
  ui_story_1_3_X1_dialog_content = "じゃあ、武器とかは…",
  ui_story_1_3_X2_dialog_content = "武装もない…",
  ui_story_1_3_4_dialog_content = "これって巨像でしょ、起動しないの？",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>起動失敗。累計失敗回数：3921回</color>。",
  ui_story_1_3_X4_dialog_content = "動かないんだ…",
  ui_story_1_3_X5_dialog_content = "どうして…？",
  ui_story_1_3_X6_dialog_content = "ダメなんだ。もう何年も数えきれないくらい試してきたけど、\nどういうわけか起動がうまくいかないんだ。",
  ui_story_1_3_X7_dialog_content = "本当にごめん。でも、この巨像はそもそも状態が良くないんだ…",
  ui_story_1_3_X8_dialog_content = "僕の生命を維持するために、もうほとんど力を使い果たしちゃってるんだ。\nずいぶん無理してるんだよ。",
  ui_story_1_3_X9_dialog_content = "お褒めにあずかり感謝します、PlayerName。",
  ui_story_1_3_X10_dialog_content = "…",
  ui_story_1_3_6_dialog_content = "待って、ナビゲーター。",
  ui_story_1_3_X11_dialog_content = "起動できなくても、武器が無くても、さっき言ってた…",
  ui_story_1_3_7_dialog_content = "信号発射台、あるのよね？",
  ui_story_1_3_8_dialog_content = "確か、巨像にはどれも必ず信号発射台があって、救難信号を出せるはずよ。",
  ui_story_1_3_A1_dialog_content = "誰かが救難信号を見たら、きっと助けに来てくれるはず！",
  ui_story_1_3_9_dialog_content = "近くにあるよね？\nさっき、ドーヴとエンジェルが信号発射台のところにいるって言ってたでしょ！",
  ui_story_1_3_10_dialog_content = "…ずいぶん巨像に詳しいんだね？",
  ui_story_1_3_X12_dialog_content = "ふふ、ちょっと知ってるだけよ。\n今までこんな知識は「無用の長物」だって言われてたけど…",
  ui_story_1_3_X13_dialog_content = "発射台は確かに、この近くにあるよ。傷ひとつない。",
  ui_story_1_3_X14_dialog_content = "でも、もう気付いているかもしれないけど…",
  ui_story_1_3_11_dialog_content = "発射するマーカーの材料がないんだ――",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>光珀</color>。",
  ui_story_1_3_13_dialog_content = "え、どうして…あぁ、「ちょっと知ってる」んだったね。",
  ui_story_1_3_14_dialog_content = "もし光珀だったら、ちょうど持って来てるわよ。",
  ui_story_1_3_15_dialog_content = "オホン、オホン。バイス、あれは…",
  ui_story_1_3_16_dialog_content = "どうしたの？持っているのを見たわ。\nあなたのカバンの中にあるはずよ。",
  ui_story_1_3_18_dialog_content = "あれ、すごく高いんだよ…",
  ui_story_1_3_19_dialog_content = "生きるか死ぬかって時に何言ってるのよ！\n今そんなことにケチケチしてどうするの、ドーヴ！",
  ui_story_1_3_B1_dialog_content = "経費で精算してくれる？",
  ui_story_1_3_B2_dialog_content = "もちろん！それと、帰ったら休暇を10日あげる。どう？",
  ui_story_1_3_B3_dialog_content = "ポッポッポ！決まりだよ！",
  ui_story_1_3_B4_dialog_content = "それじゃあ、早く信号発射台に行きましょう！",
  ui_story_1_3_A2_dialog_content = "途中で暗鬼が出てくるかもしれないわ、みんな注意して！",
  ui_story_1_3_24_dialog_content = "着いた！ここって迷路みたいね。ナビゲーターがいてよかったわ！",
  ui_story_1_3_25_dialog_content = "なんたって、ここに17年も籠ってるからね…",
  ui_story_1_3_26_dialog_content = "それにしても、間に合ってよかったわ。\nもう少し遅かったら暗鬼に荒らされたあとだったわね…",
  ui_story_1_3_27_dialog_content = "よかった、設備は無事だ。",
  ui_story_1_3_28_dialog_content = "えっと、あれが発射台？",
  ui_story_1_3_29_dialog_content = "ああ、実物を見るのは初めて…。具体的な操作となると…",
  ui_story_1_3_30_dialog_content = "光珀を発射器に入れて、<color=#FFB400>バーを動かす</color>だけだよ。",
  ui_story_1_3_31_dialog_content = "でも材料がなかったから、ずっと使えなかったんだ…",
  ui_story_1_3_33_dialog_content = "でも今日は頼れる相棒がいるわ！ドーヴ～",
  ui_story_1_3_34_dialog_content = "バイス、大事に使ってくれるよね？",
  ui_story_1_3_35_dialog_content = "もちろんよ。",
  ui_story_1_3_36_dialog_content = "…",
  ui_story_1_3_B5_dialog_content = "…ドーヴ、ええと…もう手を放していいのよ…",
  ui_story_1_3_B6_dialog_content = "ポッポッ…後悔しそう…",
  ui_story_1_3_B7_dialog_content = "今さら撤回するなら、暗鬼の指を千本飲ますわよ。",
  ui_story_1_3_B8_dialog_content = "ポッ――！",
  ui_story_1_4_1_dialog_content = "やったわ！発射成功よ！まぶしい！",
  ui_story_1_4_2_dialog_content = "やった…バイス、ありがとう！",
  ui_story_1_4_3_dialog_content = "え？私はなにもしてないわ！ちょっと思いついたことがあっただけ！",
  ui_story_1_4_4_dialog_content = "本当に私に感謝したいなら、この場を脱出した後よ！",
  ui_story_1_4_5_dialog_content = "やはり、人並み以上に優秀な光霊のようですね。\n連携を見る限り、相性もよさそうです。",
  ui_story_1_4_6_dialog_content = "ずっと静かに暮らしていたけど…今日それが打ち破られたんだね。",
  ui_story_1_4_X1_dialog_content = "でもあまり嬉しそうじゃないのはどうして、PlayerName？\nどこか具合でも悪いの？",
  ui_story_1_4_X2_dialog_content = "いや、ただ…まぶたが少し重くて…",
  ui_story_1_4_B29_dialog_content = "もしかして眠いの？あっ！それならこれがあるわ――\n『機械製図学』！",
  ui_story_1_4_B30_dialog_content = "私、眠くなったときはいつもこれを読むの。\nこの図表を見ていると、バッチリ目が覚めてくるわ！",
  ui_story_1_4_B31_dialog_content = "それは君だけじゃないかな、バイス…",
  ui_story_1_4_X3_dialog_content = "そう？でも…あ！",
  ui_story_1_4_X4_dialog_content = "どうしたの？僕の顔にまた何か付いてる？",
  ui_story_1_4_X5_dialog_content = "鼻血！鼻血が出てる！",
  ui_story_1_4_X6_dialog_content = "ま、まずい、感知の…使いすぎか…",
  ui_story_1_4_X7_dialog_content = "発射台を操作して、脳がもう限界みたい…",
  ui_story_1_4_A1_dialog_content = "え！？私たち全員を余裕で指揮していたのに、どうして…？",
  ui_story_1_4_A2_dialog_content = "巨像のコントロールには…それより多くの力が…必要なんだ…\n大丈夫、前も、あったから…すぐ良く…",
  ui_story_1_4_7_option_content = "もうダメ…",
  ui_story_1_4_8_option_content = "バ…イス…",
  ui_story_1_4_9_dialog_content = "どうしたの…ああ！誰か！PlayerNameが倒れちゃった！！",
  ui_story_1_4_10_dialog_content = "私じゃ、支えきれない！2人とも早く来て手伝って…\nPlayerName、重すぎるわ！！",
  ui_story_1_4_12_dialog_content = "信号がたくさんの暗鬼を引き寄せています。早く移動しないと！",
  ui_story_1_4_13_dialog_content = "バイス中尉、このまま彼も引きずって行くとなると、\n足手まといになってしまいます。",
  ui_story_1_4_A6_dialog_content = "何より、私の任務はこちらの女性を<color=#FFB400>シェルター28号</color>まで護送することです。\n決して…",
  ui_story_1_4_A3_dialog_content = "応援に来てくれて感謝するわ。\nでも、PlayerNameには助けられたの。見捨てることはできないわ。",
  ui_story_1_4_14_dialog_content = "恩を仇で返すなんて、<color=#FFB400>啓光連邦</color>のやり方に反するわ！",
  ui_story_1_4_A4_dialog_content = "それに、PlayerNameは…空の末裔よ。",
  ui_story_1_4_15_dialog_content = "空の末裔…本当ですか？",
  ui_story_1_4_16_dialog_content = "いずれにせよ、こちらは戦力が足りません。\n気絶した者まで連れていては、全員の安全を保障しかねます！",
  ui_story_1_4_17_dialog_content = "それも分かるわ。じゃあ、あなたはみんなを連れて行ってちょうだい。\nでも、少しだけ物資を分けて。私はここに残るから。",
  ui_story_1_4_18_dialog_content = "あなたの勇気には感服しました、バイス中尉。",
  ui_story_1_4_19_dialog_content = "自己紹介がまだでしたね。私はブランと申します。以後お見知りおきを。",
  ui_story_1_4_20_dialog_content = "ごめんなさい、あなたの旅の予定を邪魔してしまって…",
  ui_story_1_4_21_dialog_content = "どうぞお気になさらず。救難信号に応えるのは当然のこと。",
  ui_story_1_4_22_dialog_content = "それに、巨像をこの目で見ることができましたから、\n寄り道のかいもありました。",
  ui_story_1_4_23_dialog_content = "隊長が残るなら、合同探索隊の一員である私も、\n逃げるわけにはいかないわね。",
  ui_story_1_4_24_dialog_content = "ポッ？じ…じゃあ私も残ろうかな。PlayerNameは私たちの命の恩人だしね…",
  ui_story_1_4_25_dialog_content = "みんな…",
  ui_story_1_4_A5_dialog_content = "あ！よかった、目が覚めたのね！|\nあなたが意識を失っている間に、応援が到着したの。気分はどう？動ける？",
  ui_story_1_4_26_dialog_content = "うん……",
  ui_story_1_4_28_dialog_content = "バイス中尉、たった今連絡が入りました。\nこの付近でクラーケンの活動の痕跡が確認されたとのことです。",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>上級暗鬼クラーケン</color>？確かに最近は動きが活発みたいけど、\nどうしてこの近くにいるのかしら…",
  ui_story_1_4_30_dialog_content = "とにかく、今戦うべき相手じゃないわね！移動しなくちゃ！",
  ui_story_1_4_31_dialog_content = "PlayerName、一緒に行ける？",
  ui_story_1_4_32_dialog_content = "一緒に行きたいところだけど、バイス。ソラヴァンは…",
  ui_story_1_4_33_dialog_content = "この巨像がソラヴァンですか？\nこちらの回収作業については、後で時間をかけて協議しましょう。",
  ui_story_1_4_X8_dialog_content = "私の仕事は皆さんの安全をお守りすること以外にありません。",
  ui_story_1_4_X9_dialog_content = "行ってください、PlayerName。\nあなたが危機を脱することさえできれば、私の安否は重要ではありません。",
  ui_story_1_4_X10_dialog_content = "まずは皆さんと包囲を突破し、ここから逃げるのです！",
  ui_story_1_4_B1_option_content = "ごめん、すぐ迎えに来るから！",
  ui_story_1_4_B2_option_content = "…一緒に行ける方法はないのかな？",
  ui_story_1_4_B3_option_content = "荷物をまとめないと…",
  ui_story_1_4_B4_dialog_content = "分かったよ。君たちについていく！",
  ui_story_1_4_B5_dialog_content = "今日この瞬間を、首を長くしてずっと待っていたんだ…\n外の世界がどんな様子だとしても、自分の目で見てみたい。",
  ui_story_1_4_B6_dialog_content = "それにまだわからない事がたくさんある。同族の人たちに聞きたいんだ…",
  ui_story_1_4_B7_dialog_content = "わかったわ！それじゃあ戦闘の準備をしなくちゃ。もしすでに大量の暗鬼に\n囲まれているとしたら、これからもっとたくさん戦うことになるかもしれないわ！",
  ui_story_1_4_B9_dialog_content = "未練、恐怖、不安…そうした感情は強くなるための妨げとなります。",
  ui_story_1_4_B10_dialog_content = "克服していってください。まずは、私への未練から。",
  ui_story_1_4_B11_dialog_content = "ソラヴァン…",
  ui_story_1_4_B12_dialog_content = "ここから出て初めて、あなたは空の末裔として一人前になるのです。\nさあ、行ってください。今のあなたには、たくさんの仲間がいるでしょう？",
  ui_story_1_4_B13_dialog_content = "それに私はどこにも行きません。心配しないでください。",
  ui_story_1_4_B14_dialog_content = "PlayerName、暗鬼がもっと押し寄せる前に、すぐに行動しないといけないわ！",
  ui_story_1_4_B15_dialog_content = "分かったよ…",
  ui_story_1_4_B16_dialog_content = "よし！みんな集中して、いつでも戦えるように備えて！皆でここを出るわよ！",
  ui_story_1_4_B17_dialog_content = "えっ？荷物？",
  ui_story_1_4_B18_dialog_content = "廃パーツで作った万華鏡に、ケーブルを巻いて作ったボール、\nあと、光力の塗料で描いた絵…",
  ui_story_1_4_B19_dialog_content = "…",
  ui_story_1_4_B20_dialog_content = "笑わないでよ…つまらない物かもしれないけど、僕とずっと一緒だったんだ…",
  ui_story_1_4_B21_dialog_content = "名前だって付けてあるんだよ…",
  ui_story_1_4_B22_dialog_content = "…気持ちはわかりますが、今はそれらにこだわっている場合ではないと思います。",
  ui_story_1_4_B23_dialog_content = "PlayerName、私を信じてください。ここを出れば、\nもっと大切にしたくなる物が手に入れられるでしょう。",
  ui_story_1_4_B24_dialog_content = "それに私やあなたの大事にしてきた物は、どこにも行きません。\nすべてが終わったら、また会いにきてください。",
  ui_story_1_4_B25_dialog_content = "そうするしかなさそうだね…",
  ui_story_1_4_B26_dialog_content = "ごめん、変なことを言って…まずはここを離れよう。",
  ui_story_1_4_B32_dialog_content = "ふふっ、気にしないで！私も人に分かってもらえない趣味が色々あるわ！",
  ui_story_1_4_B27_dialog_content = "さあ行きましょう！\n元気を出して、暗鬼が集まってくる前に出口を探さないと！",
  ui_story_1_4_B28_dialog_content = "ナビゲーター、いつでも戦闘を指揮できるように準備しておいてね！",
  ui_story_1_8_1_dialog_content = "なんとか切り抜けたけど、暗鬼がたくさん…この場所はもうもたないわ。",
  ui_story_1_8_B37_dialog_content = "どこもかしこも、破壊された跡だらけだ…ずっときれいに整頓しておいたのに…",
  ui_story_1_8_2_dialog_content = "ごめんなさい、PlayerName、私たちが押しかけなければ…",
  ui_story_1_8_3_dialog_content = "そしたら、僕がここを離れるチャンスも無かったよ。謝らないで、バイス。\n君たちは悪くない。悪いのは暗闇から這い出してきたあいつらだ。",
  ui_story_1_8_B29_dialog_content = "安心して。ソラヴァンを回収したら、私が必ず啓光に修理をお願いするから！",
  ui_story_1_8_B30_dialog_content = "それに、私が改造プランの設計図だって作ってあげるわ！",
  ui_story_1_8_B31_dialog_content = "何か設計してほしいものはある？あ、オープンキッチンとかはどう？\n普段、タコのミルク煮なんかを作ったりできるような場所よ。",
  ui_story_1_8_B32_dialog_content = "料理は作れないんだ。いつもソラヴァンがやってくれてたから…",
  ui_story_1_8_B33_dialog_content = "あ、そっか。なら超特大バスタブなんてどう？\n一日の仕事を終えたあと、ゆっくりお湯につかって読書なんかも…",
  ui_story_1_8_B34_dialog_content = "いや、今のところ、そういうのは必要ないかな…",
  ui_story_1_8_B35_dialog_content = "もしかして、機械製図室とか実用的なものの方が興味あったりする？",
  ui_story_1_8_B36_dialog_content = "バイス、ありがとう。もし僕を元気づけようとしてくれてるなら、\nもう十分元気だよ。大丈夫。",
  ui_story_1_8_4_dialog_content = "えっ？あ…ごめんなさい…",
  ui_story_1_8_B38_dialog_content = "少し落ち込んでるように見えたから、\n私が興味のあることで気を紛らわせようと思っただけなの…",
  ui_story_1_8_5_dialog_content = "それに、一気に指揮をする人数が増えたでしょう？\nまた無理をして、鼻血を出さないか心配になって…",
  ui_story_1_8_6_dialog_content = "戦闘を手助けするのは君たち全員でも全く問題ないよ。\n巨像の感知に比べれば、このくらいのこと――",
  ui_story_1_8_7_dialog_content = "<size=45>前方に異常！後退！！早く下がって！</size>",
  ui_story_1_8_8_dialog_content = "これは！？",
  ui_story_1_8_9_dialog_content = "こんな力、考えられる可能性はただひとつ…クソ、やはり遭遇したか！",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>クラーケン</color>！！",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>グオオ！！</size></anim>",
  ui_story_1_8_12_dialog_content = "この世にあんな大きさの暗鬼が！？まさか天空ノ谷は、ああいうやつにやられて…",
  ui_story_1_8_13_dialog_content = "危険よ、PlayerName！安全な場所に隠れましょう！",
  ui_story_1_8_14_dialog_content = "安全な場所などありませんよ！？包囲を突破するなら、\nクラーケンを正面から撃破しなくては！",
  ui_story_1_8_15_option_content = "じゃあ、正面から倒しに行こう！",
  ui_story_1_8_16_option_content = "じゃあ、僕は後方でサポートする！",
  ui_story_1_8_17_dialog_content = "その調子！行くわよ！",
  ui_story_1_8_A2_dialog_content = "指揮は今回もあなたに任せるわ、ナビゲーター！",
  ui_story_1_8_18_dialog_content = "すぐに精神感知を始めるよ。みんな、準備して！",
  ui_story_1_8_19_dialog_content = "任せたわ！行きましょう！",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>グオォォン！！！</size></anim>",
  ui_story_1_8_21_dialog_content = "うるさいなあ、もう！大人しく地底に帰ってよ！",
  ui_story_1_8_B1_dialog_content = "ガガガ…",
  ui_story_1_8_B2_dialog_content = "もしかして…何かしゃべってる？",
  ui_story_1_8_B3_option_content = "バイス、とどめを刺して",
  ui_story_1_8_B4_option_content = "強制感知！",
  ui_story_1_8_B6_dialog_content = "速射感知――",
  ui_story_1_8_B7_dialog_content = "こいつが何を言ってたにせよ、理解なんてしたくないよ…",
  ui_story_1_8_B8_dialog_content = "臭いもひどいし…！！",
  ui_story_1_8_B9_dialog_content = "これは<color=#FFB400>暗影術</color>の臭いだわ…\n暗鬼たちはみんなそのエネルギーで動いていたのね。",
  ui_story_1_8_B10_dialog_content = "ここまで濃いと、誰だって吐き気がするわ…",
  ui_story_1_8_B11_dialog_content = "グ…ガァ…",
  ui_story_1_8_B12_dialog_content = "やっぱり…暗鬼の言葉は理解できないか…",
  ui_story_1_8_B13_dialog_content = "今まで他の生き物を感知したことはなかったけど、慣れてないせいもあるのかな？",
  ui_story_1_8_B14_dialog_content = "…<color=#FFB400>空の</color>…<color=#FFB400>末裔</color>？",
  ui_story_1_8_B15_dialog_content = "…？",
  ui_story_1_8_B16_dialog_content = "ウガ…",
  ui_story_1_8_B17_dialog_content = "死んだ…？ほとんど情報を読み取ることはできなかったけど、\n強烈な感情を感じとれた。",
  ui_story_1_8_B18_dialog_content = "死の恐怖よりも、驚きが強かった気がするのは…なんでだろう？",
  ui_story_1_8_22_dialog_content = "私たち…上級暗鬼に勝っちゃうなんて…",
  ui_story_1_8_23_dialog_content = "もしかして、いつの間にか強くなってた？",
  ui_story_1_8_24_dialog_content = "しっかりなさい、全部PlayerNameのおかげよ。\nでなきゃあなたなんて、逃げる方向すらわからなかったでしょ。",
  ui_story_1_8_25_dialog_content = "PlayerNameの光力を知覚する能力…本当に不思議ですね。",
  ui_story_1_8_A3_dialog_content = "そういえば、ある老兵から聞いたことがあります。",
  ui_story_1_8_26_dialog_content = "当時、空の末裔が戦場に現れさえすれば、勝利は必ず我々の側にあった、と。\nどうやら誇張などではなかったようですね。",
  ui_story_1_8_27_dialog_content = "出口はこの先よ。一気にここを離れましょう！",
  ui_story_1_8_28_dialog_content = "PlayerName、体力のほうは大丈夫そう？",
  ui_story_1_8_B19_dialog_content = "大丈夫。体力よりも、僕は…他に注意すべきことがあるのかな？",
  ui_story_1_8_B20_dialog_content = "どういうこと？",
  ui_story_1_8_B21_dialog_content = "僕はずっと巨像の中で暮らしてきた。外の世界は一体どんなところなのか…",
  ui_story_1_8_B22_dialog_content = "息を止めたほうがいいかな？",
  ui_story_1_8_B23_dialog_content = "もしかしたら、空気中に未知の細菌が漂ってるかも…？",
  ui_story_1_8_B24_dialog_content = "目を閉じて、日光の感覚に慣れたほうがいいかな？",
  ui_story_1_8_B25_dialog_content = "ああっ、それよりも顔を覆ったほうが…",
  ui_story_1_8_B26_dialog_content = "…17年間、ずっと何を考えてたのか分かった気がするわ。",
  ui_story_1_8_B27_dialog_content = "あははっ！気にしすぎよ。私と一緒に行けば問題ないわ。\n外の世界はあなたが思ってるほど、変なところじゃないもの。",
  ui_story_1_8_B28_dialog_content = "ほら、手を貸して。",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>新しい世界</color>…",
  ui_story_1_8_30_dialog_content = "――！？",
  ui_story_1_8_31_dialog_content = "バイス…問題発生よ…",
  ui_story_1_8_32_dialog_content = "これって…<color=#FFB400>暗鬼の大群</color>！？こんなところに！？",
  ui_story_1_8_33_dialog_content = "みんな、早く戻って、入口を封鎖して！",
  ui_story_1_8_34_dialog_content = "我々が応援に来た時にはいなかったはず…もろい壁を補強します！",
  ui_story_1_8_A4_dialog_content = "ですが、こうなってしまっては、再度外へ脱出することが難しくなります。バイス中尉！",
  ui_story_1_8_36_dialog_content = "どうしてこんなにたくさんの暗鬼が！？前線でもないのに、こんな大規模の！",
  ui_story_1_8_37_dialog_content = "落ち着いてください、バイス中尉。\n大量の暗鬼が前線を超えてここまで来ているようです。",
  ui_story_1_8_38_dialog_content = "問題は、どうやって啓光連邦の封鎖を通り抜けてきたか…",
  ui_story_1_8_39_dialog_content = "きっと、乗り物か何かで空から、とか…",
  ui_story_1_8_40_dialog_content = "こんなにたくさんの暗鬼を乗せることができる乗り物なんてある？\nまさか別の巨像？そんな偶然は…",
  ui_story_1_8_41_dialog_content = "単なる僕の考え過ぎかもしれないけど…どちらにしても、\n今ここを離れる方法はひとつだけだね。",
  ui_story_1_8_42_dialog_content = "つまり…<color=#FFB400>この巨像を起動する</color>しかない。",
  ui_story_1_8_44_dialog_content = "でも、今まで成功したことがないって…",
  ui_story_1_8_45_dialog_content = "他に選択肢がある？もう一度試すだけだよ。",
  ui_story_1_8_46_dialog_content = "空の末裔なのに、もし巨像の起動すらできなかったのなら…",
  ui_story_1_8_47_dialog_content = "…でも、さっき一度、倒れてるのよ…耐えられるの？",
  ui_story_1_8_48_dialog_content = "無理に起動したら、あなたの頭が…爆発したりしない？",
  ui_story_1_8_49_dialog_content = "心配してくれてありがとう。でも、やるしかない！",
  ui_story_1_8_50_dialog_content = "…",
  ui_story_1_8_51_dialog_content = "バイス…あなた、もしかして…",
  ui_story_1_8_52_dialog_content = "うん。理論上、手助けできると思う。理論上ってだけだけど。",
  ui_story_1_8_53_dialog_content = "何か言った？",
  ui_story_1_8_54_dialog_content = "よし！準備ができたわ！何か問題があったら、その時に考えましょ！\n乗り越えられない壁なんてないって、信じてるわ！",
  ui_story_1_8_55_dialog_content = "今まではあなた1人だった。でも、今は私たちがいる。\nなにか変わるかもしれないじゃない？",
  ui_story_1_8_56_dialog_content = "なんで僕より自信があるの？",
  ui_story_1_8_57_dialog_content = "それは当然よ。私はいつもポジティブなの、PlayerName。",
  ui_story_1_8_59_dialog_content = "これもきっと、あなたにとって今後のための試練なのよ！\nでも、あなたはもうひとりじゃない！",
  ui_story_1_8_60_dialog_content = "わかったよ！じゃあ、一緒にブリッジへ！",
  ui_story_1_8_61_dialog_content = "PlayerName…",
  ui_story_1_8_62_dialog_content = "今度こそきっと君を動かしてみせるよ、ソラヴァン！",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>メインコントロールシステム、セルフチェック…異常なし。起動中…</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>生体モジュール、セルフチェック…異常あり。瀕死状態。</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>生命維持システムセルフチェック…停止。</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>エンジンセルフチェック…異常なし。起動中…</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%…23%…</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%…85%…</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>起動失敗。累計失敗回数：3922回。</color>",
  ui_story_1_9_8_dialog_content = "やっぱり…だめか。",
  ui_story_1_9_10_dialog_content = "どうして？どうしてまたダメなの！？一体どこに問題が…？",
  ui_story_1_9_11_dialog_content = "う！ま、また限界か…",
  ui_story_1_9_12_dialog_content = "ポッポッ…PlayerName、どうしたの…",
  ui_story_1_9_13_dialog_content = "バイス、あなたに確信があるなら、今がその時よ。",
  ui_story_1_9_14_dialog_content = "うん！この「ピアノ」にそっくりな物、これが巨像の制御装置？",
  ui_story_1_9_15_dialog_content = "一緒に巨像を起動しよう、ナビゲーター。",
  ui_story_1_9_16_dialog_content = "一緒に…？バイス、君は光霊だよね、感知能力はない…",
  ui_story_1_9_17_dialog_content = "でも、私はあなたの力になれる。私なら…やれるわ。",
  ui_story_1_9_18_dialog_content = "…？",
  ui_story_1_9_19_dialog_content = "信じて、PlayerName。私とあなたは…少し似ている所があるの。",
  ui_story_1_9_21_dialog_content = "でもそれを話すと長くなっちゃうから、また今度ゆっくり話してあげるわ！",
  ui_story_1_9_22_dialog_content = "…でも、本当に君は、この制御装置の使い方がわかるの？",
  ui_story_1_9_23_dialog_content = "もちろん！私が巨像については詳しいってこと、忘れてないでしょ？",
  ui_story_1_9_24_dialog_content = "それに、啓光はずっと「巨像の再建とナビゲーター育成」の計画を立てていたのよ。\nだけど…",
  ui_story_1_9_25_dialog_content = "…まぁ、要するに、私たち2人が協力すれば、\nエンジンを起動させられるかもしれないの！",
  ui_story_1_9_26_dialog_content = "でも、もし問題が起きたら二人とも…\n君の言い方を借りれば、「頭が爆発」しかねないよ。",
  ui_story_1_9_27_dialog_content = "今は他に方法がないわ。リスクがあっても、やってみなきゃ。",
  ui_story_1_9_28_dialog_content = "わかったよ。ここまで来たんだ、もう逃げ場もない。来て、隣に座って。",
  ui_story_1_9_29_dialog_content = "どうやって「演奏」するか教えるよ。",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>エンジンセルフチェック…異常なし。起動中…</color>",
  ui_story_1_9_B1_dialog_content = "ナビゲーター、どうすればいいか教えて。",
  ui_story_1_9_B2_dialog_content = "簡単だよ、ピアノを弾くみたいにすればいいんだ。",
  ui_story_1_9_B3_dialog_content = "でも楽譜がないわ。どの鍵盤を押せばいいのか、教えてくれる？",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%…33%…</color>",
  ui_story_1_9_B4_dialog_content = "感じるわ…エネルギーの流れを。",
  ui_story_1_9_B5_dialog_content = "ソラヴァンに光力を注入してるの？",
  ui_story_1_9_B6_dialog_content = "うん。会話するみたいなものよ――巨像の言葉は、私にはわからないけど。",
  ui_story_1_9_B7_dialog_content = "鍵盤で話すのがソラヴァンの言葉なんだよ、バイス。",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%…97%…</color>",
  ui_story_1_9_B8_dialog_content = "もう少しだ…こんなの、信じられないよ…",
  ui_story_1_9_B9_dialog_content = "ナビゲーター、楽譜はもう少しで終わりなのね？",
  ui_story_1_9_B10_dialog_content = "そうだよ。さあ、起動命令を完成させよう、バイス！",
  ui_story_1_9_B11_dialog_content = "最後の音符――",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100%、起動成功。</color>",
  ui_story_1_9_34_dialog_content = "どういうことだ！辺りが光り出したぞ！",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName！！！</size>",
  ui_story_1_9_36_dialog_content = "ブリッジが、光ってる…？",
  ui_story_1_9_37_dialog_content = "<size=45>う、う、動いた！！</size>",
  ui_story_1_9_38_dialog_content = "…！",
  ui_story_1_9_40_dialog_content = "PlayerName！本当に、やりましたね！！まさかここまでやり通すとは！",
  ui_story_1_9_41_dialog_content = "これが――ブリッジの姿ね！全部光ってる！",
  ui_story_1_9_42_dialog_content = "綺麗…これが光力の色なの？",
  ui_story_1_9_A1_dialog_content = "それとも…あれは極光！？",
  ui_story_1_9_43_dialog_content = "ああ、もう、びっくりだわ！こんな景色見たことない…",
  ui_story_1_9_44_dialog_content = "これが本物の…空？なんて眩しくて、でも美しいんだ…",
  ui_story_1_9_45_dialog_content = "僕たちが本当にやり遂げたなんて信じられないけど、\n足元からほとばしるこの力、今まで感じたことがないよ！",
  ui_story_1_9_46_dialog_content = "本当に「生き返った」んだね、ソラヴァン！！",
  ui_story_1_9_47_dialog_content = "ええ！エネルギーが体の様々な部分に流れ込んでいますが――\n飛び立つにはまだ時間が必要です！",
  ui_story_1_9_48_dialog_content = "周囲に敵がいるかもしれません。常に警戒を！",
  ui_story_1_9_49_dialog_content = "ずいぶん長いこと動いていないから、まずはウォームアップが必要かな？",
  ui_story_1_9_50_dialog_content = "そうとも言います。どうやら余裕もありそうですね？",
  ui_story_1_9_51_dialog_content = "PlayerName！あなたは自分の状態に気をつかって！",
  ui_story_1_9_52_dialog_content = "いい感じだよ、バイス！不快感は全くない！",
  ui_story_1_9_A2_dialog_content = "僕はずっと、何が起こったらここを離れて、世界に戻れるのか想像してきたけど…",
  ui_story_1_9_A3_dialog_content = "でも今日こんな風に、光霊たちと一緒にだなんて思いもしなかった！",
  ui_story_1_9_53_dialog_content = "僕が今まで想像すらできなかったことを、みんなでやり遂げたんだ！",
  ui_story_1_9_54_dialog_content = "私もこんなこと、想像はしてなかったわね…",
  ui_story_1_9_A4_dialog_content = "全体が残ってる巨像、すぐそこにある「極光」…",
  ui_story_1_9_55_dialog_content = "言っておくけど、昨日までの私だって、暗鬼と一人で戦うこともできない、\n啓光連邦のただの衛兵だったんだもの！",
  ui_story_1_9_56_dialog_content = "眩暈が…また…あの夢だ…",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>スーモア</color>、なぜだ！！",
  ui_story_1_9_59_dialog_content = "スーモア、この裏切り者！力のために一族を裏切るとは！",
  ui_story_1_9_60_dialog_content = "裏切り…反逆…そんなの、偽善者と臆病者の墓碑銘に過ぎないわ。",
  ui_story_1_9_61_dialog_content = "天空ノ谷はもう腐ってる。「同族」の皆さん、私は私のやり方で、\nあなたたちが言う「価値観」とやらを実現するわ。",
  ui_story_1_9_62_dialog_content = "抗っても無駄よ。強い者が勝ち、弱い者が淘汰される。単純でしょ。",
  ui_story_1_9_63_dialog_content = "うわあぁぁ――！",
  ui_story_1_9_64_dialog_content = "…また、あの夢を？",
  ui_story_1_9_65_dialog_content = "いや…今まで以上だったよ。ソラヴァン、これは一体どういう意味？\n僕はどうしてこんな光景が見えるの！？",
  ui_story_1_9_A5_dialog_content = "…",
  ui_story_1_9_66_option_content = "今は放っておこう",
  ui_story_1_9_A6_option_content = "これは幻影じゃない！",
  ui_story_1_9_67_option_content = "何か僕に隠し事をしてない？",
  ui_story_1_9_B12_dialog_content = "僕は…もう訳のわからない幻に邪魔されたくない。",
  ui_story_1_9_B13_dialog_content = "起動に成功したばかりだし、巨像の安定を維持しなきゃ。集中しないと、早く…",
  ui_story_1_9_B14_dialog_content = "手間をかけます、PlayerName。あなたが見るその光景は…\nいつか答えを得ることができるはずです。",
  ui_story_1_9_B15_dialog_content = "私も、その答えを探しています。そして今、私たちはその準備が整いました。",
  ui_story_1_9_B16_dialog_content = "またわかりにくい言い方をするんだね、ソラヴァン。\nでも僕は今日…とにかく、やり遂げたんだ。",
  ui_story_1_9_B17_dialog_content = "はい。このまま前を見て進みましょう。空の末裔にとって――\n青空は、すぐ目の前に広がっているものです。",
  ui_story_1_9_B18_dialog_content = "リアルすぎるんだ…あれは本物だよ、\n幻影じゃない！本当に起こったことなんだ。そうだよね！？",
  ui_story_1_9_B19_dialog_content = "それがあなたの意識に存在する以上、現実に痕跡を残したものであることは\n間違いないでしょう。私にはそれを否定することができません。",
  ui_story_1_9_B20_dialog_content = "ソラヴァン、回りくどい言い方でごまかさないでよ…\n僕は本当のことが知りたいんだ！",
  ui_story_1_9_B21_dialog_content = "私もお教えしたいと考えていますが、残念ながら私にはできないのです。",
  ui_story_1_9_B22_dialog_content = "そもそも、覚えていないのです。あの夜、すべてが失われました。\n唯一私が覚えていることは、「あなたを生かし続ける」という命令だけです。",
  ui_story_1_9_B23_dialog_content = "…",
  ui_story_1_9_B24_dialog_content = "しかし、それが真実であろうと幻であろうと、私たちは今、旅だったのです。",
  ui_story_1_9_B25_dialog_content = "あなたも、自分で答えを探す準備ができている。そうでしょう？",
  ui_story_1_9_B26_dialog_content = "答えてよ、ソラヴァン。一体何を隠してるの…この光景は本物？それとも偽物！？",
  ui_story_1_9_B27_dialog_content = "私にはわかりません、PlayerName。",
  ui_story_1_9_B28_dialog_content = "冗談はやめて…",
  ui_story_1_9_B29_dialog_content = "あなたに嘘をついたことはありません。私は、当時起きた出来事のすべてを「喪失」し、\n記憶を失くしてしまいました。それが事実です。",
  ui_story_1_9_B30_dialog_content = "私も長い間、漠然とした希望を与えるより、明確な回答を教えたいと願っていました。\nしかし、運命が転機を迎えたようです。",
  ui_story_1_9_B31_dialog_content = "新たな仲間の協力も得られたいま、\n自分自身で答えを探す準備ができているのではありませんか？",
  ui_story_1_9_B32_dialog_content = "でも、探している答えって、一体何なんだろう…",
  ui_story_1_9_B33_dialog_content = "僕の一族、そして天空ノ谷。\nもし答えの最後の1ページが、僕の最も恐れた通りだったら――",
  ui_story_1_9_B34_dialog_content = "このすべてに、どれほどの意味があるんだろう？",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>某所</color>",
  ui_story_1_10_2_dialog_content = "『報告…光霊が巨像ソラヴァン内部に侵入、中には…「空の末裔」の存在あり…』",
  ui_story_1_10_3_dialog_content = "『光霊小隊の戦闘力は強く、クラーケンは真理の命を完遂できず…』",
  ui_story_1_10_A1_dialog_content = "『クラーケンは罪を背負う覚悟ができております。\n母上が御座すかの地へ還り、裁きをこいねがいます…』",
  ui_story_1_10_4_dialog_content = "『<color=#FFB400>日蝕</color>は、永遠なり…』",
  ui_story_1_10_5_dialog_content = "これがクラーケンの「遺言」？「光霊と空の末裔に負けた」って？",
  ui_story_1_10_6_dialog_content = "ふん、皆殺しにしたと思っていたけど、\nまだ<color=#FFB400>あの時</color>の死に損ないがいたなんて。",
  ui_story_1_10_A2_dialog_content = "私がその空の末裔を、この手で処理してあげようかしら？",
  ui_story_1_10_7_dialog_content = "あら、自分の<color=#FFB400>一族</color>を皆殺しにするのって、そんなに楽しいの？",
  ui_story_1_10_8_dialog_content = "…一族？その言葉を聞いたのは何年ぶりかしら。",
  ui_story_1_10_9_dialog_content = "あなたにはもっと重要な任務があるでしょ。\nこんなことに気を取られている暇はないわよ。",
  ui_story_1_10_10_dialog_content = "私たちが求めているものは、あの巨像内にはない。\n時間を無駄にしないで。それとも、まだ待ち続けたいの？",
  ui_story_1_10_11_dialog_content = "あの空の末裔は、<color=#FFB400>マクガフィン</color>に任せておきなさい。\nちょうど近くにいたはずでしょ？",
  ui_story_1_10_12_dialog_content = "あいつにクラーケンの尻拭いをさせるつもり？",
  ui_story_1_10_13_dialog_content = "マクガフィンならあの光霊どもと十分やりあえるわ。\nそれに、生け捕りにできれば最高じゃない…",
  ui_story_1_10_14_dialog_content = "今の仕事が終わったらすぐに合流させるわ。\nそれよりも、大事な任務を怠らないでちょうだい。",
  ui_story_1_10_A3_dialog_content = "マクガフィンはあなたと違ってよく言うことを聞いてくれるわ。\nちゃんと見習いなさいよ。",
  ui_story_1_10_15_dialog_content = "…ふん。確かに、あっちに比べれば、\n得体のしれない空の末裔なんて、気にする価値もないわね。",
  ui_story_1_10_16_dialog_content = "でも今度また私を見下すようなら、隙を狙ってあんたの首をぶったぎるわ。",
  ui_story_1_10_17_dialog_content = "アハハ…面白いことを言うのね、<color=#FFB400>スーモア</color>。",
  ui_story_1_10_18_dialog_content = "マクガフィン、送ってあげられるのはここまでよ。\nヘマをしたら、どうなるかわかっているでしょうね！",
  ui_story_1_10_19_dialog_content = "無論。マクガフィンに恐れなどございませぬ…",
  ui_story_1_10_21_dialog_content = "ターゲットは前方に。腐り果てた古骨、我らの網をすり抜けていた巨像…\n闇雲に我らの領地でその姿を現すとは。",
  ui_story_1_10_22_dialog_content = "飛び立てないよう、地上に釘で打ちつけ…",
  ui_story_1_10_23_dialog_content = "豚小屋の隅まで捜索し、空の末裔を引きずり出して、\nあのお方に献上いたしましょう！",
  ui_story_1_10_24_dialog_content = "<size=45>母の名において――進め、攻撃だ！</size>",
  ui_story_1_10_25_dialog_content = "あの規模…冗談ですよね…",
  ui_story_1_10_26_dialog_content = "巨像が起動したことにより、我々は敵の視界に自ら飛び込んだも同然です。\n周辺の暗鬼すべてが集まってきています。",
  ui_story_1_10_27_dialog_content = "まぁ、それは避けられないわよね。\nソラヴァンのウォームアップにはまだ時間がかかりそう？",
  ui_story_1_10_B1_dialog_content = "…",
  ui_story_1_10_B2_dialog_content = "PlayerName？",
  ui_story_1_10_B3_dialog_content = "えっ？ああ、ごめん…考え事をしてたんだ。",
  ui_story_1_10_B4_dialog_content = "…確認しておきたいんだけど、ソラヴァンはまだウォームアップの時間が必要よね。",
  ui_story_1_10_28_dialog_content = "残念だけど、そうだね。ソラヴァンを動かすにはもう少し時間が必要だ。\n飛べさえすれば、もう安全だけど。",
  ui_story_1_10_30_dialog_content = "時間稼ぎをお願いします、PlayerName。",
  ui_story_1_10_31_dialog_content = "もうすぐ、みなさんを連れてこの場を離れられます。\n新世界の空、ああ、待ち切れません！",
  ui_story_1_10_32_dialog_content = "ソラヴァンを死守しなきゃ！飛び立ちさえすれば大丈夫だから！",
  ui_story_1_10_33_dialog_content = "オッケー！じゃあ分かれて行動しましょう。\nここにある全ての出入口を守るのよ！",
  ui_story_1_10_34_dialog_content = "PlayerName、あなたはブリッジに残ってちょうだい！",
  ui_story_1_10_35_dialog_content = "今度は「市街戦」さながらのようですね！隊員、集合！",
  ui_story_1_10_A4_dialog_content = "弾込め！この巨像のために時間を稼ぐんだ！",
  ui_story_1_10_36_dialog_content = "啓明の光のために！",
  ui_story_1_10_37_dialog_content = "啓明の光のために！",
  ui_story_1_10_38_dialog_content = "え、何の光だって？",
  ui_story_1_14_1_dialog_content = "『巨像のウォームアップが間もなく完了する！直ちに破壊せよ！！\n巨像を光霊どもの棺にしてやるのだ！』",
  ui_story_1_14_2_dialog_content = "『すでに巨像の至るところに入り込んでいますが、\nブリッジなどで激しい抵抗を受けており、損失が激しく…』",
  ui_story_1_14_3_dialog_content = "『だから何だというのだ？我々は命を惜しむ生物だったか？』",
  ui_story_1_14_4_dialog_content = "『いいえ、喜んで命を捧げます！』",
  ui_story_1_14_5_dialog_content = "『ならば、貴様の爪を良く研いでおくことだ。もう躊躇は許さぬ。』",
  ui_story_1_14_A1_dialog_content = "『たとえ死すとも、倒れる前に敵の腹を裂いてやれ！』",
  ui_story_1_14_6_dialog_content = "『先導せよ。我自ら、その激しく抵抗する光霊とやらの相手をしてくれる…！』",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>巨像内部</color>",
  ui_story_1_14_8_dialog_content = "皆、この隙に休憩を取れ。次の暗鬼が間もなく攻めてくる。\n弾薬を確認し、死傷者の数をまとめろ。",
  ui_story_1_14_9_dialog_content = "報告！弾薬残り11発、参戦6名、軽傷4名、2名は…",
  ui_story_1_14_10_dialog_content = "…ああ、わかった。",
  ui_story_1_14_11_dialog_content = "隊長、撤退しましょう…",
  ui_story_1_14_12_dialog_content = "だめだ！中尉たちは現在、最重要箇所であるブリッジを守っている。\n我々が外で他の暗鬼を牽制しなくては！",
  ui_story_1_14_13_dialog_content = "皆が生きるために必死だ、皆が同じように大変なのだ！\n二度とそのようなことを口にするな、兵士たちよ！",
  ui_story_1_14_14_dialog_content = "全員！気合を入れろ！弾薬が尽きた者は、抜剣せよ！！",
  ui_story_1_15_1_dialog_content = "こいつ――逃がさないから！",
  ui_story_1_15_2_dialog_content = "さすがね！これで、ブリッジの暗鬼もきれいさっぱり片付いたわ！",
  ui_story_1_15_3_dialog_content = "PlayerName、指揮がどんどん手慣れてきたね！",
  ui_story_1_15_4_dialog_content = "今日はテクニックも、頭の「回転速度」も、目に見えて成長したと思う…",
  ui_story_1_15_5_dialog_content = "巨像の他の場所の戦況はどうなんだろう…",
  ui_story_1_15_6_dialog_content = "ソラヴァン、あとどれくらい？",
  ui_story_1_15_7_dialog_content = "エンジンの点火が完了しました。皆さん、しっかりつかまってください。\n<size=45>ソラヴァン、離陸します！</size>",
  ui_story_1_15_8_dialog_content = "飛んだ！？",
  ui_story_1_15_9_dialog_content = "うわっ――振り落とされるところだった…すっごく高い！！今飛んでるの！？",
  ui_story_1_15_10_dialog_content = "みんな、早く何かにつかまって！",
  ui_story_1_15_11_dialog_content = "バイス、それ僕の髪！掴んでるよ！",
  ui_story_1_15_A1_dialog_content = "空！本当に久しぶりです…最後に飛んだのは、血なまぐさい匂いのする夜でした…",
  ui_story_1_15_A2_dialog_content = "PlayerName、さらに加速します。よろしいですね！",
  ui_story_1_15_A3_dialog_content = "もちろん！ソラヴァン、昇り続けて！",
  ui_story_1_15_12_dialog_content = "出力最大で飛ぶんだ！！これなら暗鬼だって全部振り落とせちゃえそうだよ！",
  ui_story_1_15_13_dialog_content = "わかりました！空の一番高い所まで、行きましょう！",
  ui_story_1_15_14_dialog_content = "バイス中尉、この振動は一体！？",
  ui_story_1_15_15_dialog_content = "今連絡しようと思ってたの！飛べたのよ！",
  ui_story_1_15_16_dialog_content = "そうですか…良かった…間に合わないかと…",
  ui_story_1_15_17_dialog_content = "間に合わない？何が起きたの？大丈夫！？",
  ui_story_1_15_18_dialog_content = "巨大な敵に侵入されました！我々は…もうだめです、多くの者が…",
  ui_story_1_15_19_dialog_content = "やつはまっすぐにブリッジに向かっています！\n上級暗鬼に違いありません…申し訳ありません…",
  ui_story_1_15_20_dialog_content = "まさか強敵！？まだ終わってない、みんな警戒して！",
  ui_story_1_15_21_dialog_content = "あれ、なんか急に気温が下がったね？寒い…",
  ui_story_1_15_22_dialog_content = "気温じゃないわ、ドーヴ。これは暗力ね…みんな、敵がすぐ近くにいるわ…",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>突然、悪寒が全員を襲った――</color>",
  ui_story_1_15_25_dialog_content = "使えないやつらめ。棺を飛ばすのには成功したようだが…お前たちはここまでだ。",
  ui_story_1_15_26_dialog_content = "上級暗鬼がもう一匹！？",
  ui_story_1_15_27_dialog_content = "我にも名前があるのだ、光霊。\n<color=#FFB400>マクガフィン</color>と呼ぶがいい。母上から賜った名だ…",
  ui_story_1_15_28_dialog_content = "よく覚えておけ。真理のかなたに到着したあと、\n我が名が貴様らの行く道を照らす明かりとなるだろう！",
  ui_story_1_15_29_dialog_content = "この暗鬼、会話できるの？「母」？「真理」？どういうこと？",
  ui_story_1_15_30_dialog_content = "あんまりそいつと喋っちゃだめ、PlayerName！\n公用語ができる暗鬼はただでさえ少ないのに…。何かおかしいわ！",
  ui_story_1_15_31_dialog_content = "光霊にも導きを与えられるよう、公用語も習得しているのだよ。\nまぁ…聞こうともしない虫けらもいるがな…",
  ui_story_1_15_32_dialog_content = "死にゆく者への手向けのつもりだったが、お喋りがすぎたか。そろそろ――",
  ui_story_1_15_33_dialog_content = "死んでもらうぞ。",
  ui_story_1_15_34_option_content = "死ぬのはお前だ！",
  ui_story_1_15_35_option_content = "みんな、戦闘準備だ！",
  ui_story_1_15_36_dialog_content = "貴様ら…よくも我に傷を…！！もういい！",
  ui_story_1_15_37_dialog_content = "命までは取るまいと思っていたが、\nアリを傷つけずに踏むことの、なんと難しいことか！",
  ui_story_1_15_38_dialog_content = "<color=#FFB400>スーモア様</color>…実に難しい任務をこのマクガフィンにお任せくださいましたな。",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>スーモア</color>！？夢に出てきた名前だ！\nその名前、どこで聞いた？そいつはいったい誰！？",
  ui_story_1_15_40_dialog_content = "空の末裔か。当時の出来事を全く知らぬわけではないようだな…だが、なぜだ？",
  ui_story_1_15_B1_dialog_content = "お前たちの一族は我らの手によって滅びたのだ。\n一人で生き延びたとして、お前は満足なのか？",
  ui_story_1_15_B2_dialog_content = "何…だって？",
  ui_story_1_15_B3_dialog_content = "何を不思議がるのだ。しっかりと聞こえただろう。",
  ui_story_1_15_B4_dialog_content = "お前の一族は、<color=#FFB400>滅びた</color>のだ。",
  ui_story_1_15_B5_dialog_content = "天空ノ谷は、もはや存在しない。",
  ui_story_1_15_B6_dialog_content = "火の海、泣き叫ぶ声、一人ひとり粉々に踏み砕かれ…\nそして打ち捨てられたのだ。",
  ui_story_1_15_B7_dialog_content = "…そ…そんなの、嘘だ。",
  ui_story_1_15_B8_dialog_content = "そんなはず…",
  ui_story_1_15_B9_dialog_content = "黙りなさい、暗鬼！何を知ってるっていうの！？",
  ui_story_1_15_B10_dialog_content = "我はその場にいたのだ。あれほど盛大な血祭りだ。\n<color=#FFB400>我々</color>全員が勢ぞろいした…欠席する者など、いようはずもない。",
  ui_story_1_15_B11_dialog_content = "いつの日か我々は光霊の防衛線を突破し、\n同じように「皆殺しの儀式」を執り行うだろう。",
  ui_story_1_15_41_dialog_content = "PlayerName、暗鬼の言葉なんて信じちゃダメ！",
  ui_story_1_15_42_dialog_content = "信じるか信じないかはどうでもよかろう。お前たちはここで死ぬのだからな。",
  ui_story_1_15_44_dialog_content = "そうはさせん！",
  ui_story_1_15_46_dialog_content = "愚か者め！生きながらえることもできたのに、死に急ぐとは！",
  ui_story_1_15_47_dialog_content = "ぐあ…！！",
  ui_story_1_15_48_dialog_content = "無駄だ。我に踏みつけられるのも貴様の計画のうちだったか？",
  ui_story_1_15_49_dialog_content = "ふ…<color=#FFB400>爆弾</color>だ、バカな怪物め…",
  ui_story_1_15_50_dialog_content = "貴様…！",
  ui_story_1_15_53_dialog_content = "<size=45>私と地獄へ落ちろ、阿呆が！</size>",
  ui_story_1_15_54_dialog_content = "PlayerName！爆弾で穴が開きました。気をつけてください！",
  ui_story_1_15_55_dialog_content = "風圧が！！引きずり出される――！",
  ui_story_1_15_56_dialog_content = "待って！！",
  ui_story_1_15_B13_dialog_content = "隊長！！",
  ui_story_1_15_B14_dialog_content = "近づいちゃだめ、吸い込まれるわ！！私の手を掴んで！",
  ui_story_1_15_B15_dialog_content = "くっ、どうしてこんなことに…あと少しだったのに…！",
  ui_story_1_15_57_dialog_content = "ば…爆発した？あの光霊は、どうして…",
  ui_story_1_15_A4_dialog_content = "ああ、今バラバラになったのは、彼の体…？",
  ui_story_1_15_58_dialog_content = "PlayerName！落ち着いてください！精神状態が不安定です…",
  ui_story_1_15_A5_dialog_content = "記憶の中の…同族たちの体も…",
  ui_story_1_15_A6_dialog_content = "みんな死んだ。<color=#FFB400>全員死んでしまった</color>？天空ノ谷の外は？\n大陸の外は？僕は<color=#FFB400>空の末裔の最後の一人</color>なの？",
  ui_story_1_15_A7_dialog_content = "心拍数が急増しています！さきほどの様にオーバーロードしないよう、注意して下さい！",
  ui_story_1_15_B12_dialog_content = "なんということだ…こんなはずでは。今までの苦労が…",
  ui_story_1_15_A8_dialog_content = "<size=45>ふざけた事を言わないで！！！</size>",
  ui_story_1_15_59_dialog_content = "きょ、巨像が突然加速した！？立っていられない…",
  ui_story_1_15_60_dialog_content = "空の末裔！！貴様一体何を！？だめだ、このままでは…",
  ui_story_1_15_61_dialog_content = "<size=45>違う、嘘だ、こんなの…</size>",
  ui_story_1_15_62_dialog_content = "<size=45>ナビゲーター、かがんで！！</size>",
  ui_story_1_15_63_dialog_content = "グアア…！！！",
  ui_story_2_1_A1_dialog_content = "「巨像がついに飛び立った」",
  ui_story_2_1_A2_dialog_content = "「ついさっきまで、永遠に地底に閉じ込められたままなのだと思っていた」",
  ui_story_2_1_A3_dialog_content = "「でも、すべてが終わった瞬間に…」",
  ui_story_2_1_A4_dialog_content = "「生きている意味がまたなくなってしまった」",
  ui_story_2_1_A5_dialog_content = "「なぜなら、空の末裔は…もはや存在しないのだから」",
  ui_story_2_1_1_dialog_content = "あら？日記を書いていたの？",
  ui_story_2_1_3_dialog_content = "うん。以前からの習慣で、1人で他にすることもなかったしね。",
  ui_story_2_1_4_dialog_content = "日記を書くと時間の感覚を保つことができるんだ。何の役にも立たないけどね…",
  ui_story_2_1_5_dialog_content = "いい習慣じゃないかしら。でも、PlayerNameは、自分に厳しいタイプみたいね…",
  ui_story_2_1_6_dialog_content = "今の状況は？",
  ui_story_2_1_B26_dialog_content = "ピンチからは脱することができたわ。負傷者の手当てもだいたい済んだし。",
  ui_story_2_1_B27_dialog_content = "そういえば…自分を犠牲にした兵士が…",
  ui_story_2_1_B28_dialog_content = "…",
  ui_story_2_1_B29_dialog_content = "もう遺体を回収することはできないけど、お墓は作るつもり。",
  ui_story_2_1_B30_dialog_content = "…",
  ui_story_2_1_B31_dialog_content = "…死を目の当たりにしたのは、初めて？",
  ui_story_2_1_B32_dialog_content = "いいえ。",
  ui_story_2_1_B33_dialog_content = "でもこういうのって、何度経験しても慣れないわ…",
  ui_story_2_1_B34_dialog_content = "あの人に…家族は…いるのかな？",
  ui_story_2_1_B35_dialog_content = "心配しないで。遺族の面倒は啓光連邦がきちんとみるから。",
  ui_story_2_1_B37_dialog_content = "私たちは、啓明の光に身を捧げたすべての人たちを忘れない。",
  ui_story_2_1_B38_dialog_content = "ごめんなさい、PlayerName。",
  ui_story_2_1_B39_dialog_content = "どうして謝るの？",
  ui_story_2_1_B40_dialog_content = "ただ、心の底から申し訳ないと思っているの。だって、今日起きた事はすべて…",
  ui_story_2_1_B41_dialog_content = "…とにかく、生き残った者として今できることは、\n前に進んで彼の死を無駄にしないことだと思うの。",
  ui_story_2_1_F1_dialog_content = "…",
  ui_story_2_1_7_dialog_content = "これからの計画はあるの？",
  ui_story_2_1_8_dialog_content = "…自分でもわからないや。",
  ui_story_2_1_9_dialog_content = "私と…一緒に啓光に行かない？",
  ui_story_2_1_10_dialog_content = "君は…さっきマクガフィンが言ったこと、聞いた？",
  ui_story_2_1_A8_dialog_content = "聞いたわ。でも、あれはあいつがそう言ってたに過ぎないのよ。",
  ui_story_2_1_11_dialog_content = "僕の一族は皆死んでしまった。天空ノ谷は、もはや存在しない。",
  ui_story_2_1_13_dialog_content = "…",
  ui_story_2_1_A9_dialog_content = "君にはまだ帰る場所があって、一族のみんなもいる。でも僕には…",
  ui_story_2_1_14_dialog_content = "…PlayerName、そんな風に考えないで。",
  ui_story_2_1_15_dialog_content = "あなた以外にも、必ず生き延びている空の末裔はいるはずよ！",
  ui_story_2_1_B1_dialog_content = "…",
  ui_story_2_1_B2_dialog_content = "一緒に探しましょう！",
  ui_story_2_1_B3_dialog_content = "ごめん、バイス。僕はただ…",
  ui_story_2_1_B4_dialog_content = "大丈夫よ、分かるわ。",
  ui_story_2_1_B5_dialog_content = "僕は地下に17年も籠もって、ずっと天空ノ谷のことを想像してきたんだ。",
  ui_story_2_1_B6_dialog_content = "それが突然…全部、とっくにないって言われたんだよ？\nこんなのあんまりだ…そう簡単に受け入れられないよ…",
  ui_story_2_1_B7_dialog_content = "受け入れなくていいのよ、PlayerName。",
  ui_story_2_1_B8_dialog_content = "僕…17年前にいったい何が起きたか知りたい！",
  ui_story_2_1_B9_dialog_content = "そうね！大陸中を探して、真実を見つけましょう！",
  ui_story_2_1_B10_dialog_content = "でもその前に、しっかり休まないと。私と一緒に啓光に戻りましょう。",
  ui_story_2_1_A10_option_content = "わかった。それなら一緒に行こう",
  ui_story_2_1_A11_option_content = "いや、僕には僕の道がある",
  ui_story_2_1_A12_dialog_content = "君の言うとおりだよ、バイス。",
  ui_story_2_1_A13_dialog_content = "それに、今の僕には行くあてもないし…",
  ui_story_2_1_A14_dialog_content = "大丈夫よ。きっと啓光のことを気に入るわ。",
  ui_story_2_1_B11_dialog_content = "手がかりと言えば「<color=#FFB400>スーモア</color>」っていう名前だけ…\nでも、それが誰なのかはさっぱり分からない。",
  ui_story_2_1_B12_dialog_content = "思い出すといったって、その顔が繰り返し浮かんでくるだけなんだ。",
  ui_story_2_1_B13_dialog_content = "だからこそ、まず約束して。自分と巨像をきちんとケアするって。",
  ui_story_2_1_B14_dialog_content = "あなたが考えを整理して、ソラヴァンの整備が終わったら…\nあなたと一緒に冒険を続けるわ。",
  ui_story_2_1_A15_dialog_content = "どうして？",
  ui_story_2_1_A16_dialog_content = "え？どうしてって、啓光連邦は…",
  ui_story_2_1_A17_dialog_content = "聞いていいかな？どうして僕なんかと友達になろうとするの？\nそれに、わざわざ助けてくれるなんて。",
  ui_story_2_1_A18_dialog_content = "そんなの、あなたが命の恩人だからに決まってるじゃない！",
  ui_story_2_1_A19_dialog_content = "それと、あなたの能力は光霊にとっては特別なの…",
  ui_story_2_1_A20_dialog_content = "「巨像ナビゲーター」とか言ってた計画のこと？",
  ui_story_2_1_A21_dialog_content = "「巨像の再建とナビゲーター育成」計画ね。",
  ui_story_2_1_A22_dialog_content = "じつは私も…あ、そのことはいいの。",
  ui_story_2_1_A23_dialog_content = "いったい何のことだか分からないけど…",
  ui_story_2_1_F2_dialog_content = "君を信じることにするよ、バイス。",
  ui_story_2_1_A24_dialog_content = "PlayerName…ありがとう。",
  ui_story_2_1_A25_dialog_content = "そうと決まったら、さっさと一番近くの啓光のシェルターを探しましょ。\nゆっくり休まないと…",
  ui_story_2_1_A26_dialog_content = "何年間もずっと、努力してきたんだ。",
  ui_story_2_1_A28_dialog_content = "僕は毎日巨像を再起動しようとして、何度気を失いかけたか分からない。",
  ui_story_2_1_B15_dialog_content = "毎日ソラヴァンからいろいろ教えてもらってたけど、\nそれが何の役に立つのかも分からない。",
  ui_story_2_1_B16_dialog_content = "毎日、外の世界を見ることや、天空ノ谷に帰ることばかり考えてきたんだ。",
  ui_story_2_1_B17_dialog_content = "うん、あなたがすごく頑張ってたのは分かるわ、PlayerName。",
  ui_story_2_1_B19_dialog_content = "だから、僕はひとりで、自分の行きたいところに行くよ。",
  ui_story_2_1_B20_dialog_content = "でも、どこに行くの？",
  ui_story_2_1_B21_dialog_content = "…",
  ui_story_2_1_B22_dialog_content = "家に…天空ノ谷へ帰る。",
  ui_story_2_1_B23_dialog_content = "それから<color=#FFB400>スーモア</color>も探しだす。",
  ui_story_2_1_A29_dialog_content = "PlayerName、一人じゃ危険すぎるわ！",
  ui_story_2_1_A30_dialog_content = "危険は承知の上だよ。けど、僕は真相を知って、家に帰りたいんだ。",
  ui_story_2_1_A31_dialog_content = "あなたとソラヴァンは地上に出たばかりなのに、いろいろありすぎたわ…\n本当に、今は休まないと。",
  ui_story_2_1_A32_dialog_content = "しっかり休んだら、その後は私も手伝うわ…",
  ui_story_2_1_A33_dialog_content = "助けてくれるの？どうして？",
  ui_story_2_1_A34_dialog_content = "そんなの、あなたが命の恩人だからに決まってるじゃない！",
  ui_story_2_1_A35_dialog_content = "それに…あなたの能力は光霊にとっては特別なの。",
  ui_story_2_1_A36_dialog_content = "…",
  ui_story_2_1_A37_dialog_content = "共通の敵に一緒に立ち向かいましょう――昔の光霊と空の末裔みたいに！",
  ui_story_2_1_A38_dialog_content = "でもとりあえずは、早く一番近くの啓光のシェルターを探して、ゆっくり休まないと…",
  ui_story_2_1_19_dialog_content = "わあっ！なに？",
  ui_story_2_1_20_dialog_content = "ソラヴァン、何が起こったの！？",
  ui_story_2_1_21_dialog_content = "巡航システムに複数の損傷箇所が見つかりました。目下修復不能です。",
  ui_story_2_1_22_dialog_content = "17年もメンテナンスを怠ってきたので、さすがに耐えきれなかったようです…\n地上に降下しなければなりません。",
  ui_story_2_1_23_dialog_content = "そして…PlayerName、私はここまでかもしれません。",
  ui_story_2_1_24_dialog_content = "…",
  ui_story_2_1_25_dialog_content = "何が起ころうとも、まずは自分の身を守ってください。\nそして仲間を守ってください。",
  ui_story_2_1_26_dialog_content = "信じています…あなたなら…強く…なれると。",
  ui_story_2_1_A43_dialog_content = "ソラヴァン、ソラヴァン――！",
  ui_story_2_1_27_dialog_content = "PlayerName！！！",
  ui_story_2_1_28_dialog_content = "衝撃に備えて！！",
  ui_story_2_1_29_dialog_content = "強烈な光力の波を感じたわ。",
  ui_story_2_1_30_dialog_content = "スーモア様、すべては依然として我が手中にあります。",
  ui_story_2_1_A44_dialog_content = "お空に放り出された負け犬が。できないことは約束しないほうが身のためよ。",
  ui_story_2_1_A45_dialog_content = "…",
  ui_story_2_1_X1_dialog_content = "あんたはクラーケンよりも強い。そこは認めるわ。\nでも、命令を果たせないのなら…",
  ui_story_2_1_X2_dialog_content = "あんたもただのクズよ、マクガフィン。",
  ui_story_2_1_31_dialog_content = "巨像の庇護も永遠ではありません。\n奴らは無意味にあがいているのみです！",
  ui_story_2_1_32_dialog_content = "すぐにでもお望みの獲物を献上してご覧に入れます。",
  ui_story_2_1_33_dialog_content = "二度目のチャンスを無駄にしないでちょうだいね。\n私の我慢が限界を超える前に片付けなさい。",
  ui_story_2_1_35_dialog_content = "必ずや。",
  ui_story_2_1_36_dialog_content = "『巨像…西方の…荒野に…墜落…』",
  ui_story_2_1_37_dialog_content = "『西方か。それなら<color=#FFB400>黒蹄</color>一族だ…応答せよ！』",
  ui_story_2_1_38_dialog_content = "『はっ！』",
  ui_story_2_1_39_dialog_content = "『奴らを追い、打ち滅ぼすのだ…我も後から向かう！』",
  ui_story_2_1_40_dialog_content = "『黒蹄、拝命いたしました。暗鬼ども、出撃だ！』",
  ui_story_2_2_2_dialog_content = "いった～い…あれ？",
  ui_story_2_2_3_dialog_content = "バイス、僕の上から退いてくれるかな…",
  ui_story_2_2_A1_dialog_content = "え？あ、ごめんなさい…大丈夫？",
  ui_story_2_2_A2_dialog_content = "生きてるには生きてるよ…",
  ui_story_2_2_4_dialog_content = "もう暗鬼に囲まれたの！？早すぎない？",
  ui_story_2_2_5_dialog_content = "PlayerName！！早く、指示を！",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>墜落時の轟音が数匹の暗鬼を呼び寄せてしまったようだ</color>",
  ui_story_2_3_1_dialog_content = "今の状況はどう？",
  ui_story_2_3_2_dialog_content = "バイス中尉、大量の暗鬼が接近中です…こちらは弾薬も何もかも尽きています。",
  ui_story_2_3_3_dialog_content = "ここから一番近いシェルターは？",
  ui_story_2_3_A1_dialog_content = "シェルター28号です。あそこならすぐに避難できます。",
  ui_story_2_3_A2_dialog_content = "バイス中尉、ご命令を！",
  ui_story_2_3_4_dialog_content = "目標、シェルター28号。全員、全速前進よ！",
  ui_story_2_3_6_dialog_content = "PlayerName、行きましょう！",
  ui_story_2_3_7_dialog_content = "僕はいいよ。君たちだけで行って。",
  ui_story_2_3_8_dialog_content = "PlayerName！？",
  ui_story_2_3_A3_dialog_content = "早く撤退したほうがいいよ。ぐずぐずしてたら身動きできなくなるよ。",
  ui_story_2_3_A4_dialog_content = "一緒に来ないの？",
  ui_story_2_3_9_dialog_content = "傷だらけのソラヴァンを、置いてはいけないよ…",
  ui_story_2_3_10_dialog_content = "僕が17年も生きてこられたのはソラヴァンのおかげなんだ。\n今となっては、僕の唯一の「家族」なんだよ。",
  ui_story_2_3_A5_dialog_content = "…",
  ui_story_2_3_11_dialog_content = "マクガフィンが言ってたことが本当なら…",
  ui_story_2_3_12_dialog_content = "…とにかく、僕はもう1歩もソラヴァンから離れない。",
  ui_story_2_3_13_dialog_content = "一人でどうやって暗鬼の群れと戦うの！？",
  ui_story_2_3_A6_dialog_content = "暗鬼たちの目標は僕なんだよね？\n僕が残れば、君たちに害は及ばないはず。",
  ui_story_2_3_14_dialog_content = "！！",
  ui_story_2_3_15_dialog_content = "…分かったわ。あなた、みんなを連れてシェルターへ向かって！",
  ui_story_2_3_A7_dialog_content = "バイス中尉、あなたは…？",
  ui_story_2_3_A8_dialog_content = "時間がないわ、今すぐ出発して！",
  ui_story_2_3_A9_dialog_content = "はっ…はい！",
  ui_story_2_3_A10_dialog_content = "バイス、君にはもう十分助けられた。仲間と一緒に行きなよ。",
  ui_story_2_3_16_dialog_content = "あなただって私の仲間よ。1人で死なせるわけにはいかない！",
  ui_story_2_3_17_dialog_content = "これ以上ここにいたら、2人とも死ぬだけだよ。",
  ui_story_2_3_18_dialog_content = "PlayerName――！！",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_2_3_B3_dialog_content = "バイス！！",
  ui_story_2_3_B4_dialog_content = "さ、さがって！まずは安全な場所に隠れましょう！",
  ui_story_2_3_B5_dialog_content = "こいつら、もう来たの…",
  ui_story_2_3_B6_option_content = "感知を始める",
  ui_story_2_3_B7_dialog_content = "グゥアアアア――！？",
  ui_story_2_3_B8_dialog_content = "仲間って言ったら仲間なの！",
  ui_story_2_3_B9_dialog_content = "バイス…",
  ui_story_2_3_B10_dialog_content = "グアア！！",
  ui_story_2_3_22_dialog_content = "うわあーっ！",
  ui_story_2_3_A11_dialog_content = "痛い！集中できない…",
  ui_story_2_3_F1_dialog_content = "PlayerName、しっかりして！すぐに私が！",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>グオオ！！！</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>反応が間に合わず、バイスは数匹の暗鬼に同時に襲われてしまった――</color>",
  ui_story_2_3_B13_dialog_content = "うああっ！",
  ui_story_2_3_B14_dialog_content = "に、逃げて…隠れる…のよ…",
  ui_story_2_3_B15_dialog_content = "バイス！？",
  ui_story_2_3_24_option_content = "感知を始める",
  ui_story_2_3_25_dialog_content = "ダメだ、気を失ってる…",
  ui_story_2_3_26_dialog_content = "戦わなきゃ…なんとかしなきゃ。このままじゃ…",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>気を失ったバイスを無視して迫ってきた暗鬼たちにとり囲まれてしまった…</color>",
  ui_story_2_3_28_dialog_content = "おいおい。死に物狂いになったって何も解決できやしねぇぜ。\n暗鬼を殺るにはテクってもんが必要なのさ。",
  ui_story_2_3_29_dialog_content = "おい、オマエら、仕事だ！",
  ui_story_2_3_30_dialog_content = "<size=45>盛り上がっていくぜぇ！！</size>",
  ui_story_2_3_31_dialog_content = "了解、兄貴！",
  ui_story_2_3_32_dialog_content = "爆発注意！",
  ui_story_2_3_33_dialog_content = "テンションMAXでいこうゼェェ！",
  ui_story_2_3_34_dialog_content = "オッサン、どきな！そこにいられちゃ邪魔なんだよ！",
  ui_story_2_3_36_dialog_content = "誰！？いったい何をするつもり？",
  ui_story_2_3_37_dialog_content = "あ？見りゃわかんだろ？追いはぎだよ。",
  ui_story_2_3_38_dialog_content = "命は救ってやったんだ。さっさと金目の物を出しな！",
  ui_story_2_3_F2_dialog_content = "ハハハハハ！",
  ui_story_2_3_39_dialog_content = "一応名乗ってやるか。俺は<color=#FFB400>サメヤマ</color>！\n<color=#FFB400>R・W</color>のアタマさ。",
  ui_story_2_3_40_dialog_content = "このビシッとキメてる奴は<color=#FFB400>レジーナ</color>。",
  ui_story_2_3_41_dialog_content = "で、爆弾をいじってる奴は<color=#FFB400>ボンバー</color>。",
  ui_story_2_3_42_dialog_content = "2人で俺の両腕といったところだ。",
  ui_story_2_3_43_dialog_content = "R…W？追いはぎだって？何をするつもり？巨像を狙ってるなら、やめるんだ！",
  ui_story_2_3_44_dialog_content = "このでっかい奴のこと？なんで入れないの？\nそれなら…ぶっぱなして道を開けるか！",
  ui_story_2_3_45_dialog_content = "みんな！運んじゃって！",
  ui_story_2_3_46_dialog_content = "おお！！！ボンバー姉さん万歳！！！",
  ui_story_2_3_47_dialog_content = "ハハハ！まさか巨像とはな。今日は超ツイてるぜ、ハハハ！",
  ui_story_2_3_A12_dialog_content = "野郎ども、さっさと解体しろ。終わったらそのまま運びだせ！",
  ui_story_2_3_48_dialog_content = "わざわざ目の前に落ちてきたんだ、おいしく頂かないとな！",
  ui_story_2_3_49_dialog_content = "ソラヴァンを…巨像を壊さないで！生命維持装置があるんだ…",
  ui_story_2_3_50_dialog_content = "仲間のバイスが怪我をしてる。あの装置が必要なんだ…！",
  ui_story_2_3_51_dialog_content = "…あー、このお嬢ちゃんの傷、見たところ相当キツイな。",
  ui_story_2_3_52_dialog_content = "この制服…啓光か？",
  ui_story_2_3_53_dialog_content = "俺らとそいつら軍人どもとの関係は、お前が思ってるほど良くねぇんだよ…",
  ui_story_2_3_54_dialog_content = "それに、巨像はもう私たちのモノ。\nあの子を助けたければ、別のモノと交換だよ！",
  ui_story_2_3_55_dialog_content = "でもあんた、見るからにお金持ちじゃないよね！\nそのボロっちい服、どれくらい洗ってないの？",
  ui_story_2_3_56_option_content = "もちろんお金はもってる、たくさん！",
  ui_story_2_3_57_option_content = "ふざけないで！",
  ui_story_2_3_58_dialog_content = "正直に言うよ。一番金目のものはこの巨像だ！\n君たちもこんなもの見たことないでしょ！？",
  ui_story_2_3_59_dialog_content = "ふん、巨像ぐらい、見たことあるよ。\nまぁ…私たちのキャンプのと比べると、確かに完全形だね…",
  ui_story_2_3_60_dialog_content = "そうだよ！君たちがこのまま解体したら、巨像の値打ちが下がっちゃう！",
  ui_story_2_3_61_dialog_content = "チェーッ…ほ～んとやりにくいな！\n火力全開で遊べると思ったのに！兄貴、どうする？",
  ui_story_2_3_62_dialog_content = "…",
  ui_story_2_3_63_dialog_content = "こいつの言うことにも一理ある。いったん止めろ。",
  ui_story_2_3_64_dialog_content = "そうそう、早くやめて！",
  ui_story_2_3_65_dialog_content = "…おい、お前。こっちへ来い。",
  ui_story_2_3_66_dialog_content = "教えろよ。何モンだ？",
  ui_story_2_3_67_dialog_content = "…",
  ui_story_2_3_68_dialog_content = "黙ってたって、まぁ大体察しはつくけどな。\nお前のその服、そんなの着てたのは17年前のあいつらだけだ。",
  ui_story_2_3_69_dialog_content = "こんなデカブツ引き連れて、よく今日まで生きてこられたもんだ！",
  ui_story_2_3_70_dialog_content = "僕の一族の事を知ってるの…？",
  ui_story_2_3_71_dialog_content = "あの事件から、そう長くたっちゃいねぇよ、<color=#FFB400>空の末裔</color>サン。\n俺たちはそう忘れっぽくねぇ。",
  ui_story_2_3_72_dialog_content = "僕が誰かも知らないで、おかしなことをしてみろ！どうなっても知らないぞ！\n君たちなんか、こ、怖くないんだからな！",
  ui_story_2_3_73_dialog_content = "…",
  ui_story_2_3_74_dialog_content = "…こいつ、頭打っておかしくなったんじゃない？",
  ui_story_2_3_75_dialog_content = "面白れぇじゃねぇか。\n自分が<color=#FFB400>特別な一族</color>だからって、俺たちを脅すつもりか？",
  ui_story_2_3_76_dialog_content = "分かってんのか？俺たちは極悪非道な強盗だぜ。",
  ui_story_2_3_77_dialog_content = "…僕の一族の事を知ってるの…？",
  ui_story_2_3_78_dialog_content = "おい、頼むぜ。その服にこの巨像、それにその、どうしたらいいかわかりませんってツラ、\nどうやったって大体察しはつくってもんだ。",
  ui_story_2_3_79_dialog_content = "いい値段で売れそうだぜ…",
  ui_story_2_3_80_dialog_content = "う、売る？バイスと同じ光霊なのに、僕の扱いがそんなに変わるの！？",
  ui_story_2_3_81_dialog_content = "誤解すんじゃねぇ、<color=#FFB400>空の末裔</color>サンよ。\n俺たち盗賊にとっちゃ、お前なんて何の価値もねぇ。",
  ui_story_2_3_82_dialog_content = "空の末裔？暗鬼に滅ぼされたっていう、あの種族？",
  ui_story_2_3_B1_dialog_content = "滅ぼされた…",
  ui_story_2_3_B2_dialog_content = "じゃあ、やっぱり17年前の天空ノ谷の襲撃の生存者は他にいないの？",
  ui_story_2_3_83_dialog_content = "ほかにも何か知ってるなら、教えてもらえないかな…",
  ui_story_2_3_84_dialog_content = "悪いが、たった一晩のことだったからな…。\nあっという間に始まって、あっという間に終わっちまった。",
  ui_story_2_3_85_dialog_content = "当時は、俺もまだガキだったしなあ。そんなはっきり覚えてるわけねぇだろ？",
  ui_story_2_3_89_dialog_content = "さぁ、無駄口はここまでだ！空の末裔も巨像も、今は全部俺たちのもんだぜ！",
  ui_story_2_3_90_dialog_content = "あ、あの、バイスは…",
  ui_story_2_3_91_dialog_content = "とっくに<color=#FFB400>生命維持装置</color>で治療してやってるよ！\n俺らは盗賊だ、人殺しじゃねぇ！",
  ui_story_2_3_92_dialog_content = "どうして巨像にそんなに詳しいの…？",
  ui_story_2_3_93_dialog_content = "巨像を持ってんのは、お前たち空の末裔だけじゃねぇよ。\n俺たちR・Wだって「<color=#FFB400>類似品</color>」ぐらいは持ってんだぜ。",
  ui_story_2_3_94_dialog_content = "さ～て、お前たちを買う奴が出て、金がたんまり稼げるまで、\n楽しみに待つとするか――なぁ、空の末裔サンよ！",
  ui_story_2_4_1_dialog_content = "兄貴、暗鬼の一群がこっちに向かって突っ込んできてますぜ。",
  ui_story_2_4_2_dialog_content = "ああ…キリがねぇな。こんな有様で、巨像をどうやって持ちかえりゃいいかな？",
  ui_story_2_4_3_dialog_content = "話は戻るが、PlayerName。\nお前たち、さっきも暗鬼に追われてたんだろ。",
  ui_story_2_4_4_dialog_content = "そうだけど…",
  ui_story_2_4_5_dialog_content = "チッ、面倒ごとに巻きこまれたみたいだな。",
  ui_story_2_4_6_dialog_content = "おい、お前ら、張り切っていくぞ――虫どもがこっちに向かってる！",
  ui_story_2_4_7_dialog_content = "せっかくだ、ついでに伝説の空の末裔の\n「感知能力」とやらを見せて頂こうじゃねぇか？",
  ui_story_2_4_8_dialog_content = "僕の指揮なんて要る…？",
  ui_story_2_4_9_dialog_content = "こんなチャンス、滅多にねぇだろ！\n俺たちにも見せてくれよ、光の軌跡ってやつをさ！",
  ui_story_2_4_10_dialog_content = "敵が来たぞ！準備はいいか、やられんじゃねぇぞ！",
  ui_story_2_8_1_dialog_content = "こいつら、迂回してきやがった。戦術だ、偶然とは思えねぇな。",
  ui_story_2_8_2_dialog_content = "暗鬼の野郎、いつの間にこんな知性を身につけやがった？",
  ui_story_2_8_3_dialog_content = "ボン、お前どう思う？",
  ui_story_2_8_4_dialog_content = "上級暗鬼が裏で指揮してる、とか？",
  ui_story_2_8_5_dialog_content = "おいおい、不吉なこと言わないでくれよ！",
  ui_story_2_8_7_dialog_content = "上級暗鬼…",
  ui_story_2_8_B1_dialog_content = "…おっと、もうこんな時間か？",
  ui_story_2_8_B2_dialog_content = "やっと気づいてくれたか、兄貴！",
  ui_story_2_8_B3_dialog_content = "すまんすまん、空の末裔の力を使って戦うのが気持ちよくってよ。\nすっかり忘れてたぜ…",
  ui_story_2_8_B4_dialog_content = "お前ら、手を止めろ！<color=#FFB400>メシの時間だ</color>！！",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>イヤッッホォオオオウ！！メシだー！</size></anim>",
  ui_story_2_8_SS_dialog_content = "R・W野外料理CG",
  ui_story_2_8_B6_dialog_content = "おい！押すなってば！！兄貴が先だろうが！",
  ui_story_2_8_B7_dialog_content = "ハハハハ！お前らは先に食ってていいぞ！二杯分だけ残しといてくれ！",
  ui_story_2_8_B8_dialog_content = "これは…一体何が起こってるの…？",
  ui_story_2_8_B9_dialog_content = "メシを食うに決まってるだろ。おかしいか？\nお前、今までメシも食ったことねぇのか？",
  ui_story_2_8_B10_dialog_content = "そうじゃなくて、ずいぶん野性味にあふれるというか…",
  ui_story_2_8_B11_dialog_content = "生存本能ってやつよ、PlayerName。\n俺らの生命力を甘く見るんじゃねぇぞ。",
  ui_story_2_8_B12_dialog_content = "食って、飲んでこその命。\n生きるとは、食って飲むってことなり！",
  ui_story_2_8_B13_dialog_content = "兄貴、空の末裔なんかとくっちゃべってると肉がなくなるよ！",
  ui_story_2_8_B14_dialog_content = "兄貴のために<color=#FFB400>トカゲの丸焼き</color>を2本とってあるぜ！！",
  ui_story_2_8_B15_dialog_content = "この空の末裔にくれてやれ。俺は腹が減ってねぇ。",
  ui_story_2_8_B16_dialog_content = "ほら！",
  ui_story_2_8_B17_dialog_content = "…ぼ…僕も別に…",
  ui_story_2_8_B18_dialog_content = "おう、ボウズ。ずいぶん塞ぎこんでるじゃねぇか？",
  ui_story_2_8_B19_dialog_content = "初めて外に出たんだろ？",
  ui_story_2_8_B20_dialog_content = "転げ回ったり、はしゃいだりしたくねぇのか？",
  ui_story_2_8_B21_dialog_content = "なにをクヨクヨしてんだ！",
  ui_story_2_8_B22_dialog_content = "それとも、外の世界より地下のほうがよかったってか？",
  ui_story_2_8_B23_dialog_content = "えっ？",
  ui_story_2_8_B24_dialog_content = "お前の過去なんぞ知ったこっちゃないがな。\n今は巨像もあの嬢ちゃんもいて、何とかなってんだろ？",
  ui_story_2_8_B25_dialog_content = "今だって、その空の末裔の力がなけりゃ、\nお前に分けてやるメシだって無かったところだ。",
  ui_story_2_8_B26_dialog_content = "この世の中、みんな苦労して生きてんだ。\nそんなことも分からねぇようじゃ、お前は大したバカだ。",
  ui_story_2_8_B27_dialog_content = "いっそ、役に立たねぇバカなら、殺っちまうか？\n連れてきゃぁ面倒ばっかだろうからな。",
  ui_story_2_8_B28_dialog_content = "ぼ、僕を殺したら、もっと面倒なことになるよ。\nけ、啓光が許さないよ！",
  ui_story_2_8_B29_dialog_content = "ハハハハハっ！",
  ui_story_2_8_B30_dialog_content = "何がおかしいの？",
  ui_story_2_8_B33_dialog_content = "思ったよりバカじゃねぇみたいだな。それでいい！",
  ui_story_2_8_8_dialog_content = "見つけたぞ！空の末裔！",
  ui_story_2_8_9_dialog_content = "<color=#FFB400>黒蹄</color>だと！？",
  ui_story_2_8_B34_dialog_content = "暗鬼！やっぱり僕を狙ってる！？",
  ui_story_2_8_B35_dialog_content = "茶碗を置け、陣形を整えろ、戦闘準備だ！",
  ui_story_2_8_10_dialog_content = "人のメシの時間を邪魔するとは、ふてぇ奴だ。",
  ui_story_2_8_B36_dialog_content = "きっちり教えてやろうじゃねぇか、基本のマナーってやつをよ！",
  ui_story_2_8_11_dialog_content = "想像してたよりキツイぜ…",
  ui_story_2_8_12_dialog_content = "この<color=#FFB400>列車</color>…",
  ui_story_2_8_13_dialog_content = "まさか<color=#FFB400>あいつ</color>じゃないだろうな…",
  ui_story_2_8_14_dialog_content = "たいした狼狽ぶりだ、サメヤマ君。",
  ui_story_2_8_15_dialog_content = "暗鬼とおままごとでもしているのかね？",
  ui_story_2_8_16_dialog_content = "やっぱりてめぇか。\n軍人さんよ、あんたんとこの食糧なんざ、ここんとこ頂いてねぇぞ。",
  ui_story_2_8_17_dialog_content = "私は啓光の仲間を迎えに来たまでのこと。\n食糧の件はまた今度ケリを付けさせてもらおう。",
  ui_story_2_8_18_dialog_content = "お？あのお嬢ちゃんのことか？",
  ui_story_2_8_19_dialog_content = "そいつぁちょうどいい。ついさっき、送り返そうと考えてたとこだ。",
  ui_story_2_8_20_dialog_content = "彼女だけではない。この巨像も<color=#FFB400>啓光連邦</color>の財産だ。",
  ui_story_2_8_21_dialog_content = "調子に乗るんじゃないよ、白髪の化け物め！",
  ui_story_2_8_22_dialog_content = "その列車、吹き飛ばされたいの？",
  ui_story_2_8_23_dialog_content = "カッとなるな、ボン！",
  ui_story_2_8_24_dialog_content = "こいつはさっきの黒蹄よりも、相当厄介な相手だぜ。",
  ui_story_2_8_25_dialog_content = "たかが巨像だ。解体もできねぇ、売ることもできねぇじゃ、そう価値もねぇ。",
  ui_story_2_8_26_dialog_content = "ふん！運が良かったね！",
  ui_story_2_8_B37_dialog_content = "カロン、せいぜい巨像と空の末裔を大事にしてやるんだな。",
  ui_story_2_8_B38_dialog_content = "PlayerName、お前は思ってたよりおもしれぇヤツだ。",
  ui_story_2_8_B39_dialog_content = "えっ？",
  ui_story_2_8_B40_dialog_content = "ったく、惜しいぜ！せっかくレアなお宝を見つけたってのに。",
  ui_story_2_8_B41_dialog_content = "PlayerName、暗い気分がまだ晴れてねぇようだが…",
  ui_story_2_8_B42_dialog_content = "お前には光のオーラがみなぎってるぜ。",
  ui_story_2_8_B43_dialog_content = "光のオーラ？でも僕は光の力を使えないし…",
  ui_story_2_8_B44_dialog_content = "チッ、例えだよ、例え！",
  ui_story_2_8_B48_dialog_content = "年を取った人って、みんな難しい話し方をするんだね。",
  ui_story_2_8_B49_dialog_content = "ハハハッ、軽口を叩けるようになったんだな。\n少しは元気が出てきたみてぇじゃねぇか。",
  ui_story_2_8_B50_dialog_content = "いいか空の末裔、死ぬのは簡単だ。\nだが、生きてる以上は、しっかり生きろ！",
  ui_story_2_8_B51_dialog_content = "「<color=#FFB400>希望</color>」ってやつは、探せばきっと見つかるもんだ。",
  ui_story_2_8_B52_dialog_content = "真昼間だろうが、闇夜だろうがな…",
  ui_story_2_8_B53_dialog_content = "そんな言葉の使い方、いつの間に学んだのだね？",
  ui_story_2_8_B54_dialog_content = "んー…どこで読んだか忘れちまったな。",
  ui_story_2_8_B55_dialog_content = "なんと…しばらく顔を見ないと思っていたら、読書とは。",
  ui_story_2_8_B56_dialog_content = "ハハハハ！俺らみたいな流れ者のたくましさを甘く見るなよ！それじゃまたな！",
  ui_story_2_8_28_dialog_content = "直感ってやつかな。お前とはまた会う気がするぜ…",
  ui_story_2_8_29_dialog_content = "野郎ども、引きあげるぞ！今日の苦労に免じて、今夜はサンドワームのご馳走だ！",
  ui_story_2_8_31_dialog_content = "…お前、少しはいい知らせを持ってこられないの、マクガフィン？",
  ui_story_2_8_32_dialog_content = "啓光の増援が到着しまして…<color=#FFB400>カロン</color>という光霊です…",
  ui_story_2_8_33_dialog_content = "カロン？懐かしい名だわ。",
  ui_story_2_8_34_dialog_content = "それって、空の末裔も連れ去られたっていうこと？",
  ui_story_2_8_35_dialog_content = "奴らは<color=#FFB400>シェルター28号</color>へ向かいました。",
  ui_story_2_8_36_dialog_content = "少なくとも、黒蹄がターゲットの位置はつかんでいるようね？\nそれなら次は…何をすべきかわかっているでしょう。",
  ui_story_2_8_37_dialog_content = "はっ！仰せのままに！",
  ui_story_2_8_38_dialog_content = "光霊のシェルター…",
  ui_story_2_8_39_dialog_content = "ネズミどもめ。穴の中に隠れれば安全とでも思っているのか？",
  ui_story_2_8_40_dialog_content = "せいぜい後悔するがいい。腰を抜かして…そんなところに逃げ込むなどと――",
  ui_story_2_8_41_dialog_content = "全ての者を道連れにする覚悟をしておくのだな！",
  ui_story_2_9_1_dialog_content = "君は…誰？",
  ui_story_2_9_2_dialog_content = "私は<color=#FFB400>シェルター28号補給部</color>の管理責任者だ。",
  ui_story_2_9_3_dialog_content = "カロンと呼んでくれたまえ。",
  ui_story_2_9_4_dialog_content = "バイスはどこかね？",
  ui_story_2_9_5_dialog_content = "巨像の生命維持装置にいるよ。バイスは怪我をしてるんだ。\n僕が…僕が守ってあげられなかったから。",
  ui_story_2_9_6_dialog_content = "それで、君って、バイスの上司…？",
  ui_story_2_9_7_dialog_content = "うむ。今回の探索については、バイスから事前に報告を受けていた。",
  ui_story_2_9_8_dialog_content = "その後、巨像の救難信号が見えたのでね。\n暗鬼の後を追っていたら、君たちを見つけたのだよ。",
  ui_story_2_9_9_dialog_content = "バイスの状態は？",
  ui_story_2_9_10_dialog_content = "巨像の生命維持装置を使っているから、容態は落ち着いてるよ。",
  ui_story_2_9_11_dialog_content = "でも、これからどうすれば…？",
  ui_story_2_9_12_dialog_content = "君は実に質問が多いな。\nまずは私についてシェルター28号に戻るがよかろう。",
  ui_story_2_9_13_dialog_content = "カロン長官、お帰りなさいませ！",
  ui_story_2_9_14_dialog_content = "うわぁ…大きいですね。何を持ち帰ってこられたんですか？",
  ui_story_2_9_15_dialog_content = "早く交通班に知らせてカロン長官の専用線路を開けろ。",
  ui_story_2_9_17_dialog_content = "カロン長官、お帰りなさい。",
  ui_story_2_9_18_dialog_content = "これは…巨像ですね！？",
  ui_story_2_9_19_dialog_content = "ああ、巨像の中に怪我人がいる。医療班に知らせるように。",
  ui_story_2_9_20_dialog_content = "それから、啓光の一部隊が…犠牲になった。",
  ui_story_2_9_21_dialog_content = "了解しました！すぐに事後処理業務と隊員補充の配属調整を行います。",
  ui_story_2_9_22_dialog_content = "うむ。頼んだぞ。",
  ui_story_2_9_23_dialog_content = "前線の状況はどうだ？",
  ui_story_2_9_24_dialog_content = "異常ありません！",
  ui_story_2_9_25_dialog_content = "そんなはずはあるまい…\nならば、あれほど大規模な暗鬼の群れがどうやって前線をすり抜けたというのだ？",
  ui_story_2_9_26_dialog_content = "通信班に<color=#FFB400>カナン本部</color>へつなぐよう伝えろ。\n少ししたら本部と話す。",
  ui_story_2_9_B1_dialog_content = "…",
  ui_story_2_9_B2_dialog_content = "どうだ？これほど巨大な地下空間と、社会組織を見たのは初めてかね？",
  ui_story_2_9_B3_dialog_content = "ここが…啓光なの？",
  ui_story_2_9_B4_dialog_content = "ここは啓光連邦が持つシェルターの一つに過ぎん。番号は28。",
  ui_story_2_9_B5_dialog_content = "シェルター28号は暗鬼と戦うための最前線でこそないが、\n後方支援の拠点として不可欠なのだ。",
  ui_story_2_9_F1_dialog_content = "ここが陥落すれば、暗鬼はこちらの防衛線を突破し、直接…",
  ui_story_2_9_B6_dialog_content = "…空の末裔、君は地理を学んだことがあるかね？",
  ui_story_2_9_F2_dialog_content = "す、少しだけ。防衛線が突破されたら、\n暗鬼が大陸の奥地にまで入り込むってことだよね？",
  ui_story_2_9_B7_dialog_content = "その通り！一面は白夜、もう一面は極夜。この大陸は私たちが生きられる唯一の場所だ。\n撤退の余地はどこにもない。",
  ui_story_2_9_B8_dialog_content = "私たちは啓光の者として生まれた以上、暗鬼と戦わねばならない。\nこれは宿命であり、使命なのだ。",
  ui_story_2_9_B9_dialog_content = "大事な故郷を守るために…",
  ui_story_2_9_B10_dialog_content = "故郷って…光霊の土地のこと？",
  ui_story_2_9_B11_dialog_content = "正確に言えば、すべての<color=#FFB400>大切なもの</color>が存在する場所だ。",
  ui_story_2_9_B13_dialog_content = "それは光霊のことかもしれないし、遺跡のことかもしれない。\nはたまた「取るに足らない」思い出のこともあるかもしれない。",
  ui_story_2_9_B14_dialog_content = "意外と…ロマンチックなんだね。",
  ui_story_2_9_B15_dialog_content = "ロマンチック？\n私はそれこそ、生きていくための最も現実的な動力源だと思うがね。",
  ui_story_2_9_B16_dialog_content = "言い換えれば、それは「<color=#FFB400>希望</color>」だ！",
  ui_story_2_9_B17_dialog_content = "絶望を変えられないなら、希望でその永遠の闇夜を満たすまで。",
  ui_story_2_9_B18_dialog_content = "む、思わぬところで、良い詩ができたな…",
  ui_story_2_9_B19_dialog_content = "…サメヤマが言ってたことと、似てる。",
  ui_story_2_9_B20_dialog_content = "あまり元気がないようだな。これからどうするつもりだね？休むか？",
  ui_story_2_9_B21_dialog_content = "それとも君の仲間を、探しにいくか？",
  ui_story_2_9_B22_dialog_content = "仲間…？僕の一族はもう…",
  ui_story_2_9_B23_dialog_content = "私が言ったのは光霊のことだ。彼女たちは君の仲間ではないのかね？",
  ui_story_2_9_B24_dialog_content = "あ…そ、そうだね。僕を助けてくれたんだから…",
  ui_story_2_9_B25_dialog_content = "少し考えを整理する必要がありそう。\n今日はあまりにも色々なことが起こりすぎて…",
  ui_story_2_9_B26_dialog_content = "ふむ、ならば一人にしてあげよう。\n私はまだ日課の報告業務が残っているので、失礼するよ。",
  ui_story_2_9_B27_dialog_content = "意外とアッサリしてる…？",
  ui_story_2_9_B28_dialog_content = "ロマンチストの詩人でも、担うべき業務計画があるのでね。",
  ui_story_2_9_B30_dialog_content = "それから、あまり自分を責めないでおきたまえ。",
  ui_story_2_9_B31_dialog_content = "あの啓光衛兵たちが死んだのは、使命を遂行するためだ。\n君を救おうとしたことだけが原因じゃない。",
  ui_story_2_9_27_dialog_content = "…これで、少しは気を楽にしてくれるといいのだが。",
  ui_story_2_9_28_dialog_content = "…",
  ui_story_2_9_29_dialog_content = "そ…空の末裔？あなたのことは、そうお呼びすればよろしいですか？\n休憩室はこちらです。",
  ui_story_2_9_30_dialog_content = "ついてきてください。こんなことは初めてですが、\nカロン長官が連れて帰られた人であれば大丈夫でしょう。",
  ui_story_2_9_32_dialog_content = "ようこそ、シェルター28号へ。",
  ui_story_2_9_33_dialog_content = "シェルター28号、カナンに応答願う。\nこちらはカロン、重要な報告あり。",
  ui_story_2_9_34_dialog_content = "こちらカナンの<color=#FFB400>ヒイロ</color>。",
  ui_story_2_9_35_dialog_content = "合言葉を。",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>「超イケメンの列車使い」</color>。",
  ui_story_2_9_37_dialog_content = "ヒイロ、今日は君が当番だったか。",
  ui_story_2_9_38_dialog_content = "そちらも、合言葉を。",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>「櫻満開」</color>…",
  ui_story_2_9_41_dialog_content = "バイスの任務に進展はありましたか？",
  ui_story_2_9_42_dialog_content = "まさにそのことを話そうと思ってね。",
  ui_story_2_9_43_dialog_content = "巨像が見つかった。すでにシェルター28号へ回収している。",
  ui_story_2_9_44_dialog_content = "バイスは負傷して、現在治療中だ。",
  ui_story_2_9_45_dialog_content = "負傷？重傷ですか？",
  ui_story_2_9_46_dialog_content = "そう慌てるな、命に別条はないし、後遺症もあるまい。",
  ui_story_2_9_47_dialog_content = "カロン、あなたは一時的にではありますが、彼女の上司です。\nこの責は負ってもらわねばなりません。",
  ui_story_2_9_48_dialog_content = "何が起こったのですか？説明してください。",
  ui_story_2_9_49_dialog_content = "バイスの推測は当たっていた。",
  ui_story_2_9_50_dialog_content = "17年前天空ノ谷を離れた巨像の中の一体が、\n確かにシェルター28号の近くに墜落していた。",
  ui_story_2_9_51_dialog_content = "バイスたちは大量の暗鬼と遭遇したが、\n暗鬼どもも、その巨像を追跡していたようだ。",
  ui_story_2_9_52_dialog_content = "巨像を発見した時点で、バイスから支援要請はなかったのですか？",
  ui_story_2_9_F3_dialog_content = "救難信号はあったが、向かった時には…",
  ui_story_2_9_53_dialog_content = "出遅れたのですか？",
  ui_story_2_9_54_dialog_content = "ヒイロ、話は最後まで聞きたまえ。複雑な状況だったのだ。",
  ui_story_2_9_55_dialog_content = "巨像は地中に埋まっていた。それに…これは君でも予想できまい。\n中に空の末裔の生き残りがいたのだよ。",
  ui_story_2_9_57_dialog_content = "空の末裔？",
  ui_story_2_9_58_dialog_content = "つまり、その空の末裔は地下で17年間、暮らしていたということですか…",
  ui_story_2_9_60_dialog_content = "それから？",
  ui_story_2_9_61_dialog_content = "その時、バイスは巨像から救難信号を出したのだがね。",
  ui_story_2_9_62_dialog_content = "すぐに向かったが、着いた時には暗鬼の痕跡だらけだった。",
  ui_story_2_9_63_dialog_content = "あとで空の末裔に聞いたことだが、クラーケンとマクガフィン、\nそれから黒蹄と交戦したそうだ。",
  ui_story_2_9_64_dialog_content = "上級暗鬼が三匹も？",
  ui_story_2_9_65_dialog_content = "啓光の防衛線を越え、シェルター28号の近くまで潜入していたと？",
  ui_story_2_9_66_dialog_content = "クラーケンは防衛線の下を潜り抜ける能力をもっている。\nが、他の暗鬼にそれはできん。",
  ui_story_2_9_67_dialog_content = "しかも、その他にも膨大な数の低級暗鬼を引き連れていた。",
  ui_story_2_9_68_dialog_content = "まるで空から降ってきたとでもいうのか、やってきた時の痕跡が見つからない。\n17年前の天空ノ谷と一緒だ。",
  ui_story_2_9_69_dialog_content = "暗鬼が防衛線を越える手段を身につけた、と？",
  ui_story_2_9_70_dialog_content = "おそらくそうだろう…",
  ui_story_2_9_71_dialog_content = "それと、マクガフィンはまだ生きているかもしれない。\nもう一つの懸念事項だ。",
  ui_story_2_9_72_dialog_content = "わかりました。すぐに大元帥様に伝えます。",
  ui_story_2_9_73_dialog_content = "あなた達も警戒を徹底してください。",
  ui_story_2_9_74_dialog_content = "シェルター28号は前線への補給線として、とても重要です。\nそこの物資は…",
  ui_story_2_9_75_dialog_content = "ヒイロ、何をすべきかはわかっているつもりだ。",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>数日後・巨像の修理場</color>",
  ui_story_2_9_77_dialog_content = "やっぱりここにいたのね。",
  ui_story_2_9_78_dialog_content = "バイス！？怪我は大丈夫？もう動けるようになったの！？",
  ui_story_2_9_79_dialog_content = "啓光の医療技術を甘く見ちゃだめよ。",
  ui_story_2_9_80_dialog_content = "ソラヴァンは？",
  ui_story_2_9_81_dialog_content = "もう大丈夫。啓光の科学技術レベルには驚きだよ。\nたった数日で壊れていたユニットが全部直っちゃった。",
  ui_story_2_9_82_dialog_content = "今は技術者の人たちが仕上げのメッキ工程を進めてるよ。\n僕はそこまでする必要はないと思うけど…",
  ui_story_2_9_83_dialog_content = "あと、あのすごく目立つ啓光のロゴを落としてもらえたらもっといいかな…",
  ui_story_2_9_84_dialog_content = "啓光の科学技術者たちに、ここまで実力があるとは思っていませんでした…\n私に代わって、バイスにお礼を言っておいてください。",
  ui_story_2_9_87_dialog_content = "当たり前よ。啓光の科学班はいつだって精進、最高を目指してきたんだもの。",
  ui_story_2_9_88_dialog_content = "ほら、私のこの制服と武器も科学班の傑作なのよ。\nこれがないと私はまともに戦えないの。",
  ui_story_2_9_89_dialog_content = "「エンジニアリングされた」光力装置で光霊自身の力を調節、励起することができるのよ。",
  ui_story_2_9_90_dialog_content = "こうすると運用効率と技の起動速度の面で\n「儀式化」されたものにはない優位性を発揮できるの。",
  ui_story_2_9_91_dialog_content = "ただ、そっちに比べると威力がだいぶ下がってしまうけど。\nそれでも集団戦スタイルには比較的適しているのよ。",
  ui_story_2_9_A1_dialog_content = "…",
  ui_story_2_9_A2_dialog_content = "…",
  ui_story_2_9_A3_dialog_content = "あ、何かわからないことがあった？",
  ui_story_2_9_A4_dialog_content = "…うん、ほとんど全部。",
  ui_story_2_9_A5_dialog_content = "え？全部？…ごめん、あなたがそういうことに詳しくないって忘れてた…",
  ui_story_2_9_A6_dialog_content = "ああ、えっと…そんなことより…",
  ui_story_2_9_A7_dialog_content = "バイス、僕たちが墜落して…あのとき…",
  ui_story_2_9_98_dialog_content = "なんというか…ええと…",
  ui_story_2_9_99_dialog_content = "とにかく――ごめん！",
  ui_story_2_9_100_dialog_content = "え？どうして突然謝るの？",
  ui_story_2_9_101_dialog_content = "あの時、自分勝手なことばかり言って、そのせいで君に怪我をさせてしまったよね。\nここ数日、ずっと悪夢に見るほど後悔してたんだ…",
  ui_story_2_9_102_dialog_content = "ああ、そんなこと？それなら謝る必要なんて全くないわ。",
  ui_story_2_9_103_dialog_content = "あの時の私は、まだあなたとソラヴァンの絆を理解できていなかったの…\n軽々しくあんな提案をした私が悪かったんだわ。",
  ui_story_2_9_104_dialog_content = "あなたがあそこに留まって、しかも1人で暗鬼に立ち向かうことになるって思ったら、\n私も焦っちゃって。",
  ui_story_2_9_105_dialog_content = "まぁ、結果オーライよ！",
  ui_story_2_9_107_dialog_content = "これからもよろしくね、PlayerName。",
  ui_story_2_9_108_dialog_content = "うん！",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ…</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>震動は徐々に強くなってくる…どうやら足元からのようだ</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>その時、かすかな震動が起こった</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>震動は徐々に強くなってくる…どうやら足元からのようだ</color>",
  ui_story_2_9X_3_dialog_content = "何かおかしいな…",
  ui_story_2_9X_4_dialog_content = "…何が震えているの？ソラヴァンかな？",
  ui_story_2_9X_5_dialog_content = "いや、これは絶対に違う！僕が感知してみるよ。",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>ボン――ボン――ドカンッ！</color>",
  ui_story_2_9X_7_dialog_content = "この警報は…防衛網に穴が！？そんなはずない！\n100%正常だったはずよ。一体、どこから…？",
  ui_story_2_9X_8_dialog_content = "バイス！防衛…穴が…攻撃を受けている！！君たち……",
  ui_story_2_9X_9_dialog_content = "何ですか？カロン長官、よく聞こえません！",
  ui_story_2_9X_19_dialog_content = "バイス！暗鬼を感知した！",
  ui_story_2_9X_20_dialog_content = "暗鬼？このシェルターで！？そんなはずは！",
  ui_story_2_9X_21_dialog_content = "3匹…10匹…まだ増えてる。バイス、暗鬼がどんどん増え続けてるよ！！",
  ui_story_2_9X_22_dialog_content = "さっきの震動も絶対に変だ！もしかしたらこのシェルターはもう…",
  ui_story_2_9X_23_dialog_content = "それなら、引き返しましょう！\n本当に暗鬼に侵入されたんだったら、居住区の前で止めないと！！",
  ui_story_2_9X_24_dialog_content = "戦闘準備よ、PlayerName！",
  ui_story_2_9X_25_dialog_content = "任せて！",
  ui_story_2_9X_26_dialog_content = "いけ…やってしまえ…見えるものすべてを粉々に切り刻め…",
  ui_story_2_9X_27_dialog_content = "もはや失敗は許されない…何としても光霊の骨と血で屈辱をすすがねば！",
  ui_story_2_9X_28_dialog_content = "<size=45>このシェルター全てを葬るのだ！！</size>",
  ui_story_2_10_19_dialog_content = "バイス、PlayerName！",
  ui_story_2_10_20_dialog_content = "カロン長官、御無事でしたか！",
  ui_story_2_10_21_dialog_content = "バイス？？",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>シェルターの防衛網が破られた</color>…直接砦を攻められるとは、前代未聞の事態だ！",
  ui_story_2_10_23_dialog_content = "それになぜ襲撃を仕掛けてきたのだ？組織的に、シェルターの弱点を突いて？",
  ui_story_2_10_24_dialog_content = "おかしい。何かあるに違いない…\nシェルターがこのような事態になったことは、長きにわたってなかった！",
  ui_story_2_10_25_dialog_content = "どうしますか！？戦力はあとどれくらいだろう…？\n取り急ぎ、侵入口に集結しますか？",
  ui_story_2_10_26_dialog_content = "避難を開始させよう。大量の暗鬼が我々の虚を突いて入り込んでいる。\n啓光の規定において、すでにSレベル相当の脅威だ。ここを放棄するほかないだろう。",
  ui_story_2_10_27_dialog_content = "…申し訳ありません。予見できなかったなんて…",
  ui_story_2_10_28_dialog_content = "しっかりしろ、バイス。負傷者と非戦闘員を連れて撤退だ！",
  ui_story_2_10_29_option_content = "もうそんなに切迫した状況なの！？",
  ui_story_2_10_30_option_content = "反撃はできないの…？",
  ui_story_2_10_31_dialog_content = "周りを見てみろ！シェルター28号は戦闘の前線ではない。\nここにいるのは怪我人と補給部の兵士ばかりだ！",
  ui_story_2_10_32_dialog_content = "力を温存し、まずは別のシェルターに避難することこそ得策だ！",
  ui_story_2_10_33_dialog_content = "現在の状況は？",
  ui_story_2_10_34_dialog_content = "どこもかしこも暗鬼だらけ、しかも上級暗鬼までいるようだ…\nいずれにせよ、ここにはいられない！",
  ui_story_2_10_A1_dialog_content = "マクガフィンだ…",
  ui_story_2_10_35_dialog_content = "そう経たないうちに、このシェルターは暗鬼の巣窟となるだろう！",
  ui_story_2_10_36_dialog_content = "了解しました！PlayerName、\n私たちにはあなたの導きが必要よ。みんな一緒に避難するの！",
  ui_story_2_10_40_dialog_content = "よし、絶対、誰も見捨てない！",
  ui_story_2_10_41_dialog_content = "その通りだ。同胞を1人として見捨てはしない！\n華麗に撤退といこうではないか！！",
  ui_story_2_10_42_dialog_content = "さぁ、もたもたしてられないわ！",
  ui_story_2_10_43_dialog_content = "そうだ、その調子だ！！光霊に息つく暇も与えるな！\n巨像と空の末裔の居場所がわかり次第――",
  ui_story_2_10_44_dialog_content = "<size=45>すぐに知らせろ！</size>",
  ui_story_2_12_3_dialog_content = "汚れた醜い生き物め！暗い物陰で大人しくしていれば良かったものを！",
  ui_story_2_12_4_dialog_content = "なぜこの美しいシェルターを滅茶苦茶にするのだ！？まったく、考えられん！！",
  ui_story_2_12_5_dialog_content = "ウォオオオ――！",
  ui_story_2_12_6_dialog_content = "答えは得られまいな！",
  ui_story_2_12_7_dialog_content = "このままでは、私たちより先に暗鬼が居住区に到着してしまいます！",
  ui_story_2_12_8_dialog_content = "カロン長官、列車はどこに？あれは使えませんか？",
  ui_story_2_12_9_dialog_content = "ここには彼岸号が通れる線路がない。",
  ui_story_2_12_10_dialog_content = "それに、奴を呼びだしたら、助けるどころか死体が残っただけでも万々歳だろう。",
  ui_story_2_12_11_dialog_content = "最後の最後までは…",
  ui_story_2_12_12_dialog_content = "こいつら…本当に我々の知っている暗鬼か？\nなぜこんなにも…組織的に、目的を持って攻撃してくるのだ？",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>まるで何かを狙っているような…</color>",
  ui_story_2_12_14_dialog_content = "…",
  ui_story_2_12_15_dialog_content = "ああ、ターゲットは空の末裔か？厄介ごとを引き受けてしまったようだな…",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>シェルターが再び狂ったように震動し始めた</color>",
  ui_story_2_12_17_dialog_content = "認めたくはないけど、私たち絶体絶命みたいね？",
  ui_story_2_12_18_dialog_content = "まだ希望はある。僕たちの奥の手はまだ出してない！",
  ui_story_2_12_19_dialog_content = "PlayerName、あなたまさか…",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>ソラヴァン</color>さ！",
  ui_story_2_12_24_dialog_content = "この前私とPlayerNameでやったみたいに、脱出するのね！",
  ui_story_2_12_25_dialog_content = "やっこさんはエネルギーの充電中だが、まだ充電は終わっていないだろう。",
  ui_story_2_12_26_dialog_content = "だとしても試すしかありません。違いますか？\nそれに、私たち全員を乗せてここから逃げ出せます…",
  ui_story_2_12_X26_dialog_content = "行きましょう。今はもう運命をソラヴァンに委ねるしか手はありません。",
  ui_story_2_12_27_dialog_content = "こういう「緊急指令」にはもう慣れました。しかし急いでください。",
  ui_story_2_12_X27_dialog_content = "暗鬼の気配が…こちらへ近づいています…",
  ui_story_2_12_28_dialog_content = "もう他に手立てはあるまい。皆が巨像に搭乗できるよう、私が手配をしよう。",
  ui_story_2_12_29_dialog_content = "では私たちは先に、巨像を起動しておきます！",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>地下停泊ポート・巨像ソラヴァンの周辺</color>",
  ui_story_2_13_2_dialog_content = "どんどん増えています…",
  ui_story_2_13_3_dialog_content = "フー…グフゥ…",
  ui_story_2_13_4_dialog_content = "やっぱり！巨像のところにも暗鬼が集まり始めてる！",
  ui_story_2_13_5_dialog_content = "ウ…",
  ui_story_2_13_6_dialog_content = "あれは…信号を出しているの？遠くの仲間と連絡を取り合っている…？",
  ui_story_2_13_7_dialog_content = "それより！みんな先に巨像に入って！怪我人と子どもが先よ！私たちが援護するから！",
  ui_story_2_13_8_dialog_content = "どうやら列車は必要なさそうだ…今日は華やかなカーテンコールができると思っていたが。",
  ui_story_2_13_9_dialog_content = "仕方ない。これで楽しませてもらうとするか。",
  ui_story_2_13_10_dialog_content = "リモコン…？一体何の？",
  ui_story_2_13_11_dialog_content = "…<color=#FFB400>赤いボタン</color>？いつの間に…",
  ui_story_2_13_12_dialog_content = "S級の避難において標準とされる手順だ。\nすべての痕跡を抹消する。その時は、とても美しい花火が見られるぞ。",
  ui_story_2_13_13_dialog_content = "しかしやはり、少々名残惜しいな…何と言っても、このシェルターとは長い付き合いだ。",
  ui_story_2_13_14_dialog_content = "「シェルター28号管理責任者」…ああ、結局守り切れなかったな。\n晩節を汚した、といったところか？",
  ui_story_2_13_15_dialog_content = "申し訳ありません…",
  ui_story_2_13_16_dialog_content = "なぜ謝る？君たちがわざと暗鬼を引き入れたとでもいうのかね？",
  ui_story_2_13_17_dialog_content = "違います！",
  ui_story_2_13_18_dialog_content = "落ち着け、バイス…冗談だ。",
  ui_story_2_13_19_dialog_content = "シェルター28号の命運は尽きた、それだけだ。誰の責任でもない。",
  ui_story_2_13_20_dialog_content = "きっと…万事万物にそれぞれの終わり方があるのだろう…",
  ui_story_2_13_21_dialog_content = "白夜と極夜にも必ずや終わりが来るように…\nおぉ、知らぬ間に素晴らしい詩ができてしまった！",
  ui_story_2_13_22_dialog_content = "ほら、何をもたもたしている。まだ行かないのか？\n赤いボタンを押した時に誰かが爆死しても、私は責任を持たないぞ。",
  ui_story_2_13_23_dialog_content = "中尉！暗鬼です。暗鬼の群れがまた来ました！後方にまだ怪我人が…",
  ui_story_2_13_24_dialog_content = "了解！私たちで時間を稼ぐから、残りの人たちは急いで！！",
  ui_story_2_13_25_dialog_content = "どうやらカーテンコールには気が早いようだな。\nひとまず赤いボタンはしまうとしよう…",
  ui_story_2_14_1_dialog_content = "ようやく――乗れた！みんな、怪我はない？",
  ui_story_2_14_2_dialog_content = "点呼中です！おそらく全員揃ってます。カロン長官は？",
  ui_story_2_14_3_dialog_content = "カロン長官？長官は別のところで巨像の搭乗口の援護をしているはずだから…",
  ui_story_2_14_4_dialog_content = "お待たせして申し訳ありません、中尉！乗ってない者はいませんね！？\n暗鬼がもう足の踏み場もないほどの数になっています！！",
  ui_story_2_14_5_dialog_content = "ありがとう。こんなことになって本当に――",
  ui_story_2_14_6_dialog_content = "中尉、そんなこと仰らないでください！まずはみんなを連れてここを離れましょう。さぁ！",
  ui_story_2_14_7_dialog_content = "待って！まだ揃ってない！カロン長官はどこ？",
  ui_story_2_14_8_dialog_content = "カロン長官？先ほど遅れた怪我人数名を掩護して、たしか…",
  ui_story_2_14_9_dialog_content = "いた！あそこよ！",
  ui_story_2_14_10_dialog_content = "おのれ。こいつら、私の服を汚しおって…",
  ui_story_2_14_11_dialog_content = "孤軍奮闘しているようです。シェルター中の暗鬼が全部集まってきています！",
  ui_story_2_14_12_dialog_content = "進攻ルートからはっきりしました。暗鬼の目標は私です！",
  ui_story_2_14_13_dialog_content = "はやく乗って下さい！",
  ui_story_2_14_14_dialog_content = "私だって、乗りたいさ――！\nだがこの、ブタども、血気盛んにも、程がある！！",
  ui_story_2_14_15_dialog_content = "せめて、君たちに近づけることだけはさせない！！",
  ui_story_2_14_16_dialog_content = "だめよ、私、助けに行かなきゃ…PlayerName、一緒に来て！\n他の人はここに待機！！",
  ui_story_2_14_17_dialog_content = "グゥアアアア――！？",
  ui_story_2_14_18_dialog_content = "多すぎる…！前に進むことさえ…できない！",
  ui_story_2_14_19_dialog_content = "これ以上起動を遅らせれば、私たちも道連れです。\n迷っている時ではありません！",
  ui_story_2_14_20_option_content = "バイス、行かないと…",
  ui_story_2_14_21_dialog_content = "ダメよ！誰ひとり見捨てないって言ったじゃない！",
  ui_story_2_14_22_dialog_content = "中尉！PlayerNameの言う通りです。\n直ちに脱出しなければ！",
  ui_story_2_14_23_dialog_content = "カロン長官はあなたを助けたのよ！いいえ、私たち全員の恩人よ…\n恩人を見捨てるなんて、啓光のやり方じゃない！",
  ui_story_2_14_24_dialog_content = "でも、住民のみんなの命を放りだして、賭けに出るわけには！",
  ui_story_2_14_25_dialog_content = "そんなこと…もちろんわかってるわ…ああ、これじゃ、あの時の逆じゃない…",
  ui_story_2_14_26_option_content = "ダメだ。絶対にカロンを助ける",
  ui_story_2_14_27_dialog_content = "本当にそれでいいのですね、PlayerName？",
  ui_story_2_14_28_dialog_content = "このシェルターの住民全員がここにいます。\n失敗の代償がどれほどか、覚悟はありますか？",
  ui_story_2_14_29_dialog_content = "僕たちならやれると信じてる！",
  ui_story_2_14_31_dialog_content = "その揺るぎない自信が、もしかすると奇跡を起こすかもしれません…",
  ui_story_2_14_32_dialog_content = "そこはあなたと他の人たちとの一番の違いでしょう。PlayerName…",
  ui_story_2_15_1_dialog_content = "カロン長官！",
  ui_story_2_15_X1_dialog_content = "グアア――！",
  ui_story_2_15_F1_dialog_content = "ううっ、まったく近づけない…",
  ui_story_2_15_X2_dialog_content = "バイス！バカなことを！",
  ui_story_2_15_X3_dialog_content = "汚らわしい連中め、許さん！目にものを見るがいい！",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>バシュッ――！</color>",
  ui_story_2_15_A1_dialog_content = "カロン長官、何を…！？信号弾なんて発射したら、余計に暗鬼が寄ってきます！",
  ui_story_2_15_X6_dialog_content = "バイス、君たちは何を待っている！？子どもではあるまい！\n勝手なことをして、私に面倒をかけるのではない！",
  ui_story_2_15_2_dialog_content = "私は三途の列車・カロン、栄誉と美貌の集合体。\nその栄光の使命を妨げることは誰にも許されん！",
  ui_story_2_15_3_dialog_content = "もしかして、わざと…！？",
  ui_story_2_15_4_dialog_content = "PlayerName、早く行け！\n私の美しい姿に後ろ髪を引かれている場合ではなかろう！！",
  ui_story_2_15_5_dialog_content = "カロン長官、こんな時に気取った言葉なんていりません！！\nあなたが乗らないうちは、絶対に…",
  ui_story_2_15_A2_dialog_content = "安心しろ！この程度の敵に私は倒せん。君は知っているだろう、バイス！",
  ui_story_2_15_A3_dialog_content = "君たちがここにいるのは、かえって邪魔だ！！下手をすれば、\n三途の列車・暗鬼を打ち倒す者、カロンを殺したのは君たちと言うことになるぞ！！",
  ui_story_2_15_A4_dialog_content = "カロン長官…",
  ui_story_2_15_A5_dialog_content = "中尉、早く船に乗って皆を連れて離れろ！\nこれは命令だ！私も何とかして後から追いつく。",
  ui_story_2_15_A6_dialog_content = "…了解！PlayerName、起動準備を…",
  ui_story_2_15_A7_dialog_content = "起動成功…",
  ui_story_2_15_A8_dialog_content = "ソラヴァン、搭乗口はロックしないで。カロンがいつ追いつくかわからないからね！",
  ui_story_2_15_A9_dialog_content = "PlayerName、本当にそう思いますか？",
  ui_story_2_15_A10_dialog_content = "…どういう意味？",
  ui_story_2_15_A11_dialog_content = "カロンには…急いでこちらに来る気配がまったくありません。",
  ui_story_2_15_A12_dialog_content = "それどころか、暗鬼の群れの奥へ奥へと向かっています…",
  ui_story_2_15_A13_dialog_content = "何だって！？カロンは…",
  ui_story_2_15_6_dialog_content = "な、なに、この警報音は！？",
  ui_story_2_15_7_dialog_content = "中尉！自爆プログラムです。カロン長官が赤いボタンを押しました！！",
  ui_story_2_15_8_dialog_content = "そんなことわかってる！",
  ui_story_2_15_A14_dialog_content = "カロン長官…まさか最初からそのつもりだったの…！",
  ui_story_2_15_9_dialog_content = "エンジン吹き出し口、クリーンアップ完了！あの光霊を私は忘れません！\nしっかりつかまって！",
  ui_story_2_15_10_option_content = "出発！",
  ui_story_2_15_13_dialog_content = "船体に亀裂！白い巨翼に\n<color=#FFB400>何かが引っかかっているのでしょうか？この重さ、嫌な予感がします…</color>",
  ui_story_2_15_14_dialog_content = "…",
  ui_story_2_15_15_option_content = "大丈夫？",
  ui_story_2_15_17_dialog_content = "…しっかりつかまってないとだめよ、PlayerName。\n私たち、まだ危機を脱したわけじゃない。",
  ui_story_2_15_18_dialog_content = "カロン長官が赤いボタンを押したの。\nシェルターが爆発する前に、安全な高度まで上昇しなきゃ。",
  ui_story_2_15_19_option_content = "ごめんね…",
  ui_story_2_15_20_option_content = "カロンは…",
  ui_story_2_15_21_dialog_content = "約束したのに…誰も見捨てないって…あんなに約束したのに…",
  ui_story_2_15_F2_dialog_content = "あなたのせいじゃないわ、PlayerName。私…",
  ui_story_2_15_22_dialog_content = "私があの時もう少し頑張っているか、別のルートを選んでいれば、\n暗鬼に遮られることもなかったかも…",
  ui_story_2_15_23_dialog_content = "いいえ、初めから別々に援護に向かってはいけなかったのよ……",
  ui_story_2_15_24_dialog_content = "感動的なお芝居だ。あやうく見逃すところだった。",
  ui_story_2_15_25_dialog_content = "しぶとい奴らだ…我の予想以上にな。",
  ui_story_2_15_26_dialog_content = "…あなた…！？",
  ui_story_2_15_27_dialog_content = "あきらめろ。抵抗しても無駄だ！\n貴様らの小賢しい策になど、二度と引っかかるものか。二度とな…",
  ui_story_2_15_28_option_content = "どうして僕を殺そうとするの！？",
  ui_story_2_15_29_dialog_content = "使命を果たさねばならんのだ。",
  ui_story_2_15_30_dialog_content = "使命とは何か？例えば、信仰なき生き物すべてを抹殺することだ。",
  ui_story_2_15_31_option_content = "目的は一体何！？",
  ui_story_2_15_32_dialog_content = "すべては、我らが使命を全うするため。",
  ui_story_2_15_33_dialog_content = "我らの力は、信仰によってもたらされる。",
  ui_story_2_15_34_dialog_content = "そして信仰は、母上がもたらしてくださる。",
  ui_story_2_15_35_dialog_content = "空の末裔、それに光霊よ。大陸でなおざりに生き長らえている貴様ら下等生物にとって、\n我らの手にかかるのは至上の幸福であろう。",
  ui_story_2_15_36_dialog_content = "無駄な抵抗はやめたほうがいい。意味もなく苦しむだけだ。\nいつかの愚かな兵士と同じようにな。",
  ui_story_2_15_37_dialog_content = "上昇を止めて、地上に戻れ。\nそうすれば光霊は皆、喜ばしい終焉を迎えることができるぞ。",
  ui_story_2_15_38_dialog_content = "僕は降参なんてしないし、これ以上…仲間を傷つけるようなこともさせない！",
  ui_story_2_15_39_dialog_content = "名誉の戦死を望むのか？よかろう。",
  ui_story_2_15_40_dialog_content = "それでは貴様らに、その強情にふさわしい死を与えよう。",
  ui_story_2_15_41_dialog_content = "貴様らは、我にできる最も残忍なやり方で蹂躙され…死んでゆくのだ。",
  ui_story_2_15_89_dialog_content = "『我が…主よ…失敗しました…』",
  ui_story_2_15_91_dialog_content = "『しかし、決して…終わりではありません…』",
  ui_story_2_15_X92_dialog_content = "『我が懺悔をお聞きになりますか？ハハ…ハハハハハ…』",
  ui_story_2_15_X93_dialog_content = "…貴様らは仮初めの「勝利」に浸るがいい！",
  ui_story_2_15_X94_dialog_content = "我が主が、必ずや貴様らに裁きを下すであろう。あのお方が自ら貴様らの前に現れた時、\n光霊であろうと、腰の抜けた空の末裔であろうと――",
  ui_story_2_15_X95_dialog_content = "微かな呻きさえ、その卑しい咽喉から発することはできないであろう…",
  ui_story_2_15_92_dialog_content = "「スーモア」。この名前をよく覚えておくがいい。",
  ui_story_2_15_93_dialog_content = "貴様らは永遠に、我が主の持つ圧倒的な力を想像することすらできまい…",
  ui_story_2_15_42_dialog_content = "…今度こそ、二度と戻ってこられないでしょうね。",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_2_15_44_dialog_content = "シェルター28号が…爆発した…",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>炎の輝きと黎明が同時に訪れた。\nそれはまるで、新しく来た者を歓迎し、去って行った死者を弔うようだった…</color>",
  ui_story_2_15_46_dialog_content = "さようなら…シェルター28号。そしてカロン長官…",
  ui_story_2_15_47_dialog_content = "本当にごめん。",
  ui_story_2_15_48_dialog_content = "カロン長官自身が選んだことよ。あなたとは関係ないわ、PlayerName。",
  ui_story_2_15_49_dialog_content = "でもなぜ…私たちを援護するために自分の命さえも顧みないなんて。\nしかも最後の最後まで強がって…",
  ui_story_2_15_51_option_content = "きっとみんなの模範になるよ",
  ui_story_2_15_52_dialog_content = "命を落としてしまったら、模範になったところで何の意味があるっていうの？",
  ui_story_2_15_B1_dialog_content = "そもそもその「模範」って、いったいどういう意味…",
  ui_story_2_15_B2_dialog_content = "僕の理解が間違ってなければ、カロンは彼自身の「大切なもの」を守ったんだと思う…",
  ui_story_2_15_B3_dialog_content = "…",
  ui_story_2_15_B4_dialog_content = "兵士、同僚、仲間…そして、このシェルター。",
  ui_story_2_15_53_option_content = "きっとみんなの心の中で生き続けるよ",
  ui_story_2_15_54_dialog_content = "心の中で生き続ける？自分勝手に聞こえるかもしれないけど、\nそんなのは何の救いにもならないわ、PlayerName。",
  ui_story_2_15_55_dialog_content = "それは形を変えた苦しみよ…残された者への苦しみ。",
  ui_story_2_15_B5_dialog_content = "あなたの経験してきた苦しみと一緒。\nそれともあなたは、こんな結末を受け入れろっていうの…",
  ui_story_2_15_B6_dialog_content = "でも、受け入れる他に方法はない…",
  ui_story_2_15_B7_dialog_content = "少なくとも、彼は「大切なもの」を守るために犠牲になったんだ。\n兵士や、仲間たちのために…",
  ui_story_2_15_B8_dialog_content = "その気持ちを無下にすることはできないよ、バイス。",
  ui_story_2_15_B9_dialog_content = "あなたの言うことは分かるわ、PlayerName。\nでも、今はどうしても落ち着けないの。",
  ui_story_2_15_B10_dialog_content = "守ることや、身を捧げるっていうことの美徳は、\n啓光の者である以上、もちろん私にもわかる。",
  ui_story_2_15_B11_dialog_content = "でも、身近な人が一人また一人と消えていくことには…\nやっぱり平然と向き合うなんて、できないよ…。",
  ui_story_2_15_57_dialog_content = "私たちは毎日「啓明の光のために」って口にするけど、\n本当に空に輝く極光の一部になって、将来の人たちに恵みを与えられるのかな…",
  ui_story_2_15_58_dialog_content = "もしいつか…",
  ui_story_2_15_59_dialog_content = "いつか私たちがまたこんな決断を迫られたら、って…",
  ui_story_2_15_60_dialog_content = "考えただけで怖くて…",
  ui_story_2_15_61_dialog_content = "「希望」",
  ui_story_2_15_62_dialog_content = "…？",
  ui_story_2_15_63_dialog_content = "「絶望を変えられないなら、希望でその永遠の闇夜を満たすまで。」\nカロンがそう言ってたんだ。",
  ui_story_2_15_66_option_content = "…すごく長官らしいわ。",
  ui_story_2_15_F3_dialog_content = "私、ずっと忘れない――「三途の列車・カロン」という名前を！",
  ui_story_2_15_F4_dialog_content = "「三途の列車」…？",
  ui_story_2_15_F5_dialog_content = "どうしたの？",
  ui_story_2_15_70_dialog_content = "そういえば、カロンはなんで「三途の列車」って呼ばれていたの？",
  ui_story_2_15_71_dialog_content = "カロン長官のあの…やたらと目立つ列車のせいよ。あなたも見たでしょ。",
  ui_story_2_15_72_dialog_content = "もともと地下鉄の運行管理員だったから、\nいつでもあの「彼岸号」っていう…列車を呼び出せたの…",
  ui_story_2_15_73_dialog_content = "あっ！",
  ui_story_2_15_74_dialog_content = "列車？待って…あの信号弾…",
  ui_story_2_15_79_dialog_content = "カロン長官、まさか――",
  ui_story_2_15_80_dialog_content = "中尉、PlayerName！空を見て下さい、早く！",
  ui_story_2_15_81_dialog_content = "…<color=#FFB400>ハデなことが好きな方ですね</color>。",
  ui_story_2_15_82_dialog_content = "<size=45>さあ！華やかなカーテンコールの時間といこう！！</size>",
  ui_story_2_15_A15_dialog_content = "花火、拍手、そして皆の感動の涙、遠慮なく頂戴しようではないか！！",
  ui_story_2_15_83_dialog_content = "<size=45>三途の列車・カロンの登場だ！！！</size>",
  ui_story_2_15_84_dialog_content = "おや、観客の諸君、私のために感動の涙を流したのではなかったのかね？",
  ui_story_2_15_F6_dialog_content = "では、幸運な観客を1人、選ばせて頂こう――PlayerName、感想はいかがかな？",
  ui_story_2_15_X85_dialog_content = "…本当に目も眩むようなすごい演出だったよ…",
  ui_story_2_15_85_dialog_content = "…さすがはカロン長官…",
  ui_story_2_15_86_dialog_content = "本当に…喜んだらいいのか、怒ったらいいのか…",
  ui_story_2_15_87_option_content = "よかった…うう",
  ui_story_2_15_88_dialog_content = "PlayerName？",
  ui_story_2_15_X88_dialog_content = "頭がクラクラする…また…あの光景だ…",
  ui_story_2_15_95_dialog_content = "昔にも見たことのある…",
  ui_story_2_15_96_dialog_content = "バイス…",
  ui_story_2_15_100_dialog_content = "PlayerName！私はここにいる！しっかりして！",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>一方、ある別の<color=#FFB400>巨像の遺跡</color>の外にて</color>",
  ui_story_2_15_102_dialog_content = "…",
  ui_story_2_15_103_dialog_content = "大丈夫ですか、スーモア様。",
  ui_story_2_15_104_dialog_content = "どういう意味？",
  ui_story_2_15_105_dialog_content = "先ほど何か考え事をされていたようですが。長いこと苦労して待ち続けたチャンス、\nこの期に及んで、その様に心ここにあらずのご様子では…",
  ui_story_2_15_106_dialog_content = "…余計な事を探らない方が身のためよ、暗鬼。私はただ…いや、単なる気のせいね。",
  ui_story_2_15_107_dialog_content = "それでは、狩りが順調に進むことをお祈りいたしております。\nずっと探していたものが見つかるとよろしいですね。",
  ui_story_2_15_108_dialog_content = "狩り…ふん。その表現はまぁ、私好みね。",
  ui_story_2_15_109_dialog_content = "僕の声が聞こえるかい…君の存在を感じるよ…",
  ui_story_2_15_110_dialog_content = "君は<color=#FFB400>同類</color>である僕の存在を感じているはず…僕にはもう時間がない。",
  ui_story_2_15_111_dialog_content = "グリード、<color=#FFB400>あの女</color>…不吉な黒色の…同類殺しの罪人に…",
  ui_story_2_15_112_dialog_content = "見つかってしまった…",
  ui_story_2_15_113_dialog_content = "僕と僕の巨像には…時間がない…",
  ui_story_3_1_1_dialog_content = "聞こえるかい？君を知らなくても僕には分かる、君は「同胞」だ…",
  ui_story_3_1_2_dialog_content = "君なら…聞こえるはずだ、僕の声が…",
  ui_story_3_1_3_dialog_content = "信号弾を発射した。全員その場で待機せよ、勝手にうろつかないように。",
  ui_story_3_1_4_dialog_content = "む？バイス、PlayerNameがお目覚めのようだ。",
  ui_story_3_1_5_dialog_content = "しかし、まだ私の華麗なるパフォーマンスの余韻に浸っているようだな。",
  ui_story_3_1_6_dialog_content = "ありがとうございます、カロン長官。まずは長官が応急処置を受けてください！",
  ui_story_3_1_7_dialog_content = "大したことはない。私は大丈夫だ。\nそれより、先ほどの勇姿、誰かが残していれば貴重な映像資料となっただろうに、残念だ…",
  ui_story_3_1_8_dialog_content = "あ、そっちを気にしてるんですか…？",
  ui_story_3_1_9_dialog_content = "それにしても、赤いボタンの威力は凄まじかったな。\nずっと前から押してみたいとは思っていたが…",
  ui_story_3_1_10_dialog_content = "カロン長官、シェルター28号が廃墟と化してしまったのに、悲しくはないんですか？",
  ui_story_3_1_11_dialog_content = "悲しいさ。でも号泣するほどじゃない。\nなぜなら<color=#FFB400>故郷</color>はまだ残っているからな。",
  ui_story_3_1_12_dialog_content = "故郷？",
  ui_story_3_1_13_dialog_content = "そうさ、周りを見るがいい。",
  ui_story_3_1_14_dialog_content = "居住民、兵士。啓光連邦の最も重要な「財産」は、みんな無事じゃないか。",
  ui_story_3_1_15_dialog_content = "「大切なもの」のある所が故郷だ。",
  ui_story_3_1_F1_dialog_content = "…",
  ui_story_3_1_16_dialog_content = "君と空の末裔くんは無事か？そういえば、君らを助けたのはこれで二度目だな。",
  ui_story_3_1_F2_dialog_content = "ありがとうございます。",
  ui_story_3_1_17_dialog_content = "私はあの場所に行き、被害状況を確認する必要がある。\nどこへも行かず、ここで命令を待て！",
  ui_story_3_1_18_dialog_content = "は、はい…",
  ui_story_3_1_19_dialog_content = "カロン…意外と優しいんだね。",
  ui_story_3_1_20_dialog_content = "PlayerName、大丈夫？あなたさっき…",
  ui_story_3_1_B1_dialog_content = "うん、大丈夫。",
  ui_story_3_1_B2_dialog_content = "酷い顔色よ。無理はしないで。",
  ui_story_3_1_B3_dialog_content = "バイス、ありがとう…そばにいてくれて。",
  ui_story_3_1_B4_dialog_content = "そんなの水臭いわ。私たちは息もピッタリの相棒でしょ！",
  ui_story_3_1_B5_dialog_content = "あの上級暗鬼を倒せたのも、あなたがいたからよ。",
  ui_story_3_1_B6_dialog_content = "でも、これはまだ<color=#FFB400>始まり</color>に過ぎないよ、バイス。",
  ui_story_3_1_B7_dialog_content = "えっ？始まり？",
  ui_story_3_1_B8_dialog_content = "マクガフィンが死ぬ前に、また<color=#FFB400>スーモア</color>という名前を口にした。",
  ui_story_3_1_B9_dialog_content = "「スーモア」…一体どんな人かしらね？",
  ui_story_3_1_B10_dialog_content = "まだ確証はないけど、すべての真相はそいつが知ってると思う。",
  ui_story_3_1_B11_dialog_content = "バイス、ごめん。僕は「スーモア」を探し出して、真相を突き止めなきゃ。",
  ui_story_3_1_B12_dialog_content = "PlayerName…どうして急にそんな意欲がわいたの？",
  ui_story_3_1_B13_dialog_content = "僕は…自分の新しい「<color=#FFB400>故郷</color>」を見つけたんだよ、バイス。",
  ui_story_3_1_B14_dialog_content = "…私が治療を受けている間に、カロン長官といったいどんな話をしたの…",
  ui_story_3_1_B15_dialog_content = "マクガフィンの口から「スーモア」に関する情報を\nあれ以上聞きだせなかったのは、残念だけど…",
  ui_story_3_1_B17_dialog_content = "大丈夫よ。啓光連邦の本部に戻れば、何か関連する資料を見つけられるかも。",
  ui_story_3_1_B18_dialog_content = "PlayerName、どうしたの…？",
  ui_story_3_1_B21_dialog_content = "…助け…",
  ui_story_3_1_B22_dialog_content = "…や…く…聞こえる！？",
  ui_story_3_1_B23_dialog_content = "PlayerName、感じましたか？先ほどから、まるで…",
  ui_story_3_1_B24_dialog_content = "うん。<color=#FFB400>誰かが僕たちに、助けを求めてる</color>？",
  ui_story_3_1_21_dialog_content = "グリード…が…僕にはもう…時間がない…",
  ui_story_3_1_22_dialog_content = "何かの声が聞こえた、そうでしょ？",
  ui_story_3_1_23_option_content = "この感知は、空の末裔だけしか…！",
  ui_story_3_1_24_dialog_content = "<color=#FFB400>僕と同じ</color>生き残りかな？もしかして僕の同族！？",
  ui_story_3_1_25_dialog_content = "そうですね。話の内容からして、危険な状況に置かれているようです。",
  ui_story_3_1_26_dialog_content = "もしかしたら我々と同じように…",
  ui_story_3_1_27_option_content = "少年の声だったよ",
  ui_story_3_1_28_dialog_content = "ええ、彼の意識は恐怖に満ちていました。先行きが思わしくないのでしょう。",
  ui_story_3_1_F3_dialog_content = "こういう感知ができるってことは…僕の同族！？",
  ui_story_3_1_29_dialog_content = "そのようです。しかし相手の巨像のシグナルがきわめて弱いため、\n何度か試行してみましたが、補足できませんでした。",
  ui_story_3_1_30_dialog_content = "彼は助けを求めてる。何か恐ろしいことが起きているんだ。彼に、そして彼の巨像に…",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>また空の末裔</color>？",
  ui_story_3_1_32_dialog_content = "待って、あなた今、それに他の巨像も見つけたって言った？",
  ui_story_3_1_33_dialog_content = "バイス、手助けをお願いしてもいい？",
  ui_story_3_1_34_dialog_content = "…",
  ui_story_3_1_35_dialog_content = "中尉、何やら伝えたいことがあるようだな。",
  ui_story_3_1_36_dialog_content = "えっと、私たち…",
  ui_story_3_1_37_dialog_content = "他の空の末裔から救難信号を受け取ったんだ！",
  ui_story_3_1_38_dialog_content = "…！？",
  ui_story_3_1_39_dialog_content = "急に空の末裔が2人も？近頃はいったい何が起こっているのだ。",
  ui_story_3_1_40_dialog_content = "間違いないと思う。こういう感知の方法、僕が使っているのと一緒だ！",
  ui_story_3_1_41_dialog_content = "どこなのだ？近くか？",
  ui_story_3_1_42_dialog_content = "それは分からない…でも大体の方向は分かってる。今すぐ出発しないと！",
  ui_story_3_1_43_dialog_content = "…",
  ui_story_3_1_44_dialog_content = "そうはいかん。",
  ui_story_3_1_45_dialog_content = "長官！",
  ui_story_3_1_46_dialog_content = "なんたる無秩序、無鉄砲！お前たちがさっき、どれだけのトラブルを引き起こしたと…！",
  ui_story_3_1_47_dialog_content = "でも…",
  ui_story_3_1_48_dialog_content = "…シーッ…みんなが見ているぞ。こんな時に慌てるな…",
  ui_story_3_1_49_dialog_content = "それに、君の直属の長官――第三軍団長のヒイロが間もなくやってくる頃だ。",
  ui_story_3_1_50_dialog_content = "まずは彼女に現在の状況を報告するべきではないかね？",
  ui_story_3_1_51_dialog_content = "…",
  ui_story_3_1_52_dialog_content = "ですが、時間を無駄にするわけには…",
  ui_story_3_1_53_dialog_content = "次にいつ手がかりが得られるかなんて、わからないんです！",
  ui_story_3_1_54_dialog_content = "さっきの声、すぐにでも助けが必要な感じだったんだ！かなり危険な状況に違いないよ！",
  ui_story_3_1_55_dialog_content = "きっと僕の一族なんだ、カロン。本物の、まだ生きている同族なんだ！",
  ui_story_3_1_56_dialog_content = "…",
  ui_story_3_1_57_dialog_content = "カロン長官…",
  ui_story_3_1_58_dialog_content = "私も、君にとってそれがいかに重要かは理解している、PlayerName。",
  ui_story_3_1_59_dialog_content = "しかし啓光連邦にも規律というものがある。\n特に長官である私がまだこの場にいる状況ではな。",
  ui_story_3_1_60_dialog_content = "ただ…",
  ui_story_3_1_61_dialog_content = "…！",
  ui_story_3_1_62_dialog_content = "ただ、君たちの行動が私のあずかり知らぬものだというなら、話は別だ。",
  ui_story_3_1_63_dialog_content = "えっ？",
  ui_story_3_1_64_dialog_content = "君は仮にも中尉だろう、バイス。それに直属の上司は私ではない。",
  ui_story_3_1_A1_dialog_content = "つまり、君にもある程度の裁量権があるということだ。\n啓光連邦を危険にさらさない限りはな。",
  ui_story_3_1_A2_dialog_content = "オホン…もう一度言っておくが、啓光連邦の同僚たちが皆、見ているのだぞ。",
  ui_story_3_1_A3_dialog_content = "どうすればいいかわかったよ、バイス。",
  ui_story_3_1_65_dialog_content = "なにかアイデアがあるの？",
  ui_story_3_1_B25_option_content = "こっそり抜け出せばいいんだ",
  ui_story_3_1_B26_option_content = "ちょっとした演技をしよう",
  ui_story_3_1_66_dialog_content = "PlayerName、カロン長官の前でそんなこと…",
  ui_story_3_1_67_dialog_content = "ん？何か言ったかね？風が強くて聞き取れなかったな。",
  ui_story_3_1_68_dialog_content = "…",
  ui_story_3_1_B26_dialog_content = "カロン長官、まさか暗に…",
  ui_story_3_1_B27_dialog_content = "暗に？私は何も言っていないぞ！何を言っているのだ。",
  ui_story_3_1_B28_dialog_content = "私はただ、中尉である君にどのような選択肢があるのかを示しただけだ、バイス。",
  ui_story_3_1_B29_dialog_content = "君がどんな方向へ進もうとも、それは君自身の選択だ。",
  ui_story_3_1_B30_dialog_content = "わかりました、カロン長官。ありがとうございます。",
  ui_story_3_1_B31_dialog_content = "ヒイロはもうすぐ来るぞ。「私の知らない」ことをやるなら、今のうちだ。",
  ui_story_3_1_B32_dialog_content = "彼女が来てしまったら、残って報告せねばならなくなる。",
  ui_story_3_1_B33_dialog_content = "カロンって…本当に面白い人だね。",
  ui_story_3_1_B34_dialog_content = "はー…緊張する…ヒイロ長官、どんな反応をするかしら…",
  ui_story_3_1_B35_dialog_content = "演技…？",
  ui_story_3_1_B36_dialog_content = "エヘン、エヘン！",
  ui_story_3_1_B37_dialog_content = "あー、あー！カロン、言うべきかどうかわからないんだけど！",
  ui_story_3_1_B38_dialog_content = "オッホン。言うがよい。空の末裔よ！",
  ui_story_3_1_B39_dialog_content = "ソラヴァンがさっき教えてくれたんだ。\n大量の暗鬼の群れが、巨像の後を追ってこっちに向かってるって！",
  ui_story_3_1_B40_dialog_content = "え？えっ？",
  ui_story_3_1_B41_dialog_content = "おお、なんと！！巨像の気配がさらなる暗鬼どもを引き寄せているというのか！？",
  ui_story_3_1_B42_dialog_content = "なぜもっと早く言わなかった！！これはこの上ない危機ではないか！！",
  ui_story_3_1_B43_dialog_content = "？？？？",
  ui_story_3_1_B44_dialog_content = "（バイス、合わせて！これは「演技」なんだ！）",
  ui_story_3_1_B45_dialog_content = "あ、ああ！すみません、わ…私もさっき知ったばかりで…？",
  ui_story_3_1_B46_dialog_content = "ああ！そのような言い訳があるか！\n地獄のごとき火の海から逃げおおせたばかりの人々を、再び脅威にさらすとは…",
  ui_story_3_1_B47_dialog_content = "皆を危険にさらすような行為、私は断じて容認せんぞ！",
  ui_story_3_1_B48_dialog_content = "えっ、じ、じゃあどうすればいいんですか！",
  ui_story_3_1_B49_dialog_content = "今すぐに巨像を連れてここから離れたまえ！\n被災した哀れな人々から、少しでも遠ざけるのだ！",
  ui_story_3_1_B50_dialog_content = "ラジャー！",
  ui_story_3_1_B51_dialog_content = "（さ、早く行こう！）",
  ui_story_3_1_B52_dialog_content = "あ、ありがとうございます、カロン長官。",
  ui_story_3_1_B53_dialog_content = "…ふん。",
  ui_story_3_1_B55_dialog_content = "さっきのよく分からない寸劇、本当に必要だったかしら…",
  ui_story_3_1_B56_dialog_content = "さあね。でもカロンだって楽しんでたみたいだよ？",
  ui_story_3_1_B57_dialog_content = "それに、僕らにはここを離れる理由が必要だった――君の直属の長官がやってくる前に。",
  ui_story_3_1_B58_dialog_content = "そうだ、長官…",
  ui_story_3_1_B59_dialog_content = "あーっ、このことがヒイロ長官に知られたら、一体どんな反応するんだろう…",
  ui_story_3_1_69_option_content = "後悔してる？",
  ui_story_3_1_70_dialog_content = "してない！",
  ui_story_3_1_71_dialog_content = "「ヒイロ」…さん？っていう君の上司が、理解ある人だといいな。",
  ui_story_3_1_72_dialog_content = "…そう言われると、ちょっと後悔してきたわ。",
  ui_story_3_1_73_option_content = "この選択が正しかったと信じよう",
  ui_story_3_1_74_dialog_content = "正しいかどうかは、誰にもわからないわ…",
  ui_story_3_1_76_dialog_content = "ああああ、ヒイロ長官に殺されちゃうかも！！",
  ui_story_3_1_77_dialog_content = "目標、未知の空の末裔の生命シグナルの発信地。加速カウントダウン開始！",
  ui_story_3_1_78_dialog_content = "5…4…3…2…",
  ui_story_3_1_79_dialog_content = "1！離陸！",
  ui_story_3_1_80_dialog_content = "長官！本件に関する陳述書ですが、このような処理でよろしいでしょうか…",
  ui_story_3_1_81_dialog_content = "どれどれ、うむ…うむ…ここが不十分だ。",
  ui_story_3_1_82_dialog_content = "バイスと空の末裔に関する部分をさらに詳しく書き直してくれ。\n彼らの行動とここで起きたことの関連あたりをな。",
  ui_story_3_1_83_dialog_content = "あ、はい、長官！",
  ui_story_3_1_84_dialog_content = "私を信じろ。彼女に根掘り葉掘り尋問されるなんて、君もゴメンだろうからな。",
  ui_story_3_1_85_dialog_content = "この有り様は…私が想像していたものとまったく違いますね、カロン。",
  ui_story_3_1_86_dialog_content = "…",
  ui_story_3_1_87_dialog_content = "シェルター28号のことなら、あの廃墟がそれだ、軍団長くん。",
  ui_story_3_1_88_dialog_content = "わかっていることを繰り返さずとも結構です。\nカロン、あの通信で言っていた巨像は？",
  ui_story_3_1_89_dialog_content = "あの鳥なら既に、美しく飛び去って行ったよ。",
  ui_story_3_1_90_dialog_content = "私の部下はどこに？",
  ui_story_3_1_91_dialog_content = "飛んでいったよ、巨像の中だ。",
  ui_story_3_1_92_dialog_content = "…シェルター28号管理責任者、カロン。\n私の部下が命令違反をしたと言うのですか？",
  ui_story_3_1_93_dialog_content = "私はただ、彼女はあの空の末裔と一緒だと、言っているだけだ。",
  ui_story_3_1_94_dialog_content = "空の末裔…",
  ui_story_3_1_95_dialog_content = "長官！こちらはもう…あ、軍団長様、お話し中申し訳ありません！",
  ui_story_3_1_96_dialog_content = "構いません。何ですか？",
  ui_story_3_1_97_dialog_content = "はっ！被害規模と民衆の健康状態の統計が終わりましたので、\n次のご指示をお願いいたします！",
  ui_story_3_1_98_dialog_content = "元の計画通り、最も近いシェルターを手配しなさい。\n第1、第3大隊を残し、道中を守らせましょう。",
  ui_story_3_1_99_dialog_content = "民衆の護送なら、我々だけでできるさ、君の手を煩わせる必要は…",
  ui_story_3_1_100_dialog_content = "残りの者は、私と一緒に来なさい。",
  ui_story_3_1_101_dialog_content = "…",
  ui_story_3_1_102_dialog_content = "相変わらず素直ではないな、ヒイロ。",
  ui_story_3_1_103_dialog_content = "何してるの？",
  ui_story_3_1_104_dialog_content = "これのこと？",
  ui_story_3_1_A4_dialog_content = "これ何？調理器具？",
  ui_story_3_1_A5_dialog_content = "…小型化した遠距離トランシーバーよ。",
  ui_story_3_1_105_dialog_content = "啓光連邦のもの？こんなもの、ここにあったっけ？",
  ui_story_3_1_106_dialog_content = "さっきカロン長官がこっそり持たせてくれたの。",
  ui_story_3_1_107_dialog_content = "カロンが…",
  ui_story_3_1_108_dialog_content = "どうすればいいのかしら、けっこう難しいわね…",
  ui_story_3_1_109_dialog_content = "確か…ここで交差してて、コイルを入れて、それから周波数を調整…",
  ui_story_3_1_111_dialog_content = "あ、つながった！",
  ui_story_3_1_112_dialog_content = "現在地を報告しなさい。",
  ui_story_3_1_113_dialog_content = "ヒ、ヒイロ長官！？",
  ui_story_3_1_114_dialog_content = "まだ自分の上司は忘れていないようですね、中尉。\nなぜ勝手にシェルターを離れたのですか？",
  ui_story_3_1_115_dialog_content = "申し訳ありません。シェルター28号が暗鬼の侵入により、\n自爆プログラムを起動して、爆発したからです。",
  ui_story_3_1_116_dialog_content = "既に分かっていることを繰り返さなくても結構。\n私が聞いているのは、なぜ勝手に巨像を引き連れて飛び出したのかということです。",
  ui_story_3_1_117_dialog_content = "巨像…私…",
  ui_story_3_1_118_dialog_content = "あの…悪いけど、巨像はあなた方のものじゃありません。\n分かってもらえるといいんだけど。",
  ui_story_3_1_119_dialog_content = "あなたが…",
  ui_story_3_1_120_dialog_content = "はい、僕がこの巨像の主です。",
  ui_story_3_1_122_dialog_content = "あなたとあなたの大切な巨像のせいで、シェルター28号は地図上から消失しました。",
  ui_story_3_1_A6_dialog_content = "啓光連邦に説明する義理があるとは思いませんか？",
  ui_story_3_1_123_dialog_content = "それについては本当にごめんなさい…何とか説明してみます…",
  ui_story_3_1_124_dialog_content = "マクガフィンが言ってました。「<color=#FFB400>スーモア</color>」というやつが…",
  ui_story_3_1_125_dialog_content = "マクガフィン、スーモア、面妖な名前自体に興味はありません。",
  ui_story_3_1_126_dialog_content = "とにかく、すべては…シェルター28号のことは、「スーモア」と関係があるはずです！",
  ui_story_3_1_127_dialog_content = "なんと？",
  ui_story_3_1_128_dialog_content = "長官、私たちは他の空の末裔を探しているんです。\n他の巨像を探し出せるかもしれません！！",
  ui_story_3_1_129_dialog_content = "一体どういう…",
  ui_story_3_1_130_dialog_content = "ですが、その空の末裔と巨像が、危険な状態なんです！",
  ui_story_3_1_131_dialog_content = "PlayerNameはそれを何とかしたくて。それで、私は…",
  ui_story_3_1_132_dialog_content = "同行するべきだと考えました。啓光にとっても極めて重大なことです！",
  ui_story_3_1_133_dialog_content = "中尉、確認しておきますが――",
  ui_story_3_1_A7_dialog_content = "今のあなたは啓光連邦の兵士です。そのことをよく肝に銘じておくべきでしょう。",
  ui_story_3_1_134_dialog_content = "長官、申し訳ありません。一度は止めたんですが、でも今回は彼が正しいと思います！",
  ui_story_3_1_135_dialog_content = "バイス…？",
  ui_story_3_1_136_dialog_content = "今回は、彼が正しいと思うんです…",
  ui_story_3_1_137_dialog_content = "僕は同胞を救って、全ての真相を明らかにしたいんです。",
  ui_story_3_1_A8_dialog_content = "…",
  ui_story_3_1_A9_dialog_content = "…",
  ui_story_3_1_138_dialog_content = "まったく…やれるのですか？",
  ui_story_3_1_139_dialog_content = "二度と暗鬼の好きにはさせません！",
  ui_story_3_1_140_dialog_content = "…目的地の座標を伝えなさい。ただちに。",
  ui_story_3_1_141_dialog_content = "通信シグナルが不安定で、あなたたちの位置を特定できないのです。",
  ui_story_3_1_142_dialog_content = "それからバイス、あなたの立場を忘れないように。軽率な真似は…",
  ui_story_3_1_144_dialog_content = "あっ、信号が急に途絶えた！？",
  ui_story_3_1_145_dialog_content = "強い圧迫感を感じます…以前遭遇したものとは違います。",
  ui_story_3_1_146_dialog_content = "助けを求めてきた人は、「<color=#FFB400>グリード</color>」が何とかって言ってた。",
  ui_story_3_1_A10_dialog_content = "こいつのこと？",
  ui_story_3_1_147_dialog_content = "不明です、PlayerName。しかし、非常に強大な力が…",
  ui_story_3_1_148_dialog_content = "…確かに、ここに存在します。",
  ui_story_3_1_A11_dialog_content = "バイス、ソラヴァンが目的地を見つけたよ。\n中にはたぶん「グリード」って呼ばれる、すごい何かがいるはず。",
  ui_story_3_1_A12_dialog_content = "まだ情報が少なすぎるから…いつもより気を付けないと。",
  ui_story_3_1_149_dialog_content = "「グリード」？すごい何かって、まさか巨像？",
  ui_story_3_1_150_dialog_content = "それは分からないんだ…",
  ui_story_3_1_151_dialog_content = "えっ…",
  ui_story_3_1_152_dialog_content = "PlayerName、もし今、私が真剣にあなたを引き止めたら、\n言うことを聞いてくださいますか？",
  ui_story_3_1_153_dialog_content = "ソラヴァン…ごめん。",
  ui_story_3_1_154_dialog_content = "…そう言うと思っていました…",
  ui_story_3_1_155_dialog_content = "間もなく降下します、戦闘に備えてください。",
  ui_story_3_1_A13_dialog_content = "下はすでに、暗鬼の群れです!",
  ui_story_3_3_1_dialog_content = "ん？誰か来たみたいね。",
  ui_story_3_3_2_dialog_content = "身のほど知らずな…私の邪魔をしに来たのかしら？",
  ui_story_3_3_3_dialog_content = "片付けて来ましょうか？",
  ui_story_3_3_4_dialog_content = "しばらくその必要はないわ。これからやることの方が大事だもの。",
  ui_story_3_3_5_dialog_content = "スーモア…何しに来た？",
  ui_story_3_3_6_dialog_content = "あら？顔を出したわね。あの時みたいに、逃げ出すかと思っていたわ。",
  ui_story_3_3_7_dialog_content = "<color=#FFB400>セクレペトス</color>の主さん。",
  ui_story_3_3_8_dialog_content = "あ、違った。もっとチャーミングなニックネームがあったわね。\n「腰抜け<color=#FFB400>モンドル</color>」。",
  ui_story_3_3_9_dialog_content = "…ゴホッ…目覚めて最初に嗅ぐのが、君の吐き気がする臭いとはね…スーモア。",
  ui_story_3_3_10_dialog_content = "あるいは、僕の方も君を「<color=#FFB400>グリードの主</color>」と呼ぶべきかい？",
  ui_story_3_3_11_dialog_content = "いちおうは兄妹分のよしみで、単刀直入に言うわ。",
  ui_story_3_3_12_dialog_content = "<color=#FFB400>アレ</color>のありかに案内してちょうだい。",
  ui_story_3_3_A1_dialog_content = "何のことかわからないな。ここには何もないぞ、スーモア。あるのは退屈な歴史だけ…",
  ui_story_3_3_A2_dialog_content = "それと汚らわしい秘密も、でしょ。今さら知らないなんて思わないで。",
  ui_story_3_3_A3_dialog_content = "「<color=#FFB400>ブレーンパーツ</color>」、渡しなさい。\nここに1個あるのはわかってるの。",
  ui_story_3_3_A4_dialog_content = "…それで何をするつもりだ？",
  ui_story_3_3_A5_dialog_content = "ちょっとね…知りたいことがあるの。",
  ui_story_3_3_A6_dialog_content = "あれをやろうというなら、絶対に応じるわけにはいかない。",
  ui_story_3_3_A7_dialog_content = "明白に禁じられた、巨像の使命に反する「邪道」だぞ！",
  ui_story_3_3_13_dialog_content = "その扉を僕に開かせる？",
  ui_story_3_3_14_dialog_content = "君は「セクレペトス」…秘密を守る者という言葉を\nいささか誤解しているみたいだね、スーモア。",
  ui_story_3_3_15_dialog_content = "そんなケチ臭いこと言わないでよ、モンドル。",
  ui_story_3_3_16_dialog_content = "私たちは同じ力に頼って生きてる、違ったかしら？\nそうでなければ、あなただって17年前のあの日、生き残ることはできなかった…",
  ui_story_3_3_17_dialog_content = "あれは空の末裔には永遠に得ることのできない力。あなたと私は同じなの。",
  ui_story_3_3_18_dialog_content = "そうだ。だから僕は、あの日から一度だって後悔しない日はなかった、\nスーモア…ゴホッ…そうと知っていたら…",
  ui_story_3_3_19_dialog_content = "ん…？あなたの体、壊れていってるみたいね…",
  ui_story_3_3_A8_dialog_content = "「恩寵」を完全には賜っていなかったのね、モンドル。哀れな風見鶏…",
  ui_story_3_3_20_dialog_content = "話をすることさえ辛そうなんて…まったく、胸が痛むわ！",
  ui_story_3_3_22_dialog_content = "鉄槌を下すところに死線あり――これは警告である、歩みを進めてはならぬ。",
  ui_story_3_3_23_dialog_content = "わかったか？その線を超えたら地獄だぞ。",
  ui_story_3_3_24_dialog_content = "僕は戦えないけど、セクレペトスもまた、\n誰にでも侵略され放題というわけではないんだ…ゴホッ…",
  ui_story_3_3_25_dialog_content = "人型のファイアウォール…腰抜け特製の防衛装置というわけか。",
  ui_story_3_3_26_dialog_content = "僕を見くびるなよ、スーモア！",
  ui_story_3_3_27_dialog_content = "スーモア様、ここは…",
  ui_story_3_3_A9_dialog_content = "口を挟むな！これは私たちの問題よ！",
  ui_story_3_3_28_dialog_content = "ふん、飼い猫に忠犬…ほんと、モンドルらしいわ。",
  ui_story_3_3_29_dialog_content = "そんなんだから、あなたはずっと意気地なしの臆病者なんでしょうけど。",
  ui_story_3_3_30_dialog_content = "無礼者め！",
  ui_story_3_3_31_dialog_content = "うるさいわ。跪きなさい！",
  ui_story_3_3_32_dialog_content = "行動不能！行動不能…優先度最高の指令を受信、強制実行！",
  ui_story_3_3_33_dialog_content = "フェネクス！マスター、フェネクスが…",
  ui_story_3_3_34_dialog_content = "ああああ…",
  ui_story_3_3_35_dialog_content = "フェニィ、フェネクス…一体…スーモア！2人に何をした！？",
  ui_story_3_3_36_dialog_content = "おもしろい「オモチャ」ね、モンドル。",
  ui_story_3_3_37_dialog_content = "とりあえず決めたの。オモチャは私がもらっておくわね。",
  ui_story_3_3_38_dialog_content = "空の末裔としての魂と肉体を堕落させただけじゃない…\nもはや別の存在に成りはててしまったのか、スーモア！",
  ui_story_3_3_39_dialog_content = "褒めてくれるの？うれしいわ。でも、私がやりたいことは何も変わってないの。",
  ui_story_3_3_40_dialog_content = "二人を返せ！！化け物め！",
  ui_story_3_3_41_dialog_content = "あらあら。そのお願い、聞いてあげてもいいわ。\nフェネクス、フェニィ…だったかしら？",
  ui_story_3_3_42_dialog_content = "はっ！",
  ui_story_3_3_43_dialog_content = "モンドルを捕らえなさい！",
  ui_story_3_3_44_dialog_content = "な…なんだって！",
  ui_story_3_3_45_dialog_content = "チッ、また逃げるのね。",
  ui_story_3_3_46_dialog_content = "「僕を見くびるな」とか言って、結局、何も変わっていないじゃない。\n相変わらず、臆病者のまま。",
  ui_story_3_3_47_dialog_content = "どうしますか、マスター。",
  ui_story_3_3_48_dialog_content = "追いなさい、あいつを捕まえて。それから連れ帰って、顔をよく見せてちょうだい――",
  ui_story_3_3_49_dialog_content = "その時は一体どんな顔をするかしらね？",
  ui_story_3_3_50_dialog_content = "はいっ！！",
  ui_story_3_3_51_dialog_content = "はっ！！",
  ui_story_3_3_52_dialog_content = "あ、あいつらに捕まるわけには…いかない…聞こえて…いるかい…助け…",
  ui_story_3_3_53_dialog_content = "聞こえるよ！どこにいるの！？君も空の末裔なんだね！？",
  ui_story_3_3_54_dialog_content = "…グリードの力が、強くなってきてる…",
  ui_story_3_3_55_dialog_content = "か、彼女に「ブレーンパーツ」を奪われてはいけない、\n「あれ」を…使わせてはいけない…",
  ui_story_3_3_56_dialog_content = "逃げられないわよ。話をするのも苦しいほどに弱った姿を見ていると…本当に哀れね。",
  ui_story_3_3_57_dialog_content = "スーモア…今回は思い通りにはならない、絶対にだ…",
  ui_story_3_3_58_dialog_content = "私からは逃げられないわよ。",
  ui_story_3_3_59_dialog_content = "しかし…君は既に勝った…違うな。最初から勝っていた。",
  ui_story_3_3_60_dialog_content = "その邪悪な力で僕を侵食し、君に抵抗できないように――",
  ui_story_3_3_61_dialog_content = "いや、それでも阻止しないと…これは僕の使命、セクレペトスの使命だ…",
  ui_story_3_3_62_dialog_content = "…あなたはいつだって、意気地なしの臆病者だった。",
  ui_story_3_3_63_dialog_content = "僕は生きるべきなのか、それとも消えるべきなのか…",
  ui_story_3_3_64_dialog_content = "『いたぞ！捕まえろ！』",
  ui_story_3_3_65_dialog_content = "いるのかい？同胞よ、僕は逃げ続ける！",
  ui_story_3_3_66_dialog_content = "頼む、急いでくれ…僕のために、そして君自身のために！",
  ui_story_3_3_A10_dialog_content = "…あの人、今暗鬼に追われてる。正確な位置が把握できない…",
  ui_story_3_3_A11_dialog_content = "わかったわ。急ぎましょう！",
  ui_story_3_3_A12_dialog_content = "PlayerName、この先は暗鬼がどんどん増えてくるわ。警戒していて！",
  ui_story_3_7_1_dialog_content = "ここも暗鬼だらけね…PlayerName、大丈夫？",
  ui_story_3_7_2_dialog_content = "大丈夫だよ。",
  ui_story_3_7_3_dialog_content = "あなたが言ってる、空の末裔って…",
  ui_story_3_7_4_dialog_content = "待って！",
  ui_story_3_7_5_dialog_content = "…捕まるわけには…いかない…",
  ui_story_3_7_6_dialog_content = "着いたよ！どこ？聞こえる？",
  ui_story_3_7_7_dialog_content = "早くこっちへ！そしたら君を守れる！",
  ui_story_3_7_8_dialog_content = "君は…来てくれたのか！",
  ui_story_3_7_9_dialog_content = "遅くなってごめん！！聞こえる！？",
  ui_story_3_7_10_dialog_content = "もちろんだ。もちろん…君の姿だって見える、あれが君か――",
  ui_story_3_7_16_dialog_content = "誰！？",
  ui_story_3_7_17_dialog_content = "…ゴホッ、敵が、後ろに…",
  ui_story_3_7_18_dialog_content = "大丈夫！？間に合った、良かった、間に合ったよ！",
  ui_story_3_7_A5_dialog_content = "あ、もしかして…？",
  ui_story_3_7_A6_dialog_content = "そうだよ、バイス。この人がずっと僕たちに助けを求めていた空の末裔だ！",
  ui_story_3_7_19_dialog_content = "見た感じ…まずそうね。PlayerName、\nこの人の傷は暗鬼が付けたものじゃないみたい…",
  ui_story_3_7_20_dialog_content = "誰がこんなことを…",
  ui_story_3_7_22_dialog_content = "ターゲット・モンドル発見！",
  ui_story_3_7_23_dialog_content = "捕獲命令の執行準備！",
  ui_story_3_7_24_dialog_content = "フェネクス、フェニィ…",
  ui_story_3_7_25_dialog_content = "君は、後ろへ！",
  ui_story_3_7_26_dialog_content = "その人のことは任せたわ、PlayerName！戦闘は私たちが！",
  ui_story_3_7_27_dialog_content = "フェネクス、フェニィ…",
  ui_story_3_7_28_dialog_content = "ごめん…結局、僕は無力だ…",
  ui_story_3_7_29_dialog_content = "あの二人は暗鬼じゃないみたいだけど、一体どういうこと？",
  ui_story_3_7_30_dialog_content = "もともと僕の護衛だったんだ。この巨像の防衛装置だよ。",
  ui_story_3_7_31_dialog_content = "じゃあ、どうしてあなたを攻撃してくるの？",
  ui_story_3_7_32_dialog_content = "彼女だ…強大な力で、直接僕の権限を乗っ取ったんだ…",
  ui_story_3_7_33_dialog_content = "なんてこと…",
  ui_story_3_7_34_dialog_content = "ひどい話だわ。本当に気の毒…",
  ui_story_3_7_35_dialog_content = "すべてがあの時と同じだなんて…思いもしなかった…",
  ui_story_3_7_36_dialog_content = "ねぇ、君の名前は？",
  ui_story_3_7_37_dialog_content = "僕はセクレペトスの主、モンドル。",
  ui_story_3_7_38_dialog_content = "セクレペトス…聞き覚えがある名前です。\n残念ながら、私もほとんどのことを覚えていませんが…",
  ui_story_3_7_40_dialog_content = "あの日、生き残った巨像たちは「火種」を守るためにお互い連絡を絶ったんだ。",
  ui_story_3_7_41_dialog_content = "こんなにも長い間、ソラヴァンは君を守ってきたんだね。良かった、本当に良かった…",
  ui_story_3_7_42_dialog_content = "ずっとここにいたの？他の空の末裔は？",
  ui_story_3_7_43_dialog_content = "どうしてこんな姿に？グリードって何…？",
  ui_story_3_7_44_dialog_content = "ゴホッ…僕は…ゴホゴホ…",
  ui_story_3_7_45_dialog_content = "この人の傷…PlayerName、まず休ませてあげて…",
  ui_story_3_7_46_dialog_content = "すまない…僕は君たちのようにはいかなくてね…PlayerName、ソラヴァン…",
  ui_story_3_7_47_dialog_content = "君はまだ生きている。それはつまり、ソラヴァンが空の末裔を\n守るという責務を立派に果たしたということ…",
  ui_story_3_7_48_dialog_content = "だけど僕は、唯一の使命を果たせていない…",
  ui_story_3_7_49_dialog_content = "ごめん、何のこと？",
  ui_story_3_7_50_dialog_content = "PlayerName、ソラヴァンから聞いていないのかい？",
  ui_story_3_7_51_dialog_content = "…残念ながら、私の記憶は墜落時に破損しています。",
  ui_story_3_7_52_dialog_content = "PlayerNameを守るという命令に従う以外、他のことは私も…",
  ui_story_3_7_53_dialog_content = "ソラヴァンはあの日、損傷してしまったんだ。",
  ui_story_3_7_54_dialog_content = "そうだったのか…ゴホッ…君たちの会話を感知したよ…",
  ui_story_3_7_55_dialog_content = "不幸とも言えるし、その方が幸運だったとも言える…",
  ui_story_3_7_56_dialog_content = "ここで一体何があったの？",
  ui_story_3_7_57_dialog_content = "セクレペトス…この巨像には「<color=#FFB400>ブレーンパーツ</color>」という名の重要な部品があるんだ…",
  ui_story_3_7_A1_dialog_content = "中には多くの情報が保存されている。\n空の末裔たちの史料から、光霊世界の書物まで…",
  ui_story_3_7_58_dialog_content = "この上ない光の讃歌や、深淵に到る囁きも…",
  ui_story_3_7_60_dialog_content = "でも、グリード…そう、スーモアが必要としているのは、\n他の誰の目にも留まらない情報…",
  ui_story_3_7_61_dialog_content = "やっぱりスーモアがここに！？",
  ui_story_3_7_62_dialog_content = "ああ。今この時も、彼女はここの中心部に向かっている。\n「ブレーンパーツ」を強奪するためにね。",
  ui_story_3_7_A2_dialog_content = "ブレーンパーツを使えば…いや、だめだ、これだけは絶対に明かすことはできない…！",
  ui_story_3_7_63_dialog_content = "それなら僕たちがスーモアを阻止するよ！バイス、手伝って！",
  ui_story_3_7_64_dialog_content = "この人に案内してもらいましょう。\n私だって、この手でシェルター28号を壊した黒幕を倒したいもの！",
  ui_story_3_7_65_dialog_content = "あなたもこの日を待っていた、でしょ？PlayerName。",
  ui_story_3_7_A3_dialog_content = "そうだね。すべてを知れるときが待ち切れないよ…",
  ui_story_3_7_A4_dialog_content = "気を付けるんだ、PlayerName…彼女は、彼女は…",
  ui_story_3_7_66_dialog_content = "ゴホゴホ、ゴホッ…",
  ui_story_3_7_67_dialog_content = "状態がどんどんひどくなってるみたいだね。どうしたら…",
  ui_story_3_7_68_dialog_content = "ここに置いてはいけないわ、PlayerName。\nでも、私たちは先に進まないと…",
  ui_story_3_7_69_dialog_content = "…",
  ui_story_3_7_70_dialog_content = "心配はしないでくれ。",
  ui_story_3_7_71_dialog_content = "…僕は大丈夫だ。案内するよ。そうした方が効率がいい…",
  ui_story_3_7_72_dialog_content = "それにセクレペトスの主として、彼女が「ブレーンパーツ」を\n奪い去ることを阻止するのは、僕の…責務だ…",
  ui_story_3_7_73_dialog_content = "ありがとう、モンドル。\nすべてが終わったら、空の末裔にまつわること、全部教えてよ！",
  ui_story_3_7_74_dialog_content = "もちろんさ、PlayerName。約束しよう…\n君にゆっくり語ってあげるよ、天空ノ谷の日々を…",
  ui_story_3_7_75_dialog_content = "じゃあ、行こう。案内して、モンドル！",
  ui_story_3_7_76_dialog_content = "スーモアを阻止するんだ！",
  ui_story_3_9_A1_dialog_content = "（僕は何をしているんだ…？逃げるなら明らかに今がチャンスだ。また引き返したりして…）",
  ui_story_3_9_A2_dialog_content = "（どうせあんな力には勝てない、そうだ…なぜ頑張る必要が…）",
  ui_story_3_9_A3_dialog_content = "（逃げるんだ、モンドル、無意味な「責務」なんか捨てて、自分の命のために…）",
  ui_story_3_9_2_dialog_content = "僕の…僕自身の命のため…か。",
  ui_story_3_9_3_dialog_content = "どうして止まったの？もう着いた？",
  ui_story_3_9_4_dialog_content = "君たちは…本当によく考えたのか？今逃げればまだ間に合う…",
  ui_story_3_9_5_dialog_content = "スーモアは普通の敵じゃない。フェネクスとフェニィにされたことを見てみろ…",
  ui_story_3_9_6_dialog_content = "ずっと僕を守ってくれていた彼らでさえ、今では僕に刃を向けている…",
  ui_story_3_9_7_dialog_content = "スーモアの能力は、私にも計り知れないところがあります。",
  ui_story_3_9_8_dialog_content = "PlayerName、戦闘能力のない空の末裔である君が、\nなぜ彼女と真正面から戦いたいと思うんだい？",
  ui_story_3_9_10_dialog_content = "僕はずっとスーモアを探していたんだ。\nいろいろ聞きたいことがあるから。シェルター28号や、17年前のこととか…",
  ui_story_3_9_A4_dialog_content = "それに今、またやりたい放題して、僕と同じ一族の君を傷つけてる…",
  ui_story_3_9_13_dialog_content = "このままじゃ引き下がれないよ！絶対に止めないと！",
  ui_story_3_9_14_dialog_content = "…それに、逃げるって言うのは簡単だけど、どこまで逃げればいいの？",
  ui_story_3_9_15_dialog_content = "もう戻れない場所っていうのもあるんだよ、モンドル。\nそれで、進んだ先に待ち構えているのが鉄の壁だったなら…",
  ui_story_3_9_A5_dialog_content = "仲間と一緒に、頭からぶつかって血を流すまでだよ。",
  ui_story_3_9_16_dialog_content = "君の言いたいことはわかるよ。そうだね、僕は何を考えているんだろう…",
  ui_story_3_9_18_dialog_content = "天空ノ谷は壊滅した。家族も、友達も、みな暗鬼にやられてしまった。",
  ui_story_3_9_19_dialog_content = "僕だけが、体が弱く臆病だった僕だけが、\n生き残るために…セクレペトスを連れて…逃げた…",
  ui_story_3_9_20_dialog_content = "それなのに今、また逃げようとしている。",
  ui_story_3_9_21_dialog_content = "モンドルさん…",
  ui_story_3_9_22_dialog_content = "もし前に進まなければ、これまでと何も変わらない…僕たちは…",
  ui_story_3_9_23_dialog_content = "モンドル！",
  ui_story_3_9_24_dialog_content = "ああ…僕の…",
  ui_story_3_9_25_dialog_content = "な…どうして急に苦しみだしたの！？",
  ui_story_3_9_26_dialog_content = "もう始まったのか…スーモア？分かってるぞ、<color=#FFB400>もう手に入れたんだな</color>…！",
  ui_story_3_9_27_dialog_content = "君の強大な闇の力を感じる。セクレペトスさえ完全に飲み込む、闇の力を！",
  ui_story_3_9_28_dialog_content = "最後に差すひとすじの光さえも、覆い隠してしまえるような…",
  ui_story_3_9_29_dialog_content = "僕にできることはないの、モンドル！？",
  ui_story_3_9_30_dialog_content = "…心配は…いらないさ。こうなったら、逆に最後に残った恐れまで消えてしまうよ…",
  ui_story_3_9_A8_dialog_content = "行こう、PlayerName。それから君の仲間たちも。僕について来てくれ！",
  ui_story_3_9_A9_dialog_content = "まずは目の前の暗鬼を片づけて、そのまま闇のもっとも深い場所へ…",
  ui_story_3_9_A10_dialog_content = "後ろもだ、気を付けて！敵が襲ってくる！",
  ui_story_3_9_31_dialog_content = "モンドル、私の親愛なる兄弟。無駄なあがきはやめなさい。",
  ui_story_3_9_32_dialog_content = "どれほど奥に隠したところで、私には見つけられるのよ。\nこの、「<color=#FFB400>ブレーンパーツ</color>」を！",
  ui_story_3_9_33_dialog_content = "簡単すぎたわね。少し物足りないぐらいだわ。",
  ui_story_3_9_34_dialog_content = "さあ、あなたが持っている秘密を私に見せなさい…",
  ui_story_3_9_A11_dialog_content = "…ふん、やっぱり暗号化されているわね。時間がかかりそうだわ…",
  ui_story_3_9_35_dialog_content = "スーモア様、我が主がお待ちでございます…",
  ui_story_3_9_36_dialog_content = "いつまでもたもたしているつもり？",
  ui_story_3_9_37_dialog_content = "すこし手こずっているだけよ、すぐに終わるわ…",
  ui_story_3_9_38_dialog_content = "もうすぐ全てのデータを完全に読み取れるわ、「あの方法」も…",
  ui_story_3_9_39_dialog_content = "そうすれば、秘密が私を通じて<color=#FFB400>黒い巨像</color>に融け込み、\n進化の船の礎に打ち込む釘となるわ！",
  ui_story_3_9_41_dialog_content = "…もう少しだけ時間をあげるわ、スーモア。",
  ui_story_3_9_42_dialog_content = "――『行きなさい、同胞たちよ。』",
  ui_story_3_9_43_dialog_content = "ちょっと大げさすぎない？",
  ui_story_3_9_44_dialog_content = "これでも足りないわ。暗鬼どもが言うには、\nモンドルから奪った「玩具」が叩き壊されてしまったそうね…",
  ui_story_3_9_45_dialog_content = "あのソラヴァンの持ち主――あなたの同族に。",
  ui_story_3_9_47_dialog_content = "ちょうどいいでしょ？\n必要な情報をハックし終わったら、まとめて片付けてやるわ。",
  ui_story_3_9_48_dialog_content = "昔の借りなんかいつでも返せるわ。計画は計画よ、スーモア。\n余計な面倒ごとを起こさないように気を付けて。",
  ui_story_3_9_50_dialog_content = "私がガマンできると思う…？\nあの時取り逃がしたやつがこんなに近くにいるのに、オアズケなんて？",
  ui_story_3_9_51_dialog_content = "混乱、無秩序、行きあたりばったり。そういうのは嫌いなの。",
  ui_story_3_9_52_dialog_content = "それから、争いごとも。程度の低い趣味なんか、興味がないの。",
  ui_story_3_9_53_dialog_content = "…",
  ui_story_3_9_54_dialog_content = "いいわ、おしゃべりはここまで。",
  ui_story_3_9_56_dialog_content = "タブハッド！",
  ui_story_3_9_57_dialog_content = "闇の中でずっとお待ちしておりました…いかがいたしましょうか、主様？",
  ui_story_3_9_58_dialog_content = "自分の判断で行動しなさい。",
  ui_story_3_9_59_dialog_content = "はっ…主様。",
  ui_story_3_9_61_dialog_content = "我が手で自らやつらを引き裂き、\n脆弱な光を果て無き闇に溶け込ませてやりましょう。",
  ui_story_3_9_A12_dialog_content = "PlayerName、感じる？\n暗鬼たちがいっせいにこちらに向かって来てるみたい…",
  ui_story_3_9_A13_dialog_content = "うん…続々と集まってきているみたいだ。\nでも、この程度の敵に阻まれるわけにはいかない。そうだよね？",
  ui_story_3_9_A14_dialog_content = "もちろん、前進よ！途中の暗鬼なんか全部片付ければいいわ！",
  ui_story_3_12_2_dialog_content = "着いたよ。",
  ui_story_3_12_3_dialog_content = "ここなの？「ブレーンパーツ」がある場所って…",
  ui_story_3_12_4_dialog_content = "ここがそうだ…スーモアに気を付けて…",
  ui_story_3_12_5_dialog_content = "モンドル、一緒に全てを終わらせよう！",
  ui_story_3_12_6_dialog_content = "ありがとう、PlayerName。一緒に食い止めよう…",
  ui_story_3_12_7_dialog_content = "でも、呼吸…あなた、落ち着かないと、体が…",
  ui_story_3_12_9_dialog_content = "…気にしないで。これは<color=#FFB400>闇の力</color>…\n自分じゃコントロールできないんだ。もう僕の全身に広がっている。",
  ui_story_3_12_10_dialog_content = "い、一体どういうこと？",
  ui_story_3_12_12_dialog_content = "生きるためだよ…17年前のあの日、僕は生きるために<color=#FFB400>暗鬼の力</color>を受け入れた…",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>スーモアのように</color>。でも、僕の体は壊れていくだけ…",
  ui_story_3_12_A2_dialog_content = "「信仰」が足りなかったせい？それとも、\n僕自身がこの「かりそめの命」を受け入れられなかったせいか…",
  ui_story_3_12_15_dialog_content = "モンドル、苦しみは刹那に終わるものにすぎません。\n後悔するような決断をしてはなりません…",
  ui_story_3_12_16_dialog_content = "先生…申し訳ありません、もう遅いんです。僕は…僕は、生きたい…",
  ui_story_3_12_17_dialog_content = "生きるために暗鬼の力を受け入れた？どうして…",
  ui_story_3_12_18_dialog_content = "皮肉だろう？こんな怪物になっても、僕は「セクレペトス」の責務を守ろうとしている…",
  ui_story_3_12_A3_dialog_content = "僕は一体誰なんだ…僕は一体、何だったんだ…",
  ui_story_3_12_A4_dialog_content = "まだチャンスはあるよ。スーモアを倒して、きっと君を助ける方法を見つけるから！",
  ui_story_3_12_A5_dialog_content = "その必要はないよ、もう手遅れさ…\nけど、運命とは実に神秘的で、謎に満ちたものだね。",
  ui_story_3_12_19_dialog_content = "僕は今まで闇の力に頼って、この日の当たらない地下に身を隠し、ずっと眠っていた…",
  ui_story_3_12_20_dialog_content = "そして今日も、僕は以前と同じように、\n臆病な僕のまま背中を向けて逃げるんだと思っていた。",
  ui_story_3_12_21_dialog_content = "闇の片隅に閉じこもり、これからも退屈に命をつなぐという運命に身を委ねて…",
  ui_story_3_12_22_dialog_content = "でも、君たちに出会ってしまった！\nきっと、僕も一度くらい勇敢になるべきということなんだろう…",
  ui_story_3_12_23_dialog_content = "今度は逃げたりしない！僕たちは一緒に、\n粉々に砕かれた運命から立ち上がって、未来を救うんだ！",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>セクレペトス遺跡の外</color>",
  ui_story_3_13_2_dialog_content = "タブハッド、あいつらは来たの？",
  ui_story_3_13_3_dialog_content = "さまよえる魂が3つ。そのうちひとつはすでに風前の灯火、虫の息です。",
  ui_story_3_13_4_dialog_content = "わかった。好きにしなさい。",
  ui_story_3_13_5_dialog_content = "はっ。1人残らず片付けてまいります。\n極光の下、「日蝕」のみが永遠なり――母上も、ご照覧あれ！",
  ui_story_3_13_6_dialog_content = "こいつなの？",
  ui_story_3_13_8_dialog_content = "ずいぶんのんびりやってきたものだな…\n貴様らはいいところをほとんど見逃したぞ。",
  ui_story_3_13_9_dialog_content = "まさか、ここにはこいつだけ？",
  ui_story_3_13_10_dialog_content = "我ひとりで十分、こと足りるということだ。",
  ui_story_3_13_11_dialog_content = "十分だって？",
  ui_story_3_13_12_dialog_content = "PlayerName…空の末裔の生き残りよ、貴様はそこの光霊とは違う。\n貴様にはもっと相応しい道がある。",
  ui_story_3_13_13_dialog_content = "どうして…PlayerNameの名前を知ってるの？",
  ui_story_3_13_14_dialog_content = "あらゆる知識、あらゆる世界、あらゆる未来、すべてがこちらにあるからだ。\nPlayerName、貴様はそういうものにずっと憧れていたのではないか？",
  ui_story_3_13_15_dialog_content = "隠すな、PlayerName。貴様ら空の末裔が心の中で渇望していることは\n分かっている、貴様も同じだ…",
  ui_story_3_13_16_dialog_content = "PlayerName？",
  ui_story_3_13_17_dialog_content = "貴様が欲しているのは強大な力。\n々しい光霊の、そのまた後ろに立っていることではない…",
  ui_story_3_13_18_dialog_content = "僕は…",
  ui_story_3_13_19_dialog_content = "近くへ来い、そうだ、もっと近くへ。\n貴様も我が主と同じように、<color=#FFB400>日蝕に抱かれるのだ</color>！",
  ui_story_3_13_20_dialog_content = "日蝕…？",
  ui_story_3_13_21_dialog_content = "バカなことを考えるな！",
  ui_story_3_13_22_dialog_content = "…我を忘れた野良犬め、また尻尾をひきずって戻ってきたのか。",
  ui_story_3_13_23_dialog_content = "見たくなかった亡霊を見た気分か？\nお前の主はどこだ！あいつはどこだ！",
  ui_story_3_13_A1_dialog_content = "（「ブレーンパーツ」はない、スーモアもいない！）",
  ui_story_3_13_24_dialog_content = "まあ、少し意外ではあったな、モンドル。",
  ui_story_3_13_25_dialog_content = "汚れた子犬のように巨像に身を隠し、一族が殺されるのをその目にしながら、\n立ち上がることもできなかった貴様が…",
  ui_story_3_13_26_dialog_content = "閉じこもり、現実を見ようとしなかった貴様が、\nまさか自ら、あのお方に歯向かう日が来ようとは。",
  ui_story_3_13_27_dialog_content = "だが、哀れだな。お前の震える姿、指先まで弱さと\n頼りなさが透けて見えるぞ、笑わせてくれる。",
  ui_story_3_13_28_dialog_content = "いい加減にして！モンドルから離れろ！",
  ui_story_3_13_29_dialog_content = "大丈夫？",
  ui_story_3_13_30_dialog_content = "すまない、ど、どうやら、真の元凶はすでに逃げてしまったみたいだ…",
  ui_story_3_13_31_dialog_content = "「ブレーンパーツ」まで奪われて――うう！僕も、もうすぐ限界だ…",
  ui_story_3_13_32_dialog_content = "まだだ…まだもう一つやらねばならないことが…",
  ui_story_3_13_33_dialog_content = "まず休んで、あとのことは私たちに任せて！",
  ui_story_3_13_34_dialog_content = "滑稽だな、死にゆく者が死にゆく者に同情するとは。",
  ui_story_3_13_35_dialog_content = "PlayerName！考えすぎちゃダメ！",
  ui_story_3_13_36_dialog_content = "指揮は――あなたに任せるわ！",
  ui_story_3_13_37_dialog_content = "終わったのか…",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>その瞬間、周囲は異様なほど静かだった</color>",
  ui_story_3_13_39_dialog_content = "…いや、まだだ！闇の力が集まっている！攻撃が来る、気を付けるんだ！",
  ui_story_3_13_40_dialog_content = "我はここで終わらぬ！偉大なる使命のため、タブハッドの覚悟を見るがいい！",
  ui_story_3_13_41_dialog_content = "闇よ、あの空の末裔を飲み込め――！！",
  ui_story_3_13_42_dialog_content = "まずい、やられる…！",
  ui_story_3_13_43_dialog_content = "啓光の名にかけて…絶対に、そう簡単に傷つけさせたりはしない！！",
  ui_story_3_13_44_dialog_content = "よくぞ言いました、中尉！！",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>ザンッ――！</color>",
  ui_story_3_13_F1_dialog_content = "グアア！！",
  ui_story_3_13_46_dialog_content = "ちょ、長官！",
  ui_story_3_13_47_dialog_content = "ちょうどいい時に来たようですね。",
  ui_story_3_13_48_dialog_content = "『…い…卑しく、汚らわしく、無知な…弱…者…め…』",
  ui_story_3_13_49_dialog_content = "暗鬼が…桜の花になって散った？",
  ui_story_3_13_50_dialog_content = "救援、感謝します！",
  ui_story_3_13_51_dialog_content = "バイス中尉、あなたの行動は啓光の規律を著しく乱すものです。\nきわめて危険な行為だったという自覚はあるのですか？",
  ui_story_3_13_52_dialog_content = "…",
  ui_story_3_13_53_dialog_content = "バイス中尉！",
  ui_story_3_13_54_dialog_content = "はっ、はい！",
  ui_story_3_13_55_dialog_content = "戻ったら少なくとも5000字の報告書を提出しなさい。\nこの巨像に関して、それからこの戦えないという空の末裔について。",
  ui_story_3_13_56_dialog_content = "空の末裔だって、巨像の操縦と、戦いの指揮はできます！",
  ui_story_3_13_57_dialog_content = "既に分かっていることを繰り返さなくても結構です。",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>ボン――！</color>",
  ui_story_3_13_59_dialog_content = "モンドル、体が！",
  ui_story_3_13_60_dialog_content = "まずい！まさか…",
  ui_story_3_13_61_dialog_content = "どうやら…僕が最期を迎える運命は決まっていたか…\nあの時、僕がした選択には、責任を持たないとな…",
  ui_story_3_13_62_dialog_content = "だめだよ…僕たちなら助けられる！バイス、そうだよね！？",
  ui_story_3_13_63_dialog_content = "PlayerName、私には…",
  ui_story_3_13_64_dialog_content = "いいんだ。これは僕が選んだ道だ…僕は…\nもっと早くに迎えるべきだった死が、来たというだけ…",
  ui_story_3_13_A2_dialog_content = "今は僕の生き死によりも重要なことがある、PlayerName。",
  ui_story_3_13_A3_dialog_content = "こうなってしまった以上、僕も秘密を隠し続ける必要がなくなった…",
  ui_story_3_13_65_dialog_content = "「ブレーンパーツ」の話は覚えてるかい？\n<color=#FFB400>これから言うことをしっかり覚えておくんだ</color>…",
  ui_story_3_13_A4_dialog_content = "もともと、巨像にはそれぞれの特性があった。\nけど、戦闘能力を持つ巨像は一体としていなかった。",
  ui_story_3_13_A5_dialog_content = "でも、グリードだけは違う…あれは唯一、\n理論上では攻撃能力を持っている巨像なんだ…",
  ui_story_3_13_66_dialog_content = "幸い、今のグリードはまだ完全体じゃない。",
  ui_story_3_13_67_dialog_content = "あれの主――スーモアは、グリードを完全体にする方法を探している。\nそのためには…",
  ui_story_3_13_X67_dialog_content = "「<color=#FFB400>ブレーンパーツ</color>」",
  ui_story_3_13_X68_dialog_content = "「<color=#FFB400>自己成長ユニット</color>」",
  ui_story_3_13_X69_dialog_content = "「<color=#FFB400>射撃統制モジュール</color>」",
  ui_story_3_13_X70_dialog_content = "…3つのパーツが必要だ。",
  ui_story_3_13_A6_dialog_content = "スーモアはまず「ブレーンパーツ」を探していた。\nそれさえあれば残り2つの位置も分かるからだ。",
  ui_story_3_13_68_dialog_content = "全てを凌駕する力を手に入れるために、彼女はあらゆる対価を惜しまないだろう。\n全てのパーツを奪いに行くはずだ…",
  ui_story_3_13_69_dialog_content = "でも、あなたが持っていた「ブレーンパーツ」はもう奪われて…",
  ui_story_3_13_70_dialog_content = "いや、スーモアの思い通りにはならない。あのパーツには仕掛けがあるんだ。\n僕が死ねば、防衛プログラムが起動する。彼女への最後の「プレゼント」さ…",
  ui_story_3_13_71_dialog_content = "モンドル、きっと他にも方法があるはずだよ…少し休んで！\n体調さえ回復すれば、いくらでも時間はある！",
  ui_story_3_13_72_dialog_content = "一緒にスーモアを止めよう！それで、一緒に故郷に帰ろう！",
  ui_story_3_13_73_dialog_content = "僕はどこへも行ったことがないんだ。天空ノ谷の話を聞かせて…",
  ui_story_3_13_74_dialog_content = "残念だけど、だめだ。\nその役目はソラヴァンに託すよ…君は、他の同胞を探しに行くんだ…",
  ui_story_3_13_75_dialog_content = "そんな！モンドル！",
  ui_story_3_13_A7_dialog_content = "静かに、聞いてくれ。もう時間がない…",
  ui_story_3_13_76_dialog_content = "僕が死んだら、スーモアは光霊の「最後の都」…<color=#FFB400>白夜城</color>へ向かうはずだ…",
  ui_story_3_13_A8_dialog_content = "あそこにはもう一つの「ブレーンパーツ」がある！\nそう、ブレーンパーツは、1つだけじゃない…",
  ui_story_3_13_A9_dialog_content = "危機が差し迫っていることを…白夜城に伝えるんだ、PlayerName…",
  ui_story_3_13_A10_dialog_content = "あそこの光霊はおそらく、「ブレーンパーツ」の重要性を、認識していない…",
  ui_story_3_13_77_dialog_content = "モンドル！お願いだよ！僕をひとりにしないで！",
  ui_story_3_13_78_dialog_content = "PlayerName、僕だって君と、それから新しい友達と、一緒にいたいさ…",
  ui_story_3_13_79_dialog_content = "でも、今度こそ逃げたくないんだ。スーモアの思い通りにさせるわけにはいかない…",
  ui_story_3_13_80_dialog_content = "少なくとも僕の「ブレーンパーツ」を、手に入れられると思ったら大間違いだ…\n「臆病者」の最後の抵抗…掴むがいいさ、スーモア…",
  ui_story_3_13_81_dialog_content = "モンドル…",
  ui_story_3_13_82_dialog_content = "本当にきれいだ…",
  ui_story_3_13_83_dialog_content = "…",
  ui_story_3_13_84_dialog_content = "あの龍は…すごくきれいだね。",
  ui_story_3_13_F2_dialog_content = "あれは…ヒイロ長官の<color=#FFB400>櫻龍</color>よ。",
  ui_story_3_13_F3_dialog_content = "世界にこんな色があったなんて…もっと見ていたいな…",
  ui_story_3_13_85_dialog_content = "この数年…闇の中に隠れていたから、空の色だって忘れてしまった…",
  ui_story_3_13_86_dialog_content = "PlayerName！ヒイロ長官！…本当に助ける術はないの！？\nただ、黙って見ているなんて…",
  ui_story_3_13_F4_dialog_content = "…",
  ui_story_3_13_F5_dialog_content = "…",
  ui_story_3_13_87_dialog_content = "PlayerName、もっと君と話がしたい…\nソラヴァン、また昔のように、皆と一緒に…",
  ui_story_3_13_88_dialog_content = "もう一度空を…見たかった…",
  ui_story_3_13_89_dialog_content = "ソラヴァン！",
  ui_story_3_13_90_dialog_content = "はい、PlayerName。",
  ui_story_3_13_91_dialog_content = "感知を！モンドルと君をつなげて！空の色を…見せてあげて…",
  ui_story_3_13_92_dialog_content = "…はい。",
  ui_story_3_13_93_dialog_content = "あぁ、久しぶりの…青空だ…",
  ui_story_3_13_94_dialog_content = "モンドル！僕とソラヴァンと一緒に旅しよう！",
  ui_story_3_13_95_dialog_content = "ソラヴァンがずっと君の耳や目になって、\n今も、これからも、雲の上から景色を目に焼き付けていくよ…",
  ui_story_3_13_96_dialog_content = "これが…死か…思っていたのと少し…違うな…孤独で…",
  ui_story_3_13_97_dialog_content = "一人じゃないよ、マスター。",
  ui_story_3_13_98_dialog_content = "この声は！？",
  ui_story_3_13_99_dialog_content = "僕たちがここにいる。",
  ui_story_3_13_100_dialog_content = "ご主人様、最後までお側に居ります。",
  ui_story_3_13_101_dialog_content = "フェニィ…フェ…ネ…ク…",
  ui_story_3_13_103_dialog_content = "モンドル！",
  ui_story_3_13_104_dialog_content = "…",
  ui_story_3_13_105_dialog_content = "…",
  ui_story_3_13_106_dialog_content = "<size=45>スーモア…「プレゼント」、受け取るがいいさ…</size>",
  ui_story_3_13_107_dialog_content = "え？",
  ui_story_3_13_108_dialog_content = "「ブレーンパーツ」が…<color=#FFB400>分解してる</color>！？まずい！！",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>モ、ン、ド、ル――</anim>",
  ui_story_3_13_111_dialog_content = "無様ね、スーモア。アテが外れたみたいじゃない。",
  ui_story_3_13_112_dialog_content = "あのモンドルが、やってくれたわね…これじゃもう使い物にならないわ。",
  ui_story_3_13_113_dialog_content = "あの臆病者が、あの雑魚が、よくも…",
  ui_story_3_13_114_dialog_content = "…フフ…ハハハハ！それでこそ私の同胞よ！",
  ui_story_3_13_115_dialog_content = "長年あいつを臆病者と侮りすぎていたわ。\n死ぬ前にこんなことを企む勇気があったなんて、考えもしなかったもの。",
  ui_story_3_13_116_dialog_content = "で、何の情報も入手できなかったとか、言わないでよ？",
  ui_story_3_13_118_dialog_content = "当然でしょ…断片的ではあるけれど、確かに新しい情報を見つけたわ…",
  ui_story_3_13_120_dialog_content = "同じような「ブレーンパーツ」が、<color=#FFB400>白夜城</color>にもう1つある。",
  ui_story_3_13_121_dialog_content = "しかもおバカな光霊たちは、それがもつ意味を全く知らないみたいね…",
  ui_story_3_13_122_dialog_content = "白夜城は好き勝手に入れる場所じゃないわ。\nどうやってあんたの尻拭いをするか、考えなきゃいけないようね…",
  ui_story_3_13_123_dialog_content = "見てなさい、モンドル。あなたの死にきれない目でしっかりと…\n誰も私を止められない…",
  ui_story_3_13_124_dialog_content = "あなたがした全てのことには何の意味もなかったって、分からせてあげるわ。",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>白夜城・資料館</color>",
  ui_story_3_14_1_dialog_content = "まったく…今日もまたずいぶんと多いな。",
  ui_story_3_14_2_dialog_content = "まったくです。それに何もかもごちゃ混ぜですね。ん？これは…",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>ガシャン！</color>",
  ui_story_3_14_4_dialog_content = "おっと！",
  ui_story_3_14_5_dialog_content = "大丈夫ですか？どこかに当たりましたか？",
  ui_story_3_14_6_dialog_content = "大丈夫だ。どうした、こんなものもちゃんと運べないのか！？",
  ui_story_3_14_7_dialog_content = "す、すみません、今日が初めてで…",
  ui_story_3_14_8_dialog_content = "うわあ！こ、これ！お前！",
  ui_story_3_14_9_dialog_content = "すみません、本当にすみません、わざとじゃないんです…",
  ui_story_3_14_10_dialog_content = "おい！どうしてよりによって<color=#FFB400>コレ</color>を落とすんだ！貴重な物なんだぞ！",
  ui_story_3_14_11_dialog_content = "じ…自分が拾います。",
  ui_story_3_14_12_dialog_content = "いや、俺がやるよ。\n何かは知らんが、一目で高い骨董品だってことはわかる。",
  ui_story_3_14_13_dialog_content = "足音が聞こえてきた",
  ui_story_3_14_14_dialog_content = "お前たち！勤務中は私語を慎め！自分の仕事に集中しろ！",
  ui_story_3_14_15_dialog_content = "中隊長！わ、我々は資料館の物品整理中でして、間もなく半分終わります…",
  ui_story_3_14_16_dialog_content = "もういい、下がれ。",
  ui_story_3_14_17_dialog_content = "はっ！中隊長！",
  ui_story_3_14_18_dialog_content = "はっ！中隊長！",
  ui_story_3_14_A1_dialog_content = "…間違いない、<color=#FFB400>あのお方</color>がおっしゃっていたものと同じだ。",
  ui_story_3_14_19_dialog_content = "お前は貴重なのに、白夜城のお偉いさんたちはお前のことを、\nただの骨董品だと思っているようだな。",
  ui_story_3_14_20_dialog_content = "しかし、お前の<color=#FFB400>本当の価値</color>を知る者がいる…",
  ui_story_3_14_B1_dialog_content = "中隊長！長官から、報告に戻れとのことです！",
  ui_story_3_14_B2_dialog_content = "…",
  ui_story_3_14_B3_dialog_content = "わかった。では行こう。",
  ui_story_4_1_1_dialog_content = "「<color=#FFB400>ブレーンパーツ</color>」、「<color=#FFB400>自己成長ユニット</color>」、\n「<color=#FFB400>射撃統制モジュール</color>」…いったいどんな形をしてるのかしら？",
  ui_story_4_1_2_dialog_content = "モンドルがくれた情報はあまりにも少ないわ。\n白夜城にもう1つ「ブレーンパーツ」があるっていうだけじゃ…",
  ui_story_4_1_3_dialog_content = "もう一体の巨像がいるという可能性もありますね。",
  ui_story_4_1_4_dialog_content = "だからこそ、相手の計画がどうであっても、先手を打たないと！",
  ui_story_4_1_5_dialog_content = "白夜城へ直行するの？で、その後は？",
  ui_story_4_1_6_option_content = "でたとこ勝負だ！",
  ui_story_4_1_7_option_content = "実はまだ決めてない…",
  ui_story_4_1_8_dialog_content = "…PlayerName、それは無謀すぎるわ…",
  ui_story_4_1_9_dialog_content = "私たち、相手について何も知らない。\n相手の強さも目的も、姿だって見たことがないのよ。",
  ui_story_4_1_10_dialog_content = "ずいぶん正直なのね…",
  ui_story_4_1_11_dialog_content = "でも、相手のことが全く分からない状況じゃ、\n戦略も立てようがないものね。",
  ui_story_4_1_12_dialog_content = "相手の強さや目的どころか、姿だって見たことがないし。",
  ui_story_4_1_13_dialog_content = "それに、白夜城は私たち啓光とは違って…とても面倒な場所なの…",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>何かいやなことでも思い出したのだろうか、バイスは複雑な表情を浮かべた</color>",
  ui_story_4_1_15_dialog_content = "でもね、PlayerName。ナビゲーターはあなたよ。ここはあなたが決めて。",
  ui_story_4_1_16_dialog_content = "白夜城に行って確かめたい。",
  ui_story_4_1_17_dialog_content = "すごく危険だってことは分かってるよ、バイス。でも…",
  ui_story_4_1_18_dialog_content = "17年前の真相をつきとめる、唯一の手がかりなんだ…",
  ui_story_4_1_19_dialog_content = "仕方ないわね…ただし！まずはヒイロ長官に報告させて。\n白夜城に行くとなると、あなたが想像しているよりはるかに複雑なのよ…",
  ui_story_4_1_20_dialog_content = "どうやら、自分の上司の存在はまだ忘れていないようですね。",
  ui_story_4_1_21_dialog_content = "あ！ちょ、長官、まだいたんですか！",
  ui_story_4_1_22_dialog_content = "最初からいましたよ、中尉。PlayerName、あなたの同胞のことは残念です。\nしかし、白夜城に関する情報については、慎重に対応せねばなりません。",
  ui_story_4_1_23_dialog_content = "慎重に対応…どういうことですか？",
  ui_story_4_1_24_dialog_content = "まだ調査していませんが、モンドルの言葉だけでは証拠にはなりません。\n上級暗鬼も度々出現しています。軽率な行動は控えるべきでしょう。",
  ui_story_4_1_25_dialog_content = "でも、時間がないんだ。もし本当に何か起きた時は…\nソラヴァン！ソラヴァンが僕たちを守ってくれる！",
  ui_story_4_1_26_dialog_content = "…では、率直に言わせてもらいますよ、PlayerName。",
  ui_story_4_1_27_dialog_content = "私は当初から巨像に注目し、カロンから基本データも入手しています。",
  ui_story_4_1_A1_dialog_content = "かつて使われていた巨像の評価基準に基づくと…",
  ui_story_4_1_28_dialog_content = "あなたのソラヴァンは<color=#FFB400>レベル6</color>です。",
  ui_story_4_1_29_dialog_content = "…",
  ui_story_4_1_30_dialog_content = "えっ、そんなに高いんですか？さすがソラヴァン！",
  ui_story_4_1_31_dialog_content = "…最高はレベル1です。数字が大きくなるほど性能は下がります。",
  ui_story_4_1_32_dialog_content = "…？",
  ui_story_4_1_33_dialog_content = "じゃあ最低は？",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>レベル6</color>です。",
  ui_story_4_1_35_dialog_content = "…！？",
  ui_story_4_1_36_dialog_content = "ソラヴァン！「私は天空級の巨像だ」って前に言ってたよね！？",
  ui_story_4_1_37_dialog_content = "…あれは生きる自信をつけてもらうための、やむを得ない嘘でした。",
  ui_story_4_1_A2_dialog_content = "そもそも「天空級」などと言う分類自体が存在しません。",
  ui_story_4_1_38_dialog_content = "今までずっと僕を騙してきたってのに、ずいぶんあっさり認めたね！？",
  ui_story_4_1_39_dialog_content = "レベル6の巨像が擁するのは、生命維持、積載、輸送機能のみ…",
  ui_story_4_1_40_dialog_content = "…「逃走」には使えるでしょう。",
  ui_story_4_1_41_dialog_content = "それ以上言わないで…",
  ui_story_4_1_42_dialog_content = "PlayerName、すごくへこんでる…",
  ui_story_4_1_43_dialog_content = "少し喋りすぎたようです…が、そう落ち込むこともありません、PlayerName。",
  ui_story_4_1_44_dialog_content = "空の末裔たるあなたは唯一無二の才能と、素晴らしい指揮能力を有しています。\nこの点は疑いありません。",
  ui_story_4_1_45_dialog_content = "バイス中尉にも、これほどまでに見込まれているのです。\nそれだけ信頼に足る人物だということでしょう。",
  ui_story_4_1_46_dialog_content = "えっ？",
  ui_story_4_1_47_dialog_content = "ありがとう、ヒイロさん。僕…頑張るよ。",
  ui_story_4_1_48_dialog_content = "そろそろ僕たちも出発しよう！\nスーモアが動き出したなら、僕たちも急がないと！",
  ui_story_4_1_49_dialog_content = "そうね！長官、私たちに白夜城の通行証をいただけませんか？",
  ui_story_4_1_50_dialog_content = "それはできません。自分で解決してください。",
  ui_story_4_1_51_dialog_content = "えっ？",
  ui_story_4_1_52_dialog_content = "残念ですが、まだ情報に証拠がありません。啓光連邦が公に動くわけにはいきません――\n白夜城が関わるとなれば、なおさらです。",
  ui_story_4_1_54_dialog_content = "…",
  ui_story_4_1_55_dialog_content = "あなたは白夜城に留学経験があったでしょう。\n同窓生と旧交を温める頃合いとしてもいいのでは？",
  ui_story_4_1_56_dialog_content = "たしか、白夜城の護衛隊長である「<color=#FFB400>カレン</color>」と同級生でしたね？",
  ui_story_4_1_57_dialog_content = "そうですけど…だから余計に頭が痛いんです…はぁ…",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>白夜城の上空</color>",
  ui_story_4_1_59_dialog_content = "あの<color=#FFB400>空中に浮遊している都市</color>が目的地ですね。",
  ui_story_4_1_60_dialog_content = "見えたわ、もう着いたみたい。巨像に乗るとあっと言う間ね…",
  ui_story_4_1_X1_dialog_content = "バイス、そのかっこうは…",
  ui_story_4_1_X2_dialog_content = "ちょっと変装してるだけよ！カレンには手紙で説明したけど、\nやっぱり目立たないほうがいいかなって…",
  ui_story_4_1_X3_dialog_content = "…逆に目立つんじゃないかな…",
  ui_story_4_1_61_dialog_content = "PlayerName、見て！",
  ui_story_4_1_62_dialog_content = "あれが白夜城よ。",
  ui_story_4_1_64_option_content = "あれが、「最後の都」…",
  ui_story_4_1_65_option_content = "どうやって浮いてるんだろう？",
  ui_story_4_1_66_dialog_content = "ちょっと、独り言なんてしてないで、早くこっちに来て。\n始める前にもう一度言っておくわ。",
  ui_story_4_1_67_dialog_content = "この後は、何があっても質問に答えるのは私。わかった？",
  ui_story_4_1_68_dialog_content = "絶対に軽率な行動をしないこと。\n今回の任務はスーモアより先にターゲットを見つけることよ。",
  ui_story_4_1_69_dialog_content = "了解、バイス中尉！なんてね。頼りにしてるよ。",
  ui_story_4_1_70_dialog_content = "念のため、通行証をもう1回確認させて…\n本当は「あの人」には会いたくないの…",
  ui_story_4_1_71_dialog_content = "PlayerName、私は少々不安です。\n私だけがここに停留して、本当に問題ないでしょうか？",
  ui_story_4_1_72_dialog_content = "仕方ないよ、ソラヴァン。\n自分がどれほど目立つかってこと、わかるでしょ？",
  ui_story_4_1_73_dialog_content = "もし君を連れて行ったら、白夜城どころか街のはずれにも近づけないよ。",
  ui_story_4_1_74_dialog_content = "それに、君はレベル6の巨像でしょ？何かあったって戦えないじゃない。",
  ui_story_4_1_75_dialog_content = "…まだ根に持っているのですね…",
  ui_story_4_1_76_dialog_content = "まあ、いいでしょう。今後の戦闘はあなた達にお任せします。",
  ui_story_4_1_A3_dialog_content = "私は隠れられる空域を見つけて待機します。気をつけて。",
  ui_story_4_1_77_dialog_content = "さぁ、そろそろ出発しましょう。さっき、入城待ちの長～い行列が見えたから。",
  ui_story_4_1_A4_dialog_content = "はぁ…並ぶのって嫌いなのよね…",
  ui_story_4_1_78_dialog_content = "それに、やっぱりできれば会いたくないし…\n白夜城の護衛隊長、<color=#FFB400>カレン・ド・ソルラド</color>…",
  ui_story_4_1_79_dialog_content = "何か問題ある人なの？",
  ui_story_4_1_80_dialog_content = "はぁ…あなたもすぐにわかるわ。城門で私たちを待ってるはずよ。",
  ui_story_4_1_81_dialog_content = "バイス、君の言ってた護衛隊長って、どこ？",
  ui_story_4_1_82_dialog_content = "シーッ！",
  ui_story_4_1_83_dialog_content = "皆さん、列を乱さず、迅速な検査にご協力ください！",
  ui_story_4_1_84_dialog_content = "臨時通行証の所持者は24時間以上の滞在は認められません。\n違反すれば白夜城は追放権を行使します！",
  ui_story_4_1_85_dialog_content = "不審者を見かけたら、すぐに白夜城衛兵に報告してください！",
  ui_story_4_1_86_dialog_content = "PlayerName、いい？なにが起こっても…",
  ui_story_4_1_87_dialog_content = "私語はご遠慮を！通行証を見せてください。",
  ui_story_4_1_88_dialog_content = "あ、はい…",
  ui_story_4_1_89_dialog_content = "…また啓光の人間か…前線はそんなに暇なのか？格好も怪しいし…",
  ui_story_4_1_90_dialog_content = "…えっと、今回は私用で来たんです。",
  ui_story_4_1_91_dialog_content = "やけに視線が泳いでいるね？白夜城は初めて？",
  ui_story_4_1_92_dialog_content = "いえ。実は私、ここの留学生だったんです。今回はA級通行証の更新に来ました…",
  ui_story_4_1_93_dialog_content = "では「私は不審者です」と顔に書いてあるような、隣の君は？",
  ui_story_4_1_94_option_content = "僕？僕は地上に出たばかりで…",
  ui_story_4_1_95_option_content = "（バイスは喋るなって言ってたよね…）",
  ui_story_4_1_96_dialog_content = "…冗談だと思ったのか？書類を出すんだ。 1人1枚、無いとは言わせんぞ！",
  ui_story_4_1_97_dialog_content = "お前、お前に聞いてるんだよ。耳が聞こえないのか？",
  ui_story_4_1_98_dialog_content = "すみません、この人は特別な手続きのために私が連れてきたんです。\nもう一度確認してください。",
  ui_story_4_1_99_dialog_content = "護衛隊長のカレンに…",
  ui_story_4_1_100_dialog_content = "「護衛隊長？」…ああ、ではあなたが！",
  ui_story_4_1_101_dialog_content = "…それを早く言ってくださいよ…分かりました。しばらくこちらでお待ちください。",
  ui_story_4_1_102_dialog_content = "ふぅ…",
  ui_story_4_1_103_dialog_content = "相変わらず、気楽そうね。啓光の仕事はそんなに楽なの？",
  ui_story_4_1_104_dialog_content = "ははっ、<color=#FFB400>カレン</color>…久しぶり。\nあなたは相変わらず…威厳たっぷりって感じね。",
  ui_story_4_1_105_dialog_content = "隊長を名前で呼んだ…大した度胸ね…",
  ui_story_4_1_106_dialog_content = "この変てこな服装のお姉さん、見覚えがあるような…",
  ui_story_4_1_107_dialog_content = "あっ！カレンちゃんの同級生でしょ？",
  ui_story_4_1_108_dialog_content = "ラファちゃん、静かに…護衛隊長にお話させてあげて。",
  ui_story_4_1_109_dialog_content = "ミカエルちゃんを見習いなさいよ。何も言わずに落ち着いてるでしょ…",
  ui_story_4_1_110_dialog_content = "…",
  ui_story_4_1_111_dialog_content = "全員、静粛に。",
  ui_story_4_1_112_dialog_content = "こんな所に集まっていないで、定期パトロールに向かいなさい。",
  ui_story_4_1_113_dialog_content = "この2人のことは私に任せて。",
  ui_story_4_1_114_dialog_content = "自己紹介はするまでもないわね。",
  ui_story_4_1_115_dialog_content = "カレン、単刀直入に言うけど…私たちが来たのは…",
  ui_story_4_1_116_dialog_content = "手紙は読んでいるわ。相変わらず文法は間違いばかりで、\n敬語の使い方もなっていなかったけど。",
  ui_story_4_1_117_dialog_content = "いちおう確認しておくけど、「<color=#FFB400>白夜城を狙う暗鬼がいる</color>」と言うことね？",
  ui_story_4_1_118_dialog_content = "まさかこんな時に文法を酷評されるなんて…",
  ui_story_4_1_A5_dialog_content = "でも、その通りよ。私たちは「スーモア」という名前の敵が\n白夜城潜入を企んでいるという情報を得たの。",
  ui_story_4_1_119_dialog_content = "目的はおそらく、白夜城から「<color=#FFB400>ブレーンパーツ</color>」を盗み出すことで間違いないわ。",
  ui_story_4_1_120_dialog_content = "「ブレーンパーツ」？…初耳だわ。\nでもそれが何にせよ、白夜城から盗み出そうと企むなんて…",
  ui_story_4_1_122_dialog_content = "…そういえば、そちらは？",
  ui_story_4_1_123_dialog_content = "…答えていいかな？",
  ui_story_4_1_124_dialog_content = "その声の大きさじゃ、もう聞こえてると思うわ…",
  ui_story_4_1_125_dialog_content = "…",
  ui_story_4_1_126_dialog_content = "PlayerNameは…カレン、あなたにだけ話すわ。悪いけど、ちょっと耳を貸して…",
  ui_story_4_1_127_dialog_content = "つまり…安全なところに隠れて、「身勝手にも」生き延びたということ？\nそれに、巨像は？",
  ui_story_4_1_128_dialog_content = "名前はソラヴァン…今は白夜城の上空にいるわ。\nあなた達に見つからないように隠れてる。",
  ui_story_4_1_129_dialog_content = "…！",
  ui_story_4_1_130_dialog_content = "安心してよ。レベル6の巨像だから…「ただの逃走用」で「戦闘能力は皆無」だよ。",
  ui_story_4_1_131_dialog_content = "そう…",
  ui_story_4_1_132_dialog_content = "そんなことより、カレン。\nPlayerNameのことは正直に話したでしょ。私たちを信じて！",
  ui_story_4_1_133_dialog_content = "バイス、信じてあげたいところだけれど、証拠があまりにも少ないわ…\n他に説得力があるものは？",
  ui_story_4_1_134_dialog_content = "ないわ…でも暗鬼は必ず白夜城への侵入を狙ってる。\nもしかしたら、もうあの行列の中にいるかもしれないの！",
  ui_story_4_1_137_dialog_content = "隊長！緊急事態です！",
  ui_story_4_1_139_dialog_content = "…！？それは本当なの？",
  ui_story_4_1_140_dialog_content = "何を話しているのかな？",
  ui_story_4_1_141_dialog_content = "わからないわ。でも、良い知らせではなさそうね…",
  ui_story_4_1_142_dialog_content = "バイス中尉、同級生のよしみで…ひとまずあなたを信じて、入城を許可するわ。",
  ui_story_4_1_143_dialog_content = "でも、私がずっとあなた達に同行する。もし嘘だと判明した場合には、\n罰を受けてもらうことになるわ。",
  ui_story_4_1_144_dialog_content = "わかったわ！今すぐ出発よ！まずは…",
  ui_story_4_1_145_dialog_content = "まずは<color=#FFB400>ダウンタウン</color>ね。",
  ui_story_4_1_146_dialog_content = "ダウンタウン？",
  ui_story_4_1_147_dialog_content = "ええ…たった今、ダウンタウンで<color=#FFB400>襲撃事件</color>が起きたそうよ。",
  ui_story_4_1_148_dialog_content = "！？",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>ダウンタウン</color>",
  ui_story_4_2_2_dialog_content = "遊びほうけてすっかり遅くなっちまったな。近道して帰るか…",
  ui_story_4_2_3_dialog_content = "おや？あんた、そこで何を…うわああああああああ！！",
  ui_story_4_2_4_dialog_content = "騒がしいわね。",
  ui_story_4_2_5_dialog_content = "すまんすまん、こりゃ俺のミスだ。",
  ui_story_4_2_6_dialog_content = "死んでるの？",
  ui_story_4_2_A1_dialog_content = "大丈夫、もう始末したよ。",
  ui_story_4_2_7_dialog_content = "可哀そうに、俺を恨むなよ。この時間にここを通った自分の運の悪さを呪うんだな。",
  ui_story_4_2_8_dialog_content = "運も生き延びるための重要なスキルのうちだからな。",
  ui_story_4_2_9_dialog_content = "そんな奴とのおしゃべりが楽しい？グスド。",
  ui_story_4_2_A2_dialog_content = "久しぶりに会ったっていうのに、私よりもそいつと話しているつもり？",
  ui_story_4_2_10_dialog_content = "スイェート、俺の心にはいつも君がいるんだ。\nいついかなる時も、一緒にいるのさ。",
  ui_story_4_2_11_dialog_content = "相変わらず口が上手いこと…まずは仕事の話よ。\nあの方から情報が来たわ。行動開始よ。",
  ui_story_4_2_12_dialog_content = "今から？",
  ui_story_4_2_13_dialog_content = "そうよ。詳しい計画は追って教えるわ。",
  ui_story_4_2_14_dialog_content = "すでにエサとして「おともだち」を撒いてあるわ。\n衛兵たちがすぐにこの近くへ集まって来る。その隙にあなたが…",
  ui_story_4_2_15_dialog_content = "ちょっと待ってくれ、スイェート。本当にそれでいいのか？\nそんなに大きなリスクを冒さなくても、俺を待っていてさえくれれば…",
  ui_story_4_2_16_dialog_content = "いいの、グスド。何も言わないで。私の言う通りにして。",
  ui_story_4_2_17_dialog_content = "私はここで護衛隊を足止めする。\nその後はあなたが…<color=#FFB400>例のものを盗み出す</color>。",
  ui_story_4_2_18_dialog_content = "…ブツの位置は確認済みだ。でもそんなに上手く行くか？",
  ui_story_4_2_19_dialog_content = "ええ、大丈夫よ。この計画が成功すれば、\n私たちは自由になれる、そうでしょう？",
  ui_story_4_2_20_dialog_content = "…わかった。君にはいつも易々と言いくるめられてしまうな…",
  ui_story_4_2_21_dialog_content = "報告！暗鬼に襲撃されたとの通報がありました！",
  ui_story_4_2_22_dialog_content = "同じ場所ではないのね？まさか、単独犯ではない…？",
  ui_story_4_2_23_dialog_content = "カレンちゃん！私たちも来たよ～！",
  ui_story_4_2_24_dialog_content = "…",
  ui_story_4_2_25_dialog_content = "東区の調査に向かって。敵が複数いるようね。",
  ui_story_4_2_26_dialog_content = "了解！他の兵士たちは？",
  ui_story_4_2_27_dialog_content = "アップタウンに残すわ。\n人手のほとんどは貴族の居住区に回すしかない…あの男の命令だから。",
  ui_story_4_2_28_dialog_content = "<color=#FFB400>城主様</color>ね…",
  ui_story_4_2_29_dialog_content = "現在報告されている攻撃地点は全て東区。\nダウンタウンの担当者は全員出動済みよ。",
  ui_story_4_2_30_dialog_content = "私は…西区に行くわ。直感がそうしろというの。",
  ui_story_4_2_31_dialog_content = "出たわ、あの目よ…「何だかすごいことを閃いた。すぐに実行しちゃおう！」みたいな。",
  ui_story_4_2_32_dialog_content = "同級生だった時もあんな感じの目になったことがあるの？",
  ui_story_4_2_33_dialog_content = "ええ。例えば格闘戦の授業で、私を一撃で倒そうと狙っている時…とかね。",
  ui_story_4_2_34_dialog_content = "…なんだか、すごい人みたいだね。",
  ui_story_4_2_35_dialog_content = "私を誉めても無駄よ。さあ、西区に向かうわ――\nあなたは戦えるの、PlayerName？",
  ui_story_4_2_36_dialog_content = "僕は戦えない。でも指揮と誘導ならできるよ。",
  ui_story_4_2_37_dialog_content = "信用していいものかしら。",
  ui_story_4_2_38_dialog_content = "でも、証明する機会はあげましょう。",
  ui_story_4_2_39_dialog_content = "ものすごいプレッシャーだ…",
  ui_story_4_3_1_dialog_content = "…意外だわ。あなたには確かに指揮の才能がある。",
  ui_story_4_3_2_dialog_content = "それに…これが光の軌跡？\nこの力を持った一族は、私が生まれる前に絶滅したと聞いていたけれど。",
  ui_story_4_3_3_dialog_content = "けっこう若いんだね、カレン。",
  ui_story_4_3_4_dialog_content = "調子に乗らないことね。すでに西区でも暗鬼が動き出してる。油断は禁物よ。",
  ui_story_4_3_5_dialog_content = "暗鬼の数が、思っていたよりもずっと多いわ…",
  ui_story_4_3_6_option_content = "白夜城は「絶対に落ちない」んだよね？",
  ui_story_4_3_7_option_content = "城門の衛兵じゃ暗鬼を防げないの？",
  ui_story_4_3_8_dialog_content = "「永劫不落」と呼ばれているのはアップタウンだけで、ダウンタウンじゃない…",
  ui_story_4_3_9_dialog_content = "衛兵はもちろん頑張っているわ。でも、衛兵のほとんどが守っているのは\nアップタウンだけ。ダウンタウンじゃないの。",
  ui_story_4_3_10_dialog_content = "私たちが今いるのはダウンタウン。\n頼れるのは自分の力だけ。そうよね、カレン？",
  ui_story_4_3_F1_dialog_content = "…",
  ui_story_4_3_11_dialog_content = "ダウンタウンとアップタウンで、そんなに違うの？",
  ui_story_4_3_12_dialog_content = "仕方ないのよ。それが「白夜城」ってこと…",
  ui_story_4_3_13_dialog_content = "遅れて申し訳ありません…グスド中隊長、戻りました。",
  ui_story_4_3_14_dialog_content = "何か異常は？",
  ui_story_4_3_15_dialog_content = "今のところは何も、隊長。",
  ui_story_4_3_16_dialog_content = "人手を集めて、まずは住民の避難を。\nその後、ダウンタウンの出入り口を封鎖して！",
  ui_story_4_3_17_dialog_content = "全て完了しています、隊長。",
  ui_story_4_3_18_dialog_content = "仕事が早いわね。それなら、この後は私たちと一緒に――",
  ui_story_4_3_19_dialog_content = "お言葉ですが…城外にまだ多くの人々が取り残されています。\n我々が城内に引き入れなければ…",
  ui_story_4_3_20_dialog_content = "人々を暗鬼だらけの場所に見捨てることになります。",
  ui_story_4_3_21_dialog_content = "…いいわ、では急ぎなさい。人数をこちらに少し分けて。",
  ui_story_4_3_22_dialog_content = "失礼いたします。白夜に捧ぐ！",
  ui_story_4_3_23_dialog_content = "カレン、今の人は…？",
  ui_story_4_3_24_dialog_content = "ダウンタウンの中隊長の1人よ。\n通常は様々な防衛業務を担当して、常に高い成果を上げているわ。",
  ui_story_4_3_25_dialog_content = "なにしろ…かつては彼、<color=#FFB400>有名な騎士</color>だったのよ。",
  ui_story_4_3_26_dialog_content = "人は見かけによらない、ってやつだね？",
  ui_story_4_3_27_dialog_content = "さて、私たちも行きましょう。\n網を逃れた暗鬼たちがダウンタウンで暴れているそうよ。",
  ui_story_4_3_28_dialog_content = "それに、私も見てみたいわ。\nあなた達の言う「<color=#FFB400>スーモア</color>」の顔をね。",
  ui_story_4_6_1_dialog_content = "報告します！東区の処理を完了しました！",
  ui_story_4_6_2_dialog_content = "隊長、西区に新たな目撃情報あり！上級暗鬼のようです！",
  ui_story_4_6_3_dialog_content = "予想通りね。どこ？場所を教えなさい！",
  ui_story_4_6_4_dialog_content = "この騒ぎはぜんぶ、おとりよね？\n「ブレーンパーツ」はきっと上級暗鬼の近くにあるはずよ！",
  ui_story_4_6_5_dialog_content = "それほど遅れはとってないよね？",
  ui_story_4_6_6_dialog_content = "当然よ、私たちには、直感が超鋭いカレンがいるもの！",
  ui_story_4_6_7_dialog_content = "…",
  ui_story_4_6_8_dialog_content = "うわぁ、またその目…どうしたの、何かまずいことでもあった？",
  ui_story_4_6_9_dialog_content = "…いえ。でもすごく嫌な感覚…とにかく、先に進みましょう！",
  ui_story_4_6_10_dialog_content = "スイェート！計画は中止だ！",
  ui_story_4_6_11_dialog_content = "何を言ってるの？\nあのお姫様――カレン・ド・ソルラドはうまくここに誘導されているのよ！",
  ui_story_4_6_12_dialog_content = "この期に及んで止める？グスド、今さらあなたと口論する気はないわ。",
  ui_story_4_6_13_dialog_content = "カレンだけじゃない。啓光のガキもいっしょなんだ！\nやつらも「ブレーンパーツ」を探しに来てるらしい！",
  ui_story_4_6_14_dialog_content = "それに資料館のロック解除は厄介だ。間に合うかどうか…",
  ui_story_4_6_15_dialog_content = "いいえ、ダメよ。\nお子様なんかに私の計画を台なしにされるわけにはいかないわ！！",
  ui_story_4_6_16_dialog_content = "絶対に…邪魔させない…",
  ui_story_4_6_17_dialog_content = "それじゃ、どうするつもりだ？",
  ui_story_4_6_18_dialog_content = "あなたのために、もっと時間を稼ぐだけよ！",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>シャイア</color>…そうよ、シャイアを起こせばいい。あの子がいれば…",
  ui_story_4_6_20_dialog_content = "ダメだ、スイェート！たとえ君の考えでも、それだけはさせない！",
  ui_story_4_6_21_dialog_content = "シャイアは――君の妹は、もはや制御が効かない凶器じゃないか！",
  ui_story_4_6_22_dialog_content = "凶器？ふん…じゃ、私は何だっていうの？",
  ui_story_4_6_23_dialog_content = "グスド、あなたは、あなたの行くべき場所に行って。\n私をガッカリさせないで。",
  ui_story_4_6_24_dialog_content = "…約束の場所で待ってるよ、スイェート。",
  ui_story_4_6_25_dialog_content = "君は騎士との約束を必ず守る。そうだろ？",
  ui_story_4_6_26_dialog_content = "もちろんよ、グスド。約束は必ず守るわ。たとえ何が起きようと…",
  ui_story_4_6_27_dialog_content = "シャイア、よく眠れた？さあ、起きて。お姉さまと…遊びに行きましょう。",
  ui_story_4_6_28_dialog_content = "遊ぶ、遊ぶ――",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>ダウンタウン・街中</color>",
  ui_story_4_7_2_dialog_content = "隊長、さきほど前方で死体が発見されました。\nダウンタウンを守備していた衛兵です。",
  ui_story_4_7_3_dialog_content = "傷口は一か所のみ、一撃で心臓を貫かれています…",
  ui_story_4_7_4_dialog_content = "全衛兵！持ち場で捜査を継続して。\n我が城の民を傷つけるものを、私は絶対に許さない！",
  ui_story_4_7_5_dialog_content = "「<color=#FFB400>我が城の民</color>」？",
  ui_story_4_7_6_dialog_content = "そうよ、カレンは昔から城民思いだから…",
  ui_story_4_7_7_dialog_content = "そこじゃないよ。\n僕が聞きたいのは、「<color=#FFB400>我が城</color>」ってところなんだけど。",
  ui_story_4_7_8_dialog_content = "あ…話してなかったっけ？カレンはね…<color=#FFB400>白夜城城主の娘</color>なのよ。",
  ui_story_4_7_9_dialog_content = "？？？",
  ui_story_4_7_10_dialog_content = "ごめん、ごめん。いろいろあり過ぎて言うのを忘れてた…",
  ui_story_4_7_11_dialog_content = "でも、少なくとも今の彼女は「白夜城護衛隊隊長」よ。",
  ui_story_4_7_13_dialog_content = "うわっ！なんの音！？",
  ui_story_4_7_14_dialog_content = "衛兵！全速で現場に向かい調査を！",
  ui_story_4_7_16_dialog_content = "この姿を他人に見せるのは…初めてよ。",
  ui_story_4_7_17_dialog_content = "爆発したのは…ただの家？",
  ui_story_4_7_18_dialog_content = "あの人、様子が変よ！カレン、PlayerName、気をつけて！",
  ui_story_4_7_19_dialog_content = "…あなたは…スイェート？",
  ui_story_4_7_20_dialog_content = "驚いたわよね？お姫様。\nまさか、またあなたと対等に向かい合う日が来るなんてね…",
  ui_story_4_7_21_dialog_content = "この姿はどう？元の私と、どちらがいいかしら？",
  ui_story_4_7_22_dialog_content = "カレン…知り合いなの？",
  ui_story_4_7_23_dialog_content = "ええ、遠い昔のね。自らの信じるものを捨てた、ただの哀れな虫けらよ。",
  ui_story_4_7_24_dialog_content = "「哀れな虫けら」…あら、おっしゃるとおりだわ。",
  ui_story_4_7_25_dialog_content = "あなたたちにとって、私はアップタウンの虫以下の存在。哀れに違いないわ…",
  ui_story_4_7_26_dialog_content = "あなたの境遇は己の堕落のせいよ。",
  ui_story_4_7_27_dialog_content = "今のあなたの姿を見たところで…何の感慨もないわ。",
  ui_story_4_7_28_dialog_content = "私自身の堕落？本当かしら、 お姫様。もしあなたが高貴な母親の、\n高貴なベッドで産声をあげていなかったら、どうだったでしょうね？",
  ui_story_4_7_29_dialog_content = "もしカビの生えたわらの上に生まれていたら、あなたは…何だったかしら？",
  ui_story_4_7_30_dialog_content = "…",
  ui_story_4_7_31_dialog_content = "答えられないでしょう？すべてを軽々しく「自身の堕落」の一言で片付けられるのは、\nあなたが傲慢なお姫様だからよ。",
  ui_story_4_7_32_dialog_content = "スイェート、あの時話したことは覚えている？",
  ui_story_4_7_33_dialog_content = "私は白夜の名にかけて誓った。\n今後あなたがここへ足を踏み入れることがあれば、この槍で裁きを下す、と。",
  ui_story_4_7_34_dialog_content = "今、その誓いを果たすわ。",
  ui_story_4_7_35_dialog_content = "実は私ね、ずっとあなたのすぐ近くにいたのよ。\n聖なる光に照らされることのない物陰に…",
  ui_story_4_7_36_dialog_content = "どう？驚いた？しかも私には「友達」がたくさんいるのよ。",
  ui_story_4_7_37_dialog_content = "！？",
  ui_story_4_7_38_dialog_content = "私の「妹」、可愛いシャイア、こっちに来なさい。",
  ui_story_4_7_39_dialog_content = "姉さ、姉さま…シャイアは、あ、あそ…",
  ui_story_4_7_40_dialog_content = "「遊びたい」のでしょう？全く…しょうがない子ね。",
  ui_story_4_7_41_dialog_content = "いらっしゃい。\n姉さまと一緒に、あの可愛らしいお姫様と、思う存分遊びましょう。",
  ui_story_4_7_42_dialog_content = "…遊ぶ――！",
  ui_story_4_7_43_dialog_content = "気をつけて！",
  ui_story_4_7_44_dialog_content = "あああああああ！なぜ！どうしてよ！お前――お前！！",
  ui_story_4_7_45_dialog_content = "あんた何者なの！？\nなんでこんな連携ができる、どうやって指揮してるのよ！？",
  ui_story_4_7_46_dialog_content = "まさか…空の末裔！？",
  ui_story_4_7_47_dialog_content = "…",
  ui_story_4_7_48_dialog_content = "つまんない…つまんない！！姉さま、ここ、もう嫌…",
  ui_story_4_7_49_dialog_content = "ダメよ、あの人にはもっと時間が必要なの。\n私たちは…ここで止めるわけにはいかないの！",
  ui_story_4_7_50_dialog_content = "お前、それと白夜城の犬ども！度胸があるなら追いかけて来なさい！",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>ゴオォォン――！</color>",
  ui_story_4_7_53_dialog_content = "ゲホゲホッ…まずいわ！<color=#FFB400>逃げられた</color>！",
  ui_story_4_7_54_dialog_content = "アップタウン！あの二人、アップタウンに逃げているわ！",
  ui_story_4_7_55_dialog_content = "警報！それから全護衛隊隊員に伝達！\nただちにアップタウンの防衛に回りなさい！",
  ui_story_4_7_56_dialog_content = "PlayerName！急いで！私たちも追いかけるわよ！",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>アップタウンから遠く離れた白夜城資料館内</color>",
  ui_story_4_8_2_dialog_content = "左に…3度…右に…14度回して…その後は…",
  ui_story_4_8_3_dialog_content = "また失敗だ…いったいどんな方法を使ってるんだ？\nこの前に小細工を仕込んでおくべきだったな…",
  ui_story_4_8_4_dialog_content = "いっそ爆破…いや、ダメだ。万が一パーツを傷つけでもしたら…",
  ui_story_4_8_5_dialog_content = "何だってこんな資料館に、ここまで厳重なロックを使うんだ…？",
  ui_story_4_8_6_dialog_content = "グスド。",
  ui_story_4_8_7_dialog_content = "スイェート！すまない、まだ時間がかかる。資料館が…",
  ui_story_4_8_8_dialog_content = "…待て、戦闘中か？",
  ui_story_4_8_9_dialog_content = "いいえ…ごめんなさい。今は…逃走中よ。",
  ui_story_4_8_10_dialog_content = "空の末裔がいたの、グスド…空の末裔が1人、あっち側に！",
  ui_story_4_8_11_dialog_content = "カレンと戦ったのか？ケガは？",
  ui_story_4_8_12_dialog_content = "グスド、聞いて…私はやつらをアップタウンの南に誘導するわ。\n資料館から最も離れた場所よ…",
  ui_story_4_8_A1_dialog_content = "そうすれば十分な時間が稼げる…",
  ui_story_4_8_13_dialog_content = "ダメだ！アップタウンに行くなんて、死にに行くも同然だ！",
  ui_story_4_8_14_dialog_content = "忘れないでくれ、スイェート。俺たちがこんなことをしているのは…",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>あの方</color>が助けてくれるわ。私は信じてる。\nちゃんと約束してくれたもの…",
  ui_story_4_8_16_dialog_content = "信じて、グスド。私たちで選んだことよ。もう後には引けないの！",
  ui_story_4_8_17_dialog_content = "白夜城の外で会いましょう。\n…愛してるわ。",
  ui_story_4_8_18_dialog_content = "スイェート――！",
  ui_story_4_8_19_dialog_content = "ま、待ってよ。みんな、速すぎる…",
  ui_story_4_8_20_dialog_content = "カレン、あのシャイアって子は誰なの？まさかあの2人、もとは光霊？",
  ui_story_4_8_21_dialog_content = "認めたくはないけれど、そうよ。\nあの2人は、かつて白夜城に刃を向けた…ただの裏切り者。",
  ui_story_4_8_22_dialog_content = "PlayerName。さっきの指揮、みごとだったわ。\n上級暗鬼と遭遇したら、腰が引けるかと思っていたけれど。",
  ui_story_4_8_23_dialog_content = "私が想像していた空の末裔とは、まったく違うようね。",
  ui_story_4_8_24_option_content = "自分の役割を果たしただけだよ",
  ui_story_4_8_25_option_content = "いや、僕は他の空の末裔と同じだ",
  ui_story_4_8_26_dialog_content = "カレンも護衛隊長として戦っているでしょ？",
  ui_story_4_8_A2_dialog_content = "僕たちは戦いは好きじゃないし、直接戦う能力もない。",
  ui_story_4_8_27_dialog_content = "でも、暗鬼には勝たせたくない。",
  ui_story_4_8_28_dialog_content = "きっと僕の同胞たちも、同じ思いで戦っていたはずだよ。",
  ui_story_4_8_29_dialog_content = "戦う力がなくても戦うなんて、怖いとは思わないの？",
  ui_story_4_8_31_dialog_content = "僕の一族も昔は暗鬼との戦いで、重要な役割を果たしてたんだ。",
  ui_story_4_8_32_dialog_content = "だから、僕は他の空の末裔と何の違いもないと思ってるよ。",
  ui_story_4_8_33_dialog_content = "確かに、とてつもない能力には違いないわ。",
  ui_story_4_8_34_dialog_content = "僕の能力…でも、これこそ僕の一族が血みどろの襲撃に遭った\n原因だったんじゃないかって気がしてるよ。",
  ui_story_4_8_35_dialog_content = "自分が無力だと思ったことは？",
  ui_story_4_8_36_dialog_content = "ないよ。だって…僕には僕の使命があるから。",
  ui_story_4_8_37_dialog_content = "その使命を果たすためなら、自分の身を危険にさらしても構わない、と？",
  ui_story_4_8_F1_dialog_content = "うん。だって、これは僕だけの戦いじゃあない。",
  ui_story_4_8_38_dialog_content = "面白いわ。バイス、とても面白い相棒を見つけたようね。",
  ui_story_4_8_39_dialog_content = "自分の身を危険にさらしてでも、<color=#FFB400>誰かのために戦う</color>、ね…",
  ui_story_4_8_40_dialog_content = "…",
  ui_story_4_8_41_dialog_content = "…！！",
  ui_story_4_8_46_dialog_content = "ラファエル、いる？",
  ui_story_4_8_47_dialog_content = "いっるよ～！",
  ui_story_4_8_48_dialog_content = "あなたはアップタウンに行かなくていいわ…逆に向かって。",
  ui_story_4_8_49_dialog_content = "えっ？なんで？",
  ui_story_4_8_50_dialog_content = "「アップタウン」に逃げ込むなんて、自殺行為よね？",
  ui_story_4_8_51_dialog_content = "つまり、彼女たちは逃げるつもりなどない…本当は…",
  ui_story_4_8_52_dialog_content = "注意を引いているだけ？",
  ui_story_4_8_53_dialog_content = "その通り。ただし、私たちは追わないわけにはいかない。",
  ui_story_4_8_54_dialog_content = "だから、ラファエルは逆方向を探して。\nどこかに、何者かがいるはず。私の勘がそう言うの。",
  ui_story_4_8_55_dialog_content = "は～い！ラファエル、了解だよ！\n怪しい人を探せばいいんだね！ただちに向かいますっ！",
  ui_story_4_8_56_dialog_content = "カレンは本当に勘が鋭いわね。\nどんなことが起きても、見逃すことなんて無さそうな気がするわ。",
  ui_story_4_8_57_dialog_content = "全く逆よ。私はまだ多くのことを見逃すしかない。 \n「立場」というのは面倒なものね…",
  ui_story_4_8_58_dialog_content = "それより、集中して。また虫が湧いて来たわ。急いで片付けるわよ。",
  ui_story_4_12_1_dialog_content = "…",
  ui_story_4_12_2_dialog_content = "…",
  ui_story_4_12_3_dialog_content = "えっと…つまり、中隊長さんがここにいるのは…",
  ui_story_4_12_4_dialog_content = "はぁ…たったいまご説明した通り…ここには資料館のスタッフを護送するために来ました。\nお疑いのようなら、そちらに聞いてください。",
  ui_story_4_12_5_dialog_content = "でも、護衛隊長には、城外の市民を引き入れに行くって報告してたよねぇ…",
  ui_story_4_12_6_dialog_content = "その市民が資料館のスタッフで、今こうして送り届けて来たのです。",
  ui_story_4_12_7_dialog_content = "えっと…じゃあ、その手に持っている箱は…？\nなんで大事そうに包んで持ってるの？",
  ui_story_4_12_8_dialog_content = "ああ、これですか。これは書類です。\n先週から置いたままだったので持ち帰ろうかと。",
  ui_story_4_12_9_dialog_content = "中身は…主にこの半年間、暗鬼に襲われて亡くなった市民の検死報告です。",
  ui_story_4_12_10_dialog_content = "えっ…",
  ui_story_4_12_11_dialog_content = "今後の治安維持活動に必要ですから。\nいわゆる…事件現場や遺体の解剖写真などですね。",
  ui_story_4_12_12_dialog_content = "…ご覧になりますか？",
  ui_story_4_12_13_dialog_content = "…",
  ui_story_4_12_14_dialog_content = "…",
  ui_story_4_12_15_dialog_content = "あっはは～、いや、遠慮しておくよ。",
  ui_story_4_12_16_dialog_content = "いえ、この非常事態ですから、念のためご確認いただいたほうが…",
  ui_story_4_12_17_dialog_content = "いやああああ！わ、私はあっちをパトロールしに行くからっ！",
  ui_story_4_12_18_dialog_content = "…",
  ui_story_4_13_1_dialog_content = "報告！血痕はこの近辺に続いています！\nあちらの扉の中に入ったもようです！",
  ui_story_4_13_2_dialog_content = "血痕の間隔が短くなった…速度が落ちてる証拠ね。今なら距離をつめられる！",
  ui_story_4_13_3_dialog_content = "急ぎましょう。おそらく近くにいる！",
  ui_story_4_13_4_dialog_content = "うわ、知らないうちにかなり遠くまで…もうすぐアップタウンに着いちゃうわ…",
  ui_story_4_13_5_dialog_content = "彼女たちもアップタウンを突破できるなんて考えてはいないはず。\nこのあたりで背水の陣を敷いて戦うつもりでしょうね。",
  ui_story_4_13_6_dialog_content = "それなら、受けて立つわ。何度戦っても結果は同じ――\n裏切り者の末路は、永久に変わりはしない！",
  ui_story_4_13_7_dialog_content = "姉さま…眠い、眠いよ…",
  ui_story_4_13_8_dialog_content = "寝てはだめよ、シャイア…ごめんね、疲れたわよね…",
  ui_story_4_13_9_dialog_content = "もう追いつかれたのね…想像以上に速い、さすがだわ…カレン…",
  ui_story_4_13_10_dialog_content = "今こそ、あの方との約束が試される時…",
  ui_story_4_13_11_dialog_content = "こんにちは、スイェート…",
  ui_story_4_13_12_dialog_content = "ノラ様…！私…私たちは、追い詰められました…\n敵の中に空の末裔が1人おります！",
  ui_story_4_13_13_dialog_content = "…またあいつね…これで何度目かしら。",
  ui_story_4_13_14_dialog_content = "力をお貸しください！グスドは…まだ時間が必要なんです！",
  ui_story_4_13_15_dialog_content = "私たちに敵を倒す力を…私たちに、生き延びる希望を授けてください…！",
  ui_story_4_13_16_dialog_content = "それじゃあ、お願い事が2つになっちゃうわ、スィエート。",
  ui_story_4_13_17_dialog_content = "…！",
  ui_story_4_13_18_dialog_content = "敵を倒したいの？それとも、生き延びたいの？どっち？",
  ui_story_4_14_1_dialog_content = "スイェート、シャイア。",
  ui_story_4_14_3_dialog_content = "あなた達…来たのね…",
  ui_story_4_14_4_dialog_content = "姉さま…",
  ui_story_4_14_5_dialog_content = "スイェート、聞きたいことは1つだけ。\n教えなさい、<color=#FFB400>誰のために時間を稼いでいるの</color>？",
  ui_story_4_14_6_dialog_content = "…",
  ui_story_4_14_7_dialog_content = "答える気はないようね。ならば、力尽くで…悪く思わないことね！",
  ui_story_4_14_8_dialog_content = "カレン…今の私たちを袋の鼠だと思ってるのでしょうけど…",
  ui_story_4_14_9_dialog_content = "あの方に…授かったわ、新たな…力を…",
  ui_story_4_14_10_dialog_content = "「あの方」？まさかスーモア？",
  ui_story_4_14_11_dialog_content = "私たちは…必ず生き延びる…\nそして、この腐り果てた白夜城から、堂々と凱旋するわ！",
  ui_story_4_14_13_dialog_content = "たとえお姫様だろうと、永久に勝ち続けることなんて出来ない！",
  ui_story_4_14_14_dialog_content = "姉さ…姉さま？身体が…",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>ああああああああ！！！</anim>",
  ui_story_4_14_17_dialog_content = "あれは…！？2人が<color=#FFB400>融合</color>している！？",
  ui_story_4_14_18_dialog_content = "…さっきあんたが与えた力、マトモなものじゃなさそうね。",
  ui_story_4_14_19_dialog_content = "そうね。でもお望みどおりの、敵を倒す力よ。",
  ui_story_4_14_21_dialog_content = "あの化け物になんて名前をつけたらいいかしら？ねぇ、何がいいと思う？",
  ui_story_4_14_22_dialog_content = "…「面白くない」わ。",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>うぁあああ――！痛い、痛い！なぜなの！？\nこんなはずでは…！私たちは――</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>姉さま、力が、湧いてくる。でも、すごく痛い…！</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>あああっ！！これはいったい、何なの！？</anim>",
  ui_story_4_14_26_dialog_content = "PlayerName、下がって…あんなの…もう化け物ですらない…",
  ui_story_4_14_27_option_content = "怖くないよ、僕がついてる",
  ui_story_4_14_28_option_content = "集中すれば、きっと勝てる",
  ui_story_4_14_29_dialog_content = "怒りで震えが止まらないわ…",
  ui_story_4_14_30_dialog_content = "あんな力を誰かに与えられるなんて、いったい何者なの！？",
  ui_story_4_14_31_dialog_content = "…分かった！じゃあ、いつも通りね。任せたわ、PlayerName！",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>痛い…痛いよ、姉さま…すごく痛いよ…</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>シャイア…殺して。私たちを、殺して…</anim>",
  ui_story_4_14_35_dialog_content = "…",
  ui_story_4_14_36_dialog_content = "これはどういうことなの…力を与えるって、一体どういう意味なの？",
  ui_story_4_14_A1_dialog_content = "どうやったかは分からないけれど…\n闇に身を投じた者を待つ結末は、こういうものしかないのよ。",
  ui_story_4_14_37_dialog_content = "白夜の名のもとに、あなた達に…",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>タンポポ…</anim>",
  ui_story_4_14_39_dialog_content = "？",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>タンポポ…私はタンポポになって、飛ぶの…飛んで行くの…</anim>",
  ui_story_4_14_41_dialog_content = "もう意識が混濁しているのね、あなた…いえ、あなた達、と呼ぶべきかしら…",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>私は、あの方の計画を…成し遂げたのに…</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>どうして…約束が違う、私の…グスドが待っているのに――</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>あ、あの方は…</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>ドッカーン…！！！</color>",
  ui_story_4_14_46_dialog_content = "また爆発が！？",
  ui_story_4_14_47_dialog_content = "報告っ…<color=#FFB400>資料館</color>だよ！資料館で爆発が起きたの！ご、ごめんなさ～いっ！",
  ui_story_4_14_48_dialog_content = "分かったわ！でもラファエル、謝ることがあるの？",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>ヒヒ…ヒヒヒ…負けた、ついに負けたのよ、お姫様、あなたが…</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>グスド、グ…私の…グスド…どうか生き延びて…</anim>",
  ui_story_4_14_53_dialog_content = "敵とはいえ、見るにたえないわ…",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>資料館の外</color>",
  ui_story_4_14_55_dialog_content = "…つまり、裏切り者とすれ違っていた、そういうことね？",
  ui_story_4_14_56_dialog_content = "…ごめんなさい、カレンちゃん…もしあの時、私が…",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>城内全域でグスドを捜索、確保しなさい</color>。ただちに！",
  ui_story_4_14_58_dialog_content = "はっ、はい！！",
  ui_story_4_14_59_dialog_content = "治安を乱し、破壊の限りを尽くし…これほどの非道、許せない…",
  ui_story_4_14_60_dialog_content = "その人が資料館から盗み出したのって…",
  ui_story_4_14_61_dialog_content = "「ブレーンパーツ」…",
  ui_story_4_14_62_dialog_content = "盗まれたものの形さえ分からないなんて…大失敗だったね…",
  ui_story_4_14_63_dialog_content = "僕にも責任がある。いや、これは僕の責任だ…",
  ui_story_4_14_64_dialog_content = "本当にごめん、カレン…",
  ui_story_4_14_65_dialog_content = "暗鬼の襲撃はいつでも起こりうることよ、バイス。",
  ui_story_4_14_66_dialog_content = "それを伝えに来た「使者」が、あなたとPlayerNameだったことは、\nせめてもの幸いだったと、私は思っているわ。",
  ui_story_4_14_67_dialog_content = "そうでなかったら、被害はもっと甚大になっていたかもしれないもの。",
  ui_story_4_14_68_dialog_content = "…バイス、これって誉められてるの？それとも責められてるの…？",
  ui_story_4_14_69_dialog_content = "誉めてるんじゃないかしら…？",
  ui_story_4_14_70_dialog_content = "護衛隊長としての職責を果たせなかった私は…城主様に懲罰を請わねばならないわ。",
  ui_story_4_14_71_dialog_content = "城主様って、お父さんでしょ？きっと許してくれるよ。",
  ui_story_4_14_72_dialog_content = "…あなたは白夜城を全く理解してないわね。あの男のことも。",
  ui_story_4_14_73_dialog_content = "それなら、私たちは啓光に戻って、いっしょに今後の作戦を練るわね。",
  ui_story_4_14_74_dialog_content = "「今日を無駄に過ごしたことを悔いていると、明日も無駄に過ごすことになる」\nって、格言もあることだし。",
  ui_story_4_14_75_dialog_content = "そんな格言…あったかな…？",
  ui_story_4_14_76_dialog_content = "…あなたは相変わらず楽観的ね、バイス。",
  ui_story_4_14_77_dialog_content = "だって、もうこうなってしまった以上、落ち込んでいても事態は変わらないじゃない？",
  ui_story_4_14_78_dialog_content = "私は城主様のもとへ報告に向かうわ。道中、気をつけて。",
  ui_story_4_14_79_dialog_content = "それと、PlayerName…あなたとは、また会えるような気がする。",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>同時刻・某所</color>",
  ui_story_4_14_81_dialog_content = "あの姉妹、死んじゃったわ。",
  ui_story_4_14_82_dialog_content = "…どうせ想定内だったんでしょ？",
  ui_story_4_14_83_dialog_content = "報告が2つあるの。1つ目は、「ブレーンパーツ」が手に入った。",
  ui_story_4_14_84_dialog_content = "それから、このあいだの空の末裔が、また現れた。",
  ui_story_4_14_85_dialog_content = "確か、PlayerNameだったかしら？",
  ui_story_4_14_86_dialog_content = "あなたとは同族なんだから、忘れるはずもないわよね。",
  ui_story_4_14_90_dialog_content = "…しつこいわよ。私はもうあんな下等生物じゃないわ！",
  ui_story_4_14_91_dialog_content = "だいたい、危うく計画を水の泡にするところだったのは、\nあんたのバカでグズな手下どもでしょうが。",
  ui_story_4_14_92_dialog_content = "次のパーツは私が自分で手に入れるわ。\n邪魔だてするやつは…誰であろうとズタズタに引き裂いてやる…",
  ui_story_4_14_93_dialog_content = "パーツは？よこしなさい、グスド！",
  ui_story_4_14_95_dialog_content = "スイェート…スイェート…ど、どうしてなんだ！",
  ui_story_4_14_96_dialog_content = "約束しただろ…2人でここを出ようって約束してたのに…2人で自由になろうって…",
  ui_story_4_14_97_dialog_content = "いったい、何があったんだ…！？",
  ui_story_4_14_98_dialog_content = "ぐだぐだと…独り言がうるさいわよ！",
  ui_story_4_14_99_dialog_content = "彼女たちは白夜城の護衛隊の手にかかったの。\nあなたはまだ、私の命令が聞けるんだから、せいぜい感謝しなさい！",
  ui_story_4_14_100_dialog_content = "…カレン…！",
  ui_story_4_14_101_dialog_content = "その表情、たまらないわ、グスド。指名手配書の人相書きとはまるで別人ね。",
  ui_story_4_14_102_dialog_content = "あいつらには…あいつらの血で償わせてやる！",
  ui_story_5_1_1_dialog_content = "…カレン護衛隊長。それはおのれで決めたことか？",
  ui_story_5_1_2_dialog_content = "はい、殿下。あの空の末裔は…あまりに特別な存在です。\n目を配る必要があると考えました。",
  ui_story_5_1_3_dialog_content = "お前の行動に干渉はしない。が、自分の立場を忘れぬように、護衛隊長。",
  ui_story_5_1_4_dialog_content = "はい、殿下。白夜に捧ぐ…",
  ui_story_5_1_5_dialog_content = "状況は理解しました。30分後に軍団長の定例会議があります。\nそこで詳細を報告してください。",
  ui_story_5_1_6_dialog_content = "しかし、具体的な解決方法は、協議の結果次第ですね。",
  ui_story_5_1_7_dialog_content = "…では、第一の議題は終了とします。",
  ui_story_5_1_A1_dialog_content = "先述の座標付近における暗鬼の活動の徹底調査については、3名の軍団長にお任せします。",
  ui_story_5_1_8_dialog_content = "<size=30>ええと、PlayerName。さっきの長官は第一軍団の<color=#FFB400>キシローナ</color>軍団長よ。</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>…そしてこっちは第2軍団の<color=#FFB400>バートン</color>軍団長。2人とも軍を代表する人よ…</size>",
  ui_story_5_1_9_dialog_content = "了解。最近カナン付近で不審な上級暗鬼の報告がある。良い兆しではないだろう。",
  ui_story_5_1_10_dialog_content = "そのために3名の軍団長に集まっていただきました。\n眼下の脅威を放置せず、警戒を怠らないでください。",
  ui_story_5_1_11_dialog_content = "そこにいるガキは？",
  ui_story_5_1_12_dialog_content = "彼らが本日の次の議題です――ヒイロ、報告を始めてください。",
  ui_story_5_1_13_dialog_content = "巨像を操縦できる、空の末裔の生き残り…",
  ui_story_5_1_14_dialog_content = "…",
  ui_story_5_1_15_option_content = "どうしてみんな、僕をずっと見てるの…？",
  ui_story_5_1_16_dialog_content = "おい、顔が赤いぞ？",
  ui_story_5_1_X16_dialog_content = "ふん、ただのガキじゃないか。",
  ui_story_5_1_17_option_content = "えっと…やって見せたほうがいいですか？",
  ui_story_5_1_18_dialog_content = "こんな所で巨像を動かしたら、天井が吹き飛ぶぞ。",
  ui_story_5_1_19_dialog_content = "危ねぇガキだな。それで小僧、お前とスーモアはどういう関係なんだ？",
  ui_story_5_1_20_dialog_content = "長官！PlayerNameはスーモアとは違います！",
  ui_story_5_1_21_dialog_content = "慌てるな。汚染されていない、戦闘能力もない空の末裔だ。\n暗鬼に成り果てた奴らと違うことぐらい分かる。",
  ui_story_5_1_22_dialog_content = "私もバートンも空の末裔に生き残りがいたことに驚いているだけだ。\nあの大災害でみな死に絶えたと思っていたからな。",
  ui_story_5_1_23_dialog_content = "本題に戻るか。そのスーモアってやつは、\n3つのパーツの情報をどれくらい掴んでるんだ？",
  ui_story_5_1_24_dialog_content = "残る2つを探す方法は「ブレーンパーツ」の中にあるはずです。\n私たちには手がかりがありません…",
  ui_story_5_1_25_dialog_content = "しかも、スーモアはすでに「ブレーンパーツ」を手に入れたと思われます。\n状況は楽観できません。",
  ui_story_5_1_26_dialog_content = "当面の急務は、彼女より先に、残り2つのパーツを見つけ出すことです。",
  ui_story_5_1_27_dialog_content = "長官がたにはお力を貸していただくか、\nまたは…この件を引き継いでいただきたいのです。",
  ui_story_5_1_28_dialog_content = "啓光連邦軍が最優先すべき任務は前線と、本部たるカナン城の防衛だ。",
  ui_story_5_1_29_dialog_content = "最近は暗鬼の襲撃が頻発している。\nすでに日常の防衛任務で手一杯、人員を割くのは難しいだろうな。",
  ui_story_5_1_30_dialog_content = "俺はいつもと変わらねぇ。大元帥の命令以外で俺と俺の軍団は動かない。",
  ui_story_5_1_31_dialog_content = "ヒイロは？バイスの長官として、あなたの考えは？",
  ui_story_5_1_32_dialog_content = "啓光の軍人は命令に従うのが本分です。",
  ui_story_5_1_33_dialog_content = "わかりました。",
  ui_story_5_1_34_dialog_content = "ごめんなさい、PlayerName。私たちは明確な命令が下るまで、\n直接協力することはできません。",
  ui_story_5_1_35_dialog_content = "PlayerName、感知できた？",
  ui_story_5_1_36_dialog_content = "一面の静けさだ。変わった情報は何もないよ。",
  ui_story_5_1_37_dialog_content = "もう、最後の頼みの綱も役立ちそうにないわね…",
  ui_story_5_1_38_dialog_content = "モンドルは…最期に、スーモアは必ず次のパーツを探すと言ってたわ。",
  ui_story_5_1_39_dialog_content = "私たちがスーモアの痕跡を見つけられれば、\nそれを追って手がかりを見つけることができるかも、と思ったけど…",
  ui_story_5_1_40_dialog_content = "彼女に関する手がかりが全くみつからないわ。\nただ待つことしかできないのかしら…",
  ui_story_5_1_41_dialog_content = "ふわぁあ～あ。どうしたの暗い顔して。会議がうまくいかにゃかったの？",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>フィリス</color>先輩！",
  ui_story_5_1_43_dialog_content = "そんにゃにかしこまらにゃいで。\nフィリスはお届け物を持ってきただけにゃあ。はい、これ。",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>『ネームレス-13号巨像遺跡研究報告書』</color>？",
  ui_story_5_1_45_dialog_content = "フィリスがにゃが～い時間をかけたんだにゃ！",
  ui_story_5_1_46_dialog_content = "ビビアンにちょ～～う厳しい仕事を言い渡されたにゃあ。\nふわぁ、眠い…まったく人使いが荒いにゃあ…",
  ui_story_5_1_47_dialog_content = "「無名の巨像が墜落した場所ではかつて自己成長可能なパーツが発見されていた。\nあるいは成長型巨像特有の…」",
  ui_story_5_1_48_dialog_content = "「主要部分は遺跡の奥深くで休眠状態にあり、封印の解除方法は不明、探査を継続中…」",
  ui_story_5_1_49_dialog_content = "これって「<color=#FFB400>自己成長ユニット</color>」のことじゃない！？",
  ui_story_5_1_50_dialog_content = "それはすごい偶然だにゃあ～、とりあえず見にいったらどうかにゃ？",
  ui_story_5_1_51_dialog_content = "にゃあ、そうだった。ビビアンから伝言があるにゃあ。",
  ui_story_5_1_52_dialog_content = "軍団長は今のところ支援できにゃいけど、遺跡にも啓光の人員がいるらしいにゃあ！",
  ui_story_5_1_53_dialog_content = "ふぁああ～、もう起きてられにゃいから寝るにゃ。\n夢のにゃかで応援してるよお！",
  ui_story_5_1_54_dialog_content = "フィリス先輩は相変わらずね。",
  ui_story_5_1_55_option_content = "巨像にあんな仲間がいてくれれば…",
  ui_story_5_1_56_dialog_content = "先輩は啓光の情報長官よ。\n本来なら協力が得られただけで、もうスゴいことなの。",
  ui_story_5_1_57_dialog_content = "確かにフィリス先輩に手伝ってもらえれば、\n少なくとも情報収集では遅れをとらないでしょうけど…",
  ui_story_5_1_58_dialog_content = "でも、仕事中に寝ちゃったりしない？",
  ui_story_5_1_59_dialog_content = "寝ちゃうのは仕事のプレッシャーのせいよ…",
  ui_story_5_1_60_option_content = "実は僕も眠くなってきた…いっそ僕らも…",
  ui_story_5_1_61_dialog_content = "少し休もう。",
  ui_story_5_1_A4_dialog_content = "ダメよ！シャキッとしなさい、PlayerName！\n問題がうまく解決出来たら…",
  ui_story_5_1_62_dialog_content = "カナンで一番大きい図書館に連れて行ってあげる。\nそこでゆっくり休めばいいわ！",
  ui_story_5_1_63_dialog_content = "遊園地とかカフェじゃダメなの？\n仕事が終わった後も勉強なんてハードすぎるよ。",
  ui_story_5_1_64_dialog_content = "とにかく、私たちには時間がないの！\nスーモアより先に次のパーツを見つけ出さなきゃ！",
  ui_story_5_1_65_dialog_content = "巨像を起動しに行きましょう！",
  ui_story_5_1_66_dialog_content = "その自信たっぷりな様子を見るに、報告も終わって、方針が決まっているようね。",
  ui_story_5_1_67_dialog_content = "カレン！？",
  ui_story_5_1_68_dialog_content = "そんなに驚かないで。城主様への嘆願が通って、スーモアに関する全権を任せられたの。",
  ui_story_5_1_69_dialog_content = "白夜城を脅かすいかなる行為にも厳罰を与え、\n暗鬼と結託する者には絶対に容赦しない！…ってね。",
  ui_story_5_1_70_dialog_content = "<size=30>カレンは…なんというか近寄りがたい雰囲気があるなぁ。気をつけないと…</size>",
  ui_story_5_1_71_dialog_content = "何か言った？",
  ui_story_5_1_72_dialog_content = "えっ！声に出てた！？",
  ui_story_5_1_73_dialog_content = "心にやましいところがなければ、私を恐れる必要はないはずよ。",
  ui_story_5_1_A5_dialog_content = "私を恐れるべきは、スイェート、グスド、それから、その背後にいる黒幕だけ。",
  ui_story_5_1_74_dialog_content = "グスド…って、あのスイェートの共犯者で、逃亡したっていう男の人？",
  ui_story_5_1_75_dialog_content = "そうよ。日蝕に降り、浅はかにも闇に隠れ場所を求めた、裏切り者。",
  ui_story_5_1_76_dialog_content = "でも、ソルラド家の剣は必ず裏切り者を貫くわ。たとえ地の果てまで逃げようとね。",
  ui_story_5_1_77_dialog_content = "おしゃべりはこれぐらいにしましょう。これからどこへ行くの？",
  ui_story_5_1_78_dialog_content = "ネームレス-13号の巨像遺跡よ。\nカレンは巨像の遺跡って、行ったことある？",
  ui_story_5_1_79_dialog_content = "どちらでもいいでしょう…過去の事にかまっている時間はなかったわ。\n私が守るべきものは、目の前にたくさんあったから。",
  ui_story_5_1_80_dialog_content = "そうだ、それよりひとつ、伝えておくわね…\nオホン。PlayerName様、あなた方の情報提供に、改めて感謝いたします。",
  ui_story_5_1_81_dialog_content = "私はあなた方の任務に同行する者として、この手の槍に賭けて誓います。\n必ずや裏切り者の思惑を挫くと！",
  ui_story_5_2_1_dialog_content = "（声が聞こえたような気がする。悲しくなるような、懐かしいような声が…）",
  ui_story_5_2_2_dialog_content = "失われた故郷に花束を捧げなさい。かつてそこは、木々が風にそよぎ生い茂る場所でした…",
  ui_story_5_2_3_dialog_content = "亡くなった同胞のため、極光に祈りなさい。その輝きは全ての生き物をお許しくださる…",
  ui_story_5_2_4_dialog_content = "私たちの痛みは時と共に消え去り、記憶は風化して灰と化し、やがては虚空に還る…",
  ui_story_5_2_5_dialog_content = "太陽はまた昇ります。しかし私たちは眠り、永遠の安息を迎えるのです。",
  ui_story_5_2_6_dialog_content = "先生…これでいいのでしょうか？私、怖いんです…",
  ui_story_5_2_7_dialog_content = "私が植えた花、まだ芽がでていません。あの花が開くところを見たいです…",
  ui_story_5_2_8_dialog_content = "怖れることはないよ。さあ、目を閉じなさい。\n苦しいのはほんの一瞬だ。先生がずっとそばにいるからね。",
  ui_story_5_2_9_dialog_content = "（僕の…<color=#FFB400>同族</color>？この光景は現実？それともただの幻…）",
  ui_story_5_2_10_dialog_content = "死ぬ前のお祈り…くだらないわね。選択肢はあげたはずよ。",
  ui_story_5_2_11_dialog_content = "もう目的地の上空に着いてるわよ。PlayerName、大丈夫？",
  ui_story_5_2_12_option_content = "バイス…",
  ui_story_5_2_13_dialog_content = "大丈夫よ、私がついてるわ。何かを感知したのね？",
  ui_story_5_2_14_dialog_content = "幻が…あの人たちはいったい…",
  ui_story_5_2_15_dialog_content = "亡くなった空の末裔たちが、この遺跡に強い思念を残したのかもしれません。",
  ui_story_5_2_16_dialog_content = "亡くなった…？\nそれで、モンドルみたいに僕と話すことができなかったんだね。",
  ui_story_5_2_17_dialog_content = "残念ながら、会話することはできません。\n遺体はとっくに風化し、塵となっているでしょう。",
  ui_story_5_2_18_option_content = "色んなものの幻が見えた気がする…",
  ui_story_5_2_19_dialog_content = "PlayerName、誰かの意識を感知したのね？\nこの遺跡の中にまだ生存者がいるってこと？",
  ui_story_5_2_A1_dialog_content = "ここには生命反応がありません。あなたが見た光景は恐らく、幻でしょう…",
  ui_story_5_2_20_dialog_content = "悲しみと絶望の幻…亡くなった人々が残した意識でしょうか？",
  ui_story_5_2_21_dialog_content = "僕はそう信じてる。あれは仲間たちの思念だって。",
  ui_story_5_2_A2_dialog_content = "降ろして、ソラヴァン。",
  ui_story_5_2_24_dialog_content = "さあ、<color=#FFB400>ネームレス-13号遺跡</color>に着いたわよ。",
  ui_story_5_2_25_dialog_content = "資料によると「最初にここを発見した者は、目の前の名もなき巨像が\n眠る姿に震撼した…」のだそうよ。",
  ui_story_5_2_26_dialog_content = "「…それは、まるで天から地上に墜ちた星が眠っているかのようだった」",
  ui_story_5_2_27_dialog_content = "「巨像には活動していた痕跡が全くなく、時が流れ去った後の静寂だけが残されていた」",
  ui_story_5_2_28_dialog_content = "死んだような静けさ…こんな場所に来たのは初めてだわ。",
  ui_story_5_2_29_dialog_content = "天空ノ谷の惨事について、資料館の本で読んだことはあったわ。",
  ui_story_5_2_30_dialog_content = "「おびただしい数の暗鬼が天空ノ谷の種族を襲撃し、\n暗鬼の信徒を除いて生存者はいなかった」",
  ui_story_5_2_31_dialog_content = "…こうして実際に巨像遺跡に来てみると、想像していたよりも…胸が痛むものね…",
  ui_story_5_2_A3_dialog_content = "…",
  ui_story_5_2_A4_dialog_content = "バイス、あなたも色々思うことはあるのでしょう？",
  ui_story_5_2_A5_dialog_content = "うん。PlayerNameほどではないけど、でも感じることができた…悲しみを。",
  ui_story_5_2_34_dialog_content = "PlayerName、あなたはどうやって生き延びたの？",
  ui_story_5_2_35_dialog_content = "僕が知っているのは、それが起きた時、\nソラヴァンが最後の命令に従って赤ん坊だった僕を連れ出したことだけだよ。",
  ui_story_5_2_A6_dialog_content = "その後は地下生活が17年間、少し前まで続いてたんだ。",
  ui_story_5_2_36_dialog_content = "バイスが僕を外の世界に連れ出してくれるまで…\n外の世界の様子もそれほどマシじゃなかったのは、残念だったけどね。",
  ui_story_5_2_37_dialog_content = "僕は…もっと一族の人たちと、モンドルと話がしたかった…",
  ui_story_5_2_38_dialog_content = "PlayerName…",
  ui_story_5_2_39_dialog_content = "空の末裔の悲劇が繰り返されてはいけないわ…",
  ui_story_5_2_40_dialog_content = "当然ね。たとえどの種族であろうとも。そうよね？",
  ui_story_5_2_41_dialog_content = "あっ、みんな、見て――真ん中にある一番巨大な巨像が、資料に書かれた目的地よ。",
  ui_story_5_2_A7_dialog_content = "資料に書いてあったわ。あれの名前は「<color=#FFB400>シビリザー</color>」。\n自力で成長できる唯一の巨像よ。",
  ui_story_5_2_42_dialog_content = "「<color=#FFB400>自己成長ユニット</color>」は恐らくあの身体にあるはず。",
  ui_story_5_2_43_dialog_content = "ボロボロのようだけど、ユニットは無事なのかしら？",
  ui_story_5_2_44_dialog_content = "資料の情報はこれで終わっているわね。",
  ui_story_5_2_45_dialog_content = "入ってみよう。きっと手がかりがあるはずだよ。",
  ui_story_5_2_46_dialog_content = "PlayerName、分かってると思うけど、危険よ。モンドルのときみたいに…",
  ui_story_5_2_F1_dialog_content = "分かってる。中に入ればモンドルみたいに危ない目に遭って、\n同じように消えてしまうかもしれない、だよね？",
  ui_story_5_2_47_dialog_content = "モンドルが消えたときのこと、私は今でも忘れていないわ。\n助けられなかった、無力感を…",
  ui_story_5_2_48_dialog_content = "今ならまだ、身を引けるわ。",
  ui_story_5_2_F2_dialog_content = "バイス、僕だって怖いよ。けど、ほかに道はないんだ。",
  ui_story_5_2_F3_dialog_content = "僕はもう、決めたんだ…どんなに危険でも、何が起きても向き合うって。",
  ui_story_5_2_49_dialog_content = "わかったわ…でも、あなた一人に抱えこませたりしないから。\n何があろうと、私がそばにいる。",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>遺跡の内部</color>",
  ui_story_5_2_50_dialog_content = "…基礎モジュールはズタボロだわ。困ったな～。",
  ui_story_5_2_51_dialog_content = "でも、コアユニットは再起動さえできれば取り出せそう。",
  ui_story_5_2_52_dialog_content = "あの声は…",
  ui_story_5_2_53_option_content = "まさか…スーモア！？",
  ui_story_5_2_54_dialog_content = "違う違う！あれは<color=#FFB400>ガルー</color>先輩よ！",
  ui_story_5_2_55_option_content = "啓光の仲間？",
  ui_story_5_2_56_dialog_content = "そう！やっぱり<color=#FFB400>ガルー</color>先輩だわ。",
  ui_story_5_2_57_dialog_content = "ガルー先輩は啓光の科学研究部の室長で、\n巨像や光力について高度な研究をしているの。",
  ui_story_5_2_58_dialog_content = "先輩！",
  ui_story_5_2_59_dialog_content = "バイス！？このタイミングで仲間が助けに来てくれるなんて…",
  ui_story_5_2_60_dialog_content = "フィリスが話していたのはバイスのことだったんだ。",
  ui_story_5_2_61_dialog_content = "ひどくない！？フィリスったら睡眠デバフでも食らったみたいに、話の途中で寝ちゃったの。",
  ui_story_5_2_62_dialog_content = "あたしだけここに1人残してさ！ボーゼンよ！あ～もう、ム・カ・つ・く！\nでも、運が向いてきた気がするわ！",
  ui_story_5_2_63_dialog_content = "しかも「生きた」巨像も連れて来たんでしょ？完全体ってことよね！？",
  ui_story_5_2_64_dialog_content = "<size=45>ちょっとあたしに触らせて～！</size>",
  ui_story_5_2_65_dialog_content = "えっ？",
  ui_story_5_2_66_dialog_content = "…コホン、少し興奮しすぎたようね。ひとまず「メインクエスト」に戻るわ！",
  ui_story_5_2_67_dialog_content = "…ガルー先輩はとても優秀なんだけど、話し方がちょっと独特で…\n他の人にはよく分からないの。",
  ui_story_5_2_68_dialog_content = "…ああ、うん、何かにハマりすぎたのかな…",
  ui_story_5_2_69_dialog_content = "ガルー先輩、ここには1人で？",
  ui_story_5_2_70_dialog_content = "そうよ！この巨像はダメージがひどいし、\n調査の進展も遅いから、まぁ、サブクエストってとこね。",
  ui_story_5_2_71_dialog_content = "でもね、この中にはまだ未解明の何かがあるはずなの。",
  ui_story_5_2_72_dialog_content = "サブクエストの全コンプはプロの嗜みでしょ。\nだからビビアンにリクエストして、改めて何日か調査に来たの。",
  ui_story_5_2_73_dialog_content = "そうそう、ここには「<color=#FFB400>自己成長ユニット</color>」を探しにきてるのよね？",
  ui_story_5_2_74_dialog_content = "そうです。調査中に何か見つけました？",
  ui_story_5_2_75_dialog_content = "巨像の中には確かに成長型のパーツがあるわ。\nでも、力任せじゃ取り外せないの。",
  ui_story_5_2_77_dialog_content = "巨像は旧時代の最先端の創造物だから、\n啓光の今の科学レベルでも完璧に解析することは…",
  ui_story_5_2_78_dialog_content = "他に方法は？",
  ui_story_5_2_79_dialog_content = "方法？なくはないけど…",
  ui_story_5_2_80_dialog_content = "あなたがフィリスの言っていた<color=#FFB400>「空の末裔の生き残り」</color>よね？\nまるで何かの主人公みたいなあだ名ね。",
  ui_story_5_2_81_dialog_content = "せっかく空の末裔がいるんだし、このどでかい物体を再起動できるか試してみたらどう？",
  ui_story_5_2_82_dialog_content = "善は急げよ、今すぐ…",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>ウォオオオ！！！</anim>",
  ui_story_5_2_84_dialog_content = "邪魔者ね。まずはやつらを始末しないと、先に進めないわ。",
  ui_story_5_2_A9_dialog_content = "なら、さっさと片付けちゃおう！",
  ui_story_5_2_85_dialog_content = "2番目のパーツ「自己成長ユニット」のありかは、\nきっとあなたの大好きな場所よ…",
  ui_story_5_2_86_dialog_content = "…どこの話かと思ったら、虫けらを埋めたゴミ捨て場だったのね。",
  ui_story_5_2_87_dialog_content = "よりにもよって、あんな「弱者」どもが私の必要なパーツを持っていたなんて、\nありえないわ。まさか、もう私が壊していたりは…",
  ui_story_5_2_88_dialog_content = "ああ――イライラする。\n<color=#FFB400>あの女</color>、私をバカにしてるの！？弱虫どもと私は違うと言っているのに！",
  ui_story_5_2_89_dialog_content = "弱者なんか引き裂かれ、踏みつけられて、この世から消えればいいのよ！",
  ui_story_5_2_90_dialog_content = "面白くないわ。いちおう手を貸してくれているとは\n分かってるけど、違和感が拭いきれない…",
  ui_story_5_2_91_dialog_content = "あのグズの暗鬼どもがしくじりさえしなければ、\n私がわざわざ出る必要もなかったのに。",
  ui_story_5_2_92_dialog_content = "おまけに、あの空の末裔…ふん、会う時が楽しみだわ…",
  ui_story_5_3_1_dialog_content = "巨像の内部も損傷がひどいわね。道がよく見えないわ…方向はこれで合ってるのかしら？",
  ui_story_5_3_2_dialog_content = "大丈夫、あたしはプロよ！ブリッジの方向はきっちり把握してる。200m前方ね。",
  ui_story_5_3_3_dialog_content = "あたしぐらいの方向感覚があれば、こんなの楽勝よ。",
  ui_story_5_3_4_dialog_content = "何の音？",
  ui_story_5_3_5_dialog_content = "この近くではなさそうね。",
  ui_story_5_3_6_dialog_content = "この不気味で、冷たい感覚は…",
  ui_story_5_3_8_dialog_content = "PlayerName、どうしたの？大丈夫？",
  ui_story_5_3_9_dialog_content = "上級暗鬼よりも強烈な気配がする！たぶん…スーモアだ！",
  ui_story_5_3_10_dialog_content = "落ち着いて。このまま計画どおりに進みましょう。",
  ui_story_5_3_11_dialog_content = "彼女が現れたなら、倒すまで。",
  ui_story_5_3_12_dialog_content = "でも…",
  ui_story_5_3_13_dialog_content = "でも…じゃないの。彼女はやり過ぎた。その報いを受けてもらう。",
  ui_story_5_3_A1_dialog_content = "前に進みましょう。暗鬼が山ほど私たちを待ち受けているわ。",
  ui_story_5_3_14_dialog_content = "この気配…ふん、まさかあいつ、本当に来てるのね？",
  ui_story_5_3_16_dialog_content = "なんの力も無い弱者のくせに、執着心だけは大したものね。",
  ui_story_5_3_17_dialog_content = "モンドルが死んで、今度はPlayerNameがパーツを守るって？アハハ！",
  ui_story_5_3_18_dialog_content = "とっくに言ったでしょうに。私が選んだ道だけが正しいの…",
  ui_story_5_3_A2_dialog_content = "自らの運命を選び取るためには、武器を取るしかない。\nさもなければ…永遠に哀れな獲物のまま。",
  ui_story_5_3_A3_dialog_content = "お前たち、光力を追いなさい！\nお客人サマをお出迎えして、身体をほぐしてあげて――",
  ui_story_5_3_A4_dialog_content = "この戦い、少しは面白くなりそうじゃない。",
  ui_story_5_3_A5_dialog_content = "『かしこまりました…進め…！！』",
  ui_story_5_7_A14_dialog_content = "目的地に到着！ここが巨像のブリッジよ。",
  ui_story_5_7_A15_dialog_content = "道中の暗鬼も厄介だったけど…みんな、まだ油断は禁物よ！",
  ui_story_5_7_A16_dialog_content = "けっこう頑張ったんだけど、「自己成長ユニット」をブリッジから取り出すことが\nできなかったの。まさに「詰んだ」って感じ。",
  ui_story_5_7_A17_dialog_content = "でも、今回は空の末裔がいるもん！あなたなら、巨像を起動できるはずよね！",
  ui_story_5_7_A18_dialog_content = "がんばるよ…",
  ui_story_5_7_1_dialog_content = "巨像の起動、まず第一歩は、エネルギー残量の確認。",
  ui_story_5_7_2_dialog_content = "…この巨像、損傷は激しいけど、再起動に十分なエネルギーが残ってる。意外だね。",
  ui_story_5_7_3_dialog_content = "次に、巨像と感知で繋がって、制御装置を使えるようにする。\nこれこそ、空の末裔にしかできないこと。",
  ui_story_5_7_4_dialog_content = "そして制御装置を操作する…",
  ui_story_5_7_5_dialog_content = "そう、その通りです。よくできましたね。",
  ui_story_5_7_6_dialog_content = "声が？誰だろう？",
  ui_story_5_7_7_dialog_content = "喜ばしい事です…とても長い間、我が同族、\n我々の末裔に会えませんでしたから…",
  ui_story_5_7_8_dialog_content = "たった1人で大きくなって、誰とも会えず、触れあうこともできない。\nとても辛かったでしょう。",
  ui_story_5_7_9_dialog_content = "どうしてそれを…",
  ui_story_5_7_11_dialog_content = "私はあなたと同じ。美しい天空ノ谷にいたのです。",
  ui_story_5_7_14_dialog_content = "幼い頃から一族の人々は共に学び、歌声を聞いたり、\n巨像と話したりして暮らして来たのです。",
  ui_story_5_7_A1_dialog_content = "空の末裔の家は暖かく、強く結ばれた、\nひとつの大家族なのですよ、PlayerName。",
  ui_story_5_7_15_option_content = "でも、君の身体…透明だよ？",
  ui_story_5_7_16_dialog_content = "顔がよく見えないよ？",
  ui_story_5_7_17_dialog_content = "それは私があなたの…思念にすぎないから。\nあなたが私たちを見たいと望んだから、ここにいるのです。",
  ui_story_5_7_18_dialog_content = "私たちは逃げようとしました。でも最後には、命を落としてしまいました。\n私たちの肉体は朽ち果て骨となり、魂は無限の空へと飛散しました。",
  ui_story_5_7_19_dialog_content = "彼女は暗鬼を率いて、私たち一族を1人ずつ、むごたらしく殺害し…\nあれは極光でさえも照らしきれないほどの闇でした。",
  ui_story_5_7_20_dialog_content = "今もまだ、彼女は妄執に捕らわれたままです。",
  ui_story_5_7_21_dialog_content = "可哀そうな子よ、1人で暮らす日々はさぞや孤独で辛かったでしょう。",
  ui_story_5_7_22_dialog_content = "私にはあなたを抱きしめることができません。\nでも共に歌うことはできます、あの…思い出の歌を。",
  ui_story_5_7_23_dialog_content = "感知を始めるのです。ソラヴァンを動かす時のように…巨像を感じなさい。",
  ui_story_5_7_24_dialog_content = "会うこともかなわなかった最後の子よ、これが私達からの贈り物です。",
  ui_story_5_7_A2_dialog_content = "（ただの幻だって分かってる。でもどうして？あの手は、確かに僕の肌に触れた）",
  ui_story_5_7_25_dialog_content = "（とっくに死んでるはずなのに、あの人の意識が生死を越えて僕を導いてる…）",
  ui_story_5_7_26_dialog_content = "（巨像が照らしだされて、姿が見えた）",
  ui_story_5_7_27_dialog_content = "（何かを歌っている？この厳かで美しいコーラスは、弔いの曲？\n誰に向けて歌っているの？あなたたち自身がもう亡くなっていることを、僕は知っている）",
  ui_story_5_7_28_dialog_content = "（こんな旋律を耳にしたのは初めてだ。でも、不思議と歌い方を知ってる）",
  ui_story_5_7_29_dialog_content = "（歌をありがとう…この歳月を越えた交響曲、永遠に忘れない）",
  ui_story_5_7_30_dialog_content = "僕の…同族たち…本当にここにいてくれたらよかったのに…",
  ui_story_5_7_31_dialog_content = "巨像が起動しはじめたよ！",
  ui_story_5_7_32_dialog_content = "巨像全体がかすかな悲鳴をあげている…泣き声のような、いえ、違う…",
  ui_story_5_7_33_dialog_content = "まるで誰かが、精一杯の気持ちを込めて、PlayerNameと歌っているような…",
  ui_story_5_7_34_dialog_content = "PlayerName、私もやるわ。",
  ui_story_5_7_35_dialog_content = "あと少しよ…5…4…起動成功！",
  ui_story_5_7_36_dialog_content = "見て！あれがこの巨像の「<color=#FFB400>自己成長ユニット</color>」よ！",
  ui_story_5_7_37_dialog_content = "早く回収しましょ…",
  ui_story_5_7_38_dialog_content = "なんの音！？",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>グォォ――！</anim>",
  ui_story_5_7_40_dialog_content = "あら、いいところに来たみたいね。",
  ui_story_5_7_41_dialog_content = "君は…スーモア！？",
  ui_story_5_7_A3_dialog_content = "ああ、あんたがPlayerNameね？",
  ui_story_5_7_A4_dialog_content = "思っていたより子どもだったわ。いかにも無能で怖がりの顔…ふふっ。",
  ui_story_5_7_42_dialog_content = "自己陶酔のオラトリオはそこまでよ。\nあんたたちのおかげで「自己成長ユニット」も取り出せるわね。",
  ui_story_5_7_A5_dialog_content = "君が…お前が…目の前にいるのが…スーモア…",
  ui_story_5_7_45_dialog_content = "痛い…苦しい…",
  ui_story_5_7_46_dialog_content = "誰か…助けて…",
  ui_story_5_7_47_dialog_content = "あんたを見てると、ここの空の末裔たちを思い出すわ、PlayerName。\nあいつらを殺すのは、アリを踏み潰すのも同然だった。",
  ui_story_5_7_48_dialog_content = "私もかつてはお前たちのようなクズだったと思うだけで…吐き気がするわ。",
  ui_story_5_7_49_dialog_content = "口は達者ね。",
  ui_story_5_7_50_dialog_content = "それで抵抗してるつもり？ガッカリだわ。",
  ui_story_5_7_51_dialog_content = "薄汚い暗鬼に白夜城を襲撃させたのは、あなたね？",
  ui_story_5_7_52_dialog_content = "どいつも役立たずだったわ。",
  ui_story_5_7_53_dialog_content = "許しはしない…その薄汚れた手で「最後の都」に触れた代償、払ってもらう。",
  ui_story_5_7_54_dialog_content = "あんたたちに何ができるって言うの？",
  ui_story_5_7_55_dialog_content = "PlayerName！大丈夫！？",
  ui_story_5_7_A6_dialog_content = "（落ち着け、落ち着くんだ…あいつに気圧されるな、僕ならきっとできる…）",
  ui_story_5_7_A7_dialog_content = "（いつもどおりに戦えばいい。そうすれば、あの災厄の元凶――スーモアを…）",
  ui_story_5_7_A8_dialog_content = "PlayerName！あなたの目――",
  ui_story_5_7_A9_dialog_content = "ふぅ…",
  ui_story_5_7_A10_dialog_content = "バイス、僕は大丈夫。カレンとスタンバイして。いつもと同じように…",
  ui_story_5_7_A11_dialog_content = "…分かったわ。準備オッケーよ！",
  ui_story_5_7_56_dialog_content = "指揮を任せるわ、PlayerName。我が槍が必ず、一切の悪を貫く！",
  ui_story_5_7_57_dialog_content = "みんな、準備はいい！？敵は――スーモアだ！",
  ui_story_5_7_A12_dialog_content = "弱者はおとなしく潰れていればいいの。",
  ui_story_5_7_58_dialog_content = "しつこいわね。弱者は弱者らしくしていればいいのに！\n足掻いて何になるのよ！？",
  ui_story_5_7_59_dialog_content = "ああもう、面倒だわ。\n指揮だの誘導だの…結局、後ろに隠れてる臆病者じゃない。",
  ui_story_5_7_60_dialog_content = "でも認めてあげる、あんたは他の空の末裔とは少し違うみたいね…",
  ui_story_5_7_61_option_content = "いや、僕は他の空の末裔と同じだ",
  ui_story_5_7_62_option_content = "お前の相手ぐらい余裕だよ！",
  ui_story_5_7_63_dialog_content = "調子に乗るんじゃないわ。今のは誉めたわけじゃない。単なる死刑宣告よ。",
  ui_story_5_7_64_dialog_content = "その程度の力じゃ、私には遥かに及ばない。あんたたち、弱すぎるのよ！",
  ui_story_5_7_65_dialog_content = "強い…",
  ui_story_5_7_66_dialog_content = "握りつぶされるのと踏みつぶされるの、どっちがお好み？",
  ui_story_5_7_67_dialog_content = "今よ！",
  ui_story_5_7_68_dialog_content = "何？この震動は…",
  ui_story_5_7_69_dialog_content = "エクステンド成功！うまく時間が稼げたわね。",
  ui_story_5_7_70_dialog_content = "パーツは手に入れたわ！カレン、PlayerName！",
  ui_story_5_7_71_dialog_content = "あたしが足止めするから、あなた達はパーツを持って撤退して。",
  ui_story_5_7_72_option_content = "でもガルー…",
  ui_story_5_7_73_dialog_content = "あたしなら大丈夫。必殺技をお見舞いしてやるわ！",
  ui_story_5_7_74_option_content = "了解！",
  ui_story_5_7_75_dialog_content = "ゲームのルールを理解するのも強さのうち、あなた、悪くないわ！\n必ずパーツを啓光に持ち帰って！",
  ui_story_5_7_76_dialog_content = "スーモアの攻撃は尋常じゃない、あなた1人では…",
  ui_story_5_7_77_dialog_content = "あたしだってただの科学研究員じゃないの！\n力についていちばん詳しいのもあたし！すっごく強いんだから！！",
  ui_story_5_7_78_dialog_content = "分かったわ。バイス、PlayerName、行きましょう。\nこのチャンスを無駄にするべきではないわ。",
  ui_story_5_7_79_dialog_content = "あんたたちの無駄話もそろそろ聞き飽きたわ。\nさっさとパーツを渡しなさい。",
  ui_story_5_7_80_dialog_content = "それは無理かも？だって、あたしはあなたと戦う気まんまんだもの！",
  ui_story_5_7_A13_dialog_content = "暗鬼の能力をマスターした空の末裔、難易度はマックス、\n絶体絶命のソロチャレンジ。考えただけで燃えてくるわ！",
  ui_story_5_7_81_dialog_content = "さあ、あたしとゲームスタートよ！",
  ui_story_5_7_82_dialog_content = "…つまらないことこの上ないわ！",
  ui_story_5_7_83_dialog_content = "バイス、もうずいぶん経ったけど…まだガルーからの連絡が…",
  ui_story_5_7_84_dialog_content = "ガルー先輩…きっと大丈夫よね。",
  ui_story_5_7_85_dialog_content = "もう時間がないわ。そろそろ飛ばないと。",
  ui_story_5_7_86_dialog_content = "分かってる…",
  ui_story_5_7_87_dialog_content = "ねぇ、何か聞こえない？あっ、トランシーバーからだ！",
  ui_story_5_7_88_dialog_content = "この声は…",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>ガルー先輩</color>！？",
  ui_story_5_8_1_dialog_content = "バイス、急いでパーツを持ってソラヴァンで啓光に戻って。今すぐ――",
  ui_story_5_8_2_dialog_content = "ガルー先輩！",
  ui_story_5_8_3_dialog_content = "もういいわ！何を言うかはきちんと教えたでしょ！？",
  ui_story_5_8_4_dialog_content = "よく聞きなさい。一度しか言わないわ。",
  ui_story_5_8_5_dialog_content = "30分以内にここに戻って、「自己成長ユニット」を渡しなさい。\nさもないと、この女の命はないわ。",
  ui_story_5_8_6_dialog_content = "聞いちゃダメ！今すぐ離脱しなさい！これは命令よ！",
  ui_story_5_8_7_dialog_content = "お黙り！",
  ui_story_5_8_8_dialog_content = "30分なんて短すぎるわ。今すぐ啓光に支援を頼んでも間に合わない…",
  ui_story_5_8_9_dialog_content = "…「自己成長ユニット」を持ち帰れば、多くの人の命を守ることができるでしょう。",
  ui_story_5_8_10_dialog_content = "上官の命令には必ず従うこと。それは常に啓光の者が最優先すべき義務…",
  ui_story_5_8_11_dialog_content = "でも、私はガルー先輩をこのまま見殺しになんてできない。",
  ui_story_5_8_12_dialog_content = "あなたはまったく変わってないのね。\n良く言えば優しい、悪く言えば優柔不断。",
  ui_story_5_8_13_dialog_content = "1人の命と大勢の人の命を選ぶことが、そんなに難しいかしら？",
  ui_story_5_8_14_dialog_content = "…私はどの命も守りたいの。",
  ui_story_5_8_15_dialog_content = "グォォ――！",
  ui_story_5_8_16_dialog_content = "まずは巨像に取りついた邪魔者を始末して、あとの事はまた話し合いましょう。",
  ui_story_5_10_1_dialog_content = "あのザコども、どうして行動を起こさないの？さては時間を稼ぐつもり？",
  ui_story_5_10_2_dialog_content = "けど、私のガマンにも限度がある。あと20分――いえ、19分よ！",
  ui_story_5_10_3_dialog_content = "19分経ったら、この小娘の身体を少しづつ切り刻んでやるわ。",
  ui_story_5_10_4_dialog_content = "叫び声を想像しただけでゾクゾクしてくるわね。",
  ui_story_5_10_5_dialog_content = "ユニットを渡す以外にガルー先輩を救う方法はないの？",
  ui_story_5_10_6_dialog_content = "狂ってる…",
  ui_story_5_10_7_option_content = "解決方法は他にもありそうだよ",
  ui_story_5_10_8_dialog_content = "えっ？",
  ui_story_5_10_9_dialog_content = "うん、逆転できると思う…15分もあれば十分だ。",
  ui_story_5_10_10_dialog_content = "どういうこと？",
  ui_story_5_10_11_dialog_content = "ちょっとした裏技、ってやつかな…",
  ui_story_5_10_12_option_content = "僕だってみんなを守りたい",
  ui_story_5_10_13_dialog_content = "PlayerName…私に賛成してくれるの？",
  ui_story_5_10_14_dialog_content = "ガルーの命も、みんなの命も、全部守ろう。",
  ui_story_5_10_15_dialog_content = "バイスもあなたもこの様子じゃ、もう降参よ。",
  ui_story_5_10_16_dialog_content = "そこまで言うなら、打開策を思いついたのでしょうね。",
  ui_story_5_10_17_dialog_content = "そうだよ！かなり危ないけど、でも…手伝って欲しい。",
  ui_story_5_10_A1_dialog_content = "これから僕たちは攻撃に転じる。迅速に動かないといけないよ！",
  ui_story_5_10_A2_dialog_content = "聞いて、作戦を説明するから…",
  ui_story_5_10_18_dialog_content = "もうあと数分しかないのに、逃げるわけでも、従うわけでもない。\nまだ迷っているの…？",
  ui_story_5_10_19_dialog_content = "王座――起動！",
  ui_story_5_10_20_dialog_content = "身のほど知らずが。",
  ui_story_5_10_21_dialog_content = "やっぱり効かない…！？",
  ui_story_5_10_22_dialog_content = "捨て身の攻撃、もう3回目よ。本当に命知らずね。\nでも今はまだ死なせてあげない。おとなしくしてなさい。",
  ui_story_5_10_23_dialog_content = "驚愕の――コンボ――",
  ui_story_5_10_24_dialog_content = "クラクラする…もうゲームオーバーかな…",
  ui_story_5_10_25_dialog_content = "そうやって眠ってなさい。\nあと数分したら、永遠の眠りにつかせてあげるわ。",
  ui_story_5_10_A3_dialog_content = "――もう1匹！",
  ui_story_5_10_A4_dialog_content = "速い！スーモアには気付かれていないわね？",
  ui_story_5_10_A5_dialog_content = "私は敵から逃げ隠れするような戦い方がとても苦手なのだけれど、PlayerName。",
  ui_story_5_10_A6_dialog_content = "2人ともすごいや。さあ、先に進もう。\n僕たちにはもう他の選択肢はないんだから。",
  ui_story_5_13_1_dialog_content = "あと5分ね。そろそろ起きなさい。",
  ui_story_5_13_2_dialog_content = "クル、クルクル…目の前にお星さまが～。星を食べたらレベルアップできないかな…",
  ui_story_5_13_3_dialog_content = "起きなさい！",
  ui_story_5_13_4_dialog_content = "おうおうおう、気絶させたのはあんたのくせに、今度は起きろって？さすがの悪役だわ。",
  ui_story_5_13_5_dialog_content = "残り5分なのに、動きがないわ。あんた、見捨てられたんじゃない？",
  ui_story_5_13_6_dialog_content = "それでいいのよ。\nもし戻って来たら、あんたより先にあたしがあの子たちをぶん殴ってやるわ。",
  ui_story_5_13_7_dialog_content = "ふん、私も待つのに飽きてきたところよ。",
  ui_story_5_13_A1_dialog_content = "手間は増えるけど、まずはあんたを始末して、\nその後あいつらを片付ければいいだけね。",
  ui_story_5_13_8_dialog_content = "ちょっとちょっと？タイムオーバー前に人質を殺しちゃうの！？\nそれはルール違反でしょ！",
  ui_story_5_13_9_dialog_content = "ルール？ゲームのルールは強い者が決めるのよ。",
  ui_story_5_13_A2_dialog_content = "その小うるさい口を永遠に閉じなさい――",
  ui_story_5_13_10_dialog_content = "何！？",
  ui_story_5_13_11_dialog_content = "アイスブロッサム！",
  ui_story_5_13_12_dialog_content = "選んだのは不意打ち、ね…",
  ui_story_5_13_13_dialog_content = "スーモアは精神がすごく不安定だ。\n約束を守らない可能性の方が高いと思う。",
  ui_story_5_13_14_dialog_content = "ガルーが危ない。とにかく急がないと。",
  ui_story_5_13_A3_dialog_content = "準備できたわ、PlayerName。計画通りに行きましょう！",
  ui_story_5_13_A13_dialog_content = "ソラヴァンを元の位置に停めて、スーモアの判断を鈍らせる。そして――",
  ui_story_5_13_17_dialog_content = "奇襲をかけるんだ！\nこっちから攻撃を仕掛けてくるとは思っていないはず！",
  ui_story_5_13_18_dialog_content = "迷っているふり、それから奇襲？",
  ui_story_5_13_19_dialog_content = "でも、うまくいったみたいね！諦めなさい、スーモア！\n周りの暗鬼もとっくに始末したわ！",
  ui_story_5_13_20_dialog_content = "ふん、これでうまくいったと思ってるなら…",
  ui_story_5_13_21_dialog_content = "あたしを忘れないでよ！食らえ！",
  ui_story_5_13_22_dialog_content = "やった！ボスはダメージを負ったし、\nこっちはまたパーティ4人が勢ぞろい！形勢逆転ね！",
  ui_story_5_13_A4_dialog_content = "もう大事なパーツは安全なところに隠してあるんでしょ？\nそれなら、遠慮なくボコボコにできるわね！",
  ui_story_5_13_24_dialog_content = "カレン、私たちも行くわよ！",
  ui_story_5_13_26_dialog_content = "ええ！反撃の隙は与えない！",
  ui_story_5_13_27_dialog_content = "あなたはここまでよ！",
  ui_story_5_13_28_dialog_content = "…ふん、あんたたちみたいなクズにナメられるなんてね。",
  ui_story_5_13_29_dialog_content = "あたりの雰囲気が変わった！？",
  ui_story_5_13_30_dialog_content = "彼女の力、今までと全く違う…！",
  ui_story_5_13_31_dialog_content = "つけあがって、よほど死に急いでるようね。\nなら、手加減も無用ってことよね？",
  ui_story_5_13_A14_dialog_content = "悪くないわ！さっきよりは強いじゃない！面白くなってきたわ。",
  ui_story_5_13_A15_dialog_content = "さっきの「勝利を確信した」みたいな顔つき、\n最高にムカつくのよ！ひざまずきなさい！",
  ui_story_5_13_A16_dialog_content = "これって…力がケタ違いに上がってる！？",
  ui_story_5_13_A17_dialog_content = "まさか…全力を出してなかったのか、僕たちを…もてあそぶために？",
  ui_story_5_13_32_dialog_content = "（まずい！このままだと全滅だ――）",
  ui_story_5_13_A5_dialog_content = "（あの時、同族のみんなも同じ絶望の中で懸命にもがいていたのかな？\nこんなに圧倒的な力の前で…）",
  ui_story_5_13_33_dialog_content = "（暗鬼の力を受け入れた空の末裔は…こんなに強くなれるの？）",
  ui_story_5_13_34_dialog_content = "驚いた？か弱い空の末裔でも、ここまで強くなれるのよ。\nこれこそが日蝕に授けられた力！",
  ui_story_5_13_35_dialog_content = "<size=45>光霊を超越する強さよ！</size>",
  ui_story_5_13_36_dialog_content = "く、苦しい…息が…",
  ui_story_5_13_37_dialog_content = "さあ、選びなさい。この女の命か、「自己成長ユニット」か。",
  ui_story_5_13_38_dialog_content = "うっ…ダメ、渡しちゃダメ…",
  ui_story_5_13_39_dialog_content = "ガルー！…バイス、カレン…",
  ui_story_5_13_40_dialog_content = "くっ、私はまだ戦える…まだ戦え…る…",
  ui_story_5_13_41_dialog_content = "僕は…！",
  ui_story_5_13_42_dialog_content = "あら、まだ何かあるの？\nまさか…私と戦う気？何の戦闘能力もない、あんたが？",
  ui_story_5_13_43_dialog_content = "ハハ…アハハハハ！とんだお笑いね。",
  ui_story_5_13_44_dialog_content = "僕には…確かに戦う力がない、でも、この拳はある…",
  ui_story_5_13_45_dialog_content = "スーモア！！",
  ui_story_5_13_46_dialog_content = "PlayerName、行っちゃダメ！",
  ui_story_5_13_47_dialog_content = "確かに僕は光力を使えない、空の末裔だ…\nでも、戦うことが怖いわけじゃない！",
  ui_story_5_13_48_dialog_content = "僕は僕の仲間を守る、僕の同胞を、僕の家族を守る！！！",
  ui_story_5_13_A6_dialog_content = "こぶしが砕けたら噛みついてやる。歯が全て折れても、頭突きで戦う！",
  ui_story_5_13_A7_dialog_content = "僕は屈しない！空の末裔も屈しない！スーモア…今こそ、僕は…",
  ui_story_5_13_49_dialog_content = "<size=45>みんなの前に立って、守る！</size>",
  ui_story_5_13_A8_dialog_content = "…",
  ui_story_5_13_A9_dialog_content = "ふん…くだらない。",
  ui_story_5_13_50_dialog_content = "口先だけの決めセリフなんて、聞き飽きてるのよ。\nだいたい、大声を張り上げて、何になるっていうのかしら？",
  ui_story_5_13_51_dialog_content = "うぐっ…",
  ui_story_5_13_52_dialog_content = "PlayerName、どうして、そこまで…",
  ui_story_5_13_53_dialog_content = "早く選びなさい、クズが。ユニットか、あの女たちの命か。\n10数える間にね。10、9…",
  ui_story_5_13_54_option_content = "条件がある…",
  ui_story_5_13_55_option_content = "わかった、パーツを渡すよ",
  ui_story_5_13_56_dialog_content = "ふん、この私に条件ですって？あははっ…",
  ui_story_5_13_57_dialog_content = "パーツは渡す。でも、その前に彼女たちを放すんだ！",
  ui_story_5_13_58_dialog_content = "笑わせないでちょうだい。条件を言える立場だと思っているの？\n土下座をして命乞いでもするところでしょ。",
  ui_story_5_13_59_dialog_content = "先に彼女たちを放して。そうしたら、僕の命でもパーツでも、すべて渡すよ。\nさもなければ、壊す…",
  ui_story_5_13_60_dialog_content = "壊す？それに、その「死地に向かう勇者」みたいな顔つき。\nモンドルの真似か何か？心底、ヘドが出るわ。",
  ui_story_5_13_F1_dialog_content = "…でも、いいわ。解放してあげる。",
  ui_story_5_13_F2_dialog_content = "パーツは渡すよ…",
  ui_story_5_13_F3_dialog_content = "哀れな空の末裔。力がないゆえに蹂躙されるがまま。\n強者の施しがなければ、生き延びることさえできない。",
  ui_story_5_13_F4_dialog_content = "アハハっ、誰かの思うままにされるのって最悪の気分でしょう？",
  ui_story_5_13_F5_dialog_content = "空の末裔に何が起こったか、改めて理解したかしら？",
  ui_story_5_13_F6_dialog_content = "よく覚えておくことね。<size=45>弱者</size>はこういう屈辱に、耐えていかないといけないのよ。\nさもなきゃ、みじめに逃げ延びる機会だって与えられないのだから。",
  ui_story_5_13_61_dialog_content = "空の末裔は哀れな一族。力がないゆえに蹂躙されるがまま。\n強者の施しがなければ、生き延びることさえできない。",
  ui_story_5_13_F7_dialog_content = "パーツのためでもなきゃ、あんた達なんて視界に入れる価値も無いのよ。",
  ui_story_5_13_68_dialog_content = "死なずに済んでよかったわね。強者からの慈悲よ、感謝しなさい。アハハ…",
  ui_story_5_13_69_dialog_content = "ガルー先輩、大丈夫ですか？2時間近く意識を失ってたなんて…",
  ui_story_5_13_70_dialog_content = "HPがもうカラッポだけど…大丈夫、復活したわ…",
  ui_story_5_13_F8_dialog_content = "ゴメン、あたしを助けるためにパーツが…",
  ui_story_5_13_71_dialog_content = "いいえ、ガルー先輩。私たちが弱かっただけ…",
  ui_story_5_13_72_dialog_content = "でも、全員生きてる。最悪の結果は免れました。",
  ui_story_5_13_73_dialog_content = "確かに、それだけでも十分すごいわね！",
  ui_story_5_13_74_dialog_content = "フィリスから説明された時には半信半疑だったけど、でもこの目で見たら…",
  ui_story_5_13_A10_dialog_content = "スーモアの強さはあたしの想像をはるかに超えてた！",
  ui_story_5_13_75_dialog_content = "ここでの出来事はキッチリまとめて、上層部にことの重大性を知らせるわ。",
  ui_story_5_13_76_dialog_content = "この次は…3つ目のパーツよね？",
  ui_story_5_13_77_dialog_content = "<color=#FFB400>「射撃統制モジュール」</color>…",
  ui_story_5_13_78_dialog_content = "巨像を改造して、攻撃能力をもたせるための超強力な武器パーツ…\nでも、手がかりは全くないんじゃないの？",
  ui_story_5_13_79_option_content = "方法はある",
  ui_story_5_13_F9_dialog_content = "スーモアの気配はもう、十分心に刻まれたよ。\nもう死んでも忘れないと思う。",
  ui_story_5_13_F10_dialog_content = "それに、スーモアはまだそう遠くへは行ってないはず。\n目を閉じればすぐにでも…",
  ui_story_5_13_F11_dialog_content = "…そう、「弱者」らしく息をひそめて潜入すれば、\n気付かれることはないんだ。",
  ui_story_5_13_80_dialog_content = "（これは…無数のトラップが張り巡らされた、入り組んだ迷宮が見える…）",
  ui_story_5_13_81_dialog_content = "（神秘的で、陰鬱で、悪趣味な収蔵品に溢れる場所…）",
  ui_story_5_13_82_dialog_content = "スーモアならきっと、行くべき場所をもう分かっているはず…",
  ui_story_5_13_83_dialog_content = "…<color=#FFB400>ささやきの回廊</color>…",
  ui_story_5_13_85_option_content = "ささやきの回廊だ！",
  ui_story_6_1_1_dialog_content = "スーモア、本当に手ごわかったわね…",
  ui_story_6_1_2_dialog_content = "パーツをすべて集められたら、もっと大変なことになる…",
  ui_story_6_1_3_dialog_content = "（カレンもバイスも落ち込んでる。どうにか雰囲気をよくしないと）",
  ui_story_6_1_F1_dialog_content = "直接追いかければ、もしかしたらスーモアが\n次のパーツを手に入れるのを防げるかもしれないよ。",
  ui_story_6_1_F2_dialog_content = "もちろん、とても危険なことだっていうのはわかってるけど…",
  ui_story_6_1_4_option_content = "カレンの考えは？",
  ui_story_6_1_5_dialog_content = "先延ばしにはできない。\n今やるべきことは一刻も早くスーモアを追撃することよ。",
  ui_story_6_1_6_option_content = "バイスはどう思う？",
  ui_story_6_1_7_dialog_content = "さっき本部に連絡して、<color=#FFB400>ささやきの回廊</color>に向かうって報告したわ。",
  ui_story_6_1_8_dialog_content = "ささやきの回廊のこと…みんな、知ってるの？",
  ui_story_6_1_9_dialog_content = "あそこは<color=#FFB400>影ノ街</color>の縄張りよ。\n白夜城に留学していた時、聞いたことがあるわ。",
  ui_story_6_1_10_dialog_content = "さすがは皆勤賞の優等生ね。もっと詳しく知っているのでしょう？",
  ui_story_6_1_11_dialog_content = "うっ…オッホン！ささやきの回廊は元々、影ノ街の外にあった地下遺跡だったの。",
  ui_story_6_1_12_dialog_content = "白夜城の人が発見して、価値のあるものがたくさん発掘されてるわ。",
  ui_story_6_1_13_dialog_content = "でも、掘りつくされて、廃墟になったの。",
  ui_story_6_1_14_dialog_content = "その後、放浪者や罪人たちの巣窟になって混乱を極めたそうよ。",
  ui_story_6_1_A1_dialog_content = "でも十数年前、<color=#FFB400>イスタバン組</color>という組織が影ノ街に台頭して…",
  ui_story_6_1_A2_dialog_content = "イスタバンっていうのはリーダーの名前でもあるのよ。\nみんなから尊敬されていて、「シャドウマスター」と呼ばれているわ。",
  ui_story_6_1_A3_dialog_content = "その人たちがささやきの回廊を管理するようになってからは、\n誰もむやみに押し入ったりできなくなったそうよ。",
  ui_story_6_1_A4_dialog_content = "今は、いろいろな珍しい骨董品を保管する「保管庫」になっているって聞いたわ。",
  ui_story_6_1_A5_dialog_content = "まるで「生き字引」だ。よく知ってるね…",
  ui_story_6_1_F3_dialog_content = "エへへ、褒めてくれてありがとう。",
  ui_story_6_1_A6_dialog_content = "「シャドウマスター」には手紙を出してあるわ。\n援助を取り付けられればと思って。",
  ui_story_6_1_A7_dialog_content = "ささやきの回廊に着いた時、\nシャドウマスターの仲間が対応してくれるかもしれないわ。",
  ui_story_6_1_A8_dialog_content = "あなたの文法が前のままだったら、\nおそらくシャドウマスターも相手にしてくれないでしょうね。",
  ui_story_6_1_F4_dialog_content = "もう、下手でも出さないわけにはいかないじゃない！",
  ui_story_6_1_15_dialog_content = "そうだ！みんなと共有しておきたい情報があるの。\n啓光軍部でまた会議があって…",
  ui_story_6_1_16_dialog_content = "軍団長の皆さん、よくお考えになってください。\nささやきの回廊はシャドウマスターの財産ではありますが、敵の性質を考えると…",
  ui_story_6_1_17_dialog_content = "ガルー室長にも手を出した。公然と挑発していると見て間違いないでしょう。",
  ui_story_6_1_F5_dialog_content = "PlayerName達の情報がなければ、\n我々は今もスーモアの行動を一切知らなかった可能性があります。",
  ui_story_6_1_18_dialog_content = "あのガキどもがいなかったら、こんなことは\nそもそも起こらなかったかもしれない。違うか？",
  ui_story_6_1_19_dialog_content = "いいえ、PlayerNameの存在は、\nスーモアがパーツを集め始めたことと無関係です。",
  ui_story_6_1_20_dialog_content = "責任の話はひとまず後にするか。\nヒイロ！私と一緒に兵を出すか出さないか、それだけ答えてくれ！",
  ui_story_6_1_21_dialog_content = "ええと…その…",
  ui_story_6_1_22_dialog_content = "兵を出したくないのではありません。\n啓光を侵す者を前にして、私もあなたと同じ心境です…",
  ui_story_6_1_23_dialog_content = "しかし、大元帥様は「兵を動かさず時機を待て」と。",
  ui_story_6_1_X23_dialog_content = "大元帥様はなんだってそんな命令を？",
  ui_story_6_1_X24_dialog_content = "皆さん、まずは落ち着いてください！お気持ちはわかります。",
  ui_story_6_1_X25_dialog_content = "でも大元帥様の命令がない限り、私たちは引き続き様子見するしかありません。",
  ui_story_6_1_X26_dialog_content = "大元帥様には私たちの知る由もない深いお考えがあるのでしょう。\n啓明の光を信じましょう。",
  ui_story_6_1_X27_dialog_content = "…",
  ui_story_6_1_X28_dialog_content = "バートンたちは？どうしてここにいないんだ？",
  ui_story_6_1_X29_dialog_content = "バートンとあの筋肉女も兵を出すと言えば、\n大元帥様にもう少し強く出られるが…",
  ui_story_6_1_X30_dialog_content = "ほかの軍団長にも緊急の任務が入っているのです。",
  ui_story_6_1_X31_dialog_content = "ローナ、あなたは私と一緒に白夜城近郊で防衛線を張ります。",
  ui_story_6_1_25_dialog_content = "やはり、表向きにも何らかの動きは必要ということでしょう。",
  ui_story_6_1_27_dialog_content = "ということで…\nスーモアの目的が何であろうと、私たちだけで明らかにしなきゃいけないわ。",
  ui_story_6_1_28_dialog_content = "この前は運よくフィリス先輩とガルー先輩が助けてくれたけど、今回は…",
  ui_story_6_1_F6_dialog_content = "今から行くところはそもそも影ノ街の縄張り。\nおまけに影ノ街の上は白夜城だから…",
  ui_story_6_1_F7_dialog_content = "えぇ、わかっているわ。\nいくら啓光と白夜城が協力関係にあると言っても、色々と隔たりがあるの。",
  ui_story_6_1_29_dialog_content = "でも、このままじゃどちらにも利はない。特に今みたいな状況ではね。",
  ui_story_6_1_30_dialog_content = "せめて白夜城の助けが得られればと思うけれど…",
  ui_story_6_1_31_dialog_content = "カレン隊長、首尾はどうだ？",
  ui_story_6_1_32_dialog_content = "申し訳ございません、失敗しました。\n<color=#FFB400>「自己成長ユニット」</color>は持ち去られました。",
  ui_story_6_1_33_dialog_content = "死傷者は？",
  ui_story_6_1_34_dialog_content = "全員生存しております。",
  ui_story_6_1_35_dialog_content = "しかし、例の者が私たちより一足先にささやきの回廊へ向かいました。",
  ui_story_6_1_36_dialog_content = "殿下、護衛隊の出動を要請致します。できれば、四大天使を。",
  ui_story_6_1_37_dialog_content = "許可できんな。",
  ui_story_6_1_38_dialog_content = "父う…殿下、あの者に<color=#FFB400>「射撃統制モジュール」</color>まで持ち去られては、\n取り返しのつかないことになります！",
  ui_story_6_1_39_dialog_content = "巨像の改造が完了次第、白夜城を脅かす動きをとりかねないのですよ！？",
  ui_story_6_1_40_dialog_content = "その通りだ。カレン隊長。それがわかっているからこそ、護衛隊は動かさぬ。",
  ui_story_6_1_41_dialog_content = "殿下、護衛隊長である私には護衛隊の統括権があります。\n彼女らを私にお預けください。",
  ui_story_6_1_42_dialog_content = "余にはその権利を剥奪することもできるのだ、護衛隊長。",
  ui_story_6_1_43_dialog_content = "…では、私は護衛隊長として白夜城を代表し、\n彼らを掩護します――たとえ、私1人でも。",
  ui_story_6_1_45_dialog_content = "カレン、その勇敢さには敬意を表しよう。",
  ui_story_6_1_46_dialog_content = "PlayerName！\n白夜の名の下に、お主らはカレン隊長の安全を保障せよ。",
  ui_story_6_1_47_dialog_content = "え？は、はいっ。",
  ui_story_6_1_48_dialog_content = "<size=30>…私もPlayerNameも、白夜城の人じゃないけど…</size>",
  ui_story_6_1_49_dialog_content = "でも、護衛隊長じゃなくたって、そうするわ。仲間だもの！",
  ui_story_6_1_50_dialog_content = "…無駄話はひとまず置いておきましょう。そろそろ着く頃ね。",
  ui_story_6_1_51_dialog_content = "物寂しいわね。随分長い間、人が足を踏み入れていないみたいだわ。",
  ui_story_6_1_52_dialog_content = "ソラヴァンがいてくれて良かったわ！\nそうでなきゃ、スーモアに追いつけなかったもの。",
  ui_story_6_1_F8_dialog_content = "ソラヴァン、バイスに褒められてるよ。",
  ui_story_6_1_53_dialog_content = "私はそもそもあなたのために存在していますから、お役に立てて光栄です。",
  ui_story_6_1_54_dialog_content = "しかし、この雰囲気…かつての天空ノ谷と同様、不穏に感じます。",
  ui_story_6_1_55_dialog_content = "PlayerName、暗鬼がどこから出てきてもおかしくないわ、注意して。\nソラヴァンの今の位置は安全？",
  ui_story_6_1_56_dialog_content = "あの辺りの山の向こうに停めれば、巨像が隠れられるぐらいの林があるよ。",
  ui_story_6_1_57_dialog_content = "安心して、ソラヴァンは「隠れ方」をよく知ってる。\n僕たちが戦う間は、そこで僕たちの帰還を待っていてくれるよ。",
  ui_story_6_1_58_dialog_content = "なんだか「家で自分の帰りを待つ人がいる」みたいな温かみを感じちゃったわ…\n後はお風呂でもあれば、もっといいけど…",
  ui_story_6_1_59_dialog_content = "まだまだ子どもっぽいわね。",
  ui_story_6_1_A9_dialog_content = "それにしても、こんなところにあなたの言っていた「保管庫」があるの？\nどう見てもただの荒れ果てた野山しかないわ。",
  ui_story_6_1_A10_dialog_content = "ささやきの回廊の入口は隠されているの。よく調べないと見つけられないわ。",
  ui_story_6_1_A11_dialog_content = "バイス、それってつまり…",
  ui_story_6_1_A12_dialog_content = "その通り！入り口はまさに私たちの足元よ！",
  ui_story_6_1_A13_dialog_content = "足元…？ささやきの回廊は地底にあるの？",
  ui_story_6_1_A14_dialog_content = "足元に注意して！仕掛けを解くわ！",
  ui_story_6_1_A15_dialog_content = "地面が――裂けてる？？",
  ui_story_6_1_A16_dialog_content = "わ――これは…",
  ui_story_6_1_A17_dialog_content = "随分手間をかけているのね。\nどうしてこんな設計になってるのか、理解しがたいわ。",
  ui_story_6_1_A18_dialog_content = "こんな凝った隠し方をするのは…不法行為と不義の匂いがするわね。",
  ui_story_6_1_A19_dialog_content = "この下がささやきの回廊よ。PlayerName、何か感知できる？",
  ui_story_6_1_60_dialog_content = "スーモアは…おそらくこの下にいる。下の方から寒気が漂ってきてるよ。",
  ui_story_6_1_A20_dialog_content = "やっぱり、中は寒いわね！",
  ui_story_6_1_A21_dialog_content = "今は不満を言ってる時ではないわ。急がないと。",
  ui_story_6_1_61_dialog_content = "スーモアの具体的な位置を感知する方法はある？",
  ui_story_6_1_62_dialog_content = "ごめん。ささやきの回廊の中にいるとしかわからないんだ。具体的な位置は…",
  ui_story_6_1_63_dialog_content = "それは困ったわね…",
  ui_story_6_1_64_dialog_content = "ささやきの回廊の中は地形が複雑で、隠された出入り口や通路だらけなの。\n完全に知っているのはシャドウマスターだけだそうよ。",
  ui_story_6_1_65_dialog_content = "だから、この場所が「保管庫」になったの。",
  ui_story_6_1_F9_dialog_content = "モノは影ノ街よりもここに置いておく方がずっと安全ってことなんでしょうね。",
  ui_story_6_1_66_dialog_content = "まって、誰か来た！",
  ui_story_6_1_67_dialog_content = "気を付けて！暗鬼かもしれないわ…",
  ui_story_6_1_68_dialog_content = "PlayerNameが慌てていないのを見る限り、光霊ね。",
  ui_story_6_1_70_dialog_content = "随分にぎやかね！\n6重か7重には壁や扉を隔てていたはずなのに、皆の熱い議論が聞こえてきたわ。",
  ui_story_6_1_71_dialog_content = "アハハ、本当に面白いわね。\n白夜城の貴族令嬢、啓光の若い女軍人、それに空の末裔――",
  ui_story_6_1_72_dialog_content = "お偉方の言っていた巨像のチームって、あなたたちのことね。",
  ui_story_6_1_73_dialog_content = "白夜城と啓光は傍観を決め込んだみたいだけど、\nシャドウマスターからわざわざ私の方に、皆と協力するようお話があったの。",
  ui_story_6_1_X73_dialog_content = "まったく、面倒よね…",
  ui_story_6_1_74_dialog_content = "やっぱり…肝心な時には救いの手が現れるってことね！",
  ui_story_6_1_F10_dialog_content = "私のことは、「シェオル」って呼んでちょうだい。何かお困りかしら？",
  ui_story_6_1_75_option_content = "中に誰か入っていったのを見ましたか？",
  ui_story_6_1_76_dialog_content = "普段はほとんど人が来ないんだけど、最近、暗鬼がやって来たみたい。\n何も盗られてはいないみたいだけど…",
  ui_story_6_1_77_dialog_content = "スーモア…",
  ui_story_6_1_78_dialog_content = "それより、あなた達が立ち向かおうとしている敵が、今この中にいるの？",
  ui_story_6_1_79_dialog_content = "それよりも、さっきからいたのに、盗み聞きをしていたということ？",
  ui_story_6_1_80_dialog_content = "まぁ、PlayerName。お連れの女の子たち、鋭いじゃない。",
  ui_story_6_1_81_dialog_content = "ええと…シェオルさん。そのことは答えたくなかったら別に構わないんですけど、\nここについて教えていただけませんか？",
  ui_story_6_1_82_dialog_content = "ここが元々廃墟だったのは、知っているわよね。",
  ui_story_6_1_83_dialog_content = "だから、とっても安かったの。そこで、シャドウマスターが買い取ったってこと。\n誰よりもこの場所に詳しいのはシャドウマスターなの。",
  ui_story_6_1_84_dialog_content = "ささやきの回廊に見張りはいないけど、勝手に入り込む悪人たちは「道に迷う」か、\n「落とし穴に落ちる」かどちらかの運命を辿るのよ。",
  ui_story_6_1_85_dialog_content = "要するに、ガイドもなしで保管している部屋に辿り着くのは不可能っていうわけ。",
  ui_story_6_1_86_dialog_content = "それで、私たちのガイドは…",
  ui_story_6_1_87_dialog_content = "他に誰かいるかしら？",
  ui_story_6_1_88_dialog_content = "あ！そうね…では、よろしくお願いします。",
  ui_story_6_1_89_dialog_content = "あら？ガイドになるなんて一言も言ってないわよ？",
  ui_story_6_1_90_dialog_content = "そっちの女の子、とっても可愛いわぁ。\nPlayerName。あなた、本当に恵まれてるわね。",
  ui_story_6_1_91_dialog_content = "…何か誤解してませんか…？",
  ui_story_6_1_92_dialog_content = "それなら、私たちが何を探しているかはご存じかしら。\n「射撃統制モジュール」について聞いたことは？",
  ui_story_6_1_93_dialog_content = "いいえ…知らないわ…",
  ui_story_6_1_94_option_content = "ここについて教えていただけませんか？",
  ui_story_6_1_95_dialog_content = "ここが元々廃墟だったのは、知っているわよね。",
  ui_story_6_1_96_dialog_content = "だから、とっても安かったの。そこで、シャドウマスターが買い取ったってこと。\n誰よりもこの場所に詳しいのはシャドウマスターなの。",
  ui_story_6_1_97_dialog_content = "ささやきの回廊に見張りはいないけど、勝手に入り込む悪人たちは「道に迷う」か、\n「落とし穴に落ちる」かどちらかの運命を辿るのよ。",
  ui_story_6_1_98_dialog_content = "要するに、ガイドもなしで保管している部屋に辿り着くのは不可能っていうわけ。",
  ui_story_6_1_99_dialog_content = "それで、私たちのガイドは…",
  ui_story_6_1_100_dialog_content = "他に誰かいるかしら？",
  ui_story_6_1_101_dialog_content = "あ！そうね…では、よろしくお願いします。",
  ui_story_6_1_102_dialog_content = "あら可愛い。ガイドになるなんて一言も言ってないわよ？",
  ui_story_6_1_103_dialog_content = "PlayerName、お仲間の女の子、とってもかわいくて礼儀正しいわね。",
  ui_story_6_1_104_dialog_content = "…ええと…あの、話を戻してもらえますか？僕たち、急いでいるので…",
  ui_story_6_1_105_dialog_content = "あら？それもそうね。敵はもう中にいるかも知れないし。",
  ui_story_6_1_106_dialog_content = "そこら中に暗鬼に荒らされた跡が残ってるわね。\nしかも、全部ささやきの回廊の奥まで続いてる…",
  ui_story_6_1_107_dialog_content = "これはまずいわねぇ。\nあなた達が探してるもの、もしかしたら、もうとられているかもしれないわ。",
  ui_story_6_1_108_dialog_content = "…では、「射撃統制モジュール」のある所まで案内をお願いしていいかしら？",
  ui_story_6_1_109_dialog_content = "ん？なあにそれ？聞いたことないわ。",
  ui_story_6_1_110_option_content = "僕たち、探し物をしてるんです",
  ui_story_6_1_111_dialog_content = "それは分かってるわよ。だって、ここに来る人はみんな何かを探しにくるんだから。\nでも、暗鬼のほうが一足早かったみたいね…",
  ui_story_6_1_112_dialog_content = "暗鬼が入ってきたことは知っています…だからグズグズしていられないんです！",
  ui_story_6_1_113_dialog_content = "まぁまぁ、落ち着いて。",
  ui_story_6_1_114_dialog_content = "ここが元々廃墟だったのは、知っているわよね。",
  ui_story_6_1_115_dialog_content = "だから、とっても安かったの。そこで、シャドウマスターが買い取ったってこと。\n誰よりもこの場所に詳しいのはシャドウマスターなの。",
  ui_story_6_1_116_dialog_content = "ささやきの回廊に見張りはいないけど、勝手に入り込む悪人たちは「道に迷う」か、\n「落とし穴に落ちる」かどちらかの運命を辿るのよ。",
  ui_story_6_1_117_dialog_content = "要するに、ガイドもなしで保管している部屋に辿り着くのは不可能っていうわけ。",
  ui_story_6_1_118_dialog_content = "それで、私たちのガイドは…",
  ui_story_6_1_119_dialog_content = "他に誰かいるかしら？",
  ui_story_6_1_120_dialog_content = "あ！そうね…では、よろしくお願いします。",
  ui_story_6_1_121_dialog_content = "あら？ガイドになるなんて一言も言ってないわよ？",
  ui_story_6_1_122_dialog_content = "そっちの女の子、とっても可愛いわぁ。PlayerName。あなた、本当に恵まれてるわね。",
  ui_story_6_1_123_dialog_content = "あの、まじめに話してるんです…",
  ui_story_6_1_124_dialog_content = "シェオルさん、私たちが何を探しているかはご存じかしら。\n「射撃統制モジュール」について聞いたことは？",
  ui_story_6_1_125_dialog_content = "いいえ…知らないわ…",
  ui_story_6_1_126_dialog_content = "<size=30>嘘ね。</size>",
  ui_story_6_1_127_dialog_content = "<size=30>わかってる。</size>",
  ui_story_6_1_128_dialog_content = "シェオルさん、僕たちは勝手に押し入ろうとしているわけじゃありません。\n手紙で事情を説明しているのが、何よりの証拠です。",
  ui_story_6_1_129_dialog_content = "わかっているわよ。「スーモア」っていう子を止めたいんでしょ？",
  ui_story_6_1_130_dialog_content = "はい、白夜城で何があったのか、たぶんもう、ご存知ですよね。",
  ui_story_6_1_131_dialog_content = "<color=#FFB400>「射撃統制モジュール」</color>を手に入れるためなら、\nスーモアは手段をえらばないはずです。",
  ui_story_6_1_132_dialog_content = "だから、ここに向かっていると分かった時、すぐにシャドウマスターに連絡しました。\n万が一、暗鬼の群れが攻めてきたら…",
  ui_story_6_1_F11_dialog_content = "影ノ街が危ない…なるほど、誠実な気持ちが伝わって来たわぁ。\nこれじゃ、信じない方が難しいくらいねぇ。",
  ui_story_6_1_F12_dialog_content = "でも、あなた達はどうして彼女がここに来ることがわかったのかしら？",
  ui_story_6_1_F13_dialog_content = "それについても、正直に答えると…\n空の末裔の能力で、スーモアの行動を感知したんです。",
  ui_story_6_1_134_dialog_content = "あら？さすがは空の末裔ってことね。\n悪くないわ、誠意には応えてあげないとね。ガイドを引き受けてあげる。",
  ui_story_6_1_135_dialog_content = "じゃあ、お願いしますね。",
  ui_story_6_1_136_dialog_content = "やっぱり可愛いわぁ…",
  ui_story_6_1_137_dialog_content = "…あと何層あるの？もうすぐかしら？",
  ui_story_6_1_138_dialog_content = "まさかぁ。やっと外周に入ったところよ！先はまだまだ長いわ。",
  ui_story_6_1_139_dialog_content = "うそ…カナン城よりも複雑じゃない。",
  ui_story_6_1_140_dialog_content = "「射撃統制モジュール」が、どうしてこんな所にあるんですか？",
  ui_story_6_1_141_dialog_content = "十数年前の暗鬼との戦争の時、\nシャドウマスターがある戦場跡で見つけたそうよ。",
  ui_story_6_1_142_dialog_content = "私も一度しか見たことはないけど、\n埃をかぶった骨董品にしか見えなかったわ。",
  ui_story_6_1_143_dialog_content = "あなた達がこなかったら、ずっとここに保管されたまま、\n日の目を見ることはなかったでしょうね。",
  ui_story_6_1_144_dialog_content = "待って。ここ…何かおかしい。",
  ui_story_6_1_145_dialog_content = "誰かが扉を壊したみたいね？",
  ui_story_6_1_146_dialog_content = "そんな事をするのは、光霊ではないでしょうね。",
  ui_story_6_1_147_dialog_content = "もう…戦いなんて、面倒はイヤよ。",
  ui_story_6_1_148_dialog_content = "PlayerName、何か感じる？",
  ui_story_6_1_149_dialog_content = "スーモアの気配がずっと消えないよ。",
  ui_story_6_1_150_dialog_content = "やっぱり先を越されているのね。彼女との距離はどの程度？",
  ui_story_6_1_151_dialog_content = "近くはないけど、遠くもない…暗鬼に遭遇する危険もある。\nみんな、十分気を付けて。",
  ui_story_6_1_152_dialog_content = "…",
  ui_story_6_1_153_dialog_content = "それなら追いつけるかも知れないわ！スーモアにはガイドがいない。\n中で迷っている可能性もあるわ。でも私たちには、ガイドがいる…",
  ui_story_6_1_154_dialog_content = "…ちょっと、ガイドさん？どちらへ？そっちは来た道でしょう？",
  ui_story_6_1_155_dialog_content = "シェオルさん…気が変わったとか…？",
  ui_story_6_1_156_dialog_content = "確かに危険はありますから、シェオルさんに無理強いはしません…",
  ui_story_6_1_157_dialog_content = "その通りね。そもそも、いざという時に萎縮するような人なら、\n一緒に戦っても足手まといになるだけよ。",
  ui_story_6_1_158_dialog_content = "あら？私がいつ「萎縮」したって？ガイドは変わらず引き受けるわよ。",
  ui_story_6_1_159_dialog_content = "でも、戦いに向いてないのも確かなの。一緒に行くのはやめておくわ。",
  ui_story_6_1_160_dialog_content = "一緒にいないで、どうやってガイドを？まさか、遠くから、とか…",
  ui_story_6_1_161_dialog_content = "可愛いバイスちゃんの言う通りよ。\n私はここから、あなた達と通信することにするわ。",
  ui_story_6_1_162_dialog_content = "中の地形を大まかに教えてくれれば、正確な場所は把握できるし。",
  ui_story_6_1_163_dialog_content = "そんなことだろうと思ってたわ…これが影ノ街の処世術よ、バイス。",
  ui_story_6_1_164_dialog_content = "さっきのは、遠隔でガイドをしてほしいっていう意味では…\nシェオルさん、やっぱり一緒にいた方がいいと思うんですけど。",
  ui_story_6_1_165_dialog_content = "あら？それも一理あるわねぇ。じゃあ、私は外で待っていることにするわ。\nそこから、いつでも通信で一緒にいてあげる。",
  ui_story_6_1_168_dialog_content = "そうそう、もし生きて戻ってこられたら、PlayerNameちゃん…",
  ui_story_6_1_169_dialog_content = "私の店に来てちょうだい。友だち割してあげるわ。\nだって、もう私たち、友だちだもの。",
  ui_story_6_1_170_dialog_content = "じゃぁ、がんばってね～",
  ui_story_6_1_171_dialog_content = "シェオルさんって、きっとそうとう商売上手なんだろうな…",
  ui_story_6_1_172_dialog_content = "私が余計なことをいったせいかしら…「遠くからガイド」とか…",
  ui_story_6_1_173_dialog_content = "バイス、気にするのはやめましょう。\n肝心な時に足手まといになるくらいなら、今いなくなってもらった方がいいわ。",
  ui_story_6_1_174_dialog_content = "カレンはいつも冷静だね…羨ましいぐらいだよ…",
  ui_story_6_1_175_dialog_content = "緊張しないで。立ちはだかる者が何であろうと、\n私がそいつに来る場所を間違えたと思い知らせてあげるわ。",
  ui_story_6_2_X29_dialog_content = "おや…？ああ…ううむ…",
  ui_story_6_2_X30_dialog_content = "カロン長官？おかしにゃ声を出して、いったいどうしたんだにゃ？",
  ui_story_6_2_X31_dialog_content = "フィリス君か。君は相変わらず…",
  ui_story_6_2_X32_dialog_content = "眠そうな顔をしているな。",
  ui_story_6_2_X33_dialog_content = "長官たちの会議が終わるのを待っているのだよ。\nシェルター28号の経費清算の件で、少々用が…",
  ui_story_6_2_X34_dialog_content = "長官たちにゃら、もういないにゃ。また今度だにゃ。",
  ui_story_6_2_X35_dialog_content = "何だと！？まだほとんどの補助金が下りていないというのに…\n早々に会議を放り出して、どこへ行ったというのだ？",
  ui_story_6_2_X36_dialog_content = "仕方ないにゃ。みんな緊急命令を受けて、辺りに防衛線を張りにいったにゃ。",
  ui_story_6_2_X37_dialog_content = "にゃあ。バイスが脅威は<color=#FFB400>ささやきの回廊</color>にあるって、\nあんにゃにはっきり突き止めてるのに…",
  ui_story_6_2_X38_dialog_content = "大元帥様が決めたことだから、フィリスにはわからないにゃ…",
  ui_story_6_2_X39_dialog_content = "待て待て、ちょっと待て。情報が多すぎるぞ。",
  ui_story_6_2_X40_dialog_content = "もっと詳しく教えてくれたまえ。\nバイスとPlayerNameたちがまた面倒ごとに巻きこまれたのか？",
  ui_story_6_2_X41_dialog_content = "面倒？うにゃにゃ、どういったらいいのかにゃ。\n「<color=#FFB400>史上最悪の危機</color>」と言ってもいいかもしれないにゃ…",
  ui_story_6_2_X42_dialog_content = "危機！？",
  ui_story_6_2_1_dialog_content = "…私たち、もう随分歩いたはずだけど。",
  ui_story_6_2_2_dialog_content = "私でも感じられるぐらい、暗鬼の気配が濃いわ。",
  ui_story_6_2_3_dialog_content = "シェオルさん…",
  ui_story_6_2_4_dialog_content = "はぁい？どうしたの？",
  ui_story_6_2_6_dialog_content = "あらダーリン、迷子？",
  ui_story_6_2_7_dialog_content = "迷子ではないわ。でも、確かに迷路みたいね。\nこの、とても暗くて、重々しい雰囲気は。",
  ui_story_6_2_9_dialog_content = "ねぇ、見て。この跡、なんだかおかしいわ。暗鬼の足跡以外に…",
  ui_story_6_2_10_dialog_content = "この足跡って「軍靴」よね？",
  ui_story_6_2_11_dialog_content = "軍靴？これは…",
  ui_story_6_2_12_dialog_content = "光霊の気配を感知したよ。助けが来たのかな？",
  ui_story_6_2_13_dialog_content = "白夜城制式。間違いないわ。護衛隊のもの。",
  ui_story_6_2_14_dialog_content = "はっきりした足跡…戦いの痕跡なし、それに…恐れているような動きもない。",
  ui_story_6_2_15_dialog_content = "足跡ひとつでそんなにいろいろわかるんだ…",
  ui_story_6_2_16_dialog_content = "…<color=#FFB400>グスド</color>。",
  ui_story_6_2_X16_dialog_content = "グスド？記憶違いでなければ、それって…",
  ui_story_6_2_17_option_content = "スイェートを追っている時に聞いた名前だ",
  ui_story_6_2_18_option_content = "あの時「ブレーンパーツ」を盗んだ奴？",
  ui_story_6_2_19_dialog_content = "その通りよ。でもグスドは失踪したんじゃなかった？",
  ui_story_6_2_20_dialog_content = "私たちを裏切って逃亡したの。日蝕に寝返っていたわ。証拠も確かよ…",
  ui_story_6_2_21_dialog_content = "あいつもその恋人も、ずいぶん前から暗鬼に魂を売っていた。\n白夜城の恥ね。",
  ui_story_6_2_22_dialog_content = "こんな時に、こんなところで暗鬼と行動を共にしている、\n護衛隊の軍靴をはいた者なんて…",
  ui_story_6_2_23_dialog_content = "グスドしかいない！",
  ui_story_6_2_24_dialog_content = "どうしてそんなことを？",
  ui_story_6_2_25_dialog_content = "わからないわ。",
  ui_story_6_2_26_dialog_content = "グスドは真面目に務めていたし、以前の戦争では英雄でもある。\n誰一人疑っていなかったわ。",
  ui_story_6_2_27_dialog_content = "まさか、グスドがスイェートのことで恨みを抱いて、ここに来たのも…",
  ui_story_6_2_28_dialog_content = "ご主人様にくっついて放浪を続ける負け犬。ちょうどいいじゃない。",
  ui_story_6_2_29_dialog_content = "ここで会うことになるなら、スーモアもろとも、ここで葬る！",
  ui_story_6_2_30_dialog_content = "チッ…もう、イライラするわね…ハラワタみたいに曲がりくねった道だわ。\nそれに、誰かに見られてるような…",
  ui_story_6_2_31_dialog_content = "ああ、イライラする！グスド、歌でも歌いなさい。",
  ui_story_6_2_32_dialog_content = "…",
  ui_story_6_2_33_dialog_content = "グスド、その目つきは何？",
  ui_story_6_2_34_dialog_content = "スイェートを殺した奴が来たわ。\n戦いの歌でも歌って、喜びを表現するべきじゃなくって？",
  ui_story_6_2_35_dialog_content = "あなたが言った通り、奴らが追ってきています…",
  ui_story_6_2_36_dialog_content = "…スイェートに手を下したあいつらが、\n今まさに近づいている、そうですね。",
  ui_story_6_2_37_dialog_content = "その通りよ。やっぱり、低級な雑魚なんかじゃ足止めにもならないようね…\nうっとうしい奴らだわ。",
  ui_story_6_2_39_dialog_content = "スイェートは…",
  ui_story_6_2_40_dialog_content = "悲惨な最期だったわ、グスド。\n聞いたときには、私でも惨めな死に方だと思うぐらいにね。",
  ui_story_6_2_41_dialog_content = "なぜだ！スイェートたちは…",
  ui_story_6_2_42_dialog_content = "スイェートは俺に言ったんだ。あれは栄誉ある任務だったと！\nどうしてあなたやあの方に助けを求めなかったんだ？",
  ui_story_6_2_A1_dialog_content = "いいや、彼女の性格なら、助けを求めないなんてはずはない…まさか…",
  ui_story_6_2_43_dialog_content = "そんなに大きな声を出して、どうしたの？",
  ui_story_6_2_44_dialog_content = "…すみません。",
  ui_story_6_2_45_dialog_content = "そうそう、スィエートを追い詰めたのは、PlayerNameだったそうよ。",
  ui_story_6_2_46_dialog_content = "あなたがスイェートと別れてから、ダウンタウンは混乱に陥った。\nでも、アップタウンの方は関わる気配も見せていなかったらしいわ。",
  ui_story_6_2_47_dialog_content = "でも、PlayerNameが2匹の凶暴な「猟犬」を連れて追い続けたのよ。",
  ui_story_6_2_48_dialog_content = "…あいつら！そこまで…",
  ui_story_6_2_49_dialog_content = "そうよ。まだ何か盗まれたかどうかも分かっていなかったのに、殺されたの。\n流石にやりすぎよね？",
  ui_story_6_2_50_dialog_content = "最後にはスイェートと妹は追い詰められて…\nまぁ、醜い怪物になるしかなかったってことよ。",
  ui_story_6_2_51_dialog_content = "…スイェート…スイェート…",
  ui_story_6_2_52_dialog_content = "何かやりたいことがあるなら、今がチャンスよ。",
  ui_story_6_2_53_dialog_content = "射撃統制モジュールはこの先にあるから、私は進むわ。あなたはどうする？",
  ui_story_6_2_54_dialog_content = "PlayerName――！！！",
  ui_story_6_2_55_dialog_content = "ふぅん？復讐の準備は万端ってことみたいね。",
  ui_story_6_2_56_dialog_content = "――ハックション！",
  ui_story_6_2_57_dialog_content = "どうしたの、PlayerName？もしかして、寒すぎる？",
  ui_story_6_2_58_dialog_content = "いや…ただ…なぜか鳥肌が立つんだ。",
  ui_story_6_2_59_dialog_content = "空の末裔であるPlayerNameにとっては、\n暗力が濃すぎるのかもしれないわね。",
  ui_story_6_2_60_dialog_content = "でも、もうしばらく持ちこたえて。\n私たちにはまだ打ち倒すべき敵が大勢いるの。",
  ui_story_6_2_61_dialog_content = "わかってる…このまま先を急ごう…",
  ui_story_6_6_1_dialog_content = "なんだかおかしなところに来たみたいね。\n…シェオルさん！",
  ui_story_6_6_2_dialog_content = "もぐもぐ…あら？",
  ui_story_6_6_3_dialog_content = "シェオルさん…お食事中でしたか？",
  ui_story_6_6_4_dialog_content = "ん…えぇ、ちょっとお茶と一緒に\nお茶菓子をいただいてるだけよ…どうかしたの？",
  ui_story_6_6_5_dialog_content = "今、私たちが「<color=#FFB400>射撃統制モジュール</color>」の方へ続く道を進めているか知りたいんですが、\nこの道であっていますか？",
  ui_story_6_6_6_dialog_content = "ええ――もちろんよ。射撃統制モジュールの大体の位置、思い出すのも苦労したのよ。",
  ui_story_6_6_7_dialog_content = "人の言うことは信じた方がいいわ、ダーリン。\nあぁそうそう、その先は罠があるわ。気を付けてね。",
  ui_story_6_6_8_dialog_content = "待って。何かを感知したよ…",
  ui_story_6_6_9_dialog_content = "暗鬼がいるの？",
  ui_story_6_6_10_dialog_content = "いや、どうやら…光霊みたいだよ。",
  ui_story_6_6_11_dialog_content = "光霊？シェオルさん、誰も入っていないはずよね？",
  ui_story_6_6_12_dialog_content = "ハエ1匹入ってきていないわ。",
  ui_story_6_6_13_dialog_content = "グスドだわ…伏兵でしょうね。",
  ui_story_6_6_14_dialog_content = "伏兵？",
  ui_story_6_6_15_dialog_content = "この先、十字路になっているだけじゃない。落とし穴もあるわ。",
  ui_story_6_6_16_dialog_content = "それにここ自体、ずいぶん古いもの。屋根が崩れていたり、\n地面が陥没している可能性もある。つまり、天然の伏兵にもなるわ。",
  ui_story_6_6_17_dialog_content = "かつては騎士だったとはいえ、今は日蝕に墜ちた身。\nどんな手を使ってくるかは分からない。",
  ui_story_6_6_18_dialog_content = "私が先頭に立つわ。グスド…私がふさわしい最期をくれてやりましょう。",
  ui_story_6_7_1_dialog_content = "ふぅ…危なかったわ…カレンが気付いてくれてよかった。\nでなきゃ、落とし穴に落ちていたところだもの。",
  ui_story_6_7_2_dialog_content = "ちょっと、私だって何度も警告してあげてるじゃない。",
  ui_story_6_7_3_dialog_content = "さっきの油の缶だって、あと少し遅かったら\n可愛いPlayerNameに当たるところだったでしょ。",
  ui_story_6_7_4_dialog_content = "本当にびっくりしたよ…",
  ui_story_6_7_5_dialog_content = "グスドの策ね。もはや暗鬼も同然の、恥知らずな卑劣漢に成り果てたようね…",
  ui_story_6_7_6_dialog_content = "…噂をすれば影、だね。",
  ui_story_6_7_7_dialog_content = "…お前たちがスイェートを殺したんだ。",
  ui_story_6_7_8_dialog_content = "お前たちが、スイェートを…殺したんだ…！",
  ui_story_6_7_9_dialog_content = "やっぱり…復讐に来たのね。",
  ui_story_6_7_10_dialog_content = "復讐？そうさ。落とし穴にかからなかったのは、残念だ…",
  ui_story_6_7_11_dialog_content = "単にお前たちを殺す程度じゃ、この恨みは晴らせないからな。",
  ui_story_6_7_F1_dialog_content = "私たちを殺す？",
  ui_story_6_7_12_dialog_content = "グスド！白夜城の騎士としての栄誉を捨て、暗鬼に寝返ったあなたを…\n絶対に許しはしない。",
  ui_story_6_7_13_dialog_content = "許さない？許してもらう必要などない。確かに俺は白夜城の騎士だった。\nだが、今は暗鬼の精鋭…",
  ui_story_6_7_14_dialog_content = "すべてはスィエートのためにしたことだ！だが、お前らのせいで…",
  ui_story_6_7_15_dialog_content = "暗鬼よりもお前らの方が残忍じゃないか…！\nお前らのせいで、あいつは苦しみながら死んだんだ！",
  ui_story_6_7_16_dialog_content = "グスド！スイェートたちは自ら死を選んだの。",
  ui_story_6_7_17_dialog_content = "スイェートが殺してくれって頼んできたんだ。苦しみから解放されたいって…",
  ui_story_6_7_18_dialog_content = "バカを言うな！",
  ui_story_6_7_19_dialog_content = "スイェートはあんなにも…自由にあこがれていた。\nお前らに追い詰められでもしなければ、自ら死など選ぶはずがない！",
  ui_story_6_7_20_dialog_content = "スーモアに言われて来たの？",
  ui_story_6_7_21_dialog_content = "違う。俺は復讐に来たんだ。お前たちに、白夜城に復讐するために。",
  ui_story_6_7_22_dialog_content = "スーモアが…何をしようと、俺には関係ない。",
  ui_story_6_7_23_dialog_content = "反逆者が内通者の復讐？",
  ui_story_6_7_27_dialog_content = "…",
  ui_story_6_7_28_dialog_content = "カレン、グスドの敵意が強まってる。気を付けて…",
  ui_story_6_7_29_dialog_content = "敵意？反逆者なら、生まれながらに持っているものでしょう。",
  ui_story_6_7_30_dialog_content = "行き場を失い、敵意と恨みばかり抱えて…",
  ui_story_6_7_31_dialog_content = "自分を裁く者を恨み、戻ることのできない過去を恨み、失われた未来を恨む。",
  ui_story_6_7_32_dialog_content = "そんなやからと話すことなどないわ。",
  ui_story_6_7_33_dialog_content = "白夜城の護衛隊長で、城主の娘の、お前には分からないだろうな。",
  ui_story_6_7_34_dialog_content = "俺が裏切り者であろうとなかろうと、お前は俺の憎しみなんて、分かりはしない！",
  ui_story_6_7_35_dialog_content = "俺はただ、スイェートを死に追いやったお前らが憎いだけだ！",
  ui_story_6_7_36_dialog_content = "お前らの言う通りだ。彼女は暗鬼になった。\nそしてお前らは光霊。敵として戦場で死ぬのは、スイェートの運命だった。",
  ui_story_6_7_37_dialog_content = "だが、お前たちはスイェートを追い詰めた！\nあんな姿にしてしまった！あんな姿に！",
  ui_story_6_7_38_dialog_content = "あいつの姿…！",
  ui_story_6_7_39_dialog_content = "復讐…俺は復讐する…お前と同じだ、PlayerName。",
  ui_story_6_7_40_dialog_content = "俺たちは瓜二つだ。復讐の道を選んだ。引き返すことはできない…",
  ui_story_6_7_41_dialog_content = "僕と同じ？どういう意味…？",
  ui_story_6_7_42_dialog_content = "暗鬼に変化した…まさか、主とやらから、力を受け取った！？",
  ui_story_6_7_43_dialog_content = "…復讐してやる！ここで俺と刺し違えろ、PlayerName！！",
  ui_story_6_7_44_dialog_content = "そして俺と共に、彼岸でスイェートに許しを乞え！！",
  ui_story_6_7_45_dialog_content = "下がって、PlayerName！サポートをお願い！",
  ui_story_6_7_X45_dialog_content = "スイェート…俺は…負けちまったよ…",
  ui_story_6_7_48_dialog_content = "裁きを受け入れる覚悟はできた？反逆者！",
  ui_story_6_7_49_dialog_content = "…",
  ui_story_6_7_50_dialog_content = "…なぜ黙っているの？死を目前にして、\n今さら後悔が芽生えたとでも言うつもり？",
  ui_story_6_7_51_dialog_content = "いや。俺は後悔などしていない…\n自分がどんな末路を迎えるか、覚悟はできているさ…",
  ui_story_6_7_52_dialog_content = "ただ…スイェートの最期がどうだったのか、教えてくれないか…",
  ui_story_6_7_53_dialog_content = "その必要はないわ！",
  ui_story_6_7_F2_dialog_content = "待って！ちゃんと説明するよ…",
  ui_story_6_7_54_dialog_content = "確かに僕らは、スイェート達を追いかけた。\nでも、あの時はただ、彼女たちの目的を知りたかっただけだった。",
  ui_story_6_7_55_dialog_content = "そうよ、殺すつもりなんかなかったの。",
  ui_story_6_7_56_dialog_content = "でも逃げるために、彼女たちは上の暗鬼に助けを求めたみたいね。",
  ui_story_6_7_57_dialog_content = "…スーモア？",
  ui_story_6_7_58_dialog_content = "いや…あの気配は、スーモアじゃなかった。\n別人だよ。スーモアよりずっと強大な誰か…",
  ui_story_6_7_59_dialog_content = "それから、あの二人の体に恐ろしい変異が起こって、\nまるでロウソクみたいに…融合した。",
  ui_story_6_7_60_dialog_content = "でも、彼女たちが自分から進んでそうしたようには思えなかった、むしろ…",
  ui_story_6_7_61_dialog_content = "むしろ、何か抵抗できない力に無理やり…",
  ui_story_6_7_62_dialog_content = "なら、その後は…！",
  ui_story_6_7_63_dialog_content = "僕たちはスイェートを殺すしかなかった。",
  ui_story_6_7_64_dialog_content = "…苦しんだだろうな…",
  ui_story_6_7_65_dialog_content = "それは…",
  ui_story_6_7_66_option_content = "とても苦しんだよ",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>…辛かったろう…！</size></anim>",
  ui_story_6_7_69_dialog_content = "私たちと戦う前にはすでに、誰かが強制的に力を与えていた…",
  ui_story_6_7_70_dialog_content = "スイェート達は無理やり融合させられ、1匹の暗鬼になった。\nそれこそ、彼女たちが苦しんだ原因。",
  ui_story_6_7_71_option_content = "僕らは一息に決めてあげた",
  ui_story_6_7_72_dialog_content = "お前らが…スイェートを苦しみから解放したというのか？",
  ui_story_6_7_73_dialog_content = "そうよ。苦しむ様子を黙って見てはいられなかった。",
  ui_story_6_7_74_dialog_content = "私たちと戦う前にはすでに、誰かが強制的に力を与えていた…",
  ui_story_6_7_75_dialog_content = "スイェート達は無理やり融合させられ、1匹の暗鬼になった。\nそれこそ、彼女たちが苦しんだ原因。",
  ui_story_6_7_76_dialog_content = "もしかしたらだけど、あの2人は後悔していたのかもしれない。",
  ui_story_6_7_78_dialog_content = "特にスイェートはね。\n僕はあの時…彼女が僕たちと戦いたがっていないと感じた。",
  ui_story_6_7_79_dialog_content = "ただ逃げ出したかっただけなんだ。白夜城からどこか遠くに…",
  ui_story_6_7_80_dialog_content = "彼女…花の名前を口にしていたわ。",
  ui_story_6_7_81_dialog_content = "花…？",
  ui_story_6_7_82_option_content = "「タンポポ」",
  ui_story_6_7_83_dialog_content = "<size=45>……！！</size>",
  ui_story_6_7_84_dialog_content = "僕たちには分からないけど、君には…わかるんだよね。",
  ui_story_6_7_85_dialog_content = "すまない…すまない。スイェート…",
  ui_story_6_7_86_dialog_content = "あの時、君は俺に呼びかけていたんだな。俺は気づけたはずだった。\n俺たちにはまだ、チャンスが残っていたのに…",
  ui_story_6_7_87_dialog_content = "グスド、グスド。この近くにどこか面白いところはないかしら？",
  ui_story_6_7_88_dialog_content = "遊びに行くのか？",
  ui_story_6_7_89_dialog_content = "遊びじゃないわ…ねぇ、ささやきの回廊って知ってる？",
  ui_story_6_7_90_dialog_content = "隠れるのに絶好の場所らしいわ。誰も私たちを見つけられないの！\n一生住んでいられるわ！",
  ui_story_6_7_91_dialog_content = "それか、R・W砂漠も悪くないわね。ちょっと暑いけど。",
  ui_story_6_7_92_dialog_content = "白夜城を離れるつもりか？どこかの貴族でも怒らせたのか？",
  ui_story_6_7_93_dialog_content = "いいえ…日蝕よ。",
  ui_story_6_7_94_dialog_content = "ああ、タンポポになりたい。",
  ui_story_6_7_95_dialog_content = "ん？どうした、急に？",
  ui_story_6_7_96_dialog_content = "だって、タンポポは誰も捕まえることができないでしょ。\n土から離れたタンポポは、たくさんの自分になって、風に乗って散らばっていくの。",
  ui_story_6_7_97_dialog_content = "空を飛んで…世界のどんなところでも行けるの。",
  ui_story_6_7_98_dialog_content = "「たくさんの自分」って、ただのタネじゃないか…\nそれに、水に落ちたらどうするんだ？",
  ui_story_6_7_99_dialog_content = "はぁ、あなたって人は――もういいわ！",
  ui_story_6_7_100_dialog_content = "自由…そうだ。\nスイェートはいつも白夜城から離れたいと言っていた。日蝕を恐れて…",
  ui_story_6_7_101_dialog_content = "俺と一緒に…タンポポのように…遠くへ飛んでいきたい、と…",
  ui_story_6_7_102_dialog_content = "お前はホントにバカね、グスド。\n日蝕こそ万事万物の終着点。いいえ、日蝕こそ真理…",
  ui_story_6_7_103_dialog_content = "…本当に、PlayerNameがスイェートを殺したのか？",
  ui_story_6_7_104_dialog_content = "何があったのかはもう教えてあげたでしょうに、まだ質問ばかり…\nあなたに期待しすぎたかしら？",
  ui_story_6_7_105_dialog_content = "弱さも私たちへの疑いも捨てなさい、グスド。",
  ui_story_6_7_106_dialog_content = "覚えておけばいいことはたった一つ。あの子たちは、本来なら生きていられたはず。\nなのに、PlayerNameが彼女たちの運命を書き換えた。",
  ui_story_6_7_107_dialog_content = "そして、お前の運命も…",
  ui_story_6_7_108_dialog_content = "違う！違う！嘘だ！嘘だ！",
  ui_story_6_7_109_dialog_content = "グスド！",
  ui_story_6_7_110_dialog_content = "お…俺は、スイェート、スイェート、スイェートは離れたがっていた！\n融合なんて、融合なんて…",
  ui_story_6_7_111_dialog_content = "私たちは暗力なんて使えないわ。\nでも、スイェート姉妹を暗鬼として融合させられるのは、暗力しかない。",
  ui_story_6_7_112_dialog_content = "2人に暗力を注入したのがスーモアじゃなかったとしても、\nスーモアと関係のある暗鬼に違いないわ。",
  ui_story_6_7_113_dialog_content = "あいつ、あいつ、あいつだ。あいつだ…！！",
  ui_story_6_7_114_dialog_content = "グスド…何か知っているの！？",
  ui_story_6_7_116_dialog_content = "…",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>スーモア</color>…奴がどこにいるか知っている。",
  ui_story_6_8_1_dialog_content = "カレン…彼、本当にスーモアのいるところまで連れていってくれるのかしら？",
  ui_story_6_8_2_dialog_content = "ここまで暗鬼に遭わないなんて、いくら何でもすこしおかしいわ。\n手のこんだ罠とかじゃない？",
  ui_story_6_8_F1_dialog_content = "罠だろうと、関係ないわ。",
  ui_story_6_8_3_dialog_content = "また裏切るつもりなら、もう一度倒すまで。\nただし、次は…一切容赦しない。",
  ui_story_6_8_F2_dialog_content = "…",
  ui_story_6_8_4_dialog_content = "ごめん、グスド…やっぱり、まだ君のことを完全に信じるわけにはいかないんだ。\nでも、言いたいことがあるなら、直接言ってくれてかまわないよ。",
  ui_story_6_8_5_dialog_content = "これ以上何か裏切ることがあるとでも？",
  ui_story_6_8_6_dialog_content = "裏切り、か…そうだ、俺はかつて白夜城の英雄だったな。",
  ui_story_6_8_7_dialog_content = "18歳で正式な騎士になった。ソルラド殿下から直々に称号を賜ったんだ。",
  ui_story_6_8_8_dialog_content = "<color=#FFB400>「暗潮の危機」</color>のことは、知っているよな。",
  ui_story_6_8_9_dialog_content = "17年前に始まって、長く続いた戦争のことよね…",
  ui_story_6_8_10_dialog_content = "17年前…空の末裔が住む天空ノ谷を暗鬼が襲った。\n何の予兆もなかったから、白夜城も驚いたもんだった。",
  ui_story_6_8_11_dialog_content = "その後すぐに、訓練を厳しくすると命令があった。\n大規模な暗鬼の襲撃に備えるためにな。",
  ui_story_6_8_12_dialog_content = "当時の俺は今の君たちよりずっと若くて、騎士の従者になったばかりだった。",
  ui_story_6_8_13_dialog_content = "一生懸命訓練に励んで、それから白夜城の護衛隊で4年間、予備兵をしていた。",
  ui_story_6_8_14_dialog_content = "それで、チャンスが巡ってきた。",
  ui_story_6_8_15_dialog_content = "あぁ、あれは晴れ渡った日の昼前の事だった。白夜城の兵士は\n影ノ街を襲った暗鬼と戦うために出払って、街の守りが足りなくなっていたんだ。",
  ui_story_6_8_16_dialog_content = "その時、白夜城のダウンタウンに暗鬼が侵入し…\n俺は身を挺して、ある貴族の女性を救った。",
  ui_story_6_8_19_dialog_content = "そして、護衛隊と共に戦った俺は、その時の勇敢さを買われ…",
  ui_story_6_8_20_dialog_content = "帰還してすぐ、城主から直々に騎士の称号を賜ったんだ。",
  ui_story_6_8_22_dialog_content = "聞いた感じ、滑り出しは順調だったみたいに聞こえるけど。",
  ui_story_6_8_23_dialog_content = "あぁ、なにせ「姫を迎えた騎士」だったからな。\nまるでおとぎ話の結末みたいな話さ。",
  ui_story_6_8_27_dialog_content = "一ヶ月後、俺はその時の貴族の令嬢と…結婚式を挙げた。",
  ui_story_6_8_28_dialog_content = "それがスイェートなんだね。",
  ui_story_6_8_29_dialog_content = "いいや。",
  ui_story_6_8_30_dialog_content = "えっ…！？",
  ui_story_6_8_31_dialog_content = "その令嬢はいいところの貴族の娘だった。次女ではあったけどな。",
  ui_story_6_8_32_dialog_content = "だが、俺との身分の違いは、俺一人の努力で埋められるものじゃなかった…",
  ui_story_6_8_33_dialog_content = "いつでも強気な女だったが、同時にいつも現実との落差に苦しんでいた…",
  ui_story_6_8_34_dialog_content = "甘い生活もそのうち平凡な日々に変わって…他人と比べられては、\n不満不平を募らせて、争うようになって…麻痺していった。",
  ui_story_6_8_35_dialog_content = "数年後には、彼女にとって\n俺は道端の石ころ同然の、存在しないものになっていた。",
  ui_story_6_8_36_dialog_content = "俺は捨てられたんだ…それから、スイェートに出会った。",
  ui_story_6_8_45_dialog_content = "よどんだ水たまり同然、生気の抜けた生活をしていた俺に、\n少年時代のような刺激をもたらしてくれた。",
  ui_story_6_8_46_dialog_content = "彼女を見ていると、自分が若い時に戻ったような気になれた。",
  ui_story_6_8_47_dialog_content = "何が家だ、何が地位だ。\n俺はただ戦場で功績を残して、愛する人の心を射止めたい…",
  ui_story_6_8_49_dialog_content = "…もういいわ！グスド、誰も同情などしない。",
  ui_story_6_8_50_dialog_content = "あなたが何をしたのか、よく考えなさい。",
  ui_story_6_8_51_dialog_content = "妻に背き、暗鬼と結託し、衛兵を襲い、「ブレーンパーツ」を盗んだ！",
  ui_story_6_8_53_dialog_content = "かつては白夜城の英雄だったかもしれない。\nでも今はもう、白夜城に背いた罪人よ！",
  ui_story_6_8_54_dialog_content = "ああ…ハハハ！俺は確かに白夜城に背いたさ。許されざる罪人だ。",
  ui_story_6_8_F3_dialog_content = "だけどな、俺が間違っていたとは思わない。\nただ、自分にとっての真実の愛を追い求めただけだ…",
  ui_story_6_8_55_dialog_content = "理解できないわ。こんなの…メチャクチャよ。",
  ui_story_6_8_63_dialog_content = "…で、昔話はそろそろおしまい？",
  ui_story_6_8_64_dialog_content = "あっ…シェオルさんのこと、すっかり忘れてた！！",
  ui_story_6_8_65_dialog_content = "いちおう伝えておこうかと思って。\nグスドは道を間違えていないわ。それだけよ…",
  ui_story_6_8_66_dialog_content = "彼の進む方向と、私の覚えてるルートは同じよ。\n落とし穴のありそうな場所も避けられているわ。",
  ui_story_6_8_67_dialog_content = "…",
  ui_story_6_8_68_dialog_content = "言っただろう、理解してもらう必要はない。俺は君たちをスーモアのところへ連れていく。\nその後は…俺には俺の、やるべきことがある。",
  ui_story_6_9_1_dialog_content = "しょせん、風見鶏は風見鶏ね。",
  ui_story_6_9_2_dialog_content = "グスドのこと？",
  ui_story_6_9_3_dialog_content = "どうやらあなたの説得力じゃ、\nPlayerNameには勝てなかったみたいよ。",
  ui_story_6_9_4_dialog_content = "だから？グスドが裏切るなんて、最初からわかりきったことでしょ。\n予想と違ったことがあるとすれば…",
  ui_story_6_9_5_dialog_content = "PlayerName？",
  ui_story_6_9_6_dialog_content = "そう。グスドを見逃すとはね。\nふん、きっとPlayerNameが何か言ったんでしょ、たいした偽善だわ。",
  ui_story_6_9_7_dialog_content = "いいえ、それだけ賢かったのよ。あなたは今度から「予測」なんてしないことね、\nスーモア。そもそも頭脳派じゃないんだから。",
  ui_story_6_9_8_dialog_content = "…いつか必ずその首をへし折るわ…",
  ui_story_6_9_9_dialog_content = "…とにかく。どっちにしろ、私たちは奴らよりずっと先を行っている。\nもう「<color=#FFB400>射撃統制モジュール</color>」の匂いがしてきたわ。",
  ui_story_6_9_10_dialog_content = "あれを手に入れたらPlayerNameを待ち伏せして、その後…",
  ui_story_6_9_11_dialog_content = "一網打尽にしなさい。",
  ui_story_6_9_12_dialog_content = "ええ、もちろんよ。一網打尽、大好きな言葉だわ。",
  ui_story_6_9_13_dialog_content = "他の言葉も勉強したほうがいいんじゃないかしら。\nとにかく、注意するに越したことはないわ。奴らの背後には白夜城と啓光が控えてる。",
  ui_story_6_9_14_dialog_content = "ふんっ。奴らが来ることはないと思うけど？\n光霊どもは身内の馬鹿らしい猜疑とわだかまりで手いっぱいだもの。",
  ui_story_6_9_15_dialog_content = "観賞しに来たらどう？奴らきっと、面白い顔をするわよ。",
  ui_story_6_9_16_dialog_content = "結構よ。知っているでしょう？私は戦いが嫌いなの。",
  ui_story_6_9_17_dialog_content = "でも、助けを用意…いや、<color=#FFB400>贈り物</color>ね。\n奴らへの贈り物を用意しておいたわ。",
  ui_story_6_9_18_dialog_content = "贈り物？助け？…ああ！あいつのこと？",
  ui_story_6_9_19_dialog_content = "そう。あいつらの<color=#FFB400>古いお友達</color>よ。私が「強化」してあげたの。",
  ui_story_6_9_20_dialog_content = "ちょっとお遊びがすぎるんじゃない、いつもそんな「創作」ばかりして。",
  ui_story_6_9_21_dialog_content = "私は計画内で問題が起こらない範囲でやっているだけよ。\n迷惑で行きあたりばったりの行動しか繰り返さないあなたと違って。",
  ui_story_6_9_22_dialog_content = "お互い様でしょ。",
  ui_story_6_9_23_dialog_content = "世間話はここまでにしておきましょうか。\nそれより、見てよ。贈り物…",
  ui_story_6_9_24_dialog_content = "あら…綺麗ね。古いお友達と再会したら、\nPlayerNameはどんな表情を見せてくれるかしら？",
  ui_story_6_9_25_dialog_content = "今から待ちきれなくなってきたわね。早く見てみたいわ…",
  ui_story_6_9_A1_dialog_content = "グスド、あとどれくらい？",
  ui_story_6_9_A2_dialog_content = "もうすぐだ。俺を信じろ。\nこの中で、誰よりもあいつの嘘だらけの顔を見たいのは、俺だ…",
  ui_story_6_9_A3_dialog_content = "…",
  ui_story_6_9_A4_dialog_content = "前方に伏兵がいる。スーモアがおいていった暗鬼だ。\nお前たち、そういうのは得意だろ。さっさと片付けてしまえ…",
  ui_story_6_13_1_dialog_content = "この先が、ささやきの回廊の一番奥？",
  ui_story_6_13_2_dialog_content = "そうだ。スーモアもきっと近くにいるはずだ…",
  ui_story_6_13_3_dialog_content = "うん。僕も感じたよ。彼女の気配はまっすぐ、前方から来てる。",
  ui_story_6_13_5_dialog_content = "近くを探してみて。大きなガラス瓶があるはずよ。\nラベルに番号が書いてあるわ。",
  ui_story_6_13_6_dialog_content = "ええと、なんて書いてあったかしら、たしか…",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>「RX6007」</color>。",
  ui_story_6_13_8_dialog_content = "あ、そう！それよ！運び込んだ時につけた番号！どうして知ってるの？",
  ui_story_6_13_10_dialog_content = "スーモアが何気なく口にしたことがあるんだ。\n俺は一度聞いたことは忘れない。",
  ui_story_6_13_11_dialog_content = "情報であろうと、過去のことであろうと…ふっ、まるで呪いみたいな記憶力さ。",
  ui_story_6_13_12_dialog_content = "その番号のモノがあるところに行けば、あなた達の探し物も近くにあるはずよ。",
  ui_story_6_13_14_dialog_content = "気を付けて。スーモアがすでにその数字を知っていたと言うなら、それは…",
  ui_story_6_13_16_dialog_content = "とっくにそのありかを知っているし、\n今まさに、僕らが来るのを待ち構えてるってことだね。",
  ui_story_6_14_1_dialog_content = "あら、また会ったわね。",
  ui_story_6_14_2_dialog_content = "ス…",
  ui_story_6_14_3_dialog_content = "スーモア！！",
  ui_story_6_14_4_dialog_content = "あら、ずいぶんお怒りね？PlayerNameに負けたから？",
  ui_story_6_14_5_dialog_content = "見たところ、捕まったのかしら？\n助けてあげましょうか？それでもう一回戦う？",
  ui_story_6_14_6_dialog_content = "お前、それにあいつも、俺をだましたな…スイェートの死の真実を、お前は隠した！",
  ui_story_6_14_7_dialog_content = "私たちがだました？いいえ、グスド。\nあなた自身、「スイェートは白夜城に殺された」と信じたかっただけでしょ。",
  ui_story_6_14_8_dialog_content = "だから、白夜城に復讐をしようとした。違った？",
  ui_story_6_14_9_dialog_content = "俺たちをだましたな…\nスイェートはお前たちにだまされ、利用され、そして捨てられたんだ！",
  ui_story_6_14_10_dialog_content = "あら。ティッシュなんて、手を拭いたら捨てるものでしょう？",
  ui_story_6_14_11_dialog_content = "ティッシュ…だと…スイェート…",
  ui_story_6_14_12_dialog_content = "あなた、だいぶ汗をかいているわ。\n見張りも大変でしょう。このティッシュ、あげるわ。",
  ui_story_6_14_13_dialog_content = "あ？ああ…ありがとう。",
  ui_story_6_14_14_dialog_content = "なにをボーっとしているの？あら、汗じゃなくて涙の方？",
  ui_story_6_14_15_dialog_content = "あらあら、何を泣いているの？\nあなた反逆者でしょ？泣いて許されると思う？",
  ui_story_6_14_16_dialog_content = "スーモア…貴様…貴様がスイェートを…",
  ui_story_6_14_17_dialog_content = "スィエートがどうかしたかしら？グスド。\n私たちの助けもない、今のお前に何ができるの？",
  ui_story_6_14_20_dialog_content = "スーモア、君がスイェートたちを融合させたの！？",
  ui_story_6_14_22_dialog_content = "違うわ。ああ、でも――そうね、そうともいえるわ。",
  ui_story_6_14_23_dialog_content = "お前…！",
  ui_story_6_14_24_dialog_content = "「なぜそんなことをした」みたいなこと、言いたいんでしょ。",
  ui_story_6_14_25_dialog_content = "教えてあげるわ。私たちにはできるから。ただそれだけのことよ。",
  ui_story_6_14_26_dialog_content = "使い古したものは整理整頓しないとね。捨てるべきものは捨てる。\nそれのどこがおかしいの？怒るようなこと？",
  ui_story_6_14_27_dialog_content = "あれこれ聞かれるのも、そろそろ面倒になってきたわ。",
  ui_story_6_14_28_dialog_content = "PlayerName、それとそこの2人の女…あいつらみたいなクズが彼を苦しめてるのよ。",
  ui_story_6_14_29_dialog_content = "スーモア、貴様…",
  ui_story_6_14_30_dialog_content = "だから、私がそいつらを始末してあげるわ…",
  ui_story_6_14_31_dialog_content = "気を付けろ――！！",
  ui_story_6_14_32_dialog_content = "カレン！？",
  ui_story_6_14_33_dialog_content = "…！",
  ui_story_6_14_34_dialog_content = "あ！グ…スド！？",
  ui_story_6_14_35_dialog_content = "あなた！？",
  ui_story_6_14_36_dialog_content = "お…俺は…",
  ui_story_6_14_37_dialog_content = "チッ…頭おかしくなったの、グスド！！\n犬のくせに、飼い主がわからないの！？",
  ui_story_6_14_38_dialog_content = "どうして…",
  ui_story_6_14_39_dialog_content = "お前たちの…ためじゃないさ。スイェートの…ためだ…",
  ui_story_6_14_40_dialog_content = "…",
  ui_story_6_14_A1_dialog_content = "スーモアを…殺してくれ…",
  ui_story_6_14_A2_dialog_content = "俺では敵わない。でも君たちなら…君たちなら、できる…",
  ui_story_6_14_A3_dialog_content = "あいつを…君たちの剣で殺してくれ…！",
  ui_story_6_14_A5_dialog_content = "スーモア…",
  ui_story_6_14_A7_dialog_content = "…俺とスイェートは…<anim type=Shake><size=50>地獄でお前を待ってるぞ！</size></anim>",
  ui_story_6_14_44_dialog_content = "グスド…あなた…",
  ui_story_6_14_45_dialog_content = "カレン、グスドは…今のが、最後の願いだったんだ。",
  ui_story_6_14_46_dialog_content = "…くだらない。くだらない、くだらないったらありゃしない！\n…グスドも、あんたたちも！あんたたち…",
  ui_story_6_14_47_dialog_content = "スーモア！<color=#FFB400>奴らが来たわ</color>。撤退しなさい。",
  ui_story_6_14_48_dialog_content = "うるさいわね！何のつもり！？邪魔しないで！！",
  ui_story_6_14_49_dialog_content = "今すぐ、そこを離れるのよ。今、すぐ。",
  ui_story_6_14_50_dialog_content = "なんで！？",
  ui_story_6_14_51_dialog_content = "…いったいどうしたんだろう？",
  ui_story_6_14_52_dialog_content = "PlayerName！「<color=#FFB400>援軍</color>」が来たみたい！\n啓光のマークよ！すごい勢いだわ！",
  ui_story_6_14_53_dialog_content = "皆、もう少しの辛抱だ。軍の大部隊が到着すれば、\n1人も逃さず、しっかり包囲してくれるはず！",
  ui_story_6_14_54_dialog_content = "敵の大軍が近づいてるわ。パーツを持って、今すぐ出てきなさい。",
  ui_story_6_14_56_dialog_content = "ちょうど今からこいつらを殺すところだったのよ！？\nそれからPlayerNameを捕まえて、じっくりと…",
  ui_story_6_14_57_dialog_content = "あなたには無理よ。",
  ui_story_6_14_58_dialog_content = "できるわ！3分、いや、1…",
  ui_story_6_14_59_dialog_content = "だから、無理よ！啓光の軍隊が来てる…私は危険を冒したくないの。",
  ui_story_6_14_60_dialog_content = "うおおおおお！！煙を吐け！もっと煙を吐き出せ！",
  ui_story_6_14_61_dialog_content = "啓光第1軍団連合軍、先鋒部隊たる私こそ…",
  ui_story_6_14_62_dialog_content = "暗鬼の狩人、長き夜を終わらせる者、シェルターの爆破人、三途の列車、カロン様だ！",
  ui_story_6_14_63_dialog_content = "今まさに、数万の大軍を率いてささやきの回廊を包囲しつつある！！\n暗鬼ども、逃げるでないぞ！！",
  ui_story_6_14_X64_dialog_content = "私に強制手段を使わせないで、スーモア。",
  ui_story_6_14_65_dialog_content = "…わかった、わかったわよ！ふんっ、どうせもうパーツは手に入れたし…",
  ui_story_6_14_66_dialog_content = "待ちなさい！スーモア！",
  ui_story_6_14_67_dialog_content = "そうだ、「<color=#FFB400>射撃統制モジュール</color>」！一体どこに？",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>ここよ</color>。",
  ui_story_6_14_69_dialog_content = "逃げられないわよ。大部隊がすでに到着しているの、\n私たちだって逃がすつもりはない！",
  ui_story_6_14_70_dialog_content = "そんな暇があるなら、まず白夜城の心配でもしてなさい！",
  ui_story_6_14_71_dialog_content = "白夜城？",
  ui_story_6_14_72_dialog_content = "「永劫不落の都市」なんて、馬鹿げた大ほら吹き…",
  ui_story_6_14_A8_dialog_content = "完全体になった黒い巨像で、至高の力の何たるかを証明してあげるわ！！",
  ui_story_6_14_73_dialog_content = "地面が！みんな気を付けて！",
  ui_story_6_14_74_dialog_content = "アハハハッ！素敵なサプライズでしょ！！",
  ui_story_6_14_75_dialog_content = "これは…マクガフィン！死んだんじゃなかったの？",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>うあああ…ああああ！！</size></anim>",
  ui_story_6_14_77_dialog_content = "節約は美徳よ、使えるものは使うの。",
  ui_story_6_14_78_dialog_content = "もたもたしないで。黒い巨像はもう降りてる…",
  ui_story_6_14_79_dialog_content = "ああ、面白いお芝居なのに、最後まで見れないなんて残念だわ。",
  ui_story_6_14_80_dialog_content = "…まぁ、いいわ。これからもっと面白くなるもの。\nそれじゃ、ごきげんよう！",
  ui_story_6_14_81_dialog_content = "この暗鬼は…マクガフィン？強烈な敵意を感じる！",
  ui_story_6_14_83_dialog_content = "あのマクガフィン、以前とは気配が全然違うわ！みんな、油断しないで！",
  ui_story_6_14_84_dialog_content = "マクガフィンは倒したはずなのに、前よりもっとたちが悪くなってたわ…",
  ui_story_6_14_85_dialog_content = "あなたたち、白夜城へ来る前に、この暗鬼に出会ったことがあるの？",
  ui_story_6_14_86_dialog_content = "あるわ、でも…確かに死んだはずよ。",
  ui_story_6_14_87_dialog_content = "それなら、日蝕が骸を復活させて、新しい道具にしたと\nいうところかしら。本当に悪趣味…",
  ui_story_6_14_90_dialog_content = "彼女たちにとって、他の暗鬼なんて仲間でも何でもないのね。\nスイェートとシャイアも同じ、ただの道具に過ぎなかった…",
  ui_story_6_14_92_dialog_content = "「<color=#FFB400>射撃統制モジュール</color>」も奪われちゃったわ。これからどうする？",
  ui_story_6_14_93_dialog_content = "グスドの事もどうにかする必要があるわね…",
  ui_story_6_14_94_dialog_content = "カレン？",
  ui_story_6_14_97_dialog_content = "…グスドを焼くわ。",
  ui_story_6_14_98_dialog_content = "埋葬しないってこと？火葬は白夜城の習わしじゃなかったわよね…",
  ui_story_6_14_99_dialog_content = "そもそも、グスドは反逆者よ。本来ならその屍は、打ち捨てられてしかるべきもの。\nそれに、日蝕が遺体を蘇らせる可能性もあるわ。",
  ui_story_6_14_100_dialog_content = "確かに、死体まで戦いの道具にされるなんて、ひどすぎる…",
  ui_story_6_14_102_dialog_content = "バイス、PlayerName、何か火を付けられるものを探しましょう。",
  ui_story_6_14_103_dialog_content = "カレン・ド・ソルラド、白夜城護衛隊長が白夜城の代表として、\nグスドへの最後の言葉をここに手向けん…",
  ui_story_6_14_104_dialog_content = "彼は白夜城の騎士として、戦乱の中で華々しい戦功を残した。",
  ui_story_6_14_105_dialog_content = "後に凡俗に苦しみ、邪悪にうなされ、暗鬼に籠絡され、白夜城に背いた。",
  ui_story_6_14_106_dialog_content = "また、悪人に唆され、悪事を尽くして混乱を招き、\n我が白夜城の民に危険を及ぼした。その罪は許されざるものである。",
  ui_story_6_14_107_dialog_content = "しかし、最後には己の過ちを改め、命をもって償った。\n犯した罪は消えるものではない。しかし、しかばねを晒すことは免ずるものとする。",
  ui_story_6_14_108_dialog_content = "ここにその骸に火をつけ、彼の者の名節を守らん…白夜に捧ぐ。",
  ui_story_6_14_109_dialog_content = "グスド、白夜城の英雄、反逆の騎士、日蝕の走狗。ここで安らかに眠れ。",
  ui_story_6_14_111_dialog_content = "これで、グスドも安らかに眠れるでしょう…\nPlayerName、スーモアの居場所は感知できる？",
  ui_story_6_14_112_dialog_content = "もうささやきの回廊を離れてるはずだよ。",
  ui_story_6_14_114_dialog_content = "でも、方向まではわからない。あえて言うなら、上空かな…",
  ui_story_6_14_115_dialog_content = "上空…スーモアは白夜城がどうとか言っていたけど、まさかね…",
  ui_story_6_14_116_dialog_content = "ちょっと失礼！あなた達、まだ生きてる！？",
  ui_story_6_14_117_dialog_content = "もちろん！！",
  ui_story_6_14_118_dialog_content = "ついさっき、とんでもない力を感じるコが飛び出していったから、てっきり…",
  ui_story_6_14_119_dialog_content = "「射撃統制モジュール」を奪えなかった以外は、無事です！",
  ui_story_6_14_120_dialog_content = "よかったわぁ…",
  ui_story_6_14_121_dialog_content = "啓光の軍隊は？さっき援軍が来たって言ってましたよね？",
  ui_story_6_14_122_dialog_content = "ええと、後で自分の目で見た方がいいかも…",
  ui_story_6_14_123_dialog_content = "…やあ、バイス、PlayerName。",
  ui_story_6_14_124_dialog_content = "カロン長官…？",
  ui_story_6_14_125_dialog_content = "まずは一口、水を飲ませてくれたまえ。\nなにせ一目散に来たものだからな…実に疲れた…",
  ui_story_6_14_126_dialog_content = "一体どういうこと？啓光の軍隊は？",
  ui_story_6_14_127_dialog_content = "数時間前に、フィリスの奴から\n君たちが面倒なことに巻き込まれていると聞いたのだが…",
  ui_story_6_14_128_dialog_content = "カナンが兵を出し渋ったのでな。\nまぁ、私の一存でやってきたというわけだ…",
  ui_story_6_14_129_dialog_content = "まさか、シェオルさんが言っていた「軍隊」って…",
  ui_story_6_14_130_dialog_content = "君の想像通りだ、バイス。",
  ui_story_6_14_131_dialog_content = "この付近で奇妙な黒い巨像を発見してね。\nそれから、シェオル女史に出くわした。",
  ui_story_6_14_132_dialog_content = "君たちではスーモアに敵わないのではないかと彼女が心配していたのでな、\n僭越ながら一芝居、うたせてもらったというわけだ。",
  ui_story_6_14_133_dialog_content = "とはいえ…まったく、列車1つで数千人の軍勢を演出するのは、\nなかなか大変だったとも…",
  ui_story_6_14_134_dialog_content = "それってハッタリ…万が一スーモアが引っかからなかったら、\nどうするつもりだったの？",
  ui_story_6_14_135_dialog_content = "それでも試してみる価値はあるさ…\nそれに、啓光の列車にどれだけ兵士が乗っているかなど、わかるわけがないだろう？",
  ui_story_6_14_136_dialog_content = "それはそうと、スーモアの奴はどこへ逃げたのだ？",
  ui_story_6_14_137_dialog_content = "自分で起こした砂ぼこりに完全に飲まれていたから、何も見えなくてな…",
  ui_story_6_14_138_dialog_content = "気配の行った先は大体わかってる。上空…白夜城の方向だよ。",
  ui_story_6_14_139_dialog_content = "白夜城！？",
  ui_story_6_14_140_dialog_content = "！？白夜城ですって？",
  ui_story_6_14_141_dialog_content = "パーツがすべて揃ったところで、そのまま白夜城に向かうなんて…\n白夜城に手を出すつもりなの！？",
  ui_story_6_14_142_dialog_content = "ありえないわ…白夜城は強大なシールドに包まれているの。\nそう簡単に手なんて出せるはずがない！",
  ui_story_6_14_A9_dialog_content = "そうするからには、きっと理由があるのよ…",
  ui_story_6_14_143_dialog_content = "…つまり、完全体の巨像なら、\n白夜城と正面切って戦えると思っているということ！？",
  ui_story_6_14_144_dialog_content = "PlayerName、今すぐ白夜城に向かうわよ！",
  ui_story_6_14_145_dialog_content = "うん…僕たちも急ごう！",
  ui_story_7_1_1_dialog_content = "「白夜の主は我が鎧、血肉、そして骨である。\nいかなる邪悪もこの身を傷つけることはできぬ…」",
  ui_story_7_1_A1_dialog_content = "白夜の主は我が鎧、血肉、そして骨である。いかなる邪悪も――どうした！慌てるな！！",
  ui_story_7_1_2_dialog_content = "おい見ろ！ぶつかった！ぶつかったぞ！",
  ui_story_7_1_3_dialog_content = "あれは…く…<color=#FFB400>黒い龍</color>？？？",
  ui_story_7_1_4_dialog_content = "だ、大丈夫だよな？我らのシールドは堅固だ、そう簡単には破られるわけがない！",
  ui_story_7_1_5_dialog_content = "白夜の主を、極光の加護を信じるんだ。",
  ui_story_7_1_6_dialog_content = "シールドがある限り、いかなる邪悪も神聖なる\nアップタウンには踏み入れない！恐れることなどない！",
  ui_story_7_1_7_dialog_content = "もうすぐ着くわ！白夜城はこの先よ！",
  ui_story_7_1_8_dialog_content = "どうして空がこんな色になってるの？",
  ui_story_7_1_9_dialog_content = "城主が<color=#FFB400>シールド</color>を起動したからよ。",
  ui_story_7_1_X1_dialog_content = "危険な目に遭っている人が大勢いるかもしれないわ。\n早く中に入りましょう！",
  ui_story_7_1_X2_dialog_content = "スーモアは？",
  ui_story_7_1_10_dialog_content = "人命救助が優先よ。行きましょう！",
  ui_story_7_1_11_option_content = "わかった、街の中に停めよう",
  ui_story_7_1_12_option_content = "いや、外に停めた方がいい",
  ui_story_7_1_13_dialog_content = "無理でしょうね…私の大きさで、\nこのような状態の白夜城に進入することはできません。",
  ui_story_7_1_14_dialog_content = "ダメよ。白夜城の<color=#FFB400>シールドが起動されている</color>の。",
  ui_story_7_1_A2_dialog_content = "シールドが侵入を防ぐのは暗鬼だけじゃないわ。ソラヴァンも入れないのよ。",
  ui_story_7_1_16_dialog_content = "白夜城のシールドって、すごいんだね…\nでも、これなら焦って街に行かなくてもいいんじゃないの？",
  ui_story_7_1_17_dialog_content = "シールドが守るのはアップタウンだけ。\nそれ以外の場所は…完全にシールドの外よ。",
  ui_story_7_1_F1_dialog_content = "暗鬼は必ずダウンタウンから侵入して、\nシールドの盲点を突いてくるはず！",
  ui_story_7_1_F2_dialog_content = "ダウンタウンは暗鬼だらけになるわ。\nソラヴァンを停めておくわけにはいかない。",
  ui_story_7_1_18_dialog_content = "PlayerName、私は白夜城の上空に停泊し、\nいつでもお迎えに行けるようにしておきます。",
  ui_story_7_1_19_dialog_content = "それって、危なくないの？",
  ui_story_7_1_F3_dialog_content = "なるべくスーモアから距離を置き、\nいつでも皆さんと連絡が取れるようにしておきます。",
  ui_story_7_1_F4_dialog_content = "じゃあ、頼むよ、ソラヴァン。",
  ui_story_7_1_20_dialog_content = "カレン、白夜城が陥落することなんてないわよね？",
  ui_story_7_1_21_dialog_content = "ありえない。\n<color=#FFB400>あの男</color>がいる限り、白夜城の根幹が脅かされることは決してないわ。",
  ui_story_7_1_22_dialog_content = "そうですね。私の大きさと白夜城の現状を考慮すると、進入は難しいでしょう。",
  ui_story_7_1_23_dialog_content = "PlayerNameは、ソラヴァンに外で待っていてもらった方がいいと思うの？",
  ui_story_7_1_24_dialog_content = "その通りだよ。スーモアが白夜城をターゲットにしているなら、\nソラヴァンはそこからできるだけ遠くにいた方がいいと思う…",
  ui_story_7_1_25_dialog_content = "賛成よ。そもそも、ソラヴァンで街に入ることはできないわ。",
  ui_story_7_1_26_dialog_content = "アップタウンの<color=#FFB400>シールドが展開している</color>から、\nどんなものでも入ることはできない。",
  ui_story_7_1_F5_dialog_content = "でも、暗鬼は必ずダウンタウンから侵入して、\nシールドの盲点を突いてくるはず！",
  ui_story_7_1_27_dialog_content = "PlayerName、私は白夜城の上空に停泊し、\nいつでもお迎えに行けるようにしておきます。",
  ui_story_7_1_28_dialog_content = "それって、危なくないの？",
  ui_story_7_1_F6_dialog_content = "なるべくスーモアから距離を置き、\nいつでも皆さんと連絡が取れるようにしておきます。",
  ui_story_7_1_F7_dialog_content = "じゃあ、頼むよ、ソラヴァン。",
  ui_story_7_1_29_dialog_content = "全速力で急ぎましょう。\nもし本当に、スーモアが白夜城を落とせるという確信を持っているなら…",
  ui_story_7_1_30_dialog_content = "ありえない。\n<color=#FFB400>あの男</color>がいる限り、白夜城の根幹が脅かされることは決してないわ。",
  ui_story_7_1_31_dialog_content = "城主様、脅威を確認いたしました。巨像が、白夜城を攻撃しております！",
  ui_story_7_1_32_dialog_content = "シールドはすでに起動しております。\n現時点において、アップタウン一帯は依然として安全です。",
  ui_story_7_1_33_dialog_content = "油断はせぬように。現時点ではまだ敵の実力も、その意図もわからぬのだ。\n警戒を続けよ。",
  ui_story_7_1_34_dialog_content = "護衛隊に引き続き敵の動向を注視させ、\n諜報員は常に最新の情報に目を光らせよ。",
  ui_story_7_1_35_dialog_content = "ダウンタウンの状況はどうだ？",
  ui_story_7_1_36_dialog_content = "城主様、ダウンタウンは暗鬼の侵入を受けています。\n人手を割きましょうか？",
  ui_story_7_1_37_dialog_content = "いや、アップタウンの防衛が最重要だ。\n怖気づいた貴族たちが愚かなまねをせんようにな。",
  ui_story_7_1_38_dialog_content = "ダウンタウンにはダウンタウンの者たちの生きるすべがある。",
  ui_story_7_1_39_dialog_content = "啓光の者どもはどうしている？",
  ui_story_7_1_40_dialog_content = "軍団の兵力は大部分がこの地から離れた地域に配置されております。\n今すぐ救援に戻す、とはいかないかと。",
  ui_story_7_1_41_dialog_content = "白夜城付近には、ビビアン参謀長とキシローナ軍団長の小隊、2隊のみです。",
  ui_story_7_1_42_dialog_content = "その二人か…よろしい。最後になるが…<color=#FFB400>カレン</color>は？何か知らせがあったか？",
  ui_story_7_1_43_dialog_content = "情報によると、護衛隊長は現在ダウンタウンに徒歩で入られたようです。",
  ui_story_7_1_44_dialog_content = "ただちにアップタウンに戻せ。お遊びをしている時ではない。\nあらぬ噂の種があるのは、よろしくない。",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>白夜城・ダウンタウンエリア</color>",
  ui_story_7_1_46_dialog_content = "護衛隊の姿が全然見えないわ。",
  ui_story_7_1_47_dialog_content = "でも、もう暗鬼の気配がプンプンしてるよ。",
  ui_story_7_1_48_dialog_content = "こんなに混乱してるなんて、本当にこの前見たばかりの白夜城なの…？",
  ui_story_7_1_49_dialog_content = "…停留地点に到着しました。あなたたちの上方およそ…の位置です。",
  ui_story_7_1_A3_dialog_content = "白夜城のシールドにより通信干渉が生じているようです。聞こえているといいのですが…",
  ui_story_7_1_50_dialog_content = "心配いらない、聞こえてるよ！\n僕たちはみんな無事だ。自分のことだけ気を付けて！",
  ui_story_7_1_51_dialog_content = "それはこちらのセリフです、PlayerName。",
  ui_story_7_1_52_dialog_content = "私は…お待ちしています！どうか…気を付けて…",
  ui_story_7_1_53_dialog_content = "ううん、誰か今の状況を説明してくれる人がいないかしら…",
  ui_story_7_1_54_dialog_content = "それほど深刻ではありませんよ、バイス、PlayerName。",
  ui_story_7_1_55_dialog_content = "<color=#FFB400>ビビアン</color>長官！",
  ui_story_7_1_56_dialog_content = "ほとんどの軍団は近辺の別区域を防衛していますから、\nここに来ることができたのは、今のところ私たちだけですが。",
  ui_story_7_1_57_dialog_content = "「白夜城陥落」とまで騒がれていますが、民衆は大げさすぎです。",
  ui_story_7_1_A4_dialog_content = "それと、また会えましたね、空の末裔さん。\nながらく面倒ごとに巻き込まれているみたいですね。",
  ui_story_7_1_58_dialog_content = "僕だって巻き込まれたいわけじゃありません。\nあんまり責めないでください…",
  ui_story_7_1_59_dialog_content = "そのような意味ではありません。あなたは一生懸命スーモアを\n阻止しようとしていたでしょう？見通しが甘かったのは私たちの方です。",
  ui_story_7_1_60_dialog_content = "長官、現在の白夜城の状況は？",
  ui_story_7_1_61_dialog_content = "アップタウンはむろん心配いりません。あのシールドは見ましたね？",
  ui_story_7_1_62_dialog_content = "すでに起動していますから、いかなる攻撃も通らないでしょう。\nそれが「永劫不落」とまで呼ばれる業…",
  ui_story_7_1_63_dialog_content = "だが、ダウンタウンはそうはいかない。",
  ui_story_7_1_64_dialog_content = "<color=#FFB400>キシローナ</color>長官？いえ、軍団長…",
  ui_story_7_1_65_dialog_content = "あ、言い忘れていました。緊急派遣されている兵力の大部分は、第1軍団のものです。",
  ui_story_7_1_66_dialog_content = "シールドの外側にあるダウンタウンは、暗鬼どころか、\n3歳の子どもまで自由にうろつけるありさまだ。",
  ui_story_7_1_68_dialog_content = "対処できているの？現在の状況を詳しく教えて。",
  ui_story_7_1_70_dialog_content = "急ぎ掃討中だ。面倒ではあるが、この数なら私たちだけでどうにか対処できる。",
  ui_story_7_1_71_dialog_content = "護衛隊は？私は直ちにアップタウンに戻るよう知らせを受けたけど、\n他の護衛隊はどこに？",
  ui_story_7_1_72_dialog_content = "カレン・ド・ソルラド。私が言ったことの意味を理解していないようだな。",
  ui_story_7_1_A5_dialog_content = "お父上からの命令だ。\n君を含め、護衛隊は全員アップタウンの守りに全力を尽くせ、とな。",
  ui_story_7_1_73_dialog_content = "驚きはするまい？想像がつかなかったわけではなかろう。",
  ui_story_7_1_74_dialog_content = "そんな態度をとる必要はないでしょう、キシローナ！\nこれまでの行動で、私自身の意志は十分に伝えてきたつもりよ！",
  ui_story_7_1_75_dialog_content = "その行動とやらで、何か変化はあったか？\n白夜城は依然として昔のままではないか。",
  ui_story_7_1_76_option_content = "2人とも、もうやめてよ",
  ui_story_7_1_77_option_content = "今は言い争っている場合じゃない！",
  ui_story_7_1_78_dialog_content = "言い争うつもりは微塵もないわ。",
  ui_story_7_1_79_dialog_content = "PlayerName、部外者が口を出すな。",
  ui_story_7_1_80_dialog_content = "これは、啓光と白夜の問題だ。",
  ui_story_7_1_81_dialog_content = "そうじゃないよ…それに、君たちはどちらも光霊なんだから…",
  ui_story_7_1_82_dialog_content = "長官、PlayerNameはこの状況を心配しているだけです。皆、焦っていますし…",
  ui_story_7_1_83_dialog_content = "バイスは人の心が分かっていますね。\nPlayerNameの言うとおりです。みんな大切な仲間でしょう？",
  ui_story_7_1_84_dialog_content = "まずは光霊として一緒に戦うことが大切です。そうでしょう？ね？",
  ui_story_7_1_85_dialog_content = "…賛成だわ。今は立場なんて重要じゃない。",
  ui_story_7_1_86_dialog_content = "立場と言えば、カレンはまずアップタウンに戻って復命しなくてよいのですか？\n城主様がお待ちだそうですよ。",
  ui_story_7_1_F8_dialog_content = "暗鬼の群れが迫ってるんだよ、見えてないの！？",
  ui_story_7_1_87_dialog_content = "口の利き方に気を付けろ、PlayerName！",
  ui_story_7_1_88_dialog_content = "PlayerName、あの方は啓光第一軍団の軍団長だし…カレンも…",
  ui_story_7_1_89_dialog_content = "わかってるよ！でも、軍団長だろうと護衛隊長だろうと、\n口げんかのせいで人命救助が手遅れになるのは、本望じゃないはずでしょ？",
  ui_story_7_1_90_dialog_content = "いいわ、今は何よりも暗鬼の殲滅を優先しないと。\nつまらない内輪揉めをしている場合ではないわ。",
  ui_story_7_1_91_dialog_content = "それは残念。お姫様にうまく世渡りする方法を\nご教示願おうかと思っていたが、後回しだな。",
  ui_story_7_1_92_dialog_content = "まぁ、暗鬼を殲滅することなら、もともと最前線で毎日やっていることだ。",
  ui_story_7_1_93_dialog_content = "最近いろいろと戦いを経験してきたそうだな。\n今なら戦い方も少しはわかるようになっただろう？",
  ui_story_7_1_94_dialog_content = "…",
  ui_story_7_1_95_dialog_content = "ほらほら、そのくらいにしましょう。みんな仲間なんですから。\n元気があるなら、まずは暗鬼を何とかしませんか？",
  ui_story_7_1_96_dialog_content = "カレンも、まずは命令通り、アップタウンに戻って…",
  ui_story_7_1_97_dialog_content = "戻らないわ。「将、外にあっては君命も奉ぜざるあり」よ。",
  ui_story_7_1_98_dialog_content = "ここは…「外」じゃないでしょう、家に攻め込まれてるのよ…",
  ui_story_7_1_F9_dialog_content = "バイス、もういいの…",
  ui_story_7_1_99_dialog_content = "軍団長！ダウンタウンに出現した暗鬼、予想以上の多数！\n防衛線が拡がりすぎ、穴ができております！",
  ui_story_7_1_A6_dialog_content = "民衆の避難がまだできておりません、ご指示を！",
  ui_story_7_1_100_dialog_content = "私が行く！そちらは好きにするがいい。",
  ui_story_7_1_101_dialog_content = "ご一緒します！少しはお役に立てるはず！",
  ui_story_7_1_102_dialog_content = "いい意気込みです、バイス！<color=#FFB400>では、みんなで行きましょう</color>！",
  ui_story_7_1_103_dialog_content = "案内するわ。ダウンタウンは、私が数えきれないくらいパトロールした場所よ。\n誰よりも詳しいわ。",
  ui_story_7_1_104_dialog_content = "カレン…本当に戻らなくて大丈夫なの？",
  ui_story_7_1_105_dialog_content = "何も言わないで。もう決めたの。すべてに…けりをつけないと。",
  ui_story_7_1_106_dialog_content = "白夜城の甲羅って、本当に硬いのね。",
  ui_story_7_1_107_dialog_content = "…チッ、どうして教えてくれなかったの？\nこんな防壁、臆病者のやり口だわ！",
  ui_story_7_1_108_dialog_content = "言ったでしょう、ちゃんと準備を整えてから攻めましょうって。\nうぬぼれすぎて理性が吹っ飛んでない？",
  ui_story_7_1_109_dialog_content = "…お説教より、さっさとあなたの犬どもを白夜城に放って、荒らしてやって！",
  ui_story_7_1_110_dialog_content = "しーっ…静かに。私、うるさいのは嫌いなの。",
  ui_story_7_1_111_dialog_content = "そのうち、白夜城のシールドもエネルギーが切れるわ。",
  ui_story_7_1_A7_dialog_content = "それから…好きに入ればいいじゃない。",
  ui_story_7_1_112_dialog_content = "それじゃ、今は何をするの？待つ？それとも攻め続ける？",
  ui_story_7_1_113_dialog_content = "あなたの使えないザコがモタモタしているのをただ黙って見てる？",
  ui_story_7_1_114_dialog_content = "焦らないで、スーモア。\nあなたの因縁のライバルも来てるわよ。近くに隠れたみたい。",
  ui_story_7_1_116_dialog_content = "ソラヴァンのこと？それにPlayerNameも？",
  ui_story_7_1_117_dialog_content = "そうよ。スーモア、あなたの表情、どういう意味かしら？\nまた遊びに行きたいの？勝手な行動もほどほどにね。",
  ui_story_7_1_X3_dialog_content = "…私はやりたいことをやるだけ。忘れたの？\n私はあなたの命令も日蝕の命令も聞かないわ。",
  ui_story_7_1_X4_dialog_content = "やれやれ。どうしようもないわね。",
  ui_story_7_2_1_dialog_content = "カレン、支援が必要な場所まであとどれくらい？",
  ui_story_7_2_2_dialog_content = "着いたわ！この辺りよ、さっきあの兵士が言っていたのは…",
  ui_story_7_2_3_dialog_content = "暗鬼の気配が濃くなったわ。<color=#FFB400>行動に優先順位をつける</color>としたら…",
  ui_story_7_2_4_option_content = "まずは住民を避難させる",
  ui_story_7_2_5_option_content = "まずはうろついている暗鬼を一掃する",
  ui_story_7_2_6_dialog_content = "PlayerNameは、人のことを1番に考えて決定を下すんですね！\n将来大物になるかもしれません！",
  ui_story_7_2_7_dialog_content = "急にべた褒めしますね…",
  ui_story_7_2_8_dialog_content = "いい。逃げ遅れた民衆なら私が探してこよう。私の方が速いからな。",
  ui_story_7_2_A1_dialog_content = "そちらはひたすら目の前の暗鬼を倒していればいい。\nそのくらいならできるだろう？",
  ui_story_7_2_9_dialog_content = "わかったわ！スムーズな救援を行うためには、危険の原因を絶たないといけないものね。",
  ui_story_7_2_10_dialog_content = "では、手分けしてやりましょう。救援と戦闘を同時に進められそうです。",
  ui_story_7_2_11_dialog_content = "逃げ遅れた民衆なら私が探してこよう。私の方が速いからな。",
  ui_story_7_2_A2_dialog_content = "そちらはひたすら目の前の暗鬼を倒していればいい。\nそのくらいならできるだろう？",
  ui_story_7_2_12_dialog_content = "人を馬鹿にするのもいい加減にして、キシローナ。",
  ui_story_7_2_13_dialog_content = "あらあら、どちらもやる気満々ということですね。\nそれなら良かった、始めましょう！",
  ui_story_7_2_14_dialog_content = "私はこちらへ進みます。バイスはあちらをお願いしますね！",
  ui_story_7_2_15_dialog_content = "それから、巨像はどちらに？状況が不明確ですから、\n敵に退路を断たれないよう気をつけてくださいね。",
  ui_story_7_2_16_dialog_content = "街の外に停まってます。今はとても安全…なはず。",
  ui_story_7_2_17_dialog_content = "数はこちらが不利です。みなさん、頑張ってくださいね。",
  ui_story_7_2_F1_dialog_content = "せめて、護衛隊の協力があれば…",
  ui_story_7_2_18_dialog_content = "私は護衛隊に数えられていないのかしら？",
  ui_story_7_2_19_dialog_content = "あっ、ごめんなさい！責めていたつもりはありません！",
  ui_story_7_2_21_dialog_content = "とにかく、急ぎましょう！今日の暗鬼討伐ノルマも最低3ケタです！",
  ui_story_7_2_22_dialog_content = "さ、最低目標3ケタ！？",
  ui_story_7_2_23_dialog_content = "啓光の長官はみんな普通じゃないから…\nとにかく、私たちも周囲の敵を一掃しましょう！",
  ui_story_7_6_1_dialog_content = "ふう――この辺りはすっかり片付いたわね。",
  ui_story_7_6_2_dialog_content = "こっちも！…長官、ダウンタウンで\n他に支援を必要としている場所はありますか？",
  ui_story_7_6_3_dialog_content = "新しい虫が湧いているが、対応できる数だ。御苦労だった。",
  ui_story_7_6_4_dialog_content = "ふう…ハラハラしたけど何とかなったわね。\n素早く行動できたおかげかしら…",
  ui_story_7_6_6_dialog_content = "やりましたね、バイス。これでダウンタウンはしばらく大丈夫でしょう。\n他の場所を見に行けますね。",
  ui_story_7_6_7_dialog_content = "ずる賢い敵さんが、守りの薄い場所を奇襲しようとしているかもしれません。",
  ui_story_7_6_8_dialog_content = "長官は「言ったことが本当になる」っていう特技があること、お忘れですか…",
  ui_story_7_6_9_dialog_content = "念のため、ソラヴァンの状態を確認した方がいい気がするわ。\nPlayerName？",
  ui_story_7_6_10_dialog_content = "そういえば、ソラヴァンからしばらく連絡がないな。やってみるよ…",
  ui_story_7_6_12_dialog_content = "…正常です。暗鬼はいません…ですが、突然、気温が大幅に低下したようです。私は…",
  ui_story_7_6_13_dialog_content = "<size=45>これは…！？</size>",
  ui_story_7_6_14_dialog_content = "どうしたのカレン？怪我でもしたの？",
  ui_story_7_6_15_dialog_content = "いえ…たった今情報が入ったわ。<color=#FFB400>アップタウンが攻撃されている</color>。",
  ui_story_7_6_16_dialog_content = "アップタウンが？\nまさか、ダウンタウンの防衛線を突破して、アップタウンに侵入されたってこと？",
  ui_story_7_6_17_dialog_content = "いいえ、ダウンタウンの防衛線は突破されていないようだわ。\n恐らく、あらかじめ潜伏させていたのでしょう。",
  ui_story_7_6_18_dialog_content = "直接白夜城の中心部に進攻するつもりなの？\nアップタウンの守備は相当に固いはずでしょう？",
  ui_story_7_6_19_dialog_content = "ええ、とてもね。でも、さっきの暗鬼たちの行動、どうもきな臭いわ…",
  ui_story_7_6_20_dialog_content = "スーモアが白夜城を攻撃してきたということは、\n暗鬼たちも何かしら備えをしているはずだよ。",
  ui_story_7_6_21_dialog_content = "そうね、急にいやな予感がしてきたわ。今すぐ戻らないと。",
  ui_story_7_6_22_dialog_content = "私たちも一緒に行きましょ！PlayerName、早く！",
  ui_story_7_6_23_dialog_content = "アップタウンに潜伏できるなら、恐るべき実力があるはずよ…\n同行、感謝するわ。",
  ui_story_7_6_24_dialog_content = "そうね！…長官、たった今情報が入って、アップタウンが特殊な暗鬼の\n攻撃を受けていることが分かりました！これより応援に向かいます！",
  ui_story_7_6_25_dialog_content = "こちらはもう向かっています。",
  ui_story_7_6_26_dialog_content = "間もなく到着する。",
  ui_story_7_6_27_dialog_content = "軍団長、やっぱりただものじゃないね！？",
  ui_story_7_7_1_dialog_content = "遅くなってごめんなさい！",
  ui_story_7_7_2_dialog_content = "隊長！やっと戻ってこられたのですね！暗鬼が…",
  ui_story_7_7_3_dialog_content = "無駄話はいいわ！敵は！？",
  ui_story_7_7_4_dialog_content = "こちらです！ついて来てください！",
  ui_story_7_7_5_dialog_content = "<size=45>…グオオオオオ…！！</size>",
  ui_story_7_7_6_dialog_content = "攻撃を続けろ！これ以上進ませるな！この先はもう街の入り口だ！！",
  ui_story_7_7_7_dialog_content = "グゥアアアア――！？",
  ui_story_7_7_8_dialog_content = "ま、まずい！防衛線が崩れた、立て直せ！！何としてもアップタウンに入れるな！！",
  ui_story_7_7_9_dialog_content = "わあ！カレンちゃん！！",
  ui_story_7_7_10_dialog_content = "何をしてるの！？あいつがあちこち破壊して回るのを見物してるつもり！？\nここは白夜城の中心部なのよ！",
  ui_story_7_7_11_dialog_content = "城主様が命令で、<color=#FFB400>アップタウンの防衛に専念せよ</color>って…",
  ui_story_7_7_12_dialog_content = "厳密にいうと、あのでっかい虫はまだ中に入って来ていないから、\n出て行っちゃダメだって…",
  ui_story_7_7_13_dialog_content = "どういう理屈よ！？",
  ui_story_7_7_15_dialog_content = "カレン、護衛隊が出られなくても、まだ啓光の応援があるわ！\nあの長官たちなら何とかしてくれるはずよ！",
  ui_story_7_7_16_dialog_content = "また護衛隊のやつらの尻拭いをさせられるのか？",
  ui_story_7_7_17_dialog_content = "長官！護衛隊は…命令を受けているので、アップタウンから離れられません。\n私たちが行きましょう！",
  ui_story_7_7_18_dialog_content = "白夜城のやつらと共闘するたびに、\n「役立たず」って言葉への理解を改めさせられるな。",
  ui_story_7_7_19_dialog_content = "はいはい、ローナ。愚痴ってる時ではありません。\nこのままでは兵士たちが耐えられなくなりそうです…",
  ui_story_7_7_21_dialog_content = "縄とトラクターを持ってこい！\nそんなもの、直接手足をバラバラにしてやればいい！",
  ui_story_7_7_22_dialog_content = "バ、バラバラ！？",
  ui_story_7_7_23_dialog_content = "…？",
  ui_story_7_7_24_dialog_content = "その方が後で処理しやすいからな！経験談だ！\nお子様どもは戦闘だけに集中していればいい！",
  ui_story_7_7_25_dialog_content = "は、はい！長官、何をすれば…",
  ui_story_7_7_26_dialog_content = "まずはこいつを倒す！ビビアン、機を見て前のように「ばっさり」頼むぞ！",
  ui_story_7_7_27_dialog_content = "前のように、ですね。わかりました。",
  ui_story_7_7_28_dialog_content = "私が道を開くわ！無駄死にしたくなければ、退きなさい！<color=#FFB400>指揮</color>は…",
  ui_story_7_7_29_dialog_content = "任せて！期待は裏切らないよ！",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>アップタウンの土は一歩も踏ませない</color>！",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>グオォォン！！！</size></anim>",
  ui_story_7_7_32_dialog_content = "ビビアン、今だ！",
  ui_story_7_7_33_dialog_content = "了解！「雷撃」！",
  ui_story_7_7_34_dialog_content = "「血ノツグナイ」！",
  ui_story_7_7_36_dialog_content = "た、倒した！ようやく…",
  ui_story_7_7_37_dialog_content = "いい働きだった！お子様だと思っていたが、なかなかやるじゃないか！",
  ui_story_7_7_38_dialog_content = "…",
  ui_story_7_7_39_dialog_content = "照れちゃうなぁ。",
  ui_story_7_7_40_dialog_content = "ご報告いたします！\n黒い巨像の攻撃は依然として継続中、弱まる兆しがありません！",
  ui_story_7_7_41_dialog_content = "スーモア…",
  ui_story_7_7_42_dialog_content = "まだわかってないのかしら…このまま続けても、\n彼女にとっていいことなんかないのに？",
  ui_story_7_7_43_dialog_content = "身の程知らずね。暗鬼が何度来ようと、\nアップタウンには指一本触れられないわ。",
  ui_story_7_7_44_dialog_content = "本当に愚かなだけなのかもしれん。",
  ui_story_7_7_45_dialog_content = "これで、アップタウンの脅威は完全に排除されたのだな？\n他にないなら、私は行くぞ。",
  ui_story_7_7_46_dialog_content = "第1部隊はまだ東側の防衛態勢を急いで整えなければならないのだ。\n「護衛隊さんのおかげ」でな。",
  ui_story_7_7_47_dialog_content = "…なにはともあれ、協力に感謝するわ、啓光の皆さん。",
  ui_story_7_7_48_dialog_content = "いい、礼ならPlayerNameとバイスに言え。",
  ui_story_7_7_A2_dialog_content = "誰もが辛抱強く白夜城の奴らと協力できるわけじゃない。\n仲間として背中を預けるとなれば、なおさらだ。",
  ui_story_7_7_49_dialog_content = "…",
  ui_story_7_7_50_dialog_content = "よくわからないこと言って行っちゃいましたね。\nローナってそういうところがありますから。あまり気にしないでくださいね、カレン。",
  ui_story_7_7_51_dialog_content = "危機も一段落つきましたし、\nこれが最良の結果と言っていいのではないでしょうか。",
  ui_story_7_7_52_dialog_content = "スーモア、ついに行き詰ったんだ。闇雲に白夜城を攻めたけど、\nまさか破れない防衛手段があるなんて、思ってなかったんだろう。",
  ui_story_7_7_53_dialog_content = "でも、これからどうするつもりかな？\nあの黒い巨像は、もう完全体になっていたのかな？",
  ui_story_7_7_X1_dialog_content = "パーツは3つとも奪われたけど…\nあの黒い巨像、そんなに強そうには見えないよ。",
  ui_story_7_7_54_dialog_content = "たぶん、まだ補完は終わってないんじゃないかしら？\n単に敵を甘く見て、攻撃を急ぎすぎただけだと思うわ。",
  ui_story_7_7_55_dialog_content = "敵を知るあなたたちの判断からすると、\nまだ何か予想外の行動を取ってくるかも、ということでしょうか？",
  ui_story_7_7_56_dialog_content = "そうなると、大変なことになってしまうかもしれませんね？",
  ui_story_7_7_57_dialog_content = "ビビアン長官、やめてくださいよ…長官が何か言うといつも…",
  ui_story_7_7_58_option_content = "こちらから攻めるべき",
  ui_story_7_7_59_option_content = "今は静観するのがいい",
  ui_story_7_7_60_dialog_content = "賛成よ！今こそ、勢いに乗じて攻めこむべき時！",
  ui_story_7_7_61_dialog_content = "そうね、パーツを奪われた時はやられっぱなしだったけど、\n今度こそ反撃してみせるわ！",
  ui_story_7_7_62_dialog_content = "PlayerNameの言うとおりです。より多くの情報を掴むまでは、\n静観が最善の手でしょう。",
  ui_story_7_7_63_dialog_content = "今、誰よりも焦っているのはスーモアに違いありません…",
  ui_story_7_7_A3_dialog_content = "苦労して3つのパーツを手に入れたのに、\n目論見が外れたのです。彼女のミスを待ちましょう！",
  ui_story_7_7_64_dialog_content = "うう…！",
  ui_story_7_7_65_dialog_content = "PlayerName？どうしたの…",
  ui_story_7_7_66_dialog_content = "（頭の中が…刺されたみたいに痛い！？）",
  ui_story_7_7_67_dialog_content = "…",
  ui_story_7_7_68_dialog_content = "…ソラヴァン！",
  ui_story_7_7_69_dialog_content = "…襲です！敵が…私の中に…敵は彼女だけでは…他にも1人…",
  ui_story_7_7_X2_dialog_content = "良く聞こえないよ！ソラヴァン！\nまださっきの座標にいるの！？すぐ助けに戻るよ！",
  ui_story_7_7_X3_dialog_content = "…近くです！どうか…敵が既に侵入しています…それに、彼女だけではありません！",
  ui_story_7_7_A4_dialog_content = "…<color=#FFB400>救援</color>…れば…<color=#FFB400>援に</color>…",
  ui_story_7_7_X4_dialog_content = "ソラヴァンに侵入された！スーモアが、狙いを変えたんだ！",
  ui_story_7_7_X5_dialog_content = "！？",
  ui_story_7_7_X6_dialog_content = "白夜城に入れないとわかって、狙いを変えたということ！？",
  ui_story_7_7_70_dialog_content = "急ぎ救援に向かいましょう。今日は飛空艇を配備していません…\n白夜城のをお借りしてもよろしいでしょうか、カレン？",
  ui_story_7_7_71_dialog_content = "私は…",
  ui_story_7_7_72_dialog_content = "護衛隊長、城主様からまたご命令です。\nその…アップタウンにて復命せよ、と…",
  ui_story_7_7_73_dialog_content = "そんなの後！緊急事態よ、まず彼らを…",
  ui_story_7_7_74_dialog_content = "怖れながら…これはお願いではありません。\nお戻りいただけない場合、四大天使に動いていただくことになります…",
  ui_story_7_7_75_dialog_content = "…えぇっ！？私は隣にいるだけだよ？いきなりふらないでよ。",
  ui_story_7_7_76_dialog_content = "…",
  ui_story_7_7_77_dialog_content = "カレン、お父様にはきっとそれなりの考えがあるのよ。\n今すぐ戻ったほうがいいわ。",
  ui_story_7_7_78_dialog_content = "大丈夫、ソラヴァンのことは啓光の問題よ。\n自分たちの事は自分たちで何とかするわ。",
  ui_story_7_7_79_dialog_content = "待って、僕たちは啓光連邦のものになったつもりは…",
  ui_story_7_7_80_dialog_content = "…",
  ui_story_7_7_81_dialog_content = "…",
  ui_story_7_7_82_dialog_content = "なんだか妥協させられてる気分だわ…巨像の補完が終わるまであとどのくらい？",
  ui_story_7_7_83_dialog_content = "もうすぐよ。心配しないで。やりたいことがあるなら、\nさっさと終わらせてちょうだい。私の忍耐にも限度があるのよ、スーモア。",
  ui_story_7_7_85_dialog_content = "そうね。補完が終わる前に、\nささやきの回廊でやり残したことを片付けておかないと…",
  ui_story_7_7_86_dialog_content = "変わり者のPlayerName。\n殺すのが惜しいと思った空の末裔なんて、これが初めてだわ。",
  ui_story_7_7_87_dialog_content = "必ず来るわ。予感がするの。「絆」だの「道義」だの…",
  ui_story_7_7_A5_dialog_content = "PlayerNameはそういう陳腐な考えに従って、ここに帰ってくる。",
  ui_story_7_7_89_dialog_content = "わざわざ待ったりしないでよ。どれくらいのやつらが無駄口の叩きすぎで\n死んでいったかなんて、今更言う必要もないわよね。",
  ui_story_7_7_90_dialog_content = "早いとこ<color=#FFB400>殺しちゃいなさいよ</color>、スーモア。",
  ui_story_7_7_91_dialog_content = "ソラヴァン、私の古いお友達…",
  ui_story_7_7_92_dialog_content = "<size=45>ちょっと痛いかもしれないわよ！！</size>",
  ui_story_7_8_1_dialog_content = "ソラヴァン…聞こえてる？",
  ui_story_7_8_2_option_content = "感知を試す",
  ui_story_7_8_3_dialog_content = "ソラヴァン…ソラヴァン…",
  ui_story_7_8_4_option_content = "感知を試す",
  ui_story_7_8_5_dialog_content = "…だめだ、やっぱり感知できない！シールドの干渉もあるし…",
  ui_story_7_8_6_dialog_content = "とにかく急いで巨像に戻らなきゃ！",
  ui_story_7_8_7_dialog_content = "私では白夜城の飛空艇を借りる権限がないようです。\nやはり、護衛隊の許可がないとだめでしょうか？",
  ui_story_7_8_8_dialog_content = "一番近い啓光連邦の拠点で借りるのも、かなり時間がかかりそうですし…",
  ui_story_7_8_9_dialog_content = "カレンでもどうしようもなかったんだ…",
  ui_story_7_8_11_dialog_content = "カレンは城主の娘っていう立場があるのに、白夜城の護衛隊長として、\n十分すぎるほどのことをしてくれたわ。",
  ui_story_7_8_12_dialog_content = "そうですね。もしこれ以上命令に背いて、\n飛空艇と一緒に現れたりしたら、さすがに悪い気がします…",
  ui_story_7_8_13_dialog_content = "…まずいわ、また長官の「言ったことが本当になる」特技が…",
  ui_story_7_8_14_dialog_content = "――見て！",
  ui_story_7_8_15_dialog_content = "話を遮るようで悪いんだけど、あそこから急に飛空艇が飛び立ったんだ。",
  ui_story_7_8_16_dialog_content = "なんだかフラフラ飛んでるけど…こっちに向かって来てない…？",
  ui_story_7_8_17_dialog_content = "…？",
  ui_story_7_8_18_dialog_content = "えっ？",
  ui_story_7_8_19_dialog_content = "うそだよね！？カレン、君は…",
  ui_story_7_8_20_dialog_content = "早く！とりあえず乗って！飛空艇を<color=#FFB400>奪って</color>来たわ！",
  ui_story_7_8_21_dialog_content = "う、奪った！？カレン、護衛隊長でしょ！？",
  ui_story_7_8_22_dialog_content = "話はあと！ソラヴァンを助けるんでしょ！？来るの、来ないの？",
  ui_story_7_8_23_dialog_content = "…でも、これなら間に合う！",
  ui_story_7_8_24_dialog_content = "ごめんなさい、PlayerName…遅れてしまって…",
  ui_story_7_8_25_option_content = "ううん、もう十分すぎるほど助けてもらった",
  ui_story_7_8_26_option_content = "それより、飛空艇の操縦もできるなんて",
  ui_story_7_8_27_dialog_content = "そうかもね。これまでは白夜城さえ守れればいいと思っていたけれど…",
  ui_story_7_8_28_dialog_content = "でも今は、他にも守りたいものがあるから。",
  ui_story_7_8_29_dialog_content = "まだそんな冗談が言えるなんて、意外に落ち着いているのね。",
  ui_story_7_8_30_dialog_content = "早くソラヴァンに！…私たちを待ちわびているはずだもの。",
  ui_story_7_8_31_dialog_content = "…私が死を恐れることはありません。\n<color=#FFB400>あの時</color>もそうだったように、あなたを前にして畏縮することはありません。",
  ui_story_7_8_32_dialog_content = "あなたは光の信条に背き、暗黒のかの地に身を寄せるがいいでしょう…",
  ui_story_7_8_A1_dialog_content = "しかし、極光だけがあらゆる命の帰るべき場所。",
  ui_story_7_8_33_dialog_content = "スーモア、たとえ私の意識を破壊しても…\nあなたは絶対にPlayerNameに勝てません！",
  ui_story_7_9_1_dialog_content = "やっぱり、スーモアがついにソラヴァンに手を出したようね！",
  ui_story_7_9_2_dialog_content = "既に暗鬼が多数侵入していますね。空気中に暗力の臭いが漂っています。",
  ui_story_7_9_3_dialog_content = "あいつら、僕のソラヴァンをこんなにして…！",
  ui_story_7_9_4_dialog_content = "9時の方向、来たわよ。うす汚いやからに見つかったわ…",
  ui_story_7_9_5_dialog_content = "迎え撃つわよ！",
  ui_story_7_9_6_dialog_content = "よかった、それほど大きな騒ぎにならなかったわね。\n先手を取れるといいけど。",
  ui_story_7_9_7_dialog_content = "いっそ、最速で直接乗り込む手もあるわ。スーモアに気付かれる前に…",
  ui_story_7_9_8_dialog_content = "む、無理でしょ…",
  ui_story_7_9_9_dialog_content = "カレン、こんな状況なんだし…君まで危険に身をさらすことはないよ。",
  ui_story_7_9_10_dialog_content = "私たちは仲間。あなた達がそう言ったの。違う？",
  ui_story_7_9_11_dialog_content = "それに、強敵が目の前にいるのよ？\nこの槍で刺し貫くまで、うずうずして夜も眠れないわ。",
  ui_story_7_9_12_option_content = "…さすがはカレン",
  ui_story_7_9_13_option_content = "うん、僕たちは仲間だ",
  ui_story_7_9_14_dialog_content = "それってどういう意味かしら？",
  ui_story_7_9_15_dialog_content = "PlayerNameはこう言いたいんじゃない？\nさすがは白夜城の護衛隊長、カレンって。",
  ui_story_7_9_A1_dialog_content = "責任感も強いし、度胸もあるってね。",
  ui_story_7_9_16_dialog_content = "そういうものかしら。でも、お世辞を言ったところで現状は何も変わらないわ。",
  ui_story_7_9_17_dialog_content = "それに、そんなこと言われずとも…一緒に戦うつもりよ。\nだって…<color=#FFB400>仲間</color>だもの。",
  ui_story_7_9_18_dialog_content = "みんな、白夜城の人は近づきがたいって言うけど、カレンは別ね。",
  ui_story_7_9_19_dialog_content = "…おかしな話だと、自分でも思っているわ。私は白夜城の代表であるべきなのか…\nそれとも、私自身でいることが、許されるのかしら？",
  ui_story_7_9_20_dialog_content = "もう行動で結論を出してるよね…？",
  ui_story_7_9_21_dialog_content = "そうかもしれないわ。",
  ui_story_7_9_22_dialog_content = "知ってるわよ、そんなこと。繰り返さずともいいわ。",
  ui_story_7_9_23_dialog_content = "だって、カレンが「違う？」って訊いたから…もう、無駄話はやめておこう。",
  ui_story_7_9_24_dialog_content = "カレン、これから何があるのかわかってるわよね？今までは何とかなったけど…",
  ui_story_7_9_25_dialog_content = "あら、何か悪い予感でも？",
  ui_story_7_9_26_dialog_content = "長官は何も言わないでください…",
  ui_story_7_9_27_dialog_content = "スーモアがどれほど強かろうと、私たちには勝たなければならない理由がある。\n違ったかしら？",
  ui_story_7_9_28_dialog_content = "「<color=#FFB400>守りたいものがある</color>」という物言いは、古臭いかもしれないけれど…",
  ui_story_7_9_A2_dialog_content = "つまるところ、血みどろになってでも戦う意義は、\n大切な人や物を守ることにあるんじゃないかしら？",
  ui_story_7_9_29_dialog_content = "例えばソラヴァンとかね。",
  ui_story_7_9_30_dialog_content = "そう、ソラヴァン…",
  ui_story_7_9_31_dialog_content = "PlayerName、ソラヴァンを感知できる？まずは安否を確認しないと…",
  ui_story_7_9_32_dialog_content = "感知はできないよ。でも、まだ生きてるって信じてる。",
  ui_story_7_9_33_dialog_content = "そういえば、私はまだ巨像とお話できていませんでしたが、\nどんなものなのか、ちょっと気になりますね。",
  ui_story_7_9_A3_dialog_content = "あ、ごめんなさい。いい加減なことを言ってしまいました。",
  ui_story_7_9_34_dialog_content = "それにしてもビビアン…さんまで、どうしてついて来たんですか…",
  ui_story_7_9_35_dialog_content = "カレンと同じ理由ですよ？これだけ引っかきまわされたので、\nこの借りをきちんと返しておきたいのです。",
  ui_story_7_9_36_dialog_content = "よぉ～し、さっさと進みましょう！PlayerName、スーモアはどこかしら？",
  ui_story_7_9_37_dialog_content = "それなら感知できるよ、この寒気の源は…<color=#FFB400>ブリッジ</color>だ！",
  ui_story_7_9_A4_dialog_content = "たぶん、途中にかなりの数の暗鬼もいるよ。みんな、準備はいい？",
  ui_story_7_9_A5_dialog_content = "当然。いつだってこの槍を手放したことはないわ！",
  ui_story_7_12_1_dialog_content = "PlayerName…あなたがこの通信を受け取れるかはわかりませんが…",
  ui_story_7_12_2_dialog_content = "今までご一緒できてとても光栄でした。\nあなたを17年間守り、世界に希望を残すことができて、幸せでした。",
  ui_story_7_12_3_dialog_content = "できれば、<color=#FFB400>救援には来ないで</color>ください。\n繰り返します、<color=#FFB400>救援は不要です</color>――",
  ui_story_7_12_A1_dialog_content = "敵は私たちの予想よりはるかに強大です。",
  ui_story_7_12_4_dialog_content = "あなたの力を蓄えておいてください、PlayerName、\n私がいなくなっても、悲しまずに…",
  ui_story_7_12_5_dialog_content = "巨像は、<color=#FFB400>あなた方のために命を捧げるものなのですから</color>！",
  ui_story_7_13_1_dialog_content = "<size=45>う――！</size>",
  ui_story_7_13_2_dialog_content = "（心臓が…<color=#FFB400>鼓動</color>が落ち着かない…？）",
  ui_story_7_13_3_dialog_content = "あと少しでブリッジに着くわ！敵の動きに気を付けて！",
  ui_story_7_13_4_dialog_content = "まだソラヴァンと連絡できないのですか？",
  ui_story_7_13_5_dialog_content = "今試してるよ。ぼんやりと何かが聞こえる…何度も短い言葉を繰り返してるみたい。",
  ui_story_7_13_6_dialog_content = "でもさっきから、その言葉も聞こえなくなってるんだ、もしかしたら…",
  ui_story_7_13_7_dialog_content = "（まただ――鼓動が乱れてる！？）",
  ui_story_7_13_8_dialog_content = "PlayerName、どうしたの？",
  ui_story_7_13_9_dialog_content = "ここは暗力が濃すぎるのかしら？PlayerNameの体じゃ辛いかもね。",
  ui_story_7_13_10_dialog_content = "何かを感知したみたいね。",
  ui_story_7_13_11_dialog_content = "え？本当に？もしかしてソラヴァン？",
  ui_story_7_13_12_dialog_content = "いえ、違うわ。むしろ、私でさえ感じる…\n<color=#FFB400>空気が急に冷たくなった</color>こと、気付かない？",
  ui_story_7_13_13_dialog_content = "この馴染みがあるようなないような感覚、ひどく傲慢で、吐き気がする気配…",
  ui_story_7_13_14_dialog_content = "…！？",
  ui_story_7_13_15_dialog_content = "ふあぁ〜。",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>スーモア</color>――！</size>",
  ui_story_7_13_17_dialog_content = "PlayerName！スーモアを感知したのね！？彼女はどこ！？",
  ui_story_7_13_18_dialog_content = "…スーモア…ソラヴァンに何を…うう…！",
  ui_story_7_13_19_dialog_content = "やっぱり。しつこいわね、PlayerName…それに、学習能力もゼロみたいね。",
  ui_story_7_13_20_dialog_content = "私がソラヴァンにすることなんてひとつでしょ？\n意識モジュールを壊したのよ。",
  ui_story_7_13_21_dialog_content = "意識モジュール？ソラヴァンの「自我」を司るパーツを！？",
  ui_story_7_13_22_dialog_content = "そうよ、さっき感じたでしょ？\n「心臓が引きちぎられるような、魂まで痛む」感覚。",
  ui_story_7_13_23_dialog_content = "スーモア…！",
  ui_story_7_13_24_dialog_content = "聞き取れなかったら、言い換えてあげるわ…\nあなたのソラヴァンは、<color=#FFB400>もう死んだの</color>。",
  ui_story_7_14_1_dialog_content = "…見失った？",
  ui_story_7_14_2_dialog_content = "あああ！！ごめんなさい！カレンちゃんったら脚が速すぎて、\nささ～っとどこかへ行っちゃったんです～…",
  ui_story_7_14_3_dialog_content = "空を一周したけど、あの怖くて黒い巨像と、\n小さくて白い巨像しか見えませんでしたぁ！",
  ui_story_7_14_4_dialog_content = "白い巨像…PlayerNameか。ふん、子どもの集まりか。",
  ui_story_7_14_5_dialog_content = "黒い巨像の動きに変化は？",
  ui_story_7_14_6_dialog_content = "ありません。相変わらずシールドを攻撃し続けています。\n暗鬼の攻撃も一向に弱まりません。",
  ui_story_7_14_7_dialog_content = "主なエネルギーはシールドの維持に使用し、備蓄の光力を優先的に\n貴族居住区の回復と生活基盤への供給に回せ。",
  ui_story_7_14_A1_dialog_content = "その後、兵力を迅速にダウンタウンの援護に向かわせよ。",
  ui_story_7_14_9_dialog_content = "そ、そ、それじゃあ、カレンちゃんは…？",
  ui_story_7_14_10_dialog_content = "カレンは己の選択をした。それ相応の覚悟もしているはずだ。",
  ui_story_7_14_11_dialog_content = "余の立場として、いかなる理由があろうと、\n今あやつの無意味な「追撃」のために人を割くことはできぬ。",
  ui_story_7_14_12_dialog_content = "それって…",
  ui_story_7_14_13_dialog_content = "…それはそうと、飛空艇が奪えるとはどういうことであろうな…\nあれではよくない影響が出かねん。",
  ui_story_7_14_14_dialog_content = "もし、他の護衛隊員まで勝手に白夜城を飛び立ち、\n<color=#FFB400>あやつを援護しに行く</color>ようなことがあれば…",
  ui_story_7_14_15_dialog_content = "えっと、どうして、ラファエルのことを見ているんですか…？",
  ui_story_7_14_16_dialog_content = "それで、他に何か問題は？",
  ui_story_7_14_17_dialog_content = "あ！えっと…うーん…ラファエル、了解！",
  ui_story_7_14_18_dialog_content = "ラファエル、これで行ってき…あ、違う！失礼…します…",
  ui_story_7_14_19_dialog_content = "待ちくたびれたわよ、ネズミちゃん。あんたたち、自分の家で迷子になるの？",
  ui_story_7_14_20_dialog_content = "黙りなさい、暗鬼。暇があるなら、遺言でも残しておくべきだったわね！",
  ui_story_7_14_21_dialog_content = "何か誤解しているんじゃない？\n今の私は<color=#FFB400>全てのパーツ</color>の力を持っているのよ。",
  ui_story_7_14_X1_dialog_content = "PlayerNameと一緒に無駄死にするぐらいなら、\n白夜城に戻って震えていたほうがマシだったわね！",
  ui_story_7_14_22_dialog_content = "それで、まだ白夜城のシールドを突破できてないの？\n補完が終わってもその程度？",
  ui_story_7_14_23_dialog_content = "お黙り、空の末裔。今の黒い巨像はまだ完全な姿なんかじゃないの…",
  ui_story_7_14_A2_dialog_content = "その時が来たら、あんたたちに「特等席」を用意してあげるわ。",
  ui_story_7_14_X2_dialog_content = "（やっぱり、まだ完全体じゃない…！）",
  ui_story_7_14_X3_dialog_content = "そんな目で見ないでちょうだい、PlayerName。",
  ui_story_7_14_24_dialog_content = "白夜城を攻撃するついでに、あんたたちとの決着がこの手でようやくつけられるんだもの。\nもう待ちきれないわ。",
  ui_story_7_14_25_dialog_content = "ところで、バイス、PlayerName。\nあちらの暗鬼は、そこまですごい実力なのですか？",
  ui_story_7_14_26_dialog_content = "確かに少し手強そうに見えますが、私たちが協力すればわかりませんよ？",
  ui_story_7_14_27_dialog_content = "キシローナ長官もいれば最高でしたね…",
  ui_story_7_14_28_dialog_content = "ムダなこと考えるのね。\n今さら連合軍が来たところで、「あれ」の相手ではないのに…",
  ui_story_7_14_A3_dialog_content = "私の黒い巨像は、こうしている間にもすくすくと育っているの…",
  ui_story_7_14_29_dialog_content = "ポジティブで感心しちゃうわ。\n啓光の人って、みんな根拠のない自信を持っているものなの？",
  ui_story_7_14_30_dialog_content = "あまり長話しないでよ、スーモア。こっちの仕事を複雑にしないで。",
  ui_story_7_14_31_dialog_content = "分かってるわよ、うるさいわね。",
  ui_story_7_14_32_dialog_content = "…",
  ui_story_7_14_33_dialog_content = "どうしたんです？",
  ui_story_7_14_34_dialog_content = "スーモアの後ろにいる方…何となく<color=#FFB400>見覚えがあるような</color>。",
  ui_story_7_14_38_dialog_content = "コソコソしないでよ。遺言なら大きな声で言わないと、聞こえないわ！",
  ui_story_7_14_39_dialog_content = "でもPlayerName、あんたは特別よ…",
  ui_story_7_14_A4_dialog_content = "いつまでも地べたを這いずり回る弱者でいるのはイヤでしょ…あんたは私と同じだもの。",
  ui_story_7_14_40_dialog_content = "こちらへいらっしゃい。正しい道を歩むのよ。",
  ui_story_7_14_41_dialog_content = "それでこそ、運命を変える力を手に入れられるの。",
  ui_story_7_14_42_dialog_content = "運命を変える力って？例えば？",
  ui_story_7_14_43_dialog_content = "見えるもの、寿命、情報、強大な暗力、そして世界の真相。",
  ui_story_7_14_44_dialog_content = "なにより大事なのは、誰かに自分が消されてしまうんじゃないかと怯えなくて済むこと…\n相手を消す側にまわるの、すべてを凌駕する強者にね。",
  ui_story_7_14_46_dialog_content = "他にもあるなら早く言ってよ、時間がないんだ。",
  ui_story_7_14_47_dialog_content = "あんた…！",
  ui_story_7_14_48_dialog_content = "悪いけど、ちっとも興味がないや。",
  ui_story_7_14_49_dialog_content = "意味不明な言葉を並べたてるのが趣味なの？\n自分が何を言ってるのかわかってるの？",
  ui_story_7_14_50_dialog_content = "「誰よりもわかっている」、「運命を変える」、\n「強くなりたい理由は、自分を消そうとする人がいるから」…",
  ui_story_7_14_51_dialog_content = "そんな理由で他人の命を危機にさらせる人の方こそ、\nこの世にいるべきじゃないんじゃない？",
  ui_story_7_14_52_dialog_content = "弱者に会ったら相手を殺し、強者に会ったら命乞いをして力を授けてもらうって？",
  ui_story_7_14_A5_dialog_content = "まるで、理解できないよ。何を根拠に自分の考えが正しいと思ってるの？\n僕が自分と同じだ、なんて。",
  ui_story_7_14_53_dialog_content = "とにかく、君みたいに「世の中で自分が一番正しい」と思ってる奴なんて…",
  ui_story_7_14_54_dialog_content = "啓光連邦か白夜城の病院にでも行って、診てもらうべきだよ。\n脳みその代わりに泥水でも混ざってるんだろうから。",
  ui_story_7_14_55_dialog_content = "…",
  ui_story_7_14_56_dialog_content = "PlayerNameが…まくしたててる…",
  ui_story_7_14_57_dialog_content = "なかなか言うじゃない…？",
  ui_story_7_14_F1_dialog_content = "あっ、そうだ。もうひとつ聞きたいんだけど…\nその力を貰うのに、どれぐらい土下座したの？",
  ui_story_7_14_58_dialog_content = "ふふ…",
  ui_story_7_14_59_dialog_content = "<size=50>ハハハ、アハハハハ！！</size>",
  ui_story_7_14_60_dialog_content = "ほんと、あんたって大したザコだわ！愚か極まりないわね！",
  ui_story_7_14_61_dialog_content = "私を怒らせて、死にたいのかしら？自分は死をも恐れないとでも、言いたいつもり？\n思い通りにはならないわ…",
  ui_story_7_14_63_dialog_content = "あら、ようやく本気を出すのね。",
  ui_story_7_14_A6_dialog_content = "やっぱり、「力」の成長には怒りが必要なものなのね。",
  ui_story_7_14_64_dialog_content = "あんたのことは生かしておいてあげるわ。そして、ゆっくりといたぶるの。\n力を持たないがゆえの屈辱をしっかりと味わいなさい！",
  ui_story_7_14_F2_dialog_content = "そして、私の正しさを思い知るがいいわ！！",
  ui_story_7_14_65_dialog_content = "それはこっちのセリフだ、<color=#FFB400>「空の末裔の裏切者」――スーモア</color>！！",
  ui_story_7_14_66_dialog_content = "さあ！続けなさいよ！どうしてボーッとしてるの！？",
  ui_story_7_14_67_dialog_content = "つ、強すぎる…こんな力…",
  ui_story_7_14_68_dialog_content = "…私はまだ動けるわ。もう一度攻撃を！生きて返すわけにはいかない…",
  ui_story_7_14_69_dialog_content = "落ち着いて！他の…方法を考えなきゃ。",
  ui_story_7_14_70_dialog_content = "ええ、認めたくはありませんが、PlayerNameの言うとおりですね…",
  ui_story_7_14_A7_dialog_content = "まとめてここに閉じ込められてしまうよりは、少人数で来て正解でしたね？",
  ui_story_7_14_71_dialog_content = "今は逃げたくても逃げられませんし…",
  ui_story_7_14_72_dialog_content = "逃げる！？逃げたいの？いいわ、バラバラの紙屑みたいにしてから\nばらまいてあげるっていうのはどう！？",
  ui_story_7_14_73_dialog_content = "白夜城の空にあなたたちの血で雨が降るわ！",
  ui_story_7_14_74_dialog_content = "…補完が終わったわ、スーモア。黒い巨像はもう「<color=#FFB400>完全体</color>」よ。",
  ui_story_7_14_75_dialog_content = "ちょうどいいじゃない？\nこのクズどもを生まれかわったあの子のお祝いに捧げられるもの！",
  ui_story_7_14_76_dialog_content = "あのう…話を中断してごめんなさい。\nさっきからずっと気になっていたのですが…あなたは一体、どなたですか？",
  ui_story_7_14_77_dialog_content = "は！？まだわかってなかったの？",
  ui_story_7_14_78_dialog_content = "いえ、少しどいてください…後ろの方にお話しているのです。そこの…上級暗鬼に。",
  ui_story_7_14_79_dialog_content = "…",
  ui_story_7_14_80_dialog_content = "いえ、暗鬼というよりは<color=#FFB400>光霊</color>に似ていますね。",
  ui_story_7_14_81_dialog_content = "光霊！？",
  ui_story_7_14_82_dialog_content = "体つき、気配、話し方…直感ですけど、あなた、生まれつきの暗鬼ではありませんね。",
  ui_story_7_14_83_dialog_content = "…直感…どうしようもない根拠ね。",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>あなたは誰ですか</color>？教えてください。\nどうしても知る必要があるのです。",
  ui_story_7_14_85_dialog_content = "お断りよ。",
  ui_story_7_14_86_dialog_content = "<size=45>言いなさい！今！</size>",
  ui_story_7_14_87_dialog_content = "…どうしたんだろう、急に取り乱すなんて…？",
  ui_story_7_14_88_dialog_content = "もう一度言うけど、断るわ。だって…",
  ui_story_7_14_89_dialog_content = "私の名前はとっくの昔に「<color=#FFB400>剥奪</color>」されてるんだもの。",
  ui_story_7_14_90_dialog_content = "…",
  ui_story_7_14_91_dialog_content = "この美しい世界で、「<color=#FFB400>啓明の光</color>」の中で、\n名前もない人はどうやったら生きていけるのかしら？",
  ui_story_7_14_92_dialog_content = "…かつては啓光連邦の一員だったということですか。",
  ui_story_7_14_94_dialog_content = "そういうこと。",
  ui_story_7_14_95_dialog_content = "この顔を見なさい。この傷跡を…火に焼かれた跡よ、見えるでしょう？",
  ui_story_7_14_97_dialog_content = "…",
  ui_story_7_14_F3_dialog_content = "どう？",
  ui_story_7_14_98_dialog_content = "何か思い出した？",
  ui_story_7_14_99_dialog_content = "…思い出したというよりは、確証を得たという感じですね。",
  ui_story_7_14_100_dialog_content = "鼻が利くのね。もうずいぶん経つのに、相変わらず、洞察力は衰えていないようね…",
  ui_story_7_14_101_dialog_content = "し…知り合い？",
  ui_story_7_14_102_dialog_content = "知り合いどころか、PlayerName…",
  ui_story_7_14_103_dialog_content = "あの上級暗鬼は、かつて…<color=#FFB400>啓光の仲間</color>だった者です。\nこの惨劇の影の立役者なのでしょう。",
  ui_story_7_14_104_dialog_content = "そんなに意外？",
  ui_story_7_14_A8_dialog_content = "そんなことより、<color=#FFB400>ノラ</color>。いつも私の話が長いって文句ばっかりなのに、\n急にゴキブリどもとおしゃべりし始めるなんて、どういうつもり？",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>ノラ</color>…？",
  ui_story_7_14_109_dialog_content = "ちょっとしたご挨拶よ。\nいいわ、この辺で終わりにしておくから、あなたの好きにして。",
  ui_story_7_14_110_dialog_content = "ついでに、もう一つ…黒い巨像の補完は終わったけど、大量のエネルギーが余ってるの。",
  ui_story_7_14_A9_dialog_content = "使いどころを見つけておいて。",
  ui_story_7_14_111_dialog_content = "目の前に街があるじゃない？",
  ui_story_7_14_112_dialog_content = "傲慢で腐敗して、そのくせシールドが盤石だと思っている――\n光霊の信仰を今日崩してあげるわ！",
  ui_story_7_14_113_dialog_content = "そうはさせないわ！白夜城は決して落とせない。たかが暗鬼に…",
  ui_story_7_14_114_dialog_content = "<size=45>うるさいわよ、光霊！！</size>",
  ui_story_7_14_115_dialog_content = "さあ、私の可愛い巨像…",
  ui_story_7_14_116_dialog_content = "その巨大な身体で、血に染まった瞳で、奴らを震え上がらせるのよ！",
  ui_story_7_14_117_dialog_content = "おわかり！？黒い巨像？黒龍？いいえ、そんな名前ではないわ。",
  ui_story_7_14_118_dialog_content = "そう！これよ！平伏し、拝むがいいわ！これこそが私の<size=45><color=#FFB400>「グリード」</color></size>よ！",
  ui_story_7_14_119_dialog_content = "どういうこと？巨像…何をされたの！？PlayerName、説明しなさい！",
  ui_story_7_14_120_dialog_content = "僕に聞かれてもわからないよ！",
  ui_story_7_14_121_dialog_content = "光力が…消えてる！？いけない。このまま死を待つわけにはいかないわ。",
  ui_story_7_14_122_dialog_content = "動けない…誰か、何か移動手段は？",
  ui_story_7_14_123_dialog_content = "…みなさん、聞いてください。私が時間を稼ぎます。",
  ui_story_7_14_128_dialog_content = "6時の方向が手薄です。そこから逃げてください。飛び降りれば、\n逃げるチャンスは残されています。",
  ui_story_7_14_129_dialog_content = "また会いましょう、バイス、PlayerName、それに、カレン。",
  ui_story_7_14_130_dialog_content = "ビビアン…さん！？",
  ui_story_7_14_131_dialog_content = "<size=50>ふざけたことを――！！</size>",
  ui_story_7_14_133_dialog_content = "（一体…）",
  ui_story_7_14_134_dialog_content = "（何が起きたの？）",
  ui_story_8_1_1_1_dialog_content = "…PlayerName？どこを見てるの？",
  ui_story_8_1_1_2_dialog_content = "ちゃんと私についてこないと、道に迷うわよ。",
  ui_story_8_1_1_3_dialog_content = "ほら、手を握って。",
  ui_story_8_1_1_4_dialog_content = "どうしたの？そんな顔して。\n白夜城のパーティーに一緒に参加するって言ったでしょ？",
  ui_story_8_1_1_5_dialog_content = "あそこに屋台が出てるわ！寄ってみましょうよ！",
  ui_story_8_1_1_6_option_content = "ここは…どこ？",
  ui_story_8_1_1_7_dialog_content = "忘れたの？ここは白夜城よ。",
  ui_story_8_1_1_8_option_content = "何が起きたの？",
  ui_story_8_1_1_9_dialog_content = "他に何があるっていうのよ。\n年に一度のお祭りなんだから、お祝いに決まってるでしょ！",
  ui_story_8_1_1_10_dialog_content = "ちょっと、どうしたの？私をからかってるんじゃないでしょうね？",
  ui_story_8_1_1_11_dialog_content = "いい加減にしないと、怒っちゃうわよ！こんなふうに…う～、ぷんぷん！",
  ui_story_8_1_1_12_option_content = "バイス、なんだかヘンだよ",
  ui_story_8_1_1_13_dialog_content = "そう？別にヘンなところなんてないよ！私はあなたのバイスちゃんでしょ！",
  ui_story_8_1_1_14_dialog_content = "もう。いいから、早く来て。いい加減にしてくれないと、本当に怒るわよ。",
  ui_story_8_1_1_15_option_content = "…君は誰？",
  ui_story_8_1_1_16_dialog_content = "…え？バイスよ。じゃなきゃ、誰だっていうの？",
  ui_story_8_1_1_17_dialog_content = "どうしてそんな変なこと聞くの？ほらほら、早く。ぐずぐずしてると怒っちゃうよ。",
  ui_story_8_1_1_18_dialog_content = "…",
  ui_story_8_1_1_19_dialog_content = "何の音…？",
  ui_story_8_1_1_20_dialog_content = "えっ？何か聞こえたの？",
  ui_story_8_1_1_21_dialog_content = "ここはおかしいよ、バイス。それに、なんだか気持ちが悪い。これは…",
  ui_story_8_1_1_22_dialog_content = "気のせいでしょ、PlayerName。私が一緒にいるのに不安なの？ほらほら、信じてよ。",
  ui_story_8_1_1_23_dialog_content = "それに…どんな疑問にも私がぜんぶ答えてあげるわ。\nだから、まずは私の手を握って。ね？",
  ui_story_8_1_1_24_dialog_content = "教えてあげる、すべてを。",
  ui_story_8_1_1_25_dialog_content = "…PlayerName。",
  ui_story_8_1_1_26_dialog_content = "過去、未来、あなたの知りたいことを全部…",
  ui_story_8_1_1_27_dialog_content = "私たちは一緒に、「明日」を迎えるの。",
  ui_story_8_1_1_28_dialog_content = "だから、私を一人にしないで…約束したでしょ？",
  ui_story_8_1_1_29_dialog_content = "…これでも聞こえないか？ずいぶん心地よく眠っているようだ。\nPlayerName！",
  ui_story_8_1_1_30_option_content = "うん、絶対に一人にしないよ",
  ui_story_8_1_1_31_dialog_content = "よかった！やっとわかってくれた、受け入れてくれたのね…\nじゃあ約束して。永遠に離れないって…",
  ui_story_8_1_1_32_dialog_content = "空の末裔の肉体を捨てて、抱きしめるのよ。真の力を！",
  ui_story_8_1_1_33_option_content = "さようなら、君はバイスじゃない",
  ui_story_8_1_1_34_dialog_content = "戻ってきなさい！どうして、どうしてどうして！！なんて、愚かな空の末裔なの！！",
  ui_story_8_1_1_35_dialog_content = "多くの人が夢見るチャンスなのよ、わからないの！？\n愚かね、愚かすぎて哀れだわ！",
  ui_story_8_1_1_36_dialog_content = "聞こえるかい？その危険で甘美な幻から帰ってくるんだ…",
  ui_story_8_1_1_37_dialog_content = "さぁ、「旧夢」の導きに従って。それが真実を教えてくれる…",
  ui_story_8_1_1_38_dialog_content = "キュー！！",
  ui_story_8_1_1_39_dialog_content = "（ううっ――！痛い、何だ！？）",
  ui_story_8_1_1_42_dialog_content = "（何かが体の中から飛び出してきたぞ！？）",
  ui_story_8_1_1_43_dialog_content = "（あれは何だったんだろう？どうして…）",
  ui_story_8_1_1_44_dialog_content = "グォォ――！",
  ui_story_8_1_1_45_dialog_content = "キュー！！",
  ui_story_8_1_1_47_dialog_content = "あっ、君は――「キュリー」！ビビアンさんと一緒にいた！",
  ui_story_8_1_1_48_dialog_content = "キュー！！！",
  ui_story_8_1_1_49_dialog_content = "君のご主人様はどこ？…それに、バイスは？",
  ui_story_8_1_1_50_dialog_content = "さっきのあれは、僕の身体の中から…一体何だったんだ…",
  ui_story_8_1_1_51_dialog_content = "うっ、頭が…くっ、痛すぎる。どこかにぶつけたかな？",
  ui_story_8_1_1_52_dialog_content = "キュー！",
  ui_story_8_1_1_53_dialog_content = "かわいそうに、全身傷だらけだ…君もみんなとはぐれたの？",
  ui_story_8_1_1_54_dialog_content = "みんなはどうなってるかな…",
  ui_story_8_1_1_55_dialog_content = "ふざけたことを――！！",
  ui_story_8_1_1_58_dialog_content = "いたた…あのあと起きた事を、まったく思い出せないみたいだ。",
  ui_story_8_1_1_59_dialog_content = "バイスたちの様子は…",
  ui_story_8_1_1_60_dialog_content = "PlayerName！",
  ui_story_8_1_1_61_dialog_content = "バイス！？",
  ui_story_8_1_1_62_dialog_content = "シーッ！そうよ、声を抑えて！",
  ui_story_8_1_1_63_dialog_content = "大丈夫？あちこちから暗力のオーラを感じる！さっき…",
  ui_story_8_1_1_64_dialog_content = "わかってる。私は平気よ、安心して！あなたは？怪我をしてないか見せて！",
  ui_story_8_1_1_65_option_content = "気分はあんまりよくないかも",
  ui_story_8_1_1_66_dialog_content = "僕、なんだか…ヘンなんだ。\n怪我はしてないけど、体中がとても…重い感じがする。",
  ui_story_8_1_1_67_dialog_content = "頭もハッキリしないし…一体ここは何なの？",
  ui_story_8_1_1_68_dialog_content = "…わからないの？ここは「グリード」の内部よ、PlayerName。",
  ui_story_8_1_1_69_option_content = "わからない",
  ui_story_8_1_1_70_dialog_content = "…わからないんだ。さっき目が覚めて…そうだ、夢を見たんだよ、悪夢！夢の中で…",
  ui_story_8_1_1_71_dialog_content = "そう…君がいた。でも君っぽくない感じがして…\nいや！あれは絶対に君じゃない、そう…",
  ui_story_8_1_1_F1_dialog_content = "そうだ、他にもう一人いたような…",
  ui_story_8_1_1_72_dialog_content = "夢？夢に私が出てきたの？\nでも、私っぽくなくなかったのね？もう一人って誰かしら？",
  ui_story_8_1_1_F2_dialog_content = "どうしてこんなことに…よくわからないよ。",
  ui_story_8_1_1_73_dialog_content = "その後は？目が覚めたらここにいたの？",
  ui_story_8_1_1_F3_dialog_content = "そう、ここで目が覚めたんだ。",
  ui_story_8_1_1_74_dialog_content = "…なるほどね。暗力があなたの脳に干渉したせいかも。\nだってここは「グリード」の内部だもの…",
  ui_story_8_1_1_75_option_content = "一体、ここはどこ？",
  ui_story_8_1_1_76_dialog_content = "ここは「グリード」の内部よ。",
  ui_story_8_1_1_77_dialog_content = "こういう形態の巨像を見るのは、私も初めてだわ。\nいえ、もう巨像とは言えないかも…",
  ui_story_8_1_1_78_dialog_content = "見て、そこらじゅうに暗力に侵食された痕跡があるの。\n言ってみれば、ここは暗鬼の楽園ね。",
  ui_story_8_1_1_79_dialog_content = "ここへ来る途中にもたくさん暗鬼に遭遇したわ。まだ、バレてないといいけど…",
  ui_story_8_1_1_80_dialog_content = "ま、待って…いま…",
  ui_story_8_1_1_81_dialog_content = "ここがグリードの内部だって言った？",
  ui_story_8_1_1_82_dialog_content = "そうよ。あなたがスーモアに捕まってここにいるのを知って、それから…",
  ui_story_8_1_1_83_dialog_content = "あなたを追いかけてここまで来たの。",
  ui_story_8_1_1_84_dialog_content = "ここに！？どうして来たの？危険すぎるよ！",
  ui_story_8_1_1_88_dialog_content = "あなたを助けるためよ！あなたが私たちを助けて、\n自分だけソラヴァンに取り残されるだなんて、そんなこと…",
  ui_story_8_1_1_89_dialog_content = "待って、落ち着こう…一体何が起きたの？",
  ui_story_8_1_1_90_dialog_content = "いや…何が起こったにしても、\nやっぱり一人で来たなんてまずいよ！危険すぎる！！",
  ui_story_8_1_1_91_dialog_content = "わかってる！でもじっとしてたって何もできないでしょ？",
  ui_story_8_1_1_92_dialog_content = "あなたがまだ生きてるかもしれないって思ったら…私に何ができるかって考えたら…",
  ui_story_8_1_1_93_dialog_content = "君の気持ちはわかるよ、バイス。でも…",
  ui_story_8_1_1_94_dialog_content = "今さらそんなこと言ってもしょうがないわ、PlayerName！\nもう来ちゃったんだから！",
  ui_story_8_1_1_95_dialog_content = "今は一緒にこの状況を何とかする方法を考えましょう！\nほら、シャキッとして！",
  ui_story_8_1_1_96_dialog_content = "キュー！",
  ui_story_8_1_1_97_dialog_content = "はぁ…キュリー、君もバイスに何か言ってやってよ。",
  ui_story_8_1_1_98_dialog_content = "それで、一体何が起きたの？何も覚えてないんだ。\n思い出そうとすると頭がズキズキ痛んで…",
  ui_story_8_1_1_99_dialog_content = "こんな場所でじっとしてないで、まずは行動しましょう！歩きながら話すわ。",
  ui_story_8_1_1_100_dialog_content = "あの時、ビビアン長官が隙を見て私たちを逃がそうとしたの。そしたらスーモアが…",
  ui_story_8_1_1_101_dialog_content = "…みなさん気を付けてください。私が時間を稼ぎます。",
  ui_story_8_1_1_103_dialog_content = "6時の方向が手薄です。そこから逃げてください。飛び降りれば、\n逃げるチャンスは残されています。",
  ui_story_8_1_1_104_dialog_content = "また会いましょう、バイス、PlayerName、それに、カレン。",
  ui_story_8_1_1_105_dialog_content = "ビビアンさん！？",
  ui_story_8_1_1_106_dialog_content = "ふざけたことを――！！",
  ui_story_8_1_1_107_dialog_content = "あなたの相手は私です！！",
  ui_story_8_1_1_108_dialog_content = "意外と…やるじゃない。虫けらのくせに！",
  ui_story_8_1_1_109_dialog_content = "…",
  ui_story_8_1_1_110_dialog_content = "少し真面目にやろうかしらね…まったく、不愉快だわ。",
  ui_story_8_1_1_111_dialog_content = "そこのあんた達！こそこそと、どこへ逃げるつもり！？",
  ui_story_8_1_1_112_dialog_content = "急ごう！と、飛び降りるんだ！",
  ui_story_8_1_1_113_dialog_content = "この高さ…でも、仕方ないわね！いくわよ！",
  ui_story_8_1_1_114_dialog_content = "私の手を握って！一緒に…",
  ui_story_8_1_1_115_dialog_content = "グォォ――！",
  ui_story_8_1_1_116_dialog_content = "放して！",
  ui_story_8_1_1_117_dialog_content = "PlayerName！！",
  ui_story_8_1_1_118_dialog_content = "（引っ張られる！！）",
  ui_story_8_1_1_119_dialog_content = "力が出ない…どうしよう、一緒に行かなきゃ…",
  ui_story_8_1_1_120_dialog_content = "…",
  ui_story_8_1_1_121_option_content = "早く行くんだ！",
  ui_story_8_1_1_122_dialog_content = "！？",
  ui_story_8_1_1_123_dialog_content = "PlayerName！",
  ui_story_8_1_1_124_dialog_content = "た、高すぎるわ！！落っこちて死んじゃう！",
  ui_story_8_1_1_125_dialog_content = "バランスを保って、バイス！落下するときは必ず…",
  ui_story_8_1_1_126_dialog_content = "カ――レ――ン――ちゃん！！",
  ui_story_8_1_1_127_dialog_content = "つかまえた！！",
  ui_story_8_1_1_128_dialog_content = "ラファエル…？あなたどうして…くっ、痛っ！",
  ui_story_8_1_1_129_dialog_content = "この飛空艇…カレン、増援を呼んだの？",
  ui_story_8_1_1_130_dialog_content = "えへへ…んー、増援ってことになるかな！ラファエルはみんなを迎えにきたの！",
  ui_story_8_1_1_131_dialog_content = "間に合ってよかったぁ…もしあと2秒遅れてたら…",
  ui_story_8_1_1_132_dialog_content = "ギッ――",
  ui_story_8_1_1_133_dialog_content = "何の音？",
  ui_story_8_1_1_134_dialog_content = "あれ？私の下から何かが…",
  ui_story_8_1_1_135_dialog_content = "キュー！！",
  ui_story_8_1_1_136_dialog_content = "キュリー！？",
  ui_story_8_1_1_137_dialog_content = "ごめんごめん！踏んづけちゃってたのね！",
  ui_story_8_1_1_138_dialog_content = "キュー！",
  ui_story_8_1_1_139_dialog_content = "この子、バイスちゃんのペット？",
  ui_story_8_1_1_140_dialog_content = "いいえ、ビビアン長官のよ。",
  ui_story_8_1_1_141_dialog_content = "あれ？その長官って人はどこにいったの？それに、空の末裔もいたよね？",
  ui_story_8_1_1_142_dialog_content = "それは…",
  ui_story_8_1_1_143_dialog_content = "…",
  ui_story_8_1_1_144_dialog_content = "ラファエル、今はその事について話している時ではないわ。事態が急変したの。\n急いで帰還して、城主様に報告しないと。",
  ui_story_8_1_1_145_dialog_content = "PlayerNameのおかげで、やっとの思いで脱出するチャンスを得たのだから…",
  ui_story_8_1_1_146_dialog_content = "なにがなんでも反撃する方法を考えないと。",
  ui_story_8_1_1_147_dialog_content = "カレン、何か作戦はあるの？",
  ui_story_8_1_1_148_dialog_content = "戻ってあの人を説得する。「ダモクレス」を使うのよ。",
  ui_story_8_1_1_149_dialog_content = "！？",
  ui_story_8_1_1_150_dialog_content = "スーモアに対抗できるのはあれだけよ。それ以外にない。",
  ui_story_8_1_1_151_dialog_content = "「ダモクレス」…もう10年は起動してないよね？殿下が許してくれるかな？",
  ui_story_8_1_1_152_dialog_content = "私が同意させるわ。グリードを止められるのは、もはや…",
  ui_story_8_1_1_153_dialog_content = "でもPlayerNameは…",
  ui_story_8_1_1_154_dialog_content = "白夜城全体の存亡がかかっているの。私にも選択肢はない…\n選択肢はないのよ、バイス。",
  ui_story_8_1_1_155_dialog_content = "…",
  ui_story_8_1_1_156_dialog_content = "どうしたの？何をするつもり？",
  ui_story_8_1_1_157_dialog_content = "ソラヴァンに戻るつもりなの？",
  ui_story_8_1_1_158_dialog_content = "そうよ…",
  ui_story_8_1_1_159_dialog_content = "ごめんなさい、カレン。\nPlayerNameとビビアン長官を見捨てるなんて私にはできない。",
  ui_story_8_1_1_160_dialog_content = "バイス、あなた…",
  ui_story_8_1_1_161_dialog_content = "あなたの言いたいことはわかるわ、カレン！\nでも仲間を見捨てるなんて、私には…私にはできないの…",
  ui_story_8_1_1_162_dialog_content = "落ち着いて、バイス。今戻っても、危険なだけよ！",
  ui_story_8_1_1_164_dialog_content = "まさか、PlayerNameがせっかく命がけで\n作ってくれたチャンスを無駄にするつもり？",
  ui_story_8_1_1_165_dialog_content = "危険だってことくらいわかっているわ、カレン！…方法は自分で考えるから。",
  ui_story_8_1_1_166_dialog_content = "方法って何？飛空艇は一つしかないのよ！",
  ui_story_8_1_1_167_dialog_content = "そ、そうだよ…",
  ui_story_8_1_1_168_dialog_content = "バイスちゃんは飛べないでしょ…？やっぱりまずは…",
  ui_story_8_1_1_169_dialog_content = "…",
  ui_story_8_1_1_170_dialog_content = "キュリー、お願い！",
  ui_story_8_1_1_171_dialog_content = "キュー？",
  ui_story_8_1_1_172_dialog_content = "…キュー！？",
  ui_story_8_1_1_173_dialog_content = "キュリーと一緒なら戻れるわ。",
  ui_story_8_1_1_174_dialog_content = "その子が、あなたを乗せて移動できると思ってるの？",
  ui_story_8_1_1_175_dialog_content = "カレン、確かにちょっと重いかもしれないけど…でも、キュリーは強いから！",
  ui_story_8_1_1_176_dialog_content = "キュー！",
  ui_story_8_1_1_177_dialog_content = "わかってる、キュリー。あなたも戻ってご主人様を助けたいよね？",
  ui_story_8_1_1_180_dialog_content = "行くなら今のうちよ。ここからなら、戻ってもそこまで遠くないわ。",
  ui_story_8_1_1_181_dialog_content = "カレン…",
  ui_story_8_1_1_182_dialog_content = "あなたの考えを変えられない事くらい、わかってるわよ。私だって同じだもの。\n私たちは自分の理念に忠実だから。",
  ui_story_8_1_1_183_dialog_content = "でも心しておいて。ここまでのあなたはずっと「運」が良かっただけ。",
  ui_story_8_1_1_184_dialog_content = "ソラヴァンを起動して逃げられた時も、\n危険を犯してガルーを救出できたこともね。",
  ui_story_8_1_1_185_dialog_content = "でも、もし…もし、今度こそ「運」に愛想を尽かされてしまったら…",
  ui_story_8_1_1_186_dialog_content = "…私はPlayerNameを信じてる。\nもう一度困難を克服できるって信じてるわ。",
  ui_story_8_1_1_187_dialog_content = "努力すれば、必ず奇跡は起こるって信じてるから。",
  ui_story_8_1_1_188_dialog_content = "あなたの楽観的な考え方には、たまに感心させられるわ、バイス。",
  ui_story_8_1_1_189_dialog_content = "行きなさい。私は頑固者を説得しないといけないから、\nあなたと一緒にはいけない。",
  ui_story_8_1_1_190_dialog_content = "PlayerNameのことは頼んだわよ、バイス！",
  ui_story_8_1_1_191_dialog_content = "あなたも気をつけてね、カレン！もしあれを本当に起動できたら、\nきっとスーモアに一矢報いることができるわ！",
  ui_story_8_1_1_192_dialog_content = "「一矢」じゃ済ませないわよ。今はただ、あなた達が脱出できることを願うわ。",
  ui_story_8_1_1_193_dialog_content = "じゃあ、また後でね、カレン。",
  ui_story_8_1_1_194_dialog_content = "ええ、また会いましょう、バイス。",
  ui_story_8_1_1_195_dialog_content = "『そっちも取り外せ。急ぐんだ』",
  ui_story_8_1_1_196_dialog_content = "『役に立ちそうなものはすべてバラせ！補完後の巨像には大量の建材が必要だ！』",
  ui_story_8_1_1_197_dialog_content = "『…オイ！聞いてるのか！？』",
  ui_story_8_1_1_198_dialog_content = "…グゥアアア！",
  ui_story_8_1_1_200_dialog_content = "声を上げないで。この部屋にはあなた一人だけよ。\n他の暗鬼は？みんなソラヴァンから出ていったの？",
  ui_story_8_1_1_201_dialog_content = "PlayerNameの大切な家をこんな風に壊すなんて、絶対に許さない。",
  ui_story_8_1_1_202_dialog_content = "『こ…光霊…クソッ、早くあのお方に…』",
  ui_story_8_1_1_203_dialog_content = "悪いわね。一思いにとどめを刺してあげるべきなのかもしれないけど、\nどうしても知りたいことがあるのよ。",
  ui_story_8_1_1_204_dialog_content = "ウガァッ――！？",
  ui_story_8_1_1_205_dialog_content = "私の言葉を理解できないのはわかってるけど…",
  ui_story_8_1_1_206_dialog_content = "…とっても大事な人たち、\nPlayerNameとビビアン長官の行方を知りたいの。",
  ui_story_8_1_1_207_dialog_content = "『オマエは空の末裔の仲間？逃げなかったのか？バカな女め…』",
  ui_story_8_1_1_208_dialog_content = "何言ってるかわからないわ。ああもう、このままじゃ時間のムダね…",
  ui_story_8_1_1_209_dialog_content = "公用語がわからないって言うなら…そうだ、筆談があるわ！",
  ui_story_8_1_1_210_dialog_content = "？",
  ui_story_8_1_1_211_dialog_content = "こうやって描けば…",
  ui_story_8_1_1_212_dialog_content = "この人は、どこ？",
  ui_story_8_1_1_213_dialog_content = "『…あの空の末裔を探しにきたのか！』",
  ui_story_8_1_1_214_dialog_content = "『あの空の末裔は確か…いや』",
  ui_story_8_1_1_215_dialog_content = "ちょっと、どこを見てるの？",
  ui_story_8_1_1_216_dialog_content = "『教えてやるものか！ゴミめ、虫けらめ！あのお方の計画を邪魔するなら…』",
  ui_story_8_1_1_217_dialog_content = "ぐはっ…！",
  ui_story_8_1_1_218_dialog_content = "グリードの方…かな。",
  ui_story_8_1_1_219_dialog_content = "キュ、キュー…",
  ui_story_8_1_1_220_dialog_content = "大丈夫？まだいける？私をつかんでこんな遠くまで来たんだもの、辛いよね。",
  ui_story_8_1_1_221_dialog_content = "キュ…！",
  ui_story_8_1_1_222_dialog_content = "ごめんね。でもあともう1回お願いしないといけないの。",
  ui_story_8_1_1_223_dialog_content = "グリードに行かなきゃ！\nPlayerNameとビビアン長官があそこにいるかもしれないのよ。",
  ui_story_8_1_1_224_dialog_content = "キュー！？",
  ui_story_8_1_1_225_dialog_content = "それで…潜入してきたってこと？本当にそんなことができたの？",
  ui_story_8_1_1_226_dialog_content = "まぁ、信じられないわよね。でも、本当にキュリーのおかげでここにたどり着いたのよ。",
  ui_story_8_1_1_227_dialog_content = "キュー…",
  ui_story_8_1_1_228_dialog_content = "キュリーも、かなり疲れてるみたいだけど…",
  ui_story_8_1_1_229_dialog_content = "本当に、キュリーはよく頑張ったわ。戻ったらしっかりとねぎらってあげなきゃ！",
  ui_story_8_1_1_230_option_content = "じゃあ、急いでここを離れよう",
  ui_story_8_1_1_231_dialog_content = "キュー！",
  ui_story_8_1_1_232_dialog_content = "まだビビアン長官が見つかってないの、PlayerName。",
  ui_story_8_1_1_233_dialog_content = "もしまだいけそうなら、一緒についてきて…",
  ui_story_8_1_1_234_dialog_content = "私、長官も助けたいの！",
  ui_story_8_1_1_235_option_content = "でも、ビビアン長官は見ていないよ",
  ui_story_8_1_1_236_dialog_content = "キュー…",
  ui_story_8_1_1_237_dialog_content = "たぶん長官もここに捕まっているはずよ。だから、探し出さないと。",
  ui_story_8_1_1_238_dialog_content = "スーモアが何を企んでいるのかわからないけど、絶対に長官を見捨てたりはしないわ！",
  ui_story_8_1_1_239_dialog_content = "そうかもしれない。調子も良くなってきたから、一緒に行こう。",
  ui_story_8_1_1_240_dialog_content = "えぇ、行きましょう！",
  ui_story_8_1_1_241_dialog_content = "キュー！",
  ui_story_8_2_1_1_dialog_content = "先生、すみません…もう一度見せてください！",
  ui_story_8_2_1_2_dialog_content = "また感知に失敗しちゃいました。やっぱりうまくいきません…",
  ui_story_8_2_1_3_dialog_content = "先生？先生？",
  ui_story_8_2_1_4_dialog_content = "ちょっと？",
  ui_story_8_2_1_5_dialog_content = "何か考え事でもしてるの？",
  ui_story_8_2_1_6_dialog_content = "…",
  ui_story_8_2_1_7_dialog_content = "集中しなさい。もうすぐ証明できるんでしょ？",
  ui_story_8_2_1_8_dialog_content = "無駄話が多いわね。",
  ui_story_8_2_1_9_dialog_content = "自分が何をすべきか、あなたに言われなくてもわかってるわよ。",
  ui_story_8_2_1_10_dialog_content = "ふぅん。",
  ui_story_8_2_1_11_dialog_content = "…",
  ui_story_8_2_1_12_dialog_content = "私がPlayerNameを生かしておいたのは、\nつまらない「証明」とかいうもののためではないわ、ノラ。",
  ui_story_8_2_1_13_dialog_content = "私は…",
  ui_story_8_2_1_14_dialog_content = "…いや、説明しても理解できないでしょうね。",
  ui_story_8_2_1_15_dialog_content = "あなたがあの啓光のやつを生かしておいたのと同じよ。",
  ui_story_8_2_1_16_dialog_content = "同じじゃないわ。私はあなたとは違う。",
  ui_story_8_2_1_17_dialog_content = "私と啓光はとうの昔に関係が切れているのよ。\nあなたはまだ空の末裔のままみたいだけど。あははっ。",
  ui_story_8_2_1_18_dialog_content = "あなた、殺されたいの！？誰が空の末裔ですって！？",
  ui_story_8_2_1_19_dialog_content = "落ち着きなさいよ。こんなおしゃべりを続けるつもりはないわ。\nつまらないもの。",
  ui_story_8_2_1_20_dialog_content = "あなたね！",
  ui_story_8_2_1_21_dialog_content = "もう行くわ。",
  ui_story_8_2_1_22_dialog_content = "どこに？",
  ui_story_8_2_1_23_dialog_content = "あいつに「同じ力」を与えておいたわ。\nあなた達がもう一度「同胞」になれるといいわね。",
  ui_story_8_2_1_24_dialog_content = "どういうこと？そんなことをしろと言った覚えはないわよ。",
  ui_story_8_2_1_25_dialog_content = "チッ、わけがわからないわ…",
  ui_story_8_2_1_26_dialog_content = "あいつ、いったい何がしたいの？初めて会った時からずっとこうよ！",
  ui_story_8_2_1_27_dialog_content = "協力するどころか、私が白夜城に集中しないといけない時に、邪魔をしてくるなんて…",
  ui_story_8_2_1_28_dialog_content = "スーモア様、私がここに留まり、あなたに協力しているのは、\nノラ様に仰せつかったからです…",
  ui_story_8_2_1_29_dialog_content = "ノラ様への言動にはお気をつけを。",
  ui_story_8_2_1_30_dialog_content = "…ふん。完全に見放されたわけでもなさそうね。",
  ui_story_8_2_1_31_dialog_content = "ここはまるっきり…メチャクチャだ…",
  ui_story_8_2_1_32_dialog_content = "PlayerName、どう？うまくいった？",
  ui_story_8_2_1_33_dialog_content = "うまくいったよ。この巨像を感知できた。けど…理解できないんだ。",
  ui_story_8_2_1_F1_dialog_content = "いや、理解できないわけじゃなくて…",
  ui_story_8_2_1_34_dialog_content = "そもそもこの巨像には、自分の意識モジュールが\n存在しないみたいなんだ。空っぽだよ。",
  ui_story_8_2_1_35_dialog_content = "気を付けて、警報が鳴るかもしれないわ…",
  ui_story_8_2_1_36_dialog_content = "大丈夫だよ、バイス。わかってるから。",
  ui_story_8_2_1_37_dialog_content = "感知で警報を阻止してるんだ。\nこうすれば、僕たちの行動の形跡を隠すことができる。",
  ui_story_8_2_1_F2_dialog_content = "感知能力ってそんな使い方もできるのね？",
  ui_story_8_2_1_F3_dialog_content = "うん、感知で「潜る」ことができるようになってからね…とにかく、小さな感知力で\n色々できるようになったってことだよ。",
  ui_story_8_2_1_38_dialog_content = "ビビアン長官の居場所は感知できた？",
  ui_story_8_2_1_F4_dialog_content = "ごめん、むやみに感知を強めることはできないんだ。",
  ui_story_8_2_1_F5_dialog_content = "ここは「グリード」の内部だから、直接接触することで感知するんだけど…",
  ui_story_8_2_1_39_dialog_content = "感知能力で広範囲を捜索すると、たぶんスーモアに見つかってしまうと思う。",
  ui_story_8_2_1_40_dialog_content = "なるほどね。やっぱり自分たちで探すしかないってことか…",
  ui_story_8_2_1_41_dialog_content = "あなたの状態はどう？ここの暗力には慣れてきた？",
  ui_story_8_2_1_42_dialog_content = "うん、まったく問題ないよ。もう頭も痛くない。",
  ui_story_8_2_1_43_dialog_content = "むしろ元気が湧いてくるっていうか…長い間眠っていたからかな…",
  ui_story_8_2_1_44_dialog_content = "そうなの？変ね…ささやきの回廊の時にはどう見ても暗力のせいで辛そうだったのに…",
  ui_story_8_2_1_45_dialog_content = "キュー！",
  ui_story_8_2_1_46_dialog_content = "キュリー！なにか嗅ぎ取ったの？",
  ui_story_8_2_1_47_dialog_content = "…くしゅん！",
  ui_story_8_2_1_48_dialog_content = "キュー…",
  ui_story_8_2_1_49_dialog_content = "暗力が濃すぎるわね。キュリーでも耐えられないみたい…",
  ui_story_8_2_1_50_dialog_content = "遅かったな。",
  ui_story_8_2_1_51_dialog_content = "君は…！？",
  ui_story_8_2_1_52_dialog_content = "思ったより時間はかかったが、運命の輪は邪魔されることなく、\n変わらず巡っているようだ。",
  ui_story_8_2_1_53_dialog_content = "空の末裔よ、こっちだ。望むものは、この通路の終わりにある…",
  ui_story_8_2_1_54_dialog_content = "君は誰？光霊…それとも暗鬼？",
  ui_story_8_2_1_55_dialog_content = "静かに…そんなことは重要ではない。\n大事なのはこれから起こること、そして僕たちが探し求めている…",
  ui_story_8_2_1_56_dialog_content = "真理だ。",
  ui_story_8_2_1_57_dialog_content = "PlayerName、どうしたの？急に顔色が悪くなったみたい。",
  ui_story_8_2_1_58_dialog_content = "ぼ、僕、変なものを見ちゃったかも…",
  ui_story_8_2_1_59_dialog_content = "白い服を着て、カバンを手に持った男の人だった。あっちへ進めって…",
  ui_story_8_2_1_60_dialog_content = "えっ？男の人なんて、どこにいるの？",
  ui_story_8_2_1_F6_dialog_content = "それは…もしかしたら感知の力かも…あっちに進めって、たぶん信じてもいいと思う。",
  ui_story_8_2_1_F7_dialog_content = "あっちって…大雑把過ぎて、結局どっちに行けばいいの？",
  ui_story_8_2_1_61_dialog_content = "うーん、グリードの内部構造には詳しくないから、\n今まで進んできたルートを合わせると…",
  ui_story_8_2_1_62_dialog_content = "そうだ、簡単な地図を描くわ！",
  ui_story_8_2_1_63_dialog_content = "さっきの紙がまだ使えるはず…",
  ui_story_8_2_1_64_dialog_content = "バイス、ここに描いてある絵ってなに？",
  ui_story_8_2_1_65_dialog_content = "気にしないで！な、何でもないの！",
  ui_story_8_2_1_66_dialog_content = "この子供みたいな顔って…",
  ui_story_8_2_1_68_dialog_content = "わ、私はただ、アイツからあなたの居場所を聞き出そうとしただけよ！",
  ui_story_8_2_1_F8_dialog_content = "これ、僕だったの？",
  ui_story_8_2_1_69_dialog_content = "確かに画力がないのは認めるわ…でも、ちゃんと役に立ったんだから！",
  ui_story_8_2_1_70_dialog_content = "本題に戻るわよ！\nまだ覚えてるうちに、これまででわかった地図を描いてみるわね…",
  ui_story_8_2_1_72_dialog_content = "（この落書きみたいな絵、暗鬼に通じたんだ…）",
  ui_story_8_2_1_73_dialog_content = "ここに…罫線を追加して、それから…",
  ui_story_8_2_1_74_dialog_content = "できた！",
  ui_story_8_2_1_75_dialog_content = "（ひどい地図ができても笑っちゃだめだよね。せっかく苦労して描いてくれた地図なんだし…）",
  ui_story_8_2_1_76_dialog_content = "…って、なにこれ、すごい！！工学的構造図だね！？",
  ui_story_8_2_1_77_dialog_content = "普通でしょ。時間がないから、適当に描いただけよ。",
  ui_story_8_2_1_78_dialog_content = "適当に！？人の顔はめちゃくちゃだったのに、\n地図ならこんな精密なものが描けるの！？",
  ui_story_8_2_1_79_dialog_content = "言ったじゃない。私は啓光でそういうことを勉強していたの。",
  ui_story_8_2_1_80_dialog_content = "それに、ソラヴァンの整備点検にだってこういう知識が必要だもの。",
  ui_story_8_2_1_81_dialog_content = "キュー！",
  ui_story_8_2_1_82_dialog_content = "キュリー、どうしたの？",
  ui_story_8_2_1_83_dialog_content = "キュー！キュー！",
  ui_story_8_2_1_84_dialog_content = "こっちなの？この方向は…",
  ui_story_8_2_1_85_dialog_content = "さっき、あの男の人が指していた方向…？",
  ui_story_8_2_1_86_dialog_content = "この子、長官の気配を嗅ぎ取ったのかも！\n行こう、PlayerName！",
  ui_story_8_2_1_87_dialog_content = "（さっきの人は、敵じゃないってことかな…？）",
  ui_story_8_2_1_88_dialog_content = "この先にはもっと多くの暗鬼がいるはず。さっさと片付けちゃいましょ！",
  ui_story_8_2_1_89_dialog_content = "戦闘用意――！",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>白夜城・アップタウン</color>",
  ui_story_8_2_2_2_dialog_content = "ダモクレスを…",
  ui_story_8_2_2_3_dialog_content = "起動させるだと…？",
  ui_story_8_2_2_5_dialog_content = "そうです。現状を解決するにはそれしかありません！",
  ui_story_8_2_2_6_dialog_content = "カレン、自分が何を言っているのか、分かっているのか？",
  ui_story_8_2_2_7_dialog_content = "アレを起動するには、三者協議による承認が必要なのだ！\nそこを考えないとしても…",
  ui_story_8_2_2_F1_dialog_content = "あれがどれほどのエネルギーを食うのか知っているのか！？",
  ui_story_8_2_2_8_dialog_content = "シールドの維持に必要なエネルギーをすべて吸い尽くすのだぞ！\n白夜城全体が停止してしまう！",
  ui_story_8_2_2_9_dialog_content = "…分かっています。",
  ui_story_8_2_2_10_dialog_content = "まったく、どうかしているな！",
  ui_story_8_2_2_11_dialog_content = "オットー。",
  ui_story_8_2_2_12_dialog_content = "…ふん。",
  ui_story_8_2_2_13_dialog_content = "城主様は、スーモアと黒き巨像の威力をその目で見ておられないでしょう。\n私はあそこから…脱出してきたのです！",
  ui_story_8_2_2_14_dialog_content = "完全体の黒い巨像を阻止できる者などおりません。\nしかも、彼女には他の仲間がいるのです！",
  ui_story_8_2_2_15_dialog_content = "背水の陣を敷いてでも、戦わなければ！シールドの庇護も永遠には続きません。\n遅かれ早かれ、突破されてしまうでしょう。",
  ui_story_8_2_2_16_dialog_content = "負傷したのか？",
  ui_story_8_2_2_17_dialog_content = "えっ？",
  ui_story_8_2_2_18_dialog_content = "お前は負傷したのか、カレン？",
  ui_story_8_2_2_19_dialog_content = "ラファエルは、あのとき全員が危険な状態だったと言っていた。\nお前があそこまで打ち負かされた様子は初めて見た、とな。",
  ui_story_8_2_2_20_dialog_content = "…",
  ui_story_8_2_2_21_dialog_content = "私は平気です、城主様。ご心配なく。",
  ui_story_8_2_2_22_dialog_content = "そうか。",
  ui_story_8_2_2_23_dialog_content = "お前たちはどう見る？",
  ui_story_8_2_2_24_dialog_content = "私の意見は伝えたはずだ。\n白夜城を停止させ、危険にさらすなど言語道断。",
  ui_story_8_2_2_25_dialog_content = "法廷は？",
  ui_story_8_2_2_26_dialog_content = "私は段取りに従うまでです。\nいかなる提案であろうとも、三者協議さえ通せば施行できます。",
  ui_story_8_2_2_27_dialog_content = "しかし、そうでなければ、法廷は断固として制止するでしょう。\nその対象が誰であっても変わりません。",
  ui_story_8_2_2_28_dialog_content = "では、手短に決議を執るとしよう。",
  ui_story_8_2_2_29_dialog_content = "オットー、元老院代表。そなたは否決であろうな。",
  ui_story_8_2_2_30_dialog_content = "当然ですな。",
  ui_story_8_2_2_31_dialog_content = "イルンティ、法廷の裁判長。そなたの決定は？",
  ui_story_8_2_2_32_dialog_content = "棄権いたします。",
  ui_story_8_2_2_33_dialog_content = "そうか。",
  ui_story_8_2_2_34_dialog_content = "最後に、このソルラド。白夜城城主と大貴族の名において決定を下す…",
  ui_story_8_2_2_35_dialog_content = "余は否決する。",
  ui_story_8_2_2_36_dialog_content = "――！！",
  ui_story_8_2_2_37_dialog_content = "否決が2票、棄権が1票。法廷は「施行しない」ものと見なします。",
  ui_story_8_2_2_38_dialog_content = "やはり、お前の父上は白夜城を守ることの何たるかを、\nよく分かっていらっしゃるぞ、カレン。",
  ui_story_8_2_2_39_dialog_content = "お戯れはおやめください！\n三者協議は、軽々しく口頭で済ませるものなのですか！？",
  ui_story_8_2_2_40_dialog_content = "緊急事態においては、定められた形式を通す必要はありません。\n法廷が参席し、その場で承認すれば決議は有効と見なされます。",
  ui_story_8_2_2_41_dialog_content = "秩序をお守りください、カレン。",
  ui_story_8_2_2_42_dialog_content = "私は…",
  ui_story_8_2_2_43_dialog_content = "聞いた？あれを使うにはエネルギーを集中させなくてはならないそうよ。\nシールドも使えなくなるとか…",
  ui_story_8_2_2_44_dialog_content = "…そんな事をしたら自殺行為じゃない？少なくともシールドさえあれば…",
  ui_story_8_2_2_45_dialog_content = "…まったく、城主様の娘だというのに、何を言っているのかわかってるのかしら…",
  ui_story_8_2_2_46_dialog_content = "…",
  ui_story_8_2_2_47_dialog_content = "カレン。",
  ui_story_8_2_2_48_dialog_content = "…",
  ui_story_8_2_2_49_dialog_content = "こうべを上げよ、カレン・ド・ソルラド！",
  ui_story_8_2_2_50_dialog_content = "ここは白夜城である。巨像でのままごと遊びとは違うのだ！",
  ui_story_8_2_2_51_dialog_content = "そのようなやり方を、余の城に持ち込むでない。よいな？",
  ui_story_8_2_2_52_dialog_content = "…",
  ui_story_8_2_2_53_dialog_content = "わかったかと聞いておる！！",
  ui_story_8_2_2_54_dialog_content = "はい、城主様。",
  ui_story_8_2_2_55_dialog_content = "事態がより明確になるまでは、シールドを維持するのが得策だ。ダモクレスの起動など…",
  ui_story_8_2_2_56_dialog_content = "まったくもって道理にかなわぬ。",
  ui_story_8_2_2_57_dialog_content = "事態は混乱を極めているというのに、規則も何もあったものではない！\nお前は幼き頃と何も変わっていないな、カレン。教訓を学ぼうとしない！",
  ui_story_8_2_2_58_dialog_content = "え…？",
  ui_story_8_2_2_59_dialog_content = "昔、猫を助けるためにツリーハウスから落ちたことがあったな。\nそれ以上愚かな振る舞いをすることはあるまいと思っていたが…",
  ui_story_8_2_2_60_dialog_content = "だがお前は、まったく成長していないようだ。",
  ui_story_8_2_2_61_dialog_content = "（ツリーハウス…？）",
  ui_story_8_2_2_62_dialog_content = "最終的に猫を助けられたのだから、お前の決断は正しかったのかもしれない。\nだが、それが何だというのだ？",
  ui_story_8_2_2_63_dialog_content = "そんなことに、他人の忠告も聞かず、脚の骨を折るほどの価値があるのか？",
  ui_story_8_2_2_64_dialog_content = "（…！？）",
  ui_story_8_2_2_65_dialog_content = "答えよ、あの行動に価値などあったのか！？",
  ui_story_8_2_2_66_dialog_content = "ソルラド、どうした？なぜいまそんな話を持ち出す？",
  ui_story_8_2_2_67_dialog_content = "余はお主に問うたか？オットー・トロイ。",
  ui_story_8_2_2_68_dialog_content = "…",
  ui_story_8_2_2_69_dialog_content = "…はい、あります。",
  ui_story_8_2_2_70_dialog_content = "価値はあると思います、父上。",
  ui_story_8_2_2_71_dialog_content = "もうよい。やはりお前は手に負えぬな。",
  ui_story_8_2_2_72_dialog_content = "あの猫と同じように、いつまでも己の象牙の塔に囚われているがよい。",
  ui_story_8_2_2_73_dialog_content = "…",
  ui_story_8_2_2_74_dialog_content = "ひえぇ…さっきの城主様、怖かったぁ…",
  ui_story_8_2_2_75_dialog_content = "しかも、どうして急に昔の事を言いだしたんだろう？変な感じだよね。\nちょっとビックリしちゃった…",
  ui_story_8_2_2_77_dialog_content = "えーっ！？カレンちゃん、なんで笑ってるの？よけいに怖いよ！！",
  ui_story_8_2_2_78_dialog_content = "だって、分かったんだもの…あの人の言おうとしていた事が。",
  ui_story_8_2_2_79_dialog_content = "えっ？",
  ui_story_8_2_2_80_dialog_content = "ツリーハウス、それに猫…ふふっ、小さい頃そういうことがあったのは事実よ。",
  ui_story_8_2_2_81_dialog_content = "ただ…",
  ui_story_8_2_2_82_dialog_content = "…その時、私は猫を助けられなかったの。",
  ui_story_8_2_2_83_dialog_content = "じゃあ、城主様の記憶違いってこと？うーん…それとも…",
  ui_story_8_2_2_84_dialog_content = "あ、もしかして…",
  ui_story_8_2_2_85_dialog_content = "城主様、お歳のせいでボケちゃった？",
  ui_story_8_2_2_86_dialog_content = "…わからないなら、いいわ。一緒に来てちょうだい、仕事の時間よ。",
  ui_story_8_2_2_87_dialog_content = "あはっ！よーし、どこに行くの？",
  ui_story_8_2_2_88_dialog_content = "…",
  ui_story_8_2_2_89_dialog_content = "ダモクレスのコントロールルームよ。",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>グリード内部</color>",
  ui_story_8_3_1_2_dialog_content = "フフン…フン…♪",
  ui_story_8_3_1_3_dialog_content = "ああ、すまない。少し我を忘れていたよ。",
  ui_story_8_3_1_4_dialog_content = "さあ、こっちへ進んで…僕もここを「観光」するのは初めてなんだ…",
  ui_story_8_3_1_5_dialog_content = "キュー！",
  ui_story_8_3_1_6_dialog_content = "（キュリーはビビアンさんの匂いをたどれるから、きっと正しい方向がわかっているはず…）",
  ui_story_8_3_1_7_dialog_content = "さあ進もう、こっちで合ってるはずだよ。",
  ui_story_8_3_1_8_dialog_content = "…",
  ui_story_8_3_1_9_dialog_content = "ん？どうしてそんな目で見てくるの…",
  ui_story_8_3_1_10_dialog_content = "あなた、本当に大丈夫？\n私でもここの暗力に耐えられないくらいなのに、あなたは平気なの？",
  ui_story_8_3_1_11_dialog_content = "うん、本当に大丈夫だよ。",
  ui_story_8_3_1_12_dialog_content = "確かに変な話だけど、ここの暗力にはほとんど抵抗を感じないんだ。むしろ逆に…",
  ui_story_8_3_1_13_dialog_content = "いい匂いがするっていうか？",
  ui_story_8_3_1_14_dialog_content = "えっ…",
  ui_story_8_3_1_15_dialog_content = "ただ、ちょっと身体がかゆいんだよね。アレルギーかな？",
  ui_story_8_3_1_16_dialog_content = "かゆい？どこなの、見てあげましょうか？",
  ui_story_8_3_1_17_dialog_content = "平気だよ、背中のほう。服の上からかけば別に問題ないから…",
  ui_story_8_3_1_18_dialog_content = "それより…",
  ui_story_8_3_1_19_option_content = "バイス、さっき少し耐えられないって言った？",
  ui_story_8_3_1_20_dialog_content = "やっぱり、自分よりも他人を心配するのね…",
  ui_story_8_3_1_21_dialog_content = "私は大丈夫。ちょっと辛いけど、この前スーモアと戦った時よりはずっと楽だから。",
  ui_story_8_3_1_22_dialog_content = "それに、私だってここに来るまでに成長したんだからね、PlayerName。",
  ui_story_8_3_1_23_dialog_content = "どんな難関も、きっとうまく乗り越えていけるわ！",
  ui_story_8_3_1_24_dialog_content = "うん、絶対に大丈夫だよ。スーモアを倒すまでは負けられないからね。",
  ui_story_8_3_1_25_dialog_content = "ふふ、その意気ね、PlayerName。",
  ui_story_8_3_1_26_option_content = "カレンは今ごろどうしてるかな",
  ui_story_8_3_1_27_dialog_content = "もう白夜城に戻っているでしょうね。",
  ui_story_8_3_1_28_dialog_content = "今ごろカレンも、私たちとは違う方法でスーモアを倒すために戦っているはず…",
  ui_story_8_3_1_29_dialog_content = "それで、「ダモクレス」って一体何なの？強力な武器とか？",
  ui_story_8_3_1_30_dialog_content = "実際に見たことはないけど、留学中にその「威力」は聞いたことがあるわ…",
  ui_story_8_3_1_31_dialog_content = "決定的な瞬間でないと絶対に使用できない、奥の手と言えるわね。",
  ui_story_8_3_1_32_dialog_content = "つまり、君も知らないってことだね…",
  ui_story_8_3_1_33_option_content = "ビビアン…さんはどこにいるんだろう",
  ui_story_8_3_1_34_dialog_content = "わからないわ。でもキュリーの反応からして、この先にいるはずよ！",
  ui_story_8_3_1_35_dialog_content = "きっと私たちを長官のもとに連れていってくれるわ。",
  ui_story_8_3_1_36_dialog_content = "ビビアンさんがいなかったら、脱出する機会さえなかったからね。",
  ui_story_8_3_1_37_dialog_content = "あなたも色々してくれたわ、PlayerName。最終的にあんなことまで…",
  ui_story_8_3_1_38_dialog_content = "2人を押したこと？",
  ui_story_8_3_1_39_dialog_content = "あれは本能だったのかもしれない。無意識っていうか…\nそんな事をしたことすら、忘れるところだったよ…",
  ui_story_8_3_1_40_dialog_content = "今後は二度とあんなふうに…「自己犠牲」的な行動はしないでほしいわ。",
  ui_story_8_3_1_41_dialog_content = "前にガルー長官と一緒だったときもそう。自分だけで向かっていくなんて…",
  ui_story_8_3_1_42_dialog_content = "キュー！！",
  ui_story_8_3_1_43_dialog_content = "ごめんなさい。キュリーが、慌ててるみたいね。少し急ぎましょう。",
  ui_story_8_3_1_44_dialog_content = "PlayerName、とにかく自分の身体の様子にはもっと気を付けてよね。",
  ui_story_8_3_1_46_dialog_content = "わかった。心配しないで…",
  ui_story_8_6_1_1_dialog_content = "ま、まぶしい…",
  ui_story_8_6_1_3_option_content = "ダメだ！隠れなきゃ！",
  ui_story_8_6_1_4_dialog_content = "PlayerName？そんな隅に隠れて何をしてるの？",
  ui_story_8_6_1_5_dialog_content = "何してるの？早く来て！",
  ui_story_8_6_1_6_dialog_content = "キュー！",
  ui_story_8_6_1_7_dialog_content = "ご、ごめん。ここ、まぶしすぎて…もうちょっとゆっくり…",
  ui_story_8_6_1_8_dialog_content = "まぶしい？普通の部屋だけど。",
  ui_story_8_6_1_9_dialog_content = "この程度で…ねぇ、光が怖いわけじゃないわよね？",
  ui_story_8_6_1_10_dialog_content = "わからない。うーん…少しは目が慣れてきたみたいだ。",
  ui_story_8_6_1_11_option_content = "くっ…痒い…",
  ui_story_8_6_1_12_dialog_content = "目は良くなったけど、また背中が痒いの？",
  ui_story_8_6_1_13_dialog_content = "うん。もしかして僕、病気かな…？",
  ui_story_8_6_1_14_dialog_content = "ちょっと休みましょう。ここは敵もいないみたいだし、少し態勢を立て直して…",
  ui_story_8_6_1_15_dialog_content = "キュー！",
  ui_story_8_6_1_16_dialog_content = "キュリー、どこに行くの？",
  ui_story_8_6_1_17_dialog_content = "キュー！キュー！",
  ui_story_8_6_1_18_dialog_content = "ビビアン長官！？この部屋のむこうにいるの？",
  ui_story_8_6_1_19_dialog_content = "キュ――！キュー！キュー！",
  ui_story_8_6_1_20_dialog_content = "キュリー！ちゃんと扉を開ける方法を考えるから、体当たりしないで。見つかっちゃうわ…",
  ui_story_8_6_1_21_dialog_content = "ん？この匂い…この匂いは！？",
  ui_story_8_6_1_22_dialog_content = "バイス、危ない！",
  ui_story_8_6_1_23_dialog_content = "グギギ…！",
  ui_story_8_6_1_24_dialog_content = "こ…こいつら、君に向かってきてるみたい！",
  ui_story_8_6_1_25_dialog_content = "当たったわ！他にも何体かいる。他の暗鬼に知らされたらまずいわ！",
  ui_story_8_6_1_26_dialog_content = "残ってるのも始末しよう！",
  ui_story_8_6_1_27_dialog_content = "よし、私に任せて。速戦即決よ！",
  ui_story_8_6_2_1_dialog_content = "よかった！大きな騒ぎにはならなかったみたい…",
  ui_story_8_6_2_2_dialog_content = "見逃したやつがいないか確認を…",
  ui_story_8_6_2_3_dialog_content = "！？後ろっ…",
  ui_story_8_6_2_4_dialog_content = "ウォオオオ！",
  ui_story_8_6_2_5_dialog_content = "（僕を飛び越えていった！？）",
  ui_story_8_6_2_6_dialog_content = "はぁ…やっぱり、ここの暗力のせいで判断力が鈍るみたい。一匹見逃すなんてね。",
  ui_story_8_6_2_7_dialog_content = "バイス、いま…",
  ui_story_8_6_2_8_dialog_content = "今の暗鬼、僕を飛び越えていったんだ。いや、僕をまったく見てなかった！",
  ui_story_8_6_2_9_dialog_content = "…えぇ、そうみたいね。さっきだけじゃない。ここに来る途中のやつらも、\nまるであなたに興味がないみたいだった。",
  ui_story_8_6_2_10_dialog_content = "これじゃまるで…",
  ui_story_8_6_2_11_dialog_content = "…あなたを敵と思っていないみたい。",
  ui_story_8_6_2_12_dialog_content = "…",
  ui_story_8_6_2_13_dialog_content = "どうして？",
  ui_story_8_6_2_14_dialog_content = "わからないわ。PlayerName、今の気分はどう？具合が悪いところとかはない？",
  ui_story_8_6_2_15_dialog_content = "わからないよ、バイス…",
  ui_story_8_6_2_16_dialog_content = "キュー！",
  ui_story_8_6_2_17_dialog_content = "わかったわ、キュリー。でもPlayerNameの身体が…",
  ui_story_8_6_2_18_dialog_content = "大丈夫だよ。ビビアンさんがこの中にいるなら、話の続きは助け出してからにしよう！",
  ui_story_8_7_1_A1_dialog_content = "うーん…お父様…お母様…？",
  ui_story_8_7_1_A2_dialog_content = "村はもう…攻め落とされたんじゃなかったの？無事でよかった…",
  ui_story_8_7_1_1_dialog_content = "そうだ、酔いしれるがいい…\nそれはお前に最も甘美で、なによりもリアルな夢を与えてくれる…",
  ui_story_8_7_1_2_dialog_content = "穢れなく純粋な、根源からの印…『母の恩寵』。",
  ui_story_8_7_1_3_dialog_content = "肉体の潜在能力を引き出し、唯一無二の力として凝縮する。",
  ui_story_8_7_1_4_dialog_content = "なにより重要なことは、お前が我々の一員となること…",
  ui_story_8_7_1_5_dialog_content = "早く、もっと早く…根源の殿堂へと来るがいい。",
  ui_story_8_7_1_6_dialog_content = "あなたの手の中に何があるのか知らないけど、そこから離れなさい、暗鬼！",
  ui_story_8_7_1_7_dialog_content = "光霊？いつの間に入ってきた？",
  ui_story_8_7_1_8_dialog_content = "長官！聞こえますか！",
  ui_story_8_7_1_9_dialog_content = "う…ん…",
  ui_story_8_7_1_10_dialog_content = "よかった、まだ生きてる！",
  ui_story_8_7_1_11_dialog_content = "仲間を救うため、身の程をわきまえず現れたか…",
  ui_story_8_7_1_12_dialog_content = "それとも、日蝕に感化されてわざわざやってきたのか？",
  ui_story_8_7_1_A3_dialog_content = "我が名は「コンバーター」、喜んでお前たちを導いてやろう。",
  ui_story_8_7_1_13_dialog_content = "「感化」って、お前みたいな醜い暗鬼になること？悪いけど、ごめんだよ。",
  ui_story_8_7_1_14_dialog_content = "『空の末裔！もうすでにこちら側のはずでは！？』",
  ui_story_8_7_1_15_dialog_content = "何を言ってるのかわからないよ。公用語で話して。",
  ui_story_8_7_1_16_dialog_content = "なぜ「あの方」からの知らせが無かったのだ？\n警報すらも鳴っていない。お前たち、一体どのような手を使って…",
  ui_story_8_7_1_17_dialog_content = "そういう技だよ。ある程度なら、僕はグリードとも感知ができる。これでわかる？",
  ui_story_8_7_1_18_dialog_content = "大きな騒ぎでも起こさない限り、警報を切って痕跡を隠すぐらいは余裕なんだ。",
  ui_story_8_7_1_19_dialog_content = "まあ、予想外ではあるが…問題ない、私の嗅覚が確かなら…",
  ui_story_8_7_1_20_dialog_content = "お前はもうすぐ我々の仲間となるからな、空の末裔。",
  ui_story_8_7_1_21_dialog_content = "…どういう意味？",
  ui_story_8_7_1_F1_dialog_content = "PlayerName、惑わされちゃダメよ。",
  ui_story_8_7_1_22_dialog_content = "さっき、長官に何をしようとしたの？その光るものはいったい何？",
  ui_story_8_7_1_23_dialog_content = "『つまらぬ問いだ』",
  ui_story_8_7_1_24_dialog_content = "私の我慢強さを試すつもり？今は謎かけをしてる暇なんてないの。",
  ui_story_8_7_1_25_dialog_content = "あれは恩寵！母上より賜りし恩寵だ！",
  ui_story_8_7_1_26_dialog_content = "お前たちに我が主のお心がわかるか？\n一瞬のうちに塵にしてやることもできたものを、こうして生かしてやっているのだ。",
  ui_story_8_7_1_27_dialog_content = "それどころか、お前たちを楽園へと誘われた。何の代償もなく、優しく力をお授けになった。",
  ui_story_8_7_1_28_dialog_content = "光栄！なんたる光栄か！！",
  ui_story_8_7_1_29_dialog_content = "力を授ける？どういうこと！？",
  ui_story_8_7_1_30_dialog_content = "すぐにお前もわかるだろう。無駄なことを問うな。",
  ui_story_8_7_1_31_dialog_content = "まさか…",
  ui_story_8_7_1_32_dialog_content = "そんな戯言に耳を貸すな。早くやつを倒すんだ、まだ間に合う！",
  ui_story_8_7_1_33_dialog_content = "また君か！どこにいるの？",
  ui_story_8_7_1_34_dialog_content = "傍観者の席、一等席だよ。そんなに気になるかい？",
  ui_story_8_7_1_35_dialog_content = "まだ空の末裔として生きたいのなら、やるんだ。一刻も早く！",
  ui_story_8_7_1_36_dialog_content = "『広がった視野の中で、かつての無知と恥に震え上がるがいい！』",
  ui_story_8_7_1_37_dialog_content = "くっ――！",
  ui_story_8_7_1_38_dialog_content = "バイス、体内で何かが動いてる！いや、これはエネルギー…",
  ui_story_8_7_1_39_dialog_content = "ある種のエネルギーが…",
  ui_story_8_7_1_40_dialog_content = "PlayerName！！落ち着いて、落ち着くのよ！",
  ui_story_8_7_1_41_dialog_content = "うああっ…あ、頭が割れそうだ――",
  ui_story_8_7_1_43_dialog_content = "つ、強すぎる！PlayerName、しっかりして！！",
  ui_story_8_7_1_44_option_content = "分かってる…意識を…落ち着かせないと…",
  ui_story_8_7_1_45_dialog_content = "もう遅い。すべては形成されたのだ。",
  ui_story_8_7_1_46_dialog_content = "「シード」はすでに根を下ろした。私にはその鋭くうなる声が聞こえるぞ…",
  ui_story_8_7_1_47_dialog_content = "母上のもとに、また新たなる貴重な魂が増えるのだ！",
  ui_story_8_7_1_48_option_content = "意識を…落ち着かせる…",
  ui_story_8_7_1_49_dialog_content = "キュー！！",
  ui_story_8_7_1_51_dialog_content = "キュリー、一緒に…",
  ui_story_8_7_1_52_dialog_content = "哀れなものだな。空の末裔の援護がなければ、貴様らなど泥人形に等しい。",
  ui_story_8_7_1_53_dialog_content = "うっ！",
  ui_story_8_7_1_54_dialog_content = "PlayerName…",
  ui_story_8_7_1_55_dialog_content = "どうした？",
  ui_story_8_7_1_56_dialog_content = "こんなところで負けている場合ではないだろう？",
  ui_story_8_7_1_57_dialog_content = "あなたは空の末裔…その意識を支配することなど、誰にもできはしない！！",
  ui_story_8_7_1_58_option_content = "（意識を落ち着かせるんだ！！！）",
  ui_story_8_7_1_59_dialog_content = "…？",
  ui_story_8_7_1_60_dialog_content = "危なかった…自分を見失うところだったよ。",
  ui_story_8_7_1_61_dialog_content = "なにっ！強制的に転化を止めた！？",
  ui_story_8_7_1_62_dialog_content = "黙ってよ、うるさいな…",
  ui_story_8_7_1_63_dialog_content = "さっきからベラベラと、おかげで頭が割れそうだ…",
  ui_story_8_7_1_64_dialog_content = "ありえん！そんなことが！どうやって「シード」の制御を逃れた！？",
  ui_story_8_7_1_65_dialog_content = "さっきから…おしゃべりばかり…",
  ui_story_8_7_1_66_dialog_content = "声が大きすぎて、スーモアにも聞こえちゃいそうだよ。",
  ui_story_8_7_1_67_dialog_content = "まあ、今は何を叫んでも関係ないけどね…グリードをもう一度感知できた。",
  ui_story_8_7_1_F2_dialog_content = "巨像をコントロールしたんだ。この部屋は完全にシャットアウトされてる。",
  ui_story_8_7_1_68_dialog_content = "どれだけ絶叫しても、「母上」とやらには届かないよ。",
  ui_story_8_7_1_69_dialog_content = "PlayerName…よかった、元に戻ったのね。",
  ui_story_8_7_1_70_dialog_content = "うん、もう大丈夫。こいつの相手をまかせっきりにして、ごめん。",
  ui_story_8_7_1_71_dialog_content = "まだ頭は痛いけど…しばらくは耐えられそうだよ。",
  ui_story_8_7_1_73_dialog_content = "無知で愚かな者どもめ、何も知らぬ冒涜者が！お前も「彼の地」へ行けるのだぞ！",
  ui_story_8_7_1_74_dialog_content = "遅かれ早かれ、お前も必ずや我々の一員となるというのに！！",
  ui_story_8_7_1_75_dialog_content = "バイス、あいつを黙らせて。",
  ui_story_8_7_1_76_dialog_content = "ビビアンさんが僕たちを待ってるんだ…",
  ui_story_8_7_1_77_dialog_content = "よ～し！",
  ui_story_8_7_2_1_dialog_content = "長官！",
  ui_story_8_7_2_2_dialog_content = "キュー！キュー！",
  ui_story_8_7_2_4_dialog_content = "う…ん…",
  ui_story_8_7_2_5_dialog_content = "長官、ここまで弱ってるなんて…すみません、来るのが遅すぎました。",
  ui_story_8_7_2_6_dialog_content = "他人の心配をしている暇があるなら、自分の身体を気にしたらどうだい…",
  ui_story_8_7_2_7_dialog_content = "誰！？",
  ui_story_8_7_2_8_dialog_content = "君か…バイスも知ってるはずだよ…さっき案内をしてくれた人だ。",
  ui_story_8_7_2_9_dialog_content = "あっ、もしかしてこの人があなたの言っていた「白いカバン」の人？",
  ui_story_8_7_2_10_dialog_content = "僕は敵じゃない。見てのとおり光霊だ。",
  ui_story_8_7_2_11_dialog_content = "「ファウスト」と呼んでくれ。僕は真理に仕えるもの…",
  ui_story_8_7_2_12_dialog_content = "「真理」？なんか、怪しいんだけど…",
  ui_story_8_7_2_13_dialog_content = "真理は永遠に変わることのない正しい道理であり、万物の旋律さ。\n心配する必要はない。あなた達を助けに来たんだ。",
  ui_story_8_7_2_14_dialog_content = "そんな自己紹介じゃ、一体どういう人なのか全然わからないよ。",
  ui_story_8_7_2_15_dialog_content = "理解する必要はないよ。今は自分の身体のことに集中した方がいい…",
  ui_story_8_7_2_16_dialog_content = "あなたの体内にある「シード」が、間もなく芽吹こうとしている。",
  ui_story_8_7_2_17_dialog_content = "…その「シード」って一体？",
  ui_story_8_7_2_18_dialog_content = "説明する前に処理をしておこう。",
  ui_story_8_7_2_19_dialog_content = "PlayerName、服を脱ぐんだ。",
  ui_story_8_7_2_20_dialog_content = "えっ？",
  ui_story_8_7_2_21_dialog_content = "すまないが、今は恥ずかしがっている場合じゃない。僕の言う通りにするんだ。",
  ui_story_8_7_2_22_dialog_content = "身体に違和感のある場所があるだろう？",
  ui_story_8_7_2_23_dialog_content = "そういわれてみれば、背中がくすぐったいような気がするかも…",
  ui_story_8_7_2_24_dialog_content = "つまり、背中ということか？",
  ui_story_8_7_2_25_dialog_content = "僕を信じるんだ。悪いようにはしない。",
  ui_story_8_7_2_26_option_content = "わ、わかったよ…",
  ui_story_8_7_2_27_dialog_content = "…",
  ui_story_8_7_2_28_dialog_content = "下に着ている服もだ。",
  ui_story_8_7_2_29_dialog_content = "PlayerName、後ろを向いてた方がいいかしら？",
  ui_story_8_7_2_30_dialog_content = "別にただ背中を見せるだけだ。さぁ、もう一刻も猶予は無い…",
  ui_story_8_7_2_31_option_content = "わ、わかったって…脱げばいいんでしょ…",
  ui_story_8_7_2_32_dialog_content = "そんな…",
  ui_story_8_7_2_33_dialog_content = "やっぱり…",
  ui_story_8_7_2_34_dialog_content = "どうしたの？僕の背中に何があるの？",
  ui_story_8_7_2_35_dialog_content = "こんな状況でも正常な意識を保てるとは…すごいと言うべきか、鈍いと言うべきか。",
  ui_story_8_7_2_36_dialog_content = "だから、一体何が！？",
  ui_story_8_7_2_37_dialog_content = "バイス、「それ」を掘り出せるかい？",
  ui_story_8_7_2_38_dialog_content = "皮膚の下にまで食い込んでいそうだ。\n手荒になるが、まだ位置がつかめるうちにやってしまおう。",
  ui_story_8_7_2_39_dialog_content = "…私、あなたに名前を教えた覚えはないわよ。",
  ui_story_8_7_2_40_dialog_content = "あぁ、だがそれは重要ではない。特に今はね。",
  ui_story_8_7_2_41_dialog_content = "僕から敵意を感じるかい？",
  ui_story_8_7_2_42_dialog_content = "…",
  ui_story_8_7_2_43_dialog_content = "…わかったわ。無理やり取り出してもいいのね。何とかなると思う。",
  ui_story_8_7_2_44_dialog_content = "ねぇってば！僕の身体にいったい…",
  ui_story_8_7_2_45_dialog_content = "動くんじゃない！",
  ui_story_8_7_2_46_dialog_content = "バイス、頼んだよ。",
  ui_story_8_7_2_47_dialog_content = "…ちょっと痛いかもよ、PlayerName。",
  ui_story_8_7_2_48_dialog_content = "うわあっ――！？",
  ui_story_8_7_2_50_dialog_content = "（い、痛すぎて声も出ない！これが「ちょっと」だって！？）",
  ui_story_8_7_2_51_dialog_content = "バイス、下がるんだ！近くにいてはいけない…",
  ui_story_8_7_2_52_dialog_content = "これはとても危険だ…そして人を惑わせる…",
  ui_story_8_7_2_53_option_content = "これは一体なに？",
  ui_story_8_7_2_54_dialog_content = "「シード」…少なくとも暗鬼たちはそう呼んでいる。",
  ui_story_8_7_2_55_dialog_content = "資料によっては、「力の根源」や「母の接吻」、「飛翔の印」という別名でも記されている。",
  ui_story_8_7_2_56_dialog_content = "だが、結局すべて同じものだ。暗鬼はこれによって、強力かつ唯一無二の力を手に入れる。",
  ui_story_8_7_2_57_dialog_content = "何より重要なのは、この「シード」が他の生物を暗鬼へと変貌させる\n唯一の方法だということ…",
  ui_story_8_7_2_58_dialog_content = "変貌させるって…まさか、グスドのときと同じ？",
  ui_story_8_7_2_59_dialog_content = "それから…スーモアも。",
  ui_story_8_7_2_60_dialog_content = "誰のことか僕にはわからないが、光に属するはずの者が暗影の力を使ったのなら…",
  ui_story_8_7_2_61_dialog_content = "恐らく、「シード」がすでにその者の身体の中で芽吹いているということだろう。",
  ui_story_8_7_2_62_option_content = "それで、僕は「治療」されたってこと？",
  ui_story_8_7_2_63_dialog_content = "一応はね。だが、結局はあなたの意志にかかっているところが大きい。\nでなければ僕が来る前に、すでに変わり果てていたはずだ。",
  ui_story_8_7_2_64_dialog_content = "そもそも、「シード」は病の類ではない。むしろ…一種の意識と言うべきだろう。",
  ui_story_8_7_2_65_dialog_content = "今の感じはどうだい？",
  ui_story_8_7_2_66_dialog_content = "楽になったんじゃない？だって…",
  ui_story_8_7_2_67_dialog_content = "いや、すごく…辛いんだ。",
  ui_story_8_7_2_68_dialog_content = "えっ？",
  ui_story_8_7_2_69_dialog_content = "まるで気が抜けたみたいに、息もうまく吸えないし…\n胸が苦しくて、目の前が暗くて、喉もなんだか…",
  ui_story_8_7_2_70_dialog_content = "それが正常なのさ。",
  ui_story_8_7_2_71_dialog_content = "ここは暗力がとても濃い。空の末裔にとっては本来、それが普通の反応だ。",
  ui_story_8_7_2_72_dialog_content = "今まで何もなかったのは、「シード」によって暗鬼になりかけていたからだ。\nわかったかい？",
  ui_story_8_7_2_73_dialog_content = "そうだったんだ…ゴホッ…",
  ui_story_8_7_2_74_dialog_content = "そんなに危ないものだなんて。早く破壊しちゃいましょう！",
  ui_story_8_7_2_75_dialog_content = "バイス、焦らないで。",
  ui_story_8_7_2_76_dialog_content = "ある者にとっては強力な毒薬でも、他の者にとっては貴重な宝になりうるんだ。\n例えば僕のようにね。",
  ui_story_8_7_2_77_dialog_content = "…！？",
  ui_story_8_7_2_78_dialog_content = "安心してくれ、別に僕はこれで哀れな誰かに害を与えようというわけじゃない。\nただ興味があるだけだ。",
  ui_story_8_7_2_79_dialog_content = "真理に従う者として、知りたいことがある。ただそれだけのことさ。",
  ui_story_8_7_2_80_dialog_content = "それに、僕の持っているカバンに入れてしまえば、危険性はなくなるはずだ。",
  ui_story_8_7_2_81_dialog_content = "そのカバン…動いてるみたいだけど？",
  ui_story_8_7_2_82_dialog_content = "心配いらないさ、特別なカバンだから。僕を信じるんだ。\n光霊と暗鬼の秘密は、いつか解き明かされる日がくるだろう。",
  ui_story_8_7_2_83_dialog_content = "その長い探求の道において、互いに助け合っていく必要があるんだ。",
  ui_story_8_7_2_84_dialog_content = "もうちょっとわかるように言ってよ…それを持っていってどうするつもり？",
  ui_story_8_7_2_85_dialog_content = "すぐにわかるさ。またお目にかかるとしよう。PlayerName、バイス。",
  ui_story_8_7_2_86_dialog_content = "この困難をうまく乗り越えられることを…いや、こう言うべきか…",
  ui_story_8_7_2_87_dialog_content = "近い将来、あなた達が脱出する勇姿をこの目で見ている。",
  ui_story_8_7_2_88_dialog_content = "あなた達に、真理の祝福あれ。",
  ui_story_8_7_2_89_dialog_content = "バイ…ス？",
  ui_story_8_7_2_90_dialog_content = "キュー！キュー！",
  ui_story_8_7_2_91_dialog_content = "ああ、長官！すみません。急ぎPlayerNameの傷を手当てしていたので…",
  ui_story_8_7_2_92_dialog_content = "えぇ、あなた達の声が聞こえたような気がします…PlayerNameは、大丈夫ですか？",
  ui_story_8_7_2_F1_dialog_content = "もう大丈夫です。長官はいかがですか？",
  ui_story_8_7_2_F2_dialog_content = "問題ありません。恐らく先ほどは、敵の「幻影」に惑わされたのでしょう。\n今はもう、大丈夫です。",
  ui_story_8_7_2_93_dialog_content = "キュー！",
  ui_story_8_7_2_94_dialog_content = "キュリー、心配させましたね。",
  ui_story_8_7_2_95_dialog_content = "皆さんにも面倒をかけてしまいましたね…",
  ui_story_8_7_2_96_option_content = "そんなこと言わないでください",
  ui_story_8_7_2_97_dialog_content = "ビビアンさんがいなかったら、僕たちには脱出する機会さえなかったんですから。",
  ui_story_8_7_2_98_dialog_content = "それで、私を助けるためにわざわざ戻って来たのですか？",
  ui_story_8_7_2_99_dialog_content = "…色んなことがあったんです。ここを脱出してからゆっくりとお話しますね！",
  ui_story_8_7_2_100_dialog_content = "ノラ…は？それに、あの神経質そうな女の子も…",
  ui_story_8_7_2_101_dialog_content = "スーモアのことですか？\nもうここにはいません。でも、僕たちが見つかるのは時間の問題です。",
  ui_story_8_7_2_102_dialog_content = "さっきの騒ぎがスーモアに感知されているかも。今すぐここを離れないと！",
  ui_story_8_7_2_103_option_content = "もう大丈夫です",
  ui_story_8_7_2_104_dialog_content = "もう大丈夫です。\nビビアンさんの体内に「シード」を埋め込もうとしていたのは阻止しました。",
  ui_story_8_7_2_105_dialog_content = "「シード」…？あなた達…先ほどのあれは…",
  ui_story_8_7_2_106_dialog_content = "まずは脱出しましょう。詳しいことは後で説明しますから！",
  ui_story_8_7_2_107_dialog_content = "わかりました。では…お願いしますね。",
  ui_story_8_7_2_108_dialog_content = "そういえば、ノラは？それにあの、とてつもなく強い相手も…",
  ui_story_8_7_2_109_dialog_content = "もうここにはいません。でも、油断はできません。",
  ui_story_8_7_2_110_dialog_content = "さっきの騒ぎがスーモアに感知されているかも。今すぐここを離れないと！",
  ui_story_8_7_2_111_dialog_content = "敵に直面しておきながら、惨めに退散するしかないとは…",
  ui_story_8_7_2_112_dialog_content = "カナンに戻ったら、大元帥様のお叱りを受ける覚悟をしなければ…なりませんね…",
  ui_story_8_7_2_113_dialog_content = "…",
  ui_story_8_7_2_114_dialog_content = "破壊して、貫いて、木っ端みじんにするのよ。",
  ui_story_8_7_2_115_dialog_content = "つまらない価値観、道徳、そして目の前にある忌々しい街…全てを粉々にしなさい。",
  ui_story_8_7_2_116_dialog_content = "目を見開いてよく見ていなさい、PlayerName。",
  ui_story_8_7_2_117_dialog_content = "空の末裔として見る最後の景色——\n地獄のような光景を、その目にしっかりと焼き付けなさい。",
  ui_story_8_7_2_118_dialog_content = "あなた達の貧弱な遺伝子の中に刻みつけるのよ。",
  ui_story_8_8_1_1_dialog_content = "ここは白夜城である。巨像冒険団でのままごと遊びとは違うのだ！",
  ui_story_8_8_1_2_dialog_content = "昔、猫を助けるためにツリーハウスから落ちたであろう。それこそ愚の骨頂だと思っていた。",
  ui_story_8_8_1_3_dialog_content = "最終的に猫を助けられたのだから、お前の決断は正しかったのかもしれない。\nだが、それが何だというのだ？",
  ui_story_8_8_1_4_dialog_content = "答えよ、あの行動に価値などあったのか！？",
  ui_story_8_8_1_5_dialog_content = "…",
  ui_story_8_8_1_6_dialog_content = "私、真意をちゃんと理解できていればいいんだけど。",
  ui_story_8_8_1_7_dialog_content = "でも、不思議ね…あの人があんなことを言うなんて初めてよ。",
  ui_story_8_8_1_8_dialog_content = "間違っていたとしても、もう遅いんじゃない？",
  ui_story_8_8_1_9_dialog_content = "だって、もう忍び込んじゃったもん！",
  ui_story_8_8_1_10_dialog_content = "ダモクレスのコントロールルームに…",
  ui_story_8_8_1_11_dialog_content = "ええ。もし捕まったら、「私に強要された」って言いなさい。",
  ui_story_8_8_1_12_dialog_content = "ラファエルはそんなこと気にしてないよ～",
  ui_story_8_8_1_13_dialog_content = "カレンちゃんって、たまに何かを固く決心したような目つきになるでしょ。さっきみたいに。",
  ui_story_8_8_1_14_dialog_content = "ラファエルがどうしていいかわからなくなったときにね、\nそういう目を見ると「じゃあカレンちゃんについていこう」って思うんだ！",
  ui_story_8_8_1_15_dialog_content = "選択に正しいとか間違ってるとかなんて無いんだよ。選ぶことこそが大事なの！",
  ui_story_8_8_1_16_dialog_content = "…",
  ui_story_8_8_1_17_dialog_content = "すごく理にかなっているように聞こえかけたけど、よく考えたら全然そうじゃないわね？",
  ui_story_8_8_1_18_dialog_content = "…",
  ui_story_8_8_1_19_dialog_content = "あっ、ミカエルちゃん！早かったねー！",
  ui_story_8_8_1_20_dialog_content = "…",
  ui_story_8_8_1_21_dialog_content = "ありがとう、ミカエル。護衛隊のメンバーが全員呼びかけに応えてくれるとは\nはなから期待していなかったわ。あなただけでも十分よ。",
  ui_story_8_8_1_22_dialog_content = "ミカエルちゃんは頼れるコだよ～！余計な質問もしないもんね？",
  ui_story_8_8_1_23_dialog_content = "…",
  ui_story_8_8_1_24_dialog_content = "外の状況はどうかしら？シールドはまだ平気？",
  ui_story_8_8_1_25_dialog_content = "…",
  ui_story_8_8_1_26_dialog_content = "さっき、最新報告が届いたよ！\nシールドはもう肉眼で分かるくらい弱まってるって。",
  ui_story_8_8_1_27_dialog_content = "あんな頑丈な光力のバリアを破れるなんて、あいつってばすごいね！",
  ui_story_8_8_1_28_dialog_content = "彼女はもう以前のスーモアではないからよ。私にも阻止できなかった…",
  ui_story_8_8_1_29_dialog_content = "でも今度は、今度こそはやってみせる！",
  ui_story_8_8_1_30_dialog_content = "うんうん！ラファエルもやる気まんまんだよー！",
  ui_story_8_8_1_31_dialog_content = "ミカエルちゃんも準備オッケーだよね！",
  ui_story_8_8_1_32_dialog_content = "…",
  ui_story_8_8_1_33_dialog_content = "それなら、説明するわね。あなた達にやってもらうことはとってもシンプルよ。",
  ui_story_8_8_1_34_dialog_content = "コントロールルームの入り口を守って。誰も中に入れないように！",
  ui_story_8_8_1_35_dialog_content = "私がダモクレスを起動させたら、白夜城全体のエネルギーがここに集中するわ…",
  ui_story_8_8_1_36_dialog_content = "そうしたらシールドは一時的に消失するから、きっと大パニックになる。",
  ui_story_8_8_1_37_dialog_content = "ラファエル、ほかの護衛隊メンバーにもう一度連絡できる？",
  ui_story_8_8_1_38_dialog_content = "他のエリアを守らせて、ダモクレスのチャージ時間を稼いでもらうのよ！",
  ui_story_8_8_1_39_dialog_content = "オッケー！もう一回連絡してみるね！",
  ui_story_8_8_1_40_dialog_content = "カレンちゃんは心置きなく、自分が正しいと思うことをやって！",
  ui_story_8_8_1_41_dialog_content = "頼んだわよ。ここは…任せたわ。",
  ui_story_8_8_1_42_dialog_content = "…",
  ui_story_8_8_1_43_dialog_content = "父上。もしかしたら、これが私の今までで一番狂った行動になるかもしれません。",
  ui_story_8_8_1_44_dialog_content = "でも…",
  ui_story_8_8_1_45_dialog_content = "「自分のやり方で、守りたい人を守る」",
  ui_story_8_8_1_46_dialog_content = "この選択が正しいって信じてるわ。",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>コントロールルームの外</color>",
  ui_story_8_8_1_48_dialog_content = "裁判長、やはりカレン様が入っていかれたようです。",
  ui_story_8_8_1_49_dialog_content = "…",
  ui_story_8_8_1_50_dialog_content = "出動しますか？今のうちであれば…",
  ui_story_8_8_1_51_dialog_content = "単にダモクレスのコントロールルームに入った、というだけなら、\nカレンはいかなる条例にも違反していません。違いますか？",
  ui_story_8_8_1_52_dialog_content = "護衛隊長である彼女には、元よりどこにでも出入りできる権限があるのですから…",
  ui_story_8_8_1_53_dialog_content = "むろん、もしダモクレスを起動するようなことがあれば、話は別ですけどね。",
  ui_story_8_8_1_54_dialog_content = "しかし、その時を待つというのも…手遅れになるのでは？",
  ui_story_8_8_1_55_dialog_content = "何がですか？",
  ui_story_8_8_1_56_dialog_content = "白夜城の存亡は、秩序と規則の上に成り立っているのです。\nもしこの鉄則が破られ、むやみな行動が許されることがあるならば…",
  ui_story_8_8_1_57_dialog_content = "それこそ「すべてが手遅れ」になりかねませんよ。",
  ui_story_8_8_1_58_dialog_content = "わかりました。では、いつでも動けるように待機いたします。",
  ui_story_8_8_1_59_dialog_content = "それから、一部の人員を他のエリアの支援に向かわせる準備を。",
  ui_story_8_8_1_60_dialog_content = "支援、ですか？",
  ui_story_8_8_1_61_dialog_content = "もし彼女が本当にダモクレスを起動させれば、\n白夜城は一時的にではありますが、完全な無防備になってしまいます。",
  ui_story_8_8_1_62_dialog_content = "これは、九死に一生を得る賭けになるでしょうか？\nそれとも、深淵へと堕ちる引き金となるでしょうか…",
  ui_story_8_8_1_63_dialog_content = "…カレン・ド・ソルラド…",
  ui_story_8_9_1_1_dialog_content = "こっちよ！私の記憶が正しければ、もうすぐ…",
  ui_story_8_9_1_2_dialog_content = "待ってください、バイス…",
  ui_story_8_9_1_3_dialog_content = "どうしたんですか？",
  ui_story_8_9_1_4_dialog_content = "あ…あの、もう少し様子を見た方がよいのではありませんか。",
  ui_story_8_9_1_5_dialog_content = "長官、今は一刻を争うんです。私が長官を背負いますから！さあ！",
  ui_story_8_9_1_6_dialog_content = "そういう意味ではありません。私たちは今、グリードのどの辺りですか？",
  ui_story_8_9_1_7_dialog_content = "今いる場所ですか？もうすぐ出口だと思いますよ。",
  ui_story_8_9_1_8_dialog_content = "グリードは…戦っているのですか？",
  ui_story_8_9_1_9_dialog_content = "中からではよくわかりませんが、恐らく白夜城のシールドへの攻撃を続けているはずです。",
  ui_story_8_9_1_10_dialog_content = "このままだと、シールドが破壊されるのは時間の問題かも…",
  ui_story_8_9_1_11_dialog_content = "白夜城は…何か対策を？",
  ui_story_8_9_1_12_dialog_content = "カレンが白夜城に戻って、ダモクレスを起動させようと頑張っているはずです。",
  ui_story_8_9_1_13_dialog_content = "事態はそこまで…",
  ui_story_8_9_1_14_dialog_content = "はい。グリードは補完が完了しています。その力はすでに…",
  ui_story_8_9_1_15_dialog_content = "…",
  ui_story_8_9_1_16_dialog_content = "スーモアは？まだ私たちに気付いていないのですよね？",
  ui_story_8_9_1_17_dialog_content = "PlayerNameが感知能力でグリードの機能を制限しているんです。",
  ui_story_8_9_1_18_dialog_content = "そうです。内部情報の取得に制限がかかるよう働きかけています。\nつまり、グリードと繋がっているスーモアは、まだ僕らが逃げたことに気づいていないはず。",
  ui_story_8_9_1_19_dialog_content = "でも、力の加減が難しくて。少しでも干渉を強めてしまうと…\n異変に気付かれてしまうかもしれません。",
  ui_story_8_9_1_20_dialog_content = "つまり、立場が逆転しているということですね…",
  ui_story_8_9_1_21_dialog_content = "敵は表に、我々は陰に。",
  ui_story_8_9_1_22_dialog_content = "長官、まさか…",
  ui_story_8_9_1_23_dialog_content = "私たちは退くべきではありません、バイス。",
  ui_story_8_9_1_24_dialog_content = "えっ？",
  ui_story_8_9_1_25_dialog_content = "基本的な…戦略分析、忘れたのですか？今の私たちは、内部から敵を撃破できる…",
  ui_story_8_9_1_26_dialog_content = "唯一の希望です。",
  ui_story_8_9_1_27_dialog_content = "でも、長官！その状態では…",
  ui_story_8_9_1_28_dialog_content = "今は、私のことを心配している場合ではないでしょう。",
  ui_story_8_9_1_29_dialog_content = "このような絶好のチャンスを無駄にするわけにはいきません。\n成功すれば、白夜城を完全に守れるかもしれないのです。",
  ui_story_8_9_1_30_dialog_content = "…",
  ui_story_8_9_1_31_dialog_content = "あなたも何を重視すべきか理解しているはず、違いますか？",
  ui_story_8_9_1_32_dialog_content = "バイス、以前のあなたはとても冷静で決断力のある子でしたが、\n最近は迷いがちのようですね。",
  ui_story_8_9_1_33_dialog_content = "長官、私はただ…誰のことも見捨てたくないだけなんです。\n特にあなたたち2人は…",
  ui_story_8_9_1_34_dialog_content = "では問いましょう。もし私たちが逆の立場であったなら、\nあなたはこんな絶好の機会を逃すことを良しとするのですか…？",
  ui_story_8_9_1_35_dialog_content = "それは…",
  ui_story_8_9_1_36_dialog_content = "それに、PlayerNameのおかげで私の傷の具合もだいぶ安定しています。",
  ui_story_8_9_1_37_dialog_content = "バイス、敵は目の前にいます。背を向けて逃げるというのですか？",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>白夜城・数年前</color>",
  ui_story_8_9_2_2_dialog_content = "（「自分のやり方で、守りたい人を守る」…）",
  ui_story_8_9_2_3_dialog_content = "…",
  ui_story_8_9_2_4_dialog_content = "でも…",
  ui_story_8_9_2_5_dialog_content = "この子…死んじゃった。",
  ui_story_8_9_2_6_dialog_content = "どんな生き物も、いつかは必ず死ぬものだ、カレン。",
  ui_story_8_9_2_7_dialog_content = "私、助けられなかった…もっと気をつけていれば…きっと…",
  ui_story_8_9_2_8_dialog_content = "子猫は怖がるあまり、自らツリーハウスを飛び降りたのだ。お前のせいではない。",
  ui_story_8_9_2_9_dialog_content = "でも、きっと助けられたのに…間違いなくできたはずなのに。",
  ui_story_8_9_2_10_dialog_content = "ハァ、子どもに言っても無意味か。",
  ui_story_8_9_2_11_dialog_content = "お前が得るべき教訓は「他者を助けられること」ではなく、\n「今後はより注意して自分を守る」ことだ。",
  ui_story_8_9_2_F1_dialog_content = "どれだけの者がお前の身を案じていると思う？",
  ui_story_8_9_2_12_dialog_content = "だが、共にツリーハウスから飛び降りたというのに、猫は死に、お前はすり傷ひとつないな。",
  ui_story_8_9_2_13_dialog_content = "…やはりソルラド家は、怪物か何かのたぐいではないのか…？",
  ui_story_8_9_2_14_dialog_content = "ともかく、ここで大人しく待っていろ。お前の父上には言っておいたから、\nあとで医者にちゃんと診てもらいなさい…",
  ui_story_8_9_2_15_dialog_content = "オットーさん。",
  ui_story_8_9_2_16_dialog_content = "なんだ？",
  ui_story_8_9_2_17_dialog_content = "ひとつ聞いてもいいですか？",
  ui_story_8_9_2_18_dialog_content = "やれやれ。言ってみろ。",
  ui_story_8_9_2_19_dialog_content = "母上が…亡くなったとき、あなたはその場にいましたか？",
  ui_story_8_9_2_20_dialog_content = "…",
  ui_story_8_9_2_21_dialog_content = "いや、いなかったな。お前の父上以外は何も詳しいことを知らんのだ。",
  ui_story_8_9_2_22_dialog_content = "…",
  ui_story_8_9_2_23_dialog_content = "私、北境へ行くべきではありませんでした。母上の近くで守ってあげればよかった…",
  ui_story_8_9_2_24_dialog_content = "私がちゃんと守ってあげていれば…母上は…",
  ui_story_8_9_2_25_dialog_content = "お前がいたとしても、何かが変わるわけではない。",
  ui_story_8_9_2_26_dialog_content = "えっ？",
  ui_story_8_9_2_27_dialog_content = "それが現実なんだ。ソルラドですら変えられなかった事を、\nお前が増えたところでどうにかなると思っているのか？",
  ui_story_8_9_2_28_dialog_content = "…結局、私は未だに誰も守ることができない…子どもだということですか？",
  ui_story_8_9_2_29_dialog_content = "違うと言いたいのか？",
  ui_story_8_9_2_30_dialog_content = "…",
  ui_story_8_9_2_31_dialog_content = "たかが猫が死んだだけではないか。カレン。",
  ui_story_8_9_2_32_dialog_content = "いいか？二度と一人で勝手に歩き回るんじゃないぞ。少しはおとなしくしていろ。",
  ui_story_8_9_2_33_dialog_content = "…",
  ui_story_8_9_2_34_dialog_content = "カレンちゃん！！",
  ui_story_8_9_2_35_dialog_content = "なに？",
  ui_story_8_9_2_36_dialog_content = "法廷の人たちに囲まれてるよ！",
  ui_story_8_9_2_37_dialog_content = "そう。まだ動こうとはしていないのかしら？",
  ui_story_8_9_2_38_dialog_content = "今の所はね！でも、みんなこっちの動きを注視してるよ…\nラファエル、いやーな予感がするなぁ…",
  ui_story_8_9_2_39_dialog_content = "イルンティ裁判長もいるみたいだし…",
  ui_story_8_9_2_40_dialog_content = "…",
  ui_story_8_9_2_41_dialog_content = "ラファエル。ミカエルと準備をしておいて。",
  ui_story_8_9_2_42_dialog_content = "ラジャー！",
  ui_story_8_9_2_43_dialog_content = "ドアを死守して。ダモクレスのコントロールルームに誰ひとり入れないこと、いい？",
  ui_story_8_9_2_44_dialog_content = "ラファエル、了解！",
  ui_story_8_9_2_45_dialog_content = "ダモクレス…",
  ui_story_8_9_2_46_dialog_content = "白夜の主の剣となり、私たちの眼前にある、絶望の暗雲を貫きたまえ…",
  ui_story_8_9_2_47_dialog_content = "ダモクレス…<color=#FFB400>起動</color>！",
  ui_story_8_10_1_1_dialog_content = "な、何ごと！？",
  ui_story_8_10_1_2_dialog_content = "停電？",
  ui_story_8_10_1_3_dialog_content = "コントロールルーム…ダモクレスのコントロールルームだ！",
  ui_story_8_10_1_4_dialog_content = "ぼうっとしてないで、状況を確認してこい！",
  ui_story_8_10_1_5_dialog_content = "…",
  ui_story_8_10_1_6_dialog_content = "ソルラド、もしこれがカレンの仕業なら、分かっているんだろうな！？",
  ui_story_8_10_1_7_dialog_content = "余の意志ではない。カレンは健全な人間であり、選択の自由がある。",
  ui_story_8_10_1_8_dialog_content = "しかし、お前が責任を免れる理由にはならんぞ…！",
  ui_story_8_10_1_9_dialog_content = "イルンティは！？法廷の連中に…",
  ui_story_8_10_1_10_dialog_content = "裁判長はすでにコントロールルームの前にいらっしゃいます！",
  ui_story_8_10_1_11_dialog_content = "ア、アップタウンにて騒乱が発生！貴族たちがパニックになり、皆が…",
  ui_story_8_10_1_12_dialog_content = "秩序を保て！慌てるな、たとえダモクレスが起動したところで、\n白夜城のエネルギーがすぐに底を尽きるわけは…",
  ui_story_8_10_1_14_dialog_content = "街の高度が…下がっているだと？",
  ui_story_8_10_1_15_dialog_content = "エネルギーがダモクレスに集中し、すべての基盤装置がそちらを優先している。",
  ui_story_8_10_1_16_dialog_content = "そんな事は分かっておるわ！何とかせんか！",
  ui_story_8_10_1_17_dialog_content = "すでに護衛隊に各エリアへ向かうよう指示を出しておいた。\nお前は、余に元老院を動かす権力を与えようというのか？",
  ui_story_8_10_1_18_dialog_content = "貴様…",
  ui_story_8_10_1_19_dialog_content = "城主様、オットー様！シールドが…！",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>同時刻・グリードにて</color>",
  ui_story_8_10_1_22_dialog_content = "今のは…！？",
  ui_story_8_10_1_23_dialog_content = "グリードが動いた？外で何が起きているのでしょう？",
  ui_story_8_10_1_24_dialog_content = "キュ――！",
  ui_story_8_10_1_25_dialog_content = "…",
  ui_story_8_10_1_26_dialog_content = "白夜城のシールドが…消えています。",
  ui_story_8_10_1_27_dialog_content = "本当ですか？じゃあ、カレンはダモクレスの起動に成功したってことね！",
  ui_story_8_10_1_28_dialog_content = "スーモアがシールドを破壊したという可能性もあります。私たちでは、\n今の状況を判断するのは難しいでしょう。",
  ui_story_8_10_1_29_dialog_content = "…カレンが成功したって信じてます。",
  ui_story_8_10_1_30_dialog_content = "待って…どうしてシールドが消えるの？",
  ui_story_8_10_1_31_dialog_content = "ダモクレスのチャージには、白夜城全体のエネルギーを集中させる必要があるの。\nシールドを維持するためのエネルギーも含めてね。",
  ui_story_8_10_1_32_dialog_content = "でもそんなに時間はかからないわ。その間だけ持ちこたえれば…",
  ui_story_8_10_1_34_dialog_content = "まずい、感知に問題が…スーモアが僕たちに気づいた！",
  ui_story_8_10_1_35_dialog_content = "ごめん…急に動き出したせいで、準備ができなくて…",
  ui_story_8_10_1_36_dialog_content = "PlayerName――！！",
  ui_story_8_10_1_37_dialog_content = "スーモア…！",
  ui_story_8_10_1_38_dialog_content = "あんた、なぜ…いつの間に逃げたの？",
  ui_story_8_10_1_39_dialog_content = "先の僕の質問に答えろ…一体何をしたんだ！",
  ui_story_8_10_1_40_dialog_content = "どうして運命を受け入れないの？なぜそんな無意味な抵抗を続ける！？",
  ui_story_8_10_1_41_dialog_content = "どうせ最後には、あの街と同じくこの私に門戸を開くことになるのよ！",
  ui_story_8_10_1_42_dialog_content = "グリードの攻撃がうまく行ったと思ってるの…？",
  ui_story_8_10_1_43_dialog_content = "（いや、まだスーモアはダモクレスの事を知らないかもしれない！）",
  ui_story_8_10_1_F1_dialog_content = "ふふふっ、あんたまだグリードの威力をわかっていないようね？",
  ui_story_8_10_1_44_dialog_content = "PlayerName、不思議だと思わないの？\nどうして何度も負けているのに、あんたが殺されていないのか…",
  ui_story_8_10_1_45_dialog_content = "…",
  ui_story_8_10_1_46_dialog_content = "最初はどうでもよかった。ただ哀れんでいたにすぎない。でもだんだんと怒りに変わったの…\nあなたのその頑迷な態度にね。",
  ui_story_8_10_1_47_dialog_content = "そしてついに、耐えられなくなり始めたみたい。\nあんたみたいな空の末裔にはただひとつだけ、証明してやればいいのだから…",
  ui_story_8_10_1_48_dialog_content = "あんた達が口先で言うだけのそれとは違う、真の力というものをね！",
  ui_story_8_10_1_49_dialog_content = "いったい何のことだ！",
  ui_story_8_10_1_50_dialog_content = "じきにわかるわ。",
  ui_story_8_10_1_51_dialog_content = "えぇ、わかるはずよ…",
  ui_story_8_10_1_52_dialog_content = "PlayerName、どうしたの？大丈夫？早く正気に戻って！",
  ui_story_8_10_1_53_dialog_content = "心配しないで、意識はあるから。さっき、スーモアと…話をしていたんだ。",
  ui_story_8_10_1_54_dialog_content = "僕たちはもう見つかってる！スーモアを阻止しないと！",
  ui_story_8_10_1_55_dialog_content = "意見は一致しましたね。行きましょう、モタモタしている暇はありませんよ！",
  ui_story_8_10_1_56_dialog_content = "キュー！",
  ui_story_8_10_1_57_dialog_content = "わかりました。騒ぎを起こして、なるべくスーモアの邪魔をすればいいんですよね？",
  ui_story_8_10_1_58_dialog_content = "カレンのために時間稼ぎができればいいけど。",
  ui_story_8_10_2_1_dialog_content = "長官…気を付けてください！",
  ui_story_8_10_2_2_dialog_content = "身体がまだうまく言うことを聞かないみたいです…\nごめんなさい、あまり役に立てそうにありません…",
  ui_story_8_10_2_3_dialog_content = "だったら、長官はここで私たちを待っていてください！\nブリッジに近づくほど、暗鬼の数も増えますし…",
  ui_story_8_10_2_4_dialog_content = "あら、長官を甘く見ないでほしいですね、バイス。\n私が部下や後輩だけで戦わせるわけがないでしょう？",
  ui_story_8_10_2_5_dialog_content = "くっ――しっかりつかまって！",
  ui_story_8_10_2_6_dialog_content = "全力で白夜城を攻撃しているわ…！外はどうなってるのかしら…",
  ui_story_8_10_2_7_dialog_content = "…行け…第3隊！急ぎ…",
  ui_story_8_10_2_8_dialog_content = "…合流だ！むやみに…外殻の隙間を狙…",
  ui_story_8_10_2_9_dialog_content = "これ！護衛隊の通信！？",
  ui_story_8_10_2_10_dialog_content = "グリードなら僕たちの通信を妨害できるはずなのに、どうして…",
  ui_story_8_10_2_11_dialog_content = "至近距離だったから、十分なシグナルをとらえることができたということでしょうか？\nとにかく、通信内容から判断すると、彼らは今まさにこの外にいるということです。",
  ui_story_8_10_2_12_dialog_content = "外にいる？護衛隊がグリードを攻撃しているってことですか？",
  ui_story_8_10_2_13_dialog_content = "そうですね。大勢の兵士が近くにいて、積極的に出撃しているのでしょう…",
  ui_story_8_10_2_14_dialog_content = "…いけ！退がるな、後ろは白夜…",
  ui_story_8_10_2_15_dialog_content = "続けろ…！食い止めるんだ…",
  ui_story_8_10_2_16_dialog_content = "飛空艇制御不能！墜落しています…まずい！あいつも、道づれにしてやる！",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>ドッカーン――！！</color>",
  ui_story_8_10_2_18_dialog_content = "…",
  ui_story_8_10_2_19_dialog_content = "今のって…捨て身の突撃！？",
  ui_story_8_10_2_20_dialog_content = "ウゥ…",
  ui_story_8_10_2_21_dialog_content = "長官、傷が…",
  ui_story_8_10_2_22_dialog_content = "行きましょう。グズグズしている暇はありません。",
  ui_story_8_10_2_23_dialog_content = "17年前の惨劇が繰り返される前に…暗鬼を食い止めましょう。",
  ui_story_8_10_2_24_dialog_content = "はい…",
  ui_story_8_10_2_25_dialog_content = "もうすぐブリッジよ。\nスーモアもそこにいるんだよね？PlayerName。",
  ui_story_8_10_2_26_dialog_content = "うん、間違いないよ。行こう、すべてを終わらせるんだ。",
  ui_story_8_10_2_27_dialog_content = "どんな暗鬼でも、もう僕たち行く手を遮ることはできない。",
  ui_story_8_13_2_1_dialog_content = "先生、私…また失敗してしまいました。",
  ui_story_8_13_2_2_dialog_content = "大丈夫だ、もう一度やってみよう。",
  ui_story_8_13_2_3_dialog_content = "でも…",
  ui_story_8_13_2_4_dialog_content = "はじめから強い者などいない。\n成長して、困難に直面し、失敗を繰り返しながら立ち上がるんだ…",
  ui_story_8_13_2_5_dialog_content = "君ならきっと「真の強者」になれる。",
  ui_story_8_13_2_6_dialog_content = "でも…",
  ui_story_8_13_2_7_dialog_content = "スーモア～",
  ui_story_8_13_2_8_dialog_content = "ああ、いらっしゃい。スーモア、友だちが来たようだな。一緒に遊んでおいで。\n今日の訓練はここで終わりにしよう。",
  ui_story_8_13_2_9_dialog_content = "そうだよ！ほら早く！私たち「友だち」でしょ！",
  ui_story_8_13_2_10_dialog_content = "ハハハハハ！",
  ui_story_8_13_2_11_dialog_content = "…",
  ui_story_8_13_2_12_dialog_content = "どうした？",
  ui_story_8_13_2_13_dialog_content = "…私は…",
  ui_story_8_13_2_14_dialog_content = "…",
  ui_story_8_13_2_15_dialog_content = "私は彼女たちを全員殺した。",
  ui_story_8_13_2_16_dialog_content = "この手で首をもいだ。そして、骨の砕ける音が歌みたいにメロディを奏でた。",
  ui_story_8_13_2_17_dialog_content = "それは…真の力を讃える歌。",
  ui_story_8_13_2_18_dialog_content = "スーモア、状況は？",
  ui_story_8_13_2_19_dialog_content = "邪魔しないで。白夜城はもう落としたし、光霊どもが最後の抵抗を続けているだけよ。",
  ui_story_8_13_2_20_dialog_content = "どう？だから言ったでしょ、私はやれるって！",
  ui_story_8_13_2_22_dialog_content = "私は、あなた達が誰も成し遂げられなかった事をやってのけたのよ。ハハハ…",
  ui_story_8_13_2_23_dialog_content = "アハハハ…！",
  ui_story_8_13_2_24_dialog_content = "…",
  ui_story_8_13_2_25_dialog_content = "私の邪魔をしないでくれる？",
  ui_story_8_13_2_26_dialog_content = "あの空の末裔がもうすぐやってきます。",
  ui_story_8_13_2_27_dialog_content = "殺戮のプロローグにはちょうどいいじゃない。入ってくればいいわ。",
  ui_story_8_13_2_28_dialog_content = "殺さないのですか？",
  ui_story_8_13_2_29_dialog_content = "どうして？私の「同胞」よ。",
  ui_story_8_13_2_30_dialog_content = "…しかしさっきは…",
  ui_story_8_13_2_31_dialog_content = "うっとうしいわね。どいつもこいつも、なんで私を煩わせるの？",
  ui_story_8_13_2_32_dialog_content = "来なさい、PlayerName。私の側に来るがいいわ。",
  ui_story_8_13_2_33_dialog_content = "私がどう変貌を遂げたか…その目を見開いて、よく見ておきなさい…",
  ui_story_8_14_1_1_dialog_content = "…",
  ui_story_8_14_1_3_dialog_content = "ミカエルちゃん！手伝いにきたよ！",
  ui_story_8_14_1_4_dialog_content = "…？",
  ui_story_8_14_1_5_dialog_content = "カレンちゃん？順調だよ！今は他の人たちが扉を守ってるの！",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>ダモクレスのコントロールルーム・扉の外</color>",
  ui_story_8_14_1_7_dialog_content = "どけ！どけと言っておるのだ！",
  ui_story_8_14_1_8_dialog_content = "イルンティ、何をしている！？どうして早く取り押さえない！！",
  ui_story_8_14_1_9_dialog_content = "見ての通りです。",
  ui_story_8_14_1_10_dialog_content = "あら、そんなに焦らないでくださいまし、オットー様…",
  ui_story_8_14_1_11_dialog_content = "下がれ！元老院を代表し、総員退去を命ずる！",
  ui_story_8_14_1_F1_dialog_content = "誰が貴様にコントロールルームを任せたのだ！？そこを退け！",
  ui_story_8_14_1_12_dialog_content = "ソルラドは！？大事なときにどこへ行ったのだ！娘をほったらかしにするつもりか！？",
  ui_story_8_14_1_13_dialog_content = "オットー様、落ち着いてお聞きください…",
  ui_story_8_14_1_14_dialog_content = "あちらをご覧ください。空が一面暗鬼だらけでございます。\n法廷と元老院が退治に向かわなくてよろしいのですか？",
  ui_story_8_14_1_15_dialog_content = "ガブリエル…",
  ui_story_8_14_1_16_dialog_content = "私、暗鬼たちを焼いてきていいかしら。",
  ui_story_8_14_1_17_dialog_content = "いいわよ～、その代わり貴族さんたちのお家を焼かないようにね！",
  ui_story_8_14_1_18_dialog_content = "えぇ、でもそれは…ちょっと難しいかも…",
  ui_story_8_14_1_19_dialog_content = "…",
  ui_story_8_14_1_20_dialog_content = "ガブリエル、私たちの前に立ちはだかるつもりですか？",
  ui_story_8_14_1_21_dialog_content = "ええ…そうよ。",
  ui_story_8_14_1_22_dialog_content = "あ、でもちょっと違うわね。立ちはだかるんじゃなくて、座ってるもの。",
  ui_story_8_14_1_23_dialog_content = "法廷の兵よ！前進…",
  ui_story_8_14_1_24_dialog_content = "<size=45>できるかしら？</size>",
  ui_story_8_14_1_25_dialog_content = "た、建物が崩れます！背後の建物が、急いで避け…",
  ui_story_8_14_1_26_dialog_content = "！！",
  ui_story_8_14_1_27_dialog_content = "多すぎるよー！これじゃ取りこぼしちゃいそう！！",
  ui_story_8_14_1_28_dialog_content = "…！！",
  ui_story_8_14_1_29_dialog_content = "ラジャー！狭いところに移動して、防衛戦に持ち込もう！",
  ui_story_8_14_1_30_dialog_content = "これ以上暗鬼にここを通らせないよ！",
  ui_story_8_14_1_31_dialog_content = "グォォ――！",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>ダモクレス・コントロールルーム</color>",
  ui_story_8_14_1_34_dialog_content = "…",
  ui_story_8_14_1_35_dialog_content = "（ラファエル、ミカエル…それに駆けつけてくれた\nガブリエルたちも、戦っているのかしら…）",
  ui_story_8_14_1_36_dialog_content = "ダモクレス…お願いよ、急いで…",
  ui_story_8_14_1_37_dialog_content = "白夜城の民が、そしてこの街が…あなたの目覚めを必要としているの…！",
  ui_story_8_14_1_38_dialog_content = "やっぱり遅すぎるわ。チャージを加速しなければ…たとえすべての力を使い果たしても！",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>グリード・ブリッジ</color>",
  ui_story_8_14_1_40_dialog_content = "タワー。",
  ui_story_8_14_1_41_dialog_content = "城壁。",
  ui_story_8_14_1_42_dialog_content = "それからハエみたいに小うるさい飛空艇…",
  ui_story_8_14_1_43_dialog_content = "戦車も動き出したわね。あなた達が何百回死のうと私を止めることはできないわよ…",
  ui_story_8_14_1_44_dialog_content = "アハハハ！もう…誰にも私を止められない…！！",
  ui_story_8_14_1_45_dialog_content = "スーモア。",
  ui_story_8_14_1_46_dialog_content = "PlayerName。",
  ui_story_8_14_1_47_dialog_content = "そんなに息を切らして、急いできたようね？ショーは始まったばかりよ。",
  ui_story_8_14_1_48_dialog_content = "こっちへ来て座りなさい。",
  ui_story_8_14_1_49_dialog_content = "もう…やめるんだ。これ以上は…",
  ui_story_8_14_1_50_dialog_content = "PlayerName！彼女は今グリードを操縦するのに手一杯よ、今のうちに…",
  ui_story_8_14_1_51_dialog_content = "バイス、9時の方向を。",
  ui_story_8_14_1_52_dialog_content = "グォォ…",
  ui_story_8_14_1_53_dialog_content = "上級暗鬼！",
  ui_story_8_14_1_54_dialog_content = "オーラが違いますね。どうやらこちらへの攻撃をやめるつもりはなさそうです…",
  ui_story_8_14_1_55_dialog_content = "そいつらをこっちに連れてきなさい、雑種。興がさめるようなことはしないでちょうだいね。",
  ui_story_8_14_1_56_dialog_content = "ようやく開幕したショーなのよ、観客ナシなんてもったいないじゃない。",
  ui_story_8_14_1_57_dialog_content = "…スーモア、またノラ様の命令に逆らうのですか。こんなときにまで勝手な行動を。",
  ui_story_8_14_1_58_dialog_content = "私にあなたを止める権利はありませんが、命令される立場でもないということをお忘れなく。",
  ui_story_8_14_1_59_dialog_content = "あの方々を含め、我らは母にのみ忠誠を誓っています…私利私欲のためではなく！",
  ui_story_8_14_1_60_dialog_content = "母、母って…やかましいわね。",
  ui_story_8_14_1_61_dialog_content = "PlayerName、見ての通り、私は今忙しいの。",
  ui_story_8_14_1_62_dialog_content = "でも、白夜城の滅亡だけは、何としてでもあなたに直接見せてあげるつもりよ。だから…",
  ui_story_8_14_1_63_dialog_content = "そういえば、お願いするなんて初めてね…さっさとこの暗鬼を殺して、\n私のそばに来てちょうだい。",
  ui_story_8_14_1_64_dialog_content = "なっ…！？",
  ui_story_8_14_1_65_dialog_content = "一体今度は何をするつもり？PlayerName、気をつけて！",
  ui_story_8_14_1_66_dialog_content = "わかってる。でも確かにスーモアの言うとおりだ。とにかく、まずはこいつを倒さないと！",
  ui_story_8_14_1_67_dialog_content = "「ご高名」はかねてより伺っております、空の末裔、そして光霊よ。",
  ui_story_8_14_1_68_dialog_content = "あなた方は色々と問題を起こしすぎです。日蝕と母の意志を貫徹するためにも…",
  ui_story_8_14_1_69_dialog_content = "来るがいい。",
  ui_story_8_14_1_70_dialog_content = "…私をがっかりさせないでちょうだいね、PlayerName。",
  ui_story_8_14_2_1_dialog_content = "そ、そんな…うそだ！",
  ui_story_8_14_2_2_dialog_content = "もう一度だけチャンスを、ノラ様、母上！私に力をお与えください。そうすれば…",
  ui_story_8_14_2_3_dialog_content = "うるさいわね…",
  ui_story_8_14_2_4_dialog_content = "うわあっ――！",
  ui_story_8_14_2_5_dialog_content = "スーモア…裏切り者め…！",
  ui_story_8_14_2_6_dialog_content = "裏切り者？バカね。私は最初から誰にも忠誠なんて誓ってないわ。",
  ui_story_8_14_2_7_dialog_content = "スーモア…もう終わりだ。",
  ui_story_8_14_2_8_dialog_content = "は？何が終わりなの？始まったばかりでしょ？",
  ui_story_8_14_2_9_dialog_content = "グリードの…感知を開始！",
  ui_story_8_14_2_10_dialog_content = "PlayerName！",
  ui_story_8_14_2_11_dialog_content = "何をするつもり！！",
  ui_story_8_14_2_12_dialog_content = "お前を止めて…巨像も止めるんだ！",
  ui_story_8_14_2_13_dialog_content = "グリードは私で、私はグリードなのよ。お前には操縦できないわ。",
  ui_story_8_14_2_14_dialog_content = "操縦できない？\n僕にわかるのは、これ以上お前を白夜城に近づけさせてはいけないことだけ…",
  ui_story_8_14_2_15_dialog_content = "あそこは、光霊たちの家…みんなの家なんだ…",
  ui_story_8_14_2_16_dialog_content = "そして僕の大切な仲間たちが…いる場所なんだ！！",
  ui_story_8_14_2_18_dialog_content = "だから…命をかけても…うああああ…！！",
  ui_story_8_14_2_19_dialog_content = "PlayerName！鼻血が！！",
  ui_story_8_14_2_20_dialog_content = "近寄らないで！！攻撃…スーモアを攻撃して！！",
  ui_story_8_14_2_21_dialog_content = "だから言ったじゃない。あんたにはムリだって…",
  ui_story_8_14_2_22_dialog_content = "危ない、バイス！！",
  ui_story_8_14_2_23_dialog_content = "（もう一度、グリードと感知――！）",
  ui_story_8_14_2_24_dialog_content = "PlayerName、まだ懲りないの！？",
  ui_story_8_14_2_25_dialog_content = "もちろん。生きている限り…絶対にあきらめない！",
  ui_story_8_14_2_26_dialog_content = "スーモア、もう勝ち目はないよ！！",
  ui_story_8_14_2_27_dialog_content = "はぁ？何を言ってるかわかってるの？その目で見てみなさいよ！！",
  ui_story_8_14_2_28_dialog_content = "白夜城はもう終わりよ！兵士も、あの甲羅も、全部終わり！！",
  ui_story_8_14_2_29_dialog_content = "私はやったのよ、PlayerName！！\n誰にも成し遂げられなかった事をやってのけたの！",
  ui_story_8_14_2_30_dialog_content = "どうして認めようとしないの！？\n絶対的な力の前にひれ伏せばいいものを、なぜ顔を上げる！？",
  ui_story_8_14_2_31_dialog_content = "グリード、エンジン…停止…",
  ui_story_8_14_2_32_dialog_content = "これは私の巨像よ！",
  ui_story_8_14_2_33_dialog_content = "うあああああああ――！！",
  ui_story_8_14_2_35_dialog_content = "う…くっ、あ、頭が…僕は…",
  ui_story_8_14_2_36_dialog_content = "PlayerName…",
  ui_story_8_14_2_37_dialog_content = "ごめんなさい、私と長官だけじゃ…スーモアの守りを崩せないわ。",
  ui_story_8_14_2_38_dialog_content = "格の違いが分かったかしら？PlayerName、それから雑魚ども。\nどうやってこの差を埋めるつもり？",
  ui_story_8_14_2_39_dialog_content = "ただ見ていればいいのよ。\n別にあんたを苦しめるつもりはないの。特に今はね――",
  ui_story_8_14_2_40_dialog_content = "私には証人が必要なの。空の末裔としての、証人がね…",
  ui_story_8_14_2_41_dialog_content = "…なに？",
  ui_story_8_14_2_42_dialog_content = "…？",
  ui_story_8_14_2_43_dialog_content = "（どうして？辺りが…静かになったような？）",
  ui_story_8_14_2_44_dialog_content = "…",
  ui_story_8_14_2_45_dialog_content = "…あんた達、また何か企んでいるのね？",
  ui_story_8_14_2_46_dialog_content = "（スーモアも分からないのか？これは彼女がやったことじゃない？）",
  ui_story_8_14_2_47_dialog_content = "え？",
  ui_story_8_14_2_48_dialog_content = "なにこれ…身の毛がよだつような感じ…",
  ui_story_8_14_2_49_dialog_content = "バイス…空気が変わったんだ。",
  ui_story_8_14_2_50_dialog_content = "待って、それに音も…どうして急に静かになったんだろう？",
  ui_story_8_14_2_51_dialog_content = "そうね。静か過ぎるわ。どうして何も聞こえないの…",
  ui_story_8_14_2_52_dialog_content = "バイス、あなたの足元…",
  ui_story_8_14_2_53_dialog_content = "地面の土ぼこりが、移動している…一か所に向かって…",
  ui_story_8_14_2_54_dialog_content = "風かもしれません。感じますか？\n空気もどこかに集まろうとしています。これはまるで…",
  ui_story_8_14_2_55_dialog_content = "何かが集まっている……？",
  ui_story_8_14_2_56_dialog_content = "2人とも…この感じ、嫌な予感がします！",
  ui_story_8_14_2_58_dialog_content = "PlayerName！長官！身体を低くして、何かに捕まって…！",
  ui_story_8_14_2_59_dialog_content = "私の予想が正しければ…間に合ったんだわ。",
  ui_story_8_14_2_62_dialog_content = "白夜城の上空に…あれは何？",
  ui_story_8_14_2_63_dialog_content = "この光、なんなの？",
  ui_story_8_14_2_64_dialog_content = "…",
  ui_story_8_14_2_65_dialog_content = "…白夜に捧ぐ。我が誓いを、ここに献じる…",
  ui_story_8_14_2_66_dialog_content = "スーモア…空の末裔の裏切り者。このカレン・ド・ソルラドが、お前に最後の…",
  ui_story_8_14_2_67_dialog_content = "裁決を下す！！！",
  ui_story_8_14_2_68_dialog_content = "あれは！？",
  ui_story_8_14_2_69_dialog_content = "みんな、伏せてー！！",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>バシュゥゥゥン――！！</color>",
  ui_story_8_14_2_73_dialog_content = "（これは！？レーザー砲…？め、目が…！）",
  ui_story_8_14_2_74_dialog_content = "（ど…どうして動けないの？どうして…私は動けないのよ！？）",
  ui_story_8_14_2_75_dialog_content = "（スーモア…）",
  ui_story_8_14_2_76_dialog_content = "（あんた…！！！）",
  ui_story_8_14_2_77_dialog_content = "（言っただろ…生きている、限り…絶対に阻止してみせる、って…）",
  ui_story_8_14_2_78_dialog_content = "（こんなもので、私を止められるとでも思っているの！？）",
  ui_story_8_14_2_82_dialog_content = "スーモア！！",
  ui_story_8_14_2_83_dialog_content = "無駄なあがきはやめなさい！！",
  ui_story_8_14_2_F1_dialog_content = "ダモクレスの光が、あなたとグリードを貫くわ！",
  ui_story_8_14_2_84_dialog_content = "（カ――カレン！！）",
  ui_story_8_14_2_87_dialog_content = "グリード、回避よ！移動！",
  ui_story_8_14_2_88_dialog_content = "逃がすか！うあああ…！！",
  ui_story_8_14_2_89_dialog_content = "上方に避けるのよ！動きなさい！！",
  ui_story_8_14_2_90_dialog_content = "（絶対に…全力を尽くしてでも！この巨像を逃がすわけにはいかない！！）",
  ui_story_8_14_2_91_dialog_content = "巨像を放しなさい、PlayerName！！感知を切りなさい！",
  ui_story_8_14_2_92_dialog_content = "（ダメだ…このままじゃ、ダモクレスの光が…当たらない！）",
  ui_story_8_14_2_93_dialog_content = "カレン、お前の光力では弱すぎる！\n光を誘導し続けることはできない！退くがいい！",
  ui_story_8_14_2_94_dialog_content = "！？",
  ui_story_8_14_2_95_dialog_content = "どうして？",
  ui_story_8_14_2_96_dialog_content = "ダモクレスは余が誘導する！それだけだ！！",
  ui_story_8_14_2_97_dialog_content = "振り返らず、前を見ろ。お前のターゲットは前方にあるのだろう？",
  ui_story_8_14_2_98_dialog_content = "敵を仕留める最後の一手で最もやってはならぬこと、忘れてはおるまいな！",
  ui_story_8_14_2_99_dialog_content = "もちろんです、父上！",
  ui_story_8_14_2_100_dialog_content = "「敵の胸を貫くまで、ランスを握る力を弱めてはならない！」",
  ui_story_8_14_2_101_dialog_content = "（し、死ぬ！このままじゃ――）",
  ui_story_8_14_2_102_dialog_content = "（どきなさい！どきなさいよ、PlayerName！！！）",
  ui_story_8_14_2_103_dialog_content = "スーモア！！",
  ui_story_8_14_2_104_dialog_content = "お前の死は、私のこの目で見届けさせてもらう！！！",
  ui_story_8_14_2_105_dialog_content = "い、いや――",
  ui_story_8_14_2_106_dialog_content = "いやあっ！！！！！！",
  ui_story_8_14_2_112_dialog_content = "スーモア。",
  ui_story_8_14_2_113_dialog_content = "あら？先生、私はここにいるわ。",
  ui_story_8_14_2_114_dialog_content = "君は…どうしてこんな事をした？",
  ui_story_8_14_2_115_dialog_content = "…",
  ui_story_8_14_2_116_dialog_content = "スーモア…",
  ui_story_8_14_2_117_dialog_content = "…なぜ…私たちを殺す？",
  ui_story_8_14_2_118_dialog_content = "私に残された命の限り、お前を呪うぞ。\nスーモア…裏切り者め、空の末裔の恥さらし、私の失敗作…",
  ui_story_8_14_2_119_dialog_content = "私たちの百倍以上の苦しみを受けて死ぬよう、お前を呪う、スーモア…",
  ui_story_8_14_2_120_dialog_content = "呪ってやる、永遠に…",
  ui_story_8_14_2_121_dialog_content = "…平安は…訪れな…",
  ui_story_8_15_1_1_dialog_content = "遅いぞ、ノラ。",
  ui_story_8_15_1_2_dialog_content = "ここは遠すぎるのよ。こんなところに隠れる必要があったの？",
  ui_story_8_15_1_3_dialog_content = "あれはどこに？",
  ui_story_8_15_1_4_dialog_content = "まだスーモアの中よ。もうすぐだから急かさないで。",
  ui_story_8_15_1_5_dialog_content = "どうしてスーモアが白夜城を攻撃することを許した？\nやることは簡単だったはず。ただ、あの者の体内から…",
  ui_story_8_15_1_6_dialog_content = "ふん、子供のいたずらじゃない。",
  ui_story_8_15_1_7_dialog_content = "そんなに大事かしら？",
  ui_story_8_15_1_8_dialog_content = "…",
  ui_story_8_15_1_9_dialog_content = "身の程を忘れるな、光霊。",
  ui_story_8_15_1_10_dialog_content = "ふあぁ〜。",
  ui_story_8_15_1_11_dialog_content = "…以上が白夜城ダウンタウンでの被害報告となります。\nそれから護衛隊長の処罰についてですが…",
  ui_story_8_15_1_12_dialog_content = "ひとまず、そこまででよい。",
  ui_story_8_15_1_13_dialog_content = "退出し、5分後に報告を再開せよ。",
  ui_story_8_15_1_14_dialog_content = "はっ！",
  ui_story_8_15_1_15_dialog_content = "何用だ。",
  ui_story_8_15_1_16_dialog_content = "久しぶりだな、ソルラド。",
  ui_story_8_15_1_17_dialog_content = "余の慰問に来たそうだな？",
  ui_story_8_15_1_18_dialog_content = "はははっ、信じたのか？",
  ui_story_8_15_1_19_dialog_content = "切り札まで使わされたわりに、ずいぶん余裕があるみたいだな。",
  ui_story_8_15_1_20_dialog_content = "数ある中から1枚を出したに過ぎん。退屈しのぎにはなった。",
  ui_story_8_15_1_21_dialog_content = "それに、今この街を守っているのは余一人ではない。",
  ui_story_8_15_1_22_dialog_content = "おっと、子どもの教育には微塵も興味はない、そこまでにしてくれ。",
  ui_story_8_15_1_23_dialog_content = "今回お前に手を貸さなかったことを、\n気にしているわけでもないだろう？",
  ui_story_8_15_1_24_dialog_content = "深く考えるな。白夜城の力を信じているというだけだ。\n永劫不落の都の主よ。",
  ui_story_8_15_1_25_dialog_content = "こちらでも、かなり面白いことが起きているぞ…\nもうすぐお前も知ることになる。",
  ui_story_8_15_1_26_dialog_content = "ふん。啓光連邦がどこまでできるか、刮目して待つとしよう。",
  ui_story_8_15_1_27_dialog_content = "揺れ動く炎が、ついに夜の帳を打ち破る時が来た…",
  ui_story_8_15_1_28_dialog_content = "啓明の光のために…！",
  ui_story_9_1_1_1_dialog_content = "どうぞ、傍聴席にお入りください。",
  ui_story_9_1_1_2_dialog_content = "ありがとう……PlayerName、行きましょ。",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>ギィッ――</color>",
  ui_story_9_1_1_4_dialog_content = "バイス、まだよく分かってないんだけど…",
  ui_story_9_1_1_5_option_content = "ここは一体何？",
  ui_story_9_1_1_6_dialog_content = "白夜城アップタウンの法廷よ。",
  ui_story_9_1_1_7_dialog_content = "上でロッドを持ってる女の人が――<color=#FFB400>イルンティ</color>裁判長ね。",
  ui_story_9_1_1_8_option_content = "あの人たちは誰？",
  ui_story_9_1_1_9_dialog_content = "見間違いじゃないなら…",
  ui_story_9_1_1_10_dialog_content = "上でロッドを持ってる女の人は、\nこの法廷を司る――<color=#FFB400>イルンティ</color>裁判長よ。",
  ui_story_9_1_1_11_dialog_content = "で、その隣でしかめっ面をしている男の人は…",
  ui_story_9_1_1_12_dialog_content = "…覚えてるよ！カレンのお父さんだね？",
  ui_story_9_1_1_13_dialog_content = "そうよ。白夜城の城主――<color=#FFB400>ダニエル・ド・ソルラド</color>殿下。",
  ui_story_9_1_1_14_dialog_content = "なんだかここ、寒気がするね…",
  ui_story_9_1_1_15_dialog_content = "シーッ…",
  ui_story_9_1_1_16_dialog_content = "…",
  ui_story_9_1_1_17_dialog_content = "お主らがカレン護衛隊長の言う「仲間」か。",
  ui_story_9_1_1_18_dialog_content = "…お目にかかれて光栄です、城主様。",
  ui_story_9_1_1_19_dialog_content = "私は啓光連邦のバイスです。こちらはPlayerName。",
  ui_story_9_1_1_20_dialog_content = "…お目にかかれて光栄です、僕はPlayerNameと言います。",
  ui_story_9_1_1_21_dialog_content = "畏まらずともよい。",
  ui_story_9_1_1_22_dialog_content = "そなたたちは敵の攻撃を遅らせるために奮戦し、\n我らが城の防衛戦において非常に重要な役割を果たしたと聞いている。",
  ui_story_9_1_1_23_dialog_content = "大義であった。",
  ui_story_9_1_1_24_dialog_content = "たいへん光栄です、城主様。私たちもできる事をしたまでのこと。",
  ui_story_9_1_1_25_dialog_content = "傷の具合はいかがかな？",
  ui_story_9_1_1_26_dialog_content = "医療兵を派遣してくださったおかげで、かなり回復しました。",
  ui_story_9_1_1_27_dialog_content = "左様か。啓光連邦には以前にも救援を送られた恩がある。\n白夜城がその恩義を忘れることはない。",
  ui_story_9_1_1_28_dialog_content = "余の身に代わり、啓光の民に白夜城の感謝の意を伝えたまえ。",
  ui_story_9_1_1_29_dialog_content = "はい、城主様。必ずやお伝えいたします。",
  ui_story_9_1_1_X29_dialog_content = "よろしい。",
  ui_story_9_1_1_X30_dialog_content = "では裁判長、開廷の宣言を。",
  ui_story_9_1_1_X31_dialog_content = "承知しました。",
  ui_story_9_1_1_30_dialog_content = "それでは開廷いたします。当事者を入廷させてください。",
  ui_story_9_1_1_31_dialog_content = "はっ！",
  ui_story_9_1_1_32_dialog_content = "（カレン…）",
  ui_story_9_1_1_33_dialog_content = "白夜に捧ぐ。",
  ui_story_9_1_1_34_dialog_content = "法廷を代表し、ここにカレン・ド・ソルラドへの判決を読み上げる。",
  ui_story_9_1_1_35_dialog_content = "白夜城の現護衛隊長、カレン・ド・ソルラド。",
  ui_story_9_1_1_36_dialog_content = "彼女は、その在職期間において――",
  ui_story_9_1_1_37_dialog_content = "三者協議の決定に背き、騎士長を脅迫のうえコントロールルームに突入し、\nダモクレスを起動させたことが明らかとなっている。",
  ui_story_9_1_1_38_dialog_content = "これにより白夜城のシールドが効力を失い、\n白夜城のアップタウン及びミッドタウンが襲撃に遭い、被害が生じた。",
  ui_story_9_1_1_39_dialog_content = "最終的な損害は貴族の負傷者108名、その従者の死傷者数はいまだ不明。\nその他、大量の財産的被害を招いた。",
  ui_story_9_1_1_40_dialog_content = "その行為は白夜城の法律に違反するものであり、\n厳罰をもって処されるべきである。",
  ui_story_9_1_1_41_dialog_content = "しかしながら、その行動により結果的には敵を撃退し、白夜城を守ることに寄与した。\n法理に基づき、その功績と過失を鑑みる余地がある。",
  ui_story_9_1_1_42_dialog_content = "従って、法廷は以下の通り決議する。\nカレン・ド・ソルラドを――1年間の停職及び観察処分と…",
  ui_story_9_1_1_43_dialog_content = "異議あり！道理に合わん！なぜそんな判決がまかり通る！？",
  ui_story_9_1_1_44_dialog_content = "…",
  ui_story_9_1_1_45_dialog_content = "彼女の行いは、白夜城のすべての貴族の命を弄ぶものだったのだぞ！",
  ui_story_9_1_1_46_dialog_content = "今回はまだこれだけの被害で済んだが、\nこのまま彼女を放置しておけば今度は何をしでかすか、分かったものではない！",
  ui_story_9_1_1_47_dialog_content = "ソルラド。まさか法廷と結託し、\n公然と御息女を庇おうというのではあるまいな？",
  ui_story_9_1_1_48_dialog_content = "オットー・トロイ。裁判長の判決である。\n半ばで口を挟むなど、貴族にあるまじき無礼であろう。",
  ui_story_9_1_1_49_dialog_content = "フン…",
  ui_story_9_1_1_50_dialog_content = "裁判長、続けたまえ。",
  ui_story_9_1_1_51_dialog_content = "従って、法廷は以下の通り決議する。\nカレン・ド・ソルラドを――1年間の停職及び観察処分とする。",
  ui_story_9_1_1_52_dialog_content = "ならびに、カレン・ド・ソルラドは\n1年以内に白夜城襲撃の真相を解明すること。",
  ui_story_9_1_1_53_dialog_content = "また、白夜城のすべての貴族に対し、その説明を詳細に行うものとする。",
  ui_story_9_1_1_54_dialog_content = "解明に失敗した場合、法廷はカレン・ド・ソルラドの職位、貴族の身分…",
  ui_story_9_1_1_55_dialog_content = "および、白夜城での居住権をはく奪するものとする。",
  ui_story_9_1_1_56_dialog_content = "白夜に捧ぐ。白夜の民に「光の神」の加護があらんことを。",
  ui_story_9_1_1_57_dialog_content = "白夜に捧ぐ。",
  ui_story_9_1_1_58_dialog_content = "バイス、PlayerName。こっちよ。",
  ui_story_9_1_1_59_dialog_content = "カレン、大丈夫？",
  ui_story_9_1_1_60_dialog_content = "大丈夫よ、心配してくれてありがとう。",
  ui_story_9_1_1_61_dialog_content = "PlayerNameこそ、体の具合は？",
  ui_story_9_1_1_62_dialog_content = "さっきの雰囲気には驚いたよ…",
  ui_story_9_1_1_63_dialog_content = "…見苦しいところを見せちゃったわね。",
  ui_story_9_1_1_64_dialog_content = "PlayerNameの体、すっかり良くなったようね？",
  ui_story_9_1_1_65_dialog_content = "完治するにはしたけど…あはは…",
  ui_story_9_1_1_66_dialog_content = "さっきのオットーっていう人…",
  ui_story_9_1_1_67_dialog_content = "裁判長がまだ判決文を読み終わらないうちから、反対を叫んでたわ。",
  ui_story_9_1_1_68_dialog_content = "あの場にいた城主様やカレンに対する敬意だって全くないし、ひどすぎるわ！",
  ui_story_9_1_1_69_dialog_content = "カレンは白夜城を守るためにダモクレスを起動したんじゃない！",
  ui_story_9_1_1_70_dialog_content = "そのおかげで敵を倒せたっていうのに！",
  ui_story_9_1_1_71_dialog_content = "どうしてカレンのことを、あんな大罪人扱いできるの？",
  ui_story_9_1_1_72_dialog_content = "徹頭徹尾白夜城の年寄り貴族のやり方よ。誰もわかってないわ！",
  ui_story_9_1_1_73_dialog_content = "……",
  ui_story_9_1_1_74_dialog_content = "……！",
  ui_story_9_1_1_75_dialog_content = "ごめんなさい、白夜城の悪口を言いたかったわけじゃ…",
  ui_story_9_1_1_76_dialog_content = "気にしないで。あなたに悪意がないことは分かっているもの。\nそれに、私は白夜城の法と審判を信じている。",
  ui_story_9_1_1_77_dialog_content = "法廷の命令なんてなくとも、自分で調べるつもりだったわ。",
  ui_story_9_1_1_78_dialog_content = "気持ちはわかるよ。僕も…真実が知りたいから。",
  ui_story_9_1_1_79_dialog_content = "でも、法廷はカレンに調査をさせるっていうのに、\nどうして兵力の支援がないの？",
  ui_story_9_1_1_80_dialog_content = "それはおそらく…城主様は最初から\nスーモアを脅威と見なしていなかったからかも…",
  ui_story_9_1_1_81_dialog_content = "えっ…どうして？",
  ui_story_9_1_1_82_dialog_content = "裁判の後、一人で城主様に会ってきたわ…",
  ui_story_9_1_1_83_dialog_content = "お父様、白夜城がスーモアに襲撃された件について…\n教えていただきたいことがあります。",
  ui_story_9_1_1_84_dialog_content = "言うがよい。",
  ui_story_9_1_1_85_dialog_content = "スーモアの襲撃に遭ったとき、\n白夜城は最初、まったく反撃する様子がなかった…",
  ui_story_9_1_1_86_dialog_content = "それどころか、わざと好きなようにシールドを攻撃させていたのでは？",
  ui_story_9_1_1_87_dialog_content = "カレン。お前はアップタウン護衛隊長の身分として、\n己の職責を理解しているか？",
  ui_story_9_1_1_88_dialog_content = "それは…",
  ui_story_9_1_1_89_dialog_content = "当然です。護衛隊の責務は民衆を守ること。",
  ui_story_9_1_1_90_dialog_content = "無礼をお許しください。なぜ私の質問に答えていただけず、\n関係のないことをお尋ねになるのですか？",
  ui_story_9_1_1_91_dialog_content = "理解しておらぬようだな。",
  ui_story_9_1_1_92_dialog_content = "アップタウン護衛隊は本来、アップタウンを守る責務を負うもの。\nすなわち、上層部の貴族たちが住まう地域のことだ。",
  ui_story_9_1_1_93_dialog_content = "ここ数年は人手の不足を理由に、\nアップタウン護衛隊の職責が拡大していた。",
  ui_story_9_1_1_94_dialog_content = "ダウンタウンの一部の地域の治安維持まで引き受けていたのだ。",
  ui_story_9_1_1_95_dialog_content = "実際のところ、周りの目からみれば、\nお前の責務は上層貴族たちの安全を守ることだろう。",
  ui_story_9_1_1_96_dialog_content = "…",
  ui_story_9_1_1_97_dialog_content = "己の間違いに気づくべきだ。",
  ui_story_9_1_1_98_dialog_content = "そして先程のお前の質問だが…",
  ui_story_9_1_1_99_dialog_content = "お前は、本当にあれしきのことで\n白夜城のシールドが破られると思ったのか？",
  ui_story_9_1_1_100_dialog_content = "お父様、それは…？",
  ui_story_9_1_1_101_dialog_content = "自分で考えるがいい。余は会議に出席せねばならぬのでな。",
  ui_story_9_1_1_102_dialog_content = "…",
  ui_story_9_1_1_103_dialog_content = "城主様は何て言ったの…？",
  ui_story_9_1_1_104_dialog_content = "私にもよく分からないのよ。あの男が一体何を考えているのか…",
  ui_story_9_1_1_105_dialog_content = "白夜城も無事だし…啓光も無事だったし…\nもしかしたら、僕が心配することなんかじゃないのかもしれないけど…",
  ui_story_9_1_1_106_dialog_content = "それでも、僕は…どうしても真実を知りたいんだ。",
  ui_story_9_1_1_107_dialog_content = "PlayerName…",
  ui_story_9_1_1_108_dialog_content = "ううん、でも今思い返しても、やっぱり驚かずにはいられないわ。",
  ui_story_9_1_1_109_dialog_content = "レーザーが目の前まで迫ってるのに、\nPlayerNameが微動だにしなかったこと！",
  ui_story_9_1_1_110_dialog_content = "私とビビアン長官がどんなに引っ張っても動かなかったのよ。",
  ui_story_9_1_1_111_dialog_content = "幸いキュリーも来てくれたから、\nレーザーがグリードに命中する前に逃げられたけどね。",
  ui_story_9_1_1_112_dialog_content = "あの時は、とにかくグリードを逃がさないことに必死で…",
  ui_story_9_1_1_113_dialog_content = "でもカレンがダモクレスをうまくガイドしてくれたおかげで、\nグリードに当てることができたね。",
  ui_story_9_1_1_114_dialog_content = "…",
  ui_story_9_1_1_115_dialog_content = "どうして？",
  ui_story_9_1_1_116_dialog_content = "ダモクレスは余が誘導する！それだけだ！！",
  ui_story_9_1_1_117_dialog_content = "…白夜城を守ることが、私の使命よ。",
  ui_story_9_1_1_118_dialog_content = "そういえばビビアンさんとキュリーは？もう啓光に戻ったの？",
  ui_story_9_1_1_119_dialog_content = "長官とキュリーはまだ白夜城の病院にいるわ…",
  ui_story_9_1_1_120_dialog_content = "心配いらないわ、結構な深手を負ってはいるけど、命に別条はないそうよ。\nただ、まだ静養が必要なようね。",
  ui_story_9_1_1_X120_dialog_content = "キュリーはもうほぼ回復して、ビビアンの側にいるわ。\n負傷したのはほとんど翼だけだったから。",
  ui_story_9_1_1_121_dialog_content = "なら良かった…でも…",
  ui_story_9_1_1_122_dialog_content = "スーモアは、本当に倒せたのかな？",
  ui_story_9_1_1_123_dialog_content = "私たちがグリードから脱出する直前まで、スーモアもずっとブリッジにいたの。\n身動きひとつできなかったはずよ。",
  ui_story_9_1_1_124_dialog_content = "真正面からダモクレスの一撃を食らって、生きていられるはずがないわ。",
  ui_story_9_1_1_125_dialog_content = "PlayerName、あなたの心配はわかるわ。",
  ui_story_9_1_1_126_dialog_content = "スーモアの亡きがらを見つけない限り、決着はつかない。",
  ui_story_9_1_1_X126_dialog_content = "でもその前に、もう一つ重要な任務があるの。",
  ui_story_9_1_1_X127_dialog_content = "えっ？どんな？",
  ui_story_9_1_1_X128_dialog_content = "あなた達と一緒にソラヴァンを見にいくこと。",
  ui_story_9_1_1_127_dialog_content = "ソラヴァンを修理できる人に来てもらったの。もう済んだそうよ。",
  ui_story_9_1_1_128_dialog_content = "<color=#FFB400>ソラヴァン</color>！！！",
  ui_story_9_1_1_129_dialog_content = "反応がない…",
  ui_story_9_1_1_130_dialog_content = "や～！ちょうどいいところに来たね。",
  ui_story_9_1_1_131_dialog_content = "ガルー先輩！？カナン城で休暇中じゃなかったんですか？",
  ui_story_9_1_1_132_dialog_content = "えへへ、めったに出現しない「サブクエスト」だよ？\n放置はありえないでしょ。何といっても、巨像のことだし！",
  ui_story_9_1_1_133_dialog_content = "ラファエルが無敵のお友達、ガルーちゃんを連れてきたんだよ～！",
  ui_story_9_1_1_134_dialog_content = "昔ラファエルが啓光に来たばかりの頃に意気投合して、すぐにお友達になって――",
  ui_story_9_1_1_135_dialog_content = "はいはい、「回想シーン」はスキップね。",
  ui_story_9_1_1_136_dialog_content = "とにかく、材料はもう集め終わって、\nPlayerNameのために巨像を修理しといたよ！",
  ui_story_9_1_1_137_dialog_content = "前にPlayerNameがあたしのHPを回復してくれたお礼に、\nあたしも「クリア報酬」は受け取らないでおくよ。",
  ui_story_9_1_1_138_dialog_content = "修理が終わった？もう？",
  ui_story_9_1_1_139_dialog_content = "あの時、確かにソラヴァンはバラバラに壊されていたのに…",
  ui_story_9_1_1_140_dialog_content = "壊された痕すら全然わからないわ！",
  ui_story_9_1_1_141_dialog_content = "さすがは啓光の科学研究室室長ね！",
  ui_story_9_1_1_142_dialog_content = "ラファエルも手伝ったんだよ！",
  ui_story_9_1_1_143_dialog_content = "ありがとう、本当に…つまり今は…",
  ui_story_9_1_1_144_dialog_content = "ソラヴァンのすべての機能が復旧しているってこと？",
  ui_story_9_1_1_145_dialog_content = "コントロールシステム、生体モジュール、\n生命維持システム…どれも問題ないわ。",
  ui_story_9_1_1_146_dialog_content = "いい機会だったし、ついでにエンジン出力も上げておいたよ！",
  ui_story_9_1_1_147_dialog_content = "ところで、修理に使った材料って、もしかして…",
  ui_story_9_1_1_148_dialog_content = "さすがは空の末裔、感知できる？",
  ui_story_9_1_1_149_dialog_content = "うん、感じるよ…<color=#FFB400>セクレペトス</color>の気配を。",
  ui_story_9_1_1_150_dialog_content = "検査してわかったんだけど、ソラヴァンの基本材料と\nセクレペトスの基本材料は類似性が99.9%だったの。",
  ui_story_9_1_1_151_dialog_content = "セクレペトスはもう、巨像としての機能を失っちゃったから…",
  ui_story_9_1_1_152_dialog_content = "使えそうな材料を回収してきて、ソラヴァンに取り付けたんだよ。",
  ui_story_9_1_1_153_dialog_content = "<color=#FFB400>モンドル</color>！僕とソラヴァンを一緒に使おう！",
  ui_story_9_1_1_154_dialog_content = "ソラヴァンがずっと君の耳や目になって、\n今も、これからも、雲の上から景色を目に焼き付けていくよ…",
  ui_story_9_1_1_155_dialog_content = "これが…死か…思っていたのと少し…違うな…孤独で…",
  ui_story_9_1_1_156_dialog_content = "（モンドル…君とセクレペトスは、最後まで僕たちを助けてくれるんだね…）",
  ui_story_9_1_1_157_dialog_content = "でも、どうしてまだソラヴァンの意識を感知できないんだろう…",
  ui_story_9_1_1_158_dialog_content = "それがね…ブリッジでパーツみたいなモノを見つけたんだけど…",
  ui_story_9_1_1_159_dialog_content = "ズタボロに壊されてて、まともそうなのはこの小さい部品しか残ってなかったんだ。",
  ui_story_9_1_1_160_dialog_content = "これは…ソラヴァンが前に言っていたんだけど、\n意識モジュールの中にはコアって呼ばれる部分があるらしいんだ。",
  ui_story_9_1_1_161_dialog_content = "ソラヴァンの「意識」は、そのコアの中に「収められて」いる、って…",
  ui_story_9_1_1_162_dialog_content = "コアが無事なら、ソラヴァンの意識は回復できるかもしれない！",
  ui_story_9_1_1_163_dialog_content = "よかったね！で、これがそのコアってことね？",
  ui_story_9_1_1_164_dialog_content = "えっと…たぶん？モジュールのことはソラヴァンから聞いただけで、\n実際に見せてもらったことはないから…",
  ui_story_9_1_1_165_dialog_content = "うーん、分解して調べるわけにもいかないよね？",
  ui_story_9_1_1_166_dialog_content = "じゃあ…とりあえず、本当にこれがコアだと思うのね？",
  ui_story_9_1_1_167_dialog_content = "そう…だと思う。",
  ui_story_9_1_1_168_dialog_content = "それで、修理の方法は知ってるの？",
  ui_story_9_1_1_169_dialog_content = "…",
  ui_story_9_1_1_170_dialog_content = "僕は…",
  ui_story_9_1_1_171_dialog_content = "PlayerNameにもガルー先輩にも、直し方がわからないの…？",
  ui_story_9_1_1_172_dialog_content = "ごめんね。",
  ui_story_9_1_1_173_dialog_content = "あたしのレベルじゃ、まだこういう旧時代の技術を解読するスキルがないの。",
  ui_story_9_1_1_174_dialog_content = "僕は…ソラヴァンから少しだけ巨像について教わったくらいだよ。",
  ui_story_9_1_1_175_dialog_content = "でも、今までそれが問題だなんて考えたこともなかった。\nいつか…こんな日が来るなんて…",
  ui_story_9_1_1_X175_dialog_content = "僕がもっとソラヴァンについて真面目に知ろうとしていたら、今ごろ…",
  ui_story_9_1_1_176_dialog_content = "PlayerName、これも一つの試練です。\n孤独を受け入れ、強くなりたいという意志を研ぎ澄ますのです。",
  ui_story_9_1_1_177_dialog_content = "実際には、あなたは今も生きている。\n私はそのために生命維持装置を作動させているのです。",
  ui_story_9_1_1_178_dialog_content = "PlayerName、私は白夜城の上空に停泊し、\nいつでもお迎えに行けるようにしておきます。",
  ui_story_9_1_1_179_dialog_content = "じゃあ、頼むよ、ソラヴァン。",
  ui_story_9_1_1_180_dialog_content = "ソラヴァン、聞こえてるよね？",
  ui_story_9_1_1_181_dialog_content = "ごめん…僕が…",
  ui_story_9_1_1_182_dialog_content = "君をちゃんと守れなかった。\nついこの前までの僕は、あんな強気だったくせに…",
  ui_story_9_1_1_183_dialog_content = "PlayerName…",
  ui_story_9_1_1_184_dialog_content = "んー？巨像は前よりずっと頑丈になったんでしょ？\nラファエルにはわかんないよ。",
  ui_story_9_1_1_185_dialog_content = "どうしてPlayerName、あんなに悲しそうなの？",
  ui_story_9_1_1_186_dialog_content = "ラファエル、いいから。",
  ui_story_9_1_1_187_dialog_content = "うぅ、ごめんなさい…",
  ui_story_9_1_1_188_dialog_content = "PlayerName。あなたがあの時ソラヴァンを離れたのは、\n白夜城の人々を守るため。",
  ui_story_9_1_1_189_dialog_content = "こうなってしまったのは私の責任よ…",
  ui_story_9_1_1_190_dialog_content = "みんなは僕を助けてくれたし、それだけでとても感謝してるんだ。\nソラヴァンのことで、誰かを責めたりできないよ。",
  ui_story_9_1_1_191_dialog_content = "すべては…スーモアと暗鬼のせいなんだ…！",
  ui_story_9_1_1_192_dialog_content = "スーモア…あ！忘れるとこだった…",
  ui_story_9_1_1_193_dialog_content = "ラファエル、カレンちゃんに大事なことを伝えないと…",
  ui_story_9_1_1_194_dialog_content = "どうしたの？",
  ui_story_9_1_1_195_dialog_content = "騎士団で調査してたんだけど、\nグリードは<color=#FFB400>天空ノ谷</color>に向かって墜落していったみたいなの！",
  ui_story_9_1_1_196_dialog_content = "…ご苦労さま。真相を明らかにするには、\nPlayerNameの故郷へ行く必要がありそうね。",
  ui_story_9_1_1_197_dialog_content = "天空ノ…谷…？",
  ui_story_9_1_1_198_dialog_content = "グリードがよりにもよって天空ノ谷に落ちるなんて…なんだか皮肉ね。",
  ui_story_9_1_1_199_dialog_content = "PlayerName、もう一つ…伝えておくことがあるの。",
  ui_story_9_1_1_200_dialog_content = "グリードが白夜城を攻撃した具体的な方法、そして3つのパーツの事…",
  ui_story_9_1_1_201_dialog_content = "すでに白夜城に報告してあるの。",
  ui_story_9_1_1_202_dialog_content = "PlayerName、理解してくれると嬉しいのだけれど。",
  ui_story_9_1_1_203_dialog_content = "うん…大丈夫、わかってるよ。",
  ui_story_9_1_1_204_dialog_content = "3つのパーツ…",
  ui_story_9_1_1_205_dialog_content = "…PlayerName、その3つのパーツの中の、\n「<color=#FFB400>ブレーンパーツ</color>」のこと、覚えてる？",
  ui_story_9_1_1_206_dialog_content = "うん、もちろん。モンドルが言ってたんだ、覚えてるよ…",
  ui_story_9_1_1_207_dialog_content = "「ブレーンパーツ」にはあらゆる情報が保存されてる。\n何でもあるって。",
  ui_story_9_1_1_208_dialog_content = "そう！それで思いついたんだけど…",
  ui_story_9_1_1_209_dialog_content = "…「ブレーンパーツ」を見つければ、\n意識モジュールを直す方法がわかるかもしれない！？",
  ui_story_9_1_1_210_dialog_content = "そうよ！PlayerName、カレン。そうと決まれば――",
  ui_story_9_1_1_211_dialog_content = "天空ノ谷に向けて、出発しよう！",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>天空ノ谷</color>",
  ui_story_9_1_1_213_dialog_content = "思ったとおり。あなたも結局、空の末裔だったじゃない。",
  ui_story_9_1_1_214_dialog_content = "死に際に、とうの昔に墓場と化した天空ノ谷に駆け込むなんて。",
  ui_story_9_1_1_215_dialog_content = "…",
  ui_story_9_1_1_216_dialog_content = "本当に面倒なコね。",
  ui_story_9_1_1_217_dialog_content = "私が最後の結論に辿り着くまで…",
  ui_story_9_1_1_218_dialog_content = "あなたは、死ねないのよ。",
  ui_story_9_1_1_219_dialog_content = "ッ…ゴホゴホ…",
  ui_story_9_1_1_220_dialog_content = "目が覚めたようね。",
  ui_story_9_1_1_221_dialog_content = "ハァ…ゼェ…目を覚ましたら…目の前にあんたがいるなんて…\nほんとに…ムカつくわ…",
  ui_story_9_1_1_222_dialog_content = "こてんぱんにやられたくせに、命の恩人に対してそんな事を言うの？",
  ui_story_9_1_1_223_dialog_content = "ふざ…け…ゴホッ…",
  ui_story_9_1_1_224_dialog_content = "認めなさいよ、スーモア。あなたは負けた。それも徹底的にね。",
  ui_story_9_1_1_225_dialog_content = "私…は…あんな虫けらなんかに…負けてないわ。",
  ui_story_9_1_1_226_dialog_content = "相変わらず強情ね。どうして負けたか、わかってる？",
  ui_story_9_1_1_227_dialog_content = "だ…黙りなさい…ゴホッ…",
  ui_story_9_1_1_228_dialog_content = "あなたが、まだまだ弱いからよ。",
  ui_story_9_1_1_229_dialog_content = "う…うるさい…",
  ui_story_9_1_1_230_dialog_content = "でも、もう一度あなたにチャンスをあげる。",
  ui_story_9_1_1_231_dialog_content = "あなたが私の実験にこれからも付き合ってくれるなら――",
  ui_story_9_1_1_232_dialog_content = "真の強者たることの醍醐味を教えてあげられるわ。",
  ui_story_9_1_1_233_dialog_content = "…まだ…「シード」を強化できるの？",
  ui_story_9_1_1_234_dialog_content = "意識がはっきりしてきたようね。",
  ui_story_9_1_1_235_dialog_content = "ゴホッ…ひとつだけ…聞くけど…",
  ui_story_9_1_1_236_dialog_content = "手間がかかるコね。",
  ui_story_9_1_1_237_dialog_content = "私を助けて、どうするつもり…？",
  ui_story_9_1_1_238_dialog_content = "誤解しないで、私はただ実験を完成させたいだけ。",
  ui_story_9_1_1_239_dialog_content = "…",
  ui_story_9_1_1_240_dialog_content = "あなたは、私の貴重な実験体なの。",
  ui_story_9_1_1_241_dialog_content = "…",
  ui_story_9_1_1_242_dialog_content = "私を助けて、どうするつもり…？",
  ui_story_9_1_1_243_dialog_content = "ぼ、僕はわかってるよ…皆が間違ってるんだって…",
  ui_story_9_2_1_1_dialog_content = "…この座標が、グリードの墜落地点――<color=#FFB400>天空ノ谷</color>よ。",
  ui_story_9_2_1_2_dialog_content = "ここが…",
  ui_story_9_2_1_3_dialog_content = "（夢の中で17年間想い続けてきた…故郷…）",
  ui_story_9_2_1_4_dialog_content = "（もうすぐそこに着く…僕は…）",
  ui_story_9_2_1_5_dialog_content = "安心して、PlayerName。私たちがそばにいるから。",
  ui_story_9_2_1_6_dialog_content = "PlayerName、忘れないで…あなたには「仲間」がいる。",
  ui_story_9_2_1_7_dialog_content = "バイス、カレン…ありがとう…",
  ui_story_9_2_1_8_dialog_content = "PlayerName、何度も言ったけど、仲間に遠慮する必要なんてないのよ。",
  ui_story_9_2_1_9_dialog_content = "それでも、感謝したいんだ。",
  ui_story_9_2_1_10_dialog_content = "君たちが側にいてくれたから、世界をこの目で見る勇気が出たんだよ。",
  ui_story_9_2_1_11_dialog_content = "そういうことなら、私も二人には感謝しているわ。",
  ui_story_9_2_1_12_dialog_content = "あなたたちがいたから、この世界を本当に知る機会が持てた。",
  ui_story_9_2_1_13_dialog_content = "PlayerName、カレン…",
  ui_story_9_2_1_14_dialog_content = "私たちの旅は始まったばかりよ！",
  ui_story_9_2_1_15_dialog_content = "そういえば、天空ノ谷がどんな場所かはみんな知ってる？",
  ui_story_9_2_1_16_dialog_content = "資料に目を通したことがあるだけよ。\nPlayerNameのほうが詳しいかもしれないわ。",
  ui_story_9_2_1_17_dialog_content = "天空ノ谷、僕の故郷…そこは「常春で、気候が穏やか」な場所…",
  ui_story_9_2_1_18_dialog_content = "ソラヴァン、天空ノ谷の映像資料をお願い。",
  ui_story_9_2_1_19_dialog_content = "…",
  ui_story_9_2_1_20_dialog_content = "…",
  ui_story_9_2_1_21_dialog_content = "ソラヴァン？ソラ…",
  ui_story_9_2_1_22_dialog_content = "PlayerName、ソラヴァンの意識モジュールは…",
  ui_story_9_2_1_23_dialog_content = "…",
  ui_story_9_2_1_24_dialog_content = "もう一回お願い、ソラヴァン。",
  ui_story_9_2_1_25_dialog_content = "「天空ノ谷」を再生します。累計再生回数16回。",
  ui_story_9_2_1_26_dialog_content = "「天空ノ谷は世界の尾根の南部に位置しており、\n山々に囲まれた肥沃な渓谷です」",
  ui_story_9_2_1_27_dialog_content = "「常に春のように暖かく、穏やかな気候が特徴で…\n真面目で優しい空の末裔たちが、代々その地で暮らしています」",
  ui_story_9_2_1_28_dialog_content = "ソラヴァン、このモフモフしたものは何？",
  ui_story_9_2_1_29_dialog_content = "これはタンポポです。黄色い部分がタンポポの花、\n白い綿毛はタンポポの種子です。",
  ui_story_9_2_1_30_dialog_content = "どうして掴めないの？",
  ui_story_9_2_1_31_dialog_content = "PlayerName、これはただの映像です。",
  ui_story_9_2_1_32_dialog_content = "気に入ったのですね。もう一度再生しましょう。",
  ui_story_9_2_1_33_dialog_content = "「天空ノ谷」を再生します。累計再生回数17回。",
  ui_story_9_2_1_34_dialog_content = "…90回。",
  ui_story_9_2_1_35_dialog_content = "…437回。",
  ui_story_9_2_1_36_dialog_content = "…2628回。",
  ui_story_9_2_1_37_dialog_content = "ソラヴァン、絶対に君の意識を取り戻すよ。",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb>天空ノ谷</color>",
  ui_story_9_2_1_39_dialog_content = "着いたわ。",
  ui_story_9_2_1_40_dialog_content = "ここが…天空ノ谷？",
  ui_story_9_2_1_41_dialog_content = "全然違う…",
  ui_story_9_2_1_42_dialog_content = "映像で見たのと、全然違う！",
  ui_story_9_2_1_43_dialog_content = "場所は間違ってないの？",
  ui_story_9_2_1_44_dialog_content = "座標が示すポイントは、確かにここよ。間違いないわ。",
  ui_story_9_2_1_45_dialog_content = "…",
  ui_story_9_2_1_46_dialog_content = "どこも枯れ草だらけ…",
  ui_story_9_2_1_47_dialog_content = "あっ、雑草の下に白い石が隠れてるわ。",
  ui_story_9_2_1_48_dialog_content = "この石、規則的に並んでいるわ。家屋の基礎でしょうね。",
  ui_story_9_2_1_49_dialog_content = "こっちにも…あっちにも…",
  ui_story_9_2_1_50_dialog_content = "この様子だと、ここは小規模の居住区だったようね。",
  ui_story_9_2_1_51_option_content = "感知を試す",
  ui_story_9_2_1_52_dialog_content = "（何も感じない…）",
  ui_story_9_2_1_53_dialog_content = "どうして…何も感知できないの…？",
  ui_story_9_2_1_54_dialog_content = "PlayerName、すべては大昔のことよ。石もみな、風化が進んでいるわ。",
  ui_story_9_2_1_55_option_content = "感知を試す",
  ui_story_9_2_1_56_dialog_content = "…",
  ui_story_9_2_1_57_dialog_content = "PlayerName、あっちへ行ってみましょうよ。もしかしたら…",
  ui_story_9_2_1_58_option_content = "感知を試す",
  ui_story_9_2_1_59_dialog_content = "…くしゅん！",
  ui_story_9_2_1_60_dialog_content = "注意して。この感覚は…<color=#FFB400>暗力</color>！",
  ui_story_9_2_1_61_dialog_content = "グリードが近くにいるから！？",
  ui_story_9_2_1_62_dialog_content = "それは違うと思う…この辺の暗力はすごく濃いのと、\n何か他のものが混ざっている感じがする。",
  ui_story_9_2_1_63_dialog_content = "PlayerName、大丈夫？",
  ui_story_9_2_1_64_dialog_content = "大丈夫。今までよりもずっと意識がはっきりしてるよ。",
  ui_story_9_2_1_65_dialog_content = "カレン、6時の方向！",
  ui_story_9_2_1_66_dialog_content = "グォォ――！",
  ui_story_9_2_1_67_dialog_content = "散れ！氷花よ！",
  ui_story_9_2_1_68_dialog_content = "PlayerNameの故郷を汚そうとするなんて！",
  ui_story_9_2_1_69_dialog_content = "PlayerName、指揮は頼んだわよ！",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>グリード内部</color>",
  ui_story_9_2_2_2_dialog_content = "横になって。",
  ui_story_9_2_2_3_dialog_content = "これは…「<color=#FFB400>治療繭</color>」？",
  ui_story_9_2_2_4_dialog_content = "楽になった？",
  ui_story_9_2_2_5_dialog_content = "あなた、とっくにこうなることを見越していたわけね…ゴホゴホッ…",
  ui_story_9_2_2_6_dialog_content = "それであの時…黒い巨像をくれた時、\nあんなガラクタを組み込んでいたってことね…",
  ui_story_9_2_2_7_dialog_content = "言葉には気をつけなさい。",
  ui_story_9_2_2_8_dialog_content = "これ…見た目は何とかならないの？",
  ui_story_9_2_2_9_dialog_content = "そこはどうしようもないわ。",
  ui_story_9_2_2_10_dialog_content = "どうして？あな…ゴホッ…大事な実験体を助けるんじゃなかったの？",
  ui_story_9_2_2_11_dialog_content = "言ったでしょ。あなたが空の末裔のすべてを捨てさえすれば、\n最上の力を得られるって。",
  ui_story_9_2_2_12_dialog_content = "私だって何度も言ってるでしょ――もうとっくに、空の末裔なんかじゃないわ。",
  ui_story_9_3_2_1_dialog_content = "ねえ！ホントにこっちで合ってる？",
  ui_story_9_3_2_2_dialog_content = "R・Wでいちばん頼れる俺様が道案内してるんだ、間違えるはずないだろ？",
  ui_story_9_3_2_3_dialog_content = "えっ？今までヘールが道案内してたの！？",
  ui_story_9_3_2_4_dialog_content = "あっ、こんなとこに爆弾が落ちてる！こりゃついてるよ、アハハハッ！",
  ui_story_9_3_2_5_dialog_content = "…あれ？この爆弾、さっき私が捨てた不発弾じゃ…",
  ui_story_9_3_2_6_dialog_content = "つまり…何度も同じ所を回ってるってこと？",
  ui_story_9_3_2_7_dialog_content = "何言ってんだよ、ちゃんと地図を見てるぜ！",
  ui_story_9_3_2_8_dialog_content = "ヘール！このアホが！その地図逆さまだよ！",
  ui_story_9_3_2_9_dialog_content = "…そりゃこうなるよね。",
  ui_story_9_3_2_10_dialog_content = "<size=45>ヘール！！</size>",
  ui_story_9_3_2_11_dialog_content = "今すぐあんたの脳をハッキングしてやる！\nどこにバグが出てるのかしらね！？",
  ui_story_9_3_2_12_dialog_content = "心配しないで～♪バーバラがみんなを応援してるよ～♪",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪愛さえあれば、希望が生まれる～♪</anim>",
  ui_story_9_3_2_14_dialog_content = "うあー！！兄貴、もう限界だ！コイツぶっ飛ばしていいか！？",
  ui_story_9_3_2_X14_dialog_content = "今日は皆仲良くねってサメヤマさんが言ってたよ！\nバーバラはカンペキだから、争ったりなんかしないの～",
  ui_story_9_3_2_X15_dialog_content = "これ以上余計な口を叩くなら、\n兄貴の言いつけを無視してでもぶっ飛ば…",
  ui_story_9_3_2_15_dialog_content = "あれ？兄貴は？",
  ui_story_9_3_2_16_dialog_content = "おい、兄貴はどうした？",
  ui_story_9_3_2_17_dialog_content = "俺様の勢いにビビって逃げたんじゃないか！？\n何せ俺様は最強だからな！",
  ui_story_9_3_2_18_dialog_content = "兄貴？さっきまでいたでしょ？",
  ui_story_9_3_2_19_dialog_content = "アニキがいなくなった！？",
  ui_story_9_3_2_20_dialog_content = "あっ、バップもいない…！",
  ui_story_9_3_2_21_dialog_content = "お前ら、よく聞け！突っ込むぞ！",
  ui_story_9_3_2_22_dialog_content = "ヘール！戻ってきな！！",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%……！</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>ズガァン――！ドォン――！</color>",
  ui_story_9_3_2_25_dialog_content = "あいたたた…！",
  ui_story_9_3_2_26_dialog_content = "オイ！どこぞのアホが、俺に罠でも張ってたのか！？",
  ui_story_9_3_2_27_dialog_content = "落とし穴たぁ、どこのどいつだ？",
  ui_story_9_3_2_28_dialog_content = "来るなら来やがれ！俺が叩きのめしてやる！",
  ui_story_9_3_2_29_dialog_content = "崩れた場所、周りの地面と何も違わなかったよ…",
  ui_story_9_3_2_30_dialog_content = "人工的に掘られた落とし穴にも見えるけど…",
  ui_story_9_3_2_31_dialog_content = "坑道の植生の覆われ方からしても、たぶん…",
  ui_story_9_3_2_32_dialog_content = "出てきやがれ！！",
  ui_story_9_3_2_33_dialog_content = "ボス、私の話、聞いてる…？",
  ui_story_9_3_2_34_dialog_content = "ん？何か言った？",
  ui_story_9_3_2_35_dialog_content = "これ、天然の穴で、トラップじゃないよ！誰にも襲われてない！",
  ui_story_9_3_2_36_dialog_content = "…",
  ui_story_9_3_2_37_dialog_content = "バップ、さっきのは聞かなかったことにしろ…\n俺がバカやってたこと、イブには言うんじゃねぇぞ！",
  ui_story_9_3_2_38_dialog_content = "聞いてなかったのはボスのほうだよ…",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>お前ら、よく聞け！突っ込むぞ！</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>ヘール！戻ってきな！！</anim>",
  ui_story_9_3_2_41_dialog_content = "わかったわかった。",
  ui_story_9_3_2_42_dialog_content = "トラップじゃねぇなら、奇襲の心配もねぇな。さっさとココを出るぞ。",
  ui_story_9_3_2_X42_dialog_content = "レジーナ！ヘール！！聞こえるかー！！",
  ui_story_9_3_2_43_dialog_content = "落下時間の長さと重力加速度から分析する限り…",
  ui_story_9_3_2_44_dialog_content = "ここからじゃ、喉を枯らすほど叫んでも、みんなには聞こえないよ…",
  ui_story_9_3_2_45_dialog_content = "レジーナ――！",
  ui_story_9_3_2_46_dialog_content = "ボス！さっきのこと、イブにバラしちゃうよ！",
  ui_story_9_3_2_47_dialog_content = "まま、待て待て。何の長さと速度だって？",
  ui_story_9_3_2_48_dialog_content = "ええと…簡単に言うと、この穴は深すぎて私たちの声は届かないってこと。",
  ui_story_9_3_2_49_dialog_content = "はぁ、そういうことかよ…",
  ui_story_9_3_2_50_dialog_content = "さすがは俺らの「<color=#FFB400>トラベラー</color>」のナビゲーター。\n分析能力はダテじゃないな！",
  ui_story_9_3_2_51_dialog_content = "よし！それならいっそ、この穴がどこにつながってるのか確かめるとするか。",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>ピピピッ――ボン！</color>",
  ui_story_9_3_2_53_dialog_content = "見てボス、巨像のパーツがいっぱい！",
  ui_story_9_3_2_54_dialog_content = "わあ！この滑らかな頭部、可愛らしい羽、繊細な作り…",
  ui_story_9_3_2_55_dialog_content = "こんなにキレイな蛍灯は初めて見た…「トラベラー」も喜びそう！",
  ui_story_9_3_2_56_dialog_content = "この蛍灯、片方しか羽が残ってないぞ。\n何につかうんだ？サッカーボールにでもするのか？",
  ui_story_9_3_2_57_dialog_content = "あそこにもいっぱい！持って帰らなきゃ！あ、あれも…",
  ui_story_9_3_2_58_dialog_content = "少しは空きを残しておけよ。本来の目的を忘れるな！",
  ui_story_9_3_2_59_dialog_content = "忘れてないよ。でも「トラベラー」にお土産を持ってく約束もしたし…",
  ui_story_9_3_2_60_dialog_content = "墜落した黒い巨像が見つかれば、もっと価値のあるオモチャが見つかるだろうよ。",
  ui_story_9_3_2_61_dialog_content = "うーん…",
  ui_story_9_3_2_62_dialog_content = "それにしたって、この洞穴、なんで巨像のパーツがこんな大量に…",
  ui_story_9_3_2_63_dialog_content = "まさか…？",
  ui_story_9_3_2_64_dialog_content = "……？",
  ui_story_9_3_2_65_dialog_content = "行くぞ！早く出口を見つけるんだ。",
  ui_story_9_3_2_66_dialog_content = "俺たち以外にも誰か居やがる気がするんだよな…",
  ui_story_9_4_1_1_dialog_content = "気をつけて！",
  ui_story_9_4_1_2_dialog_content = "敵を貫け！",
  ui_story_9_4_1_3_dialog_content = "オイオイ、嬢ちゃん。奇襲たぁいただけないぜ！",
  ui_story_9_4_1_4_dialog_content = "あなたたち…光霊？",
  ui_story_9_4_1_5_dialog_content = "戦いのほうはまあ大したもんだが、判断力のほうは…イマイチみてぇだな！",
  ui_story_9_4_1_6_dialog_content = "その顔は…！",
  ui_story_9_4_1_7_dialog_content = "カレン、どうしたの…",
  ui_story_9_4_1_8_dialog_content = "ボス、大丈夫？",
  ui_story_9_4_1_9_dialog_content = "おう、何ともないぜ！",
  ui_story_9_4_1_10_dialog_content = "君は…",
  ui_story_9_4_1_11_dialog_content = "PlayerName、R・Wに知り合いが？",
  ui_story_9_4_1_12_option_content = "啓光に行く前…",
  ui_story_9_4_1_13_dialog_content = "僕とソラヴァンが地下から出てきたばかりのとき、\n啓光のシェルターの近くに落ちたことがあるんだ。",
  ui_story_9_4_1_14_dialog_content = "その時、仲間と一緒にソラヴァンを奪いに来た人だよ。",
  ui_story_9_4_1_15_dialog_content = "おいおい、何言ってやがる？暗鬼から助けてやったじゃねえか？",
  ui_story_9_4_1_16_dialog_content = "でも、あやうくソラヴァンがバラバラにされる所だったよね。",
  ui_story_9_4_1_17_option_content = "以前、R・W砂漠で…",
  ui_story_9_4_1_18_dialog_content = "R・W砂漠を離れようとした時に、仲間と一緒に僕らを襲ってきたんだ。",
  ui_story_9_4_1_19_dialog_content = "もう少しでソラヴァンをバラバラにされるところだったよ。",
  ui_story_9_4_1_20_dialog_content = "そういう言い方をされると、何も言い返せねぇな。\nあの時は手荒なマネをしちまった。",
  ui_story_9_4_1_21_dialog_content = "それに、お前のおかげで妹は助かったんだ。",
  ui_story_9_4_1_22_dialog_content = "PlayerName、お前には借りを作っちまったな。",
  ui_story_9_4_1_23_dialog_content = "…あなたたち、R・W砂漠に行ったことがあるの？",
  ui_story_9_4_1_24_dialog_content = "前に白夜城を出てからの事ね…",
  ui_story_9_4_1_25_dialog_content = "白夜城の「お嬢ちゃん」は、相変わらずキツいみてぇだな。",
  ui_story_9_4_1_26_dialog_content = "キッチリ状況確認もせずにいきなり攻撃を仕掛けてきやがった。\nそれで万が一、無実のヤツを傷つけたらどうするつもりだ？",
  ui_story_9_4_1_27_dialog_content = "サメヤマ、カレンもわざとじゃないから…",
  ui_story_9_4_1_28_dialog_content = "先程の攻撃は、確かにこちらの不手際だった。",
  ui_story_9_4_1_29_dialog_content = "このカレン・ド・ソルラド、先ほどの攻撃に対し、心から謝罪するわ。",
  ui_story_9_4_1_30_dialog_content = "ただ、白夜城のことをでたらめに罵るようなら…",
  ui_story_9_4_1_31_dialog_content = "R・Wとの事について、きっちり清算させてもらう。",
  ui_story_9_4_1_X31_dialog_content = "ケンカか？時と場合にもよるぜ。",
  ui_story_9_4_1_32_dialog_content = "PlayerName、このカレンって嬢ちゃんはけっこう面白いヤツだ。\n一緒に行動してるなんて、何があったんだ？",
  ui_story_9_4_1_33_dialog_content = "ええと…二人の間に何があったのかは知らないけど…",
  ui_story_9_4_1_34_dialog_content = "どっちも僕やバイスと一緒に戦ったことのある仲間だから、\nケンカはやめてほしいな。",
  ui_story_9_4_1_35_dialog_content = "いいぜ、PlayerNameがそう言うことだし、\nここでイザコザを起こす必要もねぇ。",
  ui_story_9_4_1_36_dialog_content = "それは私が言うべき台詞よ。",
  ui_story_9_4_1_X36_dialog_content = "覚えておきなさい。私には別の任務があって、\nあなたたちと揉め事を起こしている暇はないというだけ。",
  ui_story_9_4_1_X37_dialog_content = "ハッ、何を言ってやがる…",
  ui_story_9_4_1_37_dialog_content = "エヘン、エヘン…あのさ！ちょっと話題を変えようよ！サメヤマ…",
  ui_story_9_4_1_38_option_content = "後ろにいる女の子は…",
  ui_story_9_4_1_39_dialog_content = "ああ、コイツはバップ。",
  ui_story_9_4_1_40_dialog_content = "よろしく、バップだよ。",
  ui_story_9_4_1_41_dialog_content = "あなたがPlayerName？いつもイブから聞いてるよ！",
  ui_story_9_4_1_42_dialog_content = "俺たちは黒い巨像がこのあたりに落ちるのを見て、追ってきたんだ。",
  ui_story_9_4_1_43_dialog_content = "そしたら、途中で俺ら二人だけ穴の中に落っこちて、\n出てきたところでお前らに出くわしたってわけだ。",
  ui_story_9_4_1_44_option_content = "君たちはどうしてここに…",
  ui_story_9_4_1_45_dialog_content = "そりゃ、おたから目当てさ、ハハハッ！",
  ui_story_9_4_1_46_dialog_content = "おたから？どういうこと？",
  ui_story_9_4_1_47_dialog_content = "俺たちは黒い巨像がこのあたりに落ちるのを見て、追ってきたんだよ。",
  ui_story_9_4_1_48_dialog_content = "そしたら途中で俺とバップだけ穴に落っこちてな。\n出てきたところでお前らに出くわしたのさ。",
  ui_story_9_4_1_49_dialog_content = "私がバップだよ。あなた、PlayerNameでしょ？\nイブからよく話を聞いてるよ！",
  ui_story_9_4_1_50_dialog_content = "PlayerName、お前らも「宝探し」にきたのか？",
  ui_story_9_4_1_51_dialog_content = "それは…話すと長くなるけど。",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>天空ノ谷！？</size>",
  ui_story_9_4_1_54_dialog_content = "やっぱり、ここが天空ノ谷だったのかよ…",
  ui_story_9_4_1_55_dialog_content = "それにしても、PlayerName。\n短い間にずいぶん色んな事があったみてぇだな。",
  ui_story_9_4_1_56_dialog_content = "地上で生きている以上、みんな苦労はしているもの。だったよね？",
  ui_story_9_4_1_57_dialog_content = "でも僕は…「希望」のことも忘れてないよ。",
  ui_story_9_4_1_58_dialog_content = "ハハハッ！そういうことなら、このサメヤマがお供してやるぜ。",
  ui_story_9_4_1_59_dialog_content = "えっ？",
  ui_story_9_4_1_60_dialog_content = "なんだ、文句あるか？",
  ui_story_9_4_1_61_dialog_content = "ないない！歓迎するわ！",
  ui_story_9_4_1_62_dialog_content = "これから先のこともわからないし、戦力が増えるのは悪くないわ。",
  ui_story_9_4_1_63_dialog_content = "お嬢ちゃんたちも賛成のようだし、これで決まりだな！",
  ui_story_9_4_1_64_dialog_content = "ボス、レジーナたちはどうするの？",
  ui_story_9_4_1_65_dialog_content = "あ、そうだった。お前ら、ここに来る途中で\nR・Wの他の連中を見なかったか？",
  ui_story_9_4_1_66_dialog_content = "他にも来ているの？",
  ui_story_9_4_1_X66_dialog_content = "ああ。俺らR・Wはひとつになって行動するもんだからな。",
  ui_story_9_4_1_67_dialog_content = "見てないわ。ここに来るまでの間、見かけたのは暗鬼ぐらいね。",
  ui_story_9_4_1_X67_dialog_content = "ガ…",
  ui_story_9_4_1_68_dialog_content = "おう、言ったそばから暗鬼が現れやがったぞ。",
  ui_story_9_4_1_69_dialog_content = "PlayerName、お前の指揮能力の成長っぷりを見せてもらうからな！",
  ui_story_9_4_2_1_dialog_content = "『主よ、外部より光霊の集団が接近中です。』",
  ui_story_9_4_2_2_dialog_content = "『もう一人の空の末裔もいるようです。』",
  ui_story_9_4_2_3_dialog_content = "『しかし我々も今は数が限られています。足止めできる戦力がありません。』",
  ui_story_9_4_2_4_dialog_content = "空の末裔？",
  ui_story_9_4_2_5_dialog_content = "まさか前に見た、あのPlayerNameっていう空の末裔かしら。",
  ui_story_9_4_2_6_dialog_content = "そんなハズないわ。彼はもう今頃…",
  ui_story_9_4_2_7_dialog_content = "…",
  ui_story_9_4_2_8_dialog_content = "スーモア、何一つうまくいかなかったようね。",
  ui_story_9_4_2_9_dialog_content = "『行け。白夜城から捕まえてきた雑兵を連れてきなさい。』",
  ui_story_9_4_2_10_dialog_content = "『かしこまりました、主よ。』",
  ui_story_9_4_2_11_dialog_content = "私、余計な問題は嫌いなの。",
  ui_story_9_4_2_12_dialog_content = "実験材料を無駄にするのも嫌い。",
  ui_story_9_4_2_13_dialog_content = "でも、何であろうと、私の実験計画を邪魔することはできないわ。",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>真理結社・秘密拠点</color>",
  ui_story_9_5_2_2_dialog_content = "敬愛するビクトリア様、何か他にお申し付けでも？",
  ui_story_9_5_2_3_dialog_content = "ファウスト。偉大なる「真理の主」のため、\nもっと多くの「<color=#FFB400>シード</color>」を収集しなさい。",
  ui_story_9_5_2_4_dialog_content = "御下命、光栄でございます、ビクトリア様。",
  ui_story_9_5_2_5_dialog_content = "セファーとネイルスの二人を連れていきなさい。",
  ui_story_9_5_2_6_dialog_content = "ビクトリア様の仰せの通りに。真理の祝福あれ。",
  ui_story_9_5_2_7_dialog_content = "これがあなたの言っていたものかしら？",
  ui_story_9_5_2_8_dialog_content = "人を恐怖させ、渇望させる、闇より来たる力。",
  ui_story_9_5_2_9_dialog_content = "太陽が光り輝く地では、真理の教えに反して「シード」の力を自ら求める者がいる。",
  ui_story_9_5_2_10_dialog_content = "そういう哀れな人々は、すでに自分が光霊であるという「本性」を捨てている。",
  ui_story_9_5_2_11_dialog_content = "本当にこれを飲み込むつもり？",
  ui_story_9_5_2_12_dialog_content = "ああ、忘れていたわ。あなたは本だもの。\n人の「本性」なんて、理解できないのかしらね。",
  ui_story_9_5_2_13_dialog_content = "ビクトリア・ワラーキ。",
  ui_story_9_5_2_X13_dialog_content = "口を慎め。ただそれを我が身に放り込めば良い。",
  ui_story_9_5_2_14_dialog_content = "それなら、消化できるかどうか、試してみましょうか。",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>ガラン――ゴクン――</color>",
  ui_story_9_5_2_16_dialog_content = "お味はどう？",
  ui_story_9_5_2_17_dialog_content = "「かすかに血肉を感じる。」",
  ui_story_9_5_2_18_dialog_content = "この「シード」は、ある空の末裔から取り出したものよ。",
  ui_story_9_5_2_19_dialog_content = "「空の末裔？」",
  ui_story_9_5_2_20_dialog_content = "あら、空の末裔の肉体に興味を持ったの？",
  ui_story_9_5_2_21_dialog_content = "「ビクトリア・ワラーキ、態度をわきまえよ。」",
  ui_story_9_5_2_22_dialog_content = "うまく吸収できたようね。",
  ui_story_9_5_2_23_dialog_content = "「これは始まりに過ぎない。」",
  ui_story_9_5_2_24_dialog_content = "そうね、ますます面白い事になってきたわ。",
  ui_story_9_5_2_25_dialog_content = "「我々の交わした契約を忘れるな。」",
  ui_story_9_5_2_26_dialog_content = "忘れるはずがないでしょう。\nすでにほかの「シード」を探すために人を派遣してあるわ。",
  ui_story_9_5_2_27_dialog_content = "「それから、お前が始末すべき者のこともだ。」",
  ui_story_9_5_2_28_dialog_content = "あまり欲張ってはいけないわ。",
  ui_story_9_5_2_29_dialog_content = "その時が来るまで、じっくりとお待ちなさい…",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>天空ノ谷深部</color>",
  ui_story_9_5_2_31_dialog_content = "いいじゃねぇか、ボウズ！",
  ui_story_9_5_2_32_dialog_content = "指揮の腕がますます上がったみたいだな！",
  ui_story_9_5_2_33_dialog_content = "ありがとう…",
  ui_story_9_5_2_X33_dialog_content = "ゴホッ、ゴホゴホッ…",
  ui_story_9_5_2_34_dialog_content = "PlayerName、どうしたの？",
  ui_story_9_5_2_35_option_content = "寒い…",
  ui_story_9_5_2_36_dialog_content = "ほら、白湯を飲めよ。",
  ui_story_9_5_2_37_dialog_content = "ええっ…サメヤマ、どうしてそんなに準備がいいの？",
  ui_story_9_5_2_38_dialog_content = "ボスはイブのために、いつもお湯を入れた水筒を持ち歩いてたんだ。",
  ui_story_9_5_2_39_dialog_content = "何となくクセになってんだよ。",
  ui_story_9_5_2_40_option_content = "何でもないよ…",
  ui_story_9_5_2_41_dialog_content = "PlayerName、ちょっと手を貸してみて。",
  ui_story_9_5_2_42_dialog_content = "…すごく冷たいじゃない！",
  ui_story_9_5_2_43_dialog_content = "平気だよ、バイス。",
  ui_story_9_5_2_44_dialog_content = "妙だな。なんで奥に進むほど温度が低くなるんだ？",
  ui_story_9_5_2_45_dialog_content = "天空ノ谷は暖かい場所っていう伝説があったはずだけど…？",
  ui_story_9_5_2_46_dialog_content = "…",
  ui_story_9_5_2_47_dialog_content = "暗力がどんどん濃くなっているわ。みんな、警戒を緩めないで！",
  ui_story_9_5_2_48_dialog_content = "天空ノ谷、暗鬼の巣窟になっちまってるみたいだな。",
  ui_story_9_5_2_49_dialog_content = "…！",
  ui_story_9_5_2_50_dialog_content = "どうりで、あんなに暗鬼に遭遇するわけだね…",
  ui_story_9_5_2_51_dialog_content = "そう言われてみれば、\nグリードがここに落ちたのも偶然じゃないのかもしれないわ。",
  ui_story_9_5_2_52_dialog_content = "まさか…",
  ui_story_9_7_1_1_dialog_content = "グアアッ！",
  ui_story_9_7_1_2_dialog_content = "コイツら、キリがねぇな！",
  ui_story_9_7_1_3_dialog_content = "よいしょ、よいしょ、よいしょ…",
  ui_story_9_7_1_4_dialog_content = "バップ、何してるの…？",
  ui_story_9_7_1_5_dialog_content = "お宝を拾ってるんだ。",
  ui_story_9_7_1_6_dialog_content = "こんなトコまで来て、またくず拾いかよ？",
  ui_story_9_7_1_7_dialog_content = "ボス、これ、くずじゃないよ！",
  ui_story_9_7_1_8_dialog_content = "この基本材料は厚さもちょうどいいし、丈夫で耐摩耗性があるから\n――「トラベラー」も気に入ると思う！",
  ui_story_9_7_1_9_dialog_content = "このボルトは初めて見るかも――持ち帰ってタイニーさんに見せてあげよっと！",
  ui_story_9_7_1_10_dialog_content = "それに…ほら！赤、黄、青、緑で蛍灯が四色集まったよ！",
  ui_story_9_7_1_11_dialog_content = "バップ、すごいわね！",
  ui_story_9_7_1_12_dialog_content = "道の途中にこんなにたくさんいい物が落ちてるなんて、気づかなかったわ！",
  ui_story_9_7_1_13_dialog_content = "あとね、あとね…",
  ui_story_9_7_1_14_dialog_content = "PlayerName、これは…",
  ui_story_9_7_1_15_dialog_content = "このパーツは確かに巨像のものだけど、グリードのものじゃない…",
  ui_story_9_7_1_16_dialog_content = "じゃあ…他の巨像から落ちたものってこと？",
  ui_story_9_7_1_17_dialog_content = "もしかして…17年前の夜に…？",
  ui_story_9_7_1_18_dialog_content = "壊れ方からしても、当時の凄惨な状況が想像できるわ。",
  ui_story_9_7_1_19_dialog_content = "…",
  ui_story_9_7_1_20_dialog_content = "ごめんなさい…ただ、こんな所に捨てられてるのがもったいなくて…",
  ui_story_9_7_1_21_dialog_content = "もしPlayerNameを嫌な気分にさせちゃうなら、もう拾わないから…",
  ui_story_9_7_1_22_dialog_content = "大丈夫だよ、バップ。",
  ui_story_9_7_1_23_dialog_content = "きっとこのパーツだって、ちゃんと価値を理解して\n大事にしてくれる人を待っていたはずだから。",
  ui_story_9_7_1_24_dialog_content = "ほんと？ありがとう、PlayerName！",
  ui_story_9_7_1_25_dialog_content = "バップ。",
  ui_story_9_7_1_26_dialog_content = "PlayerNameが大丈夫だって言ってたし…",
  ui_story_9_7_1_27_dialog_content = "この先あとどれくらいかかるか、どれくらい戦うかもわからねぇんだ。",
  ui_story_9_7_1_28_dialog_content = "こういう時は、持っていくものと置いていくものをしっかり考えておけよ。",
  ui_story_9_7_1_29_dialog_content = "…わかった。",
  ui_story_9_7_1_30_dialog_content = "じゃあ、これなら持っていってもいい？",
  ui_story_9_7_1_31_dialog_content = "それくらいなら邪魔にならねぇし、いいんじゃねぇか？",
  ui_story_9_7_1_32_dialog_content = "……！",
  ui_story_9_7_1_33_dialog_content = "カレン、これを知ってるの？",
  ui_story_9_7_1_34_dialog_content = "<color=#FFB400>白夜城衛兵</color>のバッジ…！どうしてこんな所に？",
  ui_story_9_7_1_35_dialog_content = "バップ、このバッジをどこで拾ったか覚えてる？",
  ui_story_9_7_1_36_dialog_content = "たしか…一つ前の曲がり角。私たちが暗鬼に襲われたところだよ！",
  ui_story_9_7_1_37_dialog_content = "ちょっと見せてもらえる？",
  ui_story_9_7_1_38_dialog_content = "うん。いいよ。",
  ui_story_9_7_1_39_option_content = "感知を試す",
  ui_story_9_7_1_40_dialog_content = "ついに！ついにバッジをこの身につけることができたんだ！",
  ui_story_9_7_1_41_dialog_content = "母さん！見ていますか？",
  ui_story_9_7_1_42_dialog_content = "あなたの息子が、堂々たる白夜城衛兵になりました！",
  ui_story_9_7_1_43_dialog_content = "これでもう、あのアップタウンの老いぼれたちになんか、\nこき使われる必要もないんだ！",
  ui_story_9_7_1_44_dialog_content = "でも…もう母さんはこの世にいない…",
  ui_story_9_7_1_45_dialog_content = "新入り、何をぼうっとしている！？早く暗鬼どもを防ぐんだ！",
  ui_story_9_7_1_46_dialog_content = "…はい！",
  ui_story_9_7_1_47_dialog_content = "グォォ――！",
  ui_story_9_7_1_48_dialog_content = "母さん、僕をお守りください！",
  ui_story_9_7_1_49_dialog_content = "ここは…どこだ…？",
  ui_story_9_7_1_50_dialog_content = "『主よ、これが白夜城で捕らえてきた雑兵です。』",
  ui_story_9_7_1_51_dialog_content = "『よくやったわ。』",
  ui_story_9_7_1_52_dialog_content = "暗鬼！？お前たち…何をするつもりだ！？",
  ui_story_9_7_1_53_dialog_content = "放してくれ！",
  ui_story_9_7_1_54_dialog_content = "怖がらないで、ちっとも痛くないわ。",
  ui_story_9_7_1_55_dialog_content = "く…来るな！！！",
  ui_story_9_7_1_56_dialog_content = "うわぁ――！！！",
  ui_story_9_7_1_57_dialog_content = "……！",
  ui_story_9_7_1_58_dialog_content = "PlayerName、何が見えたの？",
  ui_story_9_7_1_59_dialog_content = "あれは…",
  ui_story_9_7_1_60_option_content = "衛兵だ",
  ui_story_9_7_1_61_dialog_content = "このバッジは、白夜城衛兵のもので間違いないよ。",
  ui_story_9_7_1_62_dialog_content = "…！",
  ui_story_9_7_1_63_dialog_content = "衛兵になったばかりで、暗鬼との戦いに参加したみたいだ。",
  ui_story_9_7_1_64_dialog_content = "でも…最後には暗鬼に変えられてしまった。",
  ui_story_9_7_1_65_option_content = "暗鬼だ",
  ui_story_9_7_1_66_dialog_content = "このバッジは暗鬼が持っていたものだよ。",
  ui_story_9_7_1_67_dialog_content = "ありえないわ！",
  ui_story_9_7_1_68_dialog_content = "でもその暗鬼は、もともと白夜城衛兵だったみたいだね。",
  ui_story_9_7_1_69_dialog_content = "じゃ、結局暗鬼か、それとも衛兵か？ワケがわからねぇぜ。",
  ui_story_9_7_1_70_dialog_content = "この衛兵は、誰かに無理やり暗鬼にさせられたんだ…",
  ui_story_9_7_1_71_dialog_content = "その誰かは、間違いなく<color=#FFB400>ノラ</color>だ！",
  ui_story_9_7_1_72_dialog_content = "それって、スーモアの近くにいた謎の人物のこと？",
  ui_story_9_7_1_73_dialog_content = "そうだよ！バイス、僕の体から取り出した「シード」のことを覚えてる？",
  ui_story_9_7_1_74_dialog_content = "ええ。あれのせいで、あなたがもう少しで暗鬼になる所だったんだから！",
  ui_story_9_7_1_75_dialog_content = "ほぅ、そんなことまであったのか？",
  ui_story_9_7_1_76_dialog_content = "僕は見たんだ…ノラが無理やり「シード」を衛兵の体内に埋め込んでいるところを！",
  ui_story_9_7_1_77_dialog_content = "…！",
  ui_story_9_7_1_78_dialog_content = "あの時、白いカバンを持った男の人が言っていた…",
  ui_story_9_7_1_79_dialog_content = "…何より重要なのは、この「シード」が他の生物を暗鬼へと変貌させる\n唯一の方法だということ…",
  ui_story_9_7_1_80_dialog_content = "それはつまり…ノラが白夜城衛兵を暗鬼に変えてしまった、ということ！？",
  ui_story_9_7_1_81_dialog_content = "うん…",
  ui_story_9_7_1_82_dialog_content = "さっき私たちが倒した暗鬼も…白夜城の衛兵だったのかな…",
  ui_story_9_7_1_83_dialog_content = "たぶん…",
  ui_story_9_7_1_84_dialog_content = "…",
  ui_story_9_7_1_85_dialog_content = "おいおい、ガキども。こんな所で自分を責めて何になるんだよ！",
  ui_story_9_7_1_86_dialog_content = "衛兵を殺したのは俺たちじゃなくて、そのノラってヤツだろ！",
  ui_story_9_7_1_87_dialog_content = "サメヤマの言うとおりかも知れないわ。",
  ui_story_9_7_1_88_dialog_content = "私たちが…その衛兵を手にかけてしまったのは確かだけれど…",
  ui_story_9_7_1_89_dialog_content = "もしノラがそんなことをしなければ、\n彼は暗鬼に変えられることもなかった…",
  ui_story_9_7_1_90_dialog_content = "…",
  ui_story_9_7_1_91_dialog_content = "カレンさん、このバッジ…",
  ui_story_9_7_1_92_dialog_content = "あなたが持っていたほうがいいと思うんだ。",
  ui_story_9_7_1_93_dialog_content = "…はい。",
  ui_story_9_7_1_94_dialog_content = "カレン・ド・ソルラド、ここに死者へ哀悼の意を捧げる…",
  ui_story_9_7_1_95_dialog_content = "このバッジの所有者であった、白夜城の衛兵へ。",
  ui_story_9_7_1_96_dialog_content = "あなたは白夜城衛兵として職務を全うし、勇敢に敵と戦った。",
  ui_story_9_7_1_97_dialog_content = "敵の手に落ち、暗鬼となって意識を失い、光霊に刃を向けたことは、\n本意によるものではなかった。",
  ui_story_9_7_1_98_dialog_content = "私たちの手で苦しみを終わらせたことを、どうか赦したまえ…",
  ui_story_9_7_1_99_dialog_content = "この地で安らかに眠りにつくことを祈り、白夜に捧ぐ。",
  ui_story_9_7_1_100_dialog_content = "安らかに…",
  ui_story_9_7_1_101_dialog_content = "…",
  ui_story_9_7_1_102_dialog_content = "グリード、天空ノ谷、ノラ…何もかも謎だらけだわ。",
  ui_story_9_7_1_103_dialog_content = "…なんだか不吉な予感がするわね。",
  ui_story_9_7_1_104_dialog_content = "スーモア…",
  ui_story_9_7_1_105_dialog_content = "まさか、スーモアはまだ生きている！？",
  ui_story_9_7_1_106_dialog_content = "…！",
  ui_story_9_7_1_107_dialog_content = "とにかく、私たちも急ぎましょう！",
  ui_story_9_7_1_108_dialog_content = "グォォ――！",
  ui_story_9_7_1_109_dialog_content = "気をつけろ！正面だ！命知らずが来たぞ！",
  ui_story_9_7_1_110_dialog_content = "上級暗鬼かな？",
  ui_story_9_7_1_111_dialog_content = "見たことないわ…あんなに身体がボロボロの暗鬼なんて…",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>い…え…</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>か…え…る…</anim>",
  ui_story_9_7_1_114_dialog_content = "公用語…？",
  ui_story_9_7_1_115_dialog_content = "全然わからないわ…",
  ui_story_9_7_1_116_dialog_content = "この暗鬼…光霊の気配がする…",
  ui_story_9_7_1_117_dialog_content = "コイツも光霊が変えられた姿なのか？",
  ui_story_9_7_1_118_dialog_content = "…！",
  ui_story_9_7_1_119_dialog_content = "間違いないよ。感じるんだ、強烈な感情が…溢れてる。",
  ui_story_9_7_1_120_dialog_content = "苦しみ、絶望、孤立、怒り…まるで出口の見つからない奔流…",
  ui_story_9_7_1_121_dialog_content = "かわいそうに…家に帰りたいだけなんだ…",
  ui_story_9_7_1_122_dialog_content = "…",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>グォォ――！</anim>",
  ui_story_9_7_1_124_dialog_content = "どうやら、コイツは自分が暗鬼になっちまって、\nもう家には帰れねぇことに気づいてねぇみたいだな…",
  ui_story_9_7_1_125_dialog_content = "これ以上苦しむ前に、ラクにしてやるしかねぇ！",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>…い……え……かえ…り…</anim>",
  ui_story_9_7_2_2_dialog_content = "白夜に捧ぐ。この地で安らかに眠らんことを…",
  ui_story_9_7_2_3_dialog_content = "…せめて、苦しみから解放されたのなら…",
  ui_story_9_7_2_4_dialog_content = "ごめん、救えなかった…ごめん…",
  ui_story_9_7_2_5_dialog_content = "余計な苦痛を与えないように、私たちも手は尽くしたわ…",
  ui_story_9_7_2_6_dialog_content = "PlayerName、自分を責める必要はないわ。",
  ui_story_9_7_2_X6_dialog_content = "今私たちがこの光霊たちのためにできることは、\nノラを見つけて止めることだけ。",
  ui_story_9_7_2_7_dialog_content = "…うん！",
  ui_story_9_7_2_8_dialog_content = "みんなの言うとおりだよ…急いでノラを探して、\nこれ以上暗鬼を生み出せないようにしないと！",
  ui_story_9_7_2_9_dialog_content = "そのノラってのはどういう相手なんだ？\n名前からして、そいつも光霊なのか？",
  ui_story_9_7_2_10_option_content = "そうだよ",
  ui_story_9_7_2_11_dialog_content = "体型や雰囲気、話し方からしても、ノラは光霊に間違いないよ。",
  ui_story_9_7_2_12_dialog_content = "でも、彼女は暗鬼側についている。",
  ui_story_9_7_2_13_dialog_content = "しかも…ビビアンさんが言うには、\nノラはかつて啓光の一員だったって…",
  ui_story_9_7_2_14_option_content = "いいや",
  ui_story_9_7_2_15_dialog_content = "ノラはもともと光霊だったのかもしれないけど、\n今は悪事を働く暗鬼に過ぎないよ。",
  ui_story_9_7_2_16_dialog_content = "でも…ビビアンさんが言うには、ノラはかつて啓光の一員だったって…",
  ui_story_9_7_2_17_dialog_content = "ビビアン？",
  ui_story_9_7_2_18_dialog_content = "啓光の参謀長で、私の上司よ。",
  ui_story_9_7_2_19_dialog_content = "出発する前、ビビアン長官が私たちに「ノラに気をつけて」って注意してくれたの…",
  ui_story_9_7_2_20_dialog_content = "不吉な予感が的中するとはね…",
  ui_story_9_7_2_21_dialog_content = "でも、わからないわ…ノラは本当にもともと、啓光の仲間だったの…？",
  ui_story_9_7_2_22_dialog_content = "どうしてそんな残酷なことができるのかしら？",
  ui_story_9_7_2_23_dialog_content = "まるで、光霊を暗鬼にする実験に打ち込んでいるみたいな…",
  ui_story_9_7_2_24_dialog_content = "私が啓光にいた時は、そんな人がいたなんて聞いたことないわ…",
  ui_story_9_7_2_25_dialog_content = "啓光の上層部のことだ、そういう後ろ暗ぇ事は、\nお前ら末端のヤツには隠してるんだろうよ。",
  ui_story_9_7_2_26_dialog_content = "サメヤマ、イブの事であなたが啓光を信用してないことは知ってるけど…",
  ui_story_9_7_2_27_dialog_content = "啓光の長官たちは、実際はみんな率先して手本を示すような人たちよ！",
  ui_story_9_7_2_X27_dialog_content = "長官たちだってずっと調査してるはずで…",
  ui_story_9_7_2_28_dialog_content = "ハハハハッ！お前ら、ホントにお人好しだな。\nそんなヨタ話を信じてるなんてよ。",
  ui_story_9_7_2_29_dialog_content = "昔、俺の妹…イブは暗鬼に襲われて、深刻な後遺症が残ったんだ。",
  ui_story_9_7_2_30_dialog_content = "そして俺は、啓光のご立派な言い分をうかうか信じて、イブを治療にやっちまった…",
  ui_story_9_7_2_31_dialog_content = "…",
  ui_story_9_7_2_32_dialog_content = "そしたらどうだ！？イブは余計に悪くなるどころか、\n大火事に巻き込まれて死ぬところだったんだぞ！",
  ui_story_9_7_2_33_dialog_content = "その大火事…",
  ui_story_9_7_2_34_dialog_content = "…！",
  ui_story_9_7_2_35_dialog_content = "なんで気づかなかったんだろう…\nノラの顔…火傷の痕があったわ…",
  ui_story_9_7_2_36_dialog_content = "何だと！？",
  ui_story_9_7_2_37_dialog_content = "啓光の大火事…",
  ui_story_9_7_2_38_dialog_content = "ああああっ！！！",
  ui_story_9_7_2_39_dialog_content = "ノラの傷跡…",
  ui_story_9_7_2_40_dialog_content = "この顔を見なさい。この傷跡を…火に焼かれた跡よ、見えるでしょう？",
  ui_story_9_7_2_41_dialog_content = "まさか…",
  ui_story_9_7_2_42_dialog_content = "サメヤマ、確認したいんだけど…\nその時イブの治療を担当していた研究員は、どこに行ったの？",
  ui_story_9_7_2_43_dialog_content = "俺がようやく啓光にたどり着いた時、言われたんだ…",
  ui_story_9_7_2_44_dialog_content = "シェルターで実験をしてたやつらは全員あの火事で死んだ、ってな。",
  ui_story_9_7_2_45_dialog_content = "本当に？",
  ui_story_9_7_2_46_dialog_content = "啓光は責任逃れするような言い方だった。俺だって信じなかったさ。",
  ui_story_9_7_2_47_dialog_content = "それに妙だったのは、あいつら、一度も研究員の名前を口にしなかった。",
  ui_story_9_7_2_48_dialog_content = "だから俺も人を使って、裏で調査したんだよ。",
  ui_story_9_7_2_49_dialog_content = "だが調査の結果は…何も変わらなかった。",
  ui_story_9_7_2_50_dialog_content = "だがな、今まで「<color=#FFB400>デニール</color>」\n――やつの名前だけは忘れたことがねぇ。",
  ui_story_9_7_2_X50_dialog_content = "元から私たちの知っている情報が間違っていたのね。\n誰もがその研究員は火事で死んだと思ってた。",
  ui_story_9_7_2_51_dialog_content = "だから、ノラを見ても誰もすぐに気づかなかった！",
  ui_story_9_7_2_52_dialog_content = "確かに。よく考えてみると、ノラとそのデニールは同一人物の可能性があるね。",
  ui_story_9_7_2_53_dialog_content = "…！",
  ui_story_9_7_2_54_dialog_content = "あ…ぁ…！",
  ui_story_9_7_2_55_dialog_content = "イブ…",
  ui_story_9_7_2_56_dialog_content = "くそっ、ツラ突き合わせて、そのノラってヤツに問いただしてやる！",
  ui_story_9_7_2_57_dialog_content = "もしそいつがイブに何かしたんなら、俺は絶対に許さねぇ！",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>グリード・治療繭の中</color>",
  ui_story_9_8_1_2_dialog_content = "先生…",
  ui_story_9_8_1_3_dialog_content = "ごめんなさい…先生…もう一度…",
  ui_story_9_8_1_4_dialog_content = "どうして…",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>天空ノ谷・教習用巨像停泊所</color>",
  ui_story_9_8_1_6_dialog_content = "ハンデル先生、ごめんなさい！もう一度チャンスをください！",
  ui_story_9_8_1_7_dialog_content = "スーモア、挑戦のチャンスは3回まで…もう使い終わりましたよ。",
  ui_story_9_8_1_8_dialog_content = "残念ですが、今回の「巨像操作実習」には不合格です。",
  ui_story_9_8_1_9_dialog_content = "で…でも、もし合格できなかったら、\n「グリード」のナビゲーター選抜に参加できなくなっちゃいます…！",
  ui_story_9_8_1_10_dialog_content = "今回の試験、どうしても合格したいんです！",
  ui_story_9_8_1_11_dialog_content = "スーモア、あなたの気持ちはわかります。",
  ui_story_9_8_1_12_dialog_content = "あなたは私にとって、最も自慢できる生徒の一人です。\n選抜にもぜひ参加させてあげたい…",
  ui_story_9_8_1_13_dialog_content = "ですが、試験にせよ、選抜にせよ、皆に公平にしなければなりません。",
  ui_story_9_8_1_14_dialog_content = "ハンデル先生、準備できました！試験はいつですか？",
  ui_story_9_8_1_15_dialog_content = "ええ、すぐに行きます。",
  ui_story_9_8_1_16_dialog_content = "スーモア、あなたの努力する姿を見て、先生はとても安心しています。",
  ui_story_9_8_1_17_dialog_content = "先生は信じていますよ。あなたがたゆまず練習を続ければ、\n感知能力もきっと強くなります！",
  ui_story_9_8_1_18_dialog_content = "次の選抜こそ、あなたが「グリード」のナビゲーターになれるはず。\nわかりましたね？",
  ui_story_9_8_1_19_dialog_content = "でも、次がいつかなんてわからないし…",
  ui_story_9_8_1_20_dialog_content = "…",
  ui_story_9_8_1_21_dialog_content = "次なんてないわよ。\n前の選抜なんて、何十年も前だったのよ？",
  ui_story_9_8_1_X1_dialog_content = "（うるさいわね。普段は無視しておいて、\n選抜に参加するって聞いたらたちまちおせっかい焼き？）",
  ui_story_9_8_1_X2_dialog_content = "スーモア、あなたは前回の座学の成績は一番でしたが…",
  ui_story_9_8_1_X3_dialog_content = "慢心はいけませんよ。巨像の感知と普段の試験は違うのです。\n努力を続けなさい。",
  ui_story_9_8_1_X4_dialog_content = "（別に言われなくっても、わかってる）",
  ui_story_9_8_1_22_dialog_content = "スーモア、いつも試験でトップの成績を取る優等生じゃなかったの？",
  ui_story_9_8_1_23_dialog_content = "巨像の操作なんて簡単じゃんか、どうしてできないの？",
  ui_story_9_8_1_X5_dialog_content = "（できるわ、今に見てなさい）",
  ui_story_9_8_1_X6_dialog_content = "それよりも、巨像を感知できないってほうが問題だろ！？\nスーモア、お前ホントに空の末裔か？",
  ui_story_9_8_1_X7_dialog_content = "（黙りなさい、ほんの少し感知できる程度で何を得意気になってるのよ）",
  ui_story_9_8_1_24_dialog_content = "スーモアが試験に落ちたの？まさか…",
  ui_story_9_8_1_X8_dialog_content = "（まだ一回目の試験じゃない。次があれば…）",
  ui_story_9_8_1_X9_dialog_content = "ハンデルが、グリードのナビゲーターにお前が最適だって？",
  ui_story_9_8_1_X10_dialog_content = "はぁ…早くあきらめたほうがいい。そのほうがお前のためだぞ。",
  ui_story_9_8_1_X11_dialog_content = "お前には才能がないんだよ、それに資格もな…",
  ui_story_9_8_1_X12_dialog_content = "（黙れ！どいつもこいつも間抜けばかり、何もわかってない！）",
  ui_story_9_8_1_X13_dialog_content = "（いつの日か…すべてを証明してみせる！）",
  ui_story_9_8_1_X14_dialog_content = "…………",
  ui_story_9_8_1_25_dialog_content = "それよりも、巨像を感知できないってほうが問題だろ！？\nスーモア、お前ホントに空の末裔か？",
  ui_story_9_8_1_26_dialog_content = "き…君たち…",
  ui_story_9_8_1_27_dialog_content = "へん、誰かと思えば「腰抜け」モンドルかよ？",
  ui_story_9_8_1_28_dialog_content = "言いたいことがあるなら、言ってみろよ！",
  ui_story_9_8_1_29_dialog_content = "そんなこと…言っちゃダメだ…",
  ui_story_9_8_1_30_dialog_content = "なんで？止めろって言ったら俺たちがやめるとでも思ったの？",
  ui_story_9_8_1_31_dialog_content = "ハ、ハンデル先生に…",
  ui_story_9_8_1_32_dialog_content = "え？先生がなんだよ。",
  ui_story_9_8_1_33_dialog_content = "先生に…言うよ…",
  ui_story_9_8_1_34_dialog_content = "ハンデル先生に言うって？フン、先生にばっか甘えやがって！",
  ui_story_9_8_1_35_dialog_content = "ねえ、もうやめなよ…",
  ui_story_9_8_1_36_dialog_content = "フン、行こうぜ！",
  ui_story_9_8_1_X15_dialog_content = "やめなよ、こ、これ以上いじめるなら…ハ、ハンデル先生に言うよ。",
  ui_story_9_8_1_37_dialog_content = "だ…大丈夫？",
  ui_story_9_8_1_38_dialog_content = "誰よ？何か問題あるように見える？あんたの助けなんていらない。",
  ui_story_9_8_1_39_dialog_content = "ぼ、僕はモンドルっていうんだ…\nあ、あいつらが君をいじめているように見えたから…",
  ui_story_9_8_1_X16_dialog_content = "その…心配になって…",
  ui_story_9_8_1_X17_dialog_content = "私がいじめられているのを見て、同情してるってこと？",
  ui_story_9_8_1_40_dialog_content = "どうせそうやって、自分のエゴを満たしたいだけなんでしょ。\nこれで満足した？自分はなんて優しいやつなんだって思った？",
  ui_story_9_8_1_X18_dialog_content = "あんたもあいつらと同じなんでしょ？",
  ui_story_9_8_1_X19_dialog_content = "気分が良いときだけ心配して、\n気分が悪くなったらからかいに来るんでしょ？",
  ui_story_9_8_1_41_dialog_content = "そ、そんなわけ…",
  ui_story_9_8_1_X20_dialog_content = "違う？じゃあなんなの？",
  ui_story_9_8_1_42_dialog_content = "私を助けて、どうするつもり…？",
  ui_story_9_8_1_43_dialog_content = "ぼ、僕はわかってるよ…皆が間違ってるんだって…",
  ui_story_9_8_1_44_dialog_content = "（当然よ。悪いのはあいつら…）",
  ui_story_9_8_1_45_dialog_content = "（思い上がって、いい気になって…）",
  ui_story_9_8_1_46_dialog_content = "スーモア、どうして一人でこんなところにいるの？",
  ui_story_9_8_1_47_dialog_content = "…！",
  ui_story_9_8_1_48_dialog_content = "あッ、「巨像を動かせない」スーモアじゃんか！",
  ui_story_9_8_1_49_dialog_content = "巨像と感知する方法のお勉強？そりゃあ大変だねぇ。",
  ui_story_9_8_1_50_dialog_content = "スーモアをからかうのはやめましょうよ、ね、もう行こう…",
  ui_story_9_8_1_51_dialog_content = "そうだ、いいこと思いついた。",
  ui_story_9_8_1_52_dialog_content = "ちょっとした賭けをしようぜ。",
  ui_story_9_8_1_53_dialog_content = "賭け？どういう？",
  ui_story_9_8_1_54_dialog_content = "スーモア、俺たちと一緒に天空ノ谷の外を回る勇気はあるか？",
  ui_story_9_8_1_X21_dialog_content = "えっ？それってこの間こっそり計画してたアレのこと？",
  ui_story_9_8_1_X22_dialog_content = "ハハッ、スーモアを見なよ。\nずっとうなだれたまま。きっとびくびくしてるんだ。",
  ui_story_9_8_1_55_dialog_content = "先に答えて。やるかやらないか。",
  ui_story_9_8_1_56_dialog_content = "ならやってやるよ！",
  ui_story_9_8_1_57_dialog_content = "あなたたちは巨像と感知できるけど…\n巨像を操縦して、天空ノ谷の外に出る勇気はあるの？",
  ui_story_9_8_1_58_dialog_content = "でも、前にも言ったでしょ…ハンデル先生が外はすごく危険で、\n暗鬼がいるかもしれないって。",
  ui_story_9_8_1_59_dialog_content = "どうして？恐いの？",
  ui_story_9_8_1_60_dialog_content = "何が怖いんだよ？巨像で行けば問題ないだろ。",
  ui_story_9_8_1_61_dialog_content = "もしあなたたちが巨像で外に出て、\n一周して戻ってきたら、あなたたちの勝ち。",
  ui_story_9_8_1_62_dialog_content = "俺たちが勝ったら、お前が全部責任取るんだからな！",
  ui_story_9_8_1_63_dialog_content = "巨像は…「アプレンティス1号」を使おう！",
  ui_story_9_8_1_64_dialog_content = "本当に見つからない？",
  ui_story_9_8_1_65_dialog_content = "安心しろよ。「グリード」の次のナビゲーターだろ。\nハンデル先生お墨付きの優勝者なんだからな！",
  ui_story_9_8_1_66_dialog_content = "…！",
  ui_story_9_8_1_67_dialog_content = "そうだよ、お前の腕を信じてるからな！",
  ui_story_9_8_1_68_dialog_content = "もし見つかっても…お前なら何も言われないよ！",
  ui_story_9_8_1_69_dialog_content = "わかったわよ…言っておくけど、今回だけだからね！",
  ui_story_9_8_1_70_dialog_content = "やった！行くぞー！",
  ui_story_9_8_1_X23_dialog_content = "スーモア、お前はどうする？",
  ui_story_9_8_1_X24_dialog_content = "僕は「来ない」ほうに本3冊賭ける！",
  ui_story_9_8_1_71_dialog_content = "（グリードは…私のもの…）",
  ui_story_9_8_1_72_dialog_content = "（あんたたちは何もわかってない…だから…）",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>天空ノ谷の外</color>",
  ui_story_9_8_1_74_dialog_content = "巨像が…動かない！",
  ui_story_9_8_1_75_dialog_content = "…",
  ui_story_9_8_1_76_dialog_content = "暗鬼だ！暗鬼が扉を破ってる…！",
  ui_story_9_8_1_77_dialog_content = "ど…どうしよう？",
  ui_story_9_8_1_78_dialog_content = "キキキキキキッ！",
  ui_story_9_8_1_79_dialog_content = "まさか獲物の方からやってくるとは思わなかったぞ！",
  ui_story_9_8_1_X25_dialog_content = "（全員死んだのよ）",
  ui_story_9_8_1_80_dialog_content = "や…やばい！",
  ui_story_9_8_1_81_dialog_content = "うわーー！",
  ui_story_9_8_1_82_dialog_content = "身の程知らずな下等生物どもめ、本来ならば、\nもう少し時間を与えてやっても良かったんだがな。",
  ui_story_9_8_1_83_dialog_content = "うあ…",
  ui_story_9_8_1_84_dialog_content = "うぅ…",
  ui_story_9_8_1_85_dialog_content = "こんなに脆いものなのか？",
  ui_story_9_8_1_86_dialog_content = "ちょっと仕分けしてやっただけなのに、\n勝手に死んでしまうとは。参ったな。",
  ui_story_9_8_1_87_dialog_content = "…",
  ui_story_9_8_1_88_dialog_content = "そんなに撃たれ弱いの？ちょっとつかんだだけで、骨が砕けるなんてね。",
  ui_story_9_8_1_89_dialog_content = "お前らの骨をネックレスに仕立て上げて、毎日身に着けて愛でてやるとも。",
  ui_story_9_8_1_90_dialog_content = "…",
  ui_story_9_8_1_91_dialog_content = "（逃げ…どこか…逃げられる場所は…）",
  ui_story_9_8_1_X91_dialog_content = "ガ…",
  ui_story_9_8_1_92_dialog_content = "んん？廃墟の中にガキが逃げ込んだだと？",
  ui_story_9_8_1_X92_dialog_content = "キキキッ、面白くなってきたな。",
  ui_story_9_8_1_X26_dialog_content = "（……！）",
  ui_story_9_8_1_S1_dialog_content = "来ないで！！！",
  ui_story_9_8_1_X27_dialog_content = "静かにしろ…いい報せがあるぞ。",
  ui_story_9_8_1_X28_dialog_content = "聞きたいか？",
  ui_story_9_8_1_X29_dialog_content = "…こ、公用語が話せるの！？",
  ui_story_9_8_1_S2_dialog_content = "キキキッ、こんな時にそんなことが気になるのか？\n殺されるのが怖くないのか？",
  ui_story_9_8_1_S3_dialog_content = "…怖いわよ。",
  ui_story_9_8_1_X30_dialog_content = "キキキキキッ！それならよーく耳を澄ませて、\n一言も漏らさずに聞くんだな。",
  ui_story_9_8_1_93_dialog_content = "偉大なる母上の意志により、空の末裔は末日を迎え、\n永遠に消滅することが決まった。",
  ui_story_9_8_1_94_dialog_content = "これこそが空の末裔に対する最後の審判であり、\n母上が空の末裔に授け給う幸福な結末なのだ！",
  ui_story_9_8_1_95_dialog_content = "喜ぶがいい！お前たちはその歴史的な瞬間を目撃することができるぞ！",
  ui_story_9_8_1_96_dialog_content = "…な、なんですって？",
  ui_story_9_8_1_97_dialog_content = "お前に質問する資格はない！",
  ui_story_9_8_1_98_dialog_content = "弱者は直ちに滅び去るのみ！",
  ui_story_9_8_1_99_dialog_content = "お前のお友達と同じように、\nひねり潰されて苦しみながら死んでいくのだ。",
  ui_story_9_8_1_100_dialog_content = "……！",
  ui_story_9_8_1_101_dialog_content = "キキキッ！だが安心しろ。お前は選ばれた。機会をくれてやろう。",
  ui_story_9_8_1_102_dialog_content = "お前に空の末裔を超える力を与えてやる！\n弱者の身分から脱するのだ！",
  ui_story_9_8_1_103_dialog_content = "弱者を…脱する…",
  ui_story_9_8_1_104_dialog_content = "スーモア、いつも試験でトップの成績を取る優等生じゃなかったの？",
  ui_story_9_8_1_105_dialog_content = "巨像の操作なんて簡単な事、どうしてできないの？",
  ui_story_9_8_1_106_dialog_content = "スーモアが試験に落ちたの？まさか…",
  ui_story_9_8_1_107_dialog_content = "それよりも、巨像を感知できないってほうが問題だろ！？\nスーモア、お前ホントに空の末裔か？",
  ui_story_9_8_1_108_dialog_content = "本当に見つからない？",
  ui_story_9_8_1_109_dialog_content = "安心しろよ。「グリード」の次のナビゲーターだろ。\nハンデル先生お墨付きの優勝者なんだからな！",
  ui_story_9_8_1_110_dialog_content = "この「シード」が見えるか？これがお前の希望だ。",
  ui_story_9_8_1_111_dialog_content = "…私の…希望。",
  ui_story_9_8_1_112_dialog_content = "いいぞ、お前が力を渇望していることは見て取れる。",
  ui_story_9_8_1_113_dialog_content = "ちか…ら…",
  ui_story_9_8_1_114_dialog_content = "ス…スーモア、ねぇ…？",
  ui_story_9_8_1_115_dialog_content = "そうだ…母上に選ばれし民だけが、生き残ることができる！",
  ui_story_9_8_1_116_dialog_content = "生き…残…",
  ui_story_9_8_1_117_dialog_content = "お前はもう弱くない、恐れる必要はない！",
  ui_story_9_8_1_118_dialog_content = "恩恵を受け入れ、力を手にし、我々に加わるのだ！",
  ui_story_9_8_1_119_dialog_content = "お前も世界を、すべてを支配するのだ！",
  ui_story_9_8_1_120_dialog_content = "すべてを…支配…",
  ui_story_9_8_1_121_dialog_content = "スーモア…い…行かないで…",
  ui_story_9_8_1_122_dialog_content = "そうだ、それでいい。こちらへ来い。",
  ui_story_9_8_1_123_dialog_content = "や…やめて…お願い…",
  ui_story_9_8_1_124_dialog_content = "…",
  ui_story_9_8_1_125_dialog_content = "どうした？",
  ui_story_9_8_1_126_dialog_content = "私は…",
  ui_story_9_8_1_127_dialog_content = "その刀を拾え！",
  ui_story_9_8_1_128_dialog_content = "私…",
  ui_story_9_8_1_129_dialog_content = "ぐずぐずするな、こちらの我慢にも限度があるぞ！\n何をためらっている！？",
  ui_story_9_8_1_130_dialog_content = "わ、私は暗鬼になる…そういうこと？",
  ui_story_9_8_1_131_dialog_content = "ふん、仕方ない。",
  ui_story_9_8_1_132_dialog_content = "きゃああっ——！",
  ui_story_9_8_1_133_dialog_content = "あなた…！",
  ui_story_9_8_1_134_dialog_content = "お前はこの女が嫌いだ、そうだろう？",
  ui_story_9_8_1_135_dialog_content = "…",
  ui_story_9_8_1_136_dialog_content = "私が代わりに片付けてやったのだから、感謝するべきじゃないか？",
  ui_story_9_8_1_137_dialog_content = "…私も殺すつもり？",
  ui_story_9_8_1_138_dialog_content = "なぜ？",
  ui_story_9_8_1_139_dialog_content = "私にはわかる。お前はヤツらとは違う、強者になれる器があるのだ。",
  ui_story_9_8_1_140_dialog_content = "その通りだとも。暗鬼になれば空の末裔を、\n更には光霊すらも超える力を手にすることが出来るのだ！",
  ui_story_9_8_1_141_dialog_content = "そ…それは、どういう力なの？",
  ui_story_9_8_1_142_dialog_content = "母上が大地を潤した甘泉であり、\n生きとし生けるものへ与えし無上の恩恵だ。",
  ui_story_9_8_1_143_dialog_content = "お前は生き延びることができる。何かを恐れる必要もなくなる。",
  ui_story_9_8_1_144_dialog_content = "つまり、それを受け入れれば…私は…生き残れる？",
  ui_story_9_8_1_145_dialog_content = "もちろんだ。この谷よりも更に長生きできるぞ。",
  ui_story_9_8_1_146_dialog_content = "それをもらったら…私は…もう弱くない？",
  ui_story_9_8_1_147_dialog_content = "そうだ。これから先、お前は強大な力、そのものとなる。",
  ui_story_9_8_1_S147_dialog_content = "それを受け入れたら…私はグリードを操縦する資格を得られる？",
  ui_story_9_8_1_S148_dialog_content = "グリード？巨像か？",
  ui_story_9_8_1_S149_dialog_content = "キキキッ、答えろ、お前の欲するその巨像とは一体どんなものだ？",
  ui_story_9_8_1_S150_dialog_content = "グリードは…最強の巨像、最強の空の末裔だけが…その操縦の資格を得られる。",
  ui_story_9_8_1_S151_dialog_content = "キッ！キッ！キッ！ならば、お前はどの空の末裔よりもふさわしくなるだろう！\nなぜなら、お前はすべての空の末裔を超越するからだ！",
  ui_story_9_8_1_148_dialog_content = "…",
  ui_story_9_8_1_149_dialog_content = "私…",
  ui_story_9_8_1_150_dialog_content = "…受け取る。",
  ui_story_9_8_1_151_dialog_content = "キキキキキキッ！",
  ui_story_9_8_1_152_dialog_content = "ううっ…！",
  ui_story_9_8_1_153_dialog_content = "偉大なる母上！この世にまた一人、あなた様の下僕が生を授かりました！",
  ui_story_9_8_1_154_dialog_content = "本当に私に力をくれたの？",
  ui_story_9_8_1_155_dialog_content = "特に何も変化を感じないけど…",
  ui_story_9_8_1_156_dialog_content = "スーモア、それがお前の名前だな？",
  ui_story_9_8_1_157_dialog_content = "覚えておけ、スーモア。いかなる者も母上の力を疑ってはならんのだ。\n待つということを覚えるがいい。",
  ui_story_9_8_1_158_dialog_content = "…",
  ui_story_9_8_1_159_dialog_content = "これから、私をどこへ連れていくの？",
  ui_story_9_8_1_160_dialog_content = "どこへも行かん。\nお前は天空ノ谷へ戻ればいいのだ。むろん、私を連れてな。",
  ui_story_9_8_1_161_dialog_content = "天空ノ谷へ！？",
  ui_story_9_8_1_162_dialog_content = "忘れたのか？お前の「グリード」が天空ノ谷で待っている。",
  ui_story_9_8_1_163_dialog_content = "「グリード」があれば、お前の力は完全なものとなる。\n誰もかなうものはいなくなるのだ！",
  ui_story_9_8_1_164_dialog_content = "忘れてなんかないわ。でも、私は他の人とは違うの。",
  ui_story_9_8_1_165_dialog_content = "私には…巨像が感知できない。でも、いつか…",
  ui_story_9_8_1_166_dialog_content = "なに？感知ができない空の末裔だと？",
  ui_story_9_8_1_167_dialog_content = "その言い方はやめて！！！",
  ui_story_9_8_1_168_dialog_content = "まあいい。「シード」がすでにお前の体内で声を上げている。",
  ui_story_9_8_1_169_dialog_content = "今日から、お前はもはや空の末裔ではなくなるのだ。",
  ui_story_9_8_1_170_dialog_content = "さあ、この巨像を動かしてみろ。",
  ui_story_9_8_1_171_dialog_content = "…わかったわ。",
  ui_story_9_8_1_172_dialog_content = "違う…ウソよ…！",
  ui_story_9_8_1_173_dialog_content = "負けてない…私は負けてなんかない…！",
  ui_story_9_8_1_174_dialog_content = "スーモア！！",
  ui_story_9_8_1_175_dialog_content = "お前の死は、私のこの目で見届けさせてもらう！！！",
  ui_story_9_8_1_176_dialog_content = "い、いや――",
  ui_story_9_8_1_177_dialog_content = "いやあっ！！！！！！",
  ui_story_9_9_1_1_dialog_content = "みんな、足元に気をつけて！",
  ui_story_9_9_1_2_dialog_content = "何が起きたの！？",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>ウ…ウ…ウ…</color>",
  ui_story_9_9_1_4_dialog_content = "声…たくさんの声が聞こえる…",
  ui_story_9_9_1_5_dialog_content = "えっ？地面が揺れてる音じゃなくて？",
  ui_story_9_9_1_6_dialog_content = "ち、違う…これは…グリードの、悲鳴…",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>ウ…ウ…ウ…</color>",
  ui_story_9_9_1_8_dialog_content = "（すべてが…巨像の悲しい鳴き声…まるで、ここに埋まっている巨像たちが\nみんな泣いているような…）",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>ウ…ウ…ウ…</anim></color>",
  ui_story_9_9_1_10_dialog_content = "（心臓が引き裂かれそうだ…）",
  ui_story_9_9_1_11_dialog_content = "（熱い液体がこぼれ落ちるような…）",
  ui_story_9_9_1_12_dialog_content = "な、涙？",
  ui_story_9_9_1_13_dialog_content = "PlayerName…",
  ui_story_9_9_1_14_dialog_content = "PlayerName…泣いてるの？",
  ui_story_9_9_1_15_dialog_content = "PlayerName…",
  ui_story_9_9_1_16_dialog_content = "大丈夫だよ…ただ…またソラヴァンのことを思い出しちゃって。",
  ui_story_9_9_1_X16_dialog_content = "PlayerName…",
  ui_story_9_9_1_17_dialog_content = "…バイス。",
  ui_story_9_9_1_18_dialog_content = "また何かを感知したの？安心して、私たちがいるから！",
  ui_story_9_9_1_19_dialog_content = "その…もし嫌じゃなければ…これをあげる。",
  ui_story_9_9_1_20_dialog_content = "これは…？",
  ui_story_9_9_1_21_dialog_content = "ハンカチ…PlayerName、これを使って涙を拭いて。",
  ui_story_9_9_1_22_dialog_content = "ごめん、なぜだかわからないけど、僕…",
  ui_story_9_9_1_23_dialog_content = "PlayerName、私たちに謝る必要はないわ。",
  ui_story_9_9_1_24_dialog_content = "涙は弱者だけの専売特許ではないの。\n誰にだって感情を表に出したい時があるものよ。",
  ui_story_9_9_1_25_dialog_content = "うん。",
  ui_story_9_9_1_26_dialog_content = "何を感知したんだ？",
  ui_story_9_9_1_27_dialog_content = "たくさんの巨像の悲しい鳴き声だよ。\nとにかくたくさん、絶え間なく押し寄せるみたいな…",
  ui_story_9_9_1_28_dialog_content = "あの声はまるで、運命を嘆くようにも…\n親しい人をとむらうような感じにも聞こえた…",
  ui_story_9_9_1_29_dialog_content = "聞いていたら自分の心まで引っ張られるみたいで…悲しくなったんだ。",
  ui_story_9_9_1_30_dialog_content = "…ここ、他の巨像がいるのかな？",
  ui_story_9_9_1_31_dialog_content = "たぶん…さっき聞こえたのは本物じゃないと思う…",
  ui_story_9_9_1_32_dialog_content = "あの声は、巨像が天空ノ谷に残した…未練だと思う。",
  ui_story_9_9_1_33_dialog_content = "でも、どうしてこのタイミングで…？",
  ui_story_9_9_1_34_dialog_content = "…",
  ui_story_9_9_1_35_dialog_content = "PlayerName、グリードはまだ感知できる？",
  ui_story_9_9_1_36_dialog_content = "天空ノ谷の暗力が、どんどん濃くなってるから…",
  ui_story_9_9_1_37_dialog_content = "グリードのかすかな気配を、断続的に感知できるくらいかな。",
  ui_story_9_9_1_38_dialog_content = "今は…また何も捉えられなくなったみたい。",
  ui_story_9_9_1_39_dialog_content = "PlayerName、巨像の意識を感知できるなんて、うらやましいな…",
  ui_story_9_9_1_40_dialog_content = "感知能力は空の末裔の本能であり、生まれ持った才能だからね。\n君が光の力を使って戦えるのと同じだよ。",
  ui_story_9_9_1_41_dialog_content = "ずっと不思議に思ってたんだけど…",
  ui_story_9_9_1_42_dialog_content = "巨像を感知できるって、どんな感覚なの？",
  ui_story_9_9_1_43_dialog_content = "どんな…感覚？",
  ui_story_9_9_1_44_dialog_content = "そう聞かれると、どう答えていいかわからないや。",
  ui_story_9_9_1_45_dialog_content = "（17年間、ソラヴァンがいつもそばにいる日々が当たり前だった…）",
  ui_story_9_9_1_46_dialog_content = "（もし…もし、これから先もソラヴァンを感知できなかったら…）",
  ui_story_9_9_1_47_dialog_content = "PlayerName、もし答えたくないなら…無理に答えなくていいからね。",
  ui_story_9_9_1_48_dialog_content = "平気だよ、イヤだなんて思ってないから。",
  ui_story_9_9_1_49_dialog_content = "でも、今までずっと、自分でもちゃんと考えたことがなかったよ。",
  ui_story_9_9_1_50_dialog_content = "巨像を感知している時は…安心できて、暖かさを感じていたんだ…",
  ui_story_9_9_1_51_dialog_content = "まるで何でも分かりあえる友達同士みたいに、\n自分が何を考えてるのか、いつも理解してくれる。",
  ui_story_9_9_1_52_dialog_content = "そして、自分も向こうが何を言おうとしてるのか理解できる、唯一の相手なんだ。",
  ui_story_9_9_1_53_dialog_content = "まあ、たまにちょっとおせっかいに感じたこともあるけどね。",
  ui_story_9_9_1_54_dialog_content = "でも、それがなくなったら、何か欠けてる気がするっていうか…",
  ui_story_9_9_1_55_dialog_content = "つまり、巨像を感知できるっていうのは、\nそういう…幸せな感覚っていうのかな。",
  ui_story_9_9_1_56_dialog_content = "幸せな感覚…",
  ui_story_9_9_1_57_dialog_content = "私も「トラベラー」が何を考えてるのか、知りたいな…",
  ui_story_9_9_1_58_dialog_content = "えっ、もしかしてその「トラベラー」って、巨像なの？",
  ui_story_9_9_1_59_dialog_content = "はははっ！「トラベラー」は俺らR・Wの立派なメンバーだぜ！",
  ui_story_9_9_1_60_dialog_content = "昔、R・W砂漠で砂の中に半分埋もれてた外装を俺たちが見つけてよぉ。",
  ui_story_9_9_1_61_dialog_content = "それで半日間掘り続けたんだが、\nまさかぼろぼろの巨像が出てくるとは思わなかったな。",
  ui_story_9_9_1_62_dialog_content = "そいつをウチの技術班のヤツらが必死に修理して、\n何とか使えるようにしたんだ。",
  ui_story_9_9_1_63_dialog_content = "だがよ、「トラベラー」はバップにしか操縦させねぇんだ。",
  ui_story_9_9_1_64_dialog_content = "もし他のヤツに操縦させようとしても、尻尾すら持ち上げやがらねぇ。",
  ui_story_9_9_1_65_dialog_content = "私もずっと研究して、やっと「トラベラー」を操作できるようになったんだよ。",
  ui_story_9_9_1_66_dialog_content = "巨像を感知できないのに、動かせるものなの？",
  ui_story_9_9_1_67_dialog_content = "うーん、私もよくわからないけど…",
  ui_story_9_9_1_68_dialog_content = "でも、たまーに「トラベラー」の気持ちがわかるような気がするんだ。",
  ui_story_9_9_1_69_dialog_content = "「トラベラー」、見つかったばかりの時は、\nたぶん孤独を感じて、戸惑っていたんだと思う…",
  ui_story_9_9_1_70_dialog_content = "何を考えてるのかはわからなかったけど、いつもお喋りしてたんだ。",
  ui_story_9_9_1_71_dialog_content = "今は、R・Wでの暮らしが気に入ってるみたい。",
  ui_story_9_9_1_72_dialog_content = "ハハハ！そういうわけだ、感知できてもできなくても、\nバップにとっちゃあ問題じゃないのさ。",
  ui_story_9_9_1_73_dialog_content = "コイツの操縦技術があれば、それで十分だ！",
  ui_story_9_9_1_74_dialog_content = "考えもしなかったわ。砂漠をうろつく盗賊たちが、\n巨像を所有していることなんて。",
  ui_story_9_9_1_75_dialog_content = "嬢ちゃんよぉ、外の世界にはあんたの知らない事がたくさんあるんだぜ。",
  ui_story_9_9_1_76_dialog_content = "いつも城の中にこもってばかりは、よくねぇな！",
  ui_story_9_9_1_77_dialog_content = "…",
  ui_story_9_9_1_78_dialog_content = "後ろよ！",
  ui_story_9_9_1_79_dialog_content = "まさか…また光霊が変化した暗鬼？",
  ui_story_9_9_1_80_dialog_content = "でもこの数は…多すぎるよ…",
  ui_story_9_9_1_81_dialog_content = "どう考えても、昔白夜城の衛兵がここを偵察しに来て、\n全員実験品にされちまったってことだよな。",
  ui_story_9_9_1_82_dialog_content = "…！",
  ui_story_9_9_1_83_dialog_content = "PlayerName、指示を！これ以上苦しむ前に、終わらせてあげましょう。",
  ui_story_9_13_1_1_dialog_content = "白夜に捧ぐ。この地で安らかに眠らんことを…",
  ui_story_9_13_1_2_dialog_content = "安らかに…",
  ui_story_9_13_1_3_dialog_content = "PlayerName、あとどれくらいだ？",
  ui_story_9_13_1_4_dialog_content = "気配はかなり弱いけど、グリードは間違いなくこの近くにいるよ！",
  ui_story_9_13_1_X4_dialog_content = "「近く」ってどっちだ？左？右？それとも前か？",
  ui_story_9_13_1_5_dialog_content = "グォォ――！",
  ui_story_9_13_1_6_dialog_content = "前方から暗鬼の大群が来るわ！",
  ui_story_9_13_1_7_dialog_content = "PlayerName、どっちの方向か教えろ！俺が道を開けてやるぜ！",
  ui_story_9_13_2_1_dialog_content = "ここにも一つあったわ！あの暗鬼の死体の首の中ね。",
  ui_story_9_13_2_2_dialog_content = "はぁ…信じられない、どうして暗鬼ってこんなに汚いの？\n触りたくもないわ。",
  ui_story_9_13_2_3_dialog_content = "ネイルス、セファーを手伝ってくれるかい？",
  ui_story_9_13_2_4_dialog_content = "…",
  ui_story_9_13_2_5_dialog_content = "偉大なる真理の主よ、どうかお許しください…",
  ui_story_9_13_2_6_dialog_content = "教義では「不潔な物に関わってはならない」と説かれております。",
  ui_story_9_13_2_7_dialog_content = "しかしあなたの行跡を追うため、私はこれから見ても触れてもならないものに、\n関わらなければなりません…",
  ui_story_9_13_2_8_dialog_content = "戻ったら、3日間の沐浴であなたのお赦しを請います…",
  ui_story_9_13_2_9_dialog_content = "…",
  ui_story_9_13_2_10_dialog_content = "それはセティに渡すんだ。",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>シュッ…</color>",
  ui_story_9_13_2_12_dialog_content = "なんで必ずセティに渡さないといけないの？",
  ui_story_9_13_2_X12_dialog_content = "セティはコレが結構お気に入りみたいだけど、\n吐き出してくれなくなったらどうするの？",
  ui_story_9_13_2_X13_dialog_content = "ネイルスだって触れるんだし、そのまま持たせておけばいいじゃない。",
  ui_story_9_13_2_X14_dialog_content = "…",
  ui_story_9_13_2_13_dialog_content = "ビクトリア様、怒りの感情を抱いてしまった私にお赦しを…",
  ui_story_9_13_2_14_dialog_content = "セファー、この「シード」を甘く見てはいけないよ。",
  ui_story_9_13_2_X15_dialog_content = "小さく見えるかも知れないが、この中に含まれている暗力の量は、\n一般的な光霊ならもう、精神に重大な差障りが出ているものなんだ。",
  ui_story_9_13_2_X16_dialog_content = "僕たちは確かに体内の強力な光力で抵抗できているけれど、\nそれも影響を一時的に抑えているに過ぎないんだ。",
  ui_story_9_13_2_X17_dialog_content = "長い間触っていてはいけないよ。",
  ui_story_9_13_2_15_dialog_content = "わかったわ。これも一種の「戒律」ってことね。\n確かに甘く見てはいけないものみたいだわ。",
  ui_story_9_14_1_1_dialog_content = "あそこがそうだよ。",
  ui_story_9_14_1_2_dialog_content = "みんな、警戒を緩めないで！",
  ui_story_9_14_1_3_dialog_content = "これが…グリード？",
  ui_story_9_14_1_4_dialog_content = "なんだか怖い。「トラベラー」のほうが可愛いよ…",
  ui_story_9_14_1_5_dialog_content = "ダモクレスの攻撃に加えて墜落の衝撃も受けたから…",
  ui_story_9_14_1_6_dialog_content = "グリードの今の状態は…見るにたえないわね。",
  ui_story_9_14_1_7_dialog_content = "うん、しかも…さっきグリードの悲鳴が聞こえた時、\nまるでこれから死んでいくような感じだった。",
  ui_story_9_14_1_8_dialog_content = "早くスーモアを探そう。",
  ui_story_9_14_1_9_dialog_content = "待て！誰かこっちへ来るぜ。",
  ui_story_9_14_1_10_dialog_content = "スーモア！？",
  ui_story_9_14_1_11_dialog_content = "違う、スーモアじゃない…",
  ui_story_9_14_1_12_dialog_content = "<color=#FFB400>ノラ</color>！！",
  ui_story_9_14_1_13_dialog_content = "！！！",
  ui_story_9_14_1_14_dialog_content = "…！",
  ui_story_9_14_1_15_dialog_content = "ちょうど、私の計画を邪魔しにきたのが誰か気になってたけど…",
  ui_story_9_14_1_16_dialog_content = "あなたたちだったのね。",
  ui_story_9_14_1_17_dialog_content = "誰かを訪問するときはまず声をかけるって、教わらなかったの？",
  ui_story_9_14_1_18_dialog_content = "それはこちらの台詞よ。",
  ui_story_9_14_1_19_dialog_content = "ここは天空ノ谷よ、あなたが居ていい場所じゃない！",
  ui_story_9_14_1_20_dialog_content = "私がここにいる以上、ルールを決めるのはあなたたちじゃないわ。",
  ui_story_9_14_1_21_dialog_content = "てめぇ…",
  ui_story_9_14_1_22_dialog_content = "てっきりあの大火事で死んだと思ってたぜ！",
  ui_story_9_14_1_23_dialog_content = "だが、たとえ焼けて灰になろうが、絶対にその顔は忘れねぇ！\n名前を変えたからって逃げられると思うなよ！",
  ui_story_9_14_1_24_dialog_content = "…",
  ui_story_9_14_1_25_dialog_content = "おい！「<color=#FFB400>デニール</color>」！\nあの時、俺の妹にいったい何をしやがった！？",
  ui_story_9_14_1_26_dialog_content = "…",
  ui_story_9_14_1_27_dialog_content = "おい！聞こえてんのか！？",
  ui_story_9_14_1_28_dialog_content = "PlayerName、あなたの体から暗力を感じないわね…",
  ui_story_9_14_1_29_option_content = "君は一体誰？",
  ui_story_9_14_1_30_dialog_content = "まさか、本当に啓光の元研究員なの？",
  ui_story_9_14_1_31_dialog_content = "どうだっていいじゃない。",
  ui_story_9_14_1_32_dialog_content = "そんなに大事なこと？",
  ui_story_9_14_1_33_dialog_content = "私にはちっとも関係ないもの。",
  ui_story_9_14_1_34_dialog_content = "それより、PlayerName。答えなさいよ。あなた、「シード」は？",
  ui_story_9_14_1_35_dialog_content = "僕の背中に「シード」を植え付けたのは、やっぱり君だったんだね！",
  ui_story_9_14_1_36_dialog_content = "かゆくてたまらなかったよ。",
  ui_story_9_14_1_37_dialog_content = "かゆい？",
  ui_story_9_14_1_38_dialog_content = "それで？その症状はどれくらい続いたの？",
  ui_story_9_14_1_39_dialog_content = "ええと、大体…いや、なんでそんなこと答えないといけないの！？",
  ui_story_9_14_1_40_dialog_content = "PlayerName、気をつけて！彼女の思い通りになっちゃだめ。",
  ui_story_9_14_1_41_dialog_content = "どうやって背中の「シード」を取り出したの？",
  ui_story_9_14_1_42_dialog_content = "知りたい？なら先に質問に答えてよ――",
  ui_story_9_14_1_43_option_content = "どうして天空ノ谷にいる？",
  ui_story_9_14_1_44_dialog_content = "どうして光霊を暗鬼に変えたの！？\nなんでこんな残酷な実験をするの！？",
  ui_story_9_14_1_45_option_content = "どうして僕に「シード」を与えた？",
  ui_story_9_14_1_46_dialog_content = "僕が「シード」を取り出さなかったら、\n暗鬼になるところだったんだよね！？",
  ui_story_9_14_1_47_dialog_content = "質問が多すぎるわ。",
  ui_story_9_14_1_48_dialog_content = "PlayerName、私が答えられるのは\n「とてもがっかりした」という事だけよ。",
  ui_story_9_14_1_49_dialog_content = "私はあなたにチャンスを与えたの。\n力を手にしてこの世界の真実に近づけるよう、わざわざ誘ってあげたのに。",
  ui_story_9_14_1_50_dialog_content = "その重要性が理解できず、\n自分ですべてを台無しにしてしまうなんて、本当に残念ね。",
  ui_story_9_14_1_51_dialog_content = "時間の無駄だったわ。",
  ui_story_9_14_1_52_dialog_content = "PlayerName、もうあなたに知る機会はなくなったの。",
  ui_story_9_14_1_53_dialog_content = "そいつのデタラメなんか聞くな！",
  ui_story_9_14_1_54_dialog_content = "俺にははっきりわかる。\n目の前のコイツが、啓光連邦の研究員だった――「デニール」だ！",
  ui_story_9_14_1_55_dialog_content = "「デニール」？知らない名前ね。",
  ui_story_9_14_1_56_dialog_content = "とぼけやがって！",
  ui_story_9_14_1_57_dialog_content = "イブが長い間苦しんだのは、テメェに利用されたからだ！",
  ui_story_9_14_1_58_dialog_content = "イブ？",
  ui_story_9_14_1_59_dialog_content = "あぁ？ようやく思い出したか？",
  ui_story_9_14_1_60_dialog_content = "何となくね。でもよく覚えてないわ。",
  ui_story_9_14_1_61_dialog_content = "使った実験材料なんていっぱいあるもの。",
  ui_story_9_14_1_62_dialog_content = "テメェ…！",
  ui_story_9_14_1_63_dialog_content = "サメヤマ、落ち着いて。これは挑発よ。",
  ui_story_9_14_1_64_dialog_content = "ああ、俺は落ち着いてるさ！",
  ui_story_9_14_1_65_dialog_content = "冷静に、ヤツを粉々にブチのめす方法を100通り思いついたところだ！",
  ui_story_9_14_1_66_dialog_content = "私の見方だと、それはあなたが自滅するための100通りの方法ね。",
  ui_story_9_14_1_67_dialog_content = "まず痛い目に遭わせねぇと、上手く話もできねぇようだな！",
  ui_story_9_14_1_68_dialog_content = "…",
  ui_story_9_14_1_69_dialog_content = "この程度の実力で、よくそんな口を叩けたものだわ。",
  ui_story_9_14_1_70_dialog_content = "ボス！大丈夫！？",
  ui_story_9_14_1_71_dialog_content = "チッ、邪魔するな！",
  ui_story_9_14_1_72_dialog_content = "いま、何が起こったの…？",
  ui_story_9_14_1_73_dialog_content = "ノラがちょっと手を動かしただけで…サメヤマが吹き飛んだ！？",
  ui_story_9_14_1_74_dialog_content = "暗影術の一種ね。",
  ui_story_9_14_1_75_dialog_content = "ノラとやら、光霊の身分を捨て、化け物に成り果てているようね！",
  ui_story_9_14_1_76_dialog_content = "…ンのやろう！絶対に息の根を止めてやるからな！",
  ui_story_9_14_1_77_dialog_content = "静かになさい、身の程も知らないのに。",
  ui_story_9_14_1_78_dialog_content = "私、争い事は好きじゃないのよ。",
  ui_story_9_14_1_79_dialog_content = "そんなに遊びたいなら、\nあなたたちにふさわしい相手を用意してあげるわ。",
  ui_story_9_14_1_80_dialog_content = "狂角、お友だちよ。",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>タブハッド…は…潰えぬ！</anim>",
  ui_story_9_14_1_82_dialog_content = "狂角？あれ、どうみてもタブハッドじゃない！？",
  ui_story_9_14_1_X82_dialog_content = "名前なんて、実験の記録用につけたコードネームに過ぎないわ…",
  ui_story_9_14_1_83_dialog_content = "あの暗鬼を知っているの？",
  ui_story_9_14_1_84_dialog_content = "セクレペトスで、ヒイロ長官が致命傷を与えたはずなのに…",
  ui_story_9_14_1_85_dialog_content = "また死体を蘇らせたのね。",
  ui_story_9_14_1_86_dialog_content = "今までそうやって死体を復活させてきたのは、ノラだったのか！",
  ui_story_9_14_1_87_dialog_content = "単なる不良品の再利用よ。",
  ui_story_9_14_1_88_dialog_content = "でも、あなたたちと遊ぶぐらいの余力はあるでしょう。",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>グォァ――！！！</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>タブハッド…は…潰えぬ！</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>ウゥ…</anim>",
  ui_story_9_14_2_2_dialog_content = "気をつけて！ノラが動いた！",
  ui_story_9_14_2_3_dialog_content = "PlayerName、危ない！",
  ui_story_9_14_2_4_dialog_content = "…！",
  ui_story_9_14_2_5_dialog_content = "そうはさせねぇ――！",
  ui_story_9_14_2_6_dialog_content = "…",
  ui_story_9_14_2_7_dialog_content = "ボス…！",
  ui_story_9_14_2_8_dialog_content = "サメヤマ、大丈夫…？",
  ui_story_9_14_2_9_dialog_content = "何ともねぇ！ゲホッ…",
  ui_story_9_14_2_10_dialog_content = "堕落した光霊！それ以上足を踏み出せば、私がこの槍で正義を執行する！",
  ui_story_9_14_2_11_dialog_content = "そんなに興奮しないで。",
  ui_story_9_14_2_12_dialog_content = "私はただPlayerNameをよく観察したいだけよ。",
  ui_story_9_14_2_13_dialog_content = "ノラ！PlayerNameに何をするつもり！？",
  ui_story_9_14_2_14_dialog_content = "あなたたちが質問に答えてくれないから、\n自分で調べるしかないでしょう？",
  ui_story_9_14_2_15_dialog_content = "PlayerName、あなたの身体にはもう「シード」の痕跡がない。",
  ui_story_9_14_2_16_dialog_content = "最後にもう一度聞くわ。\nどうやって「シード」を取り出したの？",
  ui_story_9_14_2_17_dialog_content = "そっちこそ答えてよ。\nどうして「シード」を使った実験なんかするの？",
  ui_story_9_14_2_18_dialog_content = "PlayerName、まだ状況が分かってないようね。",
  ui_story_9_14_2_19_dialog_content = "あなたに知る資格はないし、私に条件を突きつける能力もない。",
  ui_story_9_14_2_20_dialog_content = "PlayerName、彼女と話しちゃダメ。",
  ui_story_9_14_2_21_dialog_content = "ん？",
  ui_story_9_14_2_22_dialog_content = "私がPlayerNameから取り出したの。何か問題ある？",
  ui_story_9_14_2_23_dialog_content = "どうして啓光にあなたみたいな裏切り者がいるの！？",
  ui_story_9_14_2_24_dialog_content = "バイス、ダメだ！",
  ui_story_9_14_2_25_dialog_content = "本当のことでしょうね。",
  ui_story_9_14_2_26_dialog_content = "ああっ！うぅ…",
  ui_story_9_14_2_27_dialog_content = "バイス！！！",
  ui_story_9_14_2_28_dialog_content = "ノラ！バイスをはなせ！！！",
  ui_story_9_14_2_29_dialog_content = "手を止めてあげてもいいわ。その代わり、誠意を見せなさい。",
  ui_story_9_14_2_30_dialog_content = "「シード」はどこへやったの？",
  ui_story_9_14_2_31_dialog_content = "…",
  ui_story_9_14_2_32_dialog_content = "（バイスを危険な目に遭わせるわけには…）",
  ui_story_9_14_2_33_dialog_content = "（話すしかないか…）",
  ui_story_9_14_2_34_dialog_content = "彼女を放して！知りたいことは答える、約束するから！",
  ui_story_9_14_2_X34_dialog_content = "いいわ。",
  ui_story_9_14_2_X35_dialog_content = "ハァ、ハァ…",
  ui_story_9_14_2_X36_dialog_content = "バイス！こっちだ！",
  ui_story_9_14_2_X37_dialog_content = "さあ、答えなさい。",
  ui_story_9_14_2_35_dialog_content = "僕の身体にあった「シード」は、\n白いカバンを手にした男に持ち去られたよ。",
  ui_story_9_14_2_36_dialog_content = "白いカバンの、男…",
  ui_story_9_14_2_37_dialog_content = "誰？",
  ui_story_9_14_2_38_dialog_content = "僕も知らない。なんで「シード」を持っていったのかもわからない。",
  ui_story_9_14_2_39_dialog_content = "でも僕に言ったんだ。\n「シード」は光霊を暗鬼に変化させることができるって。",
  ui_story_9_14_2_40_dialog_content = "ノラ、「シード」で僕を暗鬼にしようとしただけじゃない。\n白夜城の衛兵を暗鬼に変えたのも君だね！？",
  ui_story_9_14_2_41_dialog_content = "実験材料っていうのは、「シード」の実験体にされた被害者のことだ！",
  ui_story_9_14_2_42_dialog_content = "違う！？",
  ui_story_9_14_2_43_dialog_content = "あなたがそう自分で確信しているなら、聞く必要もないでしょうに。",
  ui_story_9_14_2_44_dialog_content = "違う、僕は知りたいんだ。どうしてそんな非道な実験をするの？",
  ui_story_9_14_2_45_dialog_content = "どうして光霊なのに、闇の勢力に手を染めようとする？",
  ui_story_9_14_2_46_dialog_content = "さっきも言ったけれど、PlayerName。\nあなたがすべてを知る機会は、もうないのよ。",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>ゴ――ウン……</color>",
  ui_story_9_14_2_48_dialog_content = "あら？時間のようね。",
  ui_story_9_14_2_49_dialog_content = "何の音？",
  ui_story_9_14_2_50_dialog_content = "…グリードの内部から聞こえてくる…",
  ui_story_9_14_2_51_dialog_content = "たぶん…巨像が動きを停めた音。",
  ui_story_9_14_2_52_dialog_content = "（さっきまでグリードの微弱な気配が感知できたのに、\n突然何も感知できなくなった）",
  ui_story_9_14_2_53_dialog_content = "（まさか…グリードは…死んでしまった？）",
  ui_story_9_14_2_54_dialog_content = "ノラ！グリードまで思い通りにするつもり！？",
  ui_story_9_14_2_55_dialog_content = "グリードに何をしたの！？",
  ui_story_9_14_2_56_dialog_content = "PlayerName、あなたは本当に質問が多いわね。",
  ui_story_9_14_2_57_dialog_content = "もし何が起こったのか知りたいなら、\n巨像の中に入って直接あなたの「<color=#FFB400>古いお友達</color>」に聞いてみれば？",
  ui_story_9_14_2_58_dialog_content = "ノラ！グリードの中に入っていったわ！",
  ui_story_9_14_2_59_dialog_content = "くそ！！戻ってきやがれ！！",
  ui_story_9_14_2_60_dialog_content = "「<color=#FFB400>古いお友達</color>」…？",
  ui_story_9_14_2_61_dialog_content = "…",
  ui_story_9_14_2_62_dialog_content = "スーモア…",
  ui_story_9_14_2_63_dialog_content = "<size=45>スーモアが、まだ生きてる！！！</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>白夜城内、診療所前</color>",
  ui_story_10_1_1_2_dialog_content = "白夜城のミッドタウンってこんにゃ感じだったんだにゃあ。",
  ui_story_10_1_1_S1_dialog_content = "建物が…どれもすごく豪華だにゃ。",
  ui_story_10_1_1_3_dialog_content = "ビビアンにはちょうどいい機会だし、ここでしばらくゆっくり休んでてほしいにゃ。\nそしたらフィリスももっと休めるにゃ…",
  ui_story_10_1_1_4_dialog_content = "ミャア？",
  ui_story_10_1_1_5_dialog_content = "新しい患者さんはどこ？すぐに行くよー！",
  ui_story_10_1_1_6_dialog_content = "ラファエル様、ここで飛び回るのはおやめください！",
  ui_story_10_1_1_7_dialog_content = "…行っちゃったにゃあ？",
  ui_story_10_1_1_8_dialog_content = "どうやら、フィリスの出番みたいだにゃ。",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_10_1_1_10_dialog_content = "ああ、この傷はいつになったら良くなるのでしょう。\nずっとここにいては、何もできませんね。",
  ui_story_10_1_1_11_dialog_content = "キュー！",
  ui_story_10_1_1_12_dialog_content = "慰めてくれてありがとう、キュリー。\n大丈夫よ。少し心配しているだけだから…",
  ui_story_10_1_1_13_dialog_content = "見回りをよろしくね。",
  ui_story_10_1_1_14_dialog_content = "キュー！",
  ui_story_10_1_1_15_dialog_content = "それから…",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>ガサゴソ…</color>",
  ui_story_10_1_1_17_dialog_content = "「猫ちゃん」、耳がずっと地面にこすれていますよ。",
  ui_story_10_1_1_18_dialog_content = "え？フィリスは別に床掃除してるわけじゃないにゃ。",
  ui_story_10_1_1_19_dialog_content = "ただ、地面の音で周りの人達の状況を確かめようと思っただけにゃ。",
  ui_story_10_1_1_20_dialog_content = "何を心配しているかは分かっています。",
  ui_story_10_1_1_21_dialog_content = "確かにこの部屋は私のために特別に用意されたものですが、\nもう隅々まで調べてあります…",
  ui_story_10_1_1_22_dialog_content = "監視はありませんよ。",
  ui_story_10_1_1_S2_dialog_content = "おそらく、私を白夜城にできるだけ長く足止めしておきたいだけでしょう。",
  ui_story_10_1_1_23_dialog_content = "どんな情報を持ってきたのですか？教えてください。",
  ui_story_10_1_1_24_dialog_content = "さすがはビビアン、一発で見破られちゃったにゃ。",
  ui_story_10_1_1_25_dialog_content = "<color=#FFB400>「ノラ」</color>に関する情報を手に入れて、すぐにここへ来たにゃ。",
  ui_story_10_1_1_26_dialog_content = "彼女に関する事がわかったのですか？",
  ui_story_10_1_1_27_dialog_content = "難しいにゃあ。",
  ui_story_10_1_1_28_dialog_content = "それに…内部のレポートだと、彼女は9年前に<color=#FFB400>「死んでいる」</color>にゃ。",
  ui_story_10_1_1_29_dialog_content = "9年前、シェルターがまるごと大火事で焼失した事件…",
  ui_story_10_1_1_30_dialog_content = "みんな、彼女はあの火事の中で死んだって思ってるにゃ。",
  ui_story_10_1_1_31_dialog_content = "でもあとになって、調査隊ががれきの中から\n暗鬼と光霊の死体を発見してるにゃ。",
  ui_story_10_1_1_32_dialog_content = "フィリス、ノラがPlayerNameの身体に\n<color=#FFB400>「シード」</color>を埋め込んだって聞いたとき…",
  ui_story_10_1_1_33_dialog_content = "すぐにピンときたにゃ。",
  ui_story_10_1_1_34_dialog_content = "ノラが当時研究していたものって、これと関係があるはずにゃ？",
  ui_story_10_1_1_35_dialog_content = "可能性は高いですね。\nそれに彼女は…<color=#FFB400>すでに暗鬼になってしまっています</color>。",
  ui_story_10_1_1_36_dialog_content = "ノラがまだ生きていると知ったとき、大元帥様に何か反応はありましたか？",
  ui_story_10_1_1_37_dialog_content = "にゃあ…それは…",
  ui_story_10_1_1_38_dialog_content = "どうしたのです？言いにくいことですか？",
  ui_story_10_1_1_39_dialog_content = "その、ビビアンは…大元帥様とノラの関係を知ってるはずにゃ…",
  ui_story_10_1_1_40_dialog_content = "懸念は理解できます。<color=#FFB400>ノラは大元帥様の妹</color>ですからね。",
  ui_story_10_1_1_41_dialog_content = "さすがはフィリスの長官だにゃあ。\nフィリスの心配ごとを一言だけで見抜いたにゃ。",
  ui_story_10_1_1_42_dialog_content = "それで、何が起こったのですか？",
  ui_story_10_1_1_43_dialog_content = "大元帥様は軍団長を連れて出ていったにゃ。\n名目上は軍団長会議だったけど…",
  ui_story_10_1_1_44_dialog_content = "フィリスは、何かが違うと思ったにゃ。",
  ui_story_10_1_1_45_dialog_content = "4人の軍団長は大元帥様が最も信頼する人物で、\n啓光で一番精鋭の戦士だにゃ？",
  ui_story_10_1_1_46_dialog_content = "ビビアンは、大元帥様がノラを探しにいくって思うかにゃ？",
  ui_story_10_1_1_47_dialog_content = "フィリス、あなたは暗鬼の情報については非常に敏感です。",
  ui_story_10_1_1_48_dialog_content = "しかし仲間の情報については…分析と処理がまだ甘いようですね。",
  ui_story_10_1_1_49_dialog_content = "にゃあ…",
  ui_story_10_1_1_50_dialog_content = "それなら直接答えを教えてほしいにゃ、\nフィリスは思考が止まっちゃったにゃ…",
  ui_story_10_1_1_51_dialog_content = "フィリス。私たちの大元帥様が、\n私的な感情で勝手な行動をされる人だと思いますか？",
  ui_story_10_1_1_52_dialog_content = "えーっ？フィリスは大元帥様を疑ってなんかないよ！ホントにゃ！",
  ui_story_10_1_1_53_dialog_content = "わかっていますよ…そうではありません、まずは聞くのです。",
  ui_story_10_1_1_54_dialog_content = "ノラの出現は、私たちにとって一種の合図。",
  ui_story_10_1_1_55_dialog_content = "捕食者が獲物を狙って攻撃態勢を取るとき…\nそれは同時に、捕食者が最も油断している瞬間でもあります。",
  ui_story_10_1_1_56_dialog_content = "なるほどにゃ！ビビアンの言いたいことはつまり、\nフィリスが大元帥様の計画を探る必要はないってことだにゃ？",
  ui_story_10_1_1_57_dialog_content = "大元帥様には大元帥様の考えがあるってことだにゃ。",
  ui_story_10_1_1_58_dialog_content = "ええ、本当に理解してくれているといいのですが。\nともかく、大元帥様に関しては、あまり邪推してはなりませんよ。",
  ui_story_10_1_1_59_dialog_content = "わかったにゃ。",
  ui_story_10_1_1_60_dialog_content = "じゃあ、フィリスは「シード」の調査を引き続きやったほうがいいのかにゃ？",
  ui_story_10_1_1_61_dialog_content = "無論です。",
  ui_story_10_1_1_62_dialog_content = "じゃあ、フィリスはバイスたちを探しにいってもいいのかにゃ？",
  ui_story_10_1_1_63_dialog_content = "あら？どうしてそのような結論になるのですか？",
  ui_story_10_1_1_64_dialog_content = "簡単だにゃ、「シード」の情報はバイスとPlayerNameがくれたんだにゃ！",
  ui_story_10_1_1_65_dialog_content = "ここに来る途中、グリードが撃墜されたって話を聞いたにゃ！",
  ui_story_10_1_1_66_dialog_content = "それと、数日前には巨像が白夜城から飛び立ったって！",
  ui_story_10_1_1_67_dialog_content = "バイスたちはきっと<color=#FFB400>グリードを追っていった</color>んだにゃ！",
  ui_story_10_1_1_68_dialog_content = "「シード」とグリードには何らかの関係があるにゃ。\nそれなら、直接グリードを調べにいったらいいんじゃにゃい？",
  ui_story_10_1_1_69_dialog_content = "本当に鋭いですね、フィリス…",
  ui_story_10_1_1_70_dialog_content = "あなたの言うとおりです。\nPlayerNameとバイスはグリードの所在地へと向かいました。",
  ui_story_10_1_1_71_dialog_content = "じゃあ、フィリスも行っていい？",
  ui_story_10_1_1_72_dialog_content = "先に確認しておきますが、遊びにいくわけではありませんね？",
  ui_story_10_1_1_73_dialog_content = "違うにゃ。フィリスは何だか良くない予感がするにゃ…",
  ui_story_10_1_1_74_dialog_content = "スーモアとノラは繋がってるにゃ。\n調査にしても、安全の問題にしても…",
  ui_story_10_1_1_75_dialog_content = "フィリスが一緒の方が絶対いいことあるにゃ。",
  ui_story_10_1_1_76_dialog_content = "それにノラの情報を色々探ってたら、\nフィリスも思わず毛が逆立ったにゃ！",
  ui_story_10_1_1_77_dialog_content = "もしPlayerNameとバイスがノラに捕まって、\n実験台にされたらどうしよう？って。",
  ui_story_10_1_1_78_dialog_content = "そういうことでしたか。あなたの考えはわかりました。",
  ui_story_10_1_1_79_dialog_content = "でも、そこまでバイスたちを心配することはありませんよ。",
  ui_story_10_1_1_80_dialog_content = "実は彼らが出発する前に、\nノラに遭遇する可能性があることについては話してあります。",
  ui_story_10_1_1_81_dialog_content = "そして何より重要な事実として、\n彼らには白夜城の護衛隊長、カレンが同行しています。",
  ui_story_10_1_1_82_dialog_content = "つまり…スーモアに関わる問題は、\nすでに白夜城側に引き継がれたということです。",
  ui_story_10_1_1_83_dialog_content = "えっ？そうだったんだにゃ…",
  ui_story_10_1_1_84_dialog_content = "それなら、フィリスは行かない方がいいのかにゃあ…",
  ui_story_10_1_1_85_dialog_content = "そうですねぇ…状況がはっきりわかるまでは、\nバイスからの連絡を待ちましょう。",
  ui_story_10_2_1_1_dialog_content = "えっと…",
  ui_story_10_2_1_2_dialog_content = "これからどうするの？",
  ui_story_10_2_1_3_dialog_content = "どうするって？そりゃあ追うに決まってんだろ！\nヤツが逃げるのを見てるつもりか？",
  ui_story_10_2_1_4_dialog_content = "まずは落ち着いて。",
  ui_story_10_2_1_5_dialog_content = "どう見ても、あれは私たちを中に誘い込もうとしているわ。",
  ui_story_10_2_1_6_dialog_content = "ンなこたぁわかってる！",
  ui_story_10_2_1_7_dialog_content = "追えば、ノラが仕掛けた罠に出くわすだろうな。",
  ui_story_10_2_1_8_dialog_content = "だがここで追わなきゃ、アイツを見逃すのと同じだ！",
  ui_story_10_2_1_9_dialog_content = "それから、お前らが追ってる<color=#FFB400>スーモア</color>ってヤツもな。",
  ui_story_10_2_1_10_dialog_content = "スーモアはまだ生きていて、グリードの中にいるってことだけはわかる！",
  ui_story_10_2_1_11_dialog_content = "でも、気配はすごく微弱だ。きっと重傷なんだと思う。",
  ui_story_10_2_1_12_dialog_content = "先走ってはだめよ。いっそ、この場所で張っていたほうが…",
  ui_story_10_2_1_13_dialog_content = "白夜城か啓光の支援を要請するってんじゃないだろうな？",
  ui_story_10_2_1_14_dialog_content = "無駄だろ。支援なんて待ってたら日が暮れちまうぜ。",
  ui_story_10_2_1_15_dialog_content = "あなたの憶測だけで判断しないでほしいわね。",
  ui_story_10_2_1_16_dialog_content = "ハッ、あんたを一人でこんな所に送り出してるんだ。態度はミエミエだろ？",
  ui_story_10_2_1_17_dialog_content = "こんだけの白夜城の兵士がここでくたばってるんだ。\nおエラ方はここがどんな状況か、把握はしてるはずだぜ。",
  ui_story_10_2_1_18_dialog_content = "支援なんか要請したところで、来ちゃくれねぇよ。",
  ui_story_10_2_1_19_dialog_content = "ねえ、ケンカはよくないよ…",
  ui_story_10_2_1_20_dialog_content = "助けを呼べば、うちのメンバーが来てくれるかも…",
  ui_story_10_2_1_21_dialog_content = "俺たちは偶然穴に落ちてここに来たんだ。\nあいつらが来るのを待ってたら、全員穴に落ちるまで待つことになるぞ！",
  ui_story_10_2_1_22_dialog_content = "そっか…みんな道がわからないし…",
  ui_story_10_2_1_23_dialog_content = "ノラが罠を仕掛けて僕たちを中に引き入れてから、一気に片付けるつもり…？",
  ui_story_10_2_1_24_dialog_content = "僕にはそうは思えないなぁ…",
  ui_story_10_2_1_25_dialog_content = "さっき戦ったとき、僕らはノラに指一本触れられなかった。",
  ui_story_10_2_1_26_dialog_content = "とてつもない強さを持っているのは明らかなのに、まるで…",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>僕たちを攻撃するつもりがなかった</color>ような…？",
  ui_story_10_2_1_28_dialog_content = "もしかして、あの人は本当にスーモアを見にきてほしいだけ？",
  ui_story_10_2_1_29_dialog_content = "それならそうと言ってくれればよかったのに…",
  ui_story_10_2_1_30_dialog_content = "PlayerName、ノラの考えてることが感知でわからないかな？",
  ui_story_10_2_1_31_dialog_content = "実は…もう試してみたんだけど…",
  ui_story_10_2_1_32_dialog_content = "ごめん。<color=#FFB400>ノラを直接感知することはできなかった</color>。",
  ui_story_10_2_1_33_dialog_content = "なんでだ？",
  ui_story_10_2_1_34_dialog_content = "僕にもどう説明していいかわからないんだ。けど…",
  ui_story_10_2_1_35_dialog_content = "相手の考えを感知するってことは、あまり簡単なことじゃないんだ。",
  ui_story_10_2_1_36_dialog_content = "距離とか、感知能力の強さとか、感知する対象が拒絶してるとか…\n色んな要素が感知の効果に影響を及ぼすんだ。",
  ui_story_10_2_1_37_dialog_content = "実は、今のところ、スーモアだけは特に感知がやりやすいんだ…",
  ui_story_10_2_1_38_dialog_content = "それに…どんどんやりやすくなってる。",
  ui_story_10_2_1_39_dialog_content = "僕が今感知で確認できるのは、\nスーモアが今、重傷で弱っているってことだけ…",
  ui_story_10_2_1_40_dialog_content = "バイス、カレン、僕は…",
  ui_story_10_2_1_41_dialog_content = "行きましょ！今までだってどんなに危険な状況でも突き進んできたじゃない。\n今日だって同じよ。",
  ui_story_10_2_1_42_dialog_content = "前へ進みましょう、すべてを明らかにするために。私が先導する。",
  ui_story_10_2_1_43_dialog_content = "入るんだな？俺より勢いあるじゃねぇか。",
  ui_story_10_2_1_44_dialog_content = "お前の言ってる事はスジが通ってるように聞こえるが、\n実際には何もハッキリしてることはねぇんだよな。",
  ui_story_10_2_1_45_dialog_content = "バイスとお前は仲がいいのは知ってるけどよ、\nなんであのカレンまでお前の言うことを聞いてくれるんだ？",
  ui_story_10_2_1_46_dialog_content = "僕の言うことを聞いてるわけじゃないよ…でも、バイスとカレンにはすごく感謝してる。\n今までずっと、二人が僕を助けてくれたんだ。",
  ui_story_10_2_1_47_dialog_content = "この事が全部終わったら、必ず二人にお礼がしたいと思ってるよ。",
  ui_story_10_2_1_48_dialog_content = "行こう…",
  ui_story_10_2_1_49_dialog_content = "これがグリード？",
  ui_story_10_2_1_50_dialog_content = "ヘッ、見た感じ、中は別に驚くこともないな。\nボロボロで全然迫力もねぇや。",
  ui_story_10_2_1_51_dialog_content = "白夜城に撃墜されたからよ。",
  ui_story_10_2_1_52_dialog_content = "知ってるよ。わざわざ強調しなくていい。",
  ui_story_10_2_1_53_dialog_content = "私はただあなたの疑問に答えてあげただけよ。\nどうしてボロボロなのか、疑問に思っていたでしょう？",
  ui_story_10_2_1_54_dialog_content = "エ、エヘン…その…グリードが\nエネルギーを使い果たしたのも原因の一つだと思う…",
  ui_story_10_2_1_55_dialog_content = "エヘン、ゴホ、ゴホゴホッ…",
  ui_story_10_2_1_56_dialog_content = "俺らに口を挟むのがそんなに怖いのかよ？\nそこまで大げさに咳き込まなくてもいいだろ…",
  ui_story_10_2_1_57_dialog_content = "違うよ…暗力のせいで…",
  ui_story_10_2_1_58_dialog_content = "ほとんど残骸なのに、\nまだこんなに濃密な暗力が中に残っているなんて…",
  ui_story_10_2_1_59_dialog_content = "グァ…",
  ui_story_10_2_1_60_dialog_content = "暗鬼の声？みんな気をつけて！",
  ui_story_10_2_1_61_dialog_content = "グォォ――！",
  ui_story_10_2_2_1_dialog_content = "グアアッ！",
  ui_story_10_2_2_2_dialog_content = "あっ！PlayerName、危ない！",
  ui_story_10_2_2_3_dialog_content = "俺に任せな！",
  ui_story_10_2_2_4_dialog_content = "大丈夫か？",
  ui_story_10_2_2_5_dialog_content = "え、あ、うん…ありがとう。",
  ui_story_10_2_2_6_dialog_content = "平気だよ、ズボンがちょっと焦げたくらいで…",
  ui_story_10_2_2_7_dialog_content = "ごめん、一匹取り逃がしたわ…",
  ui_story_10_2_2_8_dialog_content = "もう一匹！",
  ui_story_10_2_2_9_dialog_content = "グォォ――！",
  ui_story_10_2_2_10_dialog_content = "あれ？どこ行くの？逃げないでよ…",
  ui_story_10_2_2_11_dialog_content = "おい、どこ行くつもりだ！",
  ui_story_10_2_2_12_dialog_content = "グァ…",
  ui_story_10_2_2_13_dialog_content = "妙だな。コイツら目が見えてねぇのか？",
  ui_story_10_2_2_14_dialog_content = "確かに変ね。いつもなら、\n暗鬼は私たちを見かけた途端にすぐ襲いかかってくるはず。",
  ui_story_10_2_2_15_dialog_content = "でも、ここの暗鬼たちは襲ってくるっていうよりも…",
  ui_story_10_2_2_16_dialog_content = "逃げようとしてる。",
  ui_story_10_2_2_17_dialog_content = "ならいいじゃねぇか。\nザコに構ってねぇで、ノラを探してケリをつけようぜ。",
  ui_story_10_2_2_18_dialog_content = "ノラがしたことと関係があるかもしれないわ。\n警戒だけは緩めないようにしましょう。",
  ui_story_10_2_2_19_dialog_content = "うん、そうかもね。",
  ui_story_10_2_2_20_dialog_content = "やっぱり、暗鬼は処理しながら進んだほうがいいと思うわ。\n放っておいたら…",
  ui_story_10_2_2_21_dialog_content = "後で暗鬼に挟み撃ちされちゃうかもしれないわ。",
  ui_story_10_2_2_22_dialog_content = "PlayerName、ここの暗力はあなたにとって苦しいかもしれないけど…",
  ui_story_10_2_2_23_dialog_content = "感知能力を使って状況を調べてもらえないかしら？",
  ui_story_10_2_2_24_dialog_content = "やってみるよ。",
  ui_story_10_2_2_25_dialog_content = "…",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>ウ…ウ…</color>",
  ui_story_10_2_2_27_dialog_content = "ねぇ、どこかから嫌な感じの空気が流れて…",
  ui_story_10_2_2_28_dialog_content = "シーッ！静かにしろ。\nPlayerNameが集中してるのが見えないのか？",
  ui_story_10_2_2_29_dialog_content = "でもボス…ボスのほうが声が大きい…",
  ui_story_10_2_2_30_dialog_content = "…シーッ。",
  ui_story_10_2_2_31_dialog_content = "（暗力…）",
  ui_story_10_2_2_32_dialog_content = "（暗力が…一つの方向に集まろうとしている）",
  ui_story_10_2_2_33_dialog_content = "（気持ち悪い…薄くなったり濃くなったり…耐えられない…）",
  ui_story_10_2_2_34_dialog_content = "（暗鬼…暗鬼…）",
  ui_story_10_2_2_35_dialog_content = "（暗鬼ばかりだ）",
  ui_story_10_2_2_36_dialog_content = "（気持ち悪い…生臭い感じがする…）",
  ui_story_10_2_2_37_dialog_content = "（それに…）",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>ギシッ…</color>",
  ui_story_10_2_2_39_dialog_content = "（何の音？）",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>ギシッ</color>",
  ui_story_10_2_2_41_dialog_content = "（歯ぎしり？）",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>ギシッ</color>",
  ui_story_10_2_2_43_dialog_content = "（違う、何かを噛んでる…）",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>ギシッ</color>",
  ui_story_10_2_2_45_dialog_content = "（何か、ベトベトして臭うものだ…）",
  ui_story_10_2_2_46_dialog_content = "（生臭い…気持ち悪い…）",
  ui_story_10_2_2_47_dialog_content = "（それに全身が痛い…）",
  ui_story_10_2_2_48_dialog_content = "（何だろう…歯の間、それに舌の底に…）",
  ui_story_10_2_2_49_dialog_content = "（喉の奥にも詰まってる…泥のような物体…！？）",
  ui_story_10_2_2_50_dialog_content = "チッ…",
  ui_story_10_2_2_51_dialog_content = "暗鬼って、ホントに不味いわね。",
  ui_story_10_3_1_1_dialog_content = "オェッ――！",
  ui_story_10_3_1_2_dialog_content = "PlayerName！は、早く感知を止めて！",
  ui_story_10_3_1_3_dialog_content = "うぅ…ゴホ、ゴホ…",
  ui_story_10_3_1_4_dialog_content = "も…もう止めたよ…おえっ！",
  ui_story_10_3_1_5_dialog_content = "どうした？なんで感知能力でそんな事になった？",
  ui_story_10_3_1_6_dialog_content = "ゴホ、ゴホ！ごめん…生臭いにおいで…んんっ！",
  ui_story_10_3_1_7_dialog_content = "わかったわかった、もういい！",
  ui_story_10_3_1_8_dialog_content = "うーん…むせないように、一度全部吐いちゃったほうがいいよ。",
  ui_story_10_3_1_9_dialog_content = "バイス、空の末裔が感知能力を使うと、\nこんなに激しく反応するものなの？",
  ui_story_10_3_1_10_dialog_content = "ううん、前はここまでじゃなかったわ。\nでも、さっきPlayerNameが感知したものは…",
  ui_story_10_3_1_11_dialog_content = "特に異常なものだったみたいね。",
  ui_story_10_3_1_12_dialog_content = "グァ…",
  ui_story_10_3_1_13_dialog_content = "命令よ、こちらへ来なさい。",
  ui_story_10_3_1_14_dialog_content = "ぐうう…",
  ui_story_10_3_1_15_dialog_content = "命令よ、行きなさい。自分で上がっていくの。",
  ui_story_10_3_1_16_dialog_content = "グァ…",
  ui_story_10_3_1_17_dialog_content = "よろしい。",
  ui_story_10_3_1_18_dialog_content = "グア！",
  ui_story_10_3_1_19_dialog_content = "黙りなさい…踏んでるわよ…",
  ui_story_10_3_1_20_dialog_content = "グ…ガァ！",
  ui_story_10_3_1_21_dialog_content = "……",
  ui_story_10_3_1_22_dialog_content = "おとなしくなったわね。",
  ui_story_10_3_1_23_dialog_content = "ノラ…入ってこさせる時、もうちょっと慎重にできないの？",
  ui_story_10_3_1_24_dialog_content = "身体中が痛いのよ…その上こんな泥臭いやつらに\nぶつかってこられたら、たまったものじゃないわ。",
  ui_story_10_3_1_25_dialog_content = "何ですって？聞こえなかったわ。",
  ui_story_10_3_1_26_dialog_content = "聞こえないフリはやめて。",
  ui_story_10_3_1_27_dialog_content = "あなたの声はちゃんと聞こえてる…\n私の大声が聞こえないわけないでしょ？",
  ui_story_10_3_1_28_dialog_content = "あなたの声の大きさと私が聞こえないことに、関係があるの？",
  ui_story_10_3_1_29_dialog_content = "もし退屈でしょうがないなら、もっと食べさせてあげるわ。\nその間ちょっと話すくらいなら、構わないわよ。",
  ui_story_10_3_1_30_dialog_content = "こんな気色悪いもの、誰が…",
  ui_story_10_3_1_31_dialog_content = "怒りはあなたの成長を促進させるの。利用することを覚えなさい。",
  ui_story_10_3_1_32_dialog_content = "暗鬼を本気で食べ物だと思わないで。\n少し噛み砕いて暗力を吸収すればそれでいいの。",
  ui_story_10_3_1_33_dialog_content = "これが一番簡単な方法なのよ。\n食べ方がわからないだなんて、今さら言わせないわ。",
  ui_story_10_3_1_34_dialog_content = "甘く見ないで…",
  ui_story_10_3_1_35_dialog_content = "でも、こいつらの背中にある「シード」は硬すぎる…\n噛めたものじゃないわ。",
  ui_story_10_3_1_36_dialog_content = "硬いのは外殻だけよ。しっかりすり潰して。\nあなたの口にある暗鬼の牙は、思っているよりも頑丈よ。",
  ui_story_10_3_1_37_dialog_content = "わかってるわ…ちょっと愚痴を言いたくなっただけよ。",
  ui_story_10_3_1_38_dialog_content = "…",
  ui_story_10_3_1_39_dialog_content = "傷が回復してから、心にもかなり変化があったようね。",
  ui_story_10_3_1_40_dialog_content = "あなたを「称賛」してあげたいところだわ。",
  ui_story_10_3_1_41_dialog_content = "いきなり何の話？",
  ui_story_10_3_1_42_dialog_content = "いい目つきをするようになった。\nPlayerNameにはまだ使い所があるわ。",
  ui_story_10_3_1_43_dialog_content = "仲間には誘い損ねたけど、彼を活かしておけば、\nこれからもあなたの成長が見込める。",
  ui_story_10_3_1_44_dialog_content = "あなたも彼と白夜城に深手を負わされたことを、感謝すべきね。",
  ui_story_10_3_1_45_dialog_content = "次に皮肉を言ったら、あんたの牙を抜いてやるわ…",
  ui_story_10_3_1_46_dialog_content = "ちょっとした皮肉くらいでいちいちへそを曲げないで。\n心理的な忍耐力をもっとつけなさい。",
  ui_story_10_3_1_47_dialog_content = "何が言いたいの？",
  ui_story_10_3_1_48_dialog_content = "…あなたの古いお友達、PlayerNameがグリードに入ってきたわ。",
  ui_story_10_3_1_49_dialog_content = "あの空の末裔は、憎き仇にトドメを刺したいと強く思っているはず。",
  ui_story_10_3_1_50_dialog_content = "…",
  ui_story_10_3_1_51_dialog_content = "私が言えることはこれだけ。時間を稼いであげるわ。",
  ui_story_10_3_1_52_dialog_content = "あなたがエネルギーを吸収し終わって変化を終えるまで、足止めしてあげる。",
  ui_story_10_3_1_53_dialog_content = "でも、時間には限りがあるわ。",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>ギシッ</color>",
  ui_story_10_3_1_55_dialog_content = "あなたが自分自身を<color=#FFB400>「補完」</color>できるよう、祈っているわ。",
  ui_story_10_3_1_56_dialog_content = "それから、あなたのグリードみたいに…",
  ui_story_10_3_1_57_dialog_content = "ようやく白夜城までたどり着いておいて、\n結局すぐに大惨敗なんてことに、ならないようにね。",
  ui_story_10_3_1_58_dialog_content = "うるさいわね…",
  ui_story_10_3_1_59_dialog_content = "言われなくてもわかってるわ。",
  ui_story_10_3_1_60_dialog_content = "敵を見くびるのはあなたの欠点よ…",
  ui_story_10_3_1_61_dialog_content = "…",
  ui_story_10_3_1_62_dialog_content = "私がしくじったのは…PlayerNameの頭を過大評価しすぎたことだけ。",
  ui_story_10_3_1_63_dialog_content = "機会を手にして、力を獲得し、強者になる…",
  ui_story_10_3_1_64_dialog_content = "彼の頭の中では、そういうことよりバカみたいに\n当たり散らすほうが重要だったみたいね？",
  ui_story_10_3_1_65_dialog_content = "笑わせるわ…光霊を少しばかり仲間に従えたくらいで、強気になって…",
  ui_story_10_3_1_66_dialog_content = "私が寛大なのをいいことに、何度も私に刃向かうなんて…",
  ui_story_10_3_1_67_dialog_content = "あの腐った空の末裔たちと一緒で、\nものごとの良し悪しの区別もつかないのね。",
  ui_story_10_3_1_68_dialog_content = "どいつもこいつもバカだらけよ。",
  ui_story_10_3_1_69_dialog_content = "そういうことなら、もういいわ…",
  ui_story_10_3_1_70_dialog_content = "代償を払わせてから、後悔と恐怖の中で死なせてあげる。",
  ui_story_10_3_1_71_dialog_content = "良くなったか？何を感知したのか話してくれよ。",
  ui_story_10_3_1_72_dialog_content = "スーモアが暗鬼を食べてた…",
  ui_story_10_3_1_73_dialog_content = "は？とんでもないモンを感知したと思ってたが、暗鬼を食ってただけか。",
  ui_story_10_3_1_74_dialog_content = "心配するな。そいつは重症で、目が覚めたばかりなんだろ。\nずっと何も食ってないから餓えてたんじゃねぇか？",
  ui_story_10_3_1_75_dialog_content = "暗鬼を食べる？倒された暗鬼はすぐ粉々になるものだったはず…",
  ui_story_10_3_1_76_dialog_content = "新鮮なやつならちょっとくらいはいけるが、\nありゃあ獣のゲ●よりマズいって聞いたぜ。",
  ui_story_10_3_1_77_dialog_content = "暗鬼が食えるヤツの味覚と脳みそなんて、どうかしてるに違いねぇな。",
  ui_story_10_3_1_78_dialog_content = "でも今までで分かっている情報によれば、暗鬼は食事をする必要がないし、\n共食いするような習性もないはずよ。",
  ui_story_10_3_1_79_dialog_content = "彼女はたぶん…エネルギーを吸収してるんだ…濃厚な暗力を。",
  ui_story_10_3_1_80_dialog_content = "自分を治療する方法を探しているんだ…僕たちも急がないと…うっ…",
  ui_story_10_3_1_81_dialog_content = "うぅ…話を聞いてただけで吐き気がするよ。",
  ui_story_10_3_1_82_dialog_content = "僕は…もう大丈夫…吐けるものは何も残ってないよ…うぅ…",
  ui_story_10_3_1_83_dialog_content = "えずいてるのを見るだけでも恐ろしいよ…\nほら、あなた、全身が引きつってる。",
  ui_story_10_3_1_84_dialog_content = "…行こう。",
  ui_story_10_3_1_85_dialog_content = "待って、フラフラしてるじゃない！5分だけでも休んだほうがいいわ！",
  ui_story_10_3_1_86_dialog_content = "5分だけでいいから！",
  ui_story_10_3_1_87_dialog_content = "大丈夫だよ…まだみんなをサポートできる…",
  ui_story_10_3_1_88_dialog_content = "いいから。休めって言ったら休めよ。",
  ui_story_10_3_1_89_dialog_content = "お前らの追ってるスーモアってやつも、\n今ここで自分を治療することを選んだってことは、どこにも逃げやしねぇさ。",
  ui_story_10_3_1_90_dialog_content = "ほら、白湯を飲め。",
  ui_story_10_3_1_91_dialog_content = "食べ物で少しはエネルギー補給でもしたらどうだ？\nR・Wの特産品があるぜ。",
  ui_story_10_3_1_92_dialog_content = "バップ、トカゲの干物をみんなに持ってきてやれ！",
  ui_story_10_3_1_93_dialog_content = "そうそう。スーモアって人がエネルギー補給してるんだから、\n私たちもしっかり準備しておかないと。ほらっ。",
  ui_story_10_3_1_94_dialog_content = "気を抜きすぎないで。",
  ui_story_10_3_1_95_dialog_content = "私にはひと袋あればいいわ。先のほうを偵察してくる。",
  ui_story_10_3_1_96_dialog_content = "あ、うん。これ、便利でしょ。\n開ければすぐ食べられるし、甘辛で美味しくて体力補充にいいんだ。",
  ui_story_10_3_1_97_dialog_content = "ほらPlayerName、カレンも食べたのよ。あなたも少し食べて。",
  ui_story_10_3_1_98_dialog_content = "吐きすぎてお腹が空っぽじゃ、戦えないわよ。",
  ui_story_10_3_1_99_dialog_content = "悪いけど…吐いたばっかりは何も食べないのが一番だよ…でないとまた…",
  ui_story_10_3_1_100_dialog_content = "えっ？そう…じゃあ、水でも飲む？",
  ui_story_10_3_1_101_dialog_content = "もう1本あるぞ、ほら。",
  ui_story_10_3_1_102_dialog_content = "前方に暗鬼の群れと思われる動きを確認したわ。\nすぐこちらに向かってきそうね。",
  ui_story_10_3_1_103_dialog_content = "PlayerName、無理に指揮を執る必要はないわ。",
  ui_story_10_3_1_104_dialog_content = "私たちが戦っている間にひと休みしておいて。",
  ui_story_10_3_1_105_dialog_content = "おうよ。暗鬼は一匹たりとも近づけさせねぇから、安心して休んでろ！",
  ui_story_10_3_1_106_dialog_content = "来たわ、迎撃準備を！",
  ui_story_10_3_2_1_dialog_content = "PlayerName！無理に指揮を執らなくてもいいって！",
  ui_story_10_3_2_2_dialog_content = "今のうちに休んでおいてって言ったでしょ？",
  ui_story_10_3_2_3_dialog_content = "平気だから…もうだいぶ良くなったよ。",
  ui_story_10_3_2_4_dialog_content = "それに、暗鬼を感知するよりも、\nみんなを感知していたほうがずっといいよ。",
  ui_story_10_3_2_5_dialog_content = "暗鬼たち…また戦意を取り戻した？",
  ui_story_10_3_2_6_dialog_content = "ええ。退治しながら進むのが最良の選択ね。",
  ui_story_10_3_2_7_dialog_content = "行こう…もう大丈夫。",
  ui_story_10_3_2_8_dialog_content = "ごめんね、私が感知能力を使わせたせいで、ひどい思いを....",
  ui_story_10_3_2_9_dialog_content = "ううん、君のせいじゃないよ。",
  ui_story_10_3_2_10_dialog_content = "さっきは、暗鬼を食べてるところを\n急に感知してしまったから、ああなっただけだよ。",
  ui_story_10_3_2_11_dialog_content = "次に感知するときは、もう問題ないから。",
  ui_story_10_3_2_12_dialog_content = "おう、なかなか根性見せるじゃねぇか。",
  ui_story_10_3_2_13_dialog_content = "そういや、さっきノラは感知できたのか？",
  ui_story_10_3_2_14_dialog_content = "さっき感知したときは、ぼんやりと感じた気がする…",
  ui_story_10_3_2_15_dialog_content = "ノラとスーモアは、同じ場所にいるって。",
  ui_story_10_3_2_16_dialog_content = "なら行こうぜ。俺らの目的地は一緒だ。",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>ウ…ウ…</color>",
  ui_story_10_3_2_18_dialog_content = "この巨像、奥に行くほどひどい壊れ方をしてる…",
  ui_story_10_3_2_19_dialog_content = "いつ崩れてきてもおかしくない感じ。\n巨像がこんな風になるなんて、おかしいよ。",
  ui_story_10_3_2_20_dialog_content = "この巨像はダモクレスに落とされたんだ。",
  ui_story_10_3_2_21_dialog_content = "しかも、スーモアにエネルギーを搾り取られてる。",
  ui_story_10_3_2_22_dialog_content = "この巨像はもう、<color=#FFB400>「死んで」</color>しまっているんだ…",
  ui_story_10_3_2_23_dialog_content = "つまり、スーモアはこの巨像のナビゲーターなのに…",
  ui_story_10_3_2_24_dialog_content = "自分の手で自分の巨像を「殺した」の？",
  ui_story_10_3_2_25_dialog_content = "暗鬼だって共食いはしないってのに、そいつはやる。\nこんな胸くそ悪いことまでやれるってのかよ。",
  ui_story_10_3_2_26_dialog_content = "その女が巨像をぶっ壊してもおかしくねえってのはわかる。\nエネルギーを吸収するのも普通のことだ。",
  ui_story_10_3_2_27_dialog_content = "だが、どんだけひでぇ事をしてるか、\nPlayerNameなら俺たちよりはっきり理解してるはずだよな。",
  ui_story_10_3_2_28_dialog_content = "行こう、彼女の治療を終わらせるわけにはいかない…",
  ui_story_10_7_1_1_dialog_content = "暗力を更に高めたいのなら、吸収するのが手っ取り早いわ。",
  ui_story_10_7_1_2_dialog_content = "でも、すべての暗鬼が暗力を吸収する能力を持っているわけではない…",
  ui_story_10_7_1_3_dialog_content = "…",
  ui_story_10_7_1_4_dialog_content = "あら、もう眠ってしまったの？今回の実験は成功しそうね。",
  ui_story_10_7_1_5_dialog_content = "この前、力について私に聞いてきたのは、誰だったかしらね…ああ、思い出した。",
  ui_story_10_7_1_6_dialog_content = "白夜城の誰かだったわね。虫の尻尾みたいなのが生えてたあの2人…\n名前はなんだっけ？確か、スーモアに…",
  ui_story_10_7_1_7_dialog_content = "<color=#FFB400>「ボアドム」</color>？",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>ウ…ウ…</color>",
  ui_story_10_7_1_9_dialog_content = "また…嫌な感じの空気が？",
  ui_story_10_7_1_10_dialog_content = "ちがうわ…これは…",
  ui_story_10_7_1_11_dialog_content = "うぅ…うぅ…",
  ui_story_10_7_1_12_dialog_content = "泣き声？",
  ui_story_10_7_1_13_dialog_content = "暗鬼って泣くことがあるの？",
  ui_story_10_7_1_14_dialog_content = "下がって。来るわ。",
  ui_story_10_7_1_15_dialog_content = "こ、この暗鬼…怖いよ…",
  ui_story_10_7_1_16_dialog_content = "待って…この暗鬼、どこかで見たことがあるような気がする。",
  ui_story_10_7_1_17_dialog_content = "まさか…まさか、また光霊が変化した暗鬼じゃないよね？",
  ui_story_10_7_1_18_dialog_content = "この見た目、木の根のような肢体に…この声…思い当たるのは…",
  ui_story_10_7_1_19_dialog_content = "あの姉妹…<color=#FFB400>スイェート</color>と<color=#FFB400>シャイア</color>！\n最期には怪物に成り果ててしまった…",
  ui_story_10_7_1_20_dialog_content = "姉妹？ってことは2人…でもこの暗鬼は1匹だよ？",
  ui_story_10_7_1_21_dialog_content = "僕たちは、この目で2人が融合するところを見たんだ。",
  ui_story_10_7_1_22_dialog_content = "そう。彼女たちは「あの方が私たちに新たな力を授けてくれた」と言って\n…こうなったの。",
  ui_story_10_7_1_23_dialog_content = "うぅ…うぅ…",
  ui_story_10_7_1_24_dialog_content = "ねえ、こっちに向かってきてるけど、すごく遅いよ…こっちから迎撃する？",
  ui_story_10_7_1_25_dialog_content = "う…う…ころ…",
  ui_story_10_7_1_26_dialog_content = "ころ…？「殺す」って言ってる？私たちのことかな？",
  ui_story_10_7_1_27_dialog_content = "違う…彼女たちは、解放されたいのよ。",
  ui_story_10_7_1_28_dialog_content = "彼女たちが、言っていたことよ…\n<color=#FFB400>「私たちを殺して」</color>と。",
  ui_story_10_7_1_29_dialog_content = "今もまた、苦しんでいるようね…",
  ui_story_10_7_1_30_dialog_content = "死者の屍体をここまで持ってきて、再利用…",
  ui_story_10_7_1_31_dialog_content = "下劣極まりない手段に際限なく手を染める！正気じゃないわ！",
  ui_story_10_7_1_32_dialog_content = "ううっ――！",
  ui_story_10_7_1_33_dialog_content = "こんな状態では、もはや意識や理性は残っていないでしょうね。",
  ui_story_10_7_1_34_dialog_content = "2人を倒しましょう！",
  ui_story_10_7_1_35_dialog_content = "そして悲劇を生み出す元凶を、墓場に送る！",
  ui_story_10_7_2_1_dialog_content = "し、静まった？",
  ui_story_10_7_2_2_dialog_content = "ええ。彼女たちは死んだわ…もう一度。",
  ui_story_10_7_2_3_dialog_content = "バイス、PlayerName。何か火を付けられるものを探しましょう。",
  ui_story_10_7_2_4_dialog_content = "2人を火葬するわ。",
  ui_story_10_7_2_5_dialog_content = "彼女たちが、<color=#FFB400>グスド</color>のように安らかに眠れるよう…",
  ui_story_10_7_2_6_dialog_content = "ええ。辺りを探してみるわ。",
  ui_story_10_7_2_7_dialog_content = "グスドってのは誰だ？",
  ui_story_10_7_2_8_dialog_content = "元白夜城の騎士で、スイェートの恋人よ。",
  ui_story_10_7_2_9_dialog_content = "彼もスイェートと同じように暗鬼側についた、でも最後は…",
  ui_story_10_7_2_10_dialog_content = "自らを犠牲にして、私たちを庇った。",
  ui_story_10_7_2_11_dialog_content = "また白夜城…こんな時にアレだけどよ、一つ聞いていいか？",
  ui_story_10_7_2_12_dialog_content = "なんでお前ら白夜城の連中から、\nわざわざ暗鬼側につくヤツらが出てくるんだ？",
  ui_story_10_7_2_13_dialog_content = "別に暗鬼に襲われる心配もする必要ねぇし、\n暮らしが大変ってわけでもねぇだろ。",
  ui_story_10_7_2_14_dialog_content = "これって大問題じゃねぇのか？",
  ui_story_10_7_2_15_dialog_content = "サメヤマ、ここにいる人たちは\nみんな同じ目標のために行動している仲間よ。",
  ui_story_10_7_2_16_dialog_content = "そんな事は聞かないでほしいわ。",
  ui_story_10_7_2_17_dialog_content = "構わないわ。",
  ui_story_10_7_2_18_dialog_content = "何となく聞いてみただけさ。\n白夜城のやつに会う機会なんて、めったにねぇからな。",
  ui_story_10_7_2_19_dialog_content = "ああそうだ、俺の火でも構わねぇなら、\n火葬するのを手伝ってやってもいいぜ。",
  ui_story_10_7_2_20_dialog_content = "この事については私がしっかり責任を持つわ。お構いなく。",
  ui_story_10_7_2_21_dialog_content = "あなたの手は借りない。",
  ui_story_10_7_2_22_dialog_content = "手を出すつもりはねぇよ。お前がそう思うなら、それでいい。",
  ui_story_10_7_2_23_dialog_content = "俺は周りを見張ってくる。",
  ui_story_10_7_2_24_dialog_content = "…",
  ui_story_10_7_2_25_dialog_content = "その、私も何か燃えるものを持ってくるから…",
  ui_story_10_7_2_26_dialog_content = "あの、ボスはときどき過激なところがあって、\n思ったことをすぐに言うタイプだけど…",
  ui_story_10_7_2_27_dialog_content = "別に悪気があるわけじゃないの。",
  ui_story_10_7_2_28_dialog_content = "ええ。わかってるわ。",
  ui_story_10_7_2_29_dialog_content = "火をつけましょう。",
  ui_story_10_7_2_30_dialog_content = "白夜に捧ぐ…",
  ui_story_10_7_2_31_dialog_content = "スイェート、シャイア。自由を求め、良からぬ道へ足を踏み入れてしまった者へ。\n願わくば、安らかな眠りの後、再び自由を手にせんことを。",
  ui_story_10_7_2_32_dialog_content = "彼女らを惑わせた者こそ、裁きを受けるべき者である。",
  ui_story_10_7_2_33_dialog_content = "次に埋葬すべきは諸悪の根源、<color=#FFB400>スーモア</color>ね。",
  ui_story_10_7_2_34_dialog_content = "どっちの方向に進めばいいか、探してみようか…",
  ui_story_10_7_2_35_dialog_content = "PlayerName？また感知能力を使ってるの？",
  ui_story_10_7_2_36_dialog_content = "そうだよ…",
  ui_story_10_7_2_37_dialog_content = "すぐに止めて！もしまた影響を受けたら…",
  ui_story_10_7_2_38_dialog_content = "ッ…",
  ui_story_10_7_2_39_dialog_content = "PlayerName！？",
  ui_story_10_7_2_40_dialog_content = "先生…",
  ui_story_10_7_2_41_dialog_content = "待って…何か見える…",
  ui_story_10_7_2_42_dialog_content = "大丈夫、なんとか探ってみるから…心配しないで…",
  ui_story_10_7_2_43_dialog_content = "ハンデル先生…",
  ui_story_10_7_2_44_dialog_content = "いったい何をしたのです？どうしてこんなことを！？",
  ui_story_10_7_2_45_dialog_content = "どうして同級生を死なせたのです？答えなさい！",
  ui_story_10_7_2_46_dialog_content = "先生、私は何もしてません。",
  ui_story_10_7_2_47_dialog_content = "私はただ、自分の勇気を証明しただけ…",
  ui_story_10_7_2_48_dialog_content = "何を馬鹿なことを！？",
  ui_story_10_7_2_49_dialog_content = "自分の勇気を証明するために？同級生を死なせたと！？",
  ui_story_10_7_2_50_dialog_content = "まただわ。先生はいつも人の言うことを半分聞いただけで、\n勝手に決めつける…",
  ui_story_10_7_2_51_dialog_content = "スーモア！？",
  ui_story_10_7_2_52_dialog_content = "…いいでしょう。話してみなさい。",
  ui_story_10_7_2_53_dialog_content = "みんなが私に賭けをしようと言ってきて、\n私はただそれに同意しただけよ。",
  ui_story_10_7_2_54_dialog_content = "みんなバカだったから、\n自分たちにもう暗鬼を倒せる実力があると勘違いしたの。",
  ui_story_10_7_2_55_dialog_content = "ならいいわ、賭けをしましょうって。\n誰が外に行く勇気があるか試そうって。",
  ui_story_10_7_2_56_dialog_content = "そんな理由で？",
  ui_story_10_7_2_57_dialog_content = "先生、私たちはちょっと外を見てみようと思っただけ。\n誰も本当に暗鬼に遭遇するなんて思わなかった…",
  ui_story_10_7_2_58_dialog_content = "あいつらが私をのけ者にして！馬鹿にして！\n私は感知が苦手だからって！",
  ui_story_10_7_2_59_dialog_content = "先生はいつも人の潜在能力を軽く見てはいけないって言ってた。\nあの子たちは聞いたの？",
  ui_story_10_7_2_60_dialog_content = "全然聞いてないじゃない！",
  ui_story_10_7_2_61_dialog_content = "だから私が証明してやったのよ！生き残ったのは私！",
  ui_story_10_7_2_62_dialog_content = "私が一番強いのよ！",
  ui_story_10_7_2_63_dialog_content = "あぁ…",
  ui_story_10_7_2_64_dialog_content = "あなたが逃げてこられたのは、運が良かったからです！",
  ui_story_10_7_2_65_dialog_content = "スーモア、もう何度も言ったはずですよ。",
  ui_story_10_7_2_66_dialog_content = "私たち空の末裔は、常に平和を愛する種族なのです。",
  ui_story_10_7_2_67_dialog_content = "誰かに何かを証明する必要などありません。",
  ui_story_10_7_2_68_dialog_content = "力の優劣など問題ではないのです。\n大事なのは互いを支え合い、外の世界の危険に協力して立ち向かうことです。",
  ui_story_10_7_2_69_dialog_content = "立ち向かう？先生の言うそれって、\n天空ノ谷に閉じこもって出ようとしないこと？",
  ui_story_10_7_2_70_dialog_content = "そうではありません。何度もあなたに注意してきたことでしょう…",
  ui_story_10_7_2_71_dialog_content = "天空ノ谷の外にはたくさんの暗鬼がいます。",
  ui_story_10_7_2_72_dialog_content = "私たちは光霊と違って、光力で戦う能力を持っていないのです。",
  ui_story_10_7_2_73_dialog_content = "少しでも強力な暗鬼に出くわせば、対抗する力はないも同然なのです。",
  ui_story_10_7_2_74_dialog_content = "でも、私たちには天空ノ谷と巨像があります。",
  ui_story_10_7_2_75_dialog_content = "天空ノ谷が私たちを守っていて、\n巨像が上空に飛べば暗鬼の攻撃を免れることもできるのです。",
  ui_story_10_7_2_76_dialog_content = "そして何より、私たちには<color=#FFB400>感知能力</color>があります。\nこれこそ、空の末裔特有の力なのです。",
  ui_story_10_7_2_77_dialog_content = "私たちは光の軌跡を感じ取り、仲間の考えを理解することで\n危険な敵を察知することができます。",
  ui_story_10_7_2_78_dialog_content = "でもあなたたちには経験がなく、能力も不十分です。\n感知能力を活用して偵察することを覚えなければ、危険を回避することができません。",
  ui_story_10_7_2_79_dialog_content = "何も知らずに天空ノ谷を出ようとするなんて、\n死ににいくようなものでしょう？",
  ui_story_10_7_2_80_dialog_content = "偵察、回避…ここにいる人たちはみんなそればっかり！",
  ui_story_10_7_2_81_dialog_content = "もし暗鬼がここを襲ったらどうすればいいのかなんて、\n考えたこともないの！？",
  ui_story_10_7_2_82_dialog_content = "天空ノ谷が永遠に私たちを守ってくれるとでも思ってるの！？",
  ui_story_10_7_2_83_dialog_content = "もしその時が来たらどうするの？巨像に乗って逃げる？どこに？",
  ui_story_10_7_2_84_dialog_content = "「出ればすぐに殺される」ような外に逃げるっていうの？",
  ui_story_10_7_2_85_dialog_content = "そんなことは言っていません！",
  ui_story_10_7_2_86_dialog_content = "何度も教えたはずです！巨像さえあれば…",
  ui_story_10_7_2_87_dialog_content = "もういい…全部分かったの。",
  ui_story_10_7_2_88_dialog_content = "先生、私たち空の末裔が平和を愛するなんて言うのは…\n私たちに戦う力がないから。",
  ui_story_10_7_2_89_dialog_content = "はぁ…今はまだわからないのも、無理はありません。",
  ui_story_10_7_2_90_dialog_content = "いずれ、わかるようになります…",
  ui_story_10_7_2_91_dialog_content = "わからないわ…これから先だってずっと…",
  ui_story_10_7_2_92_dialog_content = "もう行って、先生。",
  ui_story_10_7_2_93_dialog_content = "私は懺悔なんてしない。",
  ui_story_10_7_2_94_dialog_content = "…あなたには頭を冷やす時間が必要なようです。",
  ui_story_10_7_2_95_dialog_content = "長老がすでに調査のために人を送ってきています。",
  ui_story_10_7_2_96_dialog_content = "私は、あなたが故意に同級生を死なせたのではないと信じています…",
  ui_story_10_7_2_97_dialog_content = "しかし、長老があなたへの罰を決定するまで、\n私にはあなたをここに閉じ込めておくしかありません。",
  ui_story_10_7_2_98_dialog_content = "それから、この本はあなたのお友達から渡してほしいと頼まれたものです。",
  ui_story_10_7_2_99_dialog_content = "お友達？誰？私に友達なんて…",
  ui_story_10_7_2_100_dialog_content = "<color=#FFB400>モンドル</color>君です。とても心配していましたよ。\n彼も昔は、成績が良くありませんでした。",
  ui_story_10_7_2_101_dialog_content = "彼ならあなたの境遇を理解できますから、\n友達になりたいと思っているのでしょう。",
  ui_story_10_7_2_102_dialog_content = "私を、心配？",
  ui_story_10_7_2_103_dialog_content = "スーモア…いつか気づいてくれることを願っています。\nあなたはみんなに愛されているのだと。",
  ui_story_10_7_2_104_dialog_content = "謹慎期間中、しっかりと反省してください。\n皆の期待を無下にしないことを願っています。",
  ui_story_10_7_2_105_dialog_content = "…",
  ui_story_10_7_2_106_dialog_content = "<color=#FFB400>「みんなに愛されている」</color>ことに気づけ？",
  ui_story_10_7_2_107_dialog_content = "いつもそういういい加減な事ばかり、うっとうしい…",
  ui_story_10_7_2_108_dialog_content = "…",
  ui_story_10_7_2_109_dialog_content = "…私に本…",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>『エイダと巨像』</color>！？",
  ui_story_10_7_2_111_dialog_content = "何よこの本！？私が巨像を感知できないのを知ってて、バカにするつもり！？",
  ui_story_10_7_2_112_dialog_content = "…",
  ui_story_10_7_2_113_dialog_content = "モンドル…",
  ui_story_10_7_2_114_dialog_content = "ああ、私より紅い髪で、私より弱かったヤツね。",
  ui_story_10_7_2_115_dialog_content = "きっと私と同じで巨像を感知できないのね。",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>チャリン</color>",
  ui_story_10_7_2_117_dialog_content = "なによこれ？",
  ui_story_10_7_2_118_dialog_content = "<color=#FFB400>鍵</color>！？",
  ui_story_10_7_2_119_dialog_content = "チッ、こんな扉…鍵なんか無くたって、すぐに壊せるわ…",
  ui_story_10_8_1_1_dialog_content = "更に「シード」の暗力を高めれば…",
  ui_story_10_8_1_2_dialog_content = "暗力による高揚感が強化される。",
  ui_story_10_8_1_3_dialog_content = "そして次第に判別能力を喪失する。",
  ui_story_10_8_1_4_dialog_content = "暗力を獲得した実験体は、\n往々にして強烈な自己欲求を剥き出しにする。",
  ui_story_10_8_1_5_dialog_content = "その際、実験体の自主的な行動に最も影響を与えやすいものは、\n何かに対する執着…",
  ui_story_10_8_1_6_dialog_content = "焦らなくていい。感知能力はゆっくり高めていけばいいのです。",
  ui_story_10_8_1_7_dialog_content = "グリードは少し特別ですから、\n短期間の間に最適なナビゲーターを見つけるのは難しいでしょう。",
  ui_story_10_8_1_8_dialog_content = "頑張って勉強し、強くなれば、必ず機会が訪れますから…",
  ui_story_10_8_1_9_dialog_content = "グリードは…どこ…",
  ui_story_10_8_1_10_dialog_content = "巨像…",
  ui_story_10_8_1_11_dialog_content = "巨像…",
  ui_story_10_8_1_12_dialog_content = "普通の巨像…",
  ui_story_10_8_1_13_dialog_content = "これじゃない…",
  ui_story_10_8_1_14_dialog_content = "これでもない…",
  ui_story_10_8_1_15_dialog_content = "私に何をしろって…？",
  ui_story_10_8_1_16_dialog_content = "それらの動力源を破壊し、一つだけを残せ。",
  ui_story_10_8_1_17_dialog_content = "これは命令だ。",
  ui_story_10_8_1_18_dialog_content = "動力源を破壊…",
  ui_story_10_8_1_19_dialog_content = "グリード以外の、すべての巨像の動力源を破壊…",
  ui_story_10_8_1_20_dialog_content = "見つけたわ…",
  ui_story_10_8_1_21_dialog_content = "意識モジュールを破壊すれば、私の言うことを聞くのよね？",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>エンジンセルフチェック…異常なし。起動中…</color>",
  ui_story_10_8_1_23_dialog_content = "真っ黒で、強くて、特別な…",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>16%……33%……</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>私の…グリード。</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%、起動成功。</color>",
  ui_story_10_8_1_27_dialog_content = "できた！",
  ui_story_10_8_1_28_dialog_content = "グリードさえあれば…",
  ui_story_10_8_1_29_dialog_content = "スー…モア…",
  ui_story_10_8_1_30_dialog_content = "！？",
  ui_story_10_8_1_31_dialog_content = "この声は！？",
  ui_story_10_8_1_32_dialog_content = "ずっと聞こえていただろうに…まったく礼儀がなっておらんな！！",
  ui_story_10_8_1_33_dialog_content = "お前の返答は「はい、あなた様のご命令を拝聴します、フィジェロ様」だ！",
  ui_story_10_8_1_34_dialog_content = "はい…<color=#FFB400>フィ、フィジェロ様</color>…",
  ui_story_10_8_1_35_dialog_content = "復唱することもできんのか？愚か物め…",
  ui_story_10_8_1_36_dialog_content = "キキキッ！だがまあいい。お前と張り合うつもりはない。",
  ui_story_10_8_1_37_dialog_content = "今のお前は、我らにとって特別な存在なのだからな。",
  ui_story_10_8_1_38_dialog_content = "お前は暗鬼となって間もないから、\n何が起きたのか理解していないだろう。",
  ui_story_10_8_1_39_dialog_content = "これは暗鬼の意思疎通方法だ。\n母上が我々にくださった能力であるぞ。",
  ui_story_10_8_1_40_dialog_content = "たとえ遠くにいようとも、声を直接お前に届けることができる…",
  ui_story_10_8_1_41_dialog_content = "母上が、くださった能力？",
  ui_story_10_8_1_42_dialog_content = "覚えておけ。「母上」の意志がお前を選び、\n機会を与え、力をくださったのだ。",
  ui_story_10_8_1_43_dialog_content = "これほど早く「シード」に適応し力を得たということは、\n「母上」の眼光が確かであったということ。",
  ui_story_10_8_1_44_dialog_content = "だが、今のお前にはこれ以上のことを知る資格がまだない。",
  ui_story_10_8_1_45_dialog_content = "より強くなり、より貢献することで\n「母上」の教えを賜る資格が得られるのだ。",
  ui_story_10_8_1_46_dialog_content = "答えろ。命令は完了したのか？",
  ui_story_10_8_1_47_dialog_content = "完了しました。",
  ui_story_10_8_1_48_dialog_content = "よろしい。ならば、お前の巨像を私の近くまで動かしてみろ。",
  ui_story_10_8_1_49_dialog_content = "暗鬼の大軍が予定通り天空ノ谷に突入した。\n審判の時は間もなくだ。",
  ui_story_10_8_1_50_dialog_content = "お前に与えられた時間もわずかだけだ…\n忘れるな、お前にはまだ、使者としての使命がある。",
  ui_story_10_8_1_51_dialog_content = "え…使者？",
  ui_story_10_8_1_S1_dialog_content = "そうだ。お前が「力を得る資格がある」と思う、\nその空の末裔のもとに私を連れていけ。",
  ui_story_10_8_1_52_dialog_content = "<color=#FFB400>救済される</color>チャンスを直々に与えてやる。",
  ui_story_10_8_1_S2_dialog_content = "…",
  ui_story_10_8_1_S3_dialog_content = "スーモア、なぜ口ごもるのだ？",
  ui_story_10_8_1_S4_dialog_content = "なんだか…急に…痒くなって…",
  ui_story_10_8_1_S5_dialog_content = "痒い？",
  ui_story_10_8_1_S6_dialog_content = "キキキッ、体に異変を感じている、そうだな？\n他に変化は感じないか？",
  ui_story_10_8_1_S7_dialog_content = "他の変化…",
  ui_story_10_8_1_S8_dialog_content = "目がうまく開けられないわ、外の光が強すぎて…",
  ui_story_10_8_1_S9_dialog_content = "なるほどな…ここまで早く体内の「シード」が変化を生むとは。\n素晴らしいぞ！",
  ui_story_10_8_1_S10_dialog_content = "体の中の暗力が、すでに成熟したようだ。",
  ui_story_10_8_1_S11_dialog_content = "お前は今とは完全に違う姿となり、\n我々と共に天空ノ谷へ降臨するのだ。",
  ui_story_10_8_1_S12_dialog_content = "完全に違う姿…",
  ui_story_10_8_1_S13_dialog_content = "そうだ、お前は空の末裔を超えた。\n空の末裔のような下等生物の見た目など、お前にはもはや似合わん。",
  ui_story_10_8_1_S14_dialog_content = "でも…私は生まれた時から、ずっとこの姿よ…",
  ui_story_10_8_1_S15_dialog_content = "だが、お前は脱却することができる。\n弱々しい空の末裔として滅び去る運命から脱却するのと同じようにな…",
  ui_story_10_8_1_S16_dialog_content = "脱却って…どうやるの？",
  ui_story_10_8_1_S17_dialog_content = "どうやると思う？キキキッ！",
  ui_story_10_8_1_S18_dialog_content = "力を求めるのだ！そうすればお前の体内に秘められた力が、\nどうすればいいのか答えてくれるだろう！",
  ui_story_10_8_1_S19_dialog_content = "…",
  ui_story_10_8_1_S20_dialog_content = "もっと強い力を求める…",
  ui_story_10_8_1_S21_dialog_content = "弱者の運命から脱却する…",
  ui_story_10_8_1_S22_dialog_content = "変化を…",
  ui_story_10_8_1_S23_dialog_content = "いいえ…もう私はあいつらとは違う。",
  ui_story_10_8_1_S24_dialog_content = "私はもう、すべてを手に入れた！",
  ui_story_10_8_1_53_dialog_content = "早くあっちへ！急いで！",
  ui_story_10_8_1_54_dialog_content = "武器を取れ！武器を取るんだ！",
  ui_story_10_8_1_55_dialog_content = "何の騒ぎだろう…",
  ui_story_10_8_1_56_dialog_content = "何かあったの？",
  ui_story_10_8_1_57_dialog_content = "ここにいたのね…",
  ui_story_10_8_1_58_dialog_content = "き、君は誰だ！？",
  ui_story_10_8_1_59_dialog_content = "ふふ、スーモアよ。自分の目が信じられないの？",
  ui_story_10_8_1_60_dialog_content = "スーモア？でも、その角…それに髪の毛も？\n見た目が…全然違うじゃないか！",
  ui_story_10_8_1_61_dialog_content = "疑うことも、怖がることもしなくていいわ。\nこれは私が使者となった、証。",
  ui_story_10_8_1_62_dialog_content = "私は選ばれたの。\n選ばれたから、空の末裔を超える力を手に入れたのよ。",
  ui_story_10_8_1_63_dialog_content = "し、使者？力？どういうこと？",
  ui_story_10_8_1_64_dialog_content = "…",
  ui_story_10_8_1_65_dialog_content = "あなたに言ったってわからないわ！\nただ、どんな空の末裔よりも強くなったって思っておけばいいの！",
  ui_story_10_8_1_66_dialog_content = "答えてよ。どうして私を助けようとしたの？\n本の中に鍵を隠して渡したのはどうして？",
  ui_story_10_8_1_67_dialog_content = "そ、それは、大人たちが君を閉じ込めて、死ぬまで出さないって…",
  ui_story_10_8_1_68_dialog_content = "もし僕が先生に話したら…つ、次は僕がそうなるって…",
  ui_story_10_8_1_69_dialog_content = "でも僕は…僕たちは仲間で、兄弟じゃないか…僕はそんなの…",
  ui_story_10_8_1_70_dialog_content = "なんだ、つまらない同情ってことね。",
  ui_story_10_8_1_71_dialog_content = "要は、私の境遇に同情したんでしょ？",
  ui_story_10_8_1_72_dialog_content = "あいつら、私が閉じ込められたのを見て、\n好き放題言ったでしょうね…笑えるわ。",
  ui_story_10_8_1_73_dialog_content = "し、知らないよ…一体何が…いじめられていたんじゃないのか？",
  ui_story_10_8_1_74_dialog_content = "生徒が無断で天空ノ谷を出て、暗鬼に殺された。\nそんな事、あの長老どもは話そうともしないでしょうね。",
  ui_story_10_8_1_75_dialog_content = "審判が下ったことを知って、\n誰も教えに耳を傾けなくなるのが怖いから。",
  ui_story_10_8_1_76_dialog_content = "聞きなさい。誤解しないで。\nあんな本と鍵、受け取る意味もない。",
  ui_story_10_8_1_77_dialog_content = "でも私だってそこまで無情じゃないわ。\n私を助けようとしたことに免じて、生き残るチャンスをあげる。",
  ui_story_10_8_1_78_dialog_content = "これから、あなたも強い力を手にするのよ…",
  ui_story_10_8_1_79_dialog_content = "な、何を言ってるんだ…生き残るチャンス…？",
  ui_story_10_8_1_80_dialog_content = "まだわからないの？",
  ui_story_10_8_1_81_dialog_content = "天空ノ谷は終末を迎える。\n暗鬼がこの世界に審判をもたらしたのよ。",
  ui_story_10_8_1_82_dialog_content = "誰も彼も、死んでしまうの。",
  ui_story_10_8_1_83_dialog_content = "だから私と一緒に、暗鬼になりなさい！",
  ui_story_10_8_1_84_dialog_content = "い…いや…ぼ…僕は…",
  ui_story_10_8_1_85_dialog_content = "この男か？",
  ui_story_10_8_1_86_dialog_content = "私は忙しい、早く済ませるのだ…",
  ui_story_10_8_1_87_dialog_content = "！！！",
  ui_story_10_8_1_88_dialog_content = "同意しなければ、あなたは死ぬ。",
  ui_story_10_8_1_89_dialog_content = "答えなさい。死にたいの、死にたくないの？",
  ui_story_10_8_1_90_dialog_content = "僕は…",
  ui_story_10_8_1_91_dialog_content = "グァア…",
  ui_story_10_8_1_92_dialog_content = "たった一匹の暗鬼がここまで手強いとは…",
  ui_story_10_8_1_93_dialog_content = "ハンデル！まずい！東からも暗鬼が！",
  ui_story_10_8_1_94_dialog_content = "先に行ってください！すぐに向かいます！",
  ui_story_10_8_1_95_dialog_content = "先生！私、戻ってきたわ！",
  ui_story_10_8_1_96_dialog_content = "一緒に行きましょう！",
  ui_story_10_8_1_97_dialog_content = "あなたは…",
  ui_story_10_8_1_98_dialog_content = "スーモア！？",
  ui_story_10_8_1_99_dialog_content = "先生、怖がらないで。",
  ui_story_10_8_1_100_dialog_content = "天空ノ谷が暗鬼に滅ぼされるってこと、\n長老が言わなかったから、みんな慌てているの。",
  ui_story_10_8_1_101_dialog_content = "何を言っているのです？",
  ui_story_10_8_1_102_dialog_content = "「審判」はもう決まったこと…",
  ui_story_10_8_1_103_dialog_content = "これが世界の選択、進化のための選択なの。",
  ui_story_10_8_1_104_dialog_content = "暗鬼も傷つけるべきでない相手に危害は加えないわ。\n先生に資格さえあれば…",
  ui_story_10_8_1_105_dialog_content = "そうすれば、審判を生き残れるの！",
  ui_story_10_8_1_106_dialog_content = "私は暗鬼の使者だから、先生を推薦してもいいわ！",
  ui_story_10_8_1_107_dialog_content = "捕まえろ！早く、彼女を捕まえるんだ！",
  ui_story_10_8_1_108_dialog_content = "急げ！全員でかかれ！",
  ui_story_10_8_1_109_dialog_content = "……？",
  ui_story_10_8_1_110_dialog_content = "密室の扉を開けるんだ！早く！",
  ui_story_10_8_1_111_dialog_content = "閉じ込めるんだ…スーモアを…！",
  ui_story_10_8_1_112_dialog_content = "…",
  ui_story_10_8_1_113_dialog_content = "それが先生の答えね…",
  ui_story_10_8_1_114_dialog_content = "臆病者。",
  ui_story_10_8_1_115_dialog_content = "でも、もういいわ…",
  ui_story_10_8_1_116_dialog_content = "後悔すればいい。",
  ui_story_10_8_1_117_dialog_content = "彼らが降りたつ時、全員が後悔することになるわ。\n誰もが私にすがりつくのよ…",
  ui_story_10_8_1_118_dialog_content = "どうかチャンスを与えてください、って。",
  ui_story_10_8_1_119_dialog_content = "うわ――っ！",
  ui_story_10_8_1_120_dialog_content = "急げ！あっちだ！あっちへ行ったぞ！",
  ui_story_10_8_1_121_dialog_content = "まだ動かせる巨像はあるか！？",
  ui_story_10_8_1_122_dialog_content = "感知できる者はルート確保！子どもが先だ！",
  ui_story_10_8_1_123_dialog_content = "だめだ…多すぎる…暗鬼が多すぎる…",
  ui_story_10_8_1_124_dialog_content = "うーむ、なんとも心地よい音だ。",
  ui_story_10_8_1_125_dialog_content = "あの動物同然の下劣な亜人族どもを滅ぼしてからというもの…",
  ui_story_10_8_1_126_dialog_content = "もう長いこと、胸が張り裂けるような絶叫を聞いていなかったな。",
  ui_story_10_8_1_127_dialog_content = "空の末裔どもは亜人どものように「鳴き」はしないが、\nこいつらの高音も素晴らしいじゃないか。",
  ui_story_10_8_1_128_dialog_content = "歌を愛する種族というだけのことはある。キキキッ！",
  ui_story_10_8_1_129_dialog_content = "グァア…",
  ui_story_10_8_1_130_dialog_content = "行け。もっと叫び声を聞かせろ！やつらを滅ぼせ！",
  ui_story_10_8_1_131_dialog_content = "グォォ！",
  ui_story_10_8_1_132_dialog_content = "動かせる巨像を出すんだ！",
  ui_story_10_8_1_133_dialog_content = "急げ！生存者を救出しろ！",
  ui_story_10_8_1_134_dialog_content = "ゴホッ…",
  ui_story_10_8_1_135_dialog_content = "ハァ、ハァ…",
  ui_story_10_8_1_136_dialog_content = "まだ生きている人がいたのですね…よかった…",
  ui_story_10_8_1_137_dialog_content = "先生…先生…",
  ui_story_10_8_1_138_dialog_content = "モンドル、良かった…さあ、行きましょう…",
  ui_story_10_8_1_139_dialog_content = "先生…みんな死んじゃった…",
  ui_story_10_8_1_140_dialog_content = "先生…僕は助かるんですか…？逃げられるんですか…？",
  ui_story_10_8_1_141_dialog_content = "もちろんですよ。大丈夫ですから。ゴホッ…こっちへ…",
  ui_story_10_8_1_142_dialog_content = "こっちです。早く…<color=#FFB400>セクレペトス</color>が近くに…",
  ui_story_10_8_1_143_dialog_content = "…",
  ui_story_10_8_1_144_dialog_content = "先生？",
  ui_story_10_8_1_145_dialog_content = "モンドル、私の話をよく聞くのです。\n私たちを救助に来るはずの人たちが、全滅したことを感知しました…",
  ui_story_10_8_1_146_dialog_content = "私がしばらくの間、周囲の暗鬼を引きつけます。\nあなたはその隙に、セクレペトスの中へ。セクレペトスは、まだ起動できます。",
  ui_story_10_8_1_147_dialog_content = "セクレペトスの中には特別な隠し部屋があります。\n天空ノ谷を離れたら、その部屋を探してください…",
  ui_story_10_8_1_148_dialog_content = "中には<color=#FFB400>特別なパーツ</color>があります。\nそのパーツの存在は…",
  ui_story_10_8_1_149_dialog_content = "巨像というものに対する認識を完全に変えることができるでしょう。",
  ui_story_10_8_1_150_dialog_content = "もし邪悪な人の手に渡ってしまえば、\n結果は悲惨なものになってしまいます。",
  ui_story_10_8_1_151_dialog_content = "セクレペトスを操縦できる人はもういません。\n残っているのはあなただけです。",
  ui_story_10_8_1_152_dialog_content = "ぼ、僕には無理です…巨像の感知に成功したことだって、一度も…",
  ui_story_10_8_1_153_dialog_content = "できます。あなたには潜在能力がある。\n自信さえ持っていればいいのです。",
  ui_story_10_8_1_154_dialog_content = "あなたにはセクレペトスとの適合性がある。私たちは、もともとあなたを\nセクレペトスの次のナビゲーターとして育成することを考えていたのです。",
  ui_story_10_8_1_155_dialog_content = "でも、先生…先生も巨像を感知できますよね…\n一緒に来てくれないんですか？",
  ui_story_10_8_1_156_dialog_content = "一緒には行けません。\n<color=#FFB400>シビリザー</color>が私を待っていますから。",
  ui_story_10_8_1_157_dialog_content = "あなたなら、絶対にセクレペトスを動かせます。",
  ui_story_10_8_1_158_dialog_content = "セクレペトスの中には、<color=#FFB400>フェネクス</color>と<color=#FFB400>フェニィ</color>という守護者がいます。\nあなたを助け、そばにいてくれるでしょう…",
  ui_story_10_8_1_159_dialog_content = "僕は…先生…一人じゃ無理です！\n感知に成功したことなんて一度も…",
  ui_story_10_8_1_160_dialog_content = "あなたなら動かすことができる。\nこんな時まで自分を疑ってはなりません！",
  ui_story_10_8_1_161_dialog_content = "でも、暗鬼が…そこらじゅうにいるし、もっと恐ろしい暗鬼も…",
  ui_story_10_8_1_162_dialog_content = "仮に巨像を動かせても…もう逃げられない…",
  ui_story_10_8_1_163_dialog_content = "死んでしまう…このままじゃ、みんな死んでしまうんだ…",
  ui_story_10_8_1_164_dialog_content = "先生、スーモアが「生き残れる方法がある」って言ってたんです…",
  ui_story_10_8_1_165_dialog_content = "彼女が来たのですか！？",
  ui_story_10_8_1_166_dialog_content = "もしかしたら、生き残る方法が別にあるかもしれません…",
  ui_story_10_8_1_167_dialog_content = "終末を…生き延びられるかもしれない…",
  ui_story_10_8_1_168_dialog_content = "スーモア、もう満足したか？",
  ui_story_10_8_1_169_dialog_content = "フィジェロ様…もう選ぶべき相手はいません。",
  ui_story_10_8_1_170_dialog_content = "かわいそうな人たち。わざわざ待ってあげたのに。",
  ui_story_10_8_1_171_dialog_content = "もう生き残る機会は残されていないわ。",
  ui_story_10_8_1_172_dialog_content = "キッキッキッ！ならば、偉大なる末日に立ち会うとしよう！",
  ui_story_10_8_1_173_dialog_content = "日蝕の降臨だ！",
  ui_story_10_9_1_1_dialog_content = "PlayerName！？",
  ui_story_10_9_1_2_dialog_content = "末日…<color=#FFB400>日蝕</color>…",
  ui_story_10_9_1_3_dialog_content = "末日が何だって？よくわかんねぇぞ。\nちょっと一息入れてから、説明しろよ。",
  ui_story_10_9_1_4_dialog_content = "僕はかつて、天空ノ谷が破壊される光景を\n夢で見ていたことがあるんだ…",
  ui_story_10_9_1_5_dialog_content = "あれは全部、本当だったんだ。",
  ui_story_10_9_1_6_dialog_content = "スーモアの天空ノ谷に関わる記憶を感知したんだ。\n天空ノ谷が暗鬼に襲われた日のことを。",
  ui_story_10_9_1_7_dialog_content = "スーモアが暗鬼を引き連れて、天空ノ谷に…",
  ui_story_10_9_1_8_dialog_content = "空一面が真っ黒になって、日蝕が現れた…",
  ui_story_10_9_1_9_dialog_content = "何より、<color=#FFB400>「フィジェロ」</color>と呼ばれる人型の暗鬼が…",
  ui_story_10_9_1_10_dialog_content = "暗鬼を率いて、天空ノ谷を滅ぼした！",
  ui_story_10_9_1_11_dialog_content = "…おい、大丈夫か？",
  ui_story_10_9_1_12_dialog_content = "うん…大丈夫。前方から大量の暗鬼が来てる。戦う準備をしないと。",
  ui_story_10_9_1_13_dialog_content = "何も聞こえねぇぞ、こんな場所でも暗鬼の襲撃が予測できるのかよ？",
  ui_story_10_9_1_14_dialog_content = "ちょ、ちょっとは聞こえてるよ！暗鬼の群れが来てる！",
  ui_story_10_9_1_15_dialog_content = "ハッ、ひどく興奮してたから、てっきり錯乱するかと思ってたぜ。",
  ui_story_10_9_1_16_dialog_content = "まさかすぐに戦局の判断がここまで冷静にできるようになるとはな。",
  ui_story_10_9_1_17_dialog_content = "だが先に言っとくぞ。仇を討ちたいって気持ちだけじゃ不十分だ。",
  ui_story_10_9_1_18_dialog_content = "その時になって仇に出会っても、あまり興奮するなよ。\n指揮官として、自分の役割をしっかり果たすんだ。",
  ui_story_10_9_1_19_dialog_content = "忠告ありがとう。やってみせるよ。",
  ui_story_10_9_1_20_dialog_content = "僕は冷静に彼女と対面して…仇を討つ…",
  ui_story_10_13_1_1_dialog_content = "暗鬼になったからといって、\n必ずしも暗鬼の力をコントロールできるわけじゃない。",
  ui_story_10_13_1_2_dialog_content = "下手をすれば暗力の影響で、制御不能に陥る可能性も高い…",
  ui_story_10_13_1_3_dialog_content = "ずっと力を渇望しているスーモアでさえ、\nこの程度までしか力を上げることができないのね。",
  ui_story_10_13_1_4_dialog_content = "もしこのままなら…\nこの実験は、わざわざ記録を残す必要もなさそうね。",
  ui_story_10_13_1_5_dialog_content = "『では主よ、いかがしますか？』",
  ui_story_10_13_1_6_dialog_content = "『光霊たちが、もうすぐここに到達します。』",
  ui_story_10_13_1_7_dialog_content = "スーモアの自己成長には期待できなさそうね。",
  ui_story_10_13_1_8_dialog_content = "彼女を「起こす」わ。",
  ui_story_10_13_1_9_dialog_content = "お前は光霊たちの動向を引き続き探りなさい。",
  ui_story_10_13_1_10_dialog_content = "『はっ。』",
  ui_story_10_13_1_11_dialog_content = "スーモア。",
  ui_story_10_13_1_12_dialog_content = "うる…さい…",
  ui_story_10_13_1_13_dialog_content = "まだ目が覚めてないの？",
  ui_story_10_13_1_14_dialog_content = "あ…？",
  ui_story_10_13_1_15_dialog_content = "寝ぼけた表情はやめなさい。あなたの実験結果を伝えにきたの。",
  ui_story_10_13_1_16_dialog_content = "何を…？",
  ui_story_10_13_1_17_dialog_content = "最終的な結論として…あなたは<color=#FFB400>徹底的に役立たず</color>よ。",
  ui_story_10_13_1_18_dialog_content = "…ノ…ラ。",
  ui_story_10_13_1_19_dialog_content = "そう焦らないで、スーモア。\nあなたに言ったのは客観的な事実よ。",
  ui_story_10_13_1_20_dialog_content = "あなたはグリードをむさぼり、暗鬼を食らった。\nなのに、完全な変化が望めない。",
  ui_story_10_13_1_21_dialog_content = "グリードを…食…べ…？",
  ui_story_10_13_1_22_dialog_content = "そうよ。この治療繭はあなたのグリードとつながっているの。",
  ui_story_10_13_1_23_dialog_content = "あなたは治療繭を通してグリードのエネルギーを吸収したの。\nもう、ただの鉄くずになったわ。",
  ui_story_10_13_1_24_dialog_content = "ど…うして…教え…なかっ…",
  ui_story_10_13_1_25_dialog_content = "あなたにとってこの巨像が大事なことは知っていたもの。",
  ui_story_10_13_1_26_dialog_content = "小さいころ一番欲しかった「オモチャ」。\nようやく手に入れたのだから、何があっても手放したくない。まぁ、普通よね。",
  ui_story_10_13_1_27_dialog_content = "分かりやすいじゃない。\n結局あなたの中身は、軟弱な空の末裔のまま。",
  ui_story_10_13_1_28_dialog_content = "だからPlayerNameに会ったとき、\n彼を消すことも、手放すことも惜しんだ。",
  ui_story_10_13_1_29_dialog_content = "あなた、ずっと過去の暗い影に囚われたままなのよ。\n哀れなことに。",
  ui_story_10_13_1_30_dialog_content = "自分の運命を自分で支配できるなんて、妄想しないことね。",
  ui_story_10_13_1_31_dialog_content = "弱者にそんな資格はないの。",
  ui_story_10_13_1_32_dialog_content = "この…！",
  ui_story_10_13_1_33_dialog_content = "怒っていいのよ。",
  ui_story_10_13_1_34_dialog_content = "だって、すべてが身から出た錆だもの。",
  ui_story_10_13_1_35_dialog_content = "あなたは幼稚で、弱くて、浅はかで、愚かで…",
  ui_story_10_13_1_36_dialog_content = "あんた…いいか…に…",
  ui_story_10_13_1_37_dialog_content = "いいえ。その怒りは私に向けるべきじゃない。",
  ui_story_10_13_1_38_dialog_content = "忘れているようね。",
  ui_story_10_13_1_39_dialog_content = "あなたをこんな状況に追い込んだのは、誰だったかしら？",
  ui_story_10_13_1_40_dialog_content = "あの空の末裔が言っていたこと、覚えてる？",
  ui_story_10_13_1_41_dialog_content = "「あなたはいつも地面にひざまずいて、力を授かることを祈っている」。",
  ui_story_10_13_1_42_dialog_content = "見抜いていたのよ、彼は…",
  ui_story_10_13_1_43_dialog_content = "もうすぐここに来るわ。",
  ui_story_10_13_1_44_dialog_content = "あなたの前にやってきて、あなたにトドメを刺す。",
  ui_story_10_13_1_45_dialog_content = "本気で命乞いすれば、許してもらえるかもね。",
  ui_story_10_13_1_46_dialog_content = "そんなこと…",
  ui_story_10_13_1_47_dialog_content = "許してもらえるようにすがりついてみなさいよ。\nPlayerNameに、どうか見逃してくれって。",
  ui_story_10_13_1_48_dialog_content = "ふざけ…ないで…",
  ui_story_10_13_1_49_dialog_content = "もし死にたくないなら…",
  ui_story_10_13_1_50_dialog_content = "生き残りたいなら、あいつらをひざまずかせたいなら。",
  ui_story_10_13_1_51_dialog_content = "残された方法は一つだけよ。",
  ui_story_10_13_1_52_dialog_content = "もっと多くの力を望みなさい。",
  ui_story_10_13_1_53_dialog_content = "力…",
  ui_story_10_13_1_54_dialog_content = "…",
  ui_story_10_13_1_55_dialog_content = "スーモア？",
  ui_story_10_13_1_56_dialog_content = "<size=45>力を…よこしなさい！</size>",
  ui_story_10_13_1_57_dialog_content = "…",
  ui_story_10_13_1_58_dialog_content = "あなたが自分の感情をコントロールできなくなることは、\nある程度予想していたけれど。",
  ui_story_10_13_1_59_dialog_content = "自分から理性を捨てることを選ぶとはね…",
  ui_story_10_13_1_60_dialog_content = "<size=45>力を――！！！</size>",
  ui_story_10_13_1_61_dialog_content = "どうしようもないわね。",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>グオオ――！</color>",
  ui_story_10_13_1_63_dialog_content = "な、何の音？",
  ui_story_10_13_1_64_dialog_content = "PlayerName、何が起こったのか把握できる？",
  ui_story_10_13_1_65_dialog_content = "わからない…全力を使っても、\nスーモアの考えがわずかに感知できるだけで…",
  ui_story_10_13_1_66_dialog_content = "「強さ」とか、「力」とか、「特別」…そういう考えばかり…",
  ui_story_10_13_1_67_dialog_content = "それからもう一つ、すごく強烈な…",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>憎悪…</color>",
  ui_story_10_13_1_69_dialog_content = "こんなの…ほとんど発狂してしまったのと同じだ！",
  ui_story_10_13_1_70_dialog_content = "発狂？暗鬼を食っておいて、今さら発狂だと？",
  ui_story_10_13_1_71_dialog_content = "おかしいよ…",
  ui_story_10_13_1_72_dialog_content = "間違いねぇ、ノラが何かしたな。",
  ui_story_10_13_1_73_dialog_content = "スーモアに、俺たちが来ることを伝えた可能性が高ぇぞ。",
  ui_story_10_13_1_74_dialog_content = "もう俺らと戦う準備を整えてるに違いねぇ。",
  ui_story_10_13_1_75_dialog_content = "そいつの狙いがお前なら、俺たちを無視してお前だけ狙う可能性もある。",
  ui_story_10_13_1_76_dialog_content = "そんな時にノラが横やりを入れてきやがったら、\nさすがに守ってやれる保証はねぇぞ。",
  ui_story_10_13_1_77_dialog_content = "ちょっと様子を探ってくる。PlayerNameを頼んだぜ。",
  ui_story_10_13_1_78_dialog_content = "わかったわ。",
  ui_story_10_13_1_79_dialog_content = "前方に暗鬼！",
  ui_story_10_13_1_80_dialog_content = "ちゃっちゃと片付けるぞ！",
  ui_story_10_13_1_81_dialog_content = "グア！",
  ui_story_10_13_1_82_dialog_content = "何！？暗鬼が急に興奮しだしたわ！？",
  ui_story_10_13_1_83_dialog_content = "さっきの地震のせい！？",
  ui_story_10_13_1_84_dialog_content = "何かヤ～な予感がするわ…",
  ui_story_10_13_1_85_dialog_content = "セファーにすら予見できる…",
  ui_story_10_13_1_86_dialog_content = "となると、間違いなくかなり危険なものが出現したのだろう。",
  ui_story_10_13_1_87_dialog_content = "ビクトリア様のご命令は…",
  ui_story_10_13_1_88_dialog_content = "今はまだ、争いに関わる時ではないと。",
  ui_story_10_13_1_89_dialog_content = "その通りだ。「シード」もほぼ集まったようだし、ここを離れるとしようか。",
  ui_story_10_13_1_90_dialog_content = "大きな戦いが、間もなく始まる。",
  ui_story_10_13_2_1_dialog_content = "グア！！",
  ui_story_10_13_2_2_dialog_content = "…",
  ui_story_10_13_2_3_dialog_content = "スーモア！？",
  ui_story_10_13_2_4_dialog_content = "ス、ス…スーモアが自分から暗鬼に向かってったよ！？",
  ui_story_10_13_2_5_dialog_content = "しかも暗鬼を食べちゃった！？",
  ui_story_10_13_2_6_dialog_content = "こ…これがスーモアなの？様子が明らかにおかしいわ！？",
  ui_story_10_13_2_7_dialog_content = "スーモア！",
  ui_story_10_13_2_8_dialog_content = "お前の犯した罪は、すべて知ってる…！",
  ui_story_10_13_2_9_dialog_content = "死にたくないなら、自分を暗鬼にするだけで十分じゃないの？",
  ui_story_10_13_2_10_dialog_content = "どうして暗鬼を天空ノ谷に入れた！？",
  ui_story_10_13_2_11_dialog_content = "どうしてみんなを殺した！？",
  ui_story_10_13_2_12_dialog_content = "…",
  ui_story_10_13_2_13_dialog_content = "裏切り者…罪を償え！",
  ui_story_10_13_2_14_dialog_content = "グォアアッ！！",
  ui_story_10_13_2_15_dialog_content = "PlayerName！危ない！",
  ui_story_10_13_2_16_dialog_content = "グア！？",
  ui_story_10_13_2_17_dialog_content = "え…隅にいた暗鬼を襲ったの？",
  ui_story_10_13_2_18_dialog_content = "…",
  ui_story_10_13_2_19_dialog_content = "チカラ…",
  ui_story_10_13_2_20_dialog_content = "いったいどういうことなの…",
  ui_story_10_13_2_21_dialog_content = "彼女…私たちのことがわかってないの？",
  ui_story_10_13_2_22_dialog_content = "PlayerName…危ないマネはよせ！",
  ui_story_10_13_2_23_dialog_content = "お前は指揮官だろうが！\n俺たちより先にカっとなってどうすんだ！？",
  ui_story_10_13_2_24_dialog_content = "……ごめん…少し…冷静になったよ。",
  ui_story_10_13_2_25_dialog_content = "…",
  ui_story_10_13_2_26_dialog_content = "で、どうすんだ？",
  ui_story_10_13_2_27_dialog_content = "スーモアは…たぶん力を手に入れるために、\n手段を選ばず、結果的に理性を失ったんだ。",
  ui_story_10_13_2_28_dialog_content = "まずは力を探ることが先決だよ。慎重に戦って。",
  ui_story_10_13_2_29_dialog_content = "ガ…",
  ui_story_10_13_2_30_dialog_content = "こ…こっち見た？暗鬼を食べ終わったのかな！？",
  ui_story_10_13_2_31_dialog_content = "…",
  ui_story_10_13_2_32_dialog_content = "PlayerName…",
  ui_story_10_13_2_33_dialog_content = "反応した！？",
  ui_story_10_13_2_34_dialog_content = "PlayerName…あんたたちを…",
  ui_story_10_13_2_35_dialog_content = "やる気か！？俺が先に相手になるぜ！",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName！消えなさい！！！</size></anim>",
  ui_story_10_14_2_1_dialog_content = "やれるか！？",
  ui_story_10_14_2_2_dialog_content = "最後のとどめだ、行け！",
  ui_story_10_14_2_3_dialog_content = "スーモア！裁きを受けなさい！",
  ui_story_10_14_2_4_dialog_content = "グォォ――！",
  ui_story_10_14_2_5_dialog_content = "長い長い夢、気分が悪いわ…",
  ui_story_10_14_2_6_dialog_content = "よりによって17年前の、あの記憶…",
  ui_story_10_14_2_7_dialog_content = "もうウンザリよ…",
  ui_story_10_14_2_8_dialog_content = "ウンザリなのよ！！！",
  ui_story_10_14_2_9_dialog_content = "PlayerName！危ない！！",
  ui_story_10_14_2_10_dialog_content = "ドォン――",
  ui_story_10_14_2_11_dialog_content = "ゴホッ…",
  ui_story_10_14_2_12_dialog_content = "コイツ…手ごたえはあったのに、まだ攻撃を…",
  ui_story_10_14_2_13_dialog_content = "ここまで強いのかよ…冗談だろ？",
  ui_story_10_14_2_14_dialog_content = "…",
  ui_story_10_14_2_15_dialog_content = "バイス、PlayerName…大丈夫？",
  ui_story_10_14_2_16_dialog_content = "ううっ…何とか…",
  ui_story_10_14_2_17_dialog_content = "僕は平気…バップが守ってくれたんだね…ありがとう。",
  ui_story_10_14_2_18_dialog_content = "どういたしまして。ぶ、無事ならよかった…",
  ui_story_10_14_2_19_dialog_content = "…",
  ui_story_10_14_2_20_dialog_content = "終わったか？",
  ui_story_10_14_2_21_dialog_content = "い、いや…",
  ui_story_10_14_2_22_dialog_content = "は、はは、アハハハ…",
  ui_story_10_14_2_23_dialog_content = "スーモアが理性を取り戻した！\nもう一度戦う準備を…まだ余力がある！",
  ui_story_10_14_2_24_dialog_content = "理性？",
  ui_story_10_14_2_25_dialog_content = "そうね、私はさっき…怒っていたから…",
  ui_story_10_14_2_26_dialog_content = "でも…PlayerName、あなたが来るとわかって、嬉しくなったの。",
  ui_story_10_14_2_27_dialog_content = "…！",
  ui_story_10_14_2_28_dialog_content = "気色悪ぃこと言い出すんじゃねぇ！！",
  ui_story_10_14_2_29_dialog_content = "PlayerName、下がってろ！",
  ui_story_10_14_2_30_dialog_content = "バップ！小僧の安全はお前に任せたぞ！",
  ui_story_10_14_2_31_dialog_content = "了解！",
  ui_story_10_14_2_32_dialog_content = "おい！死にかけの変態サンよ！ノラはどこだ？答えろ！",
  ui_story_10_14_2_33_dialog_content = "「死にかけの変態」？私をバカにしてるつもり？",
  ui_story_10_14_2_34_dialog_content = "別にいいわ。怒るまでもない…怒るに値しないもの。",
  ui_story_10_14_2_35_dialog_content = "それからノラのことは…心配いらないわ。",
  ui_story_10_14_2_36_dialog_content = "逃げたバカの始末は、私がつけるから。",
  ui_story_10_14_2_37_dialog_content = "でも、その前に。\nPlayerName、私たちの決着をつけましょう。",
  ui_story_10_14_2_38_dialog_content = "保証するわ。今度は全力でもって…",
  ui_story_10_14_2_39_dialog_content = "ひねり潰してあげる！！！",
  ui_story_10_14_2_40_dialog_content = "！！！",
  ui_story_10_14_2_41_dialog_content = "命がけで戦うつもり？それは許せないわね…",
  ui_story_10_14_2_42_dialog_content = "ノ、ラ…！？",
  ui_story_10_14_2_43_dialog_content = "やるじゃない。あなたの憎しみのおかげで\n「シード」がついに成熟したわ…",
  ui_story_10_14_2_44_dialog_content = "でもあなた、さっきの戦いで\nほとんどのエネルギーを使い果たしてるわ。",
  ui_story_10_14_2_45_dialog_content = "このまま使い続ければ、\nせっかく私が育てた「シード」までダメになる。",
  ui_story_10_14_2_46_dialog_content = "なっ…！？",
  ui_story_10_14_2_47_dialog_content = "私が「シード」を取り出す間ぐらい、いい子にしてなさい。",
  ui_story_10_14_2_48_dialog_content = "サメヤマ！ノラの狙いはスーモアだ！\n「<color=#FFB400>シード</color>」だよ！",
  ui_story_10_14_2_49_dialog_content = "そうはさせねぇ！",
  ui_story_10_14_2_50_dialog_content = "あまり興奮しないでよ。\n結果的には、私はあなたたちを救ってあげてるのよ。",
  ui_story_10_14_2_51_dialog_content = "スーモアの処分はあなたたちに任せるわ。\n私はシードがあればいいから。",
  ui_story_10_14_2_52_dialog_content = "お互い必要なものが手に入って、ウィン・ウィンでしょ。",
  ui_story_10_14_2_53_dialog_content = "それに、どうせあなたに私は止められないもの…",
  ui_story_10_14_2_54_dialog_content = "サメヤマ、危ない！！！",
  ui_story_10_14_2_55_dialog_content = "なんて攻撃範囲だ！？",
  ui_story_10_14_2_56_dialog_content = "全員大人しく、這いつくばってなさい。",
  ui_story_10_14_2_57_dialog_content = "そうそう…",
  ui_story_10_14_2_58_dialog_content = "最期に何か言いたいことはある？スーモア。",
  ui_story_10_14_2_59_dialog_content = "力を失うってどんな気持ち？\nもしくは、空の末裔に戻った感想でもいいわ。",
  ui_story_10_14_2_60_dialog_content = "面白かったら、それを実験記録に残しておいてあげるから。",
  ui_story_10_14_2_61_dialog_content = "…",
  ui_story_10_14_2_62_dialog_content = "フン…",
  ui_story_10_14_2_63_dialog_content = "…そう。",
  ui_story_10_14_2_64_dialog_content = "それじゃ、私の実験の完成を手伝ってくれたお礼として、\nスーモアはあなたたちにあげるわ。",
  ui_story_10_14_2_65_dialog_content = "お別れよ、スーモア…",
  ui_story_10_14_2_66_dialog_content = "ゴホッ…",
  ui_story_10_14_2_67_dialog_content = "ボス…お願い…深追いは…",
  ui_story_10_14_2_68_dialog_content = "わかってる。",
  ui_story_10_14_2_69_dialog_content = "PlayerName、スーモアをどうするかは…お前が決めろ。",
  ui_story_10_14_2_70_dialog_content = "スーモアは致命傷を負っているわ。\n身動きすることも難しいはず。",
  ui_story_10_14_2_71_dialog_content = "さっきの話は気にせず、あなたの望むとおりにすればいい。",
  ui_story_10_14_2_72_dialog_content = "ほんのひと刺しで、自分の手で裁きを下せる。",
  ui_story_10_14_2_73_dialog_content = "その前に…まだ聞きたいことがある。",
  ui_story_10_14_2_74_dialog_content = "は…裁判のつもり？聞きたいこと？",
  ui_story_10_14_2_75_dialog_content = "なら…一つずつ…答えてあげましょうか？",
  ui_story_10_14_2_76_dialog_content = "3つの巨像のパーツはどこにある？",
  ui_story_10_14_2_77_dialog_content = "くたばりなさい！",
  ui_story_10_14_2_78_dialog_content = "このゴミクズ！私のパーツが欲しい！？許さないわ！",
  ui_story_10_14_2_79_dialog_content = "あんたはパーツの価値なんかちっともわかってないの！\nあれはグリードだけのものなのよ！",
  ui_story_10_14_2_80_option_content = "僕にはわからない。\nそんなにグリードが大事？",
  ui_story_10_14_2_81_dialog_content = "空の末裔を裏切ったのは…グリードが欲しかったから？",
  ui_story_10_14_2_82_dialog_content = "暗鬼に出会って死にたくないと思ったことまで、責めるつもりはない…",
  ui_story_10_14_2_83_dialog_content = "でも、それなら自分が暗鬼になるだけでよかったはず。\nそいつらと一緒に行けばいい…なのにどうして、暗鬼を天空ノ谷に入れたの！？",
  ui_story_10_14_2_84_dialog_content = "どうして…！？",
  ui_story_10_14_2_85_dialog_content = "アハハ…",
  ui_story_10_14_2_86_dialog_content = "わかってないのね。",
  ui_story_10_14_2_87_dialog_content = "あんたたちは終末の日を迎えたことも、本当の審判を迎えたこともない。\nわかるはずがないわ…",
  ui_story_10_14_2_88_dialog_content = "降臨…天空ノ谷に降臨したのよ！",
  ui_story_10_14_2_89_dialog_content = "逃げられない！誰一人逃げられないの！",
  ui_story_10_14_2_90_dialog_content = "あんたたちだってそう…すぐに滅びるわ…",
  ui_story_10_14_2_91_dialog_content = "戯言を！暗鬼に洗脳されているのね！",
  ui_story_10_14_2_92_dialog_content = "PlayerName、惑わされないで！",
  ui_story_10_14_2_93_option_content = "知りたくもない！パーツを渡して！",
  ui_story_10_14_2_94_dialog_content = "あれはお前のものじゃない！",
  ui_story_10_14_2_95_dialog_content = "パーツは、空の末裔のものだ！",
  ui_story_10_14_2_96_dialog_content = "空の末裔が持っているべきなんだ！！",
  ui_story_10_14_2_97_dialog_content = "空の末裔の…",
  ui_story_10_14_2_98_dialog_content = "裏切り者が持っていていいものじゃない！！",
  ui_story_10_14_2_99_dialog_content = "…",
  ui_story_10_14_2_100_dialog_content = "知ったことじゃないわ！",
  ui_story_10_14_2_101_dialog_content = "空の末裔が何？弱っちいクセに、事の良し悪しもわからない。",
  ui_story_10_14_2_102_dialog_content = "空の末裔なんて、巨像の真の価値も、力の価値もまったくわかってない！",
  ui_story_10_14_2_103_dialog_content = "みんなあんたと一緒！全員無知で浅はかな大間抜けよ！",
  ui_story_10_14_2_104_dialog_content = "うるさい！！",
  ui_story_10_14_2_105_dialog_content = "PlayerName、感情に飲まれるな！",
  ui_story_10_14_2_106_dialog_content = "わかってる…",
  ui_story_10_14_2_107_dialog_content = "わかってるよ…",
  ui_story_10_14_2_108_dialog_content = "途中で、もう分かってはいたんだ…\n暗鬼の狙いが最初から天空ノ谷を滅ぼすことだったら…",
  ui_story_10_14_2_109_dialog_content = "どんな手段を使ってでも、\nどんな時でも、襲撃されていたことに変わりはない…",
  ui_story_10_14_2_110_dialog_content = "スーモアも哀れな犠牲者に過ぎないんだ…",
  ui_story_10_14_2_111_dialog_content = "は！？",
  ui_story_10_14_2_112_dialog_content = "ふざけるんじゃないわ。",
  ui_story_10_14_2_113_dialog_content = "私は選ばれたの…選ばれたのよ！生き残る資格がある者として！",
  ui_story_10_14_2_114_dialog_content = "バイス、怪我は大丈夫？",
  ui_story_10_14_2_115_dialog_content = "え、えっ？わ、私はまぁ…大丈夫。",
  ui_story_10_14_2_116_dialog_content = "ちょっと！？",
  ui_story_10_14_2_117_dialog_content = "話を聞いてるの！？",
  ui_story_10_14_2_118_dialog_content = "バイス、巨像の構造は細かな所を除けばほとんど一緒だよ。\nパーツがどこにあるかは大体わかるよね。",
  ui_story_10_14_2_119_dialog_content = "回収してきてくれる？",
  ui_story_10_14_2_120_dialog_content = "うん。",
  ui_story_10_14_2_121_dialog_content = "…",
  ui_story_10_14_2_122_dialog_content = "…………",
  ui_story_10_14_2_123_dialog_content = "あんたの憎しみは？",
  ui_story_10_14_2_124_dialog_content = "叫ばないの？罵らないの？\n復讐しなくていいの？相手が暗鬼だから？",
  ui_story_10_14_2_125_dialog_content = "さっさとパーツを見つけて、私に復讐して、\n愛するお仲間たちとお家に帰って、おしゃべりでもしたいんじゃないの？",
  ui_story_10_14_2_126_dialog_content = "PlayerName、俺がこいつの口を塞いでやってもいいんだぜ…",
  ui_story_10_14_2_127_dialog_content = "その必要はないよ。それより、サメヤマは自分の怪我を見て…",
  ui_story_10_14_2_128_dialog_content = "バップ、悪いけど、君もパーツ探しを手伝ってくれないかな？",
  ui_story_10_14_2_129_dialog_content = "うっ、うん。",
  ui_story_10_14_2_130_dialog_content = "は、ははは…",
  ui_story_10_14_2_131_dialog_content = "平和を愛する種族、ね…",
  ui_story_10_14_2_132_dialog_content = "本当にバカだわ、空の末裔って。",
  ui_story_10_14_2_133_dialog_content = "カレン、氷の刃をひとつ使わせてもらえるかな。",
  ui_story_10_14_2_134_dialog_content = "ええ。",
  ui_story_10_14_2_135_dialog_content = "…",
  ui_story_10_14_2_136_dialog_content = "スーモア、<color=#FFB400>「フィジェロ」</color>というのは誰？",
  ui_story_10_14_2_137_dialog_content = "それから<color=#FFB400>「日蝕」</color>って何？",
  ui_story_10_14_2_138_dialog_content = "…！",
  ui_story_10_14_2_139_dialog_content = "私の記憶を見たわね！？",
  ui_story_10_14_2_140_dialog_content = "そう、僕は見た。でも一部分しか見えなかった。",
  ui_story_10_14_2_141_dialog_content = "だから残りの情報は、その口で話してもらう。",
  ui_story_10_14_2_142_dialog_content = "…",
  ui_story_10_14_2_143_dialog_content = "は、ははは…",
  ui_story_10_14_2_144_dialog_content = "いいわ。こっちに来なさい、教えてあげる…",
  ui_story_10_14_2_145_dialog_content = "そう、もっとよ。",
  ui_story_10_14_2_146_dialog_content = "ソレで私に裁きを下すつもりなんでしょ？",
  ui_story_10_14_2_147_dialog_content = "PlayerName！様子がおかしいわ。騙されないで！",
  ui_story_10_14_2_148_dialog_content = "安心して、近づくつもりはないから。",
  ui_story_10_14_2_149_dialog_content = "もう遅い…",
  ui_story_10_14_2_150_dialog_content = "グァ…",
  ui_story_10_14_2_151_dialog_content = "グァア…",
  ui_story_10_14_2_152_dialog_content = "後ろだ、危ねぇ！",
  ui_story_10_14_2_153_dialog_content = "グオアア！",
  ui_story_10_14_2_154_dialog_content = "ははは…ハハ…",
  ui_story_10_14_2_155_dialog_content = "言ったでしょう、私は選ばれたのよ！私は「日蝕」の使者！",
  ui_story_10_14_2_156_dialog_content = "来なさい…ヤツラを…",
  ui_story_10_14_2_157_dialog_content = "グァア…",
  ui_story_10_14_2_158_dialog_content = "グォォ…",
  ui_story_10_14_2_159_dialog_content = "最後に勝つのは私なのよ…",
  ui_story_10_14_2_160_dialog_content = "PlayerName！",
  ui_story_10_14_2_161_dialog_content = "競争とは、進化とは！他人の頭を踏みつけて、乗り越えていくことよ！",
  ui_story_10_14_2_162_dialog_content = "真の犠牲者は、あくまであんたたちと天空ノ谷！",
  ui_story_10_14_2_163_dialog_content = "私はあんたたちを、この試練を乗り越えて…最強になるのよ！",
  ui_story_10_14_2_164_dialog_content = "…！",
  ui_story_10_14_2_165_dialog_content = "みんな…全力で逃げる準備を…",
  ui_story_10_14_2_166_dialog_content = "おい！せっかくのチャンスじゃねぇか…やっちまおうぜ！",
  ui_story_10_14_2_167_dialog_content = "みんなの今の状態からして、\nこんなに多くの暗鬼を相手にするのはもう無理だよ。",
  ui_story_10_14_2_168_dialog_content = "みんなも自分でよくわかってるでしょ…",
  ui_story_10_14_2_169_dialog_content = "僕は敵を討ちたい…でもそれは、\nみんなを犠牲にしてまで果たすものじゃない…",
  ui_story_10_14_2_170_dialog_content = "逃げたい？なら逃げるといいわ。見ててあげるから…",
  ui_story_10_14_2_171_dialog_content = "満身創痍のあんたたちが速いか、こいつらが速いか、見ものだわ！",
  ui_story_10_14_2_172_dialog_content = "噛みついてやりなさい！",
  ui_story_10_14_2_173_dialog_content = "グァア…",
  ui_story_10_14_2_174_dialog_content = "何してるの！？いきなさい！",
  ui_story_10_14_2_175_dialog_content = "グア！",
  ui_story_10_14_2_176_dialog_content = "なっ！？",
  ui_story_10_14_2_177_dialog_content = "痛い！放しなさいよ！！",
  ui_story_10_14_2_178_dialog_content = "私じゃない！やめなさい！",
  ui_story_10_14_2_179_dialog_content = "やめてっ！！！",
  ui_story_10_14_2_180_dialog_content = "グァアア！",
  ui_story_10_14_2_181_dialog_content = "…",
  ui_story_10_14_2_182_dialog_content = "い、急がないと…今のうちに撤退しよう！",
  ui_story_10_14_2_183_dialog_content = "でないと、次は私たちだよ！",
  ui_story_10_14_2_184_dialog_content = "PlayerName！",
  ui_story_10_14_2_185_dialog_content = "PlayerNameは引っ張ってくぞ！急げ！",
  ui_story_10_14_2_186_dialog_content = "ズラかれーッ！！",
  ui_story_10_14_2_187_dialog_content = "こんな結末…",
  ui_story_10_14_2_188_dialog_content = "（受け入れないわ！）",
  ui_story_10_14_2_189_dialog_content = "（生き残って、すべてを手に入れたのに…）",
  ui_story_10_14_2_190_dialog_content = "（どいつもこいつも…嘘つきばかり！）",
  ui_story_10_14_2_191_dialog_content = "（何もかも嘘だらけ！）",
  ui_story_10_14_2_192_dialog_content = "（嘘の力！嘘の審判！）",
  ui_story_10_14_2_193_dialog_content = "（ノラ、フィジェロ、日蝕…）",
  ui_story_10_14_2_194_dialog_content = "（最初から…私を見逃すつもりなんてなかった…）",
  ui_story_10_14_2_195_dialog_content = "（呪ってやる…）",
  ui_story_10_14_2_196_dialog_content = "（弱い種族は滅ぼされる運命にあるの…）",
  ui_story_10_14_2_197_dialog_content = "（空の末裔は呪われるべき存在…）",
  ui_story_10_14_2_198_dialog_content = "（あんたも最後は私と一緒で…悲惨な死を遂げる…）",
  ui_story_10_14_2_199_dialog_content = "（呪ってやる…）",
  ui_story_10_14_2_200_dialog_content = "（PlayerName…）",
  ui_story_10_14_2_201_dialog_content = "（滅びの運命に怯えるがいいわ…）",
  ui_story_10_14_2_202_dialog_content = "（<color=#FFB400>日蝕はもう始まっているのよ！</color>）",
  ui_story_10_15_1_1_dialog_content = "（僕は何をすればいいんだろう…）",
  ui_story_10_15_1_2_dialog_content = "（スーモアはもういない…）",
  ui_story_10_15_1_3_dialog_content = "（暗鬼に食われて…凄惨な終わりを遂げた…）",
  ui_story_10_15_1_4_dialog_content = "（これから…どうすれば…僕はどうすれば…）",
  ui_story_10_15_1_5_dialog_content = "グァア…",
  ui_story_10_15_1_6_dialog_content = "（みんなケガだらけだ…あの暗鬼たち…僕たちを放っておかないはず…）",
  ui_story_10_15_1_7_dialog_content = "（「日蝕」のように…）",
  ui_story_10_15_1_8_dialog_content = "（皆を…）",
  ui_story_10_15_1_9_dialog_content = "どうすれば…",
  ui_story_10_15_1_10_dialog_content = "走れ！",
  ui_story_10_15_1_11_dialog_content = "PlayerNameを引きずっていくんだ！",
  ui_story_10_15_1_12_dialog_content = "こいつ、ボーっとして動かねぇ！無理やりにでも連れてくぞ！",
  ui_story_10_15_1_13_dialog_content = "走れ！来た道を戻るんだ！",
  ui_story_10_15_1_14_dialog_content = "あ、暗鬼が追ってきてる…",
  ui_story_10_15_1_15_dialog_content = "後ろは任せて！",
  ui_story_10_15_1_16_dialog_content = "グアア！",
  ui_story_10_15_1_17_dialog_content = "カレン！？",
  ui_story_10_15_1_18_dialog_content = "くっ…平気よ、行って！",
  ui_story_10_15_1_19_dialog_content = "ったく…もうすぐ終わりだと思ったら、ま～た面倒なことに…",
  ui_story_10_15_1_20_dialog_content = "…",
  ui_story_10_15_1_21_dialog_content = "追ってきてる！？しつこいわね！",
  ui_story_10_15_1_22_dialog_content = "グァアア！",
  ui_story_10_15_1_23_dialog_content = "…！",
  ui_story_10_15_1_24_dialog_content = "PlayerName！しっかりして！",
  ui_story_10_15_1_25_dialog_content = "みんな、あなたの助けが必要なのよ！！",
  ui_story_10_15_1_26_dialog_content = "…",
  ui_story_10_15_1_27_dialog_content = "…………",
  ui_story_10_15_1_28_dialog_content = "バイス…通路を塞いでる暗鬼に射撃を！",
  ui_story_10_15_1_29_dialog_content = "カレンは距離を取って…左後方に攻撃を！",
  ui_story_10_15_1_30_dialog_content = "速射感知！",
  ui_story_10_15_1_31_dialog_content = "了解！",
  ui_story_10_15_1_32_dialog_content = "グアア！",
  ui_story_10_15_1_33_dialog_content = "ようやく元に戻ったわね！",
  ui_story_10_15_1_34_dialog_content = "ごめん…さっきは…スーモアが遺した感情に囚われて、ぼうっとしてしまって…",
  ui_story_10_15_1_35_dialog_content = "謝る必要はないわ。でも、一刻も早くいつも通りに戻って。",
  ui_story_10_15_1_36_dialog_content = "まだ何も終わっていないのだから。",
  ui_story_10_15_1_37_dialog_content = "私は白夜城に復命して、あなたはソラヴァンを修理しないといけないの。",
  ui_story_10_15_1_38_dialog_content = "目の前の暗鬼を倒して、生き残りましょう！",
  ui_story_10_15_1_39_dialog_content = "うん。カレンの言うとおりだよ。",
  ui_story_10_15_1_40_dialog_content = "もう大丈夫…みんなの戦いをサポートするよ！",
  ui_story_10_15_1_41_dialog_content = "えっと…PlayerNameが元通りになってくれたのはいいんだけど！",
  ui_story_10_15_1_42_dialog_content = "暗鬼が…",
  ui_story_10_15_1_43_dialog_content = "グォォ――！",
  ui_story_10_15_1_44_dialog_content = "命なんか惜しくねぇ、とか言ってみたいところだけどよ。",
  ui_story_10_15_1_45_dialog_content = "悪ぃな、妹が俺の帰りを待ってるんだ！",
  ui_story_10_15_1_46_dialog_content = "<size=45>全員、命がけで戦うぞ！ただし死ぬのは許さねぇ！！</size>",
  ui_story_10_15_1_47_dialog_content = "サメヤマ、声が大きすぎよ…やっぱりあなたは指揮官向きじゃないわね！",
  ui_story_10_15_1_48_dialog_content = "グァア…",
  ui_story_10_15_1_49_dialog_content = "ガアア！",
  ui_story_10_15_1_50_dialog_content = "こっちに来やがれ！",
  ui_story_10_15_1_51_dialog_content = "暗鬼が引き寄せられた！？",
  ui_story_10_15_1_52_dialog_content = "大人しくぶっ倒れてな！",
  ui_story_10_15_1_53_dialog_content = "グアア！",
  ui_story_10_15_1_54_dialog_content = "サメヤマ！ヘール様が助けにきたぜ！",
  ui_story_10_15_1_55_dialog_content = "かーッ！まさかこんな日が来るなんてな！ハハハハハ！",
  ui_story_10_15_1_56_dialog_content = "爆発注意～！",
  ui_story_10_15_1_57_dialog_content = "おわあぁ！？",
  ui_story_10_15_1_58_dialog_content = "気をつけろ、俺様まで吹っ飛ばすつもりか！？",
  ui_story_10_15_1_59_dialog_content = "暗鬼を引っ張ってきといて、ちゃんと始末しなかったのはあんたでしょ？",
  ui_story_10_15_1_60_dialog_content = "何が起こってるの？",
  ui_story_10_15_1_61_dialog_content = "はは…",
  ui_story_10_15_1_62_dialog_content = "こりゃみっともねぇ、R・Wのヤツらが助けに来たみてぇだ…",
  ui_story_10_15_1_63_dialog_content = "アイツらの火力はなかなかだぜ。ちょっとばかり、やかましいがな。",
  ui_story_10_15_1_64_dialog_content = "うぅ…助かった！よかった…！",
  ui_story_10_15_1_65_dialog_content = "うん…よかった…",
  ui_story_10_15_1_66_dialog_content = "はぁ…さすがにこの暗鬼の量は疲れたぜ。",
  ui_story_10_15_1_67_dialog_content = "サメヤマ、俺らがどうやってここに来たかわかるか？\nそれがよ、さっきあの山が揺れて…",
  ui_story_10_15_1_68_dialog_content = "兄貴ー！大丈夫か！？",
  ui_story_10_15_1_69_dialog_content = "まぁな。大した傷じゃねぇ…",
  ui_story_10_15_1_70_dialog_content = "わわわっ、この巨像すごい！",
  ui_story_10_15_1_71_dialog_content = "コレを持ち帰ることができたら、\nここまで来たのも無駄じゃなかったってことね！",
  ui_story_10_15_1_72_dialog_content = "みんな早く手伝って！分解して持ってくよ！",
  ui_story_10_15_1_73_dialog_content = "待って！",
  ui_story_10_15_1_74_dialog_content = "白夜城の人？",
  ui_story_10_15_1_75_dialog_content = "オティ、紹介が遅れたな…",
  ui_story_10_15_1_76_dialog_content = "そいつは白夜城のカレン。そっちの2人はバイスとPlayerNameだ。",
  ui_story_10_15_1_77_dialog_content = "おいおいおい、待ってくれ…ボス、白夜城のカレンって…あの護衛隊長の？",
  ui_story_10_15_1_78_dialog_content = "ヘール、お前は少し黙ってろ！",
  ui_story_10_15_1_79_dialog_content = "今この場所では、俺らは一緒に戦った仲間だ。",
  ui_story_10_15_1_80_dialog_content = "そうだよな？カレン。",
  ui_story_10_15_1_81_dialog_content = "…",
  ui_story_10_15_1_82_dialog_content = "わかったわよ。この巨像が欲しいってことでしょ？",
  ui_story_10_15_1_83_dialog_content = "じゃあ、誰が一番貢献したかで分け前を話し合ったらいいの？",
  ui_story_10_15_1_84_dialog_content = "それについては、今日は俺の言うことを聞いてくれ。余計な事は聞くな。",
  ui_story_10_15_1_85_dialog_content = "疑問があるなら、あとで基地に戻ってから説明してやる。",
  ui_story_10_15_1_86_dialog_content = "PlayerName！",
  ui_story_10_15_1_87_dialog_content = "お前、この黒い巨像をどうするんだ？\nなんなら俺らが引っ張ってやってもいいぜ！",
  ui_story_10_15_1_88_dialog_content = "えっ？",
  ui_story_10_15_1_89_dialog_content = "まだボーッとしてんのか？しっかりしろよ。",
  ui_story_10_15_1_90_dialog_content = "ああ、うん、大丈夫…もうしっかりしてるよ。",
  ui_story_10_15_1_91_dialog_content = "ならいいけどよ…",
  ui_story_10_15_1_92_dialog_content = "俺が言いたいのは、コレはお前のモンだってことだ。\nお前ら空の末裔の巨像だろ。",
  ui_story_10_15_1_93_dialog_content = "で、俺に一つ提案があるんだが…",
  ui_story_10_15_1_94_dialog_content = "提案って？",
  ui_story_10_15_1_95_dialog_content = "お前、俺たちの仲間になったらどうだ。\nそうすれば、堂々とこいつを基地に持って帰れるぜ。",
  ui_story_10_15_1_96_dialog_content = "僕は…",
  ui_story_10_15_1_97_dialog_content = "答えを急ぐことはねぇ。俺の考えを言っただけだ。",
  ui_story_10_15_1_98_dialog_content = "もしR・Wに来たいんなら、いつでも歓迎するぜ。",
  ui_story_10_15_1_99_dialog_content = "ありがとう。",
  ui_story_10_15_1_100_dialog_content = "でも僕は、3つのパーツが欲しいだけなんだ。",
  ui_story_10_15_1_101_dialog_content = "グリードは…君たちの好きにしていいよ。",
  ui_story_10_15_1_102_dialog_content = "わかった。ならそっちの2人はどうだ？何か言うこと有るか？",
  ui_story_10_15_1_103_dialog_content = "もし啓光と白夜城もこの巨像に興味があるってんなら、\nこのまま俺らが持ってくってわけにもいかねぇんじゃねぇのか？",
  ui_story_10_15_1_104_dialog_content = "PlayerNameがそう言うなら、あなたたちを止める理由はないと思うわ。",
  ui_story_10_15_1_105_dialog_content = "必要ないわ。",
  ui_story_10_15_1_106_dialog_content = "うん。最初に会ったときから、\n君たちが巨像を探しに来たってことは知っていたし。",
  ui_story_10_15_1_107_dialog_content = "それに、もう考えてあったから。グリードのことで争うつもりはないよ。",
  ui_story_10_15_1_108_dialog_content = "そりゃ気前がいいな。",
  ui_story_10_15_1_109_dialog_content = "そういうわけじゃ…単に興味がないってだけだよ。",
  ui_story_10_15_1_110_dialog_content = "PlayerName。",
  ui_story_10_15_1_111_dialog_content = "今まで色々あったみてぇだから、お前も複雑な気持ちだと思う。",
  ui_story_10_15_1_112_dialog_content = "でもな、あまり考えすぎないほうがいいぜ。\nお前はもう、十分よくやってる。",
  ui_story_10_15_1_113_dialog_content = "お前が静かな暮らしに戻りたいって言っても、誰も責めるヤツはいないさ！",
  ui_story_10_15_1_114_dialog_content = "サメヤマ…",
  ui_story_10_15_1_115_dialog_content = "ありがとう。",
  ui_story_10_15_1_116_dialog_content = "来たばっかで何だけどよ…今聞いたの、ボスが言ったんだよな？",
  ui_story_10_15_1_117_dialog_content = "ちっとばかり元気づけてやっただけだろ！何だよその目は！？",
  ui_story_10_15_1_118_dialog_content = "やめろやめろ、さっさと動け！",
  ui_story_10_15_1_119_dialog_content = "ッたく…休むヤツは休んで、働くやつはとっとと動け！",
  ui_story_10_15_1_120_dialog_content = "ほら、行った行った！",
  ui_story_10_15_1_121_dialog_content = "じゃあ私の1、2、3で始めるよ！",
  ui_story_10_15_1_122_dialog_content = "よっ…と！！",
  ui_story_10_15_1_123_dialog_content = "ヘール！そんなトコで一人で頑張ってどうするの！？",
  ui_story_10_15_1_124_dialog_content = "ただのウォーミングアップだよ！",
  ui_story_10_15_1_125_dialog_content = "お前の「スタート」の合図なんかで、素直に始めるとでも思ったか！？",
  ui_story_10_15_1_126_dialog_content = "どうやって引っ張るんだ！？この巨像デカ過ぎだろ！",
  ui_story_10_15_1_127_dialog_content = "なら、やっぱり…有用な部品だけ解体して持ってこうよ…",
  ui_story_10_15_1_128_dialog_content = "さんせ～い。",
  ui_story_10_15_1_129_dialog_content = "バップ、僕は先にソラヴァンに戻るけど、何か手伝うことはあるかな？",
  ui_story_10_15_1_130_dialog_content = "ううん、大丈夫だよ。",
  ui_story_10_15_1_131_dialog_content = "私たちで考えるから、気にしないで。",
  ui_story_10_15_1_132_dialog_content = "今は巨像に戻って休んだほうがいいよ。\n傷の状態を診ておくのを忘れずにね。",
  ui_story_10_15_1_133_dialog_content = "忘れないわよ、まだ痛むもの…",
  ui_story_10_15_1_134_dialog_content = "そういえばサメヤマにお別れを言っておこうと思ったけど、どこに行ったの？",
  ui_story_10_15_1_135_dialog_content = "ああ…えーと…「別れの挨拶はいらねぇ！」って。",
  ui_story_10_15_1_136_dialog_content = "そう…",
  ui_story_10_15_1_137_dialog_content = "じゃあ、私たちは行くけど、いいのね？それじゃ…",
  ui_story_10_15_1_138_dialog_content = "うん、バイバイ…",
  ui_story_10_15_1_139_dialog_content = "体には気を付けてね！また会おうね！",
  ui_story_10_15_1_140_dialog_content = "うん。またね…",
  ui_story_10_15_1_141_dialog_content = "僕は、どうやって今日にたどり着いたんだろう？",
  ui_story_10_15_1_142_dialog_content = "最初は…夢のせい？",
  ui_story_10_15_1_143_dialog_content = "「生きて…」",
  ui_story_10_15_1_144_dialog_content = "…また、<color=#FFB400>あの夢</color>を見たのですか？",
  ui_story_10_15_1_145_dialog_content = "うん。",
  ui_story_10_15_1_146_dialog_content = "夢とは、未知なるものへの渇望が具象化された幻影です。",
  ui_story_10_15_1_147_dialog_content = "そして…モンドルが…",
  ui_story_10_15_1_148_dialog_content = "生きるためだよ…17年前のあの日、\n僕は生きるために<color=#FFB400>暗鬼の力</color>を受け入れた…",
  ui_story_10_15_1_149_dialog_content = "もう一度空を…見たかった…",
  ui_story_10_15_1_150_dialog_content = "そして僕はスーモアの最期に立ち会った…",
  ui_story_10_15_1_151_dialog_content = "（呪ってやる…）",
  ui_story_10_15_1_152_dialog_content = "（PlayerName……）",
  ui_story_10_15_1_153_dialog_content = "幻影なんかじゃない…すべてが本当の事…",
  ui_story_10_15_1_154_dialog_content = "ソラヴァン…",
  ui_story_10_15_1_155_dialog_content = "ブレーンパーツは手に入れたけど、君にこのパーツを接続できるのか、\n僕は知らないんだ…",
  ui_story_10_15_1_156_dialog_content = "君がレベル6の巨像だったってことさえ、\n他の人から教えられたことだよ…",
  ui_story_10_15_1_E1_dialog_content = "……",
  ui_story_10_15_1_E2_dialog_content = "君が「戻って」きたら、直接文句を言ってやらないとね。",
  ui_story_10_15_1_157_dialog_content = "ブレーンパーツに接続ポートが3つ…",
  ui_story_10_15_1_158_dialog_content = "どれも同じに見えるけど。",
  ui_story_10_15_1_159_dialog_content = "…",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>「コントロールシステム…異常なし」</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>「生体モジュール…スリープ中」</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>「生命維持ユニット…作動中。作動負荷1名」</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>「エンジン…異常なし」</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>「ブレーンパーツ…接続中」</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>「1%……3%……8%……」</color>",
  ui_story_10_15_1_166_dialog_content = "これで…",
  ui_story_10_15_1_167_dialog_content = "終わったのね。",
  ui_story_10_15_1_168_dialog_content = "スーモアの身体は何一つ残らなかったでしょう。",
  ui_story_10_15_1_169_dialog_content = "そうね…PlayerNameは確かめにいこうともしなかったわ。",
  ui_story_10_15_1_170_dialog_content = "感知能力があるから、とっくに確認していたのだと思うわ…",
  ui_story_10_15_1_171_dialog_content = "これ以上気にする必要もないでしょう。",
  ui_story_10_15_1_172_dialog_content = "でも…本当にそれでいいのかしら？",
  ui_story_10_15_1_173_dialog_content = "スーモアはもういないけれど、天空ノ谷を滅ぼした暗鬼は…",
  ui_story_10_15_1_174_dialog_content = "まだあちこちにいるわ。",
  ui_story_10_15_1_175_dialog_content = "それに、PlayerNameの言っていた<color=#FFB400>「フィジェロ」</color>の存在もあるわ。",
  ui_story_10_15_1_176_dialog_content = "でも、彼は最後まで「フィジェロ」が何者なのかを聞けなかったみたいね。",
  ui_story_10_15_1_177_dialog_content = "…ほんの十数分の間に、あまりにも多くのことが起こったから…",
  ui_story_10_15_1_178_dialog_content = "ただ間に合わなかっただけかもしれない…",
  ui_story_10_15_1_179_dialog_content = "スーモアの最期を見届けた後、抜け殻みたいになってたわ。",
  ui_story_10_15_1_180_dialog_content = "すぐに元通りになったけど、まだどこかおかしい気がするの。",
  ui_story_10_15_1_181_dialog_content = "もしかしたら私たちを心配させたくなくて、いつも通りを装っているのかも…",
  ui_story_10_15_1_182_dialog_content = "もしくは、もっと重要な事があることを理解しているのかも…",
  ui_story_10_15_1_183_dialog_content = "いずれにせよ、私たちの助けが必要な時には、\n自分から何か言ってくれると信じるわ。",
  ui_story_10_15_1_184_dialog_content = "うん、それもそうね。",
  ui_story_10_15_1_185_dialog_content = "そういえばPlayerName、ソラヴァンの中に入ってから\nずいぶん経つけど…全然出てこないわね。",
  ui_story_10_15_1_186_dialog_content = "少し心配だわ…",
  ui_story_10_15_1_187_dialog_content = "パーツを持って一人で行くと言いだしたのは、\nきっと自分なりの考えがあってのことよ。",
  ui_story_10_15_1_188_dialog_content = "今しばらく、待つしかないわ…",
  ui_story_10_15_1_189_dialog_content = "うん…",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>「10%…23%…」</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>「33%…35%…」</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>「接続失敗。累計失敗回数：1回」</color>",
  ui_story_10_15_1_193_dialog_content = "大丈夫だ、もう一度…チャレンジしてみよう…",
  ui_story_10_15_1_194_dialog_content = "ブレーンパーツを接続…",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>「ブレーンパーツ…接続中」</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>「1%…3%…8%…」</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>「61%…67%…」</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>「76%……85%……」</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>「接続失敗。累計失敗回数：2回」</color>",
  ui_story_10_15_1_200_dialog_content = "まだ2回失敗しただけだ…一番最初にエンジンを起動させた時の事を考えれば…",
  ui_story_10_15_1_201_dialog_content = "なにせ、あの時は3000回以上失敗してたからね…",
  ui_story_10_15_1_202_dialog_content = "大丈夫…",
  ui_story_10_15_1_203_dialog_content = "もう一度。やり直しだ。",
  ui_story_10_15_1_204_dialog_content = "一番最初の手順からやり直してみよう。",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>「コントロールシステム…異常なし」</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>「生体モジュール…スリープ中」</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>「意識モジュール…損傷」</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>「生命維持ユニット…作動中。作動負荷1名」</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>「エンジン…異常なし」</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>「ブレーンパーツ…接続中」</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>「1%…3%…8%…」</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>「10%…25%…」</color>",
  ui_story_10_15_1_213_dialog_content = "…",
  ui_story_10_15_1_214_dialog_content = "…",
  ui_story_10_15_1_215_dialog_content = "やっぱり中に入ってみましょうよ！",
  ui_story_10_15_1_216_dialog_content = "状況を聞くだけでもいいから！",
  ui_story_10_15_1_217_dialog_content = "バイス…それでは邪魔になるわ。",
  ui_story_10_15_1_218_dialog_content = "わかってるけど…でも…",
  ui_story_10_15_1_219_dialog_content = "もしブレーンパーツと巨像が接続できなかったら…",
  ui_story_10_15_1_220_dialog_content = "もし…ソラヴァンを修復する方法が見つからなかったら…",
  ui_story_10_15_1_221_dialog_content = "その事実を…一人で受け入れるなんて、辛すぎると思うの。",
  ui_story_10_15_1_222_dialog_content = "やっぱり見にいってくる！絶対に邪魔はしないから！",
  ui_story_10_15_1_223_dialog_content = "はぁ…あなたね。",
  ui_story_10_15_1_224_dialog_content = "そんなに心配なら、入口の前で名前を呼べばいいじゃない。",
  ui_story_10_15_1_225_dialog_content = "空の末裔だもの。鋭い感覚器官と感知能力を持っているのだから…",
  ui_story_10_15_1_226_dialog_content = "きっと聞こえるはずよ。",
  ui_story_10_15_1_227_dialog_content = "それなら、一人で中に行かせるという約束を破ったことにならないわ。",
  ui_story_10_15_1_228_dialog_content = "確かに！すぐにやってみるわ！",
  ui_story_10_15_1_229_dialog_content = "さすがカレンね、そんな方法を思いつくなんて。",
  ui_story_10_15_1_230_dialog_content = "あなたから学んだやり方よ…",
  ui_story_10_15_1_231_dialog_content = "すぅ…",
  ui_story_10_15_1_232_dialog_content = "PlayerName！",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>「89%…97%…」</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>「100%、接続成功」</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>「ようこそ、こちらはブレーンパーツ」</color>",
  ui_story_10_15_1_236_dialog_content = "バイス！カレン！",
  ui_story_10_15_1_237_dialog_content = "ブレーンパーツの接続に成功した！\n意識モジュールを修復する方法を見つけたんだ！",
  ui_story_10_15_1_238_dialog_content = "ソラヴァンは助かるよ！",
  ui_story_10_15_1_239_dialog_content = "つまり…",
  ui_story_10_15_1_240_dialog_content = "あのPlayerNameという空の末裔が、\nスーモアという空の末裔の裏切り者を撃破したと。",
  ui_story_10_15_1_241_dialog_content = "それから、黒き巨像がR・Wの手に渡り…",
  ui_story_10_15_1_242_dialog_content = "ノラは彼らを止めなかったどころか、手助けをしたと？",
  ui_story_10_15_1_243_dialog_content = "いかにも。",
  ui_story_10_15_1_244_dialog_content = "あの空の末裔が、我々の計画に影響を及ぼす可能性は？",
  ui_story_10_15_1_245_dialog_content = "ない。より面白いことになるというだけだ。",
  ui_story_10_15_1_246_dialog_content = "ソルラドも、そう思っているだろうな。",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>「セルフチェック機能起動」</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>「コントロールシステム、チェック…稼働中。部品損耗率39％、メンテナンスが必要です」</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>「生体モジュール、チェック…稼働中。部品損耗率46％、メンテナンスが必要です」</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>「生命維持ユニット、チェック…稼働中。\n警告、稼働負荷が限界に到達。メンテナンスが必要です」</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>「メンテナンス機能、チェック…異常なし。起動中…」</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>「エラー、意識モジュールが欠損しています。\nメンテナンス機能を起動できません」</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>「…起動失敗。累計失敗回数：1012回」</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>「意識モジュールをインストール後、\nメンテナンス機能を再起動してください」</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>「警告、部品損耗率が50％を超過すると、\n正常に機能を起動できなくなります」</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>「操作権限再認証。名前を入力してください」</color>",
  ui_story_70000101_11_dialog_content = "ソラヴァン…",
  ui_story_70000101_12_dialog_content = "PlayerName、ソラヴァンの調子は？",
  ui_story_70000101_13_dialog_content = "…",
  ui_story_70000101_14_dialog_content = "意識モジュールがないと、セルフメンテナンスができないって。\nかなり良くない状況だ。",
  ui_story_70000101_15_dialog_content = "もっと早く僕が気付いて、\n何より最優先でソラヴァンを修復するべきだったんだ…",
  ui_story_70000101_16_dialog_content = "あなただけのせいじゃないわ。\nソラヴァンと長い間一緒にいたのに気付かなかったのは、私も同じよ。",
  ui_story_70000101_17_dialog_content = "それに、そこまで心配いらないわ。\nだって、もう解決方法は分かってるんでしょ？",
  ui_story_70000101_18_dialog_content = "手がかりは見つかってる。",
  ui_story_70000101_19_dialog_content = "「ブレーンパーツ」が座標を出してくれた。\nでも…これって、どこだろう？",
  ui_story_70000101_20_dialog_content = "ちょっと見せて。",
  ui_story_70000101_21_dialog_content = "この座標…<color=#FFB400>「暗面」</color>じゃない！？",
  ui_story_70000101_22_dialog_content = "私の記憶が正しければ、ここはたぶん…\n<color=#FFB400>「80号シェルター」</color>よ。",
  ui_story_70000101_23_option_content = "暗面…？",
  ui_story_70000101_24_option_content = "80号シェルター…？",
  ui_story_70000101_25_dialog_content = "「暗面」っていうのは、永久極夜地帯に近い区域の総称よ。",
  ui_story_70000101_26_dialog_content = "「80号シェルター」は、この座標が示す位置にあるわ。",
  ui_story_70000101_27_dialog_content = "とても危険な場所よ。",
  ui_story_70000101_28_dialog_content = "昼は短く、夜が長い。\nそれに、大量の暗鬼が集結しているとも言われている。",
  ui_story_70000101_29_dialog_content = "PlayerName、今いいかしら？",
  ui_story_70000101_30_dialog_content = "え？シェオルさんからの通信…？",
  ui_story_70000101_31_dialog_content = "「暗面」について調べてるって聞いたから。\nちょうど、私も少し手がかりを知ってるの。",
  ui_story_70000101_32_dialog_content = "え？どうしてそれを？",
  ui_story_70000101_33_dialog_content = "影ノ街の商人だもの、\nビジネスの匂いには敏感じゃなくちゃ。",
  ui_story_70000101_34_dialog_content = "なるほど…「トクベツな情報網」ってやつですね？",
  ui_story_70000101_35_dialog_content = "さすがは常連さんね、分かってるじゃない。",
  ui_story_70000101_X35_dialog_content = "無料で忠告しておいてあげるわ――",
  ui_story_70000101_36_dialog_content = "あなたが調べてる場所はとても危険よ。\n<color=#FFB400>「底なし沼」</color>っていう異名があるほど。",
  ui_story_70000101_37_dialog_content = "…危険だとしても、\n僕はいかなきゃならないんです。",
  ui_story_70000101_38_dialog_content = "ブレーンパーツが唯一くれた手がかりが、その場所なんです。\nソラヴァンを救えるチャンスを、見逃すわけには行きません。",
  ui_story_70000101_39_dialog_content = "PlayerName、一時の衝動で\n冷静な判断を忘れてはいけないわ。",
  ui_story_70000101_40_dialog_content = "準備も情報もないまま「底なし沼」に向かうのは、無謀よ。",
  ui_story_70000101_41_dialog_content = "…",
  ui_story_70000101_42_dialog_content = "その通りよ、私も同意見ね。",
  ui_story_70000101_43_dialog_content = "それで、少しばかりの「代価」を払ってもらえるなら、\n情報集めを手伝ってあげてもいいわ…",
  ui_story_70000101_44_dialog_content = "対価って…もしかして、白夜コインですか？",
  ui_story_70000101_45_dialog_content = "白夜城にも、あの辺りに関する記録があるはずよ。",
  ui_story_70000101_46_dialog_content = "探してみるわ。",
  ui_story_70000101_47_dialog_content = "それなら、お願いするよ。\n出来るだけでいい、どうか助けて。",
  ui_story_70000101_48_dialog_content = "一通りソラヴァンの状況をチェックしてみたけど、\n今のところ、正常な稼働は保ててる。ひとまず心配はいらないわ。",
  ui_story_70000101_49_dialog_content = "もうそろそろ、カレンとシェオルさんの\n情報集めも一段落ついてる頃じゃないかな。",
  ui_story_70000101_50_dialog_content = "啓光の仲間にも手がかりを探してもらってるから、安心して。",
  ui_story_70000101_51_dialog_content = "有用な手がかりが見つかるといいな…",
  ui_story_70000101_52_dialog_content = "今はこの座標だけが、ソラヴァンを救える希望だから。",
  ui_story_70000101_53_dialog_content = "座標が正しければ、\nたぶんシェルターを丸ごと一つ、捜索することになるわ。",
  ui_story_70000101_54_dialog_content = "一番小さいタイプだったとしても、\n数日はかかるわね。",
  ui_story_70000101_55_dialog_content = "もっと具体的な位置を\n確認することはできないの？",
  ui_story_70000101_56_dialog_content = "ダメなんだ。\n大体の方向しか分からない。",
  ui_story_70000101_57_dialog_content = "でも、目標に近づけば、もしかしたら…",
  ui_story_70000101_58_dialog_content = "PlayerName、聞こえる？",
  ui_story_70000101_59_dialog_content = "カレン！聞こえるよ！",
  ui_story_70000101_60_dialog_content = "よかった。今、黎明学院の図書館にいるの。\n通信状態が良くないから、簡潔に言うわ。",
  ui_story_70000101_61_dialog_content = "図書館に「80号シェルター」について書かれた\n戦争の記録があったわ。",
  ui_story_70000101_62_dialog_content = "その記録によれば、「80号シェルター」はかつて啓光の前哨基地で、\n輸送の中継点だったらしいの。",
  ui_story_70000101_63_dialog_content = "極夜に近いシェルターだから、\n暗鬼に対抗する最前線になったこともあった。",
  ui_story_70000101_64_dialog_content = "ところが、<color=#FFB400>「暗面戦争」</color>の時、\n他のシェルターと距離が離れていたのに暗鬼の猛攻を受けて、補給線が断たれ…",
  ui_story_70000101_65_dialog_content = "啓光軍はシェルターを放棄し、ほうほうの体で撤退したそうよ。",
  ui_story_70000101_66_option_content = "「暗面戦争」？",
  ui_story_70000101_67_dialog_content = "聞いたことがあるわ。\n20年以上前にあった、暗鬼の大規模進攻のことよ。",
  ui_story_70000101_68_dialog_content = "大量の暗鬼が極夜から襲撃して来て、\n戦いは…悲惨だったそうよ。",
  ui_story_70000101_69_dialog_content = "最終的には啓光連邦が勝ったけど、それまでにシェルターをいくつも失って、\n何人もの軍人が命を落とした。高い代償を払ってるわ。",
  ui_story_70000101_70_dialog_content = "私が読んだ本にもそう書かれていたわ。",
  ui_story_70000101_71_dialog_content = "それによれば、啓光軍は撤退の時に多くの物資を置き去りにしているらしいわ。\nあなたの探している巨像のモジュールも、おそらくそのうちの1つでしょう。",
  ui_story_70000101_72_dialog_content = "分かった、ありがとう！",
  ui_story_70000101_73_dialog_content = "どういたしまして。大したことではないわ。",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>ピピピ…</color>",
  ui_story_70000101_75_dialog_content = "また通信だ。もしもし？",
  ui_story_70000101_76_dialog_content = "PlayerName、私よ。",
  ui_story_70000101_77_dialog_content = "シェオルさん！\n何か情報はつかめましたか？",
  ui_story_70000101_X77_dialog_content = "情報は入ったけど…\nあまり、いい知らせじゃないわね。",
  ui_story_70000101_78_dialog_content = "情報屋が言うには、\n暗鬼が群がっているらしいって話よ。",
  ui_story_70000101_79_dialog_content = "ソラヴァンがなければ、\n「底なし沼」の縁に近づくことさえできないでしょうね。",
  ui_story_70000101_80_dialog_content = "目的のシェルターの中については、すでに廃墟。\n戦いの跡が残っている以外、何もないそうよ。",
  ui_story_70000101_81_dialog_content = "エネルギーコアは稼働してるけど、状態はひどいわ。\n防衛システムを維持できないどころか、いつ止まってもおかしくない状態よ。",
  ui_story_70000101_82_dialog_content = "1人だけ、そこから生きて帰ってきた人の話では、\nシェルターに入れる唯一の通路は――",
  ui_story_70000101_83_dialog_content = "崩壊で出来た<color=#FFB400>裂け目</color>だそうよ。",
  ui_story_70000101_84_dialog_content = "そうなんですか…？",
  ui_story_70000101_85_dialog_content = "分かりました。",
  ui_story_70000101_86_dialog_content = "幸運を祈ってるわ。",
  ui_story_70000101_87_dialog_content = "ちゃんと生きて帰って、\n残りのお代金を支払ってね。",
  ui_story_70000101_88_dialog_content = "が、がんばります…",
  ui_story_70000101_89_dialog_content = "あとは…フィリス先輩がまだね。\n珍しいわ、情報をつかめてないのかしら…？",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>ピピピ…</color>",
  ui_story_70000101_91_dialog_content = "あら？フィリス先輩からのファイルだわ。",
  ui_story_70000101_92_dialog_content = "どんなファイル？僕にも見せて。",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>「暗面における戦闘指南」？</color>",
  ui_story_70000101_94_option_content = "そんなものがあったんだ？",
  ui_story_70000101_95_dialog_content = "私の知る限りでは、\nこんなもの存在しなかった気がするけど…",
  ui_story_70000101_96_dialog_content = "それに、作りが簡単だわ。",
  ui_story_70000101_97_dialog_content = "目次もないし、様式も整ってない。",
  ui_story_70000101_98_dialog_content = "正規のものではなさそうよ。",
  ui_story_70000101_99_dialog_content = "怪しい情報ってこと？",
  ui_story_70000101_100_dialog_content = "でも、フィリス先輩が間違った情報を送るはずないわ。",
  ui_story_70000101_101_option_content = "フィリスが手伝ってくれたの？",
  ui_story_70000101_102_dialog_content = "珍しいね…",
  ui_story_70000101_103_dialog_content = "大事なのはそこじゃないけど…\nまぁ、あなたになら、言っても構わないわね…",
  ui_story_70000101_104_dialog_content = "フィリス先輩、この間仕事をサボって昼寝してたことを\n私に黙っててほしいのよ…",
  ui_story_70000101_105_dialog_content = "それで、代わりに「80号シェルター」の資料を\nくれるって約束してくれたの。",
  ui_story_70000101_106_dialog_content = "…やっぱり、フィリスらしいや…",
  ui_story_70000101_107_dialog_content = "情報に関して、フィリス先輩以上に信頼できる人はいないわ。",
  ui_story_70000101_108_dialog_content = "ただ…この手帳、作りが簡素すぎるわね。",
  ui_story_70000101_109_dialog_content = "何が書いてあるの？",
  ui_story_70000101_110_dialog_content = "「暗面における戦闘指南、第1条――」",
  ui_story_70000101_111_dialog_content = "「いかなる兵士も、\n暗面への進入および戦闘は避けること！！」",
  ui_story_70000101_112_dialog_content = "…えっ？",
  ui_story_70000101_113_dialog_content = "暗面って…そんなに危険な場所なの？",
  ui_story_70000101_114_dialog_content = "「すでに知り得ている情報によれば、\n暗面は非常に危険な区域である」",
  ui_story_70000101_115_dialog_content = "「暗面には濃い暗力が充満しており、光霊は行動すら困難になる。\nしかも、暗力の作用は夜になるとさらに強くなる」",
  ui_story_70000101_116_dialog_content = "「また、暗鬼は暗面一帯に生息しており、\n極めて強大な暗鬼も含まれる。非常に危険である！」",
  ui_story_70000101_117_dialog_content = "「いかなる兵士も行ってはならない」か…\nじゃあ、君に迷惑がかかっちゃうね。",
  ui_story_70000101_119_dialog_content = "君を巻き込んで、\n罰を受けることになったりさせるわけにはいかない。",
  ui_story_70000101_120_dialog_content = "それか、今からでもヒイロさんに事情を説明して…",
  ui_story_70000101_121_dialog_content = "PlayerName…",
  ui_story_70000101_122_dialog_content = "私は構わないわ。",
  ui_story_70000101_123_dialog_content = "ソラヴァンはPlayerNameの大切な家族でしょ。\n私にとっても、大切な仲間よ。",
  ui_story_70000101_124_dialog_content = "仲間が困ってるのに、\n見過ごすなんてできないわ！",
  ui_story_70000101_125_dialog_content = "それに、私はもう事情を知ってる。\n事情を知りながら報告しないのは、啓光の軍令では共犯と同じことよ。",
  ui_story_70000101_126_dialog_content = "まぁ、今回の行動は…大元帥と軍団長たちに\n知られさえしなければ、問題ないはずよ…",
  ui_story_70000101_127_dialog_content = "たぶん、きっと問題ないわ！",
  ui_story_70000101_128_dialog_content = "ごめん、そんなリスクまで抱えさせてしまって…",
  ui_story_70000101_129_dialog_content = "暗面での戦闘に関する注意事項が、\n詳しく書かれてるみたいね。",
  ui_story_70000101_130_dialog_content = "でも…一体誰が書いたのかしら？",
  ui_story_70000101_131_dialog_content = "それは後で考えることにしよう。",
  ui_story_70000101_132_dialog_content = "今はとりあえず、\n手に入った情報から作戦を立てることにしよう。",
  ui_story_70000101_133_dialog_content = "大量の暗鬼がいて、暗力の影響は夜に増す。\nしかも、夜が長くて、昼は短い…",
  ui_story_70000101_134_dialog_content = "かなり難しい作戦になりそうね…",
  ui_story_70000101_135_dialog_content = "ソラヴァンで飛んで行けば、\n途中の暗鬼は無視できるよ。",
  ui_story_70000101_136_dialog_content = "シェルターに入ったら、\nブレーンパーツの測定機能で、目的のものを探せばいい。",
  ui_story_70000101_137_dialog_content = "戦闘をできるだけ早く片付ければ、\n昼間のうちに終われるかもしれない…",
  ui_story_70000101_138_dialog_content = "それでもリスクは大きいわ。\n万が一、地下に上級暗鬼が潜伏していたら、どうするの？",
  ui_story_70000101_139_dialog_content = "回り道するんだ。僕たちの目的は戦うことじゃない。\nモジュールを見つけたら、すぐに離れよう。",
  ui_story_70000101_140_dialog_content = "わかったわ。",
  ui_story_70000101_141_dialog_content = "じゃあ、出発しよう。\n目的地は「80号シェルター」だ！",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>啓光・軍事警戒線</color>",
  ui_story_70000101_143_dialog_content = "ソラヴァンは警戒線を越えて、\n「80号シェルター」の方角へ進んでいます。",
  ui_story_70000101_144_dialog_content = "…本当に2人を放っておかれるのですか？",
  ui_story_70000101_145_dialog_content = "私に聞いたのか？",
  ui_story_70000101_146_dialog_content = "はい。この件は…\n大元帥にしか、決断できないものです。",
  ui_story_70000101_147_dialog_content = "あの2人がフィリスを使って80号シェルターを調べさせたと、報告したのはお前だろう？\nであれば、目的まで分かっているはずだ。",
  ui_story_70000101_148_dialog_content = "PlayerNameは、巨像の意識モジュールを修復できる古代科学技術の遺物が\n80号シェルターにあるとの情報を得たようです。",
  ui_story_70000101_149_dialog_content = "それを探しているのは何故だ？",
  ui_story_70000101_150_dialog_content = "それは…以前、スーモアおよびノラとの戦闘において、彼の巨像――\nソラヴァンは、意識モジュールを破壊されています。",
  ui_story_70000101_151_dialog_content = "彼にとって、巨像は家族のようなものです。\n巨像が意識モジュールを失ったことは、家族が意識を失ったも同然なのでしょう。",
  ui_story_70000101_152_dialog_content = "ならば、理屈は通っているではないか。",
  ui_story_70000101_153_dialog_content = "家族を救おうとする者を止めるような理由は、私にはない。",
  ui_story_70000101_154_dialog_content = "悪意がない限り、少しばかり好きなようにさせてやっても、\n構わないと思うが。",
  ui_story_70000101_155_dialog_content = "これまで啓光と暗鬼の戦いで何度か貢献している。\nその報酬とでもしておこう。",
  ui_story_70000101_156_dialog_content = "しかし、委員会にはどのようにご説明を？暗面を探索することは許されません。\n大元帥とて、そのようにお考えでは？",
  ui_story_70000101_157_dialog_content = "そう、確かに問題だ…",
  ui_story_70000101_158_dialog_content = "では、こう伝えておけ。空の末裔は、自らの意志で暗面へ向かった。\n我々はその阻止を試みたが、失敗に終わった。",
  ui_story_70000101_159_dialog_content = "また、委員会の禁止令に従い、啓光軍は暗面内まで追跡はせず、\n警戒線上で待機することにした、と。",
  ui_story_70000101_160_dialog_content = "空の末裔は啓光の者ではない。\nしかも、各勢力に人脈を持っている。",
  ui_story_70000101_161_dialog_content = "それだけでも、委員会が\n軽々に干渉しようとは思わんだろう。",
  ui_story_70000101_162_dialog_content = "しかし…あの地は大変危険です。",
  ui_story_70000101_163_dialog_content = "豊富な戦闘経験を持っている。\n能力も、ひとまず信頼に値する。",
  ui_story_70000101_164_dialog_content = "あの「指南」通りに慎重に行動さえしていれば、\n問題は起こらん。",
  ui_story_70000101_165_dialog_content = "では、なぜ…\nここに留まっていらっしゃるのですか？",
  ui_story_70000101_166_dialog_content = "優れた戦闘能力だけでは、\nまだ足りないからだ。例えば――",
  ui_story_70000101_167_dialog_content = "いつでも彼らを「底なし沼」から\n引き上げることができる、命綱だな。",
  ui_story_70000101_168_dialog_content = "各部隊に警戒を続けるよう命令しろ。\n暗面の動向には、終始注意を払え。",
  ui_story_70000101_169_dialog_content = "了解しました。",
  ui_story_70000101_170_dialog_content = "フィリス。",
  ui_story_70000101_171_dialog_content = "にゃ～！？",
  ui_story_70000101_172_dialog_content = "お前の通信端末は、一時私が預かる。",
  ui_story_70000101_173_dialog_content = "「怠慢」については…\nすべてが終わってから、改めて話すとしよう。",
  ui_story_70000101_174_dialog_content = "はい～…",
  ui_story_70000101_175_dialog_content = "今は「80号シェルター」の動向を監視し、\n何か異常があれば、ただちに報告するように。",
  ui_story_70000101_176_dialog_content = "分かりましたにゃあ…",
  ui_story_70000101_177_dialog_content = "バイスたち…\n面倒なことに巻き込まれちゃってるにゃぁ…",
  ui_story_70000101_178_dialog_content = "「80号シェルター」…",
  ui_story_70000101_179_dialog_content = "誰でも気軽に行けるようなところではない。\nあの2人、実に大した度胸ではないか？",
  ui_story_70000201_1_dialog_content = "啓光連邦が極夜付近に展開してる警戒線を超えたわ。",
  ui_story_70000201_2_dialog_content = "もう少しで、80号シェルターに着くはずよ。",
  ui_story_70000201_3_dialog_content = "空が明らかに暗くなってる…\nこれが「暗面」なの？",
  ui_story_70000201_4_dialog_content = "暗さだけで気分が悪くなるわね。\n呼吸まで苦しくなってきた気がするわ…",
  ui_story_70000201_5_dialog_content = "戦闘に影響がないといいんだけど…",
  ui_story_70000201_6_dialog_content = "手帳を確認しようか？",
  ui_story_70000201_7_dialog_content = "ええと…",
  ui_story_70000201_8_dialog_content = "「第3条：『底なし沼』での作戦行動は、\n可能な限り戦闘を回避し、力の及ぶ範囲内で行動すること」",
  ui_story_70000201_9_dialog_content = "「80号シェルターには、呼吸ができなくなるほど重く濃い暗力が充満し、\n故に『底なし沼』とも呼ばれている」",
  ui_story_70000201_10_dialog_content = "「暗力により通信さえも阻害される。\n数メートル離れただけでも、通信機が正常に使用できなくなる」",
  ui_story_70000201_11_dialog_content = "「さらに、こうした暗力の影響は、時間により変化する。」",
  ui_story_70000201_12_dialog_content = "「夜間の影響は昼間の2倍以上となる」",
  ui_story_70000201_13_dialog_content = "つまり、普通の暗鬼であっても厄介な敵になるってことね。",
  ui_story_70000201_14_dialog_content = "やっぱり、できるだけ戦闘を避けた方がいいわね。",
  ui_story_70000201_15_dialog_content = "うん…それに、時間の制限もある。\n夜になったら、もっと不利だ。",
  ui_story_70000201_16_dialog_content = "ソラヴァンの機動力を活かして、\n昼間に侵入して、できるだけ早く終わらせよう。",
  ui_story_70000201_17_dialog_content = "PlayerName…昔に比べて、\nずいぶん頼もしくなったわね？",
  ui_story_70000201_18_dialog_content = "えっ？そ、そうかな？",
  ui_story_70000201_19_dialog_content = "ちょっと照れちゃうな…",
  ui_story_70000201_20_dialog_content = "…それより、さっきから、考えてたんだけど…",
  ui_story_70000201_21_dialog_content = "これを書いた人、80号シェルターに詳しすぎるよ。\n昔、実際に戦ったことがあるんじゃないかな？",
  ui_story_70000201_22_dialog_content = "それは分からないわ…",
  ui_story_70000201_23_dialog_content = "正式な書類じゃないみたいだし、署名もないもの。",
  ui_story_70000201_24_dialog_content = "どこかの前線の指揮官とかが部下のためにとりあえずで書いた、\n「注意書き」って言った方が近いわね。",
  ui_story_70000201_25_dialog_content = "不思議だね…",
  ui_story_70000201_26_dialog_content = "でも、フィリス先輩が提供してくれた資料なら\n絶対に間違いないし、書かれてたことは信用できるわ。",
  ui_story_70000201_27_dialog_content = "最悪の事態にならないことを願うばかりだよ。",
  ui_story_70000201_28_dialog_content = "PlayerName、外を見て！",
  ui_story_70000201_29_dialog_content = "あれが80号シェルターじゃない？",
  ui_story_70000201_30_dialog_content = "ここが…？",
  ui_story_70000201_31_dialog_content = "想像してたのと、まったく違ったよ…",
  ui_story_70000201_32_dialog_content = "僕の印象にある啓光連邦のシェルターっていえば、\n頑丈な鉄の壁と、ものものしく並んだ大砲だけど…",
  ui_story_70000201_33_dialog_content = "焼け跡に銃弾の痕が残ったボロボロの壁、\nそれに使えなくなって捨てられた武器の残骸しかない…",
  ui_story_70000201_34_dialog_content = "まるで今でも災難と戦火の真っただ中にいるみたいだ…",
  ui_story_70000201_35_dialog_content = "こんな所に…本当に僕たちが探してるモジュールがあるのかな？",
  ui_story_70000201_36_dialog_content = "昔、激戦があった場所だし、\n長年廃棄されたままだから…",
  ui_story_70000201_37_dialog_content = "今はおそらく、暗鬼の巣窟になっているでしょうね…",
  ui_story_70000201_38_dialog_content = "でも、私は啓光連邦がいつの日かきっと、\n取り戻せると信じてるわ。",
  ui_story_70000201_39_dialog_content = "どのシェルターにも、貴重なエネルギーに物資、\nそして科学技術が詰まっているの。",
  ui_story_70000201_40_dialog_content = "絶対に…それを暗鬼に譲ったりはしない。",
  ui_story_70000201_41_dialog_content = "…",
  ui_story_70000201_42_dialog_content = "地上には暗鬼がうようよいるわ。\nいちいち戦ってたら、時間がいくらあっても足りないわね。",
  ui_story_70000201_43_dialog_content = "どこか隠れられる所にソラヴァンを停めて、\nこっそりシェルターへ向かおう。",
  ui_story_70000201_44_dialog_content = "まだ夜が明けたばかりだから、十分時間はあるはず！",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>しばらくして</color>",
  ui_story_70000201_46_dialog_content = "これが…暗力の副作用？",
  ui_story_70000201_47_dialog_content = "身体がものすごく重いわ。\nまるで何十キロもあるサンドバッグを背負ってるみたい…",
  ui_story_70000201_48_dialog_content = "僕もだよ。\nちょっと歩いただけで、息が切れる…",
  ui_story_70000201_49_dialog_content = "これが、資料に書いてあった…\n暗面の影響ってことでしょうね。",
  ui_story_70000201_50_dialog_content = "こんな状態じゃ、戦うなんてムリだわ…",
  ui_story_70000201_51_dialog_content = "まずは何とかして、入口を探そう。",
  ui_story_70000201_52_dialog_content = "ここまでボロボロじゃ、\n本来の入口を探し出すのはムリだね。",
  ui_story_70000201_53_dialog_content = "捨てられた鋼板にうっすらと残ってる「80」っていう文字ぐらいしか、\nここが啓光のシェルターだったっていう証拠が見つからない…",
  ui_story_70000201_54_dialog_content = "メインフレームが折れて、外側の防御壁も完全に崩れてるわ。\n建物自体が変形してしまってる…",
  ui_story_70000201_55_dialog_content = "少なくとも震度9以上の地震が起きたか、\n精鋭暗鬼の進攻を24時間以上受けたかのどちらかね…",
  ui_story_70000201_56_dialog_content = "そうでもなければ、啓光のシェルターの防衛設備が\nここまで壊れるなんてこと、あり得ないわ。",
  ui_story_70000201_57_dialog_content = "入口は？",
  ui_story_70000201_58_dialog_content = "完全に埋まってるわね。",
  ui_story_70000201_59_dialog_content = "少なくとも見える範囲内には、見当たらないわ。",
  ui_story_70000201_60_dialog_content = "シェオルさんの言ってた、\n<color=#FFB400>裂け目</color>を見つけるしかなさそうだね。",
  ui_story_70000201_61_dialog_content = "グォォ――！",
  ui_story_70000201_62_dialog_content = "PlayerName、側面からよ！",
  ui_story_70000201_63_dialog_content = "暗鬼！？一体どこから…",
  ui_story_70000201_64_dialog_content = "暗鬼が出て来た方向に、\n裂け目みたいなものがあるわ！",
  ui_story_70000201_65_dialog_content = "どうやら、戦いは避けられなさそうだね…",
  ui_story_70000201_66_dialog_content = "バイス、手帳に書いてあった通り、\n慎重に対応しよう。",
  ui_story_70000201_67_dialog_content = "任せて！",
  ui_story_70000202_1_dialog_content = "ふぅ…はぁ…",
  ui_story_70000202_2_dialog_content = "やっと…終わったの？",
  ui_story_70000202_3_dialog_content = "頭が…割れそうだ…",
  ui_story_70000202_4_dialog_content = "光の軌跡も、よく見えない…",
  ui_story_70000202_5_dialog_content = "PlayerName！？",
  ui_story_70000202_6_dialog_content = "大丈夫だよ。ひどい目まいがしただけだ。",
  ui_story_70000202_7_dialog_content = "面倒を避けるためにも、静かに進みましょ。",
  ui_story_70000202_8_dialog_content = "こんなに厳しい環境だなんて、思わなかった…",
  ui_story_70000202_9_dialog_content = "でも、あきらめるワケにはいかない。\nソラヴァンを助けるために…",
  ui_story_70000202_10_dialog_content = "まずは裂け目を見てみよう。",
  ui_story_70000202_11_dialog_content = "ええっ…！？",
  ui_story_70000202_12_dialog_content = "これのどこが裂け目なのよ！？",
  ui_story_70000202_13_dialog_content = "どう見たってただの絶壁じゃない！",
  ui_story_70000202_14_dialog_content = "下の方、何かがかすかに光ってるのが見える。",
  ui_story_70000202_15_dialog_content = "何かの機械のランプみたいだ！",
  ui_story_70000202_16_dialog_content = "このシェルター、本当にまだ動いてるんだ…",
  ui_story_70000202_17_dialog_content = "あそこに何かの配管が飛び出してるわね。\n足場にできそうよ…",
  ui_story_70000202_18_dialog_content = "これぐらいの高さなら、\nPlayerNameを連れてても下まで降りられるわ…",
  ui_story_70000202_19_dialog_content = "でも、出る時は別の道を探さないといけないわね。",
  ui_story_70000202_20_dialog_content = "出口の情報も…書いてあるの？",
  ui_story_70000202_21_dialog_content = "あったはずよ、確認するわ…",
  ui_story_70000202_22_dialog_content = "「80号シェルターには、\n深部のコアルームから地上に通じる非常口がある」",
  ui_story_70000202_23_dialog_content = "「しかし、外敵の進入を防ぐため、\n内側からしか開けることができない構造になっている」",
  ui_story_70000202_24_dialog_content = "「また通路の入口も見つけづらくなっており、\nエネルギーコアの側に隠し扉がある」",
  ui_story_70000202_25_dialog_content = "「軽く3回、強く3回、再び軽く3回のリズムで\nコアルーム北面の壁を叩くと、隠し扉が開く」",
  ui_story_70000202_26_dialog_content = "シェオルさんも知らないような、\n細かい情報が書かれてるんだね…",
  ui_story_70000202_27_dialog_content = "80号シェルターについて、こんなに細かく知ってるなんて…\n確かに書いた人、ここで働いていたか、戦ったことがあるのかもしれないわね。",
  ui_story_70000202_28_dialog_content = "これで地上に戻る方法も分かったわ。\n早く行動しましょ。",
  ui_story_70000202_29_dialog_content = "PlayerName、私にしっかりつかまって。",
  ui_story_70000202_30_dialog_content = "イヤな予感がするんだけど、\nこの流れ、もしかして…",
  ui_story_70000202_31_dialog_content = "よいしょっ！",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>うわあああああ――！</anim>",
  ui_story_70000202_33_dialog_content = "やっぱり――",
  ui_story_70000202_34_dialog_content = "PlayerName、舌を噛むわよ！",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>あああああ――！</anim></size>",
  ui_story_70000202_36_dialog_content = "とうっ！",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>ああああ――！！！</anim></size>",
  ui_story_70000202_38_dialog_content = "…PlayerName、もう着地してるわよ。",
  ui_story_70000202_39_dialog_content = "えっ…あ？ほ、本当だ…",
  ui_story_70000202_40_dialog_content = "大丈夫？",
  ui_story_70000202_41_dialog_content = "でも…まだ浮いてるみたいだ？",
  ui_story_70000202_42_dialog_content = "頭が、クラクラする…ダメだ…",
  ui_story_70000202_43_dialog_content = "え？着地のショックかしら？\n休憩したほうがいい？",
  ui_story_70000202_44_dialog_content = "大丈夫、ちょっと落ち着けば…",
  ui_story_70000202_45_dialog_content = "周りの状況はどう？",
  ui_story_70000202_46_dialog_content = "ひとまず、暗鬼は見当たらないわ。",
  ui_story_70000202_47_dialog_content = "この辺りは…シェルターの上層部みたいね。",
  ui_story_70000202_48_dialog_content = "機械の残骸が散らばってるわ。\n啓光式の武装の残骸も混ざってるみたい。",
  ui_story_70000202_49_dialog_content = "…壁に<color=#FFB400>「第2換気シャフト」</color>って書いてあるわね。",
  ui_story_70000202_50_dialog_content = "シェルター内部に入れたことは確かみたいだね。",
  ui_story_70000202_51_dialog_content = "壁が弾痕だらけだわ。\nそうとう激しい戦いがあったのね…",
  ui_story_70000202_52_dialog_content = "「暗面戦争」の？",
  ui_story_70000202_53_dialog_content = "落ちてた弾丸の殻の型番が過去に啓光で作られていたものと合致してるわ。\nたぶんその時ので間違いないわね。",
  ui_story_70000202_54_dialog_content = "資料に「行くな」って、\n書いてあったのも分かるわね…",
  ui_story_70000202_55_dialog_content = "まるで…命をのみこむ底なし沼…",
  ui_story_70000202_56_dialog_content = "…",
  ui_story_70000202_57_option_content = "（弾痕に触れる）",
  ui_story_70000202_58_option_content = "（薬莢を拾う）",
  ui_story_70000202_59_dialog_content = "く、来るな！",
  ui_story_70000202_60_dialog_content = "グォォ――！",
  ui_story_70000202_61_dialog_content = "た…助けてくれ…",
  ui_story_70000202_62_dialog_content = "いやーっ！",
  ui_story_70000202_63_dialog_content = "お願い、食べないで！\n私なんか、おいしくない！",
  ui_story_70000202_64_dialog_content = "グォォ！！！",
  ui_story_70000202_65_dialog_content = "ああ…お母さん…",
  ui_story_70000202_66_dialog_content = "私は…もう家には帰れない…",
  ui_story_70000202_67_dialog_content = "…",
  ui_story_70000202_68_dialog_content = "PlayerName…戦争の様子が見えたの？",
  ui_story_70000202_69_dialog_content = "うん…",
  ui_story_70000202_70_dialog_content = "私たちには…どうしようもないことよ。\nあなたまで辛くなることはないわ。",
  ui_story_70000202_71_dialog_content = "それより、目的のものを探しましょ？",
  ui_story_70000202_72_dialog_content = "分かった、感知してみる。",
  ui_story_70000202_73_option_content = "感知開始！",
  ui_story_70000202_74_dialog_content = "…！",
  ui_story_70000202_75_dialog_content = "僕たちが探しているものは、\nもっと下にあるみたいだ。",
  ui_story_70000202_76_dialog_content = "干渉がひどくて、\n大体の方向しか感知できないけど…",
  ui_story_70000202_77_dialog_content = "あっちだ！",
  ui_story_70000202_78_dialog_content = "またガケ…",
  ui_story_70000202_79_dialog_content = "さっきより深そうね。\n今度は足場になりそうなものもないわ…",
  ui_story_70000202_80_dialog_content = "このまま飛び降りたら、\n物音もしちゃうだろうし…",
  ui_story_70000202_81_dialog_content = "中にまだ暗鬼がいるなら、\n集まって来るかもしれないわ。",
  ui_story_70000202_82_dialog_content = "でも、感知能力が示す限り、\nここが一番の近道のはずだよ。",
  ui_story_70000202_83_dialog_content = "時間はあとどれぐらいある？",
  ui_story_70000202_84_dialog_content = "余裕はないわ。",
  ui_story_70000202_85_dialog_content = "昼間が他の場所より短くて、6時間しかないから…",
  ui_story_70000202_86_dialog_content = "昼間のうちに帰りたいなら、あと3時間しかないわ。",
  ui_story_70000202_87_dialog_content = "じゃあ、やっぱりここから行って、\n下に降りたら急いで隠れ場所を探そう。",
  ui_story_70000202_88_dialog_content = "…分かったわ、あなたを信じる。",
  ui_story_70000301_1_dialog_content = "今、どの辺りだ？",
  ui_story_70000301_2_dialog_content = "報告しますにゃ…\n測定した限り、まだ80号シェルターの中にいますにゃ。",
  ui_story_70000301_3_dialog_content = "暗力に干渉されてるせいにゃのか、信号も途切れ途切れにゃので…\nもう深部に入ったのではにゃいかと思いますにゃ。",
  ui_story_70000301_4_dialog_content = "順調にいけばいいのですが…",
  ui_story_70000301_5_dialog_content = "焦ることはない。平静を保て。",
  ui_story_70000301_6_dialog_content = "潜入作戦のさなかにいる兵士からは、\n知らせがないことがいい知らせだ。",
  ui_story_70000301_7_dialog_content = "そう判断される根拠が？",
  ui_story_70000301_8_dialog_content = "啓光の者はすべて、私の兵士だ。\n大元帥として、部下の能力は十分に把握している。",
  ui_story_70000301_9_dialog_content = "それに、<color=#FFB400>あの者</color>と行動を共にするようになってから、\nバイスは私の「特別な注目」の対象でもある。",
  ui_story_70000301_10_dialog_content = "それほど心配することはない。\n「手帳」にも、保険を残しておいた。",
  ui_story_70000301_11_dialog_content = "保険、ですか…？",
  ui_story_70000301_12_dialog_content = "1時間半後、まだシェルター内にいるようなら、\n通信機で連絡を取れ。",
  ui_story_70000301_13_dialog_content = "承知しました。",
  ui_story_70000301_14_dialog_content = "…",
  ui_story_70000301_15_dialog_content = "PlayerName、こっちよ。",
  ui_story_70000301_16_dialog_content = "暗鬼が明らかに増えてきてる…",
  ui_story_70000301_17_dialog_content = "それに、歩くだけでも辛くなってきた…",
  ui_story_70000301_18_dialog_content = "もう少しがんばって、PlayerName。",
  ui_story_70000301_19_dialog_content = "もうダメだ、疲れが…",
  ui_story_70000301_20_dialog_content = "ここじゃ危険すぎるわ。\n休むのなら、どこか隠れられる所を探さないと。",
  ui_story_70000301_21_dialog_content = "見て…あと少しで、コアルームの真上よ。",
  ui_story_70000301_22_dialog_content = "どうしても歩けないっていうなら…\n私がかついで行く？",
  ui_story_70000301_23_dialog_content = "いやいや、その必要はないよ…",
  ui_story_70000301_24_dialog_content = "少し息を整えれば、大丈夫だ！",
  ui_story_70000301_25_dialog_content = "その調子よ、無事にソラヴァンに戻ったら、\nおいしい物を作ってあげるわ！",
  ui_story_70000301_26_dialog_content = "…その必要は本当にないよ！",
  ui_story_70000301_27_dialog_content = "まだまだ、僕は疲れてなんかない！行こう！",
  ui_story_70000301_28_dialog_content = "前方に暗鬼がいるわ。数は…\nダメね。暗すぎて影しか見えない…",
  ui_story_70000301_29_dialog_content = "ちょうどコアルームに続く通路の入口が\n塞がれてるのかな…困ったな。",
  ui_story_70000301_30_dialog_content = "回り道は出来る？",
  ui_story_70000301_31_dialog_content = "地図を見てみるわ…",
  ui_story_70000301_32_dialog_content = "地図！？そんなものあった？",
  ui_story_70000301_33_dialog_content = "あら？見てなかった？",
  ui_story_70000301_34_dialog_content = "さっき、あなたが一休みしてる時、\n半分だけの地図があったから、書き写しておいたの。",
  ui_story_70000301_35_dialog_content = "書き写すほどの時間あった？\nまさか、全部覚えて後から書き足した…？",
  ui_story_70000301_36_dialog_content = "製図は私の得意分野だもの。",
  ui_story_70000301_37_dialog_content = "あと、シェルターの構造って一定の規則があるの。\nそれが分かってれば、簡単に覚えられるわ。",
  ui_story_70000301_38_dialog_content = "例えば、避難経路は通常2本以上あって、\n換気口はシェルターの――",
  ui_story_70000301_39_dialog_content = "ストップストップ、とりあえず知りたいのは、\n暗鬼を避けて通れる道がないかどうかだよ。",
  ui_story_70000301_40_dialog_content = "あるわね。\n今通れるかどうかは分からないけど。",
  ui_story_70000301_41_dialog_content = "それに、かなり遠回りになるわ。\n今の私たちじゃ、30分以上は余計にかかりそうね。",
  ui_story_70000301_42_dialog_content = "30分…ただでさえギリギリなのに、\nこれ以上長引いたら…",
  ui_story_70000301_43_dialog_content = "PlayerName、どうする？\nやっぱり遠回りする？",
  ui_story_70000301_44_dialog_content = "それじゃ間に合わなくなりそうだ。",
  ui_story_70000301_45_dialog_content = "回り道はリスクが大きすぎる。\nそれに、時間も足りないし…",
  ui_story_70000301_46_dialog_content = "じゃあ…こうしよう。\n二手に分かれて、それぞれ暗鬼の左右に回り込む。",
  ui_story_70000301_X46_dialog_content = "僕が物音を立てて、注意を引く。\n君はそのスキを狙って奇襲して、素早く片付けて。",
  ui_story_70000301_47_dialog_content = "それでいいわ。",
  ui_story_70000301_48_dialog_content = "PlayerName、気を付けて！",
  ui_story_70000302_1_dialog_content = "今戦った暗鬼、さっきより強くなってなかった？",
  ui_story_70000302_2_dialog_content = "たぶん、暗鬼が強くなったんじゃなくて、\n私たちが弱くなってるんだわ。",
  ui_story_70000302_3_dialog_content = "深部に進むほど、息苦しくなってきてる…",
  ui_story_70000302_4_dialog_content = "ここの暗力の濃度、昼夜で変化するだけじゃなくて、\n深さとも関係しているのかもしれないわ。",
  ui_story_70000302_5_dialog_content = "下に行けば行くほど深くはまる。\nまさに「底なし沼」だね…",
  ui_story_70000302_6_dialog_content = "コアルームの真上に着いたわ。\n周りに暗鬼はいないし、ひとまず安全ね。",
  ui_story_70000302_7_dialog_content = "PlayerName、顔色が悪いわね。\n少し休んだ方がいいわ。",
  ui_story_70000302_8_dialog_content = "まだ一時間半はあるから、\n数分なら休んでも問題ないわ。",
  ui_story_70000302_9_dialog_content = "まだ大丈夫だよ。夜になったら大変だ…",
  ui_story_70000302_10_dialog_content = "手帳にも書いてあったわ。\n暗面で戦うなら、しっかり休憩の時間を取って、体力を温存すべきだって。",
  ui_story_70000302_11_dialog_content = "私の言うことが聞けなくても、\n「先輩」の忠告は聞かなきゃダメよ。",
  ui_story_70000302_12_dialog_content = "分かった…ごめん、バイス。\n僕、足手まといだ…",
  ui_story_70000302_13_dialog_content = "何言ってるの、仲間でしょ。",
  ui_story_70000302_14_dialog_content = "腰かけになりそうな石があったから、\n少し座って休んで。",
  ui_story_70000302_15_dialog_content = "今、僕たちはどの辺り？",
  ui_story_70000302_16_dialog_content = "手帳によれば、ここは昔倉庫だったところね。\nもうだいぶ深い所まで来てるわ。",
  ui_story_70000302_17_dialog_content = "確かに、周りにいろんなものが散乱してるわね。",
  ui_story_70000302_18_dialog_content = "缶詰の箱、空の医療箱、\nばらばらに落ちてる薬莢…",
  ui_story_70000302_19_dialog_content = "それから、汚れた布とトタンを積み上げた、\n穴だらけのバリケード…",
  ui_story_70000302_20_dialog_content = "ここを守っていた兵士は、\nきっと最後の最後まで戦っていたんでしょうね。",
  ui_story_70000302_21_dialog_content = "でも、結局守り切れなかった…",
  ui_story_70000302_22_dialog_content = "…",
  ui_story_70000302_23_dialog_content = "あの戦争で、啓光がたくさん、\n本当にたくさん犠牲者を出したってことしか、私は知らないの…",
  ui_story_70000302_24_dialog_content = "じっくり探す時間があれば、\n認識票を見つけられるかもしれないわ。",
  ui_story_70000302_25_dialog_content = "持って帰ることができれば、残された家族にとって、\n少しは慰めになるかもしれない…",
  ui_story_70000302_26_dialog_content = "バイス…",
  ui_story_70000302_27_dialog_content = "僕も探すのを手伝えば…",
  ui_story_70000302_28_dialog_content = "えっ？",
  ui_story_70000302_29_dialog_content = "これは…？",
  ui_story_70000302_30_dialog_content = "PlayerName、何か見つけたの？",
  ui_story_70000302_31_dialog_content = "埋まってた破片、\nどこか見覚えがある…",
  ui_story_70000302_32_dialog_content = "ホコリを被ってるけど、もとは白い破片みたいだ。\nそれにこの紋様、たぶん…",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>巨像のもの</color>…？",
  ui_story_70000302_34_dialog_content = "えっ？",
  ui_story_70000302_35_dialog_content = "そう言われてみれば、確かに…",
  ui_story_70000302_36_dialog_content = "パッと見は普通のゴミだけど、よく見たら――",
  ui_story_70000302_37_dialog_content = "巨像のモジュールとか？",
  ui_story_70000302_38_dialog_content = "巨像でなかったとしても、\n「天空ノ谷でしか見られないようなもの」だね。",
  ui_story_70000302_39_dialog_content = "ブレーンパーツがこんな所にソラヴァンを修復する方法があるって\n教えてくれたの、間違いじゃなかったわけね。",
  ui_story_70000302_40_dialog_content = "少なくとも、ここに来たのは正解だったわ。",
  ui_story_70000302_41_dialog_content = "もう一度感知で辺りを探ってみるよ…",
  ui_story_70000302_42_option_content = "感知！",
  ui_story_70000302_43_dialog_content = "これは…",
  ui_story_70000302_44_dialog_content = "グォォ――！！！",
  ui_story_70000302_45_dialog_content = "！？",
  ui_story_70000302_46_dialog_content = "PlayerName、大丈夫！？",
  ui_story_70000302_47_dialog_content = "すごく強大な何かを感知した…",
  ui_story_70000302_48_dialog_content = "暗鬼？",
  ui_story_70000302_49_dialog_content = "似てる、でも…断言はできない。",
  ui_story_70000302_50_dialog_content = "そいつの身体から、ものすごい暗力が放出されてるんだ。\nでも、かすかに光力も感じる…",
  ui_story_70000302_51_dialog_content = "似てる…",
  ui_story_70000302_52_dialog_content = "まさか、こんな所にノラが改造した暗鬼がいるの？",
  ui_story_70000302_53_dialog_content = "僕もそこまでは分からないよ。",
  ui_story_70000302_54_dialog_content = "ただ、普通よりはるかに強そうだってことぐらいしか…",
  ui_story_70000302_55_dialog_content = "でも、距離があるから、気づかれないようにこっそり移動して、\n早くモジュールを見つけて帰ろう。",
  ui_story_70000302_56_dialog_content = "こっそり…",
  ui_story_70000302_57_dialog_content = "こっそり…",
  ui_story_70000302_58_dialog_content = "…時間だ。連絡はとれたか？",
  ui_story_70000302_59_dialog_content = "ダメですにゃ、2人の信号は完全に途絶したままにゃ。",
  ui_story_70000302_60_dialog_content = "救援隊を送りますか？",
  ui_story_70000302_61_dialog_content = "…そうだな。救援用の装備で集合させろ。私も出る。",
  ui_story_70000302_62_dialog_content = "大元帥自ら？",
  ui_story_70000302_63_dialog_content = "ちょうど身体がなまっていたところだ。",
  ui_story_70000302_64_dialog_content = "やはり、この試練にはまだ早かったか…？",
  ui_story_70000302_65_dialog_content = "もう少し段階を踏ませた方がよさそうだ。",
  ui_story_70000302_66_dialog_content = "…承知しました。\n救援部隊の隊員は直ちに整列してください！",
  ui_story_70000302_67_dialog_content = "『啓光の軍隊が極夜辺境に集結しております…』",
  ui_story_70000302_68_dialog_content = "『目標も中におります。』",
  ui_story_70000302_69_dialog_content = "『それからほぼ同時に、空の末裔が80号シェルターに進入しました。』",
  ui_story_70000302_70_dialog_content = "80号シェルター…",
  ui_story_70000302_71_dialog_content = "まさか、あの女も<color=#FFB400>「アレ」</color>を探して…？",
  ui_story_70000302_72_dialog_content = "まあ、確かに世界中どこを探したって、\nあそこにしか手がかりは残っていないわね。",
  ui_story_70000302_73_dialog_content = "あなたが何を見つけられるか、\n見物させてもらうわよ――",
  ui_story_70000302_74_dialog_content = "「姉さん」。",
  ui_story_70000401_1_dialog_content = "PlayerName、私の手をつかんで…",
  ui_story_70000401_2_dialog_content = "よいしょ！",
  ui_story_70000401_3_dialog_content = "ふぅ…やっと…着いた…",
  ui_story_70000401_4_dialog_content = "暗力がとんでもなく濃いわね。\n少し身体を動かしただけでもきついわ…",
  ui_story_70000401_5_dialog_content = "探しているもの、\n本当にこの近くにあるの？",
  ui_story_70000401_6_dialog_content = "うん、感知できる。この近くだよ。",
  ui_story_70000401_7_dialog_content = "たぶん…コアルームの機械のところにある。",
  ui_story_70000401_8_dialog_content = "これじゃないかな？",
  ui_story_70000401_9_dialog_content = "これって…本当に意識モジュール？",
  ui_story_70000401_10_dialog_content = "ソラヴァンのとは全然違うけど…",
  ui_story_70000401_11_dialog_content = "でも、ブレーンパーツが示してたのは、\n間違いなくこれだよ。",
  ui_story_70000401_12_dialog_content = "他にそれらしいものはないし…",
  ui_story_70000401_13_dialog_content = "とにかく、ソラヴァンに持ち帰ろう！",
  ui_story_70000401_14_dialog_content = "分かったわ。\nでも、コアに取り付けられてるわね。",
  ui_story_70000401_15_dialog_content = "取り外せるか、試してみましょ。",
  ui_story_70000401_16_dialog_content = "う～ん…",
  ui_story_70000401_17_dialog_content = "ダメだわ、しっかりはめ込まれてる。",
  ui_story_70000401_18_dialog_content = "PlayerName、手伝って。",
  ui_story_70000401_19_dialog_content = "分かったよ！",
  ui_story_70000401_20_dialog_content = "3つ数えるから、一緒に力いっぱい引っ張って。",
  ui_story_70000401_21_dialog_content = "3――",
  ui_story_70000401_22_dialog_content = "2――",
  ui_story_70000401_23_dialog_content = "1！",
  ui_story_70000401_24_dialog_content = "力いっぱい引く！",
  ui_story_70000401_25_dialog_content = "うわっ――！",
  ui_story_70000401_26_dialog_content = "頭をぶつけた…モジュールは無事？",
  ui_story_70000401_27_dialog_content = "特に問題はなさそうよ。急ぎましょう！",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_70000401_29_dialog_content = "地震！？",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_70000401_31_dialog_content = "シェルターのエネルギー供給が…止まった！？",
  ui_story_70000401_32_dialog_content = "私たちがモジュールを外したせい？",
  ui_story_70000401_33_dialog_content = "分からないよ。\nでも、感知できる、何かが…",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>ドカン！！！</color>",
  ui_story_70000401_36_dialog_content = "どんどん近づいてきてる！！",
  ui_story_70000401_37_dialog_content = "崩れるわ！",
  ui_story_70000401_37X1_dialog_content = "PlayerName、その壁から離れて！",
  ui_story_70000401_37X2_dialog_content = "ゴホッ、ゴホゴホ！",
  ui_story_70000401_37X3_dialog_content = "すごいホコリだ！",
  ui_story_70000401_37X4_dialog_content = "…",
  ui_story_70000401_37X5_dialog_content = "崩れた壁の向こう側に、空間が…？",
  ui_story_70000401_37X6_dialog_content = "あれは…",
  ui_story_70000401_37X7_dialog_content = "…",
  ui_story_70000401_37X8_dialog_content = "とてつもない暗力よ…！",
  ui_story_70000401_37X9_dialog_content = "まさか、あなたが感知したっていう…",
  ui_story_70000401_37X10_dialog_content = "…！",
  ui_story_70000401_37X11_dialog_content = "確かに暗鬼…しかも、今まで会ったことのないタイプだ！？",
  ui_story_70000401_37X12_dialog_content = "何の反応もないようだけど、眠ってるの？",
  ui_story_70000401_37X13_dialog_content = "とにかく、驚かせないようにしよう。\n気付かれないように離れて、出口を見つけないと…",
  ui_story_70000401_37X14_dialog_content = "でも、出口を開くのに壁を叩く必要があるでしょ。\nそれで目を覚ますんじゃ…",
  ui_story_70000401_37X15_dialog_content = "その時は君が先に――",
  ui_story_70000401_37X16_dialog_content = "…光…",
  ui_story_70000401_37X17_dialog_content = "寝言…？",
  ui_story_70000401_37X18_dialog_content = "遠くてよく聞こえないわ。",
  ui_story_70000401_37X19_dialog_content = "言葉を話す暗鬼も結構いるけど…",
  ui_story_70000401_37X20_dialog_content = "今は構ってられないよ。\n何とかしてここを離れないと！",
  ui_story_70000401_37X21_dialog_content = "ええ、そうね…",
  ui_story_70000401_37X22_dialog_content = "…啓…光！！！",
  ui_story_70000401_37X23_dialog_content = "待って、聞こえた？今――",
  ui_story_70000401_37X24_dialog_content = "グォォ――！！！",
  ui_story_70000401_37X25_dialog_content = "大変、目を覚ましたわ！",
  ui_story_70000401_37X26_dialog_content = "見つかった！早く逃げよう！",
  ui_story_70000401_38_dialog_content = "PlayerName、危ない！",
  ui_story_70000401_39_dialog_content = "バイス！大丈夫！？",
  ui_story_70000401_39X1_dialog_content = "暗力が濃すぎる、戦えないわ。\n何とかスキを見て、逃げましょう！",
  ui_story_70000401_40_dialog_content = "分かった、あいつを足止めして！\n僕が出口を探す！",
  ui_story_70000401_41_dialog_content = "ううっ…",
  ui_story_70000401_42_dialog_content = "急いで！そう長く持たないわ、\n早く隠し扉を見つけて！",
  ui_story_70000402_1_dialog_content = "軽く3回――",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_70000402_3_dialog_content = "強く3回――",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>ドン！ドン！ドン！</color>",
  ui_story_70000402_5_dialog_content = "軽く3回――",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_70000402_7_dialog_content = "…",
  ui_story_70000402_8_dialog_content = "何も起こらない…！？",
  ui_story_70000402_9_dialog_content = "早く開いて！！",
  ui_story_70000402_10_dialog_content = "PlayerName、まだなの！？",
  ui_story_70000402_11_dialog_content = "ダメだ！全く反応がない！",
  ui_story_70000402_12_dialog_content = "グォォ――！",
  ui_story_70000402_13_dialog_content = "うっ――！？",
  ui_story_70000402_14_dialog_content = "これ以上足止めできないわ！\nひとまず下に逃げましょう！",
  ui_story_70000402_15_dialog_content = "でも、下に逃げたら逃げ道がなくなるよ！？",
  ui_story_70000402_16_dialog_content = "他にどうしようもないわ！",
  ui_story_70000402_17_dialog_content = "上層部に通じる道は、あの暗鬼にふさがれてる。\n突破は無理よ！",
  ui_story_70000402_18_dialog_content = "下に逃げれば、まだ何かチャンスがあるかも！",
  ui_story_70000402_19_dialog_content = "…仕方ない…！",
  ui_story_70000402_20_dialog_content = "モタモタしてられないわ！\n急ぎましょう！",
  ui_story_70000402_21_dialog_content = "グォォ！！！",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_70000402_23_dialog_content = "ほ、報告！",
  ui_story_70000402_24_dialog_content = "80号シェルター跡の方角より、\n強い揺れを確認！",
  ui_story_70000402_25_dialog_content = "落ち着け、焦る必要はない。",
  ui_story_70000402_26_dialog_content = "防御陣形を維持し、\n引き続き80号シェルターへ前進せよ。",
  ui_story_70000402_27_dialog_content = "了解！",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>グオオ――！</color>",
  ui_story_70000402_29_dialog_content = "何の音だ！？",
  ui_story_70000402_30_dialog_content = "これは…",
  ui_story_70000402_31_dialog_content = "…！",
  ui_story_70000402_32_dialog_content = "この気配…",
  ui_story_70000402_33_dialog_content = "そんなはずはない。なぜだ…",
  ui_story_70000402_34_dialog_content = "大元帥、ご気分でも！？",
  ui_story_70000402_35_dialog_content = "…",
  ui_story_70000402_36_dialog_content = "…このまま兵士を行かせてはならない…",
  ui_story_70000402_37_dialog_content = "無駄死にになる…",
  ui_story_70000402_38_dialog_content = "…命令だ。総員、直ちに警戒線に撤退せよ。",
  ui_story_70000402_39_dialog_content = "何があろうとも、\n「暗面」へ進入してはならない。",
  ui_story_70000402_40_dialog_content = "は、はい！\nしかし…大元帥…",
  ui_story_70000402_41_dialog_content = "心配は要らん。\n私が直々に処理せねばならん問題があるだけのことだ。",
  ui_story_70000402_42_dialog_content = "それから、ビビアンに伝えろ――",
  ui_story_70000402_43_dialog_content = "私が戻るまで、「あいつら」の対応を任せたと。",
  ui_story_70000402_44_dialog_content = "了解！",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>グオオ――！</color>",
  ui_story_70000402_46_dialog_content = "…",
  ui_story_70000402_47_dialog_content = "やっぱり、ここに「手がかり」があったのね。",
  ui_story_70000402_48_dialog_content = "「接触すれば、必ず痕跡が残る」",
  ui_story_70000402_49_dialog_content = "…このパズルのピース、私が頂いておくわ。",
  ui_story_70000402_50_dialog_content = "ノラ――",
  ui_story_70000402_51_dialog_content = "約束を忘れるな。",
  ui_story_70000402_52_dialog_content = "はぁ…",
  ui_story_70000402_53_dialog_content = "分かってるわ。",
  ui_story_70000402_54_dialog_content = "あなたのやることは、\n私の合図で虫ケラどもを追い出すことだけよ。",
  ui_story_70000402_55_dialog_content = "迷いがあるようだな。\nそれでは必ず失敗するぞ。",
  ui_story_70000402_56_dialog_content = "青二才めが。",
  ui_story_70000402_57_dialog_content = "…愚かね。",
  ui_story_70000501_1_dialog_content = "わずかに光力術の痕跡が暗力に飲み込まれず、\n残っている…最近のものか。",
  ui_story_70000501_2_dialog_content = "暗鬼の痕跡は…10匹程度か。\n戦闘は多くない。",
  ui_story_70000501_3_dialog_content = "奇襲で、できるだけ戦闘を避けたようだな。",
  ui_story_70000501_4_dialog_content = "悪くない戦術だ。\n地形も十分に活かしている…",
  ui_story_70000501_5_dialog_content = "少しずつ、指揮官らしくなってきたようだな。",
  ui_story_70000501_6_dialog_content = "だが、このような場所で、あとどれほど持つか…",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>ゴゴゴゴゴ――</color>",
  ui_story_70000501_8_dialog_content = "やはり閉じ込められたか？",
  ui_story_70000501_9_dialog_content = "あれほど懇切丁寧に「指南」してやったというのに、\nこのようなつまらないミスを犯すとはな。",
  ui_story_70000501_10_dialog_content = "帰ったら、しっかり頭に叩き込んでやらねばなるまい。",
  ui_story_70000501_11_dialog_content = "バイス、右後ろに避けて！",
  ui_story_70000501_12_dialog_content = "分かったわ！",
  ui_story_70000501_13_dialog_content = "食らいなさい！",
  ui_story_70000501_14_dialog_content = "グォォ――！",
  ui_story_70000501_15_dialog_content = "ダメだ、まったく効いてない！",
  ui_story_70000501_16_dialog_content = "暗力が強すぎるわ！",
  ui_story_70000501_17_dialog_content = "抑えられないか試してみるよ！",
  ui_story_70000501_18_option_content = "強制感知――！",
  ui_story_70000501_19_dialog_content = "啓…",
  ui_story_70000501_20_dialog_content = "啓…？",
  ui_story_70000501_21_dialog_content = "…何だろう？",
  ui_story_70000501_22_dialog_content = "啓…光…",
  ui_story_70000501_23_dialog_content = "啓光…？啓光連邦のこと！？",
  ui_story_70000501_24_dialog_content = "啓光…！！！",
  ui_story_70000501_25_dialog_content = "うっ！すごい恨みの念だ！",
  ui_story_70000501_26_dialog_content = "PlayerName！？",
  ui_story_70000501_27_dialog_content = "大丈夫だよ！",
  ui_story_70000501_28_dialog_content = "あの暗鬼、妙だ…\n啓光連邦をものすごく強く恨んでる。",
  ui_story_70000501_29_dialog_content = "啓光…グォオオ！！",
  ui_story_70000501_30_dialog_content = "まさか、私が着てる啓光の制服に反応してる？",
  ui_story_70000501_31_dialog_content = "PlayerName、私が引き付けるわ！\nあなたはスキを見て、外へ逃げて！",
  ui_story_70000501_32_dialog_content = "君はどうするの！？",
  ui_story_70000501_33_dialog_content = "私のことは構わないで！\n自分の身が最優先よ！",
  ui_story_70000501_34_dialog_content = "啓光…！！！",
  ui_story_70000501_35_dialog_content = "うっ――！？",
  ui_story_70000501_36_dialog_content = "バイス！",
  ui_story_70000501_37_dialog_content = "何とかしてバイスを助けないと…！",
  ui_story_70000501_38_dialog_content = "大きいだけのでくのぼうめ、\n僕はこっちだ！！",
  ui_story_70000501_39_dialog_content = "グォォ！！！",
  ui_story_70000501_40_dialog_content = "PlayerName…早く…逃げて…",
  ui_story_70000501_41_dialog_content = "僕を捕まえてみろ――！",
  ui_story_70000501_42_dialog_content = "グォォ！！！",
  ui_story_70000501_43_dialog_content = "速い！？",
  ui_story_70000501_44_dialog_content = "うっ――！",
  ui_story_70000501_45_dialog_content = "PlayerName！？",
  ui_story_70000501_46_dialog_content = "ここで…死ぬのかな…？",
  ui_story_70000501_47_dialog_content = "誰でもいい…僕たちを…助けて…",
  ui_story_70000501_48_dialog_content = "グォオオ――",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>カキン――！</color>",
  ui_story_70000501_50_dialog_content = "指揮官は、常に戦局を見極めなければならない…",
  ui_story_70000501_51_dialog_content = "この声は…！？",
  ui_story_70000501_52_dialog_content = "大元帥さん！？",
  ui_story_70000501_53_dialog_content = "空の末裔、お前には指揮官として素質がある。\nだが、まだまだ鍛え方が足りないようだな。",
  ui_story_70000501_54_dialog_content = "帰ったら、バートンとグラムにでも叩き直してもらうことだ。",
  ui_story_70000501_55_dialog_content = "えっ！？",
  ui_story_70000501_56_dialog_content = "啓光…啓光――！！",
  ui_story_70000501_57_dialog_content = "――！！！",
  ui_story_70000501_58_dialog_content = "レインハト…大元帥…！",
  ui_story_70000501_59_dialog_content = "まだ動けるのなら、どこか隠れる所を探せ。",
  ui_story_70000501_60_dialog_content = "バイス、こっちだ！",
  ui_story_70000501_61_dialog_content = "グォォ――！！！",
  ui_story_70000501_62_dialog_content = "まさか、本当にお前だったとはな。",
  ui_story_70000501_63_dialog_content = "見た目はもう半分暗鬼だが、\n戦い方のクセは少しも変わっていない。",
  ui_story_70000501_64_dialog_content = "レインハトさん…あの暗鬼と話をしてる？",
  ui_story_70000501_65_dialog_content = "まさか、忘れたというのか？",
  ui_story_70000501_66_dialog_content = "「戦友よ」。",
  ui_story_70000501_67_dialog_content = "「戦友」…？",
  ui_story_70000501_68_dialog_content = "グォォ！",
  ui_story_70000501_69_dialog_content = "まずい、こんな暗力じゃ、\n誰が戦っても不利だ！",
  ui_story_70000501_70_dialog_content = "あの暗鬼に干渉できないか、\n試してみよう…",
  ui_story_70000501_71_dialog_content = "感知――！",
  ui_story_70000501_72_dialog_content = "グォオオ――",
  ui_story_70000501_73_dialog_content = "うわああ！",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_70000501_75_dialog_content = "コイツ…自分の命が惜しくないの！？",
  ui_story_70000501_76_dialog_content = "シェルターが崩れちゃうよ！？",
  ui_story_70000501_77_dialog_content = "PlayerName、止めろ！",
  ui_story_70000501_78_dialog_content = "慌てることはない。",
  ui_story_70000501_78X1_dialog_content = "――！！！",
  ui_story_70000501_78X2_dialog_content = "避けて！！",
  ui_story_70000501_78X3_dialog_content = "大元帥！",
  ui_story_70000501_78X4_dialog_content = "心配は無用だ。何ともない。",
  ui_story_70000501_78X5_dialog_content = "ただ、一つだけ…試してみたいことがあってな。",
  ui_story_70000501_79_dialog_content = "でも…",
  ui_story_70000501_80_dialog_content = "PlayerName…とりあえず、大元帥を信じましょう…",
  ui_story_70000501_81_dialog_content = "どうして反撃しないんだろう…？",
  ui_story_70000501_82_dialog_content = "…覚えているか？",
  ui_story_70000501_83_dialog_content = "私たちはかつて共に戦い、\n数えきれないほどの敵を倒した。",
  ui_story_70000501_84_dialog_content = "…",
  ui_story_70000501_85_dialog_content = "いくつもの塹壕を掘り、いくつもの襲撃を阻止した。\n私たちの故郷、カナン城を守るために。",
  ui_story_70000501_86_dialog_content = "カ…ナ…ン…城…",
  ui_story_70000501_87_dialog_content = "そう、カナン城だ。\n私たちはかつてカナン城の前で、自らの名のもとに誓った。",
  ui_story_70000501_88_dialog_content = "自分の名は覚えているか？",
  ui_story_70000501_89_dialog_content = "グォォ…",
  ui_story_70000501_90_dialog_content = "――<color=#FFB400>ヘリオス</color>。",
  ui_story_70000501_91_dialog_content = "啓…光…",
  ui_story_70000501_92_dialog_content = "啓光…！！！",
  ui_story_70000501_93_dialog_content = "グォォ――！",
  ui_story_70000501_94_dialog_content = "フン、やはりダメか…？",
  ui_story_70000501_95_dialog_content = "大元帥、危険です！",
  ui_story_70000501_96_dialog_content = "辺りはもうボロボロです！\nこれ以上の衝撃には耐えられません！",
  ui_story_70000501_97_dialog_content = "このまま戦っていたら、\nシェルターごと崩壊してしまいます！",
  ui_story_70000501_98_dialog_content = "…グオオ！",
  ui_story_70000501_99_dialog_content = "今の自分の姿を見るがいい…",
  ui_story_70000501_100_dialog_content = "思い出せ、自分が何者かを。",
  ui_story_70000501_101_dialog_content = "私と共に啓光に帰るのだ。\n元の姿に戻る方法も探してやろう…",
  ui_story_70000501_102_dialog_content = "グォォ！！！",
  ui_story_70000501_103_dialog_content = "ゲホ、ゲホっ…！",
  ui_story_70000501_104_dialog_content = "PlayerName、こっちよ！",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000501_106_dialog_content = "――！",
  ui_story_70000501_107_dialog_content = "これは…",
  ui_story_70000501_108_dialog_content = "ベルの音？一体どこから？",
  ui_story_70000501_109_dialog_content = "グォォ――！！！",
  ui_story_70000501_110_dialog_content = "上級暗鬼が…壁をのぼって一目散に逃げだした！？",
  ui_story_70000501_111_dialog_content = "あのベルの音、暗鬼を制御してるのかな？",
  ui_story_70000501_112_dialog_content = "そうではない。",
  ui_story_70000501_113_dialog_content = "あのベルは――<color=#FFB400>「援軍到着、撤退開始」</color>の合図だ。",
  ui_story_70000501_114_dialog_content = "あの暗鬼…知り合いなんですか？",
  ui_story_70000501_115_dialog_content = "知り合い？戦友だ。",
  ui_story_70000501_116_dialog_content = "互いに命を預けていた。",
  ui_story_70000501_117_dialog_content = "「暗面戦争」で行方知れずになっていたのだ。\nまさに、このシェルターでな。",
  ui_story_70000501_118_dialog_content = "死んだものと思っていたが、まさか…",
  ui_story_70000501_119_dialog_content = "まだ生きていたとはな。しかも、暗鬼として。",
  ui_story_70000501_120_dialog_content = "「暗鬼として」？それってつまり…",
  ui_story_70000501_121_dialog_content = "私もまだ整理しきれていない。",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>ドカン！</color>",
  ui_story_70000501_123_dialog_content = "…このシェルターもいよいよ終わりのようだな。",
  ui_story_70000501_124_dialog_content = "まずはここを離れるぞ。話は後だ。",
  ui_story_70000501_125_dialog_content = "はい…",
  ui_story_70000501_126_dialog_content = "出口は分かっている。ついてこい。",
  ui_story_70000601_1_dialog_content = "私にはかつて2人の親友がいた。\nその1人が先ほどの…そう<color=#FFB400>ヘリオス</color>だ。",
  ui_story_70000601_1X1_dialog_content = "もう1人は、お前たちも知っている。\n当時はまだ<color=#FFB400>デニール</color>といった。",
  ui_story_70000601_1X2_dialog_content = "ノラ…！？",
  ui_story_70000601_1X3_dialog_content = "そう、それが今の名だ。",
  ui_story_70000601_2_dialog_content = "我々3人は同じ啓光の孤児院で育ち、軍に入って、共に戦った。",
  ui_story_70000601_3_dialog_content = "デニール、レインハト、目標は決まったか？",
  ui_story_70000601_4_dialog_content = "教官に素質があるって言われたんだ。\n俺は偵察兵になるよ。",
  ui_story_70000601_5_dialog_content = "私はあなたたちと違って、実験室が戦場なの。",
  ui_story_70000601_6_dialog_content = "熱血バカの役は、\n私よりずっとふさわしい人がいるでしょ。",
  ui_story_70000601_7_dialog_content = "相変わらず皮肉だな。",
  ui_story_70000601_8_dialog_content = "レインハト、そういうお前は？",
  ui_story_70000601_9_dialog_content = "私か？",
  ui_story_70000601_10_dialog_content = "まだ決まっていない。\nだが、当面の小さな目標ぐらいは決めておかないとな――",
  ui_story_70000601_11_dialog_content = "ひとまず、啓光の大元帥でも目指すとしよう。",
  ui_story_70000601_12_dialog_content = "それからすぐ、私たちの功績が\n啓光の指導者たちに注目されるようになった。",
  ui_story_70000601_13_dialog_content = "そして3人ともに、次の大元帥の候補となったのだ。",
  ui_story_70000601_14_dialog_content = "お前たちは啓光で最も優秀な兵士であり、\n啓光の未来の担い手だ。",
  ui_story_70000601_15_dialog_content = "この先お前たちには、\n啓光で最も過酷な訓練が待っている。",
  ui_story_70000601_16_dialog_content = "毎日、やがては1時間ごとに、誰かが淘汰される。",
  ui_story_70000601_17_dialog_content = "しかし、そこで勝ち残った者が\n最強の存在として…",
  ui_story_70000601_18_dialog_content = "啓光の大元帥となるのだ！",
  ui_story_70000601_19_dialog_content = "自信はあるか！？",
  ui_story_70000601_20_dialog_content = "あります。",
  ui_story_70000601_21_dialog_content = "有ります。",
  ui_story_70000601_22_dialog_content = "有ります！",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>委員会</color>って何ですか？",
  ui_story_70000601_24_dialog_content = "あら？PlayerNameは聞いたことなかった？",
  ui_story_70000601_25_dialog_content = "まったくないよ！",
  ui_story_70000601_26_dialog_content = "レインハト大元帥と共同で啓光のいろんなことを管理してる人たちよ。",
  ui_story_70000601_27_dialog_content = "でも、啓光の人っていつでも「大元帥が」ばっかりで…",
  ui_story_70000601_28_dialog_content = "「委員会が」なんて誰も言わないじゃない？",
  ui_story_70000601_29_dialog_content = "オッホン…",
  ui_story_70000601_30_dialog_content = "（あ、ツッコミに気を取られて、\n本人がいることを忘れてた…）",
  ui_story_70000601_31_dialog_content = "正式名称は、<color=#FFB400>「啓光連邦軍事および政務委員会」</color>と言う。",
  ui_story_70000601_32_dialog_content = "骨董品も同然の頭が固い奴らの集まりの上に、\n啓光のあらゆる事に自分で目を通さねば気がすまない性質と来ている。",
  ui_story_70000601_33_dialog_content = "幸い、普段は大人しくしている。\n外部の者が知らなくとも当然のことだ。",
  ui_story_70000601_34_dialog_content = "（よかった、怒られなかったうえに解説までしてくれた…）",
  ui_story_70000601_35_dialog_content = "え？待ってください。\nって、ことは――",
  ui_story_70000601_36_dialog_content = "啓光の大元帥は、\nその委員会が決めてるってことですか？",
  ui_story_70000601_37_dialog_content = "えっ？",
  ui_story_70000601_38_dialog_content = "大元帥って…軍功の最も高い人がなるのでは？",
  ui_story_70000601_39_dialog_content = "少なくとも、私が学校で読んだ本には、そう書いてあったはず…",
  ui_story_70000601_40_dialog_content = "軍功は選考条件の一つにすぎない。",
  ui_story_70000601_41_dialog_content = "人の心をまとめることは難しい。",
  ui_story_70000601_41X_dialog_content = "啓光連邦は多くのシェルターから成り立っている。\n「軍功」だけでは従わない者もいる。",
  ui_story_70000601_42_dialog_content = "もし、軍功ばかりあって、\n統率能力のない者が大元帥になり…",
  ui_story_70000601_43_dialog_content = "むやみに戦争ばかり起こすようなら、どうする？",
  ui_story_70000601_44_dialog_content = "その者の言う通り、啓光のすべての資源をつぎこんで、\n城壁と大砲を造るか？",
  ui_story_70000601_44X_dialog_content = "そして、全員で衣食住もままならぬ生活を送るのか？",
  ui_story_70000601_45_dialog_content = "それは…",
  ui_story_70000601_46_dialog_content = "着いたぞ。",
  ui_story_70000601_47_dialog_content = "ここは…あたり一面、廃墟ですよ？",
  ui_story_70000601_48_dialog_content = "慌てるな。入口は…",
  ui_story_70000601_49_dialog_content = "秘密の通路でもあるんですか？",
  ui_story_70000601_50_dialog_content = "正確には、避難通路だ。",
  ui_story_70000601_51_dialog_content = "このシェルターの避難通路には、特殊な加工が施されているのだ。\n地震が頻発する地域であることを考慮していたのだろうな。",
  ui_story_70000601_52_dialog_content = "私も昔、そこから包囲を突破した。",
  ui_story_70000601_53_dialog_content = "入れ。",
  ui_story_70000601_54_dialog_content = "静かですね…",
  ui_story_70000601_55_dialog_content = "バイス、手を貸すよ。",
  ui_story_70000601_56_dialog_content = "ありがとう、PlayerName。",
  ui_story_70000601_57_dialog_content = "私は大丈夫よ。",
  ui_story_70000601_58_dialog_content = "さっきあれだけ強い攻撃を受けてたんだ。\n体力は温存しておかないと。",
  ui_story_70000601_59_dialog_content = "その通り…能力が優れているからといって、\nムリをしていいわけではない。",
  ui_story_70000601_60_dialog_content = "時間が迫った時点でおとなしく、\n手帳の指示通りに地上へ戻っていれば…",
  ui_story_70000601_60X_dialog_content = "面倒なことにはならなかったはずだ。",
  ui_story_70000601_61_dialog_content = "て、手帳のことをご存じなんですか？\nまさか…",
  ui_story_70000601_62_dialog_content = "手帳なら、当然私が書いたものだ。\nお前たちがフィリスに頼んで80号シェルターを調べたことも知っている。",
  ui_story_70000601_63_dialog_content = "！！！",
  ui_story_70000601_64_dialog_content = "なんだ、その目は？",
  ui_story_70000601_65_dialog_content = "啓光連邦で唯一暗面での戦闘を経験し、\n生きて帰ってきた者が、私だ。",
  ui_story_70000601_66_dialog_content = "この80号シェルターこそ、私たちの戦場だった。",
  ui_story_70000601_67_dialog_content = "調査しようという者が出て、\n私が知らずにいると思うか？",
  ui_story_70000601_68_dialog_content = "しかし、なぜここへ…？",
  ui_story_70000601_69_dialog_content = "カナン城にいらっしゃるものとばかり…",
  ui_story_70000601_70_dialog_content = "お前たちの能力を信用して、\nこの区域の探索を黙認した。",
  ui_story_70000601_71_dialog_content = "しかし、予想外の状況が起こる可能性は大いにある。\nお前たちを放っておくという意味ではない。",
  ui_story_70000601_72_dialog_content = "大元帥の責務は、啓光のすべての者を守ること…",
  ui_story_70000601_73_dialog_content = "啓光の盟友たるPlayerNameも含めてな。",
  ui_story_70000601_74_dialog_content = "あ、は、はい…",
  ui_story_70000601_75_dialog_content = "お前たちが80号シェルターを\n調べようとしていると知った時から…",
  ui_story_70000601_75X_dialog_content = "私は兵を率いて、\n暗面境界線上の警戒線で待機していた。",
  ui_story_70000601_76_dialog_content = "お前たちの実力を測るにもいいかと考えてな。",
  ui_story_70000601_77_dialog_content = "無事に戻れば、何事もなかったふりをして、\n追及はしないつもりだったが…",
  ui_story_70000601_78_dialog_content = "ずいぶん危うかったようだな。",
  ui_story_70000601_79_dialog_content = "はい…いちおう計画は順調に進んでたんですが、\n地下にあんなに強い敵がいると思わなくて…",
  ui_story_70000601_79X_dialog_content = "もし私がヘリオスの存在に気付いて救援に駆け付けていなかったら、\n大変なことになっていたところだ。",
  ui_story_70000601_80_dialog_content = "情報は信用してもいいが、\n妄信してはいけない…",
  ui_story_70000601_81_dialog_content = "指揮官として、しかと胸に刻んでおけ。",
  ui_story_70000601_82_dialog_content = "はい…",
  ui_story_70000601_83_dialog_content = "お前たちの帰還が遅れているようだったから、\n面倒ごとに巻き込まれたのだろうと判断した。",
  ui_story_70000601_84_dialog_content = "暗鬼だろうとは思っていたが、\nまさか、ヘリオスだったとはな…",
  ui_story_70000601_85_dialog_content = "運命はずいぶんと趣味が悪いようだ。",
  ui_story_70000601_86_dialog_content = "…",
  ui_story_70000601_87_dialog_content = "まあいい。この話はここまでだ。",
  ui_story_70000601_88_dialog_content = "この扉を開ければ、避難用の通路だ。",
  ui_story_70000601_89_dialog_content = "上に行けば、地上に着く。",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>ギィ…</color>",
  ui_story_70000601_91_dialog_content = "地震の影響は受けてないみたいですね…",
  ui_story_70000601_92_dialog_content = "それに、かすかに風を感じられる…",
  ui_story_70000601_93_dialog_content = "…ってことは、外につながってるってことだね！",
  ui_story_70000601_94_dialog_content = "声をあげるな。この通路では響く。",
  ui_story_70000601_95_dialog_content = "暗鬼が潜伏していないとも限らん。",
  ui_story_70000601_96_dialog_content = "グォォ――！",
  ui_story_70000601_97_dialog_content = "噂をすればなんとやら、ですね…",
  ui_story_70000601_98_dialog_content = "ごめんなさい！",
  ui_story_70000601_99_dialog_content = "空の末裔、戦いに備えろ。\nお前の指揮能力、とくと見せてもらおう！",
  ui_story_70000602_1_dialog_content = "どうして…",
  ui_story_70000602_2_dialog_content = "上に向かってるはずなのに、\n暗力の圧迫感が強くなってるわ…",
  ui_story_70000602_3_dialog_content = "確かに…",
  ui_story_70000602_4_dialog_content = "さっきは何匹かなら片付けられたけど、\n今は1匹や2匹でも難しそうだ…",
  ui_story_70000602_5_dialog_content = "「手帳」にはっきりと書いてあることだ。\n記憶力を試してみるか？",
  ui_story_70000602_6_dialog_content = "体力を消耗したから？",
  ui_story_70000602_7_dialog_content = "違う。",
  ui_story_70000602_8_dialog_content = "それも原因の1つだが、\n最も大事なことを忘れている。",
  ui_story_70000602_9_dialog_content = "まさか…時間ですか？",
  ui_story_70000602_10_dialog_content = "その通りだ。",
  ui_story_70000602_11_dialog_content = "夜になったから？",
  ui_story_70000602_12_dialog_content = "記憶力は悪くないか。",
  ui_story_70000602_13_dialog_content = "しっかり手帳を読んでいたようだな。",
  ui_story_70000602_14_dialog_content = "時間に注意せよと再三書いてあっただろう。\nこういった最悪の状況を避けるためだ。",
  ui_story_70000602_15_dialog_content = "まぁ、何度言ったところで、\nどうせ聞きはするまい？",
  ui_story_70000602_16_dialog_content = "何しろ「ソラヴァン」はお前にとって、\n大切な仲間であり、家族だ。",
  ui_story_70000602_17_dialog_content = "何でもお見通しなんですね…",
  ui_story_70000602_18_dialog_content = "お前が分かりやすいだけのことだ。",
  ui_story_70000602_19_dialog_content = "バイスからも報告の度に\nお前の話を聞かされている。",
  ui_story_70000602_20_dialog_content = "それこそ、聞きたくなくても耳に入るのだ。",
  ui_story_70000602_21_dialog_content = "大元帥！？",
  ui_story_70000602_22_dialog_content = "ところで、僕も質問があるんです。",
  ui_story_70000602_23_dialog_content = "どうしてヘリオスだって分かったんですか？",
  ui_story_70000602_24_dialog_content = "戦友同士の絆と言ったものだろう。",
  ui_story_70000602_25_dialog_content = "幼い頃から、私たちは家族のように強く結びついていた。",
  ui_story_70000602_26_dialog_content = "家族に何かあれば、感覚で分かるものだ。\n理屈ではない。",
  ui_story_70000602_27_dialog_content = "このシェルターは閉鎖されて久しい。暗力と物理的な距離によって、\nそうした理屈ではない何かが切り離されたままだったが…",
  ui_story_70000602_28_dialog_content = "お前たちがここを開き、\n深部に長年閉じ込められていたヘリオスを目覚めさせた。",
  ui_story_70000602_29_dialog_content = "断たれた絆が再びつながったとでも言うべきか…？",
  ui_story_70000602_30_dialog_content = "感知能力があるんですか？",
  ui_story_70000602_31_dialog_content = "そんなものが私に有ればよかったが。",
  ui_story_70000602_32_dialog_content = "戦闘指揮にもずいぶん便利だろうな。",
  ui_story_70000602_33_dialog_content = "…あいつがヘリオスだと分かったのは、\n戦友同士の絆、と言ったところか。",
  ui_story_70000602_34_dialog_content = "長らく断たれたままだったが…",
  ui_story_70000602_34X_dialog_content = "お前たちの行動で、意図せず絆が再びつなぎ合わせられたということだろう。",
  ui_story_70000602_35_dialog_content = "それだけの時間を過ごしてきた――",
  ui_story_70000602_36_dialog_content = "共に、生死を賭けた数々の試練を\n経験してきたのだ。",
  ui_story_70000602_36X1_dialog_content = "私たち3人、共通の記憶としてな。",
  ui_story_70000602_36X2_dialog_content = "3人で…一体何を経験したんですか？",
  ui_story_70000602_36X3_dialog_content = "苦難に満ちた戦闘だ。\n2人にとっては、裏切られた記憶でもあるだろうな。",
  ui_story_70000602_36X4_dialog_content = "私と啓光に裏切られた…啓光に、そして私に見捨てられたのだ。",
  ui_story_70000602_36X5_dialog_content = "見捨てた…？",
  ui_story_70000602_36X6_dialog_content = "僕たちのことはここまでして助けてくれてるのに？\nそんな人には…",
  ui_story_70000602_37_dialog_content = "話すと長くなる。少し整理させてくれ。",
  ui_story_70000602_38_dialog_content = "私のカンだが…おそらく、\nあの時の裏切りがヘリオスを今のような姿にしてしまったのだ。",
  ui_story_70000602_39_dialog_content = "そして、デニールも…いや、その名は捨てられたのだったな――",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>ノラ</color>もそうだった。",
  ui_story_70000602_41_dialog_content = "ノラ…",
  ui_story_70000602_42_dialog_content = "その後、彼女が啓光を裏切ったのは、\n見捨てられたとか、失望したからとかですか？",
  ui_story_70000602_43_dialog_content = "分からん。",
  ui_story_70000602_44_dialog_content = "だからと言って、人体実験を行い、\n啓光の民に危害を加える理由にはならない。",
  ui_story_70000602_45_dialog_content = "救援が来なかったことを\n恨んでいるだろうことは知っている。",
  ui_story_70000602_46_dialog_content = "私の過ちだ。私が弱かったからいけないのだ。\n恨むのなら、私だけを恨み続けなければならない。",
  ui_story_70000602_47_dialog_content = "でも結局、他の人たちにも手を出した…",
  ui_story_70000602_48_dialog_content = "スーモア、僕、それからたくさんの、罪のない人たち…",
  ui_story_70000602_49_dialog_content = "そうだ。それが奴の罪だ。",
  ui_story_70000602_50_dialog_content = "己の身で代償を払わせねばならない。",
  ui_story_70000602_51_dialog_content = "僕もそう思います。\n恨みと犯した罪は別物です。",
  ui_story_70000602_51X1_dialog_content = "だが、つい考えてしまう…",
  ui_story_70000602_51X2_dialog_content = "「委員会」の育成計画に我々が参加していなかったら、\nあの熾烈を極めた戦いの場にいなかったら…",
  ui_story_70000602_51X3_dialog_content = "2人とも暗鬼などに身を落とさず、\n今ごろはよい暮らしを送れていたのではないか、と。",
  ui_story_70000602_52_dialog_content = "一体、どんな訓練だったんですか…？",
  ui_story_70000602_52X1_dialog_content = "どう考えても普通の人じゃ耐えられないものですよね？",
  ui_story_70000602_53_dialog_content = "委員会の育成計画は、\n単なる<color=#FFB400>「訓練」</color>に留まるものではない。",
  ui_story_70000602_54_dialog_content = "3人とも…その「委員会」って言うのが組織した訓練に参加したんですよね？",
  ui_story_70000602_55_dialog_content = "委員会の育成計画は、\n単なる訓練に留まるものではない。",
  ui_story_70000602_56_dialog_content = "時には、命賭けになることもあった。",
  ui_story_70000602_57_dialog_content = "ずいぶんひどい話に聞こえますけど…",
  ui_story_70000602_58_dialog_content = "どうしてもそんな方法で、\n大元帥を選ばなければならないんですか？",
  ui_story_70000602_59_dialog_content = "啓光の者にとって、\n「大元帥」は暗闇を照らす明かりのようなものだ。",
  ui_story_70000602_60_dialog_content = "最も強大な炎だけが、隅々まであまねく光で照らし、\n絶望の中にいるすべての人に希望を与えられる。",
  ui_story_70000602_61_dialog_content = "希望が見えてこそ、啓光の者は心を一つにし、\n苦しみに満ちた世界を前へと進み続けることができるのだ。",
  ui_story_70000602_62_dialog_content = "しかし…そんな者がこの世に現れるのをただ待っているだけでは、\n一生待っても、一人として現れはしないだろう。",
  ui_story_70000602_63_dialog_content = "だから、幾度も苦難を乗り越えなければならないとしても、\n私は啓光の大元帥に…",
  ui_story_70000602_63X_dialog_content = "最強の炎になりたいと考えたのだ。",
  ui_story_70000602_64_dialog_content = "…",
  ui_story_70000602_65_dialog_content = "そのような顔をする必要はない。",
  ui_story_70000602_66_dialog_content = "何と言ったか――",
  ui_story_70000602_67_dialog_content = "「冠を戴くものは、必ずその責任の重さをも\n引き受けなければならない」。",
  ui_story_70000602_68_dialog_content = "安心するがいい。\n天が落ちてきた時は、背の高い誰かが受け止める。",
  ui_story_70000602_69_dialog_content = "同様に、啓光に何かあれば、\n大元帥が助けるというだけだ。",
  ui_story_70000602_70_dialog_content = "お前も含めてな。",
  ui_story_70000602_71_dialog_content = "着いたぞ。",
  ui_story_70000701_1_dialog_content = "シェルターの上層部みたいですね。\n入って来た所と似てます。",
  ui_story_70000701_2_dialog_content = "避難経路をぐるぐる歩いてたから、目が回って…\n方向もよく分からないですけど…",
  ui_story_70000701_3_dialog_content = "PlayerName、私たちが入ってきた場所とは違うわ。",
  ui_story_70000701_4_dialog_content = "むしろ…まったくの逆方向よ。",
  ui_story_70000701_5_dialog_content = "えっ！？",
  ui_story_70000701_6_dialog_content = "難しいことかしら？天井の配管と機能区画から分かるわ。\nダクトの方向も――",
  ui_story_70000701_7_dialog_content = "（バイスがまた僕の分からないことを話し始めた…）",
  ui_story_70000701_8_dialog_content = "あの…僕、1つ質問が！",
  ui_story_70000701_9_dialog_content = "詮索好きは空の末裔の特徴か？",
  ui_story_70000701_10_dialog_content = "ご、ごめんなさい。\n本当にこれで最後にしますから…",
  ui_story_70000701_11_dialog_content = "構わん。好奇心が旺盛なことは、悪いことではない。\n何が知りたい？",
  ui_story_70000701_12_dialog_content = "さっき逃げた、あの上級暗鬼…\n大元帥さんの戦友だったんですよね？",
  ui_story_70000701_13_dialog_content = "それがなんで、あんな風に？",
  ui_story_70000701_14_dialog_content = "まさか、またノラの仕業ですか？\n「シード」の気配は感知できませんでしたけど…",
  ui_story_70000701_15_dialog_content = "「私には分からない」としか答えられない。",
  ui_story_70000701_16_dialog_content = "当時の戦況は凄惨なものだった。\n彼も死んだものとばかり思っていた。",
  ui_story_70000701_17_dialog_content = "一体…何があったんですか？",
  ui_story_70000701_18_dialog_content = "…",
  ui_story_70000701_19_dialog_content = "大元帥の候補として訓練を受けていた私たちは、\nある特殊部隊に所属していた。",
  ui_story_70000701_20_dialog_content = "11年前、私たちは委員会の命令を受けた。すでに放棄されていた\n80号シェルターへ向かい、回収できていなかったある物を取り戻すように、と。",
  ui_story_70000701_21_dialog_content = "80号シェルターは暗力の影響範囲下にはあるものの、\n暗鬼の数は多くないとの情報を得た。",
  ui_story_70000701_22_dialog_content = "そこで私たちは、お前たちと同じ決断をした\n――軽装備で向かったのだ。",
  ui_story_70000701_22X_dialog_content = "短い昼の間にシェルターに入り、\n目的を果たしたらすぐに引き返す。",
  ui_story_70000701_23_dialog_content = "しかし…実際の状況は、情報とは大きく違っていた。",
  ui_story_70000701_24_dialog_content = "ダメだ！暗鬼が多すぎる！",
  ui_story_70000701_25_dialog_content = "応援をお願いします！応援を――",
  ui_story_70000701_26_dialog_content = "中身の詰まった缶詰のように、大量の暗鬼がいた。\nいくら倒しても、次々と湧いて出てきた。",
  ui_story_70000701_27_dialog_content = "目的のものが置いてある倉庫にたどりついた時には、\nすでに2割の人員を失っていた。",
  ui_story_70000701_28_dialog_content = "つまり、私たちが倉庫で見た、あの防御施設や装備の残骸は…",
  ui_story_70000701_29_dialog_content = "すべて、その時勇敢に戦った兵士たちの遺品だ。",
  ui_story_70000701_30_dialog_content = "…",
  ui_story_70000701_31_dialog_content = "そして、私たちが目的の物を手にして、\n撤退しようとした時…",
  ui_story_70000701_32_dialog_content = "日が暮れた。",
  ui_story_70000701_33_dialog_content = "さらに多くの強大な暗鬼が何かに引きつけられるかのように、\n80号シェルターへ波のごとく押しよせた…",
  ui_story_70000701_34_dialog_content = "ちょうど、今のようにな。",
  ui_story_70000701_35_dialog_content = "グォォ――！！！",
  ui_story_70000701_36_dialog_content = "構えろ！",
  ui_story_70000702_1_dialog_content = "グォォ…",
  ui_story_70000702_2_dialog_content = "終わりましたね！",
  ui_story_70000702_3_dialog_content = "辺りに…ひとまず敵はいなくなったようです。",
  ui_story_70000702_4_dialog_content = "バイス！",
  ui_story_70000702_5_dialog_content = "う…体が、重い…",
  ui_story_70000702_6_dialog_content = "今がちょうど零時だ。\n暗力が最も濃くなる。",
  ui_story_70000702_7_dialog_content = "お前たち2人はよく耐えている方だ。\n私たちの時は、多くの者がそのまま気を失ったからな。",
  ui_story_70000702_8_dialog_content = "あの時、私たちが立ち向かったのは、\n今の100倍、1000倍と言う暗鬼だった…",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>「暗面戦争」時代</color>",
  ui_story_70000702_10_dialog_content = "3時の方向に注意しろ！",
  ui_story_70000702_11_dialog_content = "グォォ！！！",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>ダダダダ…！</color>",
  ui_story_70000702_13_dialog_content = "目標消滅！",
  ui_story_70000702_14_dialog_content = "10時の方向に上級暗鬼！",
  ui_story_70000702_15_dialog_content = "数は…1、2…ダメだ、多すぎる！",
  ui_story_70000702_16_dialog_content = "火力支援を頼む！",
  ui_story_70000702_17_dialog_content = "通すものか！",
  ui_story_70000702_18_dialog_content = "グアォオオ――",
  ui_story_70000702_19_dialog_content = "情報と違う！\n暗鬼がこれほど多いとは聞いていないぞ！",
  ui_story_70000702_20_dialog_content = "委員会の情報に誤りが…？",
  ui_story_70000702_21_dialog_content = "こんな状況、出来る限り避けたかったが…もう起こってしまったんだ。\n手に入れた物を持って、何とか逃げるしかない！",
  ui_story_70000702_22_dialog_content = "その後に起こったことは、\nお前も大体予想がつくだろう？",
  ui_story_70000702_23_dialog_content = "シェルター内の暗力によって、通信が遮断されていた。\n私が包囲を突破し、救援を求める役を任された。",
  ui_story_70000702_24_dialog_content = "警戒線までたどりつき、応援要請をした時には、\nシェルターは陥落し、崩壊を始めていた。",
  ui_story_70000702_25_dialog_content = "あのような状況で、暗鬼に包囲されたシェルターに向かい、\n戦いながら崩れたシェルターを掘り進み、人を救うなど…",
  ui_story_70000702_26_dialog_content = "どれだけの代償を払うことになるか、想像には難くない。\n危険を冒したところで、報いはほんのわずか…まったく無いかもしれない。",
  ui_story_70000702_27_dialog_content = "検討の末、啓光は救援を諦めるという決断を下した。",
  ui_story_70000702_28_option_content = "どうして…",
  ui_story_70000702_29_dialog_content = "残された人たちも皆、啓光の兵士なんでしょう？\nすべて同じ命じゃ…",
  ui_story_70000702_30_dialog_content = "諦めるなんて、どうして…",
  ui_story_70000702_31_dialog_content = "…",
  ui_story_70000702_32_dialog_content = "私も長い間、その問いに悩み続けた。\n解せないのは当然だ。",
  ui_story_70000702_33_dialog_content = "あの時シェルターに突入したのは、私の所属していた部隊…\nつまり啓光で最強の装備と攻撃力を持つ部隊だった。",
  ui_story_70000702_34_dialog_content = "精鋭の私たちでさえ、勝利を収められなかった。\n警戒線を見張っているような通常の部隊では無理に決まっている。",
  ui_story_70000702_35_dialog_content = "地下に取り残されたのは皆、私の戦友だ。\n無論、見殺しなどにしたいはずがない。",
  ui_story_70000702_36_dialog_content = "だが、私たちより弱い普通の兵士も、\n同じように私の戦友だ。",
  ui_story_70000702_37_dialog_content = "もし1人を生還させるのに、10人の犠牲が必要だとしたら、\nお前は、その犠牲を払うか？",
  ui_story_70000702_38_dialog_content = "僕は…",
  ui_story_70000702_39_dialog_content = "分かっただろう？\nすべての者に家族や友人、そして大切なものがある。",
  ui_story_70000702_40_dialog_content = "私にとっては、暗面の影響もわずかな負荷に過ぎない。\nしかし、普通の者にとっては、呼吸ができないも同然の危険なのだ。",
  ui_story_70000702_41_dialog_content = "その上、波のごとく襲いかかる暗鬼までいる…",
  ui_story_70000702_42_dialog_content = "そんな環境で「私たち」さえ悲惨な損失を生んだ。\nごく普通の兵士では、望むべくもない。",
  ui_story_70000702_43_option_content = "そうだったんですね…",
  ui_story_70000702_44_dialog_content = "分かればいい。",
  ui_story_70000702_45_option_content = "やっぱり分かりません",
  ui_story_70000702_46_dialog_content = "どんなことがあろうと、\n僕は自分の仲間を見捨てたりしません。",
  ui_story_70000702_47_dialog_content = "絶対に…",
  ui_story_70000702_48_dialog_content = "理解しろとは言わん。\nただ、知っておくがいい――",
  ui_story_70000702_49_dialog_content = "啓光の大元帥として決断を下す時、\n私の胸の内には、啓光のすべての者たちがいる。",
  ui_story_70000702_50_dialog_content = "…",
  ui_story_70000702_51_dialog_content = "（まずいな、話題をそらすだけのつもりが…\nとんでもなく重い話を振っちゃったみたいだ）",
  ui_story_70000702_52_dialog_content = "ええと…その、こ、この道、歩きやすいですね…？",
  ui_story_70000702_53_dialog_content = "当然だ。",
  ui_story_70000702_54_dialog_content = "我々がおびただしい血を流して\n切り拓いた道だからな。",
  ui_story_70000702_55_dialog_content = "そして、私自身も彼らの鮮血を踏みながら、ここを出た。",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000702_57_dialog_content = "PlayerName、聞こえた？",
  ui_story_70000702_58_dialog_content = "また、あのベルの音よ！",
  ui_story_70000702_59_dialog_content = "聞こえたよ！今度は近い！",
  ui_story_70000702_60_dialog_content = "あの上級暗鬼、ベルの音を聞いてすぐに逃げ出したけど…",
  ui_story_70000702_61_dialog_content = "この近くにいるってこと？",
  ui_story_70000702_62_dialog_content = "ううん、暗力がもう少し薄ければ、\n感知能力を使えたんだけど…",
  ui_story_70000702_63_dialog_content = "感知できなくても構わない。\n奴はベルの音がする辺りにいる。",
  ui_story_70000702_64_dialog_content = "大元帥、断言できる理由があるのですか？",
  ui_story_70000702_65_dialog_content = "別れる時に約束したのだ。",
  ui_story_70000702_66_dialog_content = "もし援軍を連れて来られた時は、\n撤退の合図を送ると。",
  ui_story_70000702_67_dialog_content = "撤退のタイミングは…\nいつもの方法で、ベルの音を合図にしよう。",
  ui_story_70000702_68_dialog_content = "ええ、分かったわ。",
  ui_story_70000702_69_dialog_content = "安心しろ、きっと持ちこたえてみせる。",
  ui_story_70000702_70_dialog_content = "暗鬼になってでも、\nベルの音が鳴るまで待ってるさ！",
  ui_story_70000702_71_dialog_content = "よし…",
  ui_story_70000702_72_dialog_content = "ベルの音が鳴ったら、すぐに外へ向かうんだ！",
  ui_story_70000702_73_dialog_content = "…あいつが何気なく言った冗談が、\nまさか現実になるとはな。",
  ui_story_70000702_74_dialog_content = "「口は災いのもと」とはよく言ったものだ。",
  ui_story_70000702_75_dialog_content = "つまり、あの暗鬼は…\nその時の約束をずっと覚えていたんでしょうか？",
  ui_story_70000702_76_dialog_content = "そうかもしれない。もう理性はないだろう。\n約束がもう、本能のように刷り込まれているのかもしれん。",
  ui_story_70000702_77_dialog_content = "…",
  ui_story_70000702_78_dialog_content = "…",
  ui_story_70000702_79_dialog_content = "戦いに備えろ。この先にいるかもしれない。",
  ui_story_70000702_80_dialog_content = "だが、最後にもう一度、試させてくれ…",
  ui_story_70000702_81_dialog_content = "救う機会を、一度見逃してしまったのだ。\n今度は、見逃したくない。",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000801_2_dialog_content = "やっと出られた…！",
  ui_story_70000801_3_dialog_content = "…でも、暗力の圧迫感は、相変わらずだね…",
  ui_story_70000801_4_dialog_content = "PlayerName、無理はしないで。",
  ui_story_70000801_5_dialog_content = "私が支えてあげるわ。",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000801_7_dialog_content = "ベルの音が、近づいてる…",
  ui_story_70000801_8_dialog_content = "あそこだ――",
  ui_story_70000801_9_dialog_content = "グォォ…",
  ui_story_70000801_10_dialog_content = "ベルの音の発生源を探しているみたいですね？",
  ui_story_70000801_11_dialog_content = "でも、周りは暗鬼だらけです…",
  ui_story_70000801_12_dialog_content = "近づきますか？",
  ui_story_70000801_13_dialog_content = "私個人として頼む。5分だけくれ。",
  ui_story_70000801_14_dialog_content = "最後にもう一度試したい…",
  ui_story_70000801_15_dialog_content = "5分経ったら、全員で撤退する。",
  ui_story_70000801_16_dialog_content = "お手伝いします！",
  ui_story_70000801_17_dialog_content = "PlayerNameは？",
  ui_story_70000801_18_dialog_content = "僕も手伝うよ",
  ui_story_70000801_19_dialog_content = "今度こそ、必ず助けよう！",
  ui_story_70000801_20_dialog_content = "ハハハ…ならば、よく見ておくがいい…",
  ui_story_70000801_21_dialog_content = "啓光の意志の証人となるために。",
  ui_story_70000801_22_dialog_content = "それじゃあ、いつも通り二手に分かれよう。",
  ui_story_70000801_23_dialog_content = "バイス、僕たちは回り込む。",
  ui_story_70000801_24_dialog_content = "わかったわ。",
  ui_story_70000801_25_dialog_content = "ここなら大丈夫なはず！",
  ui_story_70000801_26_dialog_content = "よし、大元帥さんの方も準備が出来たみたいだ。",
  ui_story_70000801_27_dialog_content = "それじゃあ…",
  ui_story_70000801_28_dialog_content = "やい、ザコども！\n僕を捕まえてみろ！！",
  ui_story_70000801_29_dialog_content = "グォォ…？",
  ui_story_70000801_30_dialog_content = "グォォ――！！！",
  ui_story_70000801_31_dialog_content = "うっ…",
  ui_story_70000801_32_dialog_content = "さすがにちょっと多すぎないかな…！？",
  ui_story_70000801_33_dialog_content = "PlayerName！持ちこたえて！！",
  ui_story_70000802_1_dialog_content = "お前は忘れたのか？",
  ui_story_70000802_2_dialog_content = "啓光の夢を。",
  ui_story_70000802_3_dialog_content = "啓光の信念を。",
  ui_story_70000802_4_dialog_content = "啓光の栄光を。",
  ui_story_70000802_5_dialog_content = "啓光の記憶を…",
  ui_story_70000802_6_dialog_content = "すべて忘れてしまったというのか！？",
  ui_story_70000802_7_dialog_content = "グォォ！！！",
  ui_story_70000802_8_dialog_content = "教えてくれ…",
  ui_story_70000802_9_dialog_content = "なぜ光に背を向け、闇に身を投じた？",
  ui_story_70000802_10_dialog_content = "生きるためか！？",
  ui_story_70000802_11_dialog_content = "誰かにそそのかされたか！？",
  ui_story_70000802_12_dialog_content = "教えてくれ――",
  ui_story_70000802_13_dialog_content = "<size=45>答えろ！</size>",
  ui_story_70000802_14_dialog_content = "グォォ――！",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000802_16_dialog_content = "…！",
  ui_story_70000802_17_dialog_content = "またベルの音だ！",
  ui_story_70000802_18_dialog_content = "今度はものすごく近い…あそこだ！",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>リリリリリ――</color>",
  ui_story_70000802_20_dialog_content = "あれは――",
  ui_story_70000802_21_dialog_content = "ノラ！？",
  ui_story_70000802_22_dialog_content = "…",
  ui_story_70000802_23_dialog_content = "久しぶりね。ずいぶんおしゃべりになったじゃない――",
  ui_story_70000802_24_dialog_content = "レインハト。",
  ui_story_70000802_25_dialog_content = "デニール…いや、ノラ。",
  ui_story_70000802_26_dialog_content = "ヘリオスは、お前の仕業か？",
  ui_story_70000802_27_dialog_content = "それについては、\n私の知ってることもあなたと同じくらいよ。",
  ui_story_70000802_28_dialog_content = "いい実験材料になりそうだってことは否定しないけどね。",
  ui_story_70000802_29_dialog_content = "ならば、ヘリオスが暗鬼になった原因は…",
  ui_story_70000802_30_dialog_content = "まだわからないの？",
  ui_story_70000802_31_dialog_content = "彼は、何かを忘れたわけじゃない。",
  ui_story_70000802_32_dialog_content = "むしろ…あまりにもはっきりと覚えているのよ。",
  ui_story_70000802_33_dialog_content = "…！？",
  ui_story_70000802_34_dialog_content = "あわれな捨てゴマ。唯一忘れていたのは、啓光への怨みだけ…",
  ui_story_70000802_35_dialog_content = "でも今、思い出す時が来たわ！",
  ui_story_70000802_36_dialog_content = "<size=45>グワアア――！</size>",
  ui_story_70000802_37_dialog_content = "うっ――！？",
  ui_story_70000802_38_dialog_content = "これは、記憶！？",
  ui_story_70000802_39_dialog_content = "レインハトが包囲を破ってから、もう4時間…",
  ui_story_70000802_40_dialog_content = "…「ベルの音」、まだ聞こえないわ。",
  ui_story_70000802_41_dialog_content = "俺にはまだ力が残ってる。たとえ拳だけでも、\n暗鬼に一泡吹かせてやるさ。",
  ui_story_70000802_42_dialog_content = "君は？食糧と弾薬はどれぐらい残ってる？",
  ui_story_70000802_43_dialog_content = "弾が10発と…おがくずパンが2つ。",
  ui_story_70000802_44_dialog_content = "こんなことになるって分かってたら、\nカナン城で面倒くさい実験室の規則に縛られてた方がよっぽどマシだったわ。",
  ui_story_70000802_45_dialog_content = "ライフルより、私はやっぱりメスで暗鬼を解剖する方が得意だわ。",
  ui_story_70000802_46_dialog_content = "ハハハ、さすがは注目のマトになる研究員だね。",
  ui_story_70000802_47_dialog_content = "君ならきっと暗鬼の身体を縫合する時、\nきれいなチョウチョ結びができるんだろうな。",
  ui_story_70000802_48_dialog_content = "フン、ずいぶん余裕ね。",
  ui_story_70000802_49_dialog_content = "私たち、あとどのくらい持つかしら？",
  ui_story_70000802_50_dialog_content = "それとも…もう関係が無いこと？",
  ui_story_70000802_51_dialog_content = "…",
  ui_story_70000802_52_dialog_content = "とにかく、生きる希望を捨てちゃダメだ。",
  ui_story_70000802_53_dialog_content = "レインハトが…きっと援軍を連れて助けに戻って来る。",
  ui_story_70000802_54_dialog_content = "それまで俺たちは、何とかして自分の身を守るんだ。",
  ui_story_70000802_55_dialog_content = "見ろ、出口がこの先にある！",
  ui_story_70000802_56_dialog_content = "周りは暗鬼だらけよ。\nそれに…",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_70000802_58_dialog_content = "さっきの戦闘が激しすぎたのね。\nここ、もう崩れそうよ。",
  ui_story_70000802_59_dialog_content = "夜が明けてる…\n暗鬼の力が一番弱い時だ。",
  ui_story_70000802_60_dialog_content = "今逃げられなかったら、\n俺たちは本当に、ここに閉じ込められて死んでしまう…",
  ui_story_70000802_61_dialog_content = "付いて来てくれ。\n暗鬼が遠くに行ったタイミングを見計らって、包囲を突破しよう。",
  ui_story_70000802_62_dialog_content = "11時の方向！",
  ui_story_70000802_63_dialog_content = "分かった！",
  ui_story_70000802_64_dialog_content = "クソッ…キリがない！",
  ui_story_70000802_65_dialog_content = "俺はまだ耐えられる！\nデニール、出口へ向かうんだ！",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_70000802_67_dialog_content = "足元、気を付けて！",
  ui_story_70000802_68_dialog_content = "うわっ！",
  ui_story_70000802_69_dialog_content = "ヘリオス！！",
  ui_story_70000802_70_dialog_content = "必ず…生き延びる。",
  ui_story_70000802_71_dialog_content = "応援が…来るまで。",
  ui_story_70000802_72_dialog_content = "何日経ったんだろう…",
  ui_story_70000802_73_dialog_content = "身体が…マズイことになってるみたいだ…",
  ui_story_70000802_74_dialog_content = "ベルの音は…まだなのか…",
  ui_story_70000802_75_dialog_content = "1日…2日…",
  ui_story_70000802_76_dialog_content = "1年…2年…",
  ui_story_70000802_77_dialog_content = "なぜ、まだ応援が来ないのだろう…",
  ui_story_70000802_78_dialog_content = "どうして、俺を見捨てたんだ？",
  ui_story_70000802_79_dialog_content = "グォォ――！！！",
  ui_story_70000802_80_dialog_content = "思い出したみたいね。",
  ui_story_70000802_81_dialog_content = "でも、まだ足りないわ。",
  ui_story_70000802_82_dialog_content = "「シード」と同じよ。\n怒りは一番の栄養なの…",
  ui_story_70000802_83_dialog_content = "私がもう少し手助けしてあげる。",
  ui_story_70000802_84_dialog_content = "ノラ、何をするつもり！？",
  ui_story_70000802_85_dialog_content = "…",
  ui_story_70000802_86_dialog_content = "レインハト…",
  ui_story_70000802_87_dialog_content = "どうして…私たちを見捨てたの？",
  ui_story_70000802_88_dialog_content = "それは…",
  ui_story_70000802_89_dialog_content = "あの時の状況では、お前たちを犠牲にすることが\n最良の選択だったからだ。",
  ui_story_70000802_90_dialog_content = "あなた、やっぱり――",
  ui_story_70000802_91_dialog_content = "何も成長してないわね。",
  ui_story_70000802_92_dialog_content = "あなたも啓光も、何も変わってない。",
  ui_story_70000802_93_dialog_content = "グォォ――！！！",
  ui_story_70000802_94_dialog_content = "突進してきます！気を付けて！",
  ui_story_70000802_95_dialog_content = "怒りなさい、そして…成長するのよ。",
  ui_story_70000802_96_dialog_content = "この暗面のすべてを呑み込んでしまいなさい。",
  ui_story_70000802_97_dialog_content = "グォォ――！！！",
  ui_story_70000802_98_dialog_content = "ケリをつける時が来たようだ。",
  ui_story_70000802_99_dialog_content = "バイス、戦闘準備だ！",
  ui_story_70000802_100_dialog_content = "分かったわ！",
  ui_story_70000902_1_dialog_content = "グォ……",
  ui_story_70000902_2_dialog_content = "この状況で、押さえこまれるなんて？",
  ui_story_70000902_3_dialog_content = "やっぱり、ただの<color=#FFB400>「不良品」</color>ね。",
  ui_story_70000902_4_dialog_content = "まあ、まだ動けたってことだけでも、\n予測を超えてたわ。",
  ui_story_70000902_5_dialog_content = "少しは価値があったかしら。",
  ui_story_70000902_6_dialog_content = "でも、私には時間がないの。",
  ui_story_70000902_7_dialog_content = "うっ――！？",
  ui_story_70000902_8_dialog_content = "辺りの暗力が…集まって来てる！",
  ui_story_70000902_9_dialog_content = "暗力が…濃すぎるわ…もうダメ…",
  ui_story_70000902_10_dialog_content = "ただの弱々しい研究員だったはずだが、\nしばらく見ないうちに、ずいぶん強くなったようだな。",
  ui_story_70000902_11_dialog_content = "黙りなさい。",
  ui_story_70000902_12_dialog_content = "弱者は、ひざまずくものよ。",
  ui_story_70000902_13_dialog_content = "あなたは…この暗力を使って、\n最後にまだ残っている価値を見せなさい。",
  ui_story_70000902_14_dialog_content = "グォォ――！！！",
  ui_story_70000902_15_dialog_content = "暗鬼が…消えていく…！？",
  ui_story_70000902_16_dialog_content = "グオォォ――！",
  ui_story_70000902_17_dialog_content = "これは…悲鳴！？",
  ui_story_70000902_18_dialog_content = "ノラが生命力を…暗力を吸い取ってる！",
  ui_story_70000902_19_dialog_content = "これだけの暗力をそのまま攻撃にされたら…",
  ui_story_70000902_20_dialog_content = "ただの爆発だったとしても、\nシェルターが…丸ごと灰になるわ！",
  ui_story_70000902_21_dialog_content = "大元帥さん、気を付けて！",
  ui_story_70000902_22_dialog_content = "…！",
  ui_story_70000902_23_dialog_content = "PlayerName、早く身を隠して！！",
  ui_story_70000902_24_dialog_content = "遅いわ。",
  ui_story_70000902_25_dialog_content = "（今までで一番絶望的な光景だった）",
  ui_story_70000902_26_dialog_content = "（天地を覆うような暗力が極夜の闇さえ巻き込みながら、\n津波のようなうねりをあげて、地上にあるものすべてを押し流していく）",
  ui_story_70000902_27_dialog_content = "（強大な威圧感を前に、僕もバイスも大きな石でも背負っているかのように、\n立っていることさえできなかった）",
  ui_story_70000902_28_dialog_content = "（僕はただ何とか顔を上げて、\n暗力が自分を呑み込んでいくところを見ていた…）",
  ui_story_70000902_29_dialog_content = "そして、漆黒の闇の中――",
  ui_story_70000902_30_dialog_content = "僕は<color=#FFB400>光</color>を見た。",
  ui_story_70000902_31_dialog_content = "思い通りにはさせん…",
  ui_story_70000902_32_dialog_content = "大元帥さん！？",
  ui_story_70000902_33_dialog_content = "（極夜の中では明るいとも言えず、\nいつ飲みこまれるか知れないほど、危うい光）",
  ui_story_70000902_34_dialog_content = "（でも、その光は消えず、\n四方へと輝きを散らし続けていた）",
  ui_story_70000902_35_dialog_content = "（まるで地平線から顔を出そうとしている太陽、\nあるいは夜明けの訪れを示す、白くなり始めた空のように…）",
  ui_story_70000902_36_dialog_content = "暗力ごとき…大したことはない。",
  ui_story_70000902_37_dialog_content = "私の背後には、啓明の光が輝いている！",
  ui_story_70000902_38_dialog_content = "天が崩れようとも、啓光は私が支えて見せる――！",
  ui_story_70000902_39_dialog_content = "（暗闇が、少しずつ消えていく）",
  ui_story_70000902_40_dialog_content = "（そして光が、地平線を貫いた）",
  ui_story_70000902_41_dialog_content = "うっ！！",
  ui_story_70000902_42_dialog_content = "…！",
  ui_story_70000902_43_dialog_content = "大元帥さん！？",
  ui_story_70000902_44_dialog_content = "防御を捨てて、攻撃だけに全てを賭けて…",
  ui_story_70000902_45_dialog_content = "なのに、攻撃がほとんど弾かれるなんて…",
  ui_story_70000902_46_dialog_content = "フフ…あなた、やっぱりおかしいわ。",
  ui_story_70000902_47_dialog_content = "おろかで…狂気的。",
  ui_story_70000902_48_dialog_content = "まぁ、実験予測の範囲内よ。",
  ui_story_70000902_49_dialog_content = "普通の光霊だったら、あれだけ圧倒的な暗力を前にしただけで、\nとっくに気がおかしくなってるでしょうけど…",
  ui_story_70000902_50_dialog_content = "さすがだわ。",
  ui_story_70000902_51_dialog_content = "生きて底なし沼を出た、最も優秀な「化け物」だけある。",
  ui_story_70000902_52_dialog_content = "あいつら、ずいぶん上手にあなたを「育てた」ものね。",
  ui_story_70000902_53_dialog_content = "フン、お互い様だろう。",
  ui_story_70000902_54_dialog_content = "この程度で立ち止まり、英雄ごっこで満足してる。",
  ui_story_70000902_55_dialog_content = "おまけに…ずいぶん、役に入れ込んでるようじゃない？",
  ui_story_70000902_56_dialog_content = "啓光の大元帥になり、\n啓光の人々と共に、よりよい暮らしを目指す。",
  ui_story_70000902_57_dialog_content = "最初から、それが私たち3人の夢だっただろう…",
  ui_story_70000902_58_dialog_content = "「啓光のために、人々のために」ねぇ…",
  ui_story_70000902_59_dialog_content = "実に素晴らしいわ。でも、啓光の人たちは、あなたから奪って、庇護を求めるばかり。\nあなたには、何かしてくれた？",
  ui_story_70000902_60_dialog_content = "アイツらにとって、あなたはただの記号に過ぎないわ。\n用済みになったら捨てられるのよ。",
  ui_story_70000902_61_dialog_content = "そういう意味では、あなたも実験動物と何も変わらない。",
  ui_story_70000902_62_dialog_content = "研究員が気にしているのはいつだって、\n動物たちから得られる実験データだけ。",
  ui_story_70000902_63_dialog_content = "そして、あいつらが気にかけているのは…強大さのイメージだけ。\nその役割を誰が負うかなんて、どうでもいいのよ。",
  ui_story_70000902_64_dialog_content = "フフ…",
  ui_story_70000902_65_dialog_content = "ハハハハ――",
  ui_story_70000902_66_dialog_content = "ノラ、いや、デニール…",
  ui_story_70000902_67_dialog_content = "お前もずいぶんおしゃべりになったようだな。",
  ui_story_70000902_68_dialog_content = "昔は実験室に閉じこもって、\n勉強に明け暮れてばかりだったが。",
  ui_story_70000902_69_dialog_content = "私が何を言っても、お前は――\n自分が一番優秀だと証明して見せる、としか答えなかった。",
  ui_story_70000902_70_dialog_content = "…",
  ui_story_70000902_71_dialog_content = "あの時のお前は、\n他人にどう見られようとまったく意に介さなかった。",
  ui_story_70000902_72_dialog_content = "私もだ。私は啓光の大元帥。\nだから、啓光を守り、啓光の人々を守る。",
  ui_story_70000902_73_dialog_content = "啓光の人々が私のことをどう思おうと、関係ない。",
  ui_story_70000902_74_dialog_content = "その点は、お前に学んだことだ。",
  ui_story_70000902_75_dialog_content = "…",
  ui_story_70000902_76_dialog_content = "あなたに関する研究記録には――\n「狂気」ってタグを足しておくわ。",
  ui_story_70000902_77_dialog_content = "研究材料はもう手に入ったから、\nそろそろ戻って実験を再開するとしましょう。",
  ui_story_70000902_78_dialog_content = "ノ…ラ…",
  ui_story_70000902_79_dialog_content = "虫ケラって、しぶといわよね。",
  ui_story_70000902_80_dialog_content = "失敗作とは違って…",
  ui_story_70000902_81_dialog_content = "…",
  ui_story_70000902_82_dialog_content = "もう限界かしら…",
  ui_story_70000902_83_dialog_content = "だけど、まあ、何とか研究材料にはなりそう。",
  ui_story_70000902_84_dialog_content = "光霊でもなく、暗鬼でもない。",
  ui_story_70000902_85_dialog_content = "もう大した利用価値は残ってなさそうな…半端者だけど。",
  ui_story_70000902_86_dialog_content = "何をする気だ？置いていけ！",
  ui_story_70000902_87_dialog_content = "今のあなたに、私を止められる？",
  ui_story_70000902_88_dialog_content = "「時間よ」",
  ui_story_70000902_89_dialog_content = "地平線の向こうから…震動が伝わってくる。\nそれに砂ボコリが…？",
  ui_story_70000902_90_dialog_content = "PlayerName、あれは…何？",
  ui_story_70000902_91_dialog_content = "分からない、試してみよう…",
  ui_story_70000902_92_option_content = "強制感知！",
  ui_story_70000902_93_dialog_content = "…！",
  ui_story_70000902_94_dialog_content = "（これは…暗鬼！？）",
  ui_story_70000902_95_dialog_content = "（暗鬼の…大軍だ！）",
  ui_story_70000902_96_dialog_content = "『ノラ様を…支援せよ！』",
  ui_story_70000902_97_dialog_content = "（こっちを目指してる！？）",
  ui_story_70000902_98_dialog_content = "（数が多すぎる。大元帥さんがいても…）",
  ui_story_70000902_99_dialog_content = "（いや、彼女だって捨て身の攻撃を仕掛けて、重傷を負ってる…）",
  ui_story_70000902_100_dialog_content = "（鋼の意志で持ちこたえてるだけだ！）",
  ui_story_70000902_101_dialog_content = "（今すぐに撤退しないと！）",
  ui_story_70000902_102_dialog_content = "大元帥さん！大変です！",
  ui_story_70000902_103_dialog_content = "何だ？",
  ui_story_70000902_104_dialog_content = "暗鬼の大軍を感知しました！\nすぐにこっちへ向かってきます！",
  ui_story_70000902_105_dialog_content = "強力そうなやつもいます！",
  ui_story_70000902_106_dialog_content = "早く撤退しないと…！",
  ui_story_70000902_107_dialog_content = "3分だ、3分ですべて終わらせる！",
  ui_story_70000902_108_dialog_content = "グォォ――！！！",
  ui_story_70000902_109_dialog_content = "間に合いませんよ！？",
  ui_story_70000902_110_dialog_content = "このままじゃ…包囲されてしまいます！",
  ui_story_70000902_111_dialog_content = "…",
  ui_story_70000902_112_dialog_content = "「『底なし沼』での作戦行動は、可能な限り戦闘を回避し、\n力の及ぶ範囲内で行動すること」…そうでしょう！？",
  ui_story_70000902_113_dialog_content = "…",
  ui_story_70000902_114_dialog_content = "弱者ね。",
  ui_story_70000902_115_dialog_content = "お前もよく分かっているはずだ。\nヘリオスと私たちは共に戦った戦友だ。",
  ui_story_70000902_116_dialog_content = "もしお前が彼を…啓光の軍人を傷つけるのなら、\nその代償は必ず払ってもらう。",
  ui_story_70000902_117_dialog_content = "フフ…",
  ui_story_70000902_118_dialog_content = "減らず口は、生き残ってから叩きなさい。",
  ui_story_70000902_119_dialog_content = "今のあなたに、選ぶ権利はない。",
  ui_story_70000902_120_dialog_content = "…",
  ui_story_70000902_121_dialog_content = "バイス、PlayerName、撤退だ…",
  ui_story_70000902_122_dialog_content = "…",
  ui_story_70000902_123_dialog_content = "残された時間は少ないわよ――",
  ui_story_70000902_124_dialog_content = "「姉さん」。",
  ui_story_70001001_1_dialog_content = "バイス、大元帥さんを支えて！\n僕は巨像を起動する！",
  ui_story_70001001_2_dialog_content = "分かったわ！",
  ui_story_70001001_3_dialog_content = "…離陸できたか？",
  ui_story_70001001_4_dialog_content = "はい！すでに離陸しています！",
  ui_story_70001001_5_dialog_content = "幸い、暗鬼の大軍に埋もれる前に飛べました…",
  ui_story_70001001_6_dialog_content = "全速力で…帰還しろ…",
  ui_story_70001001_7_dialog_content = "大元帥！？",
  ui_story_70001001_8_dialog_content = "大ケガしてるんだ。\nさっきから今まで、ずっとムリして強がってたんだよ。",
  ui_story_70001001_9_dialog_content = "PlayerName、あなたはソラヴァンを操縦して。\n救急キットを探してくるわ！",
  ui_story_70001001_10_dialog_content = "分かった！",
  ui_story_70001001_11_dialog_content = "大元帥さん、がんばって…",
  ui_story_70001001_12_dialog_content = "うぐ…",
  ui_story_70001001_13_dialog_content = "まずいわ…大元帥、ケガの状態があまり良くないわ。",
  ui_story_70001001_14_dialog_content = "すぐに治療しないと…",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>「キーワードを検知――治療」</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>「データスキャン中…スキャン完了」</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>「スキャン結果：\n意識モジュール修復装置にアップグレード用のデータがあります」</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>「意識モジュール修復装置をインストールすると、\n生命維持システムを医療システムに更新できます」</color>",
  ui_story_70001001_19_option_content = "ソラヴァン？",
  ui_story_70001001_20_dialog_content = "突然起動した！？",
  ui_story_70001001_21_dialog_content = "意識モジュール修復装置って…これのことかな？\nそうだ、どうして忘れてたんだろう？",
  ui_story_70001001_22_dialog_content = "医療システムって言うからには、\n大元帥さんを助けられるかもしれない。",
  ui_story_70001001_23_dialog_content = "とにかく、使ってみよう！",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>「意識モジュール修復装置を検知」</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>「接続中…完了」</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>「優先度判定実行中…完了」</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>「生命維持システムアップグレードデータを検知。\nアップグレードを実行します」</color>",
  ui_story_70001001_28_dialog_content = "修復装置が…変化してる！？",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>「アップグレードが完了しました。\n医療システムは正常に動作しています」</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>「現在の負荷：１、残りの空き容量：1」</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>「操作権限の再認証が必要です」</color>",
  ui_story_70001001_32_dialog_content = "え？でも、まず動作テストとか、しなくていいの？",
  ui_story_70001001_33_dialog_content = "うぐっ…",
  ui_story_70001001_34_dialog_content = "今は…悠長に構えてはいられん。",
  ui_story_70001001_35_dialog_content = "いいから…試せ。",
  ui_story_70001001_36_dialog_content = "…はい！",
  ui_story_70001001_37_dialog_content = "ちゃんと効けばいいけど…",
  ui_story_70001001_38_dialog_content = "きっと大丈夫だよ。",
  ui_story_70001001_39_dialog_content = "僕は大元帥さんを信じる。\nそれに、ソラヴァンなら絶対やってくれるって信じてる。",
  ui_story_70001001_40_dialog_content = "さっきのメッセージだって…もしかしたら、\nソラヴァンが僕たちが困ってることに気づいて、助けてくれたのかもしれない…",
  ui_story_70001001_41_dialog_content = "そうね…",
  ui_story_70001001_42_dialog_content = "効き目が出るまでには少し時間がかかるみたいだ。",
  ui_story_70001001_43_dialog_content = "今はとりあえず、意識モジュールの修復方法を見てみよう。",
  ui_story_70001001_44_dialog_content = "そうね、私も手伝うわ。",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>「意識モジュール修復プロセスを継続します」</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>「初めに、巨像意識体標準データベースプラグインを\nインストールしてください」</color>",
  ui_story_70001001_47_dialog_content = "えっ…？",
  ui_story_70001001_48_dialog_content = "何のこと…？",
  ui_story_70001001_49_dialog_content = "PlayerName、他にも何か持ってきた？",
  ui_story_70001001_50_dialog_content = "そんなものないよ…これ1つしかない！",
  ui_story_70001001_51_dialog_content = "ソラヴァン、その何とかデータベースプラグインって何のこと？",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>「巨像意識体標準データベースプラグインに関する情報を\n検索しています…検索が完了しました」</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>「検索結果：巨像意識体標準データベースプラグインは、\n巨像の意識のテンプレートとなるシステムです」</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>「現在、このモジュールの在庫は『0』です」</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>「なお、巨像意識体標準データベースプラグインは、\n最寄りの巨像整備基地で入手できます」</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>「最も近い巨像整備基地を検索しています…\n検索が完了しました」</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>「最も近い基地は――天空ノ谷です」</color>",
  ui_story_70001001_58_dialog_content = "天空ノ谷…！？",
  ui_story_70001001_59_dialog_content = "そんな基地がまだあるの！？",
  ui_story_70001001_60_dialog_content = "聞いたこともなかった…",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>「警告…プラグインをインストールしない場合、\n意識モジュール修復装置はスタンバイ状態に移行します」</color>",
  ui_story_70001001_62_dialog_content = "…うん、スタンバイ状態になってていいよ。",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>「意識モジュール修復装置、スタンバイ状態に移行しました」</color>",
  ui_story_70001001_64_dialog_content = "天空ノ谷に戻ったら、\nその<color=#FFB400>「巨像整備基地」</color>を調べに行こう。",
  ui_story_70001001_65_dialog_content = "谷を全部掘り起こしてでも、\n僕はソラヴァンを救う方法を見つける…",
  ui_story_70001001_66_dialog_content = "まぁ、今のところ最大の優先事項は、\n大元帥を警戒線まで送り届けることね。",
  ui_story_70001001_67_dialog_content = "確かに…",
  ui_story_70001001_68_dialog_content = "大元帥さんの様子は？",
  ui_story_70001001_69_dialog_content = "治療は進んでるみたいよ。",
  ui_story_70001001_70_dialog_content = "効果はあるかどうか、分からないけど…",
  ui_story_70001001_71_dialog_content = "助けられることを願ってるよ。",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>ピピピピ――</color>",
  ui_story_70001001_73_dialog_content = "これ…啓光からの通信要請ね。\nでも、発信者の名前がないわ？",
  ui_story_70001001_74_dialog_content = "援軍かもしれない。まずは通信してみよう！",
  ui_story_70001001_75_dialog_content = "バイス中尉、応答願います。空の末裔、PlayerNameさん、応答してください。\nソラヴァン号、応答してください。",
  ui_story_70001001_76_dialog_content = "聞こえますか？",
  ui_story_70001001_77_dialog_content = "ええと、どう答えるんだっけ…？",
  ui_story_70001001_78_dialog_content = "あ、そうだ。\nこちらソラヴァン、どうぞ。",
  ui_story_70001001_79_dialog_content = "こちらは啓光連邦の情報官――アイゼンです。",
  ui_story_70001001_80_dialog_content = "現在の位置を教えてください。",
  ui_story_70001001_81_dialog_content = "こちらは現在80号シェルターの東南、\n啓光の防衛線までおそらく10分程の位置…",
  ui_story_70001001_82_dialog_content = "それから、緊急事態発生の報告…",
  ui_story_70001001_83_dialog_content = "レインハト大元帥が戦闘中に重傷を負い、\n治療が必要な状態です。",
  ui_story_70001001_84_dialog_content = "やはりそうでしたか…",
  ui_story_70001001_85_dialog_content = "…いえ、何でもありません。",
  ui_story_70001001_86_dialog_content = "医療部隊を待機させます。\nあなた方は、直ちに大元帥を防衛線上までお連れしてください。",
  ui_story_70001001_87_dialog_content = "分かりました！",
  ui_story_70001001_88_dialog_content = "では、通信以上。",
  ui_story_70001001_89_dialog_content = "ずいぶん急いでいるようだな。",
  ui_story_70001001_90_dialog_content = "大元帥！",
  ui_story_70001001_91_dialog_content = "大元帥さん！",
  ui_story_70001001_92_dialog_content = "具合はどうですか？",
  ui_story_70001001_93_dialog_content = "もう大丈夫だ。痛みはひどいが、死にはしない。",
  ui_story_70001001_94_dialog_content = "数日静養すれば、回復するだろう。",
  ui_story_70001001_95_dialog_content = "まったく、空の末裔の技術とは不思議なものだ。",
  ui_story_70001001_96_dialog_content = "啓光のシェルターにもこのような治療装置があれば、\nより多くの者が生き延びられるだろう…",
  ui_story_70001001_97_dialog_content = "もしソラヴァンが教えてくれなかったら、\nこんな機能があるなんて、僕も知りませんでした。",
  ui_story_70001001_98_dialog_content = "ソラヴァンか。調子はどうだ？",
  ui_story_70001001_99_dialog_content = "修復モジュールは回収できましたが、\nまだ足りないものがあるみたいで…",
  ui_story_70001001_100_dialog_content = "そうか…",
  ui_story_70001001_101_dialog_content = "1日も早く修復できることを願っている。",
  ui_story_70001001_102_dialog_content = "…",
  ui_story_70001001_103_dialog_content = "大元帥さん、1つ気になることがあるんですが…",
  ui_story_70001001_104_dialog_content = "「最後の質問」はもう聞いたのではなかったか？",
  ui_story_70001001_105_dialog_content = "い、いや、質問ではなくて、\nただ、何となく違和感があるというか…",
  ui_story_70001001_106_dialog_content = "大元帥さんは戦友を見捨てるような人ではなさそうなのに…",
  ui_story_70001001_107_dialog_content = "どうしてその時はあきらめたんですか？",
  ui_story_70001001_108_dialog_content = "…それが最良の決断だったからだ。",
  ui_story_70001001_109_dialog_content = "啓光の兵士を犬死させるわけにはいかない。",
  ui_story_70001001_110_dialog_content = "でも、その時のあなたは「大元帥」じゃなくて、\n普通の兵士だったはずです。",
  ui_story_70001001_111_dialog_content = "断言してもいい。\nその決断は絶対、あなたの本当の考えじゃない。",
  ui_story_70001001_112_dialog_content = "言われてみると、確かに…",
  ui_story_70001001_113_dialog_content = "今日だって単独で私たちの救援に駆けつけてくださって、\nずっとかつての戦友を助けようとしてた…",
  ui_story_70001001_114_dialog_content = "なら、昔の大元帥だって、たとえ単独でも、\n戻って助けに行こうとしていてむしろ当然…",
  ui_story_70001001_115_dialog_content = "…",
  ui_story_70001001_116_dialog_content = "空の末裔とは、実に厄介な存在だな。",
  ui_story_70001001_117_option_content = "誉め言葉だと思っておきます",
  ui_story_70001001_118_option_content = "細かいことによく気が付くんです",
  ui_story_70001001_119_dialog_content = "…もう、話したくはなかったのだが。あの時…",
  ui_story_70001001_120_dialog_content = "私は包囲を破り、どうにか警戒線に戻った。",
  ui_story_70001001_121_dialog_content = "き、緊急事態が発生！",
  ui_story_70001001_122_dialog_content = "入手した情報に誤りがあったようです。\n80号シェルター内で大量の暗鬼に遭遇しました！",
  ui_story_70001001_123_dialog_content = "単独で包囲を突破してきましたが、まだ多くの兵士が\n暗力と重傷のため、身動きが取れず、中に閉じ込められています！",
  ui_story_70001001_124_dialog_content = "急ぎ援軍が必要です！",
  ui_story_70001001_125_dialog_content = "分かりました。これから検討します。\n衛生兵、彼女を治療へ。",
  ui_story_70001001_126_dialog_content = "こちらへ――",
  ui_story_70001001_127_dialog_content = "事の緊急度が分かっていない！",
  ui_story_70001001_128_dialog_content = "今すぐ救援部隊を出さなければ、間に合いません！",
  ui_story_70001001_129_dialog_content = "でなければ、彼らが…戦友たちが、全滅してしまいます！",
  ui_story_70001001_130_dialog_content = "救援作戦は厳格な協議のもと実施する必要があります。\nそして、それはあなたの管轄ではありません。直ちに治療を受けてください。",
  ui_story_70001001_131_dialog_content = "助けるつもりはまったくない、と！？",
  ui_story_70001001_132_dialog_content = "勝手な憶測は控えて頂きたい。",
  ui_story_70001001_133_dialog_content = "分かりました…\n援軍がなかろうと、私一人で戻ります！！",
  ui_story_70001001_134_dialog_content = "私は絶対に見捨てたりはしない！",
  ui_story_70001001_135_dialog_content = "あなたは啓光の軍人であり、軍人の職務は命令に従うことです。\nこれ以上軍紀を乱すなら、軍事法廷に送られることになりますよ。",
  ui_story_70001001_136_dialog_content = "戦友たちが私を待っているんだ！！",
  ui_story_70001001_137_dialog_content = "衛生兵！",
  ui_story_70001001_138_dialog_content = "一体…何を…",
  ui_story_70001001_139_dialog_content = "彼女を治療へ。\nしっかり見張っておきなさい。",
  ui_story_70001001_140_dialog_content = "承知しました！",
  ui_story_70001001_141_dialog_content = "鎮静剤が切れて、目を覚ました時には…\nもう数日が経っていた。",
  ui_story_70001001_142_dialog_content = "私はカナン城に移送され、治療を受けた。\n後になって、警戒線から撤退してきた者から聞いた――",
  ui_story_70001001_143_dialog_content = "結局、80号シェルターに増援は送られなかったと。",
  ui_story_70001001_144_dialog_content = "そして私は、唯一の生還者となったのだ。",
  ui_story_70001001_145_dialog_content = "…",
  ui_story_70001001_146_dialog_content = "冷静になってから、私は考えた。\nそして、少しずつ彼らの決定を理解できるようになった。",
  ui_story_70001001_147_dialog_content = "啓光のすべての者が大切な存在だ。",
  ui_story_70001001_148_dialog_content = "個人的な感情で、犠牲を払うことを強いてはならない。",
  ui_story_70001001_149_dialog_content = "大元帥になった私は、この事実を受け入れなければならない。\nそして、代償を払わなければならない。",
  ui_story_70001001_150_dialog_content = "重傷を負ったデニールが啓光に戻るまで、私はそう思っていた。",
  ui_story_70001001_151_dialog_content = "つまり、ノラが…？",
  ui_story_70001001_152_dialog_content = "私は戦友の帰還を喜んだ。\nしかし、あの日以来、私たちの間には溝ができてしまっていた。",
  ui_story_70001001_153_dialog_content = "そして結局、たもとを分かった。",
  ui_story_70001001_154_dialog_content = "それは彼女にウソをついているからでしょう？\n救援がなかったのは、大元帥さんの意志じゃない。",
  ui_story_70001001_155_dialog_content = "私はただ、彼女が啓光を恨んでしまうより、\n私個人を恨んでくれた方が、少しはましだと思っただけだ。",
  ui_story_70001001_156_dialog_content = "彼女は賢い。しかし、復讐心も強い。",
  ui_story_70001001_157_dialog_content = "彼女の怒りの矛先が私個人を狙っているなら、\n啓光の他の者は災難を逃れることができる。",
  ui_story_70001001_158_dialog_content = "何しろ、私のような「化け物」を倒すのは、\n相当に苦労するからな。",
  ui_story_70001001_159_dialog_content = "そういうことだったんですね。",
  ui_story_70001001_160_dialog_content = "誤解していたみたいです。",
  ui_story_70001001_161_dialog_content = "誤解？",
  ui_story_70001001_162_dialog_content = "大元帥さんは冷たい人だと思ってました。",
  ui_story_70001001_163_dialog_content = "PlayerName…そんなこと、軽々しく言うものじゃないわ…",
  ui_story_70001001_164_dialog_content = "ハハハ…ゲホ、ゴホッ！",
  ui_story_70001001_165_dialog_content = "ゲホ、ゲホッ…ああ、大丈夫だ、何ともない…",
  ui_story_70001001_166_dialog_content = "この世に私を誤解している者は多い。\n1人増えようと、1人減ろうと、変わりはない。",
  ui_story_70001001_167_dialog_content = "啓光連邦の民を守ることができるのなら、\nどんな誤解を受けようとも、私は構わない。",
  ui_story_70001001_168_dialog_content = "そうですか…",
  ui_story_70001001_169_dialog_content = "そろそろ啓光の防衛線が見えてきましたよ。",
  ui_story_70001001_170_dialog_content = "そうか、私も「あいつら」に応対しなくてはな。",
  ui_story_70001001_171_dialog_content = "大元帥、ようやくお戻りになりましたか！",
  ui_story_70001001_172_dialog_content = "大元帥が帰ってこにゃいから、\n危うく軍事法廷にかけられるところでしたにゃ～…",
  ui_story_70001001_173_dialog_content = "おケガをされたと聞きました。\n医療班がすでに待機しています。急ぎ治療を…",
  ui_story_70001001_174_dialog_content = "心配は無用だ、大した傷ではない。",
  ui_story_70001001_175_dialog_content = "空の末裔と巨像のおかげで、応急処置はすでに終わっている。\nひとまず命の危険はない。",
  ui_story_70001001_176_dialog_content = "ソラヴァンが教えてくれたおかげです。",
  ui_story_70001001_177_dialog_content = "そうであっても、一通り検査を受けて頂きませんと。\n何かあってはいけませんから！",
  ui_story_70001001_178_dialog_content = "啓光の大元帥を失うわけにはいきません。",
  ui_story_70001001_179_dialog_content = "「大元帥」を失う…",
  ui_story_70001001_180_dialog_content = "これだから制度や手続きというものは…\n間違ってはいない分、余計に厄介だな。",
  ui_story_70001001_181_dialog_content = "言う通りにしよう。検査を受ける。",
  ui_story_70001001_182_dialog_content = "承知しました。こちらへどうぞ。",
  ui_story_70001001_183_dialog_content = "いや、少し待て。\nPlayerNameに話しておくことがある。",
  ui_story_70001001_184_dialog_content = "え？な、なんですか…？",
  ui_story_70001001_185_dialog_content = "もし誰かに80号シェルターで起きたことを尋ねられたら、\nありのままを話して構わん。",
  ui_story_70001001_186_dialog_content = "委員会の連中は保守的で頑固ではあるが、\nむやみに誰かに罪をかぶせるようなこともしないだろう。",
  ui_story_70001001_187_dialog_content = "でも、そうすると大元帥さんが…",
  ui_story_70001001_188_dialog_content = "心配無用だ。なにせ、私は啓光の大元帥だからな。",
  ui_story_70001001_189_dialog_content = "分かりました。じゃあ、身体には十分気を付けてください。\n…また、会いましょう。",
  ui_story_70001001_190_dialog_content = "ああ、また会おう。",
  ui_story_70001001_191_dialog_content = "彼女の後ろ姿が徐々に遠ざかり、\nシェルターの中に消えていくのを僕はずっと眺めていた。",
  ui_story_70001001_192_dialog_content = "漠然とした不安が胸をよぎった…",
  ui_story_70001001_193_dialog_content = "とにかく、まずは戻ってソラヴァンの状態をチェックしよう。",
  ui_story_70001001_194_dialog_content = "それから天空ノ谷に戻って、\nソラヴァンを修復する方法を探すんだ…"
}
return config
